function scoreAttackTarget(state: GameState, attacker: UnitInstance, target: UnitInstance, damage: number): number {
  const targetDefinition = getUnitDefinition(target.type);
  const targetValue = getUnitInstanceValue(state, target);
  const supplyTruckPriority = getPlayerSupplyTruckTargetPriority(target);
  const lethal = damage >= target.health;
  const ownBaseDistance = hexDistance(target.coord, state.bases[attacker.owner]);
  const assessment = attacker.owner === "Enemy" ? getEnemyStrategicAssessment(state) : undefined;
  const targetCanReturnFire =
    canUnitTargetUnit(target.type, attacker.type) &&
    hexDistance(attacker.coord, target.coord) <= getEffectiveUnitStats(state, target.owner, target.type, target.level, target.coord, attacker.coord).attackRange;

  let score = damage * 8 + targetValue * 0.75 + (lethal ? 110 : 0) - Math.max(0, damage - target.health) * 0.35;

  if (targetDefinition.humanBased && sameHex(target.coord, state.bases[attacker.owner])) {
    score += 260;
  }

  if (targetDefinition.humanBased && ownBaseDistance <= ENEMY_BASE_RESPONSE_RADIUS) {
    score += Math.max(0, ENEMY_BASE_RESPONSE_RADIUS + 1 - ownBaseDistance) * 30;
  }

  if (targetCanReturnFire) {
    score += 36;
  }

  if (attacker.owner === "Enemy" && sameHex(target.coord, state.bases.Player)) {
    score += 34;
  }

  if (attacker.owner === "Enemy" && assessment) {
    score += damage * 7 + targetValue * 0.55 + supplyTruckPriority + (lethal ? 105 : 0);

    if (targetDefinition.humanBased && sameHex(target.coord, state.bases.Enemy)) {
      score += assessment.baseDefenseUrgency * 0.55;
    }

    if (isReconUnit(target.type)) {
      score += 48;
    }

    if (isSpecialUnit(target.type)) {
      score += target.type === "Reaper" ? 120 : 64;
    }

    if (canCounterAir(target.type) && (attacker.type === "Bomber" || attacker.type === "Reaper" || attacker.type === "Attack Heli")) {
      score += 76;
    }

    if (ownerControlsBothGates(state, "Enemy") && isEnemyBaseAttackCombatUnit(attacker) && isPlayerBaseAreaAssaultTarget(state, target)) {
      score += scoreEnemyPlayerBaseAreaTargetPriority(state, attacker, target, undefined) * 0.34;
    }

    for (const gate of state.gates ?? []) {
      if (sameHex(target.coord, gate.coord) || hexDistance(target.coord, gate.coord) <= 2) {
        score += gate.owner === "Player" ? assessment.gateUrgency * 0.42 : assessment.gateUrgency * 0.18;
      }
    }
  }

  return score;
}

export function getBestEnemyAttackTarget(state: GameState, attacker: UnitInstance, enemies: UnitInstance[]): UnitInstance | undefined {
  return enemies
    .filter((enemy) => canUnitTargetUnit(attacker.type, enemy.type))
    .sort((first, second) => {
      const firstDamage = estimateAttackDamage(state, attacker, first);
      const secondDamage = estimateAttackDamage(state, attacker, second);
      return (
        scoreAttackTarget(state, attacker, second, secondDamage) - scoreAttackTarget(state, attacker, first, firstDamage) ||
        secondDamage - firstDamage ||
        first.health - second.health
      );
    })[0];
}


function chooseGateObjective(
  state: GameState,
  owner: Owner,
  origin: UnitInstance["coord"],
  unit?: UnitInstance,
  plan?: EnemyTurnPlan
): GateState | undefined {
  const assignedGate = owner === "Enemy" && unit && plan ? getEnemyCampaignAssignedGateForUnit(state, unit, plan) : undefined;
  if (assignedGate) {
    return assignedGate;
  }

  return (state.gates ?? [])
    .filter((gate) => gate.owner !== owner)
    .sort((first, second) => scoreGateObjective(state, owner, origin, second) - scoreGateObjective(state, owner, origin, first))[0];
}

function scoreGateObjective(state: GameState, owner: Owner, origin: UnitInstance["coord"], gate: GateState): number {
  if (owner === "Enemy" && gate.owner !== owner) {
    return scoreEnemyGateCaptureObjective(state, origin, gate);
  }

  const assessment = owner === "Enemy" ? getEnemyStrategicAssessment(state) : undefined;
  const earlyCaptureBonus = getEarlyGatePositionBonus(state);
  const ownershipScore = gate.owner === null ? 145 : gate.owner !== owner ? 210 : 55;
  const holdProgressScore = gate.occupation[owner] * 45;
  const denialScore = gate.owner && gate.owner !== owner ? getGateIncomeBonusForEconomy(getEconomy(state, gate.owner)) * 18 : 0;
  const defenseScore = gate.owner === owner ? gate.occupation[owner] * 25 : 0;
  const strategicScore = assessment ? assessment.gateUrgency + Math.max(0, -assessment.gateIncomeSwing) * 12 : 0;
  const predictedPressure = assessment?.predictedGatePressure[gate.id] ?? 0;
  const sideSightScore = assessment && gate.owner !== owner ? getGateSideSightStrategicScore(state, gate) : 0;
  const knownPlayerPressure = owner === "Enemy"
    ? getKnownPlayerUnitsForEnemy(state).filter((unit) => hexDistance(unit.coord, gate.coord) <= 8).length * 36
    : 0;
  const distancePenalty = hexDistance(origin, gate.coord) * 5;
  return (
    ownershipScore +
    earlyCaptureBonus +
    holdProgressScore +
    denialScore +
    defenseScore +
    strategicScore +
    sideSightScore +
    predictedPressure * (gate.owner === owner ? 0.8 : 0.48) +
    knownPlayerPressure -
    distancePenalty
  );
}

function scoreEnemyGateRoleObjective(state: GameState, gate: GateState): number {
  const assessment = getEnemyStrategicAssessment(state);
  if (gate.owner === "Enemy") {
    const pressure = assessment.predictedGatePressure[gate.id] ?? 0;
    const knownPressure = getKnownPlayerUnitsForEnemy(state).filter((unit) => hexDistance(unit.coord, gate.coord) <= 7).length * 32;
    return pressure + knownPressure + getGateIncomeBonusForEconomy(state.enemyEconomy) * 12;
  }

  return scoreEnemyGateCaptureObjective(state, state.bases.Enemy, gate);
}

function scoreEnemyGateCaptureObjective(state: GameState, origin: UnitInstance["coord"], gate: GateState): number {
  const assessment = getEnemyStrategicAssessment(state);
  const config = getAiDifficultyConfig(state);
  const ownershipScore = gate.owner === null ? 170 : 210;
  const denialScore = gate.owner && gate.owner !== "Enemy" ? getGateIncomeBonusForEconomy(getEconomy(state, gate.owner)) * 18 : 0;
  const opportunity = assessment.gateCaptureOpportunity[gate.id] ?? 0;
  const playerPressure = assessment.predictedGatePressure[gate.id] ?? 0;
  const localKnownPressure = getKnownPlayerUnitsForEnemy(state).filter((unit) => hexDistance(unit.coord, gate.coord) <= 8).length * 42;
  const pressureMultiplier = state.difficulty === "Hard" ? 2.4 : 1;
  const earlyNeutralBonus = gate.owner === null && state.difficulty === "Hard" ? Math.max(0, 16 - state.day) * 5 : 0;
  const sideSightScore = getGateSideSightStrategicScore(state, gate);
  const holdProgressScore = gate.occupation.Enemy * 48 - gate.occupation.Player * 55;
  const wouldControlBothGates = state.difficulty === "Hard" && (state.gates ?? []).filter((candidate) => candidate.id !== gate.id).every((candidate) => candidate.owner === "Enemy");
  const gateLockout = getEnemyGateLockoutOpportunityScore(state, gate);
  const lockoutTempoScore = wouldControlBothGates ? 180 + gateLockout.total * 1.05 : assessment.gateLockoutLeverage * 0.18;
  const theatre = state.difficulty === "Hard" ? estimateGateTheatrePressure(state, gate) : undefined;
  const playerCombatAdvantage = theatre ? Math.max(0, theatre.player.combat - theatre.enemy.combat) : 0;
  const playerCombatRatio = theatre ? theatre.player.combat / Math.max(1, theatre.enemy.combat) : 1;
  const gateDeficit = Math.max(0, assessment.playerGateCount - assessment.enemyGateCount);
  const recoveryCounterattackUrgency =
    assessment.strategicPhase === "Recovery"
      ? Math.min(
          320,
          assessment.initiativePressure * 0.55 +
            Math.min(135, playerCombatAdvantage * 0.24) +
            Math.min(120, gateDeficit * 70)
        )
      : 0;
  const recoveryOutpoweredPenalty =
    assessment.strategicPhase === "Recovery" && playerCombatAdvantage > 0
      ? Math.min(210, playerCombatAdvantage * 0.52 + Math.max(0, playerCombatRatio - 1) * 78)
      : 0;
  const theatreScore = theatre
    ? assessment.strategicPhase === "GateLockoutCombat"
      ? Math.max(-140, Math.min(185, theatre.balance * 0.28 + theatre.player.combat * 0.18)) + (theatre.recaptureFeasible ? 55 : -35)
      : Math.max(-260, Math.min(220, theatre.balance * 0.72)) + (theatre.recaptureFeasible ? 105 : gate.owner === "Player" ? -155 : -45) - recoveryOutpoweredPenalty * 0.65
    : 0;
  const directCaptureMultiplier =
    assessment.strategicPhase === "GateLockoutCombat"
      ? theatre?.recaptureFeasible ? 0.62 : 0.36
      : assessment.strategicPhase === "Recovery" && playerCombatAdvantage > 0
        ? Math.max(0.38, 1 - Math.min(0.62, playerCombatAdvantage / 360))
        : 1;
  const gateLaneClearScore =
    assessment.strategicPhase === "GateLockoutCombat" && theatre
      ? Math.min(260, theatre.player.combat * 0.26 + theatre.player.artillery * 0.18 + theatre.player.armor * 0.12 + theatre.player.antiAir * 0.12 + localKnownPressure * 0.22)
      : assessment.strategicPhase === "Recovery" && theatre
        ? Math.min(220, theatre.player.combat * 0.16 + theatre.player.artillery * 0.16 + theatre.player.armor * 0.08 + localKnownPressure * 0.14 + recoveryCounterattackUrgency * 0.24)
      : 0;
  const phaseScore =
    assessment.strategicPhase === "OpeningGateRace"
      ? 150
      : assessment.strategicPhase === "OneGateOwned"
        ? wouldControlBothGates ? 230 : 100
        : assessment.strategicPhase === "GateLockoutCombat"
          ? 35 + gateLaneClearScore * 0.35
        : assessment.strategicPhase === "Recovery"
          ? Math.max(20, 220 - recoveryOutpoweredPenalty) + recoveryCounterattackUrgency * 0.46
          : isEnemyBaseOperationPhase(assessment.strategicPhase)
            ? -70
            : 0;
  const distancePenalty = hexDistance(origin, gate.coord) * 5;
  return (
    ownershipScore * directCaptureMultiplier +
    denialScore * directCaptureMultiplier +
    earlyNeutralBonus +
    phaseScore +
    theatreScore +
    sideSightScore +
    lockoutTempoScore * (assessment.strategicPhase === "GateLockoutCombat" ? 0.45 : 1) +
    gateLaneClearScore +
    opportunity * 0.9 * config.gateCaptureOpportunityMultiplier * directCaptureMultiplier +
    holdProgressScore * directCaptureMultiplier -
    playerPressure * (0.25 + 0.52 * config.gateCaptureOpportunityMultiplier) * pressureMultiplier -
    localKnownPressure * (0.32 + 0.68 * config.gateCaptureOpportunityMultiplier) * pressureMultiplier -
    distancePenalty
  );
}

function getGateSideSightStrategicScore(state: GameState, gate: GateState): number {
  const sideHexes = getGateSideHexes(state, gate);
  const enemySupportOnSide = getOwnerUnits(state, "Enemy").filter(
    (unit) => needsReconSupport(unit.type) && sideHexes.has(hexId(unit.coord))
  ).length;
  const playerIntelOnSide = getPlayerIntelForEnemy(state).filter((intel) => sideHexes.has(hexId(intel.predictedCoord))).length;
  return enemySupportOnSide * 24 - playerIntelOnSide * 18;
}

function getGateSideHexes(state: GameState, gate: GateState): Set<string> {
  const sideWidth = Math.max(1, Math.floor(state.map.width * 0.42));
  return new Set(
    state.map.hexes
      .filter((hex) => (gate.id === "West" ? hex.coord.q < sideWidth : hex.coord.q >= state.map.width - sideWidth))
      .map((hex) => hex.id)
  );
}

function getGatePositionScore(state: GameState, owner: Owner, coord: UnitInstance["coord"]): number {
  const gate = (state.gates ?? []).find((candidate) => sameHex(candidate.coord, coord));
  if (!gate) {
    return 0;
  }

  if (gate.owner === owner) {
    return 95 + gate.occupation[owner] * 20;
  }

  return 280 + getEarlyGatePositionBonus(state) + gate.occupation[owner] * 70;
}

function getEarlyGatePositionBonus(state: GameState): number {
  return state.difficulty === "Hard" ? Math.max(0, 16 - state.day) * 18 : Math.max(0, 12 - state.day) * 12;
}


export function runEnemyTurn(state: GameState, context: EngineDispatchContext): void {
  runEnemyPlannerTurn(state, context);
}

function runEnemyPlannerTurn(state: GameState, context: EngineDispatchContext): void {
  enforceEnemyDroneFactoryFirstReaperProduction(state);

  let plan: EnemyTurnPlan | undefined;
  try {
    plan = beginEnemyTurnPlan(state);
    const planningPlan = plan;
    withEnemyTurnPlan(planningPlan, () => {
      const placementPlanningState = planEnemyPlacement(state, planningPlan);
      planEnemyFieldUpgrades(placementPlanningState, planningPlan);
    });
  } catch (error) {
    debugEnemyPlanner("planning failed before live mutation; enemy turn skipped", error);
    appendLog(state, "Enemy command degraded - fallback orders issued.");
    tryRunEnemyEmergencyFallbackTurn(state, context);
    return;
  }

  const livePlan = plan;
  try {
    withEnemyTurnPlan(livePlan, () => {
      livePlan.executionStarted = true;
      executeEnemyPlacementPlan(state, livePlan);
      executeEnemyFieldUpgradePlan(state, livePlan);
      if (!shouldSkipEnemyTacticalBeamPlan(state)) {
        finalizeEnemyTacticalPlan(state, livePlan);
      }
      executeEnemyUnifiedActionEvaluator(state, livePlan, context);
      planEnemyEconomy(state, livePlan, { includeFieldUpgrades: false });
      executeEnemyEconomyCancellations(state, livePlan);
      executeEnemyGainFinishPlan(state);
      executeEnemyProductionPlan(state, livePlan);
      executeEnemyResearchPlan(state, livePlan);
      executeEnemyGainFinishPlan(state);
      persistEnemyCampaignPlan(state, livePlan);
      recordDebugUnitMissions(state, livePlan);
      endEnemyTurnPlan(livePlan);
    });
  } catch (error) {
    debugEnemyPlanner("execution error after live mutation; emergency fallback will handle remaining enemy units", error);
    appendLog(state, "Enemy command degraded during execution - fallback orders issued.");
    tryRunEnemyEmergencyFallbackTurn(state, context);
  }
}

function enforceEnemyDroneFactoryFirstReaperProduction(state: GameState): void {
  const economy = state.enemyEconomy;
  const eliteBuilding = getOwnerEliteBuilding(state, "Enemy");
  const eliteUnit = getOwnerEliteUnit(state, "Enemy");
  if (
    !ownerHasBuilding(state, "Enemy", eliteBuilding) ||
    !canOwnerProduceUnit(state, "Enemy", eliteUnit) ||
    hasEnemyCompletedOrFieldedReaper(state)
  ) {
    return;
  }

  const firstProduction = getEnemyFirstProductionQueueJob(economy.productionQueue);
  if (!firstProduction) {
    return;
  }

  if (firstProduction.unitType !== eliteUnit) {
    firstProduction.unitType = eliteUnit;
    firstProduction.unitLevel = Math.min(getMaxUnitLevel(eliteUnit), Math.max(1, economy.unitLevels[eliteUnit] ?? 1));
    appendOwnerLog(state, "Enemy", `Enemy redirected first ${eliteBuilding} production to ${eliteUnit}.`);
  }

  economy.productionQueue.sort(compareEnemyFirstProductionQueueJob);
}

function hasEnemyCompletedOrFieldedReaper(state: GameState): boolean {
  const eliteUnit = getOwnerEliteUnit(state, "Enemy");
  return (
    getOwnerUnits(state, "Enemy").some((unit) => unit.type === eliteUnit && unit.health > 0) ||
    getEnemyInventoryHardLimitCount(state, eliteUnit) > 0
  );
}

function getEnemyFirstProductionQueueJob(queue: ProductionJob[]): ProductionJob | undefined {
  return queue.filter((job) => job.owner === "Enemy").sort(compareEnemyFirstProductionQueueJob)[0];
}

function compareEnemyFirstProductionQueueJob(first: ProductionJob, second: ProductionJob): number {
  const firstReaperPriority = first.unitType === "Reaper" || first.unitType === "Spectral" ? 0 : 1;
  const secondReaperPriority = second.unitType === "Reaper" || second.unitType === "Spectral" ? 0 : 1;
  return (
    first.availableDay - second.availableDay ||
    firstReaperPriority - secondReaperPriority ||
    first.startedDay - second.startedDay ||
    first.id.localeCompare(second.id)
  );
}

function tryRunEnemyEmergencyFallbackTurn(state: GameState, context: EngineDispatchContext): void {
  try {
    runEnemyEmergencyFallbackTurn(state, context);
  } catch (error) {
    debugEnemyPlanner("emergency fallback failed", error);
    appendLog(state, "Enemy fallback failed - enemy units hold position.");
    clearEnemyEvaluationCache();
  }
}

function runEnemyEmergencyFallbackTurn(state: GameState, context: EngineDispatchContext): void {
  clearEnemyEvaluationCache();
  placeEnemyEmergencyFallbackUnits(state);
  const plan = createEnemyEmergencyFallbackPlan(state);
  const handledUnitIds = new Set<string>();
  const priorities: EnemyEmergencyFallbackPriority[] = [
    "ImmediateBaseLossDenial",
    "ImmediateGateLossDenial",
    "ActiveCapturerHold",
    "CaptureProgressMove",
    "AntiAirSafeAirMove",
    "GenericAttack"
  ];

  for (const priority of priorities) {
    for (const unit of getEnemyEmergencyFallbackUnitOrder(state, priority, handledUnitIds)) {
      try {
        const handled = executeEnemyEmergencyFallbackPriorityAction(state, unit, priority, context, plan);
        if (handled) {
          handledUnitIds.add(unit.id);
        }
      } catch (error) {
        debugEnemyPlanner(`emergency fallback unit ${unit.id} failed`, error);
      }
    }
  }
  clearEnemyEvaluationCache();
}

function placeEnemyEmergencyFallbackUnits(state: GameState): void {
  const placementLimit = getEnemyPlacementLimit(state);
  let placed = 0;
  for (const unitType of ENEMY_UNIT_TYPES) {
    while ((state.enemyEconomy.inventory[unitType] ?? 0) > 0 && placed < placementLimit) {
      const coord = findEnemyEmergencyFallbackPlacementCoord(state, unitType);
      if (!coord || !placeUnit(state, "Enemy", unitType, coord, "preserve")) {
        break;
      }
      placed += 1;
      invalidateEnemyEvaluationCache();
    }
    if (placed >= placementLimit) {
      return;
    }
  }
}

function findEnemyEmergencyFallbackPlacementCoord(state: GameState, unitType: UnitType): UnitInstance["coord"] | undefined {
  return getLegalPlacementCoords(state, "Enemy", unitType)
    .sort((first, second) => {
      const firstCenterDistance = Math.abs(first.q - state.bases.Enemy.q);
      const secondCenterDistance = Math.abs(second.q - state.bases.Enemy.q);
      const firstStack = state.units.filter((unit) => unit.owner === "Enemy" && sameHex(unit.coord, first)).length;
      const secondStack = state.units.filter((unit) => unit.owner === "Enemy" && sameHex(unit.coord, second)).length;
      return firstStack - secondStack || firstCenterDistance - secondCenterDistance || first.q - second.q;
    })[0];
}

type EnemyEmergencyFallbackPriority =
  | "ImmediateBaseLossDenial"
  | "ImmediateGateLossDenial"
  | "ActiveCapturerHold"
  | "CaptureProgressMove"
  | "AntiAirSafeAirMove"
  | "GenericAttack";

function createEnemyEmergencyFallbackPlan(state: GameState): EnemyTurnPlan | undefined {
  try {
    return beginEnemyTurnPlan(state);
  } catch (error) {
    debugEnemyPlanner("emergency fallback could not build objective context; using local priorities", error);
    return undefined;
  }
}

function getEnemyEmergencyFallbackUnitOrder(
  state: GameState,
  priority: EnemyEmergencyFallbackPriority,
  handledUnitIds: Set<string>
): UnitInstance[] {
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => !handledUnitIds.has(unit.id))
    .filter((unit) => unit.placedDay !== state.day)
    .filter((unit) => !unit.hasMovedThisDay || !unit.hasAttackedThisDay)
    .map((unit) => ({
      unit,
      score: scoreEnemyEmergencyFallbackUnitPriority(state, unit, priority)
    }))
    .filter((entry) => entry.score > Number.NEGATIVE_INFINITY)
    .sort((first, second) => second.score - first.score || first.unit.id.localeCompare(second.unit.id))
    .map((entry) => entry.unit);
}

function scoreEnemyEmergencyFallbackUnitPriority(
  state: GameState,
  unit: UnitInstance,
  priority: EnemyEmergencyFallbackPriority
): number {
  switch (priority) {
    case "ImmediateBaseLossDenial": {
      const target = chooseEnemyEmergencyFallbackImmediateBaseLossTarget(state, unit);
      return target ? 10_000 + scoreEnemyEmergencyFallbackDenialUnit(state, unit, target) : Number.NEGATIVE_INFINITY;
    }
    case "ImmediateGateLossDenial": {
      const target = chooseEnemyEmergencyFallbackImmediateGateLossTarget(state, unit);
      return target ? 8_000 + scoreEnemyEmergencyFallbackDenialUnit(state, unit, target) : Number.NEGATIVE_INFINITY;
    }
    case "ActiveCapturerHold":
      return isEnemyEmergencyFallbackActiveCapturer(state, unit) ? 6_000 + getUnitInstanceValue(state, unit) : Number.NEGATIVE_INFINITY;
    case "CaptureProgressMove":
      return getUnitDefinition(unit.type).humanBased && chooseEnemyEmergencyFallbackCaptureProgressTarget(state, unit)
        ? 4_000 + getUnitInstanceValue(state, unit)
        : Number.NEGATIVE_INFINITY;
    case "AntiAirSafeAirMove":
      return getUnitDefinition(unit.type).domain === "Air" && !unit.hasMovedThisDay ? 2_500 + getUnitInstanceValue(state, unit) : Number.NEGATIVE_INFINITY;
    case "GenericAttack":
      return getUnitInstanceValue(state, unit);
  }
}

function executeEnemyEmergencyFallbackPriorityAction(
  state: GameState,
  unit: UnitInstance,
  priority: EnemyEmergencyFallbackPriority,
  context: EngineDispatchContext,
  plan?: EnemyTurnPlan
): boolean {
  const liveUnit = state.units.find((candidate) => candidate.id === unit.id && candidate.owner === "Enemy");
  if (!liveUnit || liveUnit.placedDay === state.day) {
    return false;
  }

  const action = chooseEnemyEmergencyFallbackPriorityAction(state, liveUnit, priority, plan);
  if (!action) {
    return false;
  }
  if (action.kind === "Hold") {
    return true;
  }
  let executed = executeEnemyCompoundActionDirect(state, liveUnit, action, plan, context);
  if (!executed && plan) {
    const localAction = chooseEnemyEmergencyFallbackPriorityAction(state, liveUnit, priority, undefined);
    if (localAction && localAction.kind !== "Hold") {
      executed = executeEnemyCompoundActionDirect(state, liveUnit, localAction, undefined, context);
    }
  }
  if (executed) {
    invalidateEnemyEvaluationCache();
  }
  return executed;
}

function chooseEnemyEmergencyFallbackPriorityAction(
  state: GameState,
  unit: UnitInstance,
  priority: EnemyEmergencyFallbackPriority,
  plan?: EnemyTurnPlan
): EnemyCompoundAction | undefined {
  switch (priority) {
    case "ImmediateBaseLossDenial":
      return chooseEnemyEmergencyFallbackDenialAction(state, unit, chooseEnemyEmergencyFallbackImmediateBaseLossTarget(state, unit), plan);
    case "ImmediateGateLossDenial":
      return chooseEnemyEmergencyFallbackDenialAction(state, unit, chooseEnemyEmergencyFallbackImmediateGateLossTarget(state, unit), plan);
    case "ActiveCapturerHold":
      return isEnemyEmergencyFallbackActiveCapturer(state, unit)
        ? createEnemyEmergencyFallbackCompoundAction(state, unit, plan, "Hold", {})
        : undefined;
    case "CaptureProgressMove": {
      const target = chooseEnemyEmergencyFallbackCaptureProgressTarget(state, unit);
      const moveTo = target ? chooseEnemyEmergencyFallbackProgressMove(state, unit, target) : undefined;
      return moveTo ? createEnemyEmergencyFallbackCompoundAction(state, unit, plan, "Move", { moveTo }) : undefined;
    }
    case "AntiAirSafeAirMove": {
      if (getUnitDefinition(unit.type).domain !== "Air" || unit.hasMovedThisDay) {
        return undefined;
      }
      const moveTo = chooseEnemyEmergencyFallbackAirSafeMove(state, unit, plan);
      return moveTo ? createEnemyEmergencyFallbackCompoundAction(state, unit, plan, "Move", { moveTo }) : undefined;
    }
    case "GenericAttack":
      return chooseEnemyEmergencyFallbackGenericAction(state, unit, plan);
  }
}

function createEnemyEmergencyFallbackCompoundAction(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan | undefined,
  kind: EnemyCompoundActionKind,
  input: {
    moveTo?: UnitInstance["coord"];
    retreatTo?: UnitInstance["coord"];
    attackAt?: UnitInstance["coord"];
    targetId?: string;
    targetType?: UnitType;
    expectedOutcome?: ExpectedAttackOutcome;
  }
): EnemyCompoundAction {
  if (plan) {
    return createEnemyCompoundAction(state, unit, plan, kind, input, {}, {});
  }
  const action: EnemyCompoundAction = {
    id: `${unit.id}:emergency:${kind}:${input.moveTo ? hexId(input.moveTo) : "hold"}:${input.targetId ?? "none"}`,
    unitId: unit.id,
    unitType: unit.type,
    kind,
    moveTo: input.moveTo ? { ...input.moveTo } : undefined,
    retreatTo: input.retreatTo ? { ...input.retreatTo } : undefined,
    attackAt: input.attackAt ? { ...input.attackAt } : undefined,
    targetId: input.targetId,
    targetType: input.targetType,
    expectedOutcome: input.expectedOutcome,
    dependencies: [],
    breakdown: createEmptyEnemyPlannerScoreBreakdown()
  };
  return action;
}

function chooseEnemyEmergencyFallbackImmediateBaseLossTarget(state: GameState, unit: UnitInstance): UnitInstance | undefined {
  if (state.baseOccupation.Enemy < BASE_CAPTURE_DAYS - 1) {
    return undefined;
  }
  return getOwnerUnits(state, "Player")
    .filter((target) => getUnitDefinition(target.type).humanBased && sameHex(target.coord, state.bases.Enemy))
    .filter((target) => canUnitTargetUnit(unit.type, target.type))
    .sort((first, second) => scoreEnemyEmergencyFallbackAttackTarget(state, unit, second) - scoreEnemyEmergencyFallbackAttackTarget(state, unit, first) || first.id.localeCompare(second.id))[0];
}

function chooseEnemyEmergencyFallbackImmediateGateLossTarget(state: GameState, unit: UnitInstance): UnitInstance | undefined {
  const threatenedGates = (state.gates ?? [])
    .filter((gate) => gate.owner !== "Player" && gate.occupation.Player >= GATE_CAPTURE_DAYS - 1)
    .sort((first, second) => second.occupation.Player - first.occupation.Player || first.id.localeCompare(second.id));
  for (const gate of threatenedGates) {
    const target = getOwnerUnits(state, "Player")
      .filter((candidate) => getUnitDefinition(candidate.type).humanBased && sameHex(candidate.coord, gate.coord))
      .filter((candidate) => canUnitTargetUnit(unit.type, candidate.type))
      .sort((first, second) => scoreEnemyEmergencyFallbackAttackTarget(state, unit, second) - scoreEnemyEmergencyFallbackAttackTarget(state, unit, first) || first.id.localeCompare(second.id))[0];
    if (target) {
      return target;
    }
  }
  return undefined;
}

function scoreEnemyEmergencyFallbackDenialUnit(state: GameState, unit: UnitInstance, target: UnitInstance): number {
  const inRange =
    !unit.hasAttackedThisDay &&
    hexDistance(unit.coord, target.coord) <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord).attackRange;
  const mobileAttack = !isMoveAttackExclusiveUnit(unit.type) && !unit.hasMovedThisDay && !unit.hasAttackedThisDay ? 80 : 0;
  return scoreEnemyEmergencyFallbackAttackTarget(state, unit, target) + (inRange ? 260 : 0) + mobileAttack - hexDistance(unit.coord, target.coord) * 8;
}

function chooseEnemyEmergencyFallbackDenialAction(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance | undefined,
  plan?: EnemyTurnPlan
): EnemyCompoundAction | undefined {
  if (!target || unit.hasAttackedThisDay || !canUnitTargetUnit(unit.type, target.type)) {
    return undefined;
  }
  const range = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord).attackRange;
  if (hexDistance(unit.coord, target.coord) <= range && canUnitAttackHex(state, unit, target.coord)) {
    return createEnemyEmergencyFallbackCompoundAction(state, unit, plan, "Attack", {
      attackAt: target.coord,
      targetId: target.id,
      targetType: target.type,
      expectedOutcome: getExpectedAttackOutcome(state, unit, target)
    });
  }

  if (unit.hasMovedThisDay || isMoveAttackExclusiveUnit(unit.type)) {
    return undefined;
  }

  const moveTo = getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => isEnemyFallbackAirMoveAllowed(state, unit, coord, plan))
    .filter((coord) => hexDistance(coord, target.coord) <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, target.coord).attackRange)
    .sort((first, second) => {
      const firstDistance = hexDistance(first, target.coord);
      const secondDistance = hexDistance(second, target.coord);
      const firstDanger = plan ? estimatePlayerDangerAtPlanner(state, unit, first, plan) : 0;
      const secondDanger = plan ? estimatePlayerDangerAtPlanner(state, unit, second, plan) : 0;
      return firstDistance - secondDistance || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
  if (!moveTo) {
    return undefined;
  }

  const movedUnit: UnitInstance = {
    ...unit,
    coord: { ...moveTo },
    movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, moveTo)
  };
  return createEnemyEmergencyFallbackCompoundAction(state, unit, plan, "MoveThenAttack", {
    moveTo,
    attackAt: target.coord,
    targetId: target.id,
    targetType: target.type,
    expectedOutcome: getExpectedAttackOutcome(state, movedUnit, target)
  });
}

function isEnemyEmergencyFallbackActiveCapturer(state: GameState, unit: UnitInstance): boolean {
  if (!getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  if (sameHex(unit.coord, state.bases.Player) && state.baseOccupation.Player > 0) {
    return true;
  }
  return (state.gates ?? []).some(
    (gate) => sameHex(unit.coord, gate.coord) && gate.owner !== "Enemy" && gate.occupation.Enemy > 0
  );
}

function chooseEnemyEmergencyFallbackCaptureProgressTarget(state: GameState, unit: UnitInstance): UnitInstance["coord"] | undefined {
  if (!getUnitDefinition(unit.type).humanBased) {
    return undefined;
  }
  if (ownerControlsBothGates(state, "Enemy")) {
    return state.bases.Player;
  }
  return getEnemyEmergencyFallbackGateTarget(state, unit.coord);
}

function chooseEnemyEmergencyFallbackProgressMove(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance["coord"]
): UnitInstance["coord"] | undefined {
  const currentDistance = hexDistance(unit.coord, target);
  if (unit.hasMovedThisDay || currentDistance === 0) {
    return undefined;
  }
  const path = findMovementPath(state, unit, target);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (path?.length && remainingMovement > 0) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (canMoveUnitTo(state, unit, coord) && hexDistance(coord, target) < currentDistance) {
        return coord;
      }
    }
  }
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => hexDistance(coord, target) < currentDistance)
    .sort((first, second) => hexDistance(first, target) - hexDistance(second, target) || hexId(first).localeCompare(hexId(second)))[0];
}

function chooseEnemyEmergencyFallbackAirSafeMove(
  state: GameState,
  unit: UnitInstance,
  plan?: EnemyTurnPlan
): UnitInstance["coord"] | undefined {
  if (plan) {
    const localFallback = chooseEnemyAirAntiAirLocalFallbackAction(state, unit, plan);
    if (localFallback?.moveTo && canMoveUnitTo(state, unit, localFallback.moveTo)) {
      return localFallback.moveTo;
    }
  }
  const target = chooseEnemyEmergencyFallbackMoveTarget(state, unit);
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => isEnemyFallbackAirMoveAllowed(state, unit, coord, plan))
    .sort((first, second) => {
      const firstProgress = target ? hexDistance(first, target) : hexDistance(first, state.bases.Enemy);
      const secondProgress = target ? hexDistance(second, target) : hexDistance(second, state.bases.Enemy);
      return firstProgress - secondProgress || hexDistance(first, state.bases.Enemy) - hexDistance(second, state.bases.Enemy) || hexId(first).localeCompare(hexId(second));
    })[0];
}

function chooseEnemyEmergencyFallbackGenericAction(
  state: GameState,
  unit: UnitInstance,
  plan?: EnemyTurnPlan
): EnemyCompoundAction | undefined {
  const attackTarget = getEnemyEmergencyFallbackAttackTarget(state, unit);
  if (attackTarget) {
    return createEnemyEmergencyFallbackCompoundAction(state, unit, plan, "Attack", {
      attackAt: attackTarget.coord,
      targetId: attackTarget.id,
      targetType: attackTarget.type,
      expectedOutcome: getExpectedAttackOutcome(state, unit, attackTarget)
    });
  }

  const moveTo = chooseEnemyEmergencyFallbackMove(state, unit, plan);
  return moveTo ? createEnemyEmergencyFallbackCompoundAction(state, unit, plan, "Move", { moveTo }) : undefined;
}

function executeEnemyEmergencyFallbackUnitAction(
  state: GameState,
  unit: UnitInstance,
  context: EngineDispatchContext
): void {
  const attackTarget = getEnemyEmergencyFallbackAttackTarget(state, unit);
  if (attackTarget) {
    const action = createEnemyEmergencyFallbackCompoundAction(state, unit, undefined, "Attack", {
      attackAt: attackTarget.coord,
      targetId: attackTarget.id,
      targetType: attackTarget.type,
      expectedOutcome: getExpectedAttackOutcome(state, unit, attackTarget)
    });
    withEnemyActionLogDetail(state, unit, action, undefined, context, () => attackHexWithUnit(state, unit, attackTarget.coord, context));
    invalidateEnemyEvaluationCache();
    return;
  }

  const move = chooseEnemyEmergencyFallbackMove(state, unit);
  if (move && canMoveUnitTo(state, unit, move) && isEnemyFallbackAirMoveAllowed(state, unit, move)) {
    const action = createEnemyEmergencyFallbackCompoundAction(state, unit, undefined, "Move", { moveTo: move });
    withEnemyActionLogDetail(state, unit, action, undefined, context, () => moveUnitTo(state, unit, move, "preserve", context));
    invalidateEnemyEvaluationCache();
    const moved = state.units.find((candidate) => candidate.id === unit.id && candidate.owner === "Enemy");
    const movedAttackTarget = moved ? getEnemyEmergencyFallbackAttackTarget(state, moved) : undefined;
    if (moved && movedAttackTarget && !isMoveAttackExclusiveUnit(moved.type)) {
      const followupAction = createEnemyEmergencyFallbackCompoundAction(state, moved, undefined, "Attack", {
        attackAt: movedAttackTarget.coord,
        targetId: movedAttackTarget.id,
        targetType: movedAttackTarget.type,
        expectedOutcome: getExpectedAttackOutcome(state, moved, movedAttackTarget)
      });
      withEnemyActionLogDetail(state, moved, followupAction, undefined, context, () => attackHexWithUnit(state, moved, movedAttackTarget.coord, context));
      invalidateEnemyEvaluationCache();
    }
    return;
  }
}

function getEnemyEmergencyFallbackAttackTarget(state: GameState, unit: UnitInstance): UnitInstance | undefined {
  if (unit.hasAttackedThisDay || unit.placedDay === state.day) {
    return undefined;
  }
  const visiblePlayerIds = new Set(getVisiblePlayerUnitsForEnemy(state).map((target) => target.id));
  return getOwnerUnits(state, "Player")
    .filter((target) => visiblePlayerIds.has(target.id))
    .filter((target) => canUnitTargetUnit(unit.type, target.type) && hexDistance(unit.coord, target.coord) <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord).attackRange)
    .sort((first, second) => scoreEnemyEmergencyFallbackAttackTarget(state, unit, second) - scoreEnemyEmergencyFallbackAttackTarget(state, unit, first) || first.id.localeCompare(second.id))[0];
}

function chooseEnemyEmergencyFallbackMove(state: GameState, unit: UnitInstance, plan?: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const target = chooseEnemyEmergencyFallbackMoveTarget(state, unit);
  if (!target) {
    return undefined;
  }
  const path = findMovementPath(state, unit, target);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (path?.length && remainingMovement > 0) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (canMoveUnitTo(state, unit, coord) && isEnemyFallbackAirMoveAllowed(state, unit, coord, plan)) {
        return coord;
      }
    }
  }

  return getLegalMoveCoordsWithVisibility(state, unit, getEnemyVisibleHexIds(state))
    .filter((coord) => hexDistance(coord, target) < hexDistance(unit.coord, target))
    .filter((coord) => isEnemyFallbackAirMoveAllowed(state, unit, coord, plan))
    .sort((first, second) => hexDistance(first, target) - hexDistance(second, target) || hexId(first).localeCompare(hexId(second)))[0];
}

function chooseEnemyEmergencyFallbackMoveTarget(state: GameState, unit: UnitInstance): UnitInstance["coord"] | undefined {
  const intelTargets = getEnemyPlannerPlayerIntel(state)
    .filter((intel) => getUnitDefinition(intel.unit.type).humanBased || canUnitTargetUnit(unit.type, intel.unit.type))
    .sort((first, second) => second.confidence - first.confidence || hexDistance(unit.coord, first.predictedCoord) - hexDistance(unit.coord, second.predictedCoord))
    .map((intel) => intel.predictedCoord);
  const targets = [
    ...intelTargets,
    getEnemyEmergencyFallbackGateTarget(state, unit.coord),
    getEnemyEmergencyFallbackLaneTarget(state, unit),
    state.bases.Player
  ].filter((coord): coord is UnitInstance["coord"] => Boolean(coord));
  return targets.sort((first, second) => hexDistance(unit.coord, first) - hexDistance(unit.coord, second))[0] ?? state.bases.Player;
}

function isEnemyFallbackAirMoveAllowed(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan?: EnemyTurnPlan): boolean {
  return isEnemyAirMoveAllowedByThreatMap(state, unit, coord, {
    unitId: unit.id,
    unitType: unit.type
  }, plan);
}

function scoreEnemyEmergencyFallbackAttackTarget(state: GameState, attacker: UnitInstance, target: UnitInstance): number {
  const damage = estimateAttackDamage(state, attacker, target);
  const lethal = damage >= target.health ? 160 : 0;
  const objective = getUnitDefinition(target.type).humanBased && sameHex(target.coord, state.bases.Enemy) ? 220 : 0;
  return damage * 8 + getUnitInstanceValue(state, target) * 0.7 + lethal + objective + getPlayerSupplyTruckTargetPriority(target);
}

function getEnemyEmergencyFallbackGateTarget(state: GameState, origin: UnitInstance["coord"]): UnitInstance["coord"] | undefined {
  return [...(state.gates ?? [])]
    .filter((gate) => gate.owner !== "Enemy")
    .sort((first, second) => hexDistance(origin, first.coord) - hexDistance(origin, second.coord) || first.id.localeCompare(second.id))[0]?.coord;
}

function getEnemyEmergencyFallbackLaneTarget(state: GameState, unit: UnitInstance): UnitInstance["coord"] | undefined {
  if (isReconUnit(unit.type)) {
    return chooseEnemyScoutTarget(state, unit);
  }

  const gate = chooseGateObjective(state, "Enemy", unit.coord);
  if (gate) {
    return getEnemyPatrolCoord(state, gate.id, unit);
  }

  return getEnemyVanguard(state, unit.id)?.coord;
}

function withEnemyTurnPlan<T>(plan: EnemyTurnPlan, callback: () => T): T {
  const previousPlan = activeEnemyTurnPlan;
  activeEnemyTurnPlan = plan;
  try {
    return callback();
  } finally {
    activeEnemyTurnPlan = previousPlan;
  }
}

function beginEnemyTurnPlan(state: GameState): EnemyTurnPlan {
  invalidateEnemyEvaluationCache();
  const strategicSnapshot = getEnemyStrategicAssessment(state);
  const historicalProfile = updateEnemyHistoricalPlayerProfile(state);
  const playerIntel = getEnemyPlannerPlayerIntel(state);
  const rolesByUnitId = buildEnemyPlannerRoleAssignments(state, strategicSnapshot, historicalProfile);
  enforceEnemyBaseSentryGateRequirement(state, rolesByUnitId);
  const campaignPlan = resolveEnemyCampaignPlan(state, rolesByUnitId, strategicSnapshot, playerIntel);
  reconcileEnemyRolesWithCampaign(state, rolesByUnitId, campaignPlan);
  scaleEnemyStrategicRolesInPlaceForDifficulty(state, rolesByUnitId);
  enforceEnemyBaseSentryGateRequirement(state, rolesByUnitId);
  const taskForces = buildEnemyPlannerTaskForces(state, rolesByUnitId, campaignPlan);
  const plan: EnemyTurnPlan = {
    day: state.day,
    strategicSnapshot,
    doctrine: {
      strategyPlan: strategicSnapshot.strategyPlan,
      strategyPlaybook: getEnemyStrategyPlaybook(strategicSnapshot),
      opponentProfile: blendOpponentProfileWithHistoricalPrior(strategicSnapshot.opponentProfile, historicalProfile),
      historicalProfile
    },
    objectiveImperatives: [],
    primaryObjective: chooseEnemyPlannerPrimaryObjective(state, strategicSnapshot),
    secondaryObjective: chooseEnemyPlannerSecondaryObjective(state, strategicSnapshot),
    economyPlan: {
      cancellations: [],
      purchases: [],
      reservedFunds: 0,
      liquidityAfterPlan: state.enemyEconomy.moneyPoundsBn
    },
    placementPlan: [],
    rolesByUnitId,
    campaignPlan,
    taskForces,
    activationDependencies: {},
    reservedDestinations: {},
    reservedExpectedDamage: {},
    plannedActions: [],
    debugBreakdowns: [],
    playerIntel,
    searchStats: {
      nodes: 0,
      capped: false
    },
    executionStarted: false,
    cache: {}
  };
  plan.objectiveImperatives = solveEnemyObjectiveImperatives(state, plan);
  reconcileEnemyRolesAfterImperatives(state, plan);
  enforceEnemyBaseSentryGateRequirement(state, plan.rolesByUnitId);
  plan.campaignPlan = resolveEnemyCampaignPlan(state, plan.rolesByUnitId, strategicSnapshot, playerIntel);
  reconcileEnemyRolesWithCampaign(state, plan.rolesByUnitId, plan.campaignPlan);
  scaleEnemyStrategicRolesInPlaceForDifficulty(state, plan.rolesByUnitId);
  enforceEnemyBaseSentryGateRequirement(state, plan.rolesByUnitId);
  reconcileEnemyRolesAfterImperatives(state, plan);
  scaleEnemyStrategicRolesInPlaceForDifficulty(state, plan.rolesByUnitId);
  enforceEnemyBaseSentryGateRequirement(state, plan.rolesByUnitId);
  plan.taskForces = buildEnemyPlannerTaskForces(state, plan.rolesByUnitId, plan.campaignPlan);
  plan.activationDependencies = buildEnemyActivationDependencies(state, plan);
  return plan;
}

function endEnemyTurnPlan(plan: EnemyTurnPlan): void {
  debugEnemyPlanner(
    `turn ${plan.day} complete: ${plan.plannedActions.length} actions, ${plan.searchStats.nodes} search nodes${plan.searchStats.capped ? " (capped)" : ""}`
  );
}

function persistEnemyCampaignPlan(state: GameState, plan: EnemyTurnPlan): void {
  (state as GameStateWithEnemyCampaign).enemyCampaignPlan = JSON.parse(JSON.stringify(plan.campaignPlan)) as EnemyCampaignPlan;
}

function recordDebugUnitMissions(state: GameState, plan: EnemyTurnPlan): void {
  state.debugUnitMissions = Object.fromEntries(
    state.units.map((unit) => [
      unit.id,
      unit.owner === "Enemy" ? (plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit)) : "Player command"
    ])
  );
}

function planEnemyEconomy(
  state: GameState,
  plan: EnemyTurnPlan,
  options: { includeFieldUpgrades?: boolean } = {}
): GameState {
  const simulated = cloneState(state);
  const includeFieldUpgrades = options.includeFieldUpgrades ?? true;
  plan.economyPlan.cancellations = chooseEnemyEconomyCancellations();

  const purchases: EnemyEconomyPlanItem[] = [...plan.economyPlan.purchases];
  const difficultyMaxPurchases = getAiDifficultyConfig(simulated).maxEconomyPurchasesPerTurn;
  const economyMaxPurchases = simulated.enemyEconomy.moneyPoundsBn >= 250 ? 7 : simulated.enemyEconomy.moneyPoundsBn >= 180 ? 5 : 4;
  const maxPurchases = Math.min(
    isEnemyGateLockoutEconomyOverride(simulated, plan) ? Math.max(difficultyMaxPurchases, 2) : difficultyMaxPurchases,
    economyMaxPurchases
  );

  plan.economyPlan.reservedFunds = 0;

  runEnemyEmergencyProductionGatePass(simulated, plan, purchases, maxPurchases);
  runEnemyStrategicDeadlineResearchGatePass(simulated, plan, purchases, maxPurchases);
  const strategicDeadlineBlocking = isEnemyStrategicDeadlineResearchGateBlocking(simulated);
  if (!strategicDeadlineBlocking) {
    runEnemyFirstReaperProductionGatePass(simulated, plan, purchases, maxPurchases);
  }
  const firstReaperBlocking = !strategicDeadlineBlocking && isEnemyFirstReaperSpendBlocking(simulated);

  if (!strategicDeadlineBlocking && !firstReaperBlocking) {
    runEnemyEfficiencyResearchGatePass(simulated, plan, purchases, maxPurchases);
  }
  const efficiencyGateBlocking = !strategicDeadlineBlocking && !firstReaperBlocking && isEnemyEfficiencyResearchGateBlocking(simulated);

  if (includeFieldUpgrades && !strategicDeadlineBlocking && !firstReaperBlocking && !efficiencyGateBlocking) {
    for (let index = purchases.filter((item) => item.kind === "fieldUpgrade").length; purchases.length < maxPurchases && index < 3; index += 1) {
      const item = chooseNextEnemyFieldUpgradePlanItem(simulated, plan, purchases);
      if (!item) {
        break;
      }

      purchases.push(item);
      if (!executeEnemyEconomyPurchase(simulated, item)) {
        break;
      }
    }
  }

  const immediateUnlock =
    strategicDeadlineBlocking || firstReaperBlocking || efficiencyGateBlocking
      ? undefined
      : chooseEnemyImmediateStrategicUnlockResearchPlanItem(simulated, plan, purchases);
  if (immediateUnlock && purchases.length < maxPurchases) {
    purchases.push(immediateUnlock);
    executeEnemyEconomyPurchase(simulated, immediateUnlock);
  }

  if (
    !isEnemyStrategicDeadlineResearchGateBlocking(simulated) &&
    !isEnemyFirstReaperSpendBlocking(simulated) &&
    !isEnemyEfficiencyResearchGateBlocking(simulated) &&
    purchases.length < maxPurchases &&
    hasEnemyEconomyPlannerSpendResource(simulated)
  ) {
    runEnemyProductionEvaluatorPass(simulated, plan, purchases, maxPurchases);
    runEnemyFieldSupportProductionGatePass(simulated, plan, purchases, maxPurchases);
    runEnemyResearchEvaluatorPass(simulated, plan, purchases, maxPurchases);
  }

  if (
    !isEnemyStrategicDeadlineResearchGateBlocking(simulated) &&
    !isEnemyFirstReaperSpendBlocking(simulated) &&
    !purchases.some((item) => item.kind === "production") &&
    purchases.length < maxPurchases &&
    shouldEnemyForceEmptyPipelineProduction(simulated)
  ) {
    const item = chooseEnemyEmptyPipelineProductionFloorItem(simulated, plan, purchases);
    if (item) {
      purchases.push(item);
      executeEnemyEconomyPurchase(simulated, item);
    }
  }

  plan.economyPlan.purchases = purchases;
  plan.economyPlan.liquidityAfterPlan = simulated.enemyEconomy.moneyPoundsBn;
  return simulated;
}

function runEnemyEmergencyProductionGatePass(
  state: GameState,
  plan: EnemyTurnPlan,
  purchases: EnemyEconomyPlanItem[],
  maxPurchases: number
): void {
  if (purchases.length >= maxPurchases) {
    return;
  }

  const candidates = getEnemyPlannerProductionCandidates(state, plan)
    .filter((item) => !purchases.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .map((item) => applyEnemyRepeatProductionPurchasePenalty(state, plan, purchases, item));
  const emergency =
    chooseEnemyBaseDefenseEmergencyProductionCandidate(state, plan, candidates) ??
    chooseEnemyGateLockoutRequiredProductionCandidate(state, plan, purchases, candidates);
  if (!emergency) {
    return;
  }

  purchases.push(emergency);
  executeEnemyEconomyPurchase(state, emergency);
}

function runEnemyStrategicDeadlineResearchGatePass(
  state: GameState,
  plan: EnemyTurnPlan,
  purchases: EnemyEconomyPlanItem[],
  maxPurchases: number
): void {
  while (purchases.length < maxPurchases && isEnemyStrategicDeadlineResearchGateBlocking(state)) {
    const item = chooseEnemyRequiredStrategicDeadlineResearchCandidate(state, plan);
    if (!item) {
      break;
    }

    purchases.push(item);
    if (!executeEnemyEconomyPurchase(state, item)) {
      break;
    }
  }
}

function runEnemyFirstReaperProductionGatePass(
  state: GameState,
  plan: EnemyTurnPlan,
  purchases: EnemyEconomyPlanItem[],
  maxPurchases: number
): void {
  while (purchases.length < maxPurchases && isEnemyFirstReaperSpendBlocking(state)) {
    const item = chooseEnemyRequiredFirstReaperProductionCandidate(state, plan, []);
    if (!item) {
      break;
    }

    purchases.push(item);
    if (!executeEnemyEconomyPurchase(state, item)) {
      break;
    }
  }
}

function runEnemyEfficiencyResearchGatePass(
  state: GameState,
  plan: EnemyTurnPlan,
  purchases: EnemyEconomyPlanItem[],
  maxPurchases: number
): void {
  while (purchases.length < maxPurchases && isEnemyEfficiencyResearchGateBlocking(state)) {
    const item = chooseNextEnemyResearchPlanItem(state, plan, purchases);
    if (!item || item.kind !== "research" || item.researchType !== "Efficiency") {
      break;
    }

    purchases.push(item);
    if (!executeEnemyEconomyPurchase(state, item)) {
      break;
    }
  }
}

function runEnemyFieldSupportProductionGatePass(
  state: GameState,
  plan: EnemyTurnPlan,
  purchases: EnemyEconomyPlanItem[],
  maxPurchases: number
): void {
  if (purchases.length >= maxPurchases) {
    return;
  }

  const candidates = getEnemyPlannerProductionCandidates(state, plan)
    .filter((item) => !purchases.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .map((item) => applyEnemyRepeatProductionPurchasePenalty(state, plan, purchases, item));
  const support = chooseEnemyRequiredFieldSupportProductionCandidate(state, plan, purchases, candidates);
  if (!support) {
    return;
  }

  purchases.push(support);
  executeEnemyEconomyPurchase(state, support);
}

function runEnemyProductionEvaluatorPass(
  state: GameState,
  plan: EnemyTurnPlan,
  purchases: EnemyEconomyPlanItem[],
  maxPurchases: number
): void {
  while (purchases.length < maxPurchases - (hasAffordableEnemyResearchCandidate(state, plan) ? 1 : 0)) {
    const item = chooseNextEnemyProductionPlanItem(state, plan, purchases);
    if (!item) {
      break;
    }

    purchases.push(item);
    if (!executeEnemyEconomyPurchase(state, item)) {
      break;
    }
  }
}

function runEnemyResearchEvaluatorPass(
  state: GameState,
  plan: EnemyTurnPlan,
  purchases: EnemyEconomyPlanItem[],
  maxPurchases: number
): void {
  while (purchases.length < maxPurchases) {
    const item = chooseNextEnemyResearchPlanItem(state, plan, purchases);
    if (!item) {
      break;
    }

    purchases.push(item);
    if (!executeEnemyEconomyPurchase(state, item)) {
      break;
    }
  }
}

function hasAffordableEnemyResearchCandidate(state: GameState, plan: EnemyTurnPlan): boolean {
  const baseContext = createEnemyResearchFeasibilityContext(state);
  const context = {
    ...baseContext,
    queueLimit: shouldEnemyBypassEfficiencyGateForCommittedUpgrade(state)
      ? Math.max(baseContext.queueLimit, state.enemyEconomy.researchQueue.length + 1)
      : baseContext.queueLimit,
    criticalTechReserve: 0,
    productionReserve: 0
  };
  const candidates = getEnemyPlannerResearchCandidates(state, plan, context)
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .map((item) => applyEnemyEconomyResearchLevelSpreadPenalty(state, item))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost);
  const best = candidates[0];
  return Boolean(best && best.priority > scoreEnemyNoResearchPriority(state, candidates));
}

function planEnemyFieldUpgrades(state: GameState, plan: EnemyTurnPlan): GameState {
  const simulated = cloneState(state);
  if (isEnemyStrategicDeadlineResearchGateBlocking(simulated) || isEnemyFirstReaperSpendBlocking(simulated)) {
    plan.economyPlan.purchases = plan.economyPlan.purchases.filter((item) => item.kind !== "fieldUpgrade");
    plan.economyPlan.liquidityAfterPlan = simulated.enemyEconomy.moneyPoundsBn;
    return simulated;
  }

  const upgrades: EnemyEconomyPlanItem[] = [];
  const maxUpgrades = Math.min(3, getAiDifficultyConfig(simulated).maxEconomyPurchasesPerTurn);
  for (let index = 0; index < maxUpgrades; index += 1) {
    const candidate = getEnemyPlannerFieldUpgradeCandidates(simulated, plan)
      .filter((item) => !upgrades.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
      .filter((item) => canEnemyAffordEconomyPlanItem(simulated, item))
      .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
    if (!candidate || candidate.priority < 40) {
      break;
    }
    upgrades.push(candidate);
    if (!executeEnemyEconomyPurchase(simulated, candidate)) {
      break;
    }
  }
  plan.economyPlan.purchases = [
    ...plan.economyPlan.purchases.filter((item) => item.kind !== "fieldUpgrade"),
    ...upgrades
  ];
  plan.economyPlan.liquidityAfterPlan = simulated.enemyEconomy.moneyPoundsBn;
  return simulated;
}

function chooseEnemyEconomyCancellations(): EnemyEconomyPlanCancellation[] {
  return [];
}

function getEnemyPlannerReservedFunds(state: GameState, plan: EnemyTurnPlan): number {
  return 0;
}

function hasEnemyEconomyPlannerSpendResource(state: GameState): boolean {
  return state.enemyEconomy.moneyPoundsBn > 0 || state.enemyEconomy.gainPoints > 0;
}

function getEnemyProductionGainCost(state: GameState, unitType: UnitType): number {
  return getProductionGainCost(unitType, state.enemyEconomy.unitLevels[unitType]);
}

function canEnemyAffordProductionUnit(state: GameState, unitType: UnitType): boolean {
  return state.enemyEconomy.moneyPoundsBn >= getProductionCost(unitType) || (canUseGainForProduction(unitType) && state.enemyEconomy.gainPoints >= getEnemyProductionGainCost(state, unitType));
}

function canEnemyAffordProductionPlanItem(state: GameState, item: EnemyEconomyPlanItem): boolean {
  return Boolean(
    item.kind === "production" &&
      item.unitType &&
      (state.enemyEconomy.moneyPoundsBn >= item.cost || (canUseGainForProduction(item.unitType) && state.enemyEconomy.gainPoints >= getEnemyProductionGainCost(state, item.unitType)))
  );
}

function canEnemySpendGainOnResearchLine(state: GameState, researchType: ResearchType, unitType: UnitType | undefined, startLevel: number): boolean {
  if (!canUseGainForResearch(researchType)) {
    return false;
  }

  if (state.enemyEconomy.researchQueue.some((job) => isSameResearchLine(job, researchType, unitType))) {
    return false;
  }

  return state.enemyEconomy.gainPoints >= getResearchGainCost(researchType, unitType, state.enemyEconomy, startLevel);
}

function canEnemyAffordResearchType(state: GameState, researchType: ResearchType, unitType: UnitType | undefined = undefined): boolean {
  const startLevel = getNextResearchStartLevel(state.enemyEconomy, researchType, unitType);
  return state.enemyEconomy.moneyPoundsBn >= getResearchCost(researchType, unitType, state.enemyEconomy, startLevel) || canEnemySpendGainOnResearchLine(state, researchType, unitType, startLevel);
}

function canEnemyAffordResearchOption(state: GameState, option: EnemyResearchOption): boolean {
  const startLevel = getNextResearchStartLevel(state.enemyEconomy, option.type, option.unitType);
  return state.enemyEconomy.moneyPoundsBn >= option.cost || canEnemySpendGainOnResearchLine(state, option.type, option.unitType, startLevel);
}

function canEnemyAffordResearchPlanItem(state: GameState, item: EnemyEconomyPlanItem): boolean {
  if (item.kind !== "research" || !item.researchType) {
    return false;
  }

  const startLevel = getNextResearchStartLevel(state.enemyEconomy, item.researchType, item.researchUnitType);
  return state.enemyEconomy.moneyPoundsBn >= item.cost || canEnemySpendGainOnResearchLine(state, item.researchType, item.researchUnitType, startLevel);
}

function canEnemyAffordEconomyPlanItem(state: GameState, item: EnemyEconomyPlanItem): boolean {
  if (item.kind === "production") {
    return canEnemyAffordProductionPlanItem(state, item);
  }

  if (item.kind === "research") {
    return canEnemyAffordResearchPlanItem(state, item);
  }

  if (item.kind !== "fieldUpgrade") {
    return false;
  }

  return (item.currency ?? "funds") === "gain"
    ? state.enemyEconomy.gainPoints >= item.cost
    : state.enemyEconomy.moneyPoundsBn >= item.cost;
}

function chooseNextEnemyFieldUpgradePlanItem(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (isEnemyStrategicDeadlineResearchGateBlocking(state) || isEnemyFirstReaperSpendBlocking(state)) {
    return undefined;
  }

  return getEnemyPlannerFieldUpgradeCandidates(state, plan)
    .filter((item) => !chosen.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function chooseNextEnemyProductionPlanItem(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (isEnemyStrategicDeadlineResearchGateBlocking(state) || isEnemyFirstReaperSpendBlocking(state) || isEnemyEfficiencyResearchGateBlocking(state)) {
    return undefined;
  }

  const candidates = getEnemyPlannerProductionCandidates(state, plan)
    .filter((item) => !chosen.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .map((item) => applyEnemyRepeatProductionPurchasePenalty(state, plan, chosen, item));

  const requiredLockoutCombatProduction = chooseEnemyGateLockoutRequiredProductionCandidate(state, plan, chosen, candidates);
  if (requiredLockoutCombatProduction) {
    return requiredLockoutCombatProduction;
  }

  const requiredOpeningCapturer = chooseEnemyOpeningRequiredCapturerProductionCandidate(state, plan, candidates);
  if (requiredOpeningCapturer) {
    return requiredOpeningCapturer;
  }

  const requiredBaseClearer = chooseEnemyBaseAssaultRequiredClearerProductionCandidate(state, plan, chosen, candidates);
  if (requiredBaseClearer) {
    return requiredBaseClearer;
  }

  const requiredFirstReaper = chooseEnemyRequiredFirstReaperProductionCandidate(state, plan, candidates);
  if (requiredFirstReaper) {
    return requiredFirstReaper;
  }

  const requiredCombatBacklog = chooseEnemyHardCombatBacklogProductionCandidate(state, candidates);
  if (requiredCombatBacklog) {
    return requiredCombatBacklog;
  }

  const best = candidates
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
  const noProductionPriority = scoreEnemyNoProductionChoice(state, plan);
  if (best && shouldEnemyForceEmptyPipelineProduction(state)) {
    return best;
  }
  if (!best || best.priority < 42 || noProductionPriority >= best.priority) {
    return chooseEnemyRequiredFieldSupportProductionCandidate(state, plan, chosen, candidates);
  }
  return best;
}

function chooseEnemyHardCombatBacklogProductionCandidate(
  state: GameState,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    state.difficulty !== "Hard" ||
    state.day < 12 ||
    state.enemyEconomy.moneyPoundsBn < 120 ||
    state.enemyEconomy.productionQueue.length >= getEnemyRoutineProductionQueueLimit(state)
  ) {
    return undefined;
  }

  return candidates
    .filter((item) => item.kind === "production" && item.unitType && item.unitType !== "Infantry" && isHardCombatProductionUnit(item.unitType))
    .filter((item) => item.priority >= 38 || item.score >= ENEMY_ARMY_SPEND_DOWN_SCORE_THRESHOLD)
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function shouldEnemyForceEmptyPipelineProduction(state: GameState): boolean {
  if (state.difficulty !== "Hard" || state.enemyEconomy.moneyPoundsBn < 45 || state.enemyEconomy.productionQueue.length > 0) {
    return false;
  }

  const inventoryCount = ENEMY_UNIT_TYPES.reduce((total, unitType) => total + Math.max(0, Math.floor(state.enemyEconomy.inventory[unitType] ?? 0)), 0);
  return inventoryCount <= 0;
}

function chooseEnemyRequiredFirstReaperProductionCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  const eliteUnit = getOwnerEliteUnit(state, "Enemy");
  if (
    !isEnemyFirstReaperSpendBlocking(state) ||
    isEnemyProductionHardCapped(state, eliteUnit) ||
    state.enemyEconomy.productionQueue.length >= getEnemyRoutineProductionQueueLimit(state)
  ) {
    return undefined;
  }

  const candidate = candidates.find((item) => item.kind === "production" && item.unitType === eliteUnit);
  if (candidate) {
    return {
      ...candidate,
      priority: Math.max(candidate.priority, 4_000),
      reason: `${candidate.reason}; required first ${eliteUnit}`
    };
  }

  const cost = getProductionCost(eliteUnit);
  if (!canEnemyAffordProductionUnit(state, eliteUnit) || !canOwnerProduceUnit(state, "Enemy", eliteUnit)) {
    return undefined;
  }

  const score = scoreEnemyProductionChoice(state, eliteUnit);
  const phasePriority = getEnemyPhaseEconomyProductionPriority(state, plan, eliteUnit);
  return {
    kind: "production",
    unitType: eliteUnit,
    cost,
    score,
    priority: Math.max(4_000, score + phasePriority),
    reason: `required first ${eliteUnit}`
  };
}

function chooseEnemyRequiredFieldSupportProductionCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    !isEnemyMissingFieldSupportProduction(state) ||
    state.enemyEconomy.productionQueue.length >= getEnemyRoutineProductionQueueLimit(state)
  ) {
    return undefined;
  }

  const candidate = candidates
    .filter((item) => item.kind === "production" && item.unitType && isEnemyRequiredFieldSupportProductionUnit(state, item.unitType))
    .sort(compareEnemyRequiredFieldSupportProductionCandidate)[0];
  if (candidate) {
    return {
      ...candidate,
      priority: Math.max(candidate.priority, 3_200),
      reason: `${candidate.reason}; required field support`
    };
  }

  return ENEMY_FIELD_SUPPORT_UNIT_TYPES
    .filter((unitType) => isEnemyRequiredFieldSupportProductionUnit(state, unitType))
    .filter((unitType) => canOwnerProduceUnit(state, "Enemy", unitType))
    .filter((unitType) => !isEnemyProductionHardCapped(state, unitType))
    .map((unitType) => {
      const cost = getProductionCost(unitType);
      const score = scoreEnemyProductionChoice(state, unitType);
      const phasePriority = getEnemyPhaseEconomyProductionPriority(state, plan, unitType);
      return {
        kind: "production" as const,
        unitType,
        cost,
        score,
        priority: Math.max(3_200, score + phasePriority),
        reason: "required field support"
      };
    })
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .filter((item) => !chosen.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .sort(compareEnemyRequiredFieldSupportProductionCandidate)[0];
}

function compareEnemyRequiredFieldSupportProductionCandidate(first: EnemyEconomyPlanItem, second: EnemyEconomyPlanItem): number {
  return (
    second.priority - first.priority ||
    second.score - first.score ||
    first.cost - second.cost ||
    getEnemyFieldSupportUnitOrder(first.unitType) - getEnemyFieldSupportUnitOrder(second.unitType)
  );
}

function getEnemyFieldSupportUnitOrder(unitType: UnitType | undefined): number {
  const index = unitType ? ENEMY_FIELD_SUPPORT_UNIT_TYPES.indexOf(unitType) : -1;
  return index >= 0 ? index : ENEMY_FIELD_SUPPORT_UNIT_TYPES.length;
}

function chooseEnemyEmptyPipelineProductionFloorItem(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  const candidate = getEnemyPlannerProductionCandidates(state, plan)
    .filter((item) => !chosen.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
  if (candidate) {
    return {
      ...candidate,
      reason: `${candidate.reason}; empty production pipeline floor`
    };
  }

  return ENEMY_UNIT_TYPES
    .filter((unitType) => canOwnerProduceUnit(state, "Enemy", unitType))
    .filter((unitType) => !isEnemyProductionHardCapped(state, unitType))
    .map((unitType) => {
      const cost = getProductionCost(unitType);
      const score = scoreEnemyProductionChoice(state, unitType);
      return {
        kind: "production" as const,
        unitType,
        cost,
        score,
        priority: score - cost,
        reason: "empty production pipeline floor"
      };
    })
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .filter((item) => !chosen.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function applyEnemyRepeatProductionPurchasePenalty(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  item: EnemyEconomyPlanItem
): EnemyEconomyPlanItem {
  const productionSpentThisTurn = chosen.filter((candidate) => candidate.kind === "production").length;
  if (
    state.enemyEconomy.productionCapacityLevel <= 1 ||
    productionSpentThisTurn <= 0 ||
    isEnemyImmediateProductionNeed(state, plan, item)
  ) {
    return item;
  }

  const penalty = 140 + Math.max(0, productionSpentThisTurn - 1) * 95;
  return {
    ...item,
    priority: item.priority - penalty,
    score: item.score - penalty * 0.2,
    reason: `${item.reason}; repeat production value reduced`
  };
}

function isEnemyImmediateProductionNeed(state: GameState, plan: EnemyTurnPlan, item: EnemyEconomyPlanItem): boolean {
  if (item.kind !== "production" || !item.unitType) {
    return false;
  }

  const baseThreat = getEnemyBaseThreat(state);
  return (
    isEnemyRequiredFieldSupportProductionUnit(state, item.unitType) ||
    (baseThreat && isActiveEnemyBaseThreat(state, baseThreat) && canUnitTargetUnit(item.unitType, baseThreat.type)) ||
    (isEnemyGateLockoutEconomyOverride(state, plan) && isEnemyGateLockoutDirectCombatProductionUnit(item.unitType)) ||
    (plan.objectiveImperatives.some((imperative) => imperative.terminal < 0) && canUnitTargetUnit(item.unitType, "Infantry"))
  );
}

function chooseNextEnemyResearchPlanItem(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  const requiredStrategicDeadline = chooseEnemyRequiredStrategicDeadlineResearchCandidate(state, plan);
  if (requiredStrategicDeadline || isEnemyStrategicDeadlineResearchGateBlocking(state)) {
    return requiredStrategicDeadline;
  }

  const baseContext = createEnemyResearchFeasibilityContext(state);
  const context = {
    ...baseContext,
    queueLimit: shouldEnemyBypassEfficiencyGateForCommittedUpgrade(state)
      ? Math.max(baseContext.queueLimit, state.enemyEconomy.researchQueue.length + 1)
      : baseContext.queueLimit,
    criticalTechReserve: 0,
    productionReserve: 0
  };
  const candidates = getEnemyPlannerResearchCandidates(state, plan, context)
    .filter((item) => !chosen.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .map((item) => applyEnemyRepeatResearchPurchasePenalty(state, chosen, item))
    .map((item) => applyEnemyEconomyResearchLevelSpreadPenalty(state, item))
    .map((item) => applyEnemyProminentUnlockResearchPriorityBonus(state, plan, item))
    .map((item) => applyEnemyBalancedEconomyResearchPriorityBonus(state, item));

  const requiredEfficiencyGate = chooseEnemyRequiredEfficiencyGateResearchCandidate(state, candidates);
  if (requiredEfficiencyGate || isEnemyEfficiencyResearchGateBlocking(state)) {
    return requiredEfficiencyGate;
  }

  if (isEnemyFirstReaperSpendBlocking(state)) {
    return undefined;
  }

  const committedUpgradeResearch = chooseEnemyCommittedUnitUpgradeResearchCandidate(state, plan, chosen, candidates);
  if (committedUpgradeResearch) {
    return committedUpgradeResearch;
  }

  const best = candidates
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
  const forcedEfficiency = chooseEnemyMinimumEfficiencyResearchCandidate(state, plan, chosen, candidates);
  if (forcedEfficiency) {
    return forcedEfficiency;
  }
  if (!best || scoreEnemyNoResearchPriority(state, candidates) >= best.priority) {
    return undefined;
  }
  return best;
}

function chooseEnemyImmediateStrategicUnlockResearchPlanItem(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    state.day < 12 ||
    plan.campaignPlan.phase === "BaseDefenseEmergency" ||
    isEnemyGateLockoutEconomyOverride(state, plan) ||
    plan.objectiveImperatives.some((imperative) => imperative.terminal < 0)
  ) {
    return undefined;
  }

  const candidates = getEnemyPlannerResearchCandidates(state, plan, {
    ...createEnemyResearchFeasibilityContext(state),
    criticalTechReserve: 0,
    productionReserve: 0
  })
    .filter((item) => item.kind === "research" && (item.researchType === "UnlockSpecialServices" || item.researchType === "UnlockDroneFactory"))
    .filter((item) => !chosen.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .map((item) => ({
      ...item,
      priority: item.priority + 2_400 + (item.researchType === "UnlockDroneFactory" ? 260 : 0),
      reason: `${item.reason}; immediate affordable strategic unlock`
    }))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost);
  const best = candidates[0];
  return best && best.priority > scoreEnemyNoResearchPriority(state, candidates) ? best : undefined;
}

function chooseEnemyRequiredStrategicDeadlineResearchCandidate(
  state: GameState,
  plan: EnemyTurnPlan
): EnemyEconomyPlanItem | undefined {
  const researchType = getEnemyStrategicDeadlineBlockingResearchType(state);
  const startLevel = researchType ? getNextResearchStartLevel(state.enemyEconomy, researchType, undefined) : 1;
  if (!researchType || !canStartResearch(state, "Enemy", researchType, undefined, { ignoreMoney: canEnemySpendGainOnResearchLine(state, researchType, undefined, startLevel) })) {
    return undefined;
  }

  const context = {
    ...createEnemyResearchFeasibilityContext(state),
    criticalTechReserve: 0,
    productionReserve: 0
  };
  const candidate = getEnemyPlannerResearchCandidates(state, plan, context)
    .filter((item) => item.kind === "research" && item.researchType === researchType)
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
  if (candidate) {
    return {
      ...candidate,
      priority: Math.max(candidate.priority, 100_000),
      reason: `${candidate.reason}; required day-${getEnemyStrategicUnlockDeadlineDay(researchType)} strategic unlock`
    };
  }

  const cost = getResearchCost(researchType, undefined, state.enemyEconomy, startLevel);
  if (state.enemyEconomy.moneyPoundsBn < cost && !canEnemySpendGainOnResearchLine(state, researchType, undefined, startLevel)) {
    return undefined;
  }

  const option: EnemyResearchOption = {
    type: researchType,
    cost,
    score: scoreEnemyResearchOption(state, researchType)
  };
  const timing = estimateEnemyResearchTiming(state, option);
  const phasePriority = getEnemyPhaseEconomyResearchPriority(state, plan, option);
  return {
    kind: "research",
    researchType,
    cost,
    score: option.score,
    priority: 100_000 + option.score + phasePriority,
    reason: `required day-${getEnemyStrategicUnlockDeadlineDay(researchType)} strategic unlock, completion d${timing.completeDay}`
  };
}

function isEnemyStrategicDeadlineResearchGateBlocking(state: GameState): boolean {
  return Boolean(getEnemyStrategicDeadlineBlockingResearchType(state));
}

function getEnemyStrategicDeadlineBlockingResearchType(state: GameState): ResearchType | undefined {
  const requiredEfficiencyLevel = getEnemyRequiredEfficiencyResearchGateLevel(state);
  if (requiredEfficiencyLevel && !hasEnemyEfficiencyResearchStartedForLevel(state, requiredEfficiencyLevel)) {
    if (
      state.day >= ENEMY_SPECIAL_SERVICES_RESEARCH_DEADLINE_DAY &&
      !hasEnemyStrategicUnlockResearchStarted(state, "UnlockSpecialServices") &&
      shouldEnemyForceStrategicUnlockBeforeEfficiency(state, "UnlockSpecialServices")
    ) {
      return "UnlockSpecialServices";
    }
    if (
      state.day >= ENEMY_DRONE_FACTORY_RESEARCH_DEADLINE_DAY &&
      !hasEnemyStrategicUnlockResearchStarted(state, "UnlockDroneFactory") &&
      shouldEnemyForceStrategicUnlockBeforeEfficiency(state, "UnlockDroneFactory")
    ) {
      return "UnlockDroneFactory";
    }
    return undefined;
  }

  if (state.day >= ENEMY_SPECIAL_SERVICES_RESEARCH_DEADLINE_DAY && !hasEnemyStrategicUnlockResearchStarted(state, "UnlockSpecialServices")) {
    return "UnlockSpecialServices";
  }

  if (state.day >= ENEMY_DRONE_FACTORY_RESEARCH_DEADLINE_DAY && !hasEnemyStrategicUnlockResearchStarted(state, "UnlockDroneFactory")) {
    return "UnlockDroneFactory";
  }

  return undefined;
}

function shouldEnemyForceStrategicUnlockBeforeEfficiency(state: GameState, researchType: ResearchType): boolean {
  const intel = getPlayerIntelForEnemy(state);
  if (researchType === "UnlockSpecialServices") {
    return intel.some((entry) => entry.unit.type === "Spectral" || entry.unit.type === "Ghost" || entry.unit.type === "Operator");
  }
  if (researchType === "UnlockDroneFactory") {
    return getPlayerArtilleryPressure(state) > 80 || intel.some((entry) => entry.unit.type === "Spectral");
  }
  return false;
}

function hasEnemyStrategicUnlockResearchStarted(state: GameState, researchType: ResearchType): boolean {
  if (researchType === "UnlockSpecialServices" && ownerHasBuilding(state, "Enemy", "Special Services")) {
    return true;
  }
  if (researchType === "UnlockDroneFactory" && ownerHasBuilding(state, "Enemy", "Drone Factory")) {
    return true;
  }

  return state.enemyEconomy.researchQueue.some((job) => job.owner === "Enemy" && job.type === researchType);
}

function getEnemyStrategicUnlockDeadlineDay(researchType: ResearchType): number {
  return researchType === "UnlockDroneFactory" ? ENEMY_DRONE_FACTORY_RESEARCH_DEADLINE_DAY : ENEMY_SPECIAL_SERVICES_RESEARCH_DEADLINE_DAY;
}

function applyEnemyRepeatResearchPurchasePenalty(
  state: GameState,
  chosen: EnemyEconomyPlanItem[],
  item: EnemyEconomyPlanItem
): EnemyEconomyPlanItem {
  const researchSpentThisTurn = chosen.filter((candidate) => candidate.kind === "research").length;
  if (researchSpentThisTurn <= 0) {
    return item;
  }

  const penalty = 720 + Math.max(0, researchSpentThisTurn - 1) * 240;
  return {
    ...item,
    priority: item.priority - penalty,
    score: item.score - penalty * 0.18,
    reason: `${item.reason}; repeat research value reduced`
  };
}

function applyEnemyProminentUnlockResearchPriorityBonus(
  state: GameState,
  plan: EnemyTurnPlan,
  item: EnemyEconomyPlanItem
): EnemyEconomyPlanItem {
  if (
    item.kind !== "research" ||
    !item.researchType ||
    (item.researchType !== "UnlockSpecialServices" && item.researchType !== "UnlockDroneFactory") ||
    !isEnemyStrategicUnlockProminent(state, plan, item.researchType, item.score)
  ) {
    return item;
  }

  const bonus = 520 + (item.researchType === "UnlockDroneFactory" ? 120 : 0);
  return {
    ...item,
    priority: item.priority + bonus,
    score: item.score + bonus * 0.15,
    reason: `${item.reason}; prominent strategic unlock`
  };
}

function applyEnemyBalancedEconomyResearchPriorityBonus(state: GameState, item: EnemyEconomyPlanItem): EnemyEconomyPlanItem {
  if (item.kind !== "research" || !item.researchType || !ENEMY_ECONOMY_RESEARCH_ORDER.includes(item.researchType)) {
    return item;
  }

  const researchType = item.researchType;
  const orderIndex = ENEMY_ECONOMY_RESEARCH_ORDER.indexOf(researchType);
  const effectiveLevel = getEnemyEconomyResearchEffectiveLevel(state, researchType);
  const lowestEconomyLevel = Math.min(
    ...ENEMY_ECONOMY_RESEARCH_ORDER.map((type) => getEnemyEconomyResearchEffectiveLevel(state, type))
  );
  const orderBias = (ENEMY_ECONOMY_RESEARCH_ORDER.length - orderIndex) * 24;
  const efficiencyBias = researchType === "Efficiency" ? 90 + Math.max(0, 4 - effectiveLevel) * 45 : 0;
  const levelGapPenalty = Math.max(0, effectiveLevel - lowestEconomyLevel) * 240;
  const matureEconomyPenalty = Math.max(0, effectiveLevel - 4) * 130;
  const priority = orderBias + efficiencyBias - levelGapPenalty - matureEconomyPenalty;
  return {
    ...item,
    priority: item.priority + priority,
    reason: `${item.reason}; balanced economy level ${effectiveLevel}`
  };
}

function chooseEnemyProminentUnlockResearchCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  return candidates
    .filter((item) => item.kind === "research" && (item.researchType === "UnlockSpecialServices" || item.researchType === "UnlockDroneFactory"))
    .filter((item) => item.researchType && isEnemyStrategicUnlockProminent(state, plan, item.researchType, item.score))
    .map((item) => ({
      ...item,
      priority: item.priority + 1_000 + (item.researchType === "UnlockDroneFactory" ? 90 : 0),
      reason: `${item.reason}; prominent strategic unlock`
    }))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function isEnemyStrategicUnlockProminent(
  state: GameState,
  plan: EnemyTurnPlan,
  researchType: ResearchType,
  score: number
): boolean {
  const assessment = plan.strategicSnapshot;
  const gateDisadvantage = getEnemyGateDisadvantage(state);
  const playerPressure = assessment.player.totalValue + getPlayerForwardPressure(state) * 0.35;

  if (researchType === "UnlockSpecialServices" && !ownerHasBuilding(state, "Enemy", "Special Services")) {
    return (
      (state.day >= 12 && canEnemyAffordResearchType(state, "UnlockSpecialServices")) ||
      (assessment.strategyPlan === "FastSpecialServices" && state.day >= 8) ||
      assessment.forecast.specialPipelineNeed >= 110 ||
      assessment.specialPlanUrgency >= 125 ||
      (state.day >= 10 && score >= 205) ||
      (state.day >= 12 && (gateDisadvantage > 0 || playerPressure >= 150))
    );
  }

  if (
    researchType === "UnlockDroneFactory" &&
    ownerHasBuilding(state, "Enemy", "Special Services") &&
    !ownerHasBuilding(state, "Enemy", "Drone Factory")
  ) {
    return (
      (state.day >= 12 && canEnemyAffordResearchType(state, "UnlockDroneFactory")) ||
      plan.doctrine.strategyPlaybook.requiredBehaviors.includes("UnlockDroneFactory") ||
      assessment.strategyPlan === "ReaperTechRush" ||
      assessment.forecast.reaperPipelineNeed >= 110 ||
      assessment.reaperPlanUrgency >= 125 ||
      score >= 205 ||
      (state.day >= 16 && (gateDisadvantage > 0 || getPlayerArtilleryPressure(state) >= 70 || playerPressure >= 170 || isEnemyBaseOperationPhase(plan.campaignPlan.phase)))
    );
  }

  return false;
}

function chooseEnemyBalancedEconomyResearchCandidate(
  state: GameState,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  const economyCandidates = candidates
    .filter((item) => item.kind === "research" && item.researchType && ENEMY_ECONOMY_RESEARCH_ORDER.includes(item.researchType))
    .map((item) => {
      const researchType = item.researchType!;
      const orderIndex = ENEMY_ECONOMY_RESEARCH_ORDER.indexOf(researchType);
      const effectiveLevel = getEnemyEconomyResearchEffectiveLevel(state, researchType);
      const lowestEconomyLevel = Math.min(
        ...ENEMY_ECONOMY_RESEARCH_ORDER.map((type) => getEnemyEconomyResearchEffectiveLevel(state, type))
      );
      const orderBias = (ENEMY_ECONOMY_RESEARCH_ORDER.length - orderIndex) * 72;
      const efficiencyBias = researchType === "Efficiency" ? 300 + Math.max(0, 5 - effectiveLevel) * 110 : 0;
      const levelGapPenalty = Math.max(0, effectiveLevel - lowestEconomyLevel) * 320;
      const matureEconomyPenalty = Math.max(0, effectiveLevel - 3) * 115;
      const balancedPriority = item.priority + 620 + orderBias + efficiencyBias + item.score * 0.28 - levelGapPenalty - matureEconomyPenalty;
      return {
        ...item,
        priority: balancedPriority,
        reason: `${item.reason}; balanced economy level ${effectiveLevel}`
      };
    })
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost);

  const best = economyCandidates[0];
  if (!best || best.priority < 120) {
    return undefined;
  }
  return best;
}

function chooseEnemyRequiredEfficiencyGateResearchCandidate(
  state: GameState,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (shouldEnemyBypassEfficiencyGateForStrategicUnlock(state) || shouldEnemyBypassEfficiencyGateForCommittedUpgrade(state)) {
    return undefined;
  }

  const requiredLevel = getEnemyRequiredEfficiencyResearchGateLevel(state);
  if (!requiredLevel || hasEnemyEfficiencyResearchStartedForLevel(state, requiredLevel)) {
    return undefined;
  }

  if (hasEnemyEfficiencyResearchQueuedForLevel(state, requiredLevel)) {
    return undefined;
  }

  const efficiency = candidates.find((item) => item.kind === "research" && item.researchType === "Efficiency");
  if (efficiency && canEnemyAffordEconomyPlanItem(state, efficiency)) {
    return {
      ...efficiency,
      priority: efficiency.priority + 100_000,
      reason: `${efficiency.reason}; required Efficiency gate before other spending`
    };
  }

  const startLevel = getNextResearchStartLevel(state.enemyEconomy, "Efficiency", undefined);
  if (!canStartResearch(state, "Enemy", "Efficiency", undefined, { ignoreMoney: canEnemySpendGainOnResearchLine(state, "Efficiency", undefined, startLevel) })) {
    return undefined;
  }
  if (state.enemyEconomy.researchQueue.length >= getEnemyRoutineResearchQueueLimit(state)) {
    return undefined;
  }

  const cost = getResearchCost("Efficiency", undefined, state.enemyEconomy);
  if (state.enemyEconomy.moneyPoundsBn < cost && !canEnemySpendGainOnResearchLine(state, "Efficiency", undefined, startLevel)) {
    return undefined;
  }
  return {
    kind: "research",
    researchType: "Efficiency",
    cost,
    score: 0,
    priority: 100_000,
    reason: "required Efficiency gate before other spending"
  };
}

function isEnemyEfficiencyResearchGateBlocking(state: GameState): boolean {
  if (isEnemyStrategicDeadlineResearchGateBlocking(state) || isEnemyFirstReaperSpendBlocking(state)) {
    return false;
  }

  if (shouldEnemyBypassEfficiencyGateForStrategicUnlock(state) || shouldEnemyBypassEfficiencyGateForCommittedUpgrade(state)) {
    return false;
  }

  const requiredLevel = getEnemyRequiredEfficiencyResearchGateLevel(state);
  return Boolean(requiredLevel && !hasEnemyEfficiencyResearchStartedForLevel(state, requiredLevel));
}

function shouldEnemyBypassEfficiencyGateForStrategicUnlock(state: GameState): boolean {
  if (state.difficulty !== "Hard" || state.day < 12) {
    return false;
  }
  const requiredEfficiencyLevel = getEnemyRequiredEfficiencyResearchGateLevel(state);
  if (requiredEfficiencyLevel && requiredEfficiencyLevel >= 4) {
    return false;
  }

  if (!ownerHasBuilding(state, "Enemy", "Special Services")) {
    const cost = getResearchCost("UnlockSpecialServices", undefined, state.enemyEconomy);
    return state.enemyEconomy.moneyPoundsBn >= Math.max(cost, 80) && canStartResearch(state, "Enemy", "UnlockSpecialServices", undefined);
  }

  if (!ownerHasBuilding(state, "Enemy", "Drone Factory")) {
    const cost = getResearchCost("UnlockDroneFactory", undefined, state.enemyEconomy);
    return state.enemyEconomy.moneyPoundsBn >= Math.max(cost, 80) && canStartResearch(state, "Enemy", "UnlockDroneFactory", undefined);
  }

  return false;
}

function shouldEnemyBypassEfficiencyGateForCommittedUpgrade(state: GameState): boolean {
  if (state.difficulty !== "Hard" || state.day < 18 || state.enemyEconomy.moneyPoundsBn < 250) {
    return false;
  }
  const requiredEfficiencyLevel = getEnemyRequiredEfficiencyResearchGateLevel(state);
  if (
    requiredEfficiencyLevel &&
    !state.enemyEconomy.researchQueue.some((job) => job.type === "Efficiency" && job.startedDay <= state.day)
  ) {
    return false;
  }

  return ENEMY_UNIT_TYPES.some((unitType) => {
    if (!canStartResearch(state, "Enemy", "UnitUpgrade", unitType)) {
      return false;
    }

    const profile = getEnemyUnitUpgradeUseProfile(state, unitType);
    return profile.fielded + profile.inventory + profile.queuedProduction > 0 && profile.committedUse >= 1;
  });
}

function getEnemyRequiredEfficiencyResearchGateLevel(state: GameState): number | undefined {
  if (state.difficulty !== "Hard") {
    return undefined;
  }

  if (state.day >= 25 && state.enemyEconomy.efficiencyLevel < 4) {
    return 4;
  }

  if (state.day >= 7 && state.enemyEconomy.efficiencyLevel < 3) {
    return 3;
  }

  return undefined;
}

function hasEnemyEfficiencyResearchStartedForLevel(state: GameState, requiredLevel: number): boolean {
  return (
    state.enemyEconomy.efficiencyLevel >= requiredLevel ||
    state.enemyEconomy.researchQueue.some(
      (job) => job.type === "Efficiency" && (job.targetLevel ?? 0) >= requiredLevel && job.startedDay <= state.day
    )
  );
}

function hasEnemyEfficiencyResearchQueuedForLevel(state: GameState, requiredLevel: number): boolean {
  return state.enemyEconomy.researchQueue.some(
    (job) => job.type === "Efficiency" && (job.targetLevel ?? 0) >= requiredLevel
  );
}

function chooseEnemyMinimumEfficiencyResearchCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  const economy = state.enemyEconomy;
  const efficiencyQueued =
    economy.researchQueue.some((job) => job.type === "Efficiency") ||
    chosen.some((item) => item.kind === "research" && item.researchType === "Efficiency");
  const otherEconomyScalingStarted =
    economy.researchCapacityLevel > 1 ||
    economy.productionCapacityLevel > 1 ||
    economy.researchSpeedLevel > 1 ||
    economy.productionSpeedLevel > 1 ||
    economy.researchQueue.some((job) => job.type === "ResearchCapacity" || job.type === "ProductionCapacity" || job.type === "ResearchSpeed" || job.type === "ProductionSpeed");

  if (
    state.difficulty !== "Hard" ||
    economy.efficiencyLevel >= 3 ||
    getEnemyCompletedResearchCount(state) >= 12 ||
    efficiencyQueued ||
    state.day < 7 ||
    plan.campaignPlan.phase === "BaseDefenseEmergency" ||
    !otherEconomyScalingStarted
  ) {
    return undefined;
  }

  const efficiency = candidates.find((item) => item.kind === "research" && item.researchType === "Efficiency");
  if (!efficiency || state.enemyEconomy.moneyPoundsBn < efficiency.cost) {
    return undefined;
  }

  return {
    ...efficiency,
    priority: efficiency.priority + 2_000,
    reason: `${efficiency.reason}; minimum efficiency floor`
  };
}

function getEnemyEconomyResearchEffectiveLevel(state: GameState, researchType: ResearchType): number {
  return getNextResearchStartLevel(state.enemyEconomy, researchType, undefined);
}

function applyEnemyEconomyResearchLevelSpreadPenalty(state: GameState, item: EnemyEconomyPlanItem): EnemyEconomyPlanItem {
  if (!item.researchType || !ENEMY_ECONOMY_RESEARCH_ORDER.includes(item.researchType)) {
    return item;
  }

  const effectiveLevel = getEnemyEconomyResearchEffectiveLevel(state, item.researchType);
  const levels = ENEMY_ECONOMY_RESEARCH_ORDER.map((type) => getEnemyEconomyResearchEffectiveLevel(state, type));
  const lowestLevel = Math.min(...levels);
  const belowThisLineCount = levels.filter((level) => level < effectiveLevel).length;
  if (effectiveLevel <= lowestLevel || belowThisLineCount === 0) {
    return item;
  }

  const levelGap = effectiveLevel - lowestLevel;
  const earlyTierThreePenalty = effectiveLevel >= 2 && lowestLevel <= 1 ? 900 + belowThisLineCount * 140 : 0;
  const penalty = levelGap * 420 + belowThisLineCount * 90 + earlyTierThreePenalty;
  return {
    ...item,
    priority: item.priority - penalty,
    reason: `${item.reason}; economy spread penalty ${Math.round(penalty)}`
  };
}

function chooseEnemyUnitUpgradeResearchCandidate(
  state: GameState,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  const best = candidates
    .filter((item) => item.kind === "research" && item.researchType === "UnitUpgrade" && item.researchUnitType)
    .map((item) => ({
      ...item,
      priority: item.priority + getEnemyUnitUpgradeResearchPriorityBonus(state, item.researchUnitType!),
      reason: `${item.reason}; fielded unit upgrade value`
    }))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];

  if (!best || best.priority < 42) {
    return undefined;
  }
  return best;
}

function getEnemyUnitUpgradeResearchPriorityBonus(state: GameState, unitType: UnitType): number {
  const profile = getEnemyUnitUpgradeUseProfile(state, unitType);
  if (profile.committedUse <= 0 || profile.fielded + profile.inventory + profile.queuedProduction <= 0) {
    return -500;
  }

  const value = getUnitTypeValue(state, "Enemy", unitType);
  const fieldedValue = profile.fielded * value * 0.24 + profile.fieldUpgradeable * 18;
  const pipelineValue = profile.inventory * value * 0.08 + profile.queuedProduction * value * 0.14;
  const combatPowerBonus =
    unitType === "Reaper" ? 58 :
    unitType === "Tank" ? 44 :
    unitType === "Ghost" || unitType === "Operator" ? 40 :
    unitType === "Bomber" || unitType === "Jet" ? 36 :
    unitType === "Artillery" ? 30 :
    unitType === "IFV" || unitType === "Anti-Air" ? 24 :
    10;

  return fieldedValue + pipelineValue + combatPowerBonus + Math.max(0, scoreUnitCountersPlayerArmy(state, unitType)) * 0.1;
}

function getEnemyUnitUpgradeQualityMultiplier(state: GameState, unitType: UnitType): number {
  const infantryValue = getUnitTypeValue(state, "Enemy", "Infantry");
  const value = getUnitTypeValue(state, "Enemy", unitType);
  return Math.max(0.7, Math.min(2.6, value / Math.max(1, infantryValue)));
}

function chooseNextEnemyEconomyPlanItem(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  options: { includeFieldUpgrades?: boolean } = {}
): EnemyEconomyPlanItem | undefined {
  const includeFieldUpgrades = options.includeFieldUpgrades ?? true;
  const candidates = [
    ...getEnemyPlannerProductionCandidates(state, plan),
    ...getEnemyPlannerResearchCandidates(state, plan),
    ...(includeFieldUpgrades ? getEnemyPlannerFieldUpgradeCandidates(state, plan) : [])
  ]
    .filter((item) => !chosen.some((existing) => isSameEnemyEconomyPlanItem(existing, item)))
    .filter((item) => canEnemyAffordEconomyPlanItem(state, item))
    .map((item) => applyEnemyEconomyResearchLevelSpreadPenalty(state, item));

  const requiredLockoutCombatProduction = chooseEnemyGateLockoutRequiredProductionCandidate(state, plan, chosen, candidates);
  if (requiredLockoutCombatProduction) {
    return requiredLockoutCombatProduction;
  }

  const openingEfficiencyResearch = chooseEnemyOpeningEfficiencyResearchCandidate(state, plan, chosen, candidates);
  if (openingEfficiencyResearch) {
    return openingEfficiencyResearch;
  }

  const midgameDoctrineResearch = chooseEnemyMidgameDoctrineResearchCandidate(state, plan, chosen, candidates);
  if (midgameDoctrineResearch) {
    return midgameDoctrineResearch;
  }

  const endgameDoctrineResearch = chooseEnemyEndgameDoctrineResearchCandidate(state, plan, chosen, candidates);
  if (endgameDoctrineResearch) {
    return endgameDoctrineResearch;
  }

  const criticalTechResearch = chooseEnemyCriticalTechResearchCandidate(state, plan, candidates);
  if (criticalTechResearch) {
    return criticalTechResearch;
  }

  const committedUpgradeResearch = chooseEnemyCommittedUnitUpgradeResearchCandidate(state, plan, chosen, candidates);
  if (committedUpgradeResearch) {
    return committedUpgradeResearch;
  }

  const bootstrapResearch = chooseEnemyEconomyThroughputBootstrapCandidate(state, plan, chosen, candidates);
  if (bootstrapResearch) {
    return bootstrapResearch;
  }

  const sortedCandidates = candidates
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost);

  const best = sortedCandidates[0];
  if (!best || best.priority < 42) {
    return undefined;
  }
  return best;
}

function chooseEnemyOpeningEfficiencyResearchCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    !isHardOpeningDoctrineActive(state) ||
    plan.campaignPlan.phase !== "OpeningGateRace" ||
    state.enemyEconomy.researchQueue.some((job) => job.type === "Efficiency") ||
    chosen.some((item) => item.kind === "research" && item.researchType === "Efficiency")
  ) {
    return undefined;
  }

  return candidates
    .filter((item) => item.kind === "research" && item.researchType === "Efficiency")
    .map((item) => ({
      ...item,
      priority: item.priority + 1_200,
      reason: `${item.reason}; opening efficiency doctrine`
    }))
    .sort((first, second) => second.priority - first.priority || first.cost - second.cost)[0];
}

function chooseEnemyMidgameDoctrineResearchCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    !isHardMidgameDoctrineActive(state, plan) ||
    isEnemyGateLockoutEconomyOverride(state, plan) ||
    plan.campaignPlan.phase === "BaseDefenseEmergency" ||
    (plan.doctrine.strategyPlaybook.requiredBehaviors.includes("UnlockDroneFactory") && !ownerHasBuilding(state, "Enemy", "Drone Factory")) ||
    plan.objectiveImperatives.some((imperative) => imperative.terminal < 0) ||
    chosen.some((item) => item.kind === "research")
  ) {
    return undefined;
  }

  const alreadyQueued = (researchType: ResearchType, unitType?: UnitType): boolean =>
    state.enemyEconomy.researchQueue.some((job) => job.type === researchType && job.unitType === unitType);
  const preferredResearch: ResearchType[] = ["Efficiency", "ResearchCapacity", "ProductionCapacity", "ResearchSpeed", "ProductionSpeed", "UnlockSpecialServices"];
  for (const researchType of preferredResearch) {
    if (alreadyQueued(researchType)) {
      continue;
    }
    const option = candidates.find((item) => item.kind === "research" && item.researchType === researchType);
    if (option) {
      return {
        ...option,
        priority: option.priority + 720,
        reason: `${option.reason}; midgame doctrine research`
      };
    }
  }

  const basicUpgradeOrder: UnitType[] = ["Infantry", "Tank", "IFV", "Attack Heli", "Artillery", "Anti-Air"];
  return candidates
    .filter((item) => item.kind === "research" && item.researchType === "UnitUpgrade" && item.researchUnitType)
    .filter((item) => Boolean(item.researchUnitType && basicUpgradeOrder.includes(item.researchUnitType)))
    .filter((item) => !alreadyQueued("UnitUpgrade", item.researchUnitType))
    .map((item) => ({
      ...item,
      priority: item.priority + 160 + (item.researchUnitType ? Math.max(0, basicUpgradeOrder.length - basicUpgradeOrder.indexOf(item.researchUnitType)) * 6 : 0),
      reason: `${item.reason}; midgame basic upgrade doctrine`
    }))
    .sort((first, second) => second.priority - first.priority || first.cost - second.cost)[0];
}

function chooseEnemyEndgameDoctrineResearchCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    !isHardEndgameDoctrineActive(state, plan) ||
    plan.campaignPlan.phase === "BaseDefenseEmergency" ||
    plan.objectiveImperatives.some((imperative) => imperative.terminal < 0) ||
    chosen.some((item) => item.kind === "research")
  ) {
    return undefined;
  }

  const alreadyQueued = (researchType: ResearchType, unitType?: UnitType): boolean =>
    state.enemyEconomy.researchQueue.some((job) => job.type === researchType && job.unitType === unitType);
  const preferredResearch: ResearchType[] = ["UnlockDroneFactory", "Efficiency", "ResearchCapacity", "ProductionCapacity", "ResearchSpeed", "ProductionSpeed", "UnlockSpecialServices"];
  for (const researchType of preferredResearch) {
    if (alreadyQueued(researchType)) {
      continue;
    }
    const option = candidates.find((item) => item.kind === "research" && item.researchType === researchType);
    if (option) {
      return {
        ...option,
        priority: option.priority + 860,
        reason: `${option.reason}; endgame doctrine research`
      };
    }
  }

  const upgradeOrder: UnitType[] = ["Reaper", "Ghost", "Operator", "Bomber", "Jet"];
  return candidates
    .filter((item) => item.kind === "research" && item.researchType === "UnitUpgrade" && item.researchUnitType)
    .filter((item) => Boolean(item.researchUnitType && upgradeOrder.includes(item.researchUnitType)))
    .filter((item) => !alreadyQueued("UnitUpgrade", item.researchUnitType))
    .map((item) => ({
      ...item,
      priority: item.priority + 220 + (item.researchUnitType ? Math.max(0, upgradeOrder.length - upgradeOrder.indexOf(item.researchUnitType)) * 8 : 0),
      reason: `${item.reason}; endgame advanced upgrade doctrine`
    }))
    .sort((first, second) => second.priority - first.priority || first.cost - second.cost)[0];
}

function chooseEnemyGateLockoutRequiredProductionCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    !isEnemyGateLockoutEconomyOverride(state, plan) ||
    chosen.some((item) => item.kind === "production" && item.unitType && isEnemyGateLockoutDirectCombatProductionUnit(item.unitType))
  ) {
    return undefined;
  }

  return candidates
    .filter((item) => item.kind === "production" && item.unitType && isEnemyGateLockoutDirectCombatProductionUnit(item.unitType))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function chooseEnemyBaseDefenseEmergencyProductionCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (plan.campaignPlan.phase !== "BaseDefenseEmergency") {
    return undefined;
  }

  const threat = getEnemyBaseThreat(state);
  if (!threat || !isActiveEnemyBaseThreat(state, threat)) {
    return undefined;
  }

  return candidates
    .filter((item) => item.kind === "production" && item.unitType && canUnitTargetUnit(item.unitType, threat.type))
    .map((item) => ({
      ...item,
      priority: item.priority + 4_000,
      reason: `${item.reason}; required base defense remover`
    }))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function chooseEnemyOpeningRequiredCapturerProductionCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  const reserveCapturerCount = ENEMY_CAPTURE_UNIT_TYPES.reduce(
    (total, unitType) =>
      total +
      Math.max(0, Math.floor(state.enemyEconomy.inventory[unitType] ?? 0)) +
      state.enemyEconomy.productionQueue.filter((job) => job.owner === "Enemy" && job.unitType === unitType).length,
    0
  );
  if (
    state.difficulty !== "Hard" ||
    state.day > 8 ||
    plan.playerIntel.length > 0 ||
    reserveCapturerCount > 0
  ) {
    return undefined;
  }

  return candidates
    .filter((item) => item.kind === "production" && item.unitType && getUnitDefinition(item.unitType).humanBased)
    .map((item) => ({
      ...item,
      priority: item.priority + 1_800,
      reason: `${item.reason}; required opening capturer`
    }))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function chooseEnemyBaseAssaultRequiredClearerProductionCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    state.difficulty !== "Hard" ||
    (plan.campaignPlan.phase !== "BothGatesOwned" && plan.campaignPlan.phase !== "BaseAssault") ||
    chosen.some((item) => item.kind === "production" && item.unitType && ["Tank", "Artillery", "Bomber", "Reaper"].includes(item.unitType))
  ) {
    return undefined;
  }

  const baseBlocker = getPlayerBaseTileBlocker(state) ?? getPlayerBaseAreaDefender(state);
  if (!baseBlocker) {
    return undefined;
  }

  return candidates
    .filter((item) => item.kind === "production" && item.unitType && ["Tank", "Artillery", "Bomber", "Reaper"].includes(item.unitType))
    .filter((item) => item.unitType && canUnitTargetUnit(item.unitType, baseBlocker.type))
    .map((item) => ({
      ...item,
      priority: item.priority + 2_100,
      reason: `${item.reason}; required base approach clearer`
    }))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function isEnemyGateLockoutEconomyOverride(state: GameState, plan: EnemyTurnPlan): boolean {
  return state.difficulty === "Hard" && plan.campaignPlan.phase === "GateLockoutCombat";
}

function chooseEnemyCriticalTechResearchCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    state.difficulty !== "Hard" ||
    plan.campaignPlan.phase === "BaseDefenseEmergency" ||
    plan.objectiveImperatives.some((imperative) => imperative.terminal < 0)
  ) {
    return undefined;
  }

  return candidates
    .filter((item) => {
      if (item.kind !== "research" || !item.researchType) {
        return false;
      }
      return isCriticalEnemyTechResearchOption(state, {
        type: item.researchType,
        unitType: item.researchUnitType,
        cost: item.cost,
        score: item.score
      });
    })
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function chooseEnemyCommittedUnitUpgradeResearchCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  const hasCommittedUpgradeLine = candidates.some((item) => {
    if (item.kind !== "research" || item.researchType !== "UnitUpgrade" || !item.researchUnitType) {
      return false;
    }
    const profile = getEnemyUnitUpgradeUseProfile(state, item.researchUnitType);
    return profile.fielded + profile.inventory + profile.queuedProduction > 0 && profile.committedUse >= 1;
  });

  if (
    state.difficulty !== "Hard" ||
    state.day < 18 ||
    chosen.some((item) => item.kind === "research" && item.researchType === "UnitUpgrade") ||
    (!chosen.some((item) => item.kind === "production") && !hasCommittedUpgradeLine) ||
    hasAvailableEnemyCriticalTechResearch(state) ||
    plan.campaignPlan.phase === "BaseDefenseEmergency" ||
    plan.objectiveImperatives.some((imperative) => imperative.terminal < 0)
  ) {
    return undefined;
  }

  return candidates
    .filter((item) => item.kind === "research" && item.researchType === "UnitUpgrade" && item.researchUnitType)
    .filter((item) => {
      const profile = item.researchUnitType ? getEnemyUnitUpgradeUseProfile(state, item.researchUnitType) : undefined;
      return Boolean(profile && profile.committedUse > 0 && profile.fielded + profile.inventory + profile.queuedProduction > 0);
    })
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function chooseEnemyEconomyThroughputBootstrapCandidate(
  state: GameState,
  plan: EnemyTurnPlan,
  chosen: EnemyEconomyPlanItem[],
  candidates: EnemyEconomyPlanItem[]
): EnemyEconomyPlanItem | undefined {
  if (
    state.difficulty !== "Hard" ||
    state.day < 8 ||
    state.enemyEconomy.researchQueue.length > 0 ||
    chosen.some((item) => item.kind === "research") ||
    !chosen.some((item) => item.kind === "production") ||
    isEnemyGateLockoutEconomyOverride(state, plan) ||
    plan.campaignPlan.phase === "BaseDefenseEmergency" ||
    plan.objectiveImperatives.some((imperative) => imperative.terminal < 0)
  ) {
    return undefined;
  }

  return candidates
    .filter((item) => item.kind === "research" && item.researchType && isEconomyOrThroughputResearch(item.researchType))
    .filter((item) => item.priority >= 36 || state.enemyEconomy.moneyPoundsBn >= 160)
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
}

function isSameEnemyEconomyPlanItem(first: EnemyEconomyPlanItem, second: EnemyEconomyPlanItem): boolean {
  return (
    first.kind === second.kind &&
    first.unitType === second.unitType &&
    first.researchType === second.researchType &&
    first.researchUnitType === second.researchUnitType &&
    first.unitId === second.unitId
  );
}

function getEnemyPlannerProductionCandidates(state: GameState, plan: EnemyTurnPlan): EnemyEconomyPlanItem[] {
  const gateLockoutOverride = isEnemyGateLockoutEconomyOverride(state, plan);
  if (state.enemyEconomy.productionQueue.length >= getEnemyRoutineProductionQueueLimit(state)) {
    return [];
  }

  const context: EnemyProductionCandidateContext = {
    assessment: plan.strategicSnapshot,
    campaignPlan: plan.campaignPlan,
    phase: plan.campaignPlan.phase,
    reserve: 0,
    researchReserveFloor: 0,
    scoreThreshold: getAiDifficultyConfig(state).productionScoreThreshold,
    armySpendDownThreshold: ENEMY_ARMY_SPEND_DOWN_SCORE_THRESHOLD
  };
  return ENEMY_UNIT_TYPES
    .filter((unitType) => canOwnerProduceUnit(state, "Enemy", unitType))
    .filter((unitType) => !isEnemyProductionHardCapped(state, unitType))
    .filter((unitType) => !isEnemyGateLockoutCappedCapturerProduction(state, plan, unitType))
    .filter((unitType) => canEnemyAffordProductionUnit(state, unitType))
    .map((unitType) => {
      const timing = estimateEnemyProductionTiming(state, unitType);
      const cost = getProductionCost(unitType);
      const baseScore = scoreEnemyProductionChoice(state, unitType);
      const variableScore = scoreEnemyProductionVariableFit(state, unitType);
      const phasePriority = getEnemyPhaseEconomyProductionPriority(state, plan, unitType);
      const score = baseScore + variableScore + phasePriority * 0.65;
      const delayPenalty = timing.waitDays * 18 + Math.max(0, timing.totalDays - 6) * 5;
      const lockupPenalty = 0;
      const obsoletePenalty = isEnemyProductionObsoletedByQueuedUpgrade(state, unitType, timing) ? 120 : 0;
      const gateLockoutCombatBonus =
        gateLockoutOverride && isEnemyGateLockoutDirectCombatProductionUnit(unitType)
          ? 210 + Math.max(0, plan.strategicSnapshot.gateLockoutLeverage) * 0.28
          : 0;
      const heavyArmorBonus = getEnemyHeavyArmorProductionPriorityBonus(state, unitType, plan);
      const ifvSaturationPenalty = getEnemyIfvProductionSaturationPenalty(state, unitType);
      const emergencyBonus =
        plan.objectiveImperatives.some((imperative) => imperative.terminal < 0) && canUnitTargetUnit(unitType, "Infantry") ? 90 : 0;
      const midgameTankBonus =
        unitType === "Tank" &&
        state.day >= 12 &&
        state.day <= 22 &&
        plan.playerIntel.some((intel) => intel.unit.type === "Tank" || intel.unit.type === "IFV")
          ? 95
          : 0;
      const priority =
        score -
        cost * (gateLockoutOverride && isEnemyGateLockoutDirectCombatProductionUnit(unitType) ? 0.95 : 1.5) -
        delayPenalty -
        lockupPenalty -
        obsoletePenalty -
        ifvSaturationPenalty +
        emergencyBonus +
        midgameTankBonus +
        heavyArmorBonus +
        gateLockoutCombatBonus +
        phasePriority;
      return {
        kind: "production" as const,
        unitType,
        cost,
        score,
        priority,
        reason: `${gateLockoutCombatBonus > 0 ? "lockout combat " : ""}production score ${Math.round(score)}, variables ${Math.round(variableScore)}, phase ${Math.round(phasePriority)}, armor ${Math.round(heavyArmorBonus)}, arrival d${timing.completeDay}`
      };
    })
    .filter((item) => shouldEvaluateEnemyProductionCandidate(state, item.unitType, context));
}

function isEnemyProductionHardCapped(state: GameState, unitType: UnitType): boolean {
  const limit = ENEMY_PRODUCTION_HARD_LIMITS[unitType];
  return limit !== undefined && getEnemyProductionHardLimitCount(state, unitType) >= limit;
}

function getEnemyProductionHardLimitCount(state: GameState, unitType: UnitType): number {
  const fielded = getOwnerUnits(state, "Enemy").filter((unit) => unit.type === unitType && unit.health > 0).length;
  const inventory = getEnemyInventoryHardLimitCount(state, unitType);
  const queued = state.enemyEconomy.productionQueue.filter((job) => job.unitType === unitType).length;
  return fielded + inventory + queued;
}

function getEnemyInventoryHardLimitCount(state: GameState, unitType: UnitType): number {
  const flatCount = Math.max(0, Math.floor(state.enemyEconomy.inventory[unitType] ?? 0));
  if (flatCount <= 0) {
    return 0;
  }
  const byLevel = state.enemyEconomy.inventoryByLevel?.[unitType];
  const levelCount = byLevel
    ? Object.values(byLevel).reduce((total, count) => total + Math.max(0, Math.floor(count ?? 0)), 0)
    : 0;
  return Math.max(flatCount, levelCount);
}

function getEnemyTotalProductionStockCount(state: GameState): number {
  const fielded = getOwnerUnits(state, "Enemy").filter((unit) => unit.health > 0).length;
  const inventory = ENEMY_UNIT_TYPES.reduce((total, unitType) => total + getEnemyInventoryHardLimitCount(state, unitType), 0);
  const queued = state.enemyEconomy.productionQueue.filter((job) => job.owner === "Enemy").length;
  return fielded + inventory + queued;
}

function getEnemyFieldedProductionCount(state: GameState): number {
  return getOwnerUnits(state, "Enemy").filter((unit) => unit.health > 0).length;
}

function getEnemyNextTurnIncome(state: GameState): number {
  return state.enemyEconomy.incomePoundsBn - getOwnerGateIncomeBonus(state, "Enemy");
}

function getEnemyProductionCostRatio(unitType: UnitType): number {
  const costs = ENEMY_UNIT_TYPES.map((candidate) => getProductionCost(candidate));
  const minCost = Math.min(...costs);
  const maxCost = Math.max(...costs);
  return (getProductionCost(unitType) - minCost) / Math.max(1, maxCost - minCost);
}

function getEnemyProductionAdvancedRatio(state: GameState, unitType: UnitType): number {
  const costRatio = getEnemyProductionCostRatio(unitType);
  const level = state.enemyEconomy.unitLevels[unitType];
  const levelRatio = (level - 1) / Math.max(1, getMaxUnitLevel(unitType) - 1);
  const specialRatio = isSpecialUnit(unitType) ? 1 : 0;
  return Math.max(0, Math.min(1, costRatio * 0.56 + levelRatio * 0.22 + specialRatio * 0.22));
}

function getEnemyLastProductionUnitType(state: GameState): UnitType | undefined {
  if (state.enemyEconomy.lastProductionUnitType) {
    return state.enemyEconomy.lastProductionUnitType;
  }

  return state.enemyEconomy.productionQueue
    .map((job, index) => ({ job, index }))
    .filter((entry) => entry.job.owner === "Enemy")
    .sort((first, second) => second.job.startedDay - first.job.startedDay || second.index - first.index)[0]?.job.unitType;
}

function getEnemyProductionRepetitionPenalty(state: GameState, unitType: UnitType): number {
  if (getEnemyLastProductionUnitType(state) !== unitType) {
    return 0;
  }

  const sameTypeQueued = state.enemyEconomy.productionQueue.filter((job) => job.owner === "Enemy" && job.unitType === unitType).length;
  const costRatio = getEnemyProductionCostRatio(unitType);
  return 280 + Math.max(0, sameTypeQueued - 1) * 70 + (1 - costRatio) * 45;
}

function getEnemyLateReaperProductionBias(state: GameState, unitType: UnitType): number {
  if (state.difficulty !== "Hard" || unitType !== "Reaper" || state.day < 45) {
    return 0;
  }

  const reaperStock = getEnemyProductionHardLimitCount(state, "Reaper");
  const ramp = Math.min(1.35, 1 + (state.day - 45) / 30);
  const saturation = 1 / (1 + Math.max(0, reaperStock - 1) * 0.45);
  return 220 * ramp * saturation;
}

function isEnemyBasicGroundProductionUnit(unitType: UnitType): boolean {
  const definition = getUnitDefinition(unitType);
  return definition.domain === "Ground" && definition.producedBy.some((building) => building === "Barracks" || building === "Tank Factory");
}

function getEnemyProductionDayObsolescencePenalty(state: GameState, unitType: UnitType): number {
  if (!isEnemyBasicGroundProductionUnit(unitType)) {
    return 0;
  }

  const definition = getUnitDefinition(unitType);
  const costRatio = getEnemyProductionCostRatio(unitType);
  const advancedRatio = getEnemyProductionAdvancedRatio(state, unitType);
  const cheapBasicWeight = 1 - Math.max(costRatio, advancedRatio);
  const dayPressure = Math.max(0, Math.min(1, (state.day - 8) / 18));
  const latePressure = Math.max(0, Math.min(1, (state.day - 20) / 10));
  const barracksPenalty = definition.producedBy.includes("Barracks") ? dayPressure * 430 + latePressure * 620 : 0;
  const tankFactoryPenalty = definition.producedBy.includes("Tank Factory") ? dayPressure * 340 + latePressure * 500 : 0;
  const cheapBasicPenalty = cheapBasicWeight * (dayPressure * 180 + latePressure * 260);

  return barracksPenalty + tankFactoryPenalty + cheapBasicPenalty;
}

function getEnemyProductionSaturationMaturity(state: GameState): number {
  if (state.day <= 8) {
    return 0.18;
  }

  return Math.max(0.18, Math.min(1, (state.day - 8) / 10));
}

function scoreEnemyProductionVariableFit(state: GameState, unitType: UnitType): number {
  const definition = getUnitDefinition(unitType);
  const cost = getProductionCost(unitType);
  const costRatio = getEnemyProductionCostRatio(unitType);
  const advancedRatio = getEnemyProductionAdvancedRatio(state, unitType);
  const basicRatio = 1 - advancedRatio;
  const dayPressure = Math.max(0, Math.min(1, (state.day - 6) / 24));
  const efficiencyPressure = Math.max(0, Math.min(1, (state.enemyEconomy.efficiencyLevel - 1) / 6));
  const nextTurnIncome = getEnemyNextTurnIncome(state);
  const incomePressure = Math.max(-1, Math.min(1, (nextTurnIncome - 5) / 8));
  const totalStock = getEnemyTotalProductionStockCount(state);
  const fieldedCount = getEnemyFieldedProductionCount(state);
  const saturationMaturity = getEnemyProductionSaturationMaturity(state);
  const stockPressure = Math.max(0, Math.min(1.35, (totalStock - 6) / 12));
  const fieldedPressure = Math.max(0, Math.min(1.5, (fieldedCount - 5) / 10));
  const unitStock = getEnemyProductionHardLimitCount(state, unitType);
  const unitLevel = state.enemyEconomy.unitLevels[unitType];

  const priceScore = costRatio * 22;
  const dayScore = (advancedRatio - 0.42) * dayPressure * 92 + (isSpecialUnit(unitType) ? dayPressure * 32 : 0);
  const efficiencyScore = (advancedRatio - 0.44) * efficiencyPressure * 78;
  const incomeScore = (advancedRatio - 0.5) * incomePressure * 70;
  const levelScore = Math.max(0, unitLevel - 1) * (12 + advancedRatio * 18);
  const totalStockPenalty = stockPressure * saturationMaturity * (38 + basicRatio * 112);
  const fieldedPenalty = fieldedPressure * saturationMaturity * (72 + basicRatio * 165 + (1 - costRatio) * 68);
  const unitStockPenalty = unitStock * (10 + basicRatio * 18 + Math.max(0, 14 - cost) * 0.65);
  const repetitionPenalty = getEnemyProductionRepetitionPenalty(state, unitType);
  const dayObsolescencePenalty = getEnemyProductionDayObsolescencePenalty(state, unitType);
  const earlyCaptureMaterialScore =
    definition.humanBased && state.day <= 8 && getKnownPlayerUnitsForEnemy(state).length === 0
      ? getEnemyCaptureNeed(state) * 24
      : 0;

  return priceScore + dayScore + efficiencyScore + incomeScore + levelScore + earlyCaptureMaterialScore - totalStockPenalty - fieldedPenalty - unitStockPenalty - repetitionPenalty - dayObsolescencePenalty;
}

function shouldEvaluateEnemyProductionCandidate(
  state: GameState,
  unitType: UnitType,
  context: EnemyProductionCandidateContext
): boolean {
  const baseThreat = getEnemyBaseThreat(state);
  const urgentDefense = Boolean(baseThreat && canUnitTargetUnit(unitType, baseThreat.type));
  const timing = estimateEnemyProductionTiming(state, unitType);
  const wouldArriveObsolete = state.difficulty === "Hard" && isEnemyProductionObsoletedByQueuedUpgrade(state, unitType, timing);
  const endgameReaperDoctrine =
    state.difficulty === "Hard" &&
    unitType === "Reaper" &&
    ownerControlsBothGates(state, "Enemy") &&
    (context.phase === "BothGatesOwned" || context.phase === "BaseAssault" || context.phase === "BaseHold");
  const firstReaperDoctrine = unitType === "Reaper" && shouldEnemyPrioritizeFirstReaperProduction(state);
  const reaperSurvivalAcceptable = unitType !== "Reaper" || isEnemyReaperProductionSurvivalAcceptable(state, context.assessment);
  const playbook = getEnemyStrategyPlaybook(context.assessment);
  const reaperRushNonDelayer =
    playbook.delayObjectiveClockOnly &&
    unitType !== "Reaper" &&
    !isEnemyReaperTechRushDelayProductionUnit(state, unitType, context.assessment) &&
    !urgentDefense;

  return !wouldArriveObsolete && (reaperSurvivalAcceptable || endgameReaperDoctrine) && !reaperRushNonDelayer;
}

function shouldEnemyPrioritizeFirstReaperProduction(state: GameState): boolean {
  const eliteUnit = getOwnerEliteUnit(state, "Enemy");
  return !isEnemyProductionHardCapped(state, eliteUnit) && isEnemyFirstReaperSpendBlocking(state) && canEnemyAffordProductionUnit(state, eliteUnit);
}

function isEnemyFirstReaperSpendBlocking(state: GameState): boolean {
  const eliteBuilding = getOwnerEliteBuilding(state, "Enemy");
  const eliteUnit = getOwnerEliteUnit(state, "Enemy");
  return (
    ownerHasBuilding(state, "Enemy", eliteBuilding) &&
    canOwnerProduceUnit(state, "Enemy", eliteUnit) &&
    getEnemyUnitPresence(state, eliteUnit) + state.enemyEconomy.productionQueue.filter((job) => job.unitType === eliteUnit).length <= 0
  );
}

function scoreEnemyNoProductionChoice(state: GameState, plan: EnemyTurnPlan): number {
  const nextTurnIncome = getEnemyNextTurnIncome(state);
  const totalStock = getEnemyTotalProductionStockCount(state);
  const fieldedCount = getEnemyFieldedProductionCount(state);
  const saturationMaturity = getEnemyProductionSaturationMaturity(state);
  const stockPressure = Math.max(0, Math.min(1.5, (totalStock - 6) / 10));
  const fieldedPressure = Math.max(0, Math.min(1.7, (fieldedCount - 5) / 8));
  const queuePressure = Math.max(0, state.enemyEconomy.productionQueue.length - 1);
  const lowIncomeScore = Math.max(0, 6 - nextTurnIncome) * 30;
  const highIncomePenalty = Math.max(0, nextTurnIncome - 6) * 12;
  const stockScore =
    saturationMaturity * (stockPressure * 760 + fieldedPressure * 940 + Math.max(0, fieldedCount - 12) * 80) +
    queuePressure * 38;
  const lowLiquidityScore = Math.max(0, 42 - state.enemyEconomy.moneyPoundsBn) * 2.2;
  const baseThreat = getEnemyBaseThreat(state);
  const emergencyPenalty =
    (baseThreat && isActiveEnemyBaseThreat(state, baseThreat) ? 220 : 0) +
    (plan.objectiveImperatives.some((imperative) => imperative.terminal < 0) ? 180 : 0) +
    (isEnemyGateLockoutEconomyOverride(state, plan) ? 160 : 0);
  const openingBuildPenalty =
    plan.campaignPlan.phase === "OpeningGateRace" && state.day <= 12 && state.enemyEconomy.moneyPoundsBn >= 70 ? 620 : 0;

  return 24 + lowIncomeScore + stockScore + lowLiquidityScore - highIncomePenalty - emergencyPenalty - openingBuildPenalty;
}

function getEnemyPhaseEconomyProductionPriority(state: GameState, plan: EnemyTurnPlan, unitType: UnitType): number {
  if (state.difficulty !== "Hard") {
    return 0;
  }

  const definition = getUnitDefinition(unitType);
  const phase = plan.campaignPlan.phase;
  const packagePlan = plan.campaignPlan.baseAssaultPackage;
  const baseThreat = getEnemyBaseThreat(state);
  const activeBaseEmergency = isActiveEnemyBaseThreat(state, baseThreat) || phase === "BaseDefenseEmergency";
  const preBaseThreat = phase === "GateLockoutCombat" ? chooseEnemyPreBaseEmergencyThreat(state, plan.playerIntel, unitType) : undefined;
  if (activeBaseEmergency) {
    if (baseThreat && canUnitTargetUnit(unitType, baseThreat.type)) {
      const speedBonus = Math.max(0, 7 - getProductionDays(unitType)) * 18;
      return 230 + baseThreat.score * 0.55 + speedBonus;
    }
    return definition.humanBased && unitType !== "Ghost" && unitType !== "Operator" ? -120 : -180;
  }

  const missingBaseCapturer = ownerControlsBothGates(state, "Enemy") && !packagePlan.capturerId;
  const missingBaseBackup = ownerControlsBothGates(state, "Enemy") && !packagePlan.backupCapturerId;
  const missingBaseScout = ownerControlsBothGates(state, "Enemy") && !packagePlan.scoutId;
  const missingBaseEscort = ownerControlsBothGates(state, "Enemy") && packagePlan.blockerEscortIds.length < 1;
  const missingBaseClearer = ownerControlsBothGates(state, "Enemy") && packagePlan.damageDealerIds.length < 1;
  const baseBlocker = getPlayerBaseTileBlocker(state) ?? getPlayerBaseAreaDefender(state);
  const enemyCapturerStock = ENEMY_CAPTURE_UNIT_TYPES.reduce(
    (total, candidate) =>
      total +
      getOwnerUnits(state, "Enemy").filter((unit) => unit.type === candidate && unit.health > 0).length +
      (state.enemyEconomy.inventory[candidate] ?? 0) +
      state.enemyEconomy.productionQueue.filter((job) => job.unitType === candidate).length,
    0
  );
  const missingOpeningCapturer = phase === "OpeningGateRace" && enemyCapturerStock <= 0;
  const gateContestedOrOneOwned = phase === "OneGateOwned" || phase === "GateLockoutCombat" || phase === "Recovery" || (state.gates ?? []).some((gate) => gate.occupation.Player > 0 || gate.occupation.Enemy > 0);
  const visibleGateCapturer = plan.playerIntel.some((intel) =>
    getUnitDefinition(intel.unit.type).humanBased &&
    (state.gates ?? []).some((gate) => gate.owner === "Enemy" && hexDistance(intel.predictedCoord, gate.coord) <= 5)
  );
  const needsFirstReaper = shouldEnemyPrioritizeFirstReaperProduction(state);
  const firstReaperBonus = needsFirstReaper && unitType === "Reaper" ? 2_700 : 0;
  const firstReaperPenalty = needsFirstReaper && unitType !== "Reaper" ? 1_600 : 0;

  switch (phase) {
    case "OpeningGateRace":
      return (
        firstReaperBonus -
        firstReaperPenalty +
        (missingOpeningCapturer && definition.humanBased ? (plan.playerIntel.length === 0 ? 1_200 : 360) : 0) +
        (definition.humanBased ? (unitType === "Infantry" ? 92 : 126) : 0) +
        (unitType === "Tank" || unitType === "IFV" ? 112 : 0) +
        (unitType === "Attack Heli" || unitType === "IFV" || unitType === "Ghost" ? 58 : 0) -
        (unitType === "Bomber" || unitType === "Jet" || unitType === "Artillery" ? 38 : 0)
      );
    case "OneGateOwned":
    case "GateLockoutCombat":
    case "Recovery":
      if (phase === "GateLockoutCombat") {
        const cappedCapturerPenalty = isEnemyGateLockoutCappedCapturerProduction(state, plan, unitType) ? 260 : 0;
        const preBaseEmergencyBonus =
          preBaseThreat && isEnemyGateLockoutDirectCombatProductionUnit(unitType)
            ? 210 + preBaseThreat.score * 0.42 + Math.max(0, 7 - getProductionDays(unitType)) * 14
            : 0;
        const lockoutAirCounterattackAdjustment = getEnemyGateLockoutAirCounterattackProductionAdjustment(state, plan, unitType);
        return (
          firstReaperBonus -
          firstReaperPenalty +
          preBaseEmergencyBonus +
          lockoutAirCounterattackAdjustment +
          (isEnemyGateLockoutDirectCombatProductionUnit(unitType) ? 260 : 0) +
          (unitType === "Tank" || unitType === "IFV" ? 160 : 0) +
          (unitType === "Artillery" || unitType === "Reaper" || unitType === "Bomber" || unitType === "Jet" ? 150 : 0) +
          (unitType === "Anti-Air" && plan.playerIntel.some((intel) => getUnitDefinition(intel.unit.type).domain === "Air") ? 130 : 0) +
          (unitType === "Ghost" || unitType === "Operator" ? 108 : 0) -
          (definition.humanBased && !isEnemyGateLockoutDirectCombatProductionUnit(unitType) ? 70 : 0) -
          cappedCapturerPenalty
        );
      }
      return (
        firstReaperBonus -
        firstReaperPenalty +
        (definition.humanBased ? unitType === "Infantry" ? 78 : 138 : 0) +
        (unitType === "Tank" || unitType === "IFV" ? 164 : 0) +
        (unitType === "Attack Heli" ? 94 : 0) +
        (unitType === "Artillery" || unitType === "Anti-Air" || unitType === "Reaper" || unitType === "Bomber" || unitType === "Jet" ? 112 : 0) +
        (visibleGateCapturer && canUnitTargetUnit(unitType, "Infantry") ? 86 : 0) +
        (gateContestedOrOneOwned && canUnitTargetUnit(unitType, "Ghost") ? 48 : 0) +
        (isHardCombatProductionUnit(unitType) ? 72 : 0)
      );
    case "BothGatesOwned":
    case "BaseAssault":
      {
        const endgameBonus = getEnemyEndgameProductionDoctrineBonus(unitType);
        const basicCombatFallback = isHardCombatProductionUnit(unitType) || unitType === "Infantry" || unitType === "IFV" || unitType === "Attack Heli" ? 72 : 0;
        const baseBlockerNonClearerPenalty = baseBlocker && !missingBaseCapturer && !canUnitTargetUnit(unitType, baseBlocker.type) ? 2_400 : 0;
        return (
          endgameBonus +
          firstReaperBonus +
          basicCombatFallback +
          (definition.humanBased ? (unitType === "Ghost" ? 160 : unitType === "Operator" ? 132 : missingBaseCapturer || missingBaseBackup ? 112 : 48) : 0) +
          (missingBaseScout && isReconUnit(unitType) ? 82 : 0) +
          (missingBaseEscort && (unitType === "Tank" || unitType === "IFV" || unitType === "Reaper") ? 106 : 0) +
          (missingBaseClearer && (unitType === "Tank" || unitType === "Artillery" || unitType === "Reaper" || unitType === "Bomber") ? 128 : 0) +
          (baseBlocker && canUnitTargetUnit(unitType, baseBlocker.type) ? 98 : 0) +
          (baseBlocker && !definition.humanBased && canUnitTargetUnit(unitType, baseBlocker.type) ? 560 : 0) +
          (unitType === "Tank" || unitType === "Artillery" || unitType === "Reaper" ? 58 : 0) -
          baseBlockerNonClearerPenalty -
          (baseBlockerNonClearerPenalty ? 0 : firstReaperPenalty)
        );
      }
    case "BaseHold":
      return (
        firstReaperBonus -
        firstReaperPenalty +
        getEnemyEndgameProductionDoctrineBonus(unitType) * 0.55 +
        (definition.humanBased ? (unitType === "Ghost" || unitType === "Operator" ? 122 : 82) : 0) +
        (unitType === "Tank" || unitType === "IFV" || unitType === "Reaper" ? 112 : 0) +
        (unitType === "Artillery" ? 64 : 0) +
        (plan.playerIntel.some((intel) => canUnitTargetUnit(unitType, intel.unit.type) && hexDistance(intel.predictedCoord, state.bases.Player) <= 6) ? 92 : 0)
      );
  }
}

function getEnemyHeavyArmorProductionPriorityBonus(state: GameState, unitType: UnitType, plan: EnemyTurnPlan): number {
  if (unitType !== "Tank" || state.enemyEconomy.moneyPoundsBn < getProductionCost("Tank")) {
    return 0;
  }

  const ifvPresence = getEnemyUnitPresence(state, "IFV");
  const tankPresence = getEnemyUnitPresence(state, "Tank");
  const playerArmorPressure = plan.playerIntel
    .filter((intel) => intel.unit.type === "Tank" || intel.unit.type === "IFV" || getUnitDefinition(intel.unit.type).humanBased)
    .reduce((score, intel) => score + getUnitInstanceValue(state, intel.unit) * intel.confidence, 0);
  const forwardPressure = getPlayerForwardPressure(state);
  const tankShortfall = Math.max(0, 3 - tankPresence);
  return (
    110 +
    tankShortfall * 44 +
    (ifvPresence >= 2.5 ? 135 + Math.max(0, ifvPresence - 2.5) * 48 : 0) +
    Math.min(140, playerArmorPressure * 0.22) +
    Math.min(120, forwardPressure * 0.28) +
    (plan.campaignPlan.phase === "OpeningGateRace" || plan.campaignPlan.phase === "OneGateOwned" ? 42 : 0)
  );
}

function getEnemyIfvProductionSaturationPenalty(state: GameState, unitType: UnitType): number {
  if (unitType !== "IFV" || state.enemyEconomy.moneyPoundsBn < getProductionCost("Tank")) {
    return 0;
  }

  const ifvPresence = getEnemyUnitPresence(state, "IFV");
  const tankPresence = getEnemyUnitPresence(state, "Tank");
  if (ifvPresence < 2.5 || tankPresence >= ifvPresence) {
    return 0;
  }

  return 120 + Math.max(0, ifvPresence - 2.5) * 70 + Math.max(0, 2.5 - tankPresence) * 42;
}

function getEnemyEndgameProductionDoctrineBonus(unitType: UnitType): number {
  switch (unitType) {
    case "Reaper":
      return 420;
    case "Ghost":
      return 360;
    case "Operator":
      return 320;
    case "Bomber":
      return 280;
    case "Jet":
      return 210;
    case "Tank":
    case "Artillery":
    case "Anti-Air":
    case "IFV":
    case "Attack Heli":
      return 120;
    case "Infantry":
      return 64;
    default:
      return 0;
  }
}

function getEnemyPlannerResearchCandidates(
  state: GameState,
  plan: EnemyTurnPlan,
  context = createEnemyResearchFeasibilityContext(state)
): EnemyEconomyPlanItem[] {
  return getEnemyResearchOptions(state)
    .filter((option) => isEnemyResearchOptionFeasible(state, option, context))
    .filter((option) => isEnemyGateLockoutResearchCandidatePermitted(state, plan, option))
    .map((option) => {
      const timing = estimateEnemyResearchTiming(state, option);
      const strategic = isCriticalEnemyTechResearchOption(state, option) || option.type === "UnlockSpecialServices" || option.type === "UnlockDroneFactory";
      const upgradePressure = state.day >= 18 || plan.playerIntel.length > 0 || plan.strategicSnapshot.player.totalValue > 0;
      const upgradeProfile = option.type === "UnitUpgrade" && option.unitType ? getEnemyUnitUpgradeUseProfile(state, option.unitType) : undefined;
      const upgradeUse =
        upgradePressure && option.type === "UnitUpgrade" && option.unitType && upgradeProfile
          ? (upgradeProfile.fielded * 12 + upgradeProfile.committedUse * 6) * getEnemyUnitUpgradeQualityMultiplier(state, option.unitType)
          : 0;
      const criticalTechOpen = hasAvailableEnemyCriticalTechResearch(state);
      const committedUpgradeBonus =
        state.difficulty === "Hard" &&
        state.day >= 18 &&
        !criticalTechOpen &&
        option.type === "UnitUpgrade" &&
        option.unitType &&
        (upgradeProfile?.committedUse ?? 0) > 0
          ? 45
          : 0;
      const earlyThroughput =
        state.day <= 16 && isEconomyOrThroughputResearch(option.type)
          ? 90
          : 0;
      const nextTurnIncome = getEnemyNextTurnIncome(state);
      const efficiencyStarved = option.type === "Efficiency" && isEnemyEfficiencyStarvedForResearch(state);
      const efficiencyThroughput =
        option.type === "Efficiency"
          ? (state.day <= 24 ? 120 : 60) +
            Math.max(0, 4 - state.enemyEconomy.efficiencyLevel) * 70 +
            (efficiencyStarved
              ? 260 + Math.max(0, 9 - nextTurnIncome) * 52 + Math.max(0, 95 - state.enemyEconomy.moneyPoundsBn) * 2
              : Math.max(0, 6 - nextTurnIncome) * 14)
          : 0;
      const variableFit = scoreEnemyResearchVariableFit(state, option);
      const delayPenalty = strategic ? timing.waitDays * 8 : timing.waitDays * 18 + Math.max(0, timing.totalDays - 7) * 4;
      const phasePriority = getEnemyPhaseEconomyResearchPriority(state, plan, option);
      const priority = option.score + variableFit + upgradeUse + committedUpgradeBonus + earlyThroughput + efficiencyThroughput + phasePriority - delayPenalty + (strategic ? 80 : 0);
      return {
        kind: "research" as const,
        researchType: option.type,
        researchUnitType: option.unitType,
        cost: option.cost,
        score: option.score,
        priority,
        reason: `research score ${Math.round(option.score)}, variable ${Math.round(variableFit)}, phase ${Math.round(phasePriority)}, completion d${timing.completeDay}`
      };
    });
}

function scoreEnemyResearchVariableFit(state: GameState, option: EnemyResearchOption): number {
  const economy = state.enemyEconomy;
  const day = state.day;
  const researchSpeed = economy.researchSpeedLevel;
  const researchCapacity = economy.researchCapacityLevel;
  const totalDone = getEnemyCompletedResearchCount(state);
  const level = getEnemyResearchEvaluationLevel(state, option);
  const cost = option.cost;
  const basicness = getEnemyResearchBasicness(option);
  const specialness = getEnemyResearchSpecialness(option);
  const speedAdvantage = Math.max(0, researchSpeed - 1);
  const capacityAdvantage = Math.max(0, researchCapacity - 1);
  const researchThroughput = speedAdvantage + capacityAdvantage;
  const dayPressure = Math.max(0, day - 6);
  const lowCost = Math.max(0, 18 - cost);
  const expensive = Math.max(0, cost - 10);
  const lowLevel = Math.max(0, 3 - level);
  const highLevel = Math.max(0, level - 2);

  const priceScore = cost * (4.8 + dayPressure * 0.72 + researchThroughput * 4.6 + highLevel * 2.8);
  const expensiveProgressionBonus = expensive * (dayPressure * 1.1 + researchThroughput * 8 + totalDone * 2.8);
  const highLevelProgressionBonus = highLevel * (76 + dayPressure * 9 + researchThroughput * 58 + totalDone * 18);
  const specialProgressionBonus = specialness * (210 + dayPressure * 20 + researchThroughput * 95 + totalDone * 24);
  const cheapPenalty = lowCost * (5 + dayPressure * 1.2 + researchThroughput * 7 + totalDone * 3.2);
  const basicObsolescencePenalty = basicness * (dayPressure * 18 + researchThroughput * 58 + totalDone * 42 + lowLevel * (48 + totalDone * 10));
  const unitUpgradePenalty =
    option.type === "UnitUpgrade"
      ? 680 + dayPressure * 10 + researchThroughput * 85 + totalDone * 28 + lowLevel * 90
      : 0;

  return (
    priceScore +
    expensiveProgressionBonus +
    highLevelProgressionBonus +
    specialProgressionBonus -
    cheapPenalty -
    basicObsolescencePenalty -
    unitUpgradePenalty
  );
}

function scoreEnemyNoResearchPriority(state: GameState, candidates: EnemyEconomyPlanItem[] = []): number {
  const totalDone = getEnemyCompletedResearchCount(state);
  const researchSpeed = state.enemyEconomy.researchSpeedLevel;
  const queuedPressure = Math.max(0, state.enemyEconomy.researchQueue.length - state.enemyEconomy.researchCapacityLevel + 1);
  const affordableCandidateCount = candidates.filter((item) => canEnemyAffordEconomyPlanItem(state, item)).length;
  return 52 + totalDone * 58 + Math.max(0, researchSpeed - 1) * 26 + Math.max(0, state.day - 18) * 5 + queuedPressure * 95 - affordableCandidateCount * 4;
}

function getEnemyCompletedResearchCount(state: GameState): number {
  const economy = state.enemyEconomy;
  const economyLevels =
    Math.max(0, economy.efficiencyLevel - 1) +
    Math.max(0, economy.productionCapacityLevel - 1) +
    Math.max(0, economy.researchCapacityLevel - 1) +
    Math.max(0, economy.productionSpeedLevel - 1) +
    Math.max(0, economy.researchSpeedLevel - 1);
  const unitLevels = ENEMY_UNIT_TYPES.reduce((total, unitType) => total + Math.max(0, economy.unitLevels[unitType] - 1), 0);
  const unlocks =
    (ownerHasBuilding(state, "Enemy", "Special Services") ? 1 : 0) +
    (ownerHasBuilding(state, "Enemy", "Drone Factory") ? 1 : 0) +
    (ownerHasBuilding(state, "Enemy", "The Room") ? 1 : 0);
  return economyLevels + unitLevels + unlocks;
}

function isEnemyEfficiencyStarvedForResearch(state: GameState): boolean {
  const economy = state.enemyEconomy;
  const nextTurnIncome = getEnemyNextTurnIncome(state);
  const otherEconomyMax = Math.max(
    economy.productionCapacityLevel,
    economy.researchCapacityLevel,
    economy.productionSpeedLevel,
    economy.researchSpeedLevel
  );
  const economyOutranEfficiency = otherEconomyMax > economy.efficiencyLevel;

  return (
    economy.efficiencyLevel <= 2 &&
    economyOutranEfficiency &&
    ((nextTurnIncome <= 8 && economy.moneyPoundsBn < 120) || economy.moneyPoundsBn < 75)
  );
}

function getEnemyResearchEvaluationLevel(state: GameState, option: EnemyResearchOption): number {
  if (option.type === "UnlockSpecialServices") {
    return 3;
  }
  if (option.type === "UnlockDroneFactory") {
    return 5;
  }
  if (option.type === "UnlockRoom") {
    return 6;
  }
  return getNextResearchStartLevel(state.enemyEconomy, option.type, option.unitType);
}

function getEnemyResearchBasicness(option: EnemyResearchOption): number {
  if (option.type === "UnitUpgrade") {
    return 1.55;
  }
  if (option.type === "ProductionCapacity" || option.type === "ResearchCapacity") {
    return 1.05;
  }
  if (option.type === "ProductionSpeed" || option.type === "ResearchSpeed") {
    return 0.9;
  }
  if (option.type === "Efficiency") {
    return 0.75;
  }
  if (option.type === "UnlockSpecialServices") {
    return 0.2;
  }
  return 0;
}

function getEnemyResearchSpecialness(option: EnemyResearchOption): number {
  if (option.type === "UnlockDroneFactory") {
    return 1.55;
  }
  if (option.type === "UnlockRoom") {
    return 1.7;
  }
  if (option.type === "UnlockSpecialServices") {
    return 1.05;
  }
  return 0;
}

function getEnemyPhaseEconomyResearchPriority(state: GameState, plan: EnemyTurnPlan, option: EnemyResearchOption): number {
  if (state.difficulty !== "Hard") {
    return 0;
  }
  if (plan.campaignPlan.phase === "GateLockoutCombat") {
    if (isEconomyOrThroughputResearch(option.type)) {
      return -680;
    }
    const lockoutRelevance = scoreEnemyGateLockoutResearchRelevance(state, plan, option);
    if (option.type === "UnitUpgrade" && option.unitType && isEnemyGateLockoutDirectCombatProductionUnit(option.unitType)) {
      return lockoutRelevance > 0 ? -80 + lockoutRelevance * 0.45 : -560;
    }
    if (option.type === "UnlockSpecialServices" || option.type === "UnlockDroneFactory") {
      return lockoutRelevance > 0 ? 35 + lockoutRelevance * 0.35 : -540;
    }
    return -520;
  }
  const playbook = plan.doctrine.strategyPlaybook;
  if (playbook.requiredBehaviors.includes("UnlockDroneFactory")) {
    if (option.type === "UnlockDroneFactory") {
      return 260 + plan.strategicSnapshot.forecast.reaperPipelineNeed * 0.45;
    }
    if (isEconomyOrThroughputResearch(option.type) && !ownerHasBuilding(state, "Enemy", "Drone Factory")) {
      return -120;
    }
  }
  if (playbook.requiredBehaviors.includes("ProduceAirCounters")) {
    if (option.type === "UnitUpgrade" && option.unitType && (option.unitType === "Anti-Air" || option.unitType === "Jet" || option.unitType === "Operator" || option.unitType === "Reaper")) {
      return 35;
    }
  }
  if (playbook.requiredBehaviors.includes("ProtectGateIncome") && isEconomyOrThroughputResearch(option.type)) {
    return 120;
  }
  if (plan.campaignPlan.phase === "BaseDefenseEmergency") {
    return isEconomyOrThroughputResearch(option.type)
      ? -260
      : option.type === "UnitUpgrade" && option.unitType && canUnitTargetUnit(option.unitType, getEnemyBaseThreat(state)?.type ?? "Infantry")
        ? 35
        : -120;
  }
  if (plan.campaignPlan.phase === "OpeningGateRace") {
    if (option.type === "UnlockSpecialServices") {
      return 80;
    }
    if (isEconomyOrThroughputResearch(option.type)) {
      return state.day <= 8 ? 18 : -45;
    }
  }
  if (plan.campaignPlan.phase === "OneGateOwned" || plan.campaignPlan.phase === "Recovery") {
    if (option.type === "UnlockSpecialServices" || option.type === "UnlockDroneFactory") {
      return 70;
    }
    if (option.type === "UnitUpgrade" && option.unitType && (getUnitDefinition(option.unitType).humanBased || option.unitType === "Tank" || option.unitType === "IFV")) {
      return 20;
    }
  }
  if (isEnemyBaseOperationPhase(plan.campaignPlan.phase)) {
    if (option.type === "UnlockSpecialServices" || option.type === "UnlockDroneFactory") {
      return 84;
    }
    if (option.type === "UnitUpgrade" && option.unitType && (option.unitType === "Ghost" || option.unitType === "Operator" || option.unitType === "Reaper" || option.unitType === "Tank" || option.unitType === "Artillery")) {
      return 26;
    }
    if (isEconomyOrThroughputResearch(option.type)) {
      return -58;
    }
  }
  return 0;
}

function hasAvailableEnemyCriticalTechResearch(state: GameState): boolean {
  return (
    canStartResearch(state, "Enemy", "UnlockSpecialServices", undefined) &&
    isCriticalEnemyTechResearchOption(state, { type: "UnlockSpecialServices", cost: getResearchCost("UnlockSpecialServices", undefined, state.enemyEconomy, undefined), score: 1 })
  ) || (
    canStartResearch(state, "Enemy", "UnlockDroneFactory", undefined) &&
    isCriticalEnemyTechResearchOption(state, { type: "UnlockDroneFactory", cost: getResearchCost("UnlockDroneFactory", undefined, state.enemyEconomy, undefined), score: 1 })
  );
}

function getEnemyPlannerFieldUpgradeCandidates(state: GameState, plan: EnemyTurnPlan): EnemyEconomyPlanItem[] {
  return getOwnerUnits(state, "Enemy")
    .map((unit): EnemyEconomyPlanItem | undefined => {
      const level = getUnitInstanceLevel(state, unit);
      const targetLevel = level + 1;
      if (targetLevel > state.enemyEconomy.unitLevels[unit.type]) {
        return undefined;
      }

      const currency = chooseEnemyFieldUpgradeCurrency(state, unit.type, level);
      if (!currency) {
        return undefined;
      }

      const cost = currency === "gain" ? getFieldUnitUpgradeGainCost(unit.type, level) : getFieldUnitUpgradeCost(unit.type, level);
      const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
      const forcedObjective = plan.objectiveImperatives.some((imperative) => imperative.unitId === unit.id);
      const score =
        getUnitInstanceValue(state, unit) * 0.18 +
        (isSpecialUnit(unit.type) ? 32 : 0) +
        (mission === "DefendBase" || mission === "CaptureBase" ? 22 : 0) +
        (forcedObjective ? 80 : 0);
      return {
        kind: "fieldUpgrade" as const,
        unitId: unit.id,
        unitType: unit.type,
        currency,
        cost,
        score,
        priority: score - cost * 2.4,
        reason: `${unit.type} L${level} field upgrade with ${currency}`
      };
    })
    .filter((item): item is EnemyEconomyPlanItem => Boolean(item))
    .filter((item) => item.priority >= 40);
}

function chooseEnemyFieldUpgradeCurrency(state: GameState, unitType: UnitType, fromLevel: number): PurchaseCurrency | undefined {
  const fundsCost = getFieldUnitUpgradeCost(unitType, fromLevel);
  if (state.enemyEconomy.moneyPoundsBn >= fundsCost) {
    return "funds";
  }

  const gainCost = getFieldUnitUpgradeGainCost(unitType, fromLevel);
  return state.enemyEconomy.gainPoints >= gainCost ? "gain" : undefined;
}

function executeEnemyEconomyPlan(state: GameState, plan: EnemyTurnPlan): void {
  executeEnemyEconomyCancellations(state, plan);
  executeEnemyGainFinishPlan(state);
  executeEnemyFieldUpgradePlan(state, plan);
  executeEnemyProductionPlan(state, plan);
  executeEnemyResearchPlan(state, plan);
  executeEnemyGainFinishPlan(state);
}

function executeEnemyEconomyCancellations(state: GameState, plan: EnemyTurnPlan): void {
  plan.economyPlan.cancellations = [];
}

function executeEnemyFieldUpgradePlan(state: GameState, plan: EnemyTurnPlan): void {
  executeEnemyEconomyPurchasesByKind(state, plan, "fieldUpgrade");
}

function executeEnemyProductionPlan(state: GameState, plan: EnemyTurnPlan): void {
  executeEnemyEconomyPurchasesByKind(state, plan, "production");
}

function executeEnemyResearchPlan(state: GameState, plan: EnemyTurnPlan): void {
  executeEnemyEconomyPurchasesByKind(state, plan, "research");
}

function executeEnemyGainFinishPlan(state: GameState): void {
  while (state.enemyEconomy.gainPoints > 0) {
    const options = [
      ...state.enemyEconomy.productionQueue.map((job) => ({
        kind: "production" as const,
        jobId: job.id,
        canFinishWithGain: canUseGainForProduction(job.unitType),
        completeDay: job.availableDay,
        cost: getProductionFinishGainCost(job, state.day)
      })),
      ...state.enemyEconomy.researchQueue.map((job) => ({
        kind: "research" as const,
        jobId: job.id,
        canFinishWithGain: canUseGainForResearch(job.type),
        completeDay: job.completeDay,
        cost: getResearchFinishGainCost(job, state.enemyEconomy, state.day)
      }))
    ]
      .filter((option) => option.canFinishWithGain && option.cost > 0 && option.cost <= state.enemyEconomy.gainPoints)
      .sort((first, second) => first.cost - second.cost || first.completeDay - second.completeDay);

    if (!options.length) {
      return;
    }

    let finished = false;
    for (const option of options) {
      finished = option.kind === "production"
        ? finishProduction(state, "Enemy", option.jobId)
        : finishResearch(state, "Enemy", option.jobId);
      if (finished) {
        break;
      }
    }

    if (!finished) {
      return;
    }
  }
}

function executeEnemyEconomyPurchasesByKind(state: GameState, plan: EnemyTurnPlan, kind: EnemyEconomyPlanItem["kind"]): void {
  for (const purchase of plan.economyPlan.purchases.filter((item) => item.kind === kind)) {
    executeEnemyEconomyPurchase(state, purchase);
  }
}

function executeEnemyEconomyPurchase(state: GameState, item: EnemyEconomyPlanItem): boolean {
  if (item.kind === "production" && item.unitType) {
    if (canUseGainForProduction(item.unitType) && state.enemyEconomy.gainPoints >= getEnemyProductionGainCost(state, item.unitType)) {
      return instantProduction(state, "Enemy", item.unitType);
    }

    return startProduction(state, "Enemy", item.unitType);
  }
  if (item.kind === "research" && item.researchType) {
    const startLevel = getNextResearchStartLevel(state.enemyEconomy, item.researchType, item.researchUnitType);
    if (canEnemySpendGainOnResearchLine(state, item.researchType, item.researchUnitType, startLevel)) {
      return instantResearch(state, "Enemy", item.researchType, item.researchUnitType);
    }

    return startResearch(state, "Enemy", item.researchType, item.researchUnitType);
  }
  if (item.kind === "fieldUpgrade" && item.unitId) {
    const unit = state.units.find((candidate) => candidate.id === item.unitId && candidate.owner === "Enemy");
    return Boolean(unit && upgradeFieldUnit(state, unit, item.currency ?? "funds"));
  }
  return false;
}

function planEnemyPlacement(state: GameState, plan: EnemyTurnPlan): GameState {
  const simulated = cloneState(state);
  const placements: EnemyPlacementPlanItem[] = [];
  let placementsLeft = getEnemyPlacementLimit(state);
  placementsLeft = planEnemyCapturedGateDefensePlacements(simulated, plan, placements, placementsLeft);
  const placementOrder = ENEMY_UNIT_TYPES
    .filter((unitType) => simulated.enemyEconomy.inventory[unitType] > 0)
    .map((unitType) => ({
      unitType,
      score: scoreEnemyPlacementOrderPriority(simulated, unitType, plan)
    }))
    .sort((first, second) => second.score - first.score)
    .map((entry) => entry.unitType);

  for (const unitType of placementOrder) {
    while (simulated.enemyEconomy.inventory[unitType] > 0 && placementsLeft > 0) {
      const coord = findEnemyPlacementCoord(simulated, unitType, plan);
      if (!coord) {
        break;
      }
      placements.push({
        unitType,
        coord,
        score: scoreEnemyPlannerPlacement(simulated, unitType, coord, plan)
      });
      placeUnitWithoutFog(simulated, "Enemy", unitType, coord, "preserve");
      invalidateEnemyEvaluationCache();
      placementsLeft -= 1;
    }
  }
  if (placements.length) {
    synchronizeEnemyFogInPlace(simulated);
    invalidateEnemyEvaluationCache();
  }
  plan.placementPlan = placements;
  return simulated;
}

function planEnemyCapturedGateDefensePlacements(
  state: GameState,
  plan: EnemyTurnPlan,
  placements: EnemyPlacementPlanItem[],
  placementsLeft: number
): number {
  if (placementsLeft <= 0) {
    return placementsLeft;
  }

  for (const gate of getEnemyCapturedGateDefensePlacementGates(state, plan)) {
    let placedForGate = 0;
    const desiredPlacements = getEnemyCapturedGateDefensePlacementCount(state, gate, placementsLeft);
    while (placedForGate < desiredPlacements && placementsLeft > 0) {
      const candidate = chooseEnemyCapturedGateDefensePlacement(state, gate, plan);
      if (!candidate) {
        break;
      }
      placements.push(candidate);
      placeUnitWithoutFog(state, "Enemy", candidate.unitType, candidate.coord, "preserve");
      invalidateEnemyEvaluationCache();
      placementsLeft -= 1;
      placedForGate += 1;
    }
  }

  return placementsLeft;
}

function getEnemyCapturedGateDefensePlacementGates(state: GameState, plan: EnemyTurnPlan): GateState[] {
  return [...(state.gates ?? [])]
    .filter((gate) => gate.owner === "Enemy")
    .filter((gate) => getEnemyCapturedGateDefensePlacementCount(state, gate, ENEMY_CAPTURED_GATE_DEFENSE_MAX_PLACEMENTS) > 0)
    .sort((first, second) => scoreEnemyCapturedGateDefensePlacementNeed(state, second, plan) - scoreEnemyCapturedGateDefensePlacementNeed(state, first, plan) || first.id.localeCompare(second.id));
}

function getEnemyCapturedGateDefensePlacementCount(state: GameState, gate: GateState, placementsLeft: number): number {
  const availableCaptureUnits = ENEMY_CAPTURE_UNIT_TYPES.reduce((total, unitType) => total + Math.max(0, Math.floor(state.enemyEconomy.inventory[unitType] ?? 0)), 0);
  if (placementsLeft <= 0 || availableCaptureUnits <= 0 || getEnemyLocalGateCaptureDefenderCount(state, gate) >= ENEMY_CAPTURED_GATE_DEFENSE_MAX_PLACEMENTS) {
    return 0;
  }

  const nearbyPlayerCapturers = getPlayerIntelForEnemy(state).filter((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, gate.coord) <= 7).length;
  const predictedPressure = getEnemyStrategicAssessment(state).predictedGatePressure[gate.id] ?? 0;
  const desired =
    gate.occupation.Player > 0 || nearbyPlayerCapturers >= 2 || predictedPressure >= 95
      ? ENEMY_CAPTURED_GATE_DEFENSE_MAX_PLACEMENTS
      : nearbyPlayerCapturers > 0 || predictedPressure >= 45
        ? 2
        : ENEMY_CAPTURED_GATE_DEFENSE_MIN_PLACEMENTS;
  return Math.min(desired, ENEMY_CAPTURED_GATE_DEFENSE_MAX_PLACEMENTS, availableCaptureUnits, placementsLeft);
}

function getEnemyLocalGateCaptureDefenderCount(state: GameState, gate: GateState): number {
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => getUnitDefinition(unit.type).humanBased)
    .filter((unit) => hexDistance(unit.coord, gate.coord) <= 4)
    .length;
}

function chooseEnemyCapturedGateDefensePlacement(state: GameState, gate: GateState, plan: EnemyTurnPlan): EnemyPlacementPlanItem | undefined {
  return ENEMY_CAPTURE_UNIT_TYPES
    .filter((unitType) => state.enemyEconomy.inventory[unitType] > 0)
    .flatMap((unitType) =>
      getLegalPlacementCoords(state, "Enemy", unitType).map((coord) => ({
        unitType,
        coord,
        score:
          scoreEnemyCapturedGateDefensePlacementCoord(state, unitType, coord, gate, plan) +
          scoreEnemyPlacementUnitType(state, unitType) * 0.25
      }))
    )
    .sort((first, second) => second.score - first.score || first.unitType.localeCompare(second.unitType) || hexId(first.coord).localeCompare(hexId(second.coord)))[0];
}

function scoreEnemyCapturedGateDefensePlacementNeed(state: GameState, gate: GateState, plan: EnemyTurnPlan): number {
  const nearbyPlayerCapturers = getPlayerIntelForEnemy(state).filter((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, gate.coord) <= 7).length;
  const predictedPressure = getEnemyStrategicAssessment(state).predictedGatePressure[gate.id] ?? 0;
  return (
    (gate.id === plan.campaignPlan.mainEffortGateId ? 120 : 0) +
    gate.occupation.Player * 220 +
    nearbyPlayerCapturers * 90 +
    predictedPressure -
    getEnemyLocalGateCaptureDefenderCount(state, gate) * 70
  );
}

function scoreEnemyCapturedGateDefensePlacementCoord(
  state: GameState,
  unitType: UnitType,
  coord: UnitInstance["coord"],
  gate: GateState,
  plan: EnemyTurnPlan
): number {
  const route = estimateEnemyPlacementObjectiveRoute(state, unitType, coord, gate.coord);
  const laneDistance = Math.abs(coord.q - getOpeningGateTopLaneQ(state, gate));
  const localSupport = getOwnerUnits(state, "Enemy").filter((unit) => hexDistance(unit.coord, coord) <= 3).length;
  const supplyDeploymentAnchor = getEnemySupplyPlacementAnchor(state, coord, unitType);
  const supplyDeployment = supplyDeploymentAnchor ? 260 + (isEnemyCommandHelicopter(supplyDeploymentAnchor.type) && sameHex(coord, gate.coord) ? 520 : 0) : 0;
  const dangerPenalty = estimatePlayerDangerAtPlanner(state, createHypotheticalEnemyUnit(state, unitType, coord), coord, plan) > 0 ? 120 : 0;
  return (
    1_800 +
    supplyDeployment +
    Math.max(0, 22 - route.routeDistance) * 34 +
    Math.max(0, 16 - laneDistance) * 42 +
    localSupport * 8 -
    Math.max(0, route.routeDistance - route.geometricDistance) * 34 -
    (route.reachable ? 0 : 260) -
    dangerPenalty
  );
}

function getEnemyPlacementLimit(state: GameState): number {
  const defaultLimit = getAiDifficultyConfig(state).maxPlacementsPerTurn;
  const availableInventory = Object.values(state.enemyEconomy.inventory).reduce((total, count) => total + Math.max(0, Math.floor(count ?? 0)), 0);
  return Math.max(defaultLimit, availableInventory);
}

function scoreEnemyPlacementOrderPriority(state: GameState, unitType: UnitType, plan?: EnemyTurnPlan): number {
  const openingCenterSupportPriority =
    isHardOpeningInitialDeployment(state) &&
    (unitType === "Artillery" || unitType === "Anti-Air" || unitType === "Supply Truck")
      ? 12_000
      : 0;
  const openingInfantryPriority =
    state.difficulty === "Hard" &&
    state.day === 1 &&
    unitType === "Infantry" &&
    isHardOpeningGateRace(state)
      ? 10_000
      : 0;
  const definition = getUnitDefinition(unitType);
  const phase = plan?.campaignPlan.phase;
  if (phase === "GateLockoutCombat") {
    return scoreEnemyPlacementUnitType(state, unitType) + openingCenterSupportPriority + openingInfantryPriority + getEnemyGateLockoutPlacementOrderPriority(unitType);
  }
  const campaignPriority =
    definition.humanBased && isEnemyGateContinuityPhase(phase)
      ? 420
      : (unitType === "Tank" || unitType === "IFV") && (phase === "OpeningGateRace" || phase === "OneGateOwned")
        ? 230
        : (unitType === "Anti-Air" || unitType === "Artillery") && (phase === "BothGatesOwned" || phase === "BaseAssault" || phase === "BaseDefenseEmergency")
          ? 180
          : 0;
  return scoreEnemyPlacementUnitType(state, unitType) + openingCenterSupportPriority + openingInfantryPriority + campaignPriority;
}

function getEnemyGateLockoutPlacementOrderPriority(unitType: UnitType): number {
  if (isEnemyGateLockoutPrimaryDamageDealerPlacementUnit(unitType)) {
    return 1_200;
  }
  if (unitType === "Anti-Air" || isReconUnit(unitType)) {
    return 850;
  }
  if (isEnemyGateLockoutReserveCapturer(unitType)) {
    return -260;
  }
  return 0;
}

function isEnemyGateLockoutPrimaryDamageDealerPlacementUnit(unitType: UnitType): boolean {
  return unitType === "Tank" || unitType === "IFV" || unitType === "Artillery" || unitType === "Bomber" || unitType === "Reaper" || unitType === "Ghost" || unitType === "Operator" || unitType === "Jet";
}

function scoreEnemyPlannerPlacement(state: GameState, unitType: UnitType, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  const baseThreat = getEnemyBaseThreat(state);
  const definition = getUnitDefinition(unitType);
  const openingGate = chooseOpeningGatePlacementTarget(state, unitType, plan);
  const lockoutTarget = chooseEnemyGateLockoutPlacementTarget(state, unitType, plan);
  const target = lockoutTarget
    ? lockoutTarget
    : definition.humanBased
    ? chooseEnemyPlannerCaptureObjectiveForPlacement(state, coord, plan)
    : openingGate && isPatrolCapableUnit(unitType)
      ? openingGate.coord
      : chooseEnemyDeploymentTarget(state, unitType, plan);
  const route = estimateEnemyPlacementObjectiveRoute(state, unitType, coord, target);
  const baseDefense = baseThreat && canUnitTargetUnit(unitType, baseThreat.type)
    ? Math.max(0, getEnemyBaseResponseRadius(state) + 2 - hexDistance(coord, baseThreat.coord)) * 22
    : 0;
  const gateOpening =
    (definition.humanBased || isPatrolCapableUnit(unitType)) && state.day <= 12
      ? (state.gates ?? []).reduce((score, gate) => score + Math.max(0, 16 - Math.abs(coord.q - gate.coord.q)) * 5, 0)
      : 0;
  const support = getOwnerUnits(state, "Enemy").filter((unit) => hexDistance(unit.coord, coord) <= 3).length * 3;
  const lockoutPlacement = scoreEnemyGateLockoutPlacementCoord(state, unitType, coord, plan);
  const routePenalty = route.reachable ? 0 : 180;
  return scoreEnemyPlacementUnitType(state, unitType) - route.routeDistance * 7 - routePenalty + baseDefense + gateOpening + support + lockoutPlacement + scoreEnemyHighAltitudeLayerPlacement(state, unitType, coord, plan);
}

function chooseEnemyGateLockoutPlacementTarget(state: GameState, unitType: UnitType, plan?: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (state.difficulty !== "Hard" || plan?.campaignPlan.phase !== "GateLockoutCombat") {
    return undefined;
  }
  const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
  if (!gate) {
    return undefined;
  }
  const laneQ = getOpeningGateTopLaneQ(state, gate);
  const backRow = state.bases.Enemy.r;
  const supportOffset =
    unitType === "Artillery" || unitType === "Anti-Air" || needsReconSupport(unitType)
      ? 1
      : isEnemyGateLockoutReserveCapturer(unitType)
        ? 3
        : 0;
  const q = Math.max(0, Math.min(state.map.width - 1, laneQ + (gate.id === "West" ? supportOffset : -supportOffset)));
  return { q, r: backRow };
}

function scoreEnemyGateLockoutPlacementCoord(state: GameState, unitType: UnitType, coord: UnitInstance["coord"], plan?: EnemyTurnPlan): number {
  const target = chooseEnemyGateLockoutPlacementTarget(state, unitType, plan);
  if (!target) {
    return 0;
  }

  const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
  const laneDistance = Math.abs(coord.q - target.q);
  const targetDistance = hexDistance(coord, target);
  const gateLaneDistance = gate ? Math.abs(coord.q - getOpeningGateTopLaneQ(state, gate)) : laneDistance;
  const roleWeight =
    isEnemyGateLockoutPrimaryDamageDealerPlacementUnit(unitType) ? 46 :
      unitType === "Anti-Air" || isReconUnit(unitType) ? 34 :
        isEnemyGateLockoutReserveCapturer(unitType) ? 18 :
          14;
  const orderBias =
    isEnemyGateLockoutPrimaryDamageDealerPlacementUnit(unitType) ? 260 :
      unitType === "Anti-Air" || isReconUnit(unitType) ? 150 :
        isEnemyGateLockoutReserveCapturer(unitType) ? -130 :
          0;
  const laneScore = Math.max(0, 18 - laneDistance) * roleWeight;
  const gateLaneScore = Math.max(0, 16 - gateLaneDistance) * Math.max(8, roleWeight * 0.35);
  const wrongLanePenalty = laneDistance > 8 ? 220 : laneDistance > 5 ? 90 : 0;
  const counterattackSupport =
    unitType === "Artillery" || unitType === "Anti-Air" || needsReconSupport(unitType)
      ? (gate ? getGateSideSightStrategicScore(state, gate) * 0.08 : 0)
      : 0;
  return orderBias + laneScore + gateLaneScore - targetDistance * 8 - wrongLanePenalty + counterattackSupport;
}

function chooseEnemyPlannerCaptureObjectiveForPlacement(state: GameState, coord: UnitInstance["coord"], plan: EnemyTurnPlan): UnitInstance["coord"] {
  const campaignGate = chooseEnemyCampaignPlacementGateTarget(state, "Infantry", plan, coord);
  if (campaignGate && plan.strategicSnapshot.gateUrgency > plan.strategicSnapshot.baseAttackUrgency * 0.55) {
    return campaignGate.coord;
  }
  if (isEnemyBaseOperationPlacementPhase(plan.campaignPlan.phase)) {
    return chooseEnemyCampaignBasePlacementTarget(state, "Infantry", plan);
  }
  return plan.primaryObjective;
}

function executeEnemyPlacementPlan(state: GameState, plan: EnemyTurnPlan): void {
  let placed = false;
  for (const placement of plan.placementPlan) {
    placeUnitWithoutFog(state, "Enemy", placement.unitType, placement.coord, "preserve");
    invalidateEnemyEvaluationCache();
    placed = true;
  }
  if (placed) {
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
  }
}

function cloneEnemyPlanningState(state: GameState): GameState {
  return {
    ...state,
    units: state.units.map((unit) => ({
      ...unit,
      coord: { ...unit.coord },
      queuedMovement: unit.queuedMovement
        ? {
            destination: { ...unit.queuedMovement.destination },
            path: unit.queuedMovement.path.map((coord) => ({ ...coord })),
            createdDay: unit.queuedMovement.createdDay
          }
        : undefined
    }))
  };
}

function isEnemyLowContactMovementTurn(state: GameState, plan: EnemyTurnPlan): boolean {
  return (
    plan.playerIntel.length === 0 &&
    getEnemyPlannerVisibleTargetIds(plan).size === 0 &&
    !hasActivePlayerGatePressure(state) &&
    state.baseOccupation.Enemy <= 0
  );
}

function refreshEnemyTacticalPlanContext(state: GameState, plan: EnemyTurnPlan): void {
  plan.objectiveImperatives = solveEnemyObjectiveImperatives(state, plan);
  reconcileEnemyRolesAfterImperatives(state, plan);
  plan.campaignPlan = resolveEnemyCampaignPlan(state, plan.rolesByUnitId, plan.strategicSnapshot, plan.playerIntel);
  reconcileEnemyRolesWithCampaign(state, plan.rolesByUnitId, plan.campaignPlan);
  reconcileEnemyRolesAfterImperatives(state, plan);
  plan.taskForces = buildEnemyPlannerTaskForces(state, plan.rolesByUnitId, plan.campaignPlan);
  plan.activationDependencies = buildEnemyActivationDependencies(state, plan);
}

function finalizeEnemyTacticalPlan(state: GameState, plan: EnemyTurnPlan): void {
  refreshEnemyTacticalPlanContext(state, plan);
  const activationOrder = chooseEnemyPlannerActivationOrder(state, plan);
  const decisiveMoment = isEnemyPlannerDecisiveMoment(state, plan);
  const lowContactMovement = isEnemyLowContactMovementTurn(state, plan);
  const searchOrder = activationOrder.slice(0, lowContactMovement ? 4 : decisiveMoment ? ENEMY_PLANNER_RELEVANT_UNIT_CAP + 4 : ENEMY_PLANNER_RELEVANT_UNIT_CAP);
  const actionCap = lowContactMovement ? 2 : decisiveMoment ? ENEMY_PLANNER_ACTION_CAP + 2 : ENEMY_PLANNER_ACTION_CAP;
  const beamWidth = lowContactMovement ? 2 : decisiveMoment ? ENEMY_PLANNER_BEAM_WIDTH + 4 : ENEMY_PLANNER_BEAM_WIDTH;
  const nodeCap = lowContactMovement ? Math.min(96, ENEMY_PLANNER_NODE_CAP) : ENEMY_PLANNER_NODE_CAP;
  let nodes: EnemyPlannerBeamNode[] = [
    {
      state: cloneEnemyPlanningState(state),
      actions: [],
      score: 0,
      tieBreak: "",
      reservedDestinations: {},
      reservedExpectedDamage: {}
    }
  ];

  for (const unitId of searchOrder) {
    const nextNodes: EnemyPlannerBeamNode[] = [];
    for (const node of nodes) {
      if (plan.searchStats.nodes >= nodeCap) {
        plan.searchStats.capped = true;
        break;
      }

      const unit = node.state.units.find((candidate) => candidate.id === unitId && candidate.owner === "Enemy");
      if (!unit || unit.placedDay === node.state.day) {
        nextNodes.push(node);
        continue;
      }

      const actions = enumerateEnemyCompoundActions(node.state, unit, plan, node.reservedDestinations, node.reservedExpectedDamage)
        .slice(0, actionCap);
      for (const action of actions) {
        if (plan.searchStats.nodes >= nodeCap) {
          plan.searchStats.capped = true;
          break;
        }
        plan.searchStats.nodes += 1;
        const nextState = cloneEnemyPlanningState(node.state);
        applyExpectedEnemyCompoundActionForPlanning(nextState, action);
        const reservedDestinations = { ...node.reservedDestinations };
        reserveEnemyActionDestination(action, reservedDestinations);
        const reservedExpectedDamage = cloneReservedExpectedDamage(node.reservedExpectedDamage);
        reserveEnemyActionExpectedDamage(action, reservedExpectedDamage);
        nextNodes.push({
          state: nextState,
          actions: [...node.actions, action],
          score: node.score + action.breakdown.total,
          tieBreak: appendEnemyActionTieBreak(node.tieBreak, action),
          reservedDestinations,
          reservedExpectedDamage
        });
      }
    }

    if (nextNodes.length === 0) {
      break;
    }

    nodes = nextNodes
      .sort((first, second) => second.score - first.score || first.tieBreak.localeCompare(second.tieBreak))
      .slice(0, beamWidth);
    if (plan.searchStats.capped) {
      break;
    }
  }

  const best = nodes.sort((first, second) => second.score - first.score || first.tieBreak.localeCompare(second.tieBreak))[0];
  plan.plannedActions = best?.actions ?? [];
  plan.reservedDestinations = best?.reservedDestinations ?? {};
  plan.reservedExpectedDamage = best?.reservedExpectedDamage ?? {};
  appendEnemyRoutineObjectivePlannedActions(state, plan, activationOrder);
  plan.debugBreakdowns = plan.plannedActions.map(formatEnemyPlannerActionDebug);
}

function appendEnemyRoutineObjectivePlannedActions(state: GameState, plan: EnemyTurnPlan, activationOrder: string[]): void {
  const plannedUnitIds = new Set(
    plan.plannedActions
      .filter((action) => action.kind === "Move" || action.kind === "Hold")
      .map((action) => action.unitId)
  );
  const planningState = cloneEnemyPlanningState(state);
  for (const action of plan.plannedActions.filter((candidate) => candidate.kind === "Move" || candidate.kind === "Hold")) {
    applyExpectedEnemyCompoundActionForPlanning(planningState, action);
  }

  const reservedDestinations = { ...plan.reservedDestinations };
  const reservedExpectedDamage = cloneReservedExpectedDamage(plan.reservedExpectedDamage);
  for (const unitId of activationOrder) {
    if (plannedUnitIds.has(unitId)) {
      continue;
    }

    const unit = planningState.units.find((candidate) => candidate.id === unitId && candidate.owner === "Enemy");
    if (!unit || unit.placedDay === planningState.day || unit.hasMovedThisDay) {
      continue;
    }

    const action = chooseEnemyRoutineObjectiveAction(planningState, unit, plan, reservedDestinations, reservedExpectedDamage);
    if (!action) {
      continue;
    }

    plan.plannedActions.push(action);
    plannedUnitIds.add(unitId);
    reserveEnemyActionDestination(action, reservedDestinations);
    reserveEnemyActionExpectedDamage(action, reservedExpectedDamage);
    applyExpectedEnemyCompoundActionForPlanning(planningState, action);
  }

  plan.reservedDestinations = reservedDestinations;
  plan.reservedExpectedDamage = reservedExpectedDamage;
}

function executeEnemyTacticalPlan(state: GameState, plan: EnemyTurnPlan, context?: EngineDispatchContext): void {
  const actedUnitIds = new Set<string>();
  const planHasActiveAction = plan.plannedActions.some((action) => action.kind !== "Hold");
  for (const action of plan.plannedActions) {
    const unit = state.units.find((candidate) => candidate.id === action.unitId && candidate.owner === "Enemy");
    if (!unit) {
      continue;
    }

    if ((action.kind === "Hold" && shouldEnemyAttemptRepairRetreat(state, unit)) || (action.kind !== "Move" && isEnemyLowHealthHighValueRepairCandidate(state, unit))) {
      const repairMove = chooseEnemyRepairFallbackMove(state, unit, plan);
      if (repairMove && canMoveUnitTo(state, unit, repairMove)) {
        const repairAction = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: repairMove }, {}, {});
        withEnemyActionLogDetail(state, unit, repairAction, plan, context, () => moveUnitTo(state, unit, repairMove, "preserve", context));
        invalidateEnemyEvaluationCache();
        actedUnitIds.add(unit.id);
        continue;
      }
    }

    if (
      !isEnemyLiveObjectiveActionStillValid(state, unit, action, plan) ||
      !executeEnemyCompoundAction(state, action, plan, context)
    ) {
      executeEnemyLocalFallback(state, unit.id, plan, context);
    }
    if (!shouldRevisitGateRoleHold(state, unit.id, action, plan)) {
      actedUnitIds.add(unit.id);
    }
  }

  if (!planHasActiveAction && getOwnerUnits(state, "Enemy").some((unit) => unit.placedDay !== state.day && !unit.hasMovedThisDay && !unit.hasAttackedThisDay)) {
    for (const unit of getOwnerUnits(state, "Enemy")) {
      if (unit.placedDay === state.day || unit.hasMovedThisDay || unit.hasAttackedThisDay || shouldEnemyPreserveCriticalHold(state, unit)) {
        continue;
      }
      if (shouldEnemyAttemptRepairRetreat(state, unit)) {
        const repairMove = chooseEnemyRepairFallbackMove(state, unit, plan);
        if (repairMove && canMoveUnitTo(state, unit, repairMove)) {
          const repairAction = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: repairMove }, {}, {});
          withEnemyActionLogDetail(state, unit, repairAction, plan, context, () => moveUnitTo(state, unit, repairMove, "preserve", context));
          invalidateEnemyEvaluationCache();
        }
      } else {
        executeEnemyEmergencyFallbackUnitAction(state, unit, context ?? { enemyMovementTrails: [] });
      }
    }
    return;
  }

  for (const unit of getOwnerUnits(state, "Enemy")) {
    if (
      actedUnitIds.has(unit.id) ||
      unit.placedDay === state.day ||
      unit.hasMovedThisDay ||
      unit.hasAttackedThisDay ||
      (
        !shouldEnemyAttemptRepairRetreat(state, unit) &&
        plan.rolesByUnitId[unit.id] !== "CaptureGate" &&
        plan.rolesByUnitId[unit.id] !== "DefendGate" &&
        plan.rolesByUnitId[unit.id] !== "Repair" &&
        plan.rolesByUnitId[unit.id] !== "ShadowCapturer" &&
        plan.rolesByUnitId[unit.id] !== "EscortCapture"
      )
    ) {
      continue;
    }
    executeEnemyLocalFallback(state, unit.id, plan, context);
  }
}

function executeEnemyCombatEvaluator(state: GameState, plan: EnemyTurnPlan, context?: EngineDispatchContext): void {
  if (isEnemyLowContactMovementTurn(state, plan)) {
    return;
  }

  const reservedDestinations: Record<string, string> = {};
  const reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }> = {};
  const blockedActionIds = new Set<string>();
  const maxIterations = Math.max(1, getOwnerUnits(state, "Enemy").length);
  const executedActions: EnemyCompoundAction[] = [];

  for (let iteration = 0; iteration < maxIterations; iteration += 1) {
    const best = chooseBestEnemyCombatEvaluatorAction(state, plan, reservedDestinations, reservedExpectedDamage, blockedActionIds);
    if (!best) {
      break;
    }

    plan.searchStats.nodes += 1;
    if (
      !isEnemyLiveObjectiveActionStillValid(state, best.unit, best.action, plan) ||
      !executeEnemyCompoundAction(state, best.action, plan, context)
    ) {
      blockedActionIds.add(best.action.id);
      continue;
    }

    reserveEnemyActionDestination(best.action, reservedDestinations);
    reserveEnemyActionExpectedDamage(best.action, reservedExpectedDamage);
    executedActions.push(best.action);
    invalidateEnemyEvaluationCache();
  }

  plan.reservedDestinations = reservedDestinations;
  plan.reservedExpectedDamage = reservedExpectedDamage;
  if (executedActions.length) {
    plan.plannedActions = executedActions;
    plan.debugBreakdowns = executedActions.map(formatEnemyPlannerActionDebug);
  }
}

function chooseBestEnemyCombatEvaluatorAction(
  state: GameState,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>,
  blockedActionIds: Set<string>
): { unit: UnitInstance; action: EnemyCompoundAction } | undefined {
  const antiAirThreatMap = getEnemyAntiAirThreatMap(state, plan);
  const candidates: Array<{ unit: UnitInstance; action: EnemyCompoundAction }> = [];

  for (const unit of getOwnerUnits(state, "Enemy")) {
    if (unit.health <= 0 || unit.hasAttackedThisDay || unit.placedDay === state.day) {
      continue;
    }
    for (const action of enumerateEnemyImmediateTacticalAttackActions(state, unit, plan, reservedDestinations, reservedExpectedDamage, antiAirThreatMap)) {
      if (
        blockedActionIds.has(action.id) ||
        (action.kind !== "Attack" && action.kind !== "MoveThenAttack" && action.kind !== "AttackThenMove" && action.kind !== "MoveAttackRetreat")
      ) {
        continue;
      }
      candidates.push({ unit, action });
    }
  }

  return candidates
    .sort((first, second) =>
      second.action.breakdown.total - first.action.breakdown.total ||
      getEnemyCombatEvaluatorKindRank(first.action) - getEnemyCombatEvaluatorKindRank(second.action) ||
      first.action.id.localeCompare(second.action.id)
    )[0];
}

function getEnemyCombatEvaluatorKindRank(action: EnemyCompoundAction): number {
  if (action.kind === "MoveAttackRetreat") return 0;
  if (action.kind === "MoveThenAttack") return 1;
  if (action.kind === "AttackThenMove") return 2;
  if (action.kind === "Attack") return 3;
  return 4;
}

function executeEnemyUnifiedActionEvaluator(state: GameState, plan: EnemyTurnPlan, context?: EngineDispatchContext): void {
  refreshEnemyPlannerLiveIntel(state, plan);
  const executedActions: EnemyCompoundAction[] = [];
  const activationOrder = chooseEnemyPlannerActivationOrder(state, plan);
  const unitOrder = uniqueUnitIds([
    ...activationOrder,
    ...getOwnerUnits(state, "Enemy").map((unit) => unit.id)
  ]);
  const maxActionsPerUnit = 4;

  for (const unitId of unitOrder) {
    let actionsTaken = 0;
    while (actionsTaken < maxActionsPerUnit) {
      const unit = state.units.find((candidate) => candidate.id === unitId && candidate.owner === "Enemy");
      if (!unit || unit.health <= 0 || unit.placedDay === state.day || !canEnemyUnitStillAct(state, unit)) {
        break;
      }

      const immediateBaseLossAction = chooseEnemyUnifiedImmediateBaseLossAction(state, unit, plan);
      if (immediateBaseLossAction) {
        if (!executeEnemyCompoundActionDirect(state, unit, immediateBaseLossAction, plan, context)) {
          break;
        }
        executedActions.push(immediateBaseLossAction);
        refreshEnemyPlannerLiveIntel(state, plan, { synchronizeFog: false });
        actionsTaken += 1;
        continue;
      }
      if (isEnemyImmediateBaseLossCrisis(state)) {
        break;
      }

      if (shouldEnemyAttemptRepairRetreat(state, unit)) {
        const repairMove = chooseEnemyRepairFallbackMove(state, unit, plan);
        if (repairMove && canMoveUnitTo(state, unit, repairMove)) {
          const repairAction = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: repairMove }, {}, {});
          withEnemyActionLogDetail(state, unit, repairAction, plan, context, () => moveUnitTo(state, unit, repairMove, "preserve", context, { refreshFog: false }));
          executedActions.push(repairAction);
          refreshEnemyPlannerLiveIntel(state, plan);
        }
        break;
      }

      const forcedAction = chooseEnemyUnifiedForcedMovementAction(state, unit, plan);
      if (forcedAction) {
        if (forcedAction.kind === "Hold") {
          break;
        }
        if (!executeEnemyCompoundActionDirect(state, unit, forcedAction, plan, context)) {
          break;
        }
        executedActions.push(forcedAction);
        refreshEnemyPlannerLiveIntel(state, plan, { synchronizeFog: false });
        actionsTaken += 1;
        const movedUnit = state.units.find((candidate) => candidate.id === unit.id && candidate.owner === "Enemy");
        if (movedUnit && isEnemyOpeningPatrolAtGateStandoff(state, movedUnit, plan)) {
          break;
        }
        continue;
      }

      const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
      if (isEnemyBaseAssaultCombatMission(state, unit, mission, plan)) {
        break;
      }

      const action = chooseBestEnemyUnifiedEvaluatorAction(state, unit, plan);
      if (!action || action.kind === "Hold") {
        break;
      }

      plan.searchStats.nodes += 1;
      if (
        !isEnemyLiveObjectiveActionStillValid(state, unit, action, plan) ||
        !executeEnemyCompoundActionDirect(state, unit, action, plan, context)
      ) {
        break;
      }

      executedActions.push(action);
      refreshEnemyPlannerLiveIntel(state, plan, { synchronizeFog: false });
      actionsTaken += 1;
    }
  }

  if (executedActions.length) {
    plan.plannedActions = executedActions;
    plan.debugBreakdowns = executedActions.map(formatEnemyPlannerActionDebug);
    plan.reservedDestinations = {};
    plan.reservedExpectedDamage = {};
  }
}

function isEnemyImmediateBaseLossCrisis(state: GameState): boolean {
  return state.baseOccupation.Enemy >= BASE_CAPTURE_DAYS - 1 && getEnemyImmediateBaseLossCapturer(state) !== undefined;
}

function isEnemyImmediateBaseWinCrisis(state: GameState): boolean {
  return (
    state.baseOccupation.Player >= BASE_CAPTURE_DAYS - 1 &&
    getOwnerUnits(state, "Enemy").some((unit) => getUnitDefinition(unit.type).humanBased && sameHex(unit.coord, state.bases.Player))
  );
}

function shouldSkipEnemyTacticalBeamPlan(state: GameState): boolean {
  return isEnemyImmediateBaseLossCrisis(state) || isEnemyImmediateBaseWinCrisis(state);
}

function getEnemyImmediateBaseLossCapturer(state: GameState, unit?: UnitInstance): UnitInstance | undefined {
  if (state.baseOccupation.Enemy < BASE_CAPTURE_DAYS - 1) {
    return undefined;
  }

  return getOwnerUnits(state, "Player")
    .filter((target) => getUnitDefinition(target.type).humanBased && sameHex(target.coord, state.bases.Enemy))
    .filter((target) => !unit || canUnitTargetUnit(unit.type, target.type))
    .sort((first, second) => first.health - second.health || first.id.localeCompare(second.id))[0];
}

function chooseEnemyUnifiedImmediateBaseLossAction(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan
): EnemyCompoundAction | undefined {
  if (unit.hasAttackedThisDay) {
    return undefined;
  }

  const target = getEnemyImmediateBaseLossCapturer(state, unit);
  if (!target) {
    return undefined;
  }

  const outcome = getExpectedAttackOutcome(state, unit, target);
  const attackRange = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord).attackRange;
  if (hexDistance(unit.coord, target.coord) <= attackRange) {
    return createEnemyCompoundAction(
      state,
      unit,
      plan,
      "Attack",
      { attackAt: target.coord, targetId: target.id, targetType: target.type, expectedOutcome: outcome },
      {},
      {}
    );
  }

  if (unit.hasMovedThisDay || isMoveAttackExclusiveUnit(unit.type)) {
    return undefined;
  }

  const moveTo = chooseEnemyImmediateBaseLossAttackMove(state, unit, target);
  return moveTo
    ? createEnemyCompoundAction(
        state,
        unit,
        plan,
        "MoveThenAttack",
        { moveTo, attackAt: target.coord, targetId: target.id, targetType: target.type, expectedOutcome: outcome },
        {},
        {}
      )
    : undefined;
}

function chooseEnemyImmediateBaseLossAttackMove(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance
): UnitInstance["coord"] | undefined {
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => {
      const range = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, target.coord).attackRange;
      return hexDistance(coord, target.coord) <= range;
    })
    .sort((first, second) =>
      hexDistance(first, target.coord) - hexDistance(second, target.coord) ||
      hexDistance(first, state.bases.Enemy) - hexDistance(second, state.bases.Enemy) ||
      hexId(first).localeCompare(hexId(second))
    )[0];
}

function chooseEnemyUnifiedForcedMovementAction(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan
): EnemyCompoundAction | undefined {
  const reservedDestinations: Record<string, string> = {};
  const reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }> = {};
  const antiAirThreatMap = getEnemyAntiAirThreatMap(state, plan);
  const imperativeAction = getPlausibleEnemyCompoundActions(
    state,
    unit,
    plan,
    enumerateForcedEnemyCompoundActions(state, unit, plan, reservedDestinations, reservedExpectedDamage)
  )[0];
  if (imperativeAction) {
    return imperativeAction;
  }

  const baseAssaultAction = chooseEnemyUnifiedBaseAssaultForcedAction(state, unit, plan);
  if (baseAssaultAction && isEnemyCompoundActionPlausiblyLegal(state, unit, baseAssaultAction, plan)) {
    return baseAssaultAction;
  }

  const forcedMoves = [
    chooseEnemyPlannerScoutGateStandoffMove(state, unit, plan),
    chooseEnemyPlannerForcedOpeningPatrolMove(state, unit, plan, reservedDestinations),
    chooseEnemyPlannerEarlyPatrolPriorityMove(state, unit, plan, reservedDestinations),
    chooseEnemyPlannerOpeningGateCapturerMove(state, unit, plan, reservedDestinations),
    chooseEnemyPlannerForcedOpeningGateEntryMove(state, unit, plan),
    chooseEnemyPlannerOpeningGateEscortMove(state, unit, plan, reservedDestinations)
  ];

  for (const moveTo of forcedMoves) {
    if (!moveTo || !canMoveUnitTo(state, unit, moveTo) || !isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap)) {
      continue;
    }
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return action;
    }
  }

  if (shouldEnemyPlannerOpeningGateCapturerHold(state, unit, plan)) {
    return createEnemyCompoundAction(state, unit, plan, "Hold", {}, reservedDestinations, reservedExpectedDamage);
  }

  return undefined;
}

function chooseEnemyUnifiedBaseAssaultForcedAction(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan
): EnemyCompoundAction | undefined {
  if (!isHardEndgameDoctrineActive(state, plan) || unit.placedDay === state.day) {
    return undefined;
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission === "CaptureBase" && getUnitDefinition(unit.type).humanBased && !unit.hasMovedThisDay) {
    const moveTo = chooseEnemyPlannerForcedBaseAssaultMove(state, unit, plan);
    return moveTo ? createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, {}, {}) : undefined;
  }

  if (mission !== "Siege" || !isEnemyBaseAttackCombatUnit(unit)) {
    return undefined;
  }

  const attackAction = enumerateEnemyPriorityBaseAreaAttackActions(state, unit, plan, {}, {})[0];
  if (attackAction) {
    return attackAction;
  }

  const moveTo = chooseEnemyPlannerForcedBaseAttackMove(state, unit, plan);
  return moveTo ? createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, {}, {}) : undefined;
}

function canEnemyUnitStillAct(state: GameState, unit: UnitInstance): boolean {
  return !unit.hasAttackedThisDay || getRemainingMovementPoints(state, unit) > 0;
}

function chooseBestEnemyUnifiedEvaluatorAction(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan
): EnemyCompoundAction | undefined {
  const actions = enumerateEnemyUnifiedEvaluatorActions(state, unit, plan)
    .filter((action) => isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan))
    .sort((first, second) => compareEnemyCompoundActionsForPlanning(state, unit, plan, first, second));
  return actions[0];
}

function enumerateEnemyUnifiedEvaluatorActions(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): EnemyCompoundAction[] {
  const actions: EnemyCompoundAction[] = [
    createEnemyCompoundAction(state, unit, plan, "Hold", {}, {}, {})
  ];
  const antiAirThreatMap = getEnemyAntiAirThreatMap(state, plan);

  if (!unit.hasAttackedThisDay) {
    for (const attack of getEnemyPlannerAttackOptions(state, unit, plan, {})) {
      actions.push(createEnemyCompoundAction(
        state,
        unit,
        plan,
        "Attack",
        { attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
        {},
        {}
      ));
    }
  }

  const canUseMoveAttackSequence = !isMoveAttackExclusiveUnit(unit.type) && !unit.hasMovedThisDay && !unit.hasAttackedThisDay && !shouldEnemyForbidRelocatingForAttack(state, unit);
  const moveCoords = uniqueCoords(getEnemyLegalMoveCoords(state, unit).filter((coord) => canMoveUnitTo(state, unit, coord)));
  for (const moveTo of moveCoords) {
    if (isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap)) {
      actions.push(createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, {}, {}));
    }

    if (!canUseMoveAttackSequence) {
      continue;
    }

    const movedUnit: UnitInstance = {
      ...unit,
      coord: { ...moveTo },
      movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, moveTo)
    };
    for (const attack of getEnemyPlannerAttackOptions(state, movedUnit, plan, {})) {
      if (!isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap, {
        targetId: attack.target.id,
        expectedOutcome: attack.outcome
      })) {
        continue;
      }

      actions.push(createEnemyCompoundAction(
        state,
        unit,
        plan,
        "MoveThenAttack",
        { moveTo, attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
        {},
        {}
      ));

      for (const retreatTo of getEnemyMoveAttackRetreatCoords(state, unit, movedUnit, attack, plan, {}, antiAirThreatMap)) {
        actions.push(createEnemyCompoundAction(
          state,
          unit,
          plan,
          "MoveAttackRetreat",
          { moveTo, retreatTo, attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
          {},
          {}
        ));
      }
    }
  }

  if (!isMoveAttackExclusiveUnit(unit.type) && !unit.hasMovedThisDay && !unit.hasAttackedThisDay) {
    for (const attack of getEnemyPlannerAttackOptions(state, unit, plan, {})) {
      for (const moveTo of moveCoords) {
        if (!isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap, {
          targetId: attack.target.id,
          expectedOutcome: attack.outcome
        })) {
          continue;
        }
        actions.push(createEnemyCompoundAction(
          state,
          unit,
          plan,
          "AttackThenMove",
          { moveTo, attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
          {},
          {}
        ));
      }
    }
  }

  return actions;
}

function uniqueUnitIds(unitIds: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const unitId of unitIds) {
    if (seen.has(unitId)) {
      continue;
    }
    seen.add(unitId);
    result.push(unitId);
  }
  return result;
}

function executeEnemyMovementPlan(state: GameState, plan: EnemyTurnPlan, context?: EngineDispatchContext): void {
  const actedUnitIds = new Set<string>();
  const movementActions = plan.plannedActions.filter((action) => action.kind === "Move" || action.kind === "Hold");
  const planHasActiveMove = movementActions.some((action) => action.kind === "Move");

  for (const action of movementActions) {
    const unit = state.units.find((candidate) => candidate.id === action.unitId && candidate.owner === "Enemy");
    if (!unit) {
      continue;
    }

    if (action.kind === "Hold" && shouldEnemyAttemptRepairRetreat(state, unit)) {
      const repairMove = chooseEnemyRepairFallbackMove(state, unit, plan);
      if (repairMove && canMoveUnitTo(state, unit, repairMove)) {
        const repairAction = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: repairMove }, {}, {});
        withEnemyActionLogDetail(state, unit, repairAction, plan, context, () => moveUnitTo(state, unit, repairMove, "preserve", context));
        invalidateEnemyEvaluationCache();
        actedUnitIds.add(unit.id);
        continue;
      }
    }

    if (
      action.kind === "Move" &&
      (!isEnemyLiveObjectiveActionStillValid(state, unit, action, plan) ||
        !executeEnemyCompoundAction(state, action, plan, context))
    ) {
      executeEnemyMovementLocalFallback(state, unit.id, plan, context);
    }
    if (!shouldRevisitGateRoleHold(state, unit.id, action, plan)) {
      actedUnitIds.add(unit.id);
    }
  }

  for (const unit of getOwnerUnits(state, "Enemy")) {
    if (
      actedUnitIds.has(unit.id) ||
      unit.placedDay === state.day ||
      unit.hasMovedThisDay ||
      shouldEnemyPreserveCriticalHold(state, unit)
    ) {
      continue;
    }
    executeEnemyMovementLocalFallback(state, unit.id, plan, context);
  }
}

function executeEnemyMovementLocalFallback(state: GameState, unitId: string, plan: EnemyTurnPlan, context?: EngineDispatchContext): void {
  const unit = state.units.find((candidate) => candidate.id === unitId && candidate.owner === "Enemy");
  if (!unit || unit.hasMovedThisDay || unit.placedDay === state.day) {
    return;
  }

  const strategicFallback = chooseEnemyStrategicLocalFallbackAction(state, unit, plan);
  if (strategicFallback?.kind === "Move" && executeEnemyCompoundActionDirect(state, unit, strategicFallback, plan, context)) {
    return;
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (isEnemyBaseAssaultCombatMission(state, unit, mission, plan)) {
    return;
  }

  if (isEnemyLowContactMovementTurn(state, plan)) {
    return;
  }

  const action = enumerateEnemyCompoundActions(state, unit, plan, {}, {})
    .filter((candidate) => candidate.kind === "Move")
    .sort((first, second) => second.breakdown.total - first.breakdown.total || first.id.localeCompare(second.id))[0];
  if (action && action.breakdown.total > 0) {
    executeEnemyCompoundActionDirect(state, unit, action, plan, context);
  }
}

function isEnemyLiveObjectiveActionStillValid(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  if (!isEnemyLiveActionTargetStillValid(state, action)) {
    return false;
  }
  if (!isEnemyLiveActionDestinationStillLegal(state, unit, action)) {
    return false;
  }
  if (!isEnemyLiveCaptureTileAssumptionStillValid(state, unit, action, plan)) {
    return false;
  }
  const moveThreatContext =
    action.kind === "MoveAttackRetreat"
      ? { ...action, moveAttackRetreatAttackTile: true }
      : action;
  if (action.moveTo && !isEnemyAirMoveAllowedByThreatMap(state, unit, action.moveTo, moveThreatContext, plan)) {
    return false;
  }
  if (action.retreatTo && !isEnemyAirMoveAllowedByThreatMap(state, unit, action.retreatTo, action, plan)) {
    return false;
  }
  return doesEnemyLiveActionStillSupportRole(state, unit, action, plan);
}

function isEnemyLiveActionTargetStillValid(state: GameState, action: EnemyCompoundAction): boolean {
  if (!action.targetId) {
    return true;
  }

  const target = getUnitById(state, action.targetId);
  if (!target || target.owner !== "Player") {
    return false;
  }
  return !action.attackAt || sameHex(target.coord, action.attackAt);
}

function isEnemyLiveActionDestinationStillLegal(state: GameState, unit: UnitInstance, action: EnemyCompoundAction): boolean {
  if ((action.kind === "Move" || action.kind === "MoveThenAttack" || action.kind === "AttackThenMove" || action.kind === "MoveAttackRetreat") && (!action.moveTo || !canMoveUnitTo(state, unit, action.moveTo))) {
    return false;
  }
  if ((action.kind === "Attack" || action.kind === "AttackThenMove") && (!action.attackAt || !canUnitAttackHex(state, unit, action.attackAt))) {
    return false;
  }
  if (action.kind === "MoveThenAttack" && !action.attackAt) {
    return false;
  }
  if (action.kind === "MoveAttackRetreat") {
    return isEnemyMoveAttackRetreatLegsLegal(state, unit, action);
  }
  return true;
}

function isEnemyLiveCaptureTileAssumptionStillValid(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  const role = plan.rolesByUnitId[unit.id];
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);

  if (role === "CaptureGate") {
    const gate = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
    if (!gate || !sameHex(finalCoord, gate.coord)) {
      return true;
    }
    const contestingPlayer = getOwnerUnits(state, "Player").find((candidate) => getUnitDefinition(candidate.type).humanBased && sameHex(candidate.coord, gate.coord));
    return !contestingPlayer || action.targetId === contestingPlayer.id;
  }

  if (role === "CaptureBase" && sameHex(finalCoord, state.bases.Player)) {
    const blocker = getOwnerUnits(state, "Player").find((candidate) => sameHex(candidate.coord, state.bases.Player));
    return !blocker || action.targetId === blocker.id;
  }

  return true;
}

function doesEnemyLiveActionStillSupportRole(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  if (isEnemyImmediateObjectiveImperativeAction(state, unit, action, plan)) {
    return true;
  }
  const role = plan.rolesByUnitId[unit.id];
  if (role === "CaptureGate") {
    const gate = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
    return gate ? doesEnemyLiveActionProgressTowardObjective(state, unit, action, gate.coord) : false;
  }
  if (role === "CaptureBase") {
    return doesEnemyLiveActionProgressTowardObjective(state, unit, action, state.bases.Player);
  }
  if (role === "DefendGate") {
    const gate = chooseEnemyGateRoleTarget(state, "DefendGate");
    return gate ? doesEnemyLiveActionProgressTowardObjective(state, unit, action, gate.coord) : true;
  }
  if (role === "ProtectCapturer") {
    const capturer = getOwnerUnits(state, "Enemy").find((candidate) => getUnitDefinition(candidate.type).humanBased && sameHex(candidate.coord, state.bases.Player));
    return capturer ? doesEnemyLiveActionProgressTowardObjective(state, unit, action, capturer.coord) : true;
  }
  return true;
}

function doesEnemyLiveActionProgressTowardObjective(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  objective: UnitInstance["coord"]
): boolean {
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  if (sameHex(finalCoord, objective)) {
    return true;
  }
  if (action.targetId) {
    const target = getUnitById(state, action.targetId);
    if (target && hexDistance(target.coord, objective) <= 1) {
      return true;
    }
  }
  if (action.kind === "Hold") {
    return sameHex(unit.coord, objective);
  }
  return hexDistance(finalCoord, objective) < hexDistance(unit.coord, objective);
}

function isEnemyActionAllowedByStrategicStructure(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (!isEnemyGateRecaptureMoveSafe(state, unit, action, plan)) {
    return false;
  }
  if (isEnemyImmediateObjectiveImperativeAction(state, unit, action, plan)) {
    return true;
  }
  if (isEnemyBaseAssaultCombatMission(state, unit, mission, plan)) {
    return isEnemyBaseAssaultCombatActionAllowed(state, unit, action, plan);
  }
  if (isEnemyTacticalAttackAllowedByStrategicStructure(state, unit, action, plan)) {
    return true;
  }

  if (mission === "CaptureGate") {
    const gate = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
    return gate ? isEnemyStructuredObjectiveActionAllowed(state, unit, action, gate.coord, true) : false;
  }

  if (mission === "DefendGate") {
    const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    return gate ? isEnemyGateTheatreDefenseActionAllowed(state, unit, action, gate, plan) : true;
  }

  if (isEnemyGateLockoutCombatMission(mission)) {
    const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
    const targetCoord = chooseEnemyGateLockoutRoleTargetCoord(state, unit, mission, plan);
    if (!gate || !targetCoord) {
      return true;
    }
    if (action.targetId) {
      const target = getUnitById(state, action.targetId);
      if (target && target.owner === "Player" && hexDistance(target.coord, gate.coord) <= 5) {
        return true;
      }
    }
    return isEnemyStructuredObjectiveActionAllowed(state, unit, action, targetCoord, mission === "ReserveCapturer");
  }

  if (mission === "CaptureBase") {
    return isEnemyStructuredObjectiveActionAllowed(state, unit, action, state.bases.Player, true);
  }

  if (mission === "DefendBase") {
    return isEnemyStructuredObjectiveActionAllowed(state, unit, action, state.bases.Enemy, true);
  }

  if (mission === "ProtectCapturer") {
    const capturer = getEnemyBaseHoldCapturer(state, plan);
    return capturer ? isEnemyStructuredObjectiveActionAllowed(state, unit, action, capturer.coord, false) : true;
  }

  if ((mission === "ShadowCapturer" || mission === "EscortCapture") && isEnemyGateContinuityPhase(plan.campaignPlan.phase)) {
    const gateId = plan.campaignPlan.assignedGateByUnitId[unit.id];
    const gate = gateId ? (state.gates ?? []).find((candidate) => candidate.id === gateId) : undefined;
    return gate ? isEnemyCaptureSupportActionAllowed(state, unit, action, gate.coord) : true;
  }

  return true;
}

function isEnemyBaseAssaultCombatMission(state: GameState, unit: UnitInstance, mission: EnemyMission, plan: EnemyTurnPlan): boolean {
  return mission === "Siege" && isEnemyBaseOperationPhase(plan.campaignPlan.phase) && isEnemyBaseAttackCombatUnit(unit) && ownerControlsBothGates(state, "Enemy");
}

function isEnemyBaseAssaultCombatActionAllowed(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan
): boolean {
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  if (target) {
    if (target.owner !== "Player" || !isPlayerBaseAreaAssaultTarget(state, target)) {
      return false;
    }
    if (action.kind === "Attack") {
      return true;
    }
    return isEnemyBaseAssaultCombatMovementAllowed(state, unit, finalCoord, plan);
  }

  if (action.kind === "Hold") {
    return isEnemyBaseAssaultFireCoveragePosition(state, unit, unit.coord, plan);
  }

  if (!action.moveTo) {
    return false;
  }
  return isEnemyBaseAssaultCombatMovementAllowed(state, unit, finalCoord, plan);
}

function isEnemyBaseAssaultCombatMovementAllowed(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): boolean {
  if (sameHex(finalCoord, unit.coord)) {
    return isEnemyBaseAssaultFireCoveragePosition(state, unit, unit.coord, plan);
  }
  const rowProgress = finalCoord.r - unit.coord.r;
  if (rowProgress < 0) {
    return false;
  }
  const currentDistance = hexDistance(unit.coord, state.bases.Player);
  const finalDistance = hexDistance(finalCoord, state.bases.Player);
  if (rowProgress > 0 && finalDistance <= currentDistance) {
    return true;
  }

  const currentCoverage = scoreEnemyBaseAssaultFireCoverage(state, unit, unit.coord, plan);
  const finalCoverage = scoreEnemyBaseAssaultFireCoverage(state, unit, finalCoord, plan);
  return (
    isCoordInPlayerBaseAssaultArea(state, finalCoord) &&
    finalDistance <= currentDistance &&
    finalCoverage >= 520 &&
    finalCoverage > currentCoverage + 80
  );
}

function isEnemyTacticalAttackAllowedByStrategicStructure(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  if (!action.targetId || !action.attackAt || !action.expectedOutcome) {
    return false;
  }

  const target = getUnitById(state, action.targetId);
  if (!target || target.owner !== "Player" || !canUnitTargetUnit(unit.type, target.type)) {
    return false;
  }

  if (action.moveTo && shouldEnemyForbidRelocatingForAttack(state, unit) && !sameHex(action.moveTo, unit.coord)) {
    return false;
  }

  return true;
}

function getEnemyStructuredObjectiveForMission(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission === "CaptureGate") {
    return chooseEnemyPlannerGateTargetForUnit(state, unit, plan)?.coord;
  }
  if (mission === "DefendGate") {
    return chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission)?.coord;
  }
  if (isEnemyGateLockoutCombatMission(mission)) {
    return chooseEnemyGateLockoutRoleTargetCoord(state, unit, mission, plan);
  }
  if (mission === "CaptureBase") {
    return state.bases.Player;
  }
  if (mission === "DefendBase") {
    return state.bases.Enemy;
  }
  if (mission === "ProtectCapturer") {
    return getEnemyBaseHoldCapturer(state, plan)?.coord;
  }
  if ((mission === "ShadowCapturer" || mission === "EscortCapture") && isEnemyGateContinuityPhase(plan.campaignPlan.phase)) {
    const gateId = plan.campaignPlan.assignedGateByUnitId[unit.id];
    return gateId ? (state.gates ?? []).find((candidate) => candidate.id === gateId)?.coord : undefined;
  }
  return undefined;
}

function isEnemyGateRecaptureMoveSafe(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  const finalCoord = getEnemyCompoundActionReservedCoord(action);
  if (unit.owner !== "Enemy" || !getUnitDefinition(unit.type).humanBased || !finalCoord) {
    return true;
  }

  const gate = (state.gates ?? []).find((candidate) => candidate.owner !== "Enemy" && sameHex(candidate.coord, finalCoord));
  if (!gate || sameHex(unit.coord, gate.coord)) {
    return true;
  }

  return isGateSafeForRecapture(state, gate, unit, plan);
}

function isEnemyImmediateObjectiveImperativeAction(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  return plan.objectiveImperatives.some((imperative) => {
    if (imperative.unitId && imperative.unitId !== action.unitId) {
      return false;
    }
    if (imperative.targetId && action.targetId === imperative.targetId) {
      return true;
    }
    if (!imperative.targetCoord) {
      return false;
    }
    if (sameHex(finalCoord, imperative.targetCoord)) {
      return true;
    }
    if (action.attackAt && sameHex(action.attackAt, imperative.targetCoord)) {
      return true;
    }
    return action.kind === "Hold" && imperative.actionKind === "Hold" && sameHex(finalCoord, imperative.targetCoord);
  });
}

function isEnemyGateContinuityPhase(phase: EnemyStrategicPhase | undefined): boolean {
  return phase === "OpeningGateRace" || phase === "OneGateOwned" || phase === "GateLockoutCombat" || phase === "Recovery";
}

function isEnemyStructuredObjectiveActionAllowed(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  objective: UnitInstance["coord"],
  preserveClockOnObjective: boolean
): boolean {
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  const currentDistance = hexDistance(unit.coord, objective);
  const finalDistance = hexDistance(finalCoord, objective);

  if (currentDistance === 0) {
    if (sameHex(finalCoord, objective)) {
      return true;
    }
    return !preserveClockOnObjective && isEnemyActionTargetNearObjective(state, action, objective);
  }

  if (action.kind === "Hold") {
    return false;
  }

  if (sameHex(finalCoord, objective) || finalDistance < currentDistance) {
    return true;
  }

  return isEnemyActionTargetNearObjective(state, action, objective);
}

function isEnemyCaptureSupportActionAllowed(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, gateCoord: UnitInstance["coord"]): boolean {
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  const currentDistance = hexDistance(unit.coord, gateCoord);
  const finalDistance = hexDistance(finalCoord, gateCoord);

  if (action.kind === "Hold") {
    return currentDistance <= 3;
  }

  if (isEnemyActionTargetNearObjective(state, action, gateCoord)) {
    return true;
  }

  if (currentDistance > 3) {
    return finalDistance < currentDistance;
  }

  return finalDistance <= 3 || finalDistance < currentDistance;
}

function isEnemyGateTheatreDefenseActionAllowed(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  gate: GateState,
  plan: EnemyTurnPlan
): boolean {
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  const currentDistance = hexDistance(unit.coord, gate.coord);
  const finalDistance = hexDistance(finalCoord, gate.coord);
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  if (target && isEnemyGateTheatreDefenseTarget(state, target, gate, plan)) {
    return true;
  }
  if (sameHex(finalCoord, gate.coord)) {
    return true;
  }
  if (action.kind === "Hold") {
    return isEnemyGateTheatreDefensePosition(state, unit, finalCoord, gate, plan);
  }
  if (finalDistance < currentDistance) {
    return true;
  }
  return finalDistance <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS && isEnemyGateTheatreDefensePosition(state, unit, finalCoord, gate, plan);
}

function isEnemyActionTargetNearObjective(state: GameState, action: EnemyCompoundAction, objective: UnitInstance["coord"]): boolean {
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  if (target && isEnemyTargetNearObjective(state, target, objective)) {
    return true;
  }
  if (!action.attackAt) {
    return false;
  }
  const gate = getGateAtObjectiveCoord(state, objective);
  return hexDistance(action.attackAt, objective) <= (gate ? ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS : 1);
}

const ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS = 5;
const ENEMY_GATE_THEATRE_PRIORITY_RADIUS = 6;

function isEnemyTargetNearObjective(state: GameState, target: UnitInstance, objective: UnitInstance["coord"]): boolean {
  const distance = hexDistance(target.coord, objective);
  if (distance <= 1) {
    return true;
  }

  const gate = getGateAtObjectiveCoord(state, objective);
  if (!gate || target.owner !== "Player") {
    return false;
  }
  if (distance <= ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS) {
    return true;
  }
  return distance <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS && getEnemyGateTheatreTargetPriority(state, target, gate) > 0;
}

function getGateAtObjectiveCoord(state: GameState, objective: UnitInstance["coord"]): GateState | undefined {
  return (state.gates ?? []).find((gate) => sameHex(gate.coord, objective));
}

function getEnemyGateTheatreTargetPriority(state: GameState, target: UnitInstance, gate: GateState): number {
  if (target.owner !== "Player") {
    return 0;
  }

  const distance = hexDistance(target.coord, gate.coord);
  if (distance > ENEMY_GATE_THEATRE_PRIORITY_RADIUS) {
    return 0;
  }

  const definition = getUnitDefinition(target.type);
  const value = getUnitInstanceValue(state, target);
  const damagedHighValue = value >= 120 && target.health / Math.max(1, target.maxHealth) <= 0.55;
  const clearanceTarget = isGateClearanceTarget(state, target, gate);
  const priorityType =
    isEnemySupplySupportUnit(target.type) ||
    target.type === "Artillery" ||
    target.type === "Anti-Air" ||
    target.type === "Tank" ||
    target.type === "IFV";
  const humanCapturer = definition.humanBased;
  if (!priorityType && !damagedHighValue && !humanCapturer && !clearanceTarget) {
    return distance <= ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS ? 120 - distance * 14 : 0;
  }

  const typePriority =
    isEnemySupplySupportUnit(target.type) ? (target.type === "Command Heli" ? 640 : 560) :
      target.type === "Artillery" ? 520 :
        target.type === "Anti-Air" ? 460 :
          target.type === "Tank" ? 430 :
            target.type === "IFV" ? 360 :
              humanCapturer ? 420 :
                damagedHighValue ? 330 :
                  clearanceTarget ? 260 :
                    0;
  const damageBonus = damagedHighValue ? 180 : 0;
  const clockBonus = humanCapturer && (gate.occupation.Player > 0 || gate.owner === "Player") ? 220 : 0;
  const clearanceBonus = clearanceTarget ? 180 : 0;
  return Math.max(0, typePriority + damageBonus + clockBonus + clearanceBonus + value * 0.35 - distance * 38);
}

function isEnemyGateTheatreDefenseTarget(state: GameState, target: UnitInstance, gate: GateState, plan?: EnemyTurnPlan): boolean {
  if (target.owner !== "Player") {
    return false;
  }
  const distance = hexDistance(target.coord, gate.coord);
  if (distance > ENEMY_GATE_THEATRE_PRIORITY_RADIUS + 2) {
    return false;
  }
  return (
    distance <= ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS ||
    getEnemyGateTheatreTargetPriority(state, target, gate) > 0 ||
    isGateClearanceTarget(state, target, gate, plan) ||
    isPlayerGateReinforcementApproach(state, target.coord, gate) ||
    canUnitProjectThreatToCoord(state, target, target.coord, gate.coord)
  );
}

function getEnemyGateTheatreDefenseThreats(state: GameState, gate: GateState, plan?: EnemyTurnPlan): UnitInstance[] {
  const intel = plan?.playerIntel ?? getPlayerIntelForEnemy(state);
  const threats = intel
    .filter((entry) => entry.age <= 3)
    .map((entry) => ({ ...entry.unit, coord: { ...entry.predictedCoord } }))
    .filter((target) => isEnemyGateTheatreDefenseTarget(state, target, gate, plan));
  const visibleThreats = getOwnerUnits(state, "Player").filter((target) => isEnemyGateTheatreDefenseTarget(state, target, gate, plan));
  const seen = new Set<string>();
  return [...visibleThreats, ...threats].filter((target) => {
    if (seen.has(target.id)) {
      return false;
    }
    seen.add(target.id);
    return true;
  });
}

function isPlayerGateReinforcementApproach(state: GameState, coord: UnitInstance["coord"], gate: GateState): boolean {
  const distance = hexDistance(coord, gate.coord);
  if (distance > ENEMY_GATE_THEATRE_PRIORITY_RADIUS + 2) {
    return false;
  }
  const laneQDistance = Math.abs(coord.q - gate.coord.q);
  const approachesFromPlayerSide = coord.r >= gate.coord.r || hexDistance(coord, state.bases.Player) < hexDistance(gate.coord, state.bases.Player);
  return approachesFromPlayerSide && laneQDistance <= 4;
}

function isEnemyGateTheatreDefensePosition(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState,
  plan?: EnemyTurnPlan
): boolean {
  return scoreEnemyGateTheatreDefensePosition(state, unit, coord, gate, plan) >= 70;
}

function scoreEnemyGateTheatreDefensePosition(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState,
  plan?: EnemyTurnPlan
): number {
  const gateDistance = hexDistance(coord, gate.coord);
  if (gateDistance > ENEMY_GATE_THEATRE_PRIORITY_RADIUS + 1) {
    return 0;
  }

  const threats = getEnemyGateTheatreDefenseThreats(state, gate, plan);
  const coverage = threats.reduce((score, threat) => {
    if (!canUnitTargetUnit(unit.type, threat.type)) {
      return score;
    }
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, threat.coord);
    const distance = hexDistance(coord, threat.coord);
    const priority = Math.max(90, getEnemyGateTheatreTargetPriority(state, threat, gate));
    if (distance <= stats.attackRange) {
      return score + 95 + priority * 0.34 + getUnitInstanceValue(state, threat) * 0.2;
    }
    if (!getUnitDefinition(unit.type).cannotMoveAndAttack && distance <= stats.attackRange + stats.moveRange) {
      return score + 42 + priority * 0.16;
    }
    return score;
  }, 0);
  const firingBand =
    gateDistance >= 2 && gateDistance <= Math.max(4, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, gate.coord).attackRange)
      ? 82 - Math.max(0, gateDistance - 4) * 9
      : gateDistance <= 1 && !getUnitDefinition(unit.type).humanBased
        ? -60
        : 18;
  const laneCutoff = isPlayerGateReinforcementApproach(state, coord, gate) && gateDistance >= 2 ? 96 - gateDistance * 7 : 0;
  const gateClockPressure = gate.occupation.Player > 0 ? Math.max(0, 5 - gateDistance) * 28 : 0;
  const danger = plan ? estimatePlayerDangerAtPlanner(state, unit, coord, plan) : estimatePlayerDangerAt(state, unit, coord);
  return Math.max(0, coverage + firingBand + laneCutoff + gateClockPressure - danger * 0.32);
}

function chooseEnemyGateTheatreDefenseAnchorCoord(
  state: GameState,
  unit: UnitInstance,
  gate: GateState,
  plan?: EnemyTurnPlan
): UnitInstance["coord"] | undefined {
  return getPassableCoordsNear(state, gate.coord, ENEMY_GATE_THEATRE_PRIORITY_RADIUS)
    .filter((coord) => !sameHex(coord, gate.coord))
    .sort((first, second) => {
      const firstScore = scoreEnemyGateTheatreDefensePosition(state, unit, first, gate, plan) - hexDistance(unit.coord, first) * 3;
      const secondScore = scoreEnemyGateTheatreDefensePosition(state, unit, second, gate, plan) - hexDistance(unit.coord, second) * 3;
      return secondScore - firstScore || hexDistance(unit.coord, first) - hexDistance(unit.coord, second);
    })[0];
}

function isGateClearanceTarget(state: GameState, target: UnitInstance, gate: GateState, plan?: EnemyTurnPlan): boolean {
  if (target.owner !== "Player") {
    return false;
  }

  const distance = hexDistance(target.coord, gate.coord);
  if (distance > ENEMY_GATE_THEATRE_PRIORITY_RADIUS) {
    return false;
  }

  const definition = getUnitDefinition(target.type);
  const statsToGate = getEffectiveUnitStats(state, target.owner, target.type, target.level, target.coord, gate.coord);
  const canAttackGateTile =
    canUnitTargetUnit(target.type, "Infantry") &&
    hexDistance(target.coord, gate.coord) <= statsToGate.attackRange;
  if (canAttackGateTile) {
    return true;
  }

  if (canGateClearanceTargetKillReserveCapturer(state, target, gate, plan)) {
    return true;
  }

  const laneHexes = getGateSideHexes(state, gate);
  const blocksApproach =
    definition.domain === "Ground" &&
    (distance <= 2 || (distance <= ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS && laneHexes.has(hexId(target.coord))));
  if (blocksApproach) {
    return true;
  }

  const artilleryCoverage =
    target.type === "Artillery" &&
    (distance <= statsToGate.attackRange + 1 || canUnitProjectThreatToCoord(state, target, target.coord, gate.coord));
  if (artilleryCoverage) {
    return true;
  }

  const antiAirCoverage =
    target.type === "Anti-Air" &&
    (distance <= statsToGate.attackRange + 1 || distance <= ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS);
  if (antiAirCoverage) {
    return true;
  }

  const highValueDamaged =
    getUnitInstanceValue(state, target) >= 120 &&
    target.health / Math.max(1, target.maxHealth) <= 0.55 &&
    distance <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS;
  return highValueDamaged;
}

function canGateClearanceTargetKillReserveCapturer(state: GameState, target: UnitInstance, gate: GateState, plan?: EnemyTurnPlan): boolean {
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => {
      const mission = plan?.rolesByUnitId[unit.id];
      return (
        unit.health > 0 &&
        getUnitDefinition(unit.type).humanBased &&
        (mission === "ReserveCapturer" || (isEnemyGateLockoutReserveCapturer(unit.type) && hexDistance(unit.coord, gate.coord) <= 5))
      );
    })
    .some((reserve) => {
      if (!canUnitTargetUnit(target.type, reserve.type)) {
        return false;
      }
      const stats = getEffectiveUnitStats(state, target.owner, target.type, target.level, target.coord, reserve.coord);
      const reach = stats.attackRange + (getUnitDefinition(target.type).cannotMoveAndAttack ? 0 : stats.moveRange);
      if (hexDistance(target.coord, reserve.coord) > reach) {
        return false;
      }
      return estimateAttackDamage(state, target, reserve) >= reserve.health * 0.72;
    });
}

function shouldEnemyPreserveCriticalHold(state: GameState, unit: UnitInstance): boolean {
  if (!getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  if (sameHex(unit.coord, state.bases.Player) && state.baseOccupation.Player > 0) {
    return true;
  }
  return (state.gates ?? []).some((gate) => sameHex(unit.coord, gate.coord) && gate.occupation.Enemy > 0);
}

function shouldEnemyForbidRelocatingForAttack(state: GameState, unit: UnitInstance): boolean {
  if (shouldEnemyPreserveCriticalHold(state, unit)) {
    return true;
  }

  const occupiedGate = (state.gates ?? []).find((gate) => sameHex(gate.coord, unit.coord));
  return Boolean(occupiedGate && shouldEnemyNonCapturerHoldGateAsOnlyBlocker(state, unit, occupiedGate));
}

function shouldRevisitGateRoleHold(state: GameState, unitId: string, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  if (action.kind !== "Hold") {
    return false;
  }

  const unit = state.units.find((candidate) => candidate.id === unitId && candidate.owner === "Enemy");
  if (!unit || unit.hasMovedThisDay || unit.hasAttackedThisDay || !getUnitDefinition(unit.type).humanBased) {
    return false;
  }

  const role = plan.rolesByUnitId[unit.id];
  if (role !== "CaptureGate" && role !== "DefendGate" && role !== "ShadowCapturer" && role !== "EscortCapture") {
    return false;
  }

  if (role === "ShadowCapturer" || role === "EscortCapture") {
    return Boolean(chooseEnemyPlannerOpeningGateEscortMove(state, unit, plan));
  }

  const target = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
  return Boolean(target && !sameHex(unit.coord, target.coord));
}

function debugEnemyPlanner(message: string, details?: unknown): void {
  if (!isEnemyPlannerDebugEnabled()) {
    return;
  }
  if (details === undefined) {
    console.debug(ENEMY_AI_DEBUG_PREFIX, message);
  } else {
    console.debug(ENEMY_AI_DEBUG_PREFIX, message, details);
  }
}

function isEnemyPlannerDebugEnabled(): boolean {
  if (typeof window === "undefined") {
    return false;
  }
  try {
    return new URLSearchParams(window.location.search).get(ENEMY_PLANNER_DEBUG_PARAM) === "1";
  } catch {
    return false;
  }
}

function getNeutralEnemyPlayerStyleProfile(): EnemyPlayerStyleProfile {
  return {
    schemaVersion: 1,
    gamesObserved: 0,
    updatedAtDay: 0,
    preferredOpeningGateWest: 0.5,
    earlyGateCommitment: 0.5,
    baseRush: 0.5,
    gateDefense: 0.5,
    retreatValuableUnits: 0.5,
    sacrificeCapturer: 0.5,
    targetAir: 0.5,
    targetGround: 0.5,
    spendArmy: 0.5,
    spendEconomy: 0.5,
    spendTech: 0.5,
    concealBeforeCommit: 0.5
  };
}

function loadEnemyHistoricalPlayerProfile(): EnemyPlayerStyleProfile {
  if (typeof window === "undefined") {
    return getNeutralEnemyPlayerStyleProfile();
  }
  try {
    const raw = window.localStorage.getItem(ENEMY_PLANNER_PROFILE_KEY);
    if (!raw) {
      return getNeutralEnemyPlayerStyleProfile();
    }
    const parsed = JSON.parse(raw) as Partial<EnemyPlayerStyleProfile>;
    if (parsed.schemaVersion !== 1) {
      return getNeutralEnemyPlayerStyleProfile();
    }
    return {
      ...getNeutralEnemyPlayerStyleProfile(),
      ...parsed,
      schemaVersion: 1
    };
  } catch {
    return getNeutralEnemyPlayerStyleProfile();
  }
}

function saveEnemyHistoricalPlayerProfile(profile: EnemyPlayerStyleProfile): void {
  if (typeof window === "undefined") {
    return;
  }
  try {
    window.localStorage.setItem(ENEMY_PLANNER_PROFILE_KEY, JSON.stringify(profile));
  } catch {
    // localStorage is optional for the AI profile; failure must not affect play.
  }
}

function resetEnemyHistoricalPlayerProfile(): EnemyPlayerStyleProfile {
  const profile = getNeutralEnemyPlayerStyleProfile();
  if (typeof window !== "undefined") {
    try {
      window.localStorage.removeItem(ENEMY_PLANNER_PROFILE_KEY);
    } catch {
      // Harmless in private or locked-down storage contexts.
    }
  }
  return profile;
}

function updateEnemyHistoricalPlayerProfile(state: GameState): EnemyPlayerStyleProfile {
  const previous = loadEnemyHistoricalPlayerProfile();
  const visiblePlayerUnits = getVisiblePlayerUnitsForEnemy(state);
  const alpha = 0.12;
  const blend = (oldValue: number, sample: number): number => Math.max(0, Math.min(1, oldValue * (1 - alpha) + sample * alpha));
  const westGate = (state.gates ?? []).find((gate) => gate.id === "West");
  const eastGate = (state.gates ?? []).find((gate) => gate.id === "East");
  const earlyGateUnits = visiblePlayerUnits.filter(
    (unit) => getUnitDefinition(unit.type).humanBased && (state.gates ?? []).some((gate) => hexDistance(unit.coord, gate.coord) <= 5)
  );
  const westCommitment = westGate ? earlyGateUnits.filter((unit) => hexDistance(unit.coord, westGate.coord) <= 5).length : 0;
  const eastCommitment = eastGate ? earlyGateUnits.filter((unit) => hexDistance(unit.coord, eastGate.coord) <= 5).length : 0;
  const baseRushUnits = visiblePlayerUnits.filter(
    (unit) => getUnitDefinition(unit.type).humanBased && hexDistance(unit.coord, state.bases.Enemy) <= getEnemyBaseResponseRadius(state)
  ).length;
  const valuableDamaged = visiblePlayerUnits.filter(
    (unit) => getUnitInstanceValue(state, unit) > 80 && unit.health / Math.max(1, unit.maxHealth) < 0.45
  ).length;
  const playerAir = visiblePlayerUnits.filter((unit) => getUnitDefinition(unit.type).domain === "Air").length;
  const playerGround = visiblePlayerUnits.filter((unit) => getUnitDefinition(unit.type).domain === "Ground").length;
  const profile: EnemyPlayerStyleProfile = {
    ...previous,
    gamesObserved: Math.min(10_000, previous.gamesObserved + 1),
    updatedAtDay: state.day,
    preferredOpeningGateWest: blend(previous.preferredOpeningGateWest, westCommitment + eastCommitment > 0 ? westCommitment / Math.max(1, westCommitment + eastCommitment) : 0.5),
    earlyGateCommitment: blend(previous.earlyGateCommitment, Math.min(1, earlyGateUnits.length / 3)),
    baseRush: blend(previous.baseRush, Math.min(1, baseRushUnits / 2)),
    gateDefense: blend(previous.gateDefense, (state.gates ?? []).some((gate) => gate.owner === "Player" && visiblePlayerUnits.some((unit) => hexDistance(unit.coord, gate.coord) <= 4)) ? 1 : 0.35),
    retreatValuableUnits: blend(previous.retreatValuableUnits, valuableDamaged === 0 ? 0.58 : 0.25),
    sacrificeCapturer: blend(previous.sacrificeCapturer, visiblePlayerUnits.some((unit) => getUnitDefinition(unit.type).humanBased && unit.health <= unit.maxHealth * 0.25 && hexDistance(unit.coord, state.bases.Enemy) <= 4) ? 0.8 : 0.45),
    targetAir: blend(previous.targetAir, playerAir / Math.max(1, playerAir + playerGround)),
    targetGround: blend(previous.targetGround, playerGround / Math.max(1, playerAir + playerGround)),
    spendArmy: blend(previous.spendArmy, Math.min(1, visiblePlayerUnits.length / 8)),
    spendEconomy: blend(previous.spendEconomy, Math.min(1, (state.gates ?? []).filter((gate) => gate.owner === "Player").length / 2)),
    spendTech: blend(previous.spendTech, visiblePlayerUnits.filter((unit) => isSpecialUnit(unit.type)).length > 0 ? 0.75 : 0.45),
    concealBeforeCommit: blend(previous.concealBeforeCommit, visiblePlayerUnits.length <= 2 && state.day >= 8 ? 0.75 : 0.35)
  };
  saveEnemyHistoricalPlayerProfile(profile);
  return profile;
}

function blendOpponentProfileWithHistoricalPrior(current: OpponentProfile, historical: EnemyPlayerStyleProfile): OpponentProfile {
  const weight = ENEMY_PLAYER_STYLE_PRIOR_WEIGHT;
  const blend = (currentValue: number, historicalValue: number): number => currentValue * (1 - weight) + historicalValue * weight;
  const blended: OpponentProfile = {
    kind: current.kind,
    airBias: blend(current.airBias, historical.targetAir),
    groundBias: blend(current.groundBias, historical.targetGround),
    gateRush: blend(current.gateRush, historical.earlyGateCommitment),
    baseRush: blend(current.baseRush, historical.baseRush),
    turtle: blend(current.turtle, historical.gateDefense),
    fastSpecial: blend(current.fastSpecial, historical.spendTech),
    economyFirst: blend(current.economyFirst, historical.spendEconomy)
  };
  const scores: Record<OpponentProfileKind, number> = {
    AirHeavy: blended.airBias,
    GroundHeavy: blended.groundBias,
    GateRusher: blended.gateRush,
    BaseRusher: blended.baseRush,
    Turtle: blended.turtle,
    FastSpecial: blended.fastSpecial,
    EconomyFirst: blended.economyFirst,
    Balanced: 0.35
  };
  blended.kind = (Object.keys(scores) as OpponentProfileKind[]).sort((first, second) => scores[second] - scores[first] || first.localeCompare(second))[0];
  return blended;
}

function getVisiblePlayerUnitsForEnemy(state: GameState): UnitInstance[] {
  const visibleHexIds = getEnemyVisibleHexIds(state);
  return state.units.filter((unit) => unit.owner === "Player" && visibleHexIds.has(hexId(unit.coord)));
}

function getEnemyPlannerPlayerIntel(state: GameState): EnemyPlannerPlayerIntel[] {
  const visibleHexIds = getEnemyVisibleHexIds(state);
  const livePlayerUnitIds = new Set(state.units.filter((unit) => unit.owner === "Player").map((unit) => unit.id));
  const intelById = new Map<string, { unit: UnitInstance; lastSeenDay: number; observed: boolean }>();
  for (const unit of state.units) {
    if (unit.owner === "Player" && visibleHexIds.has(hexId(unit.coord))) {
      intelById.set(unit.id, {
        unit,
        lastSeenDay: state.day,
        observed: true
      });
    }
  }

  for (const spottedUnit of Object.values(state.spottedUnits?.Enemy ?? {})) {
    if (!livePlayerUnitIds.has(spottedUnit.id) || intelById.has(spottedUnit.id)) {
      continue;
    }
    intelById.set(spottedUnit.id, {
      unit: spottedUnitToUnitInstance(spottedUnit),
      lastSeenDay: spottedUnit.spottedDay,
      observed: false
    });
  }

  return Array.from(intelById.values())
    .map(({ unit, lastSeenDay, observed }) => {
      const age = Math.max(0, state.day - lastSeenDay);
      const likelyObjective = inferPlayerLikelyObjective(state, unit);
      const confidence = getIntelConfidence(age);
      const currentBeliefs = observed
        ? [{ coord: { ...unit.coord }, weight: 1 }]
        : buildEnemyPlannerBeliefRegion(state, unit, likelyObjective, age);
      const representative = chooseRepresentativeBeliefCoord(currentBeliefs);
      const reach = buildEnemyPlannerReachRegion(state, unit, currentBeliefs);
      const fireZone = buildEnemyPlannerFireZone(state, unit, currentBeliefs, false);
      const repositionZone = reach;
      const longTermProjection = buildEnemyPlannerBeliefRegion(state, { ...unit, coord: representative }, likelyObjective, Math.max(1, age + 2));
      return {
        unit,
        lastSeenDay,
        age,
        confidence,
        predictedCoord: representative,
        likelyObjective,
        observedCoord: observed ? { ...unit.coord } : undefined,
        lastSeenCoord: { ...unit.coord },
        currentBeliefs,
        nextTurnReach: reach,
        nextTurnFireZone: fireZone,
        nextTurnRepositionZone: repositionZone,
        longTermProjection
      };
    })
    .sort((first, second) => first.unit.id.localeCompare(second.unit.id));
}

function buildEnemyPlannerBeliefRegion(
  state: GameState,
  unit: UnitInstance,
  objective: PlayerLikelyObjective,
  age: number
): EnemyPlannerBeliefCoord[] {
  if (age <= 0) {
    return [{ coord: { ...unit.coord }, weight: 1 }];
  }
  const objectiveCoord = getPlayerObjectiveCoord(state, unit, objective);
  const currentDistance = hexDistance(unit.coord, objectiveCoord);
  const confidence = getIntelConfidence(age);
  const candidates = state.map.hexes
    .filter((hex) => {
      if (!hex.passable) {
        return false;
      }
      const effectiveMove = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, hex.coord).moveRange;
      return hexDistance(unit.coord, hex.coord) <= effectiveMove * Math.min(3, age);
    })
    .map((hex) => {
      const progress = currentDistance - hexDistance(hex.coord, objectiveCoord);
      const travel = hexDistance(unit.coord, hex.coord);
      const weight = Math.max(0.05, confidence * (1 + progress * 0.18) / Math.max(1, 1 + travel * 0.12));
      return {
        coord: { ...hex.coord },
        weight
      };
    })
    .sort((first, second) => second.weight - first.weight || hexId(first.coord).localeCompare(hexId(second.coord)))
    .slice(0, ENEMY_PLANNER_BELIEF_CAP);
  return normalizeEnemyPlannerBeliefs(candidates.length ? candidates : [{ coord: { ...unit.coord }, weight: 1 }]);
}

function buildEnemyPlannerReachRegion(
  state: GameState,
  unit: UnitInstance,
  beliefs: EnemyPlannerBeliefCoord[]
): EnemyPlannerBeliefCoord[] {
  const byHex = new Map<string, EnemyPlannerBeliefCoord>();
  for (const belief of beliefs) {
    for (const hex of state.map.hexes) {
      const effectiveMove = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, belief.coord, hex.coord).moveRange;
      if (!hex.passable || hexDistance(belief.coord, hex.coord) > effectiveMove) {
        continue;
      }
      const id = hex.id;
      const weight = belief.weight / Math.max(1, 1 + hexDistance(belief.coord, hex.coord));
      const existing = byHex.get(id);
      byHex.set(id, {
        coord: { ...hex.coord },
        weight: (existing?.weight ?? 0) + weight
      });
    }
  }
  return normalizeEnemyPlannerBeliefs(
    Array.from(byHex.values())
      .sort((first, second) => second.weight - first.weight || hexId(first.coord).localeCompare(hexId(second.coord)))
      .slice(0, ENEMY_PLANNER_BELIEF_CAP)
  );
}

function buildEnemyPlannerFireZone(
  state: GameState,
  unit: UnitInstance,
  beliefs: EnemyPlannerBeliefCoord[],
  includeTwoTurnSetup: boolean
): EnemyPlannerBeliefCoord[] {
  const attackOriginBeliefs = getUnitDefinition(unit.type).cannotMoveAndAttack
    ? beliefs
    : buildEnemyPlannerReachRegion(state, unit, beliefs);
  const setupWeight = includeTwoTurnSetup && getUnitDefinition(unit.type).cannotMoveAndAttack ? 0.35 : 1;
  const byHex = new Map<string, EnemyPlannerBeliefCoord>();
  for (const belief of attackOriginBeliefs) {
    for (const hex of state.map.hexes) {
      const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, belief.coord, hex.coord);
      if (hexDistance(belief.coord, hex.coord) > stats.attackRange) {
        continue;
      }
      const existing = byHex.get(hex.id);
      byHex.set(hex.id, {
        coord: { ...hex.coord },
        weight: (existing?.weight ?? 0) + belief.weight * setupWeight
      });
    }
  }
  return normalizeEnemyPlannerBeliefs(
    Array.from(byHex.values())
      .sort((first, second) => second.weight - first.weight || hexId(first.coord).localeCompare(hexId(second.coord)))
      .slice(0, ENEMY_PLANNER_BELIEF_CAP)
  );
}

function normalizeEnemyPlannerBeliefs(beliefs: EnemyPlannerBeliefCoord[]): EnemyPlannerBeliefCoord[] {
  const total = beliefs.reduce((sum, belief) => sum + belief.weight, 0);
  if (total <= 0) {
    return beliefs;
  }
  return beliefs.map((belief) => ({
    coord: { ...belief.coord },
    weight: belief.weight / total
  }));
}

function chooseRepresentativeBeliefCoord(beliefs: EnemyPlannerBeliefCoord[]): UnitInstance["coord"] {
  return [...beliefs].sort((first, second) => second.weight - first.weight || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord ?? { q: 0, r: 0 };
}

function chooseEnemyPlannerPrimaryObjective(state: GameState, assessment: EnemyStrategicAssessment): UnitInstance["coord"] {
  switch (assessment.strategicPhase) {
    case "BaseDefenseEmergency":
      return state.bases.Enemy;
    case "BothGatesOwned":
    case "BaseAssault":
    case "BaseHold":
      return state.bases.Player;
    case "OpeningGateRace":
    case "OneGateOwned":
    case "GateLockoutCombat":
    case "Recovery":
      return chooseGateObjective(state, "Enemy", state.bases.Enemy)?.coord ?? state.bases.Player;
  }
}

function chooseEnemyPlannerSecondaryObjective(state: GameState, assessment: EnemyStrategicAssessment): UnitInstance["coord"] | undefined {
  if (assessment.strategicPhase === "BaseDefenseEmergency") {
    return chooseGateObjective(state, "Enemy", state.bases.Enemy)?.coord;
  }
  if (assessment.strategicPhase === "BothGatesOwned" || assessment.strategicPhase === "BaseAssault" || assessment.strategicPhase === "BaseHold") {
    return chooseGateObjective(state, "Enemy", state.bases.Enemy)?.coord;
  }
  return ownerControlsBothGates(state, "Enemy") ? state.bases.Player : undefined;
}

function buildEnemyPlannerRoleAssignments(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  historicalProfile: EnemyPlayerStyleProfile
): Record<string, EnemyMission> {
  const assignments: Record<string, EnemyMission> = {};
  const units = getOwnerUnits(state, "Enemy").filter((unit) => unit.health > 0);
  const unassigned = (): UnitInstance[] => units.filter((unit) => !assignments[unit.id]);
  const assign = (unit: UnitInstance | undefined, mission: EnemyMission): void => {
    if (unit) {
      assignments[unit.id] = mission;
    }
  };
  const combatPressure = state.day > 10 ? getPlayerForwardPressure(state) : 0;
  const combatCrisis = usesHardEnemyDoctrine(state) && combatPressure >= ENEMY_COMBAT_PRESSURE_CRISIS_THRESHOLD;
  const gateLockout = usesHardEnemyDoctrine(state) && assessment.enemyGateCount === 0 && assessment.playerGateCount > 0 && assessment.strategicPhase !== "GateLockoutCombat";
  const lockoutCombatPressure = assessment.strategicPhase === "GateLockoutCombat" ? scoreEnemyGateLockoutCombatPressure(state, getPlayerIntelForEnemy(state)) : 0;
  const frontLineInterdiction = usesHardEnemyDoctrine(state) && assessment.gateLockoutLeverage > 70 && assessment.enemyGateCount < (state.gates ?? []).length;

  if (frontLineInterdiction) {
    const targetGates = [...(state.gates ?? [])]
      .filter((gate) => gate.owner !== "Enemy")
      .sort((first, second) => scoreEnemyGateRoleObjective(state, second) - scoreEnemyGateRoleObjective(state, first));
    const gateRoleLimit = assessment.gateLockoutLeverage > 190 ? 2 : 1;
    for (const gate of targetGates.slice(0, gateRoleLimit)) {
      const candidate = unassigned()
        .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.4)
        .sort((first, second) => scoreGateRoleCandidate(state, second, gate) - scoreGateRoleCandidate(state, first, gate))[0];
      assign(candidate, "CaptureGate");
    }
  }

  const baseThreat = getEnemyBaseThreat(state);
  const activeBaseThreat = isActiveEnemyBaseThreat(state, baseThreat);
  const defenseResponderLimit = getEnemyDefenseResponderLimit(state, assessment);
  if (activeBaseThreat && baseThreat) {
    unassigned()
      .filter((unit) => canUnitTargetUnit(unit.type, baseThreat.type))
      .sort((first, second) => scoreBaseDefenseCandidate(state, second, baseThreat.coord) - scoreBaseDefenseCandidate(state, first, baseThreat.coord))
      .slice(0, Math.min(defenseResponderLimit, frontLineInterdiction ? 1 : assessment.baseDefenseUrgency > 260 ? 4 : 2))
      .forEach((unit) => assign(unit, "DefendBase"));
  }

  if (usesHardEnemyDoctrine(state) && isEnemyBaseOperationPhase(assessment.strategicPhase) && isPlayerBaseExposedForHardAttack(state)) {
    assign(
      unassigned()
        .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.45)
        .sort((first, second) => scoreBaseAttackCandidate(state, second) - scoreBaseAttackCandidate(state, first))[0],
      "CaptureBase"
    );
  }

  preserveStableOpeningGateCaptureRoles(state, unassigned(), assignments);
  preserveActiveObjectiveClockRoles(state, unassigned(), assignments);
  assignOneGateFollowThroughCapturer(state, unassigned(), assignments);

  assignEnemyBaseSentryGroup(state, assessment, unassigned, assign, activeBaseThreat, baseThreat, frontLineInterdiction, Object.values(assignments).filter(isEnemyBaseDefenseResponderMission).length);

  if (usesHardEnemyDoctrine(state) && assessment.strategicPhase === "GateLockoutCombat") {
    assignEnemyGateLockoutCombatRoles(state, units, assignments);
    assignEnemyPreBaseEmergencySentryLine(state, assessment, units, assignments);
  }

  if (
    usesHardEnemyDoctrine(state) &&
    !gateLockout &&
    (combatPressure >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD || assessment.strategicPhase === "GateLockoutCombat")
  ) {
    assignEnemyCombatResponseRoles(state, unassigned(), assignments, Math.max(combatPressure, lockoutCombatPressure));
  }

  unassigned()
    .filter((unit) => shouldEnemyRetreatForRepair(state, unit))
    .forEach((unit) => assign(unit, "Repair"));

  const gateCandidates = [...(state.gates ?? [])]
    .filter((gate) => shouldAssignHardGateRole(state, gate))
    .sort((first, second) => scoreEnemyGateRoleObjective(state, second) - scoreEnemyGateRoleObjective(state, first));
  const exposedBaseAttack = isPlayerBaseExposedForHardAttack(state);
  const contestedOwnedGateCount = gateCandidates.filter((gate) => gate.owner === "Enemy" && gate.occupation.Player > 0).length;
  const activeGatePressure = hasActivePlayerGatePressure(state);
  const ordinaryGateRoleLimit =
    assessment.strategicPhase === "GateLockoutCombat"
      ? 2
      : frontLineInterdiction ? 2 : combatCrisis || exposedBaseAttack ? 0 : state.day <= 12 && assessment.enemyGateCount === 0 ? 2 : assessment.gateUrgency > assessment.baseAttackUrgency ? 2 : 1;
  const pressureGateRoleLimit = activeGatePressure && !exposedBaseAttack && assessment.strategicPhase !== "GateLockoutCombat" ? Math.min(2, gateCandidates.length) : 0;
  const gateRoleLimit = Math.max(contestedOwnedGateCount, pressureGateRoleLimit, ordinaryGateRoleLimit);
  for (const gate of gateCandidates.slice(0, gateRoleLimit)) {
      const candidate = unassigned()
        .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.4)
        .sort((first, second) => scoreGateRoleCandidate(state, second, gate) - scoreGateRoleCandidate(state, first, gate))[0];
      assign(candidate, gate.owner === "Enemy" ? "DefendGate" : "CaptureGate");
      assignEnemyGatePacketRoles(state, assessment, gate, units, assignments);
  }

  if (usesHardEnemyDoctrine(state) && state.day <= 16 && !exposedBaseAttack && (!combatCrisis || activeGatePressure)) {
    assignOpeningGateInfantry(state, unassigned(), assignments);
    assignOpeningGateSupport(state, unassigned(), assignments);
  }

  applyOpeningDoctrineRoleAssignments(state, assignments);

  if (!combatCrisis && state.day <= 12 && (state.gates ?? []).some((gate) => gate.owner === null)) {
    assign(
      unassigned()
        .filter((unit) => unit.type === "Infantry" && unit.health / Math.max(1, unit.maxHealth) > 0.45)
        .sort((first, second) => hexDistance(first.coord, state.bases.Player) - hexDistance(second.coord, state.bases.Player) || first.id.localeCompare(second.id))[0],
      "Escort"
    );
  }

  if (combatPressure < ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD) {
    assignOpeningPatrolScout(state, assignments, "West");
    assignOpeningPatrolScout(state, assignments, "East");
    assignBestPatrolScout(state, assignments, historicalProfile.preferredOpeningGateWest >= 0.5 ? "West" : "East");
    assignBestPatrolScout(state, assignments, historicalProfile.preferredOpeningGateWest >= 0.5 ? "East" : "West");
  }

  unassigned()
    .filter((unit) => unit.type === "Artillery" || unit.type === "Anti-Air")
    .forEach((unit) => assign(unit, "Siege"));

  const desiredBaseCapturers = !isEnemyBaseOperationPhase(assessment.strategicPhase)
    ? 0
    : combatCrisis
      ? 1
      : assessment.playerBaseVulnerability > 220
        ? 4
        : assessment.phase === "early"
          ? 2
          : 3;
  unassigned()
    .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.45)
    .sort((first, second) => scoreBaseAttackCandidate(state, second) - scoreBaseAttackCandidate(state, first))
    .slice(0, desiredBaseCapturers)
    .forEach((unit) => assign(unit, "CaptureBase"));

  if (usesHardEnemyDoctrine(state) && isEnemyBaseOperationPhase(assessment.strategicPhase)) {
    unassigned()
      .filter((unit) => isEnemyEndgamePushUnit(unit) && !isEnemySupplySupportUnit(unit.type))
      .forEach((unit) => assign(unit, "Siege"));
  }

  unassigned()
    .filter((unit) => isReconUnit(unit.type))
    .forEach((unit) => assign(unit, "Scout"));

  return assignments;
}

function resolveEnemyCampaignPlan(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  assessment: EnemyStrategicAssessment,
  playerIntel: EnemyPlannerPlayerIntel[]
): EnemyCampaignPlan {
  const previous = (state as GameStateWithEnemyCampaign).enemyCampaignPlan;
  const phase = resolveEnemyStrategicPhase(state, assessment, playerIntel);
  const gates = [...(state.gates ?? [])];
  const objectiveClock = estimateEnemyObjectiveClocks(state, playerIntel);
  const invalidationKey = buildEnemyCampaignInvalidationKey(state, rolesByUnitId, phase, objectiveClock, playerIntel);
  if (previous && !isEnemyCampaignPlanInvalidated(state, previous, invalidationKey)) {
    const refreshed = refreshEnemyCampaignPlanContinuity(state, previous, phase, objectiveClock, invalidationKey);
    return refreshed;
  }

  const scoredGates = gates
    .map((gate) => ({
      gate,
      score:
        scoreEnemyGateRoleObjective(state, gate) +
        (previous?.mainEffortGateId === gate.id ? 45 : 0) +
        (gate.owner !== "Enemy" ? 80 : 0) +
        (gate.occupation.Player > 0 ? 70 : 0)
    }))
    .sort((first, second) => second.score - first.score || first.gate.id.localeCompare(second.gate.id));
  const gateEffortPlan = resolveEnemyGateEffortPlan(state, phase, scoredGates, previous, objectiveClock, rolesByUnitId);
  const mainEffortGateId = gateEffortPlan.mainEffortGateId;
  const secondaryGateId = gateEffortPlan.secondaryGateId;
  const assignedGateByUnitId: Record<string, GateState["id"]> = {};

  for (const unit of getOwnerUnits(state, "Enemy")) {
    const mission = rolesByUnitId[unit.id];
    const canHoldStableGate =
      isEnemyOpeningLaneMission(state, unit, mission) &&
      isEnemyCampaignAssignedGateStillValid(state, unit, previous?.assignedGateByUnitId[unit.id], objectiveClock);
    const assignedGate = canHoldStableGate
      ? previous?.assignedGateByUnitId[unit.id]
      : chooseEnemyCampaignGateForUnit(state, unit, rolesByUnitId, mainEffortGateId, secondaryGateId, objectiveClock);
    if (assignedGate) {
      assignedGateByUnitId[unit.id] = assignedGate;
    }
  }
  applyOpeningDoctrineGateAssignments(state, rolesByUnitId, assignedGateByUnitId);
  applyEnemyGateEffortAssignments(state, rolesByUnitId, assignedGateByUnitId, gateEffortPlan);

  const laneTaskForces: Record<GateState["id"], EnemyLaneTaskForcePlan> = {
    West: createEnemyLaneTaskForcePlan(state, "West", assignedGateByUnitId, rolesByUnitId, previous?.laneTaskForces.West),
    East: createEnemyLaneTaskForcePlan(state, "East", assignedGateByUnitId, rolesByUnitId, previous?.laneTaskForces.East)
  };
  assignEnemyActiveMainEffortBestCapturer(state, mainEffortGateId, assignedGateByUnitId, laneTaskForces, rolesByUnitId);
  const baseAssaultPackage = createEnemyBaseAssaultPackage(state, rolesByUnitId, previous?.baseAssaultPackage);
  const campaignPlan: EnemyCampaignPlan = {
    schemaVersion: 1,
    day: state.day,
    generatedDay: state.day,
    invalidationKey,
    phase,
    mainEffortGateId,
    secondaryGateId,
    assignedCapturerByGateId: getEnemyCampaignLaneField(laneTaskForces, "principalCapturerId"),
    backupCapturerByGateId: getEnemyCampaignLaneField(laneTaskForces, "backupCapturerId"),
    escortGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "escortIds"),
    scoutGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "scoutIds"),
    supportGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "supportIds"),
    baseAssaultPackage,
    assignedGateByUnitId,
    laneTaskForces,
    baseAssaultRoute: findEnemyBaseAssaultRoute(state),
    expectedTurnsToCapture: objectiveClock.enemyTurnsToGates,
    objectiveClock
  };
  return campaignPlan;
}

function assignEnemyActiveMainEffortBestCapturer(
  state: GameState,
  mainEffortGateId: GateState["id"] | undefined,
  assignedGateByUnitId: Record<string, GateState["id"]>,
  laneTaskForces: Record<GateState["id"], EnemyLaneTaskForcePlan>,
  rolesByUnitId: Record<string, EnemyMission>
): void {
  const gate = mainEffortGateId ? (state.gates ?? []).find((candidate) => candidate.id === mainEffortGateId) : undefined;
  if (!gate || state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY || gate.owner === "Enemy" || gate.occupation.Enemy <= 0) {
    return;
  }

  const capturer = getOwnerUnits(state, "Enemy")
    .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => isEnemyGateEffortUnitMission(rolesByUnitId[unit.id], unit))
    .filter((unit) => isEnemyAssignedGateReachable(state, unit, gate))
    .sort((first, second) => scoreEnemyGateEffortCapturerCandidate(state, second, gate) - scoreEnemyGateEffortCapturerCandidate(state, first, gate) || first.id.localeCompare(second.id))[0];
  if (!capturer) {
    return;
  }

  assignedGateByUnitId[capturer.id] = gate.id;
  laneTaskForces[gate.id].principalCapturerId = capturer.id;
  if (laneTaskForces[gate.id].backupCapturerId === capturer.id) {
    laneTaskForces[gate.id].backupCapturerId = undefined;
  }
}

function isEnemyCampaignPlanInvalidated(state: GameState, plan: EnemyCampaignPlan, invalidationKey: string): boolean {
  if (plan.schemaVersion !== 1 || plan.invalidationKey !== invalidationKey) {
    return true;
  }
  const liveUnitIds = new Set(getOwnerUnits(state, "Enemy").map((unit) => unit.id));
  const liveGateIds = new Set((state.gates ?? []).map((gate) => gate.id));
  if (plan.mainEffortGateId && !liveGateIds.has(plan.mainEffortGateId)) {
    return true;
  }
  if (plan.secondaryGateId && !liveGateIds.has(plan.secondaryGateId)) {
    return true;
  }
  if (ownerControlsBothGates(state, "Enemy") && !isEnemyBaseAssaultPackageReady(plan.baseAssaultPackage)) {
    return true;
  }
  return Object.keys(plan.assignedGateByUnitId).some((unitId) => !liveUnitIds.has(unitId));
}

function isEnemyBaseAssaultPackageReady(packagePlan: EnemyBaseAssaultPackage | undefined): boolean {
  return Boolean(
    packagePlan?.capturerId &&
      packagePlan.backupCapturerId &&
      packagePlan.scoutId &&
      packagePlan.blockerEscortIds.length >= 1 &&
      packagePlan.damageDealerIds.length >= 1
  );
}

interface EnemyGateEffortPlan {
  mainEffortGateId?: GateState["id"];
  secondaryGateId?: GateState["id"];
  pressureBothGates: boolean;
}

function resolveEnemyGateEffortPlan(
  state: GameState,
  phase: EnemyStrategicPhase,
  scoredGates: Array<{ gate: GateState; score: number }>,
  previous: EnemyCampaignPlan | undefined,
  objectiveClock: EnemyObjectiveClockEstimate,
  rolesByUnitId: Record<string, EnemyMission>
): EnemyGateEffortPlan {
  const followThroughGates = isEnemyMidGameGateEffortPhase(state, phase)
    ? scoredGates.filter((entry) => entry.gate.owner !== "Enemy")
    : scoredGates;
  const topGate =
    phase === "OpeningGateRace"
      ? chooseEnemyOpeningMainEffortGate(state, followThroughGates.length ? followThroughGates : scoredGates, objectiveClock)?.gate
      : followThroughGates[0]?.gate ?? scoredGates[0]?.gate;
  const previousMainGate = previous?.mainEffortGateId ? (state.gates ?? []).find((gate) => gate.id === previous.mainEffortGateId) : undefined;
  const keepPreviousMain =
    previousMainGate &&
    isEnemyMidGameGateEffortPhase(state, phase) &&
    shouldKeepEnemyPreviousMainEffortGate(state, previousMainGate, scoredGates, objectiveClock);
  const mainEffortGateId = keepPreviousMain ? previousMainGate.id : topGate?.id;
  const secondaryGateId = (followThroughGates.find((entry) => entry.gate.id !== mainEffortGateId) ?? scoredGates.find((entry) => entry.gate.id !== mainEffortGateId))?.gate.id;
  return {
    mainEffortGateId,
    secondaryGateId,
    pressureBothGates: isEnemyMidGameGateEffortPhase(state, phase) && canEnemyPressureBothGates(state, rolesByUnitId)
  };
}

function chooseEnemyOpeningMainEffortGate(
  state: GameState,
  candidates: Array<{ gate: GateState; score: number }>,
  objectiveClock: EnemyObjectiveClockEstimate
): { gate: GateState; score: number } | undefined {
  const best = candidates[0];
  const preferred = candidates.find((entry) => entry.gate.id === getEnemySeededOpeningMainEffortGateId(state));
  if (!best || !preferred || best.gate.id === preferred.gate.id) {
    return best ?? preferred;
  }

  if (isEnemyOpeningGateObjectivelyUrgent(best.gate, objectiveClock)) {
    return best;
  }

  return best.score > preferred.score + 220 ? best : preferred;
}

function isEnemyOpeningGateObjectivelyUrgent(gate: GateState, objectiveClock: EnemyObjectiveClockEstimate): boolean {
  return (
    (objectiveClock.enemyTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY) <= 1 ||
    (objectiveClock.playerTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY) <= 1 ||
    gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1 ||
    gate.occupation.Player >= GATE_CAPTURE_DAYS - 1
  );
}

function isEnemyMidGameGateEffortPhase(state: GameState, phase: EnemyStrategicPhase): boolean {
  return (
    state.difficulty === "Hard" &&
    state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY &&
    !ownerControlsBothGates(state, "Enemy") &&
    isEnemyGateContinuityPhase(phase)
  );
}

function shouldKeepEnemyPreviousMainEffortGate(
  state: GameState,
  previousMainGate: GateState,
  scoredGates: Array<{ gate: GateState; score: number }>,
  objectiveClock: EnemyObjectiveClockEstimate
): boolean {
  if (previousMainGate.owner === "Enemy" && previousMainGate.occupation.Player <= 0) {
    return false;
  }
  const previousScore = scoredGates.find((entry) => entry.gate.id === previousMainGate.id)?.score ?? Number.NEGATIVE_INFINITY;
  const urgentOtherGate = scoredGates.find((entry) => {
    if (entry.gate.id === previousMainGate.id) {
      return false;
    }
    return (
      (objectiveClock.enemyTurnsToGates[entry.gate.id] ?? Number.POSITIVE_INFINITY) <= 1 ||
      (objectiveClock.playerTurnsToGates[entry.gate.id] ?? Number.POSITIVE_INFINITY) <= 1 ||
      entry.gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1 ||
      entry.gate.occupation.Player >= GATE_CAPTURE_DAYS - 1
    );
  });
  if (urgentOtherGate) {
    return false;
  }
  const bestOtherScore = scoredGates.find((entry) => entry.gate.id !== previousMainGate.id)?.score ?? Number.NEGATIVE_INFINITY;
  return bestOtherScore < previousScore + 220;
}

function canEnemyPressureBothGates(state: GameState, rolesByUnitId: Record<string, EnemyMission>): boolean {
  const units = getOwnerUnits(state, "Enemy").filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.4);
  const capturers = units.filter((unit) => getUnitDefinition(unit.type).humanBased && isEnemyGateEffortUnitMission(rolesByUnitId[unit.id], unit));
  const armorSupport = units.filter((unit) => unit.type === "Tank" || unit.type === "IFV");
  const scouts = units.filter((unit) => isReconUnit(unit.type) && !getUnitDefinition(unit.type).humanBased);
  return capturers.length >= 2 && armorSupport.length >= 2 && scouts.length >= 2;
}

function applyEnemyGateEffortAssignments(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  assignedGateByUnitId: Record<string, GateState["id"]>,
  effortPlan: EnemyGateEffortPlan
): void {
  if (!effortPlan.mainEffortGateId || !isEnemyMidGameGateEffortPhase(state, resolveEnemyStrategicPhase(state, getEnemyStrategicAssessment(state), getEnemyPlannerPlayerIntel(state)))) {
    return;
  }
  const mainGate = (state.gates ?? []).find((gate) => gate.id === effortPlan.mainEffortGateId);
  const secondaryGate = effortPlan.secondaryGateId ? (state.gates ?? []).find((gate) => gate.id === effortPlan.secondaryGateId) : undefined;
  if (!mainGate) {
    return;
  }

  const units = getOwnerUnits(state, "Enemy")
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => isEnemyGateEffortUnitMission(rolesByUnitId[unit.id], unit));
  for (const unit of units) {
    delete assignedGateByUnitId[unit.id];
  }

  const used = new Set<string>();
  const assign = (unit: UnitInstance | undefined, gate: GateState | undefined): void => {
    if (!unit || !gate || used.has(unit.id) || !isEnemyAssignedGateReachable(state, unit, gate)) {
      return;
    }
    assignedGateByUnitId[unit.id] = gate.id;
    used.add(unit.id);
  };
  const bestForGate = <T extends UnitInstance>(candidates: T[], gate: GateState, scorer: (state: GameState, unit: T, gate: GateState) => number): T | undefined =>
    candidates
      .filter((unit) => !used.has(unit.id))
      .filter((unit) => isEnemyAssignedGateReachable(state, unit, gate))
      .sort((first, second) => scorer(state, second, gate) - scorer(state, first, gate) || first.id.localeCompare(second.id))[0];

  const capturers = units.filter((unit) => getUnitDefinition(unit.type).humanBased);
  const armorSupport = units.filter((unit) => unit.type === "Tank" || unit.type === "IFV");
  const fireSupport = units.filter((unit) => isEnemyGatePacketFireSupportUnit(unit.type));
  const scouts = units.filter((unit) => isReconUnit(unit.type) && !getUnitDefinition(unit.type).humanBased);
  const assessment = getEnemyStrategicAssessment(state);
  const assignedCount = (gate: GateState): number => Object.entries(assignedGateByUnitId).filter(([unitId, gateId]) => gateId === gate.id && used.has(unitId)).length;
  const assignIfPacketNeeds = (unit: UnitInstance | undefined, gate: GateState): void => {
    if (assignedCount(gate) < getEnemyGatePacketTargetSize(state, assessment, gate)) {
      assign(unit, gate);
    }
  };
  const fillPacketCore = (gate: GateState): void => {
    assignIfPacketNeeds(bestForGate(capturers, gate, scoreEnemyGateEffortCapturerCandidate), gate);
    assignIfPacketNeeds(bestForGate(armorSupport, gate, scoreEnemyGateEffortSupportCandidate), gate);
    assignIfPacketNeeds(bestForGate([...fireSupport, ...scouts], gate, scoreEnemyGateEffortScoutCandidate), gate);
  };
  const fillPacketExtras = (gate: GateState): void => {
    if (shouldEnemyGatePacketUseBackup(state, assessment, gate)) {
      assignIfPacketNeeds(bestForGate(capturers, gate, scoreEnemyGateEffortCapturerCandidate), gate);
    }
    while (assignedCount(gate) < getEnemyGatePacketTargetSize(state, assessment, gate)) {
      const support = bestForGate([...armorSupport, ...fireSupport, ...scouts], gate, scoreEnemyGateEffortHarasserCandidate);
      if (!support) {
        break;
      }
      assign(support, gate);
    }
  };
  const fillPacket = (gate: GateState): void => {
    fillPacketCore(gate);
    fillPacketExtras(gate);
  };

  if (secondaryGate && effortPlan.pressureBothGates) {
    fillPacketCore(mainGate);
    fillPacketCore(secondaryGate);
    fillPacketExtras(mainGate);
    fillPacketExtras(secondaryGate);
  } else {
    fillPacket(mainGate);
  }

  if (secondaryGate && !effortPlan.pressureBothGates) {
    assign(bestForGate([...scouts, ...armorSupport], secondaryGate, scoreEnemyGateEffortHarasserCandidate), secondaryGate);
  }
}

function isEnemyGateEffortUnitMission(mission: EnemyMission | undefined, unit: UnitInstance): boolean {
  if (mission === "CaptureBase" || mission === "DefendBase" || mission === "BaseSentry" || mission === "Repair" || mission === "ProtectCapturer" || isEnemyGateLockoutCombatMission(mission)) {
    return false;
  }
  return (
    mission === "CaptureGate" ||
    mission === "ShadowCapturer" ||
    mission === "EscortCapture" ||
    mission === "DefendGate" ||
    mission === "Escort" ||
    mission === "Scout" ||
    mission === "PatrolWest" ||
    mission === "PatrolEast" ||
    (mission === "Siege" && (unit.type === "Tank" || unit.type === "IFV")) ||
    getUnitDefinition(unit.type).humanBased ||
    unit.type === "Tank" ||
    unit.type === "IFV" ||
    (isReconUnit(unit.type) && !getUnitDefinition(unit.type).humanBased)
  );
}

function scoreEnemyGateEffortCapturerCandidate(state: GameState, unit: UnitInstance, gate: GateState): number {
  return getUnitInstanceValue(state, unit) * 0.5 + unit.health * 3 - hexDistance(unit.coord, gate.coord) * 14 + (unit.type === "Ghost" ? 90 : unit.type === "Operator" ? 55 : 0);
}

function scoreEnemyGateEffortSupportCandidate(state: GameState, unit: UnitInstance, gate: GateState): number {
  return getUnitInstanceValue(state, unit) * 0.45 + unit.health * 2 - hexDistance(unit.coord, gate.coord) * 12 + (unit.type === "Tank" ? 55 : 35);
}

function scoreEnemyGateEffortScoutCandidate(state: GameState, unit: UnitInstance, gate: GateState): number {
  const stats = getUnitDefinition(unit.type);
  return stats.visibilityRange * 20 + stats.moveRange * 12 + getUnitInstanceValue(state, unit) * 0.12 - hexDistance(unit.coord, gate.coord) * 10;
}

function scoreEnemyGateEffortHarasserCandidate(state: GameState, unit: UnitInstance, gate: GateState): number {
  return scoreEnemyGateEffortSupportCandidate(state, unit, gate) + (isReconUnit(unit.type) ? 65 : 0) - (unit.type === "Tank" ? 20 : 0);
}

function refreshEnemyCampaignPlanContinuity(
  state: GameState,
  previous: EnemyCampaignPlan,
  phase: EnemyStrategicPhase,
  objectiveClock: EnemyObjectiveClockEstimate,
  invalidationKey: string
): EnemyCampaignPlan {
  const liveUnitIds = new Set(getOwnerUnits(state, "Enemy").map((unit) => unit.id));
  const assignedGateByUnitId = Object.fromEntries(
    Object.entries(previous.assignedGateByUnitId).filter(([unitId]) => liveUnitIds.has(unitId))
  ) as Record<string, GateState["id"]>;
  const laneTaskForces: Record<GateState["id"], EnemyLaneTaskForcePlan> = {
    West: refreshEnemyLaneTaskForcePlan(previous.laneTaskForces.West, liveUnitIds),
    East: refreshEnemyLaneTaskForcePlan(previous.laneTaskForces.East, liveUnitIds)
  };
  return {
    ...previous,
    day: state.day,
    phase,
    invalidationKey,
    assignedGateByUnitId,
    laneTaskForces,
    assignedCapturerByGateId: getEnemyCampaignLaneField(laneTaskForces, "principalCapturerId"),
    backupCapturerByGateId: getEnemyCampaignLaneField(laneTaskForces, "backupCapturerId"),
    escortGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "escortIds"),
    scoutGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "scoutIds"),
    supportGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "supportIds"),
    baseAssaultPackage: refreshEnemyBaseAssaultPackage(previous.baseAssaultPackage ?? createEmptyEnemyBaseAssaultPackage(), liveUnitIds),
    expectedTurnsToCapture: objectiveClock.enemyTurnsToGates,
    objectiveClock
  };
}

function refreshEnemyLaneTaskForcePlan(plan: EnemyLaneTaskForcePlan, liveUnitIds: Set<string>): EnemyLaneTaskForcePlan {
  const keep = (id: string | undefined): string | undefined => id && liveUnitIds.has(id) ? id : undefined;
  const keepGroup = (ids: string[]): string[] => ids.filter((id) => liveUnitIds.has(id));
  return {
    ...plan,
    principalCapturerId: keep(plan.principalCapturerId),
    backupCapturerId: keep(plan.backupCapturerId),
    escortIds: keepGroup(plan.escortIds),
    scoutIds: keepGroup(plan.scoutIds),
    supportIds: keepGroup(plan.supportIds)
  };
}

function getEnemyCampaignLaneField(
  laneTaskForces: Record<GateState["id"], EnemyLaneTaskForcePlan>,
  field: "principalCapturerId" | "backupCapturerId"
): Partial<Record<GateState["id"], string>> {
  return Object.fromEntries(
    (Object.entries(laneTaskForces) as Array<[GateState["id"], EnemyLaneTaskForcePlan]>)
      .map(([gateId, lane]) => [gateId, lane[field]])
      .filter((entry): entry is [GateState["id"], string] => Boolean(entry[1]))
  );
}

function getEnemyCampaignLaneGroup(
  laneTaskForces: Record<GateState["id"], EnemyLaneTaskForcePlan>,
  field: "escortIds" | "scoutIds" | "supportIds"
): Partial<Record<GateState["id"], string[]>> {
  return Object.fromEntries(
    (Object.entries(laneTaskForces) as Array<[GateState["id"], EnemyLaneTaskForcePlan]>).map(([gateId, lane]) => [gateId, [...lane[field]]])
  ) as Partial<Record<GateState["id"], string[]>>;
}

function createEmptyEnemyBaseAssaultPackage(): EnemyBaseAssaultPackage {
  return {
    blockerEscortIds: [],
    damageDealerIds: []
  };
}

function refreshEnemyBaseAssaultPackage(packagePlan: EnemyBaseAssaultPackage, liveUnitIds: Set<string>): EnemyBaseAssaultPackage {
  const keep = (id: string | undefined): string | undefined => id && liveUnitIds.has(id) ? id : undefined;
  const keepGroup = (ids: string[]): string[] => ids.filter((id) => liveUnitIds.has(id));
  return {
    capturerId: keep(packagePlan.capturerId),
    backupCapturerId: keep(packagePlan.backupCapturerId),
    scoutId: keep(packagePlan.scoutId),
    blockerEscortIds: keepGroup(packagePlan.blockerEscortIds),
    damageDealerIds: keepGroup(packagePlan.damageDealerIds),
    clearBaseTileTargetId: packagePlan.clearBaseTileTargetId
  };
}

function createEnemyBaseAssaultPackage(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  previous?: EnemyBaseAssaultPackage
): EnemyBaseAssaultPackage {
  if (!ownerControlsBothGates(state, "Enemy")) {
    return createEmptyEnemyBaseAssaultPackage();
  }

  const liveUnits = getOwnerUnits(state, "Enemy").filter((unit) => unit.health > 0);
  const unitById = new Map(liveUnits.map((unit) => [unit.id, unit]));
  const packagePlan: EnemyBaseAssaultPackage = createEmptyEnemyBaseAssaultPackage();
  const used = new Set<string>();
  const baseTileTarget = getPlayerBaseTileBlocker(state) ?? getPlayerBaseAreaDefender(state);
  const keep = (id: string | undefined, predicate: (unit: UnitInstance) => boolean): UnitInstance | undefined => {
    const unit = id ? unitById.get(id) : undefined;
    return unit && !used.has(unit.id) && predicate(unit) ? unit : undefined;
  };
  const take = (unit: UnitInstance | undefined): UnitInstance | undefined => {
    if (unit) {
      used.add(unit.id);
    }
    return unit;
  };

  const capturer = take(
    keep(previous?.capturerId, isBaseAssaultCapturerCandidate) ??
      liveUnits
        .filter(isBaseAssaultCapturerCandidate)
        .sort((first, second) => scoreBaseAssaultCapturerPackageCandidate(state, second) - scoreBaseAssaultCapturerPackageCandidate(state, first) || first.id.localeCompare(second.id))[0]
  );
  packagePlan.capturerId = capturer?.id;

  const backup = take(
    keep(previous?.backupCapturerId, isBaseAssaultCapturerCandidate) ??
      liveUnits
        .filter((unit) => !used.has(unit.id))
        .filter(isBaseAssaultCapturerCandidate)
        .sort((first, second) => scoreBaseAssaultCapturerPackageCandidate(state, second) - scoreBaseAssaultCapturerPackageCandidate(state, first) || first.id.localeCompare(second.id))[0]
  );
  packagePlan.backupCapturerId = backup?.id;

  const scout = take(
    keep(previous?.scoutId, isBaseAssaultScoutCandidate) ??
      liveUnits
        .filter((unit) => !used.has(unit.id))
        .filter(isBaseAssaultScoutCandidate)
        .sort((first, second) => scoreBaseAssaultScoutPackageCandidate(state, second) - scoreBaseAssaultScoutPackageCandidate(state, first) || first.id.localeCompare(second.id))[0]
  );
  packagePlan.scoutId = scout?.id;

  packagePlan.blockerEscortIds = [
    ...(previous?.blockerEscortIds ?? [])
      .map((id) => keep(id, isBaseAssaultBlockerEscortCandidate))
      .filter((unit): unit is UnitInstance => Boolean(unit))
      .map((unit) => take(unit)!.id),
    ...liveUnits
      .filter((unit) => !used.has(unit.id))
      .filter(isBaseAssaultBlockerEscortCandidate)
      .sort((first, second) => scoreBaseAssaultBlockerPackageCandidate(state, second) - scoreBaseAssaultBlockerPackageCandidate(state, first) || first.id.localeCompare(second.id))
      .slice(0, Math.max(0, 2 - (previous?.blockerEscortIds ?? []).length))
      .map((unit) => take(unit)!.id)
  ].filter((id, index, ids) => ids.indexOf(id) === index).slice(0, 2);

  packagePlan.damageDealerIds = [
    ...(previous?.damageDealerIds ?? [])
      .map((id) => keep(id, (unit) => isBaseAssaultDamageDealerCandidate(state, unit, baseTileTarget)))
      .filter((unit): unit is UnitInstance => Boolean(unit))
      .map((unit) => take(unit)!.id),
    ...liveUnits
      .filter((unit) => !used.has(unit.id))
      .filter((unit) => isBaseAssaultDamageDealerCandidate(state, unit, baseTileTarget))
      .sort((first, second) => scoreBaseAssaultDamageDealerPackageCandidate(state, second, baseTileTarget) - scoreBaseAssaultDamageDealerPackageCandidate(state, first, baseTileTarget) || first.id.localeCompare(second.id))
      .slice(0, Math.max(0, 3 - (previous?.damageDealerIds ?? []).length))
      .map((unit) => take(unit)!.id)
  ].filter((id, index, ids) => ids.indexOf(id) === index).slice(0, 3);
  packagePlan.clearBaseTileTargetId = baseTileTarget?.id;

  return packagePlan;
}

function getPlayerBaseTileBlocker(state: GameState): UnitInstance | undefined {
  return getOwnerUnits(state, "Player").find((unit) => sameHex(unit.coord, state.bases.Player));
}

function getPlayerBaseAreaDefender(state: GameState): UnitInstance | undefined {
  return getOwnerUnits(state, "Player")
    .filter((unit) => hexDistance(unit.coord, state.bases.Player) <= 3)
    .sort((first, second) => hexDistance(first.coord, state.bases.Player) - hexDistance(second.coord, state.bases.Player) || getUnitInstanceValue(state, second) - getUnitInstanceValue(state, first))[0];
}

function isPlayerBaseAreaAssaultTarget(state: GameState, target: UnitInstance): boolean {
  if (target.owner !== "Player") {
    return false;
  }
  const assaultMinRow = getPlayerBaseAssaultAreaMinRow(state);
  return (
    sameHex(target.coord, state.bases.Player) ||
    hexDistance(target.coord, state.bases.Player) <= 7 ||
    target.coord.r >= assaultMinRow - 2
  );
}

function getPlayerBaseAssaultAreaMinRow(state: GameState): number {
  return Math.min(state.bases.Player.r - 1, getFrontLineRows(state).playerLineRow);
}

function isCoordInPlayerBaseAssaultArea(state: GameState, coord: UnitInstance["coord"]): boolean {
  return coord.r >= getPlayerBaseAssaultAreaMinRow(state);
}

function scoreEnemyPlayerBaseAreaTargetPriority(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance,
  plan: EnemyTurnPlan | undefined
): number {
  if (!isPlayerBaseAreaAssaultTarget(state, target) || !canUnitTargetUnit(unit.type, target.type)) {
    return 0;
  }

  const distanceToBase = hexDistance(target.coord, state.bases.Player);
  const baseTile = sameHex(target.coord, state.bases.Player) ? 1800 : 0;
  const baseRing = Math.max(0, 7 - distanceToBase) * 170;
  const assaultMinRow = getPlayerBaseAssaultAreaMinRow(state);
  const playerArea = isCoordInPlayerBaseAssaultArea(state, target.coord) ? 760 : Math.max(0, target.coord.r - (assaultMinRow - 2)) * 120;
  const rowPressure = Math.max(0, target.coord.r - (assaultMinRow - 2)) * 85;
  const supportAsset = isEnemySupplySupportUnit(target.type) ? (target.type === "Command Heli" ? 640 : 560) : target.type === "Artillery" || target.type === "Anti-Air" ? 360 : isReconUnit(target.type) ? 220 : 0;
  const productionDefense = plan && isEnemyBaseOperationPhase(plan.campaignPlan.phase) ? 480 : 0;
  return baseTile + baseRing + playerArea + rowPressure + supportAsset + productionDefense + getUnitInstanceValue(state, target) * 0.55;
}

function isBaseAssaultCapturerCandidate(unit: UnitInstance): boolean {
  return getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.4;
}

function isBaseAssaultScoutCandidate(unit: UnitInstance): boolean {
  return isReconUnit(unit.type) && unit.health / Math.max(1, unit.maxHealth) > 0.35;
}

function isBaseAssaultBlockerEscortCandidate(unit: UnitInstance): boolean {
  return unit.health / Math.max(1, unit.maxHealth) > 0.4 && (getUnitDefinition(unit.type).humanBased || unit.type === "Tank" || unit.type === "IFV" || unit.type === "Reaper");
}

function isBaseAssaultDamageDealerCandidate(state: GameState, unit: UnitInstance, target: UnitInstance | undefined): boolean {
  if (unit.health / Math.max(1, unit.maxHealth) <= 0.3) {
    return false;
  }
  if (target) {
    return canUnitTargetUnit(unit.type, target.type);
  }
  return unit.type === "Tank" || unit.type === "Artillery" || unit.type === "Bomber" || unit.type === "Reaper" || unit.type === "Operator" || unit.type === "Ghost";
}

function scoreBaseAssaultCapturerPackageCandidate(state: GameState, unit: UnitInstance): number {
  return scoreBaseAttackCandidate(state, unit) + (unit.type === "Ghost" ? 70 : unit.type === "Operator" ? 45 : 0) + unit.health * 3;
}

function scoreBaseAssaultScoutPackageCandidate(state: GameState, unit: UnitInstance): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, state.bases.Player);
  return stats.visibilityRange * 14 + stats.moveRange * 10 - hexDistance(unit.coord, state.bases.Player) * 6 + getUnitInstanceValue(state, unit) * 0.12;
}

function scoreBaseAssaultBlockerPackageCandidate(state: GameState, unit: UnitInstance): number {
  return getUnitInstanceValue(state, unit) * 0.28 + unit.health * 2 + (unit.type === "Tank" || unit.type === "Reaper" ? 80 : 0) - hexDistance(unit.coord, state.bases.Player) * 5;
}

function scoreBaseAssaultDamageDealerPackageCandidate(state: GameState, unit: UnitInstance, target: UnitInstance | undefined): number {
  const range = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, state.bases.Player).attackRange;
  const damage = target ? estimateAttackDamage(state, unit, target) : getUnitInstanceValue(state, unit) * 0.12;
  return damage * 24 + range * 12 + getUnitInstanceValue(state, unit) * 0.2 - hexDistance(unit.coord, state.bases.Player) * 4;
}

function buildEnemyCampaignInvalidationKey(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  phase: EnemyStrategicPhase,
  objectiveClock: EnemyObjectiveClockEstimate,
  playerIntel: EnemyPlannerPlayerIntel[]
): string {
  const gateSignature = (state.gates ?? [])
    .map((gate) => `${gate.id}:${gate.owner ?? "Neutral"}:${gate.occupation.Enemy}:${gate.occupation.Player}`)
    .sort()
    .join("|");
  const campaignUnitSignature = getOwnerUnits(state, "Enemy")
    .filter((unit) => isEnemyCampaignRelevantUnit(unit, rolesByUnitId[unit.id]))
    .map((unit) => `${unit.id}:${unit.type}:${rolesByUnitId[unit.id] ?? "none"}:${getEnemyCampaignHealthBand(unit)}`)
    .sort()
    .join("|");
  const imminentGateSignature = (state.gates ?? [])
    .map((gate) => {
      const enemyTurns = objectiveClock.enemyTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY;
      const playerTurns = objectiveClock.playerTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY;
      return `${gate.id}:e${enemyTurns <= 1 ? 1 : 0}:p${playerTurns <= 1 ? 1 : 0}`;
    })
    .sort()
    .join("|");
  const baseThreatSignature = playerIntel
    .filter((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, state.bases.Enemy) <= 2)
    .map((intel) => intel.unit.id)
    .sort()
    .join(",");
  const playerBaseBlocker = getPlayerBaseTileBlocker(state)?.id ?? "none";
  return [
    "v1",
    state.difficulty,
    phase,
    `base:${state.baseOccupation.Enemy}:${state.baseOccupation.Player}`,
    `gates:${gateSignature}`,
    `units:${campaignUnitSignature}`,
    `clock:${imminentGateSignature}`,
    `threat:${baseThreatSignature}`,
    `playerBaseBlocker:${playerBaseBlocker}`
  ].join(";");
}

function isEnemyCampaignRelevantUnit(unit: UnitInstance, mission: EnemyMission | undefined): boolean {
  return (
    getUnitDefinition(unit.type).humanBased ||
    isReconUnit(unit.type) ||
    isOpeningGateSupportUnit(unit.type) ||
    unit.type === "Artillery" ||
    unit.type === "Anti-Air" ||
    mission === "Escort" ||
    mission === "DefendBase" ||
    mission === "CaptureBase" ||
    mission === "Siege" ||
    isEnemyGateLockoutCombatMission(mission)
  );
}

function getEnemyCampaignHealthBand(unit: UnitInstance): string {
  const ratio = unit.health / Math.max(1, unit.maxHealth);
  return ratio <= 0.25 ? "critical" : ratio <= 0.45 ? "damaged" : "ready";
}

function resolveEnemyStrategicPhase(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  playerIntel: EnemyPlannerPlayerIntel[]
): EnemyStrategicPhase {
  return resolveEnemyStrategicPhaseFromSnapshot(state, {
    enemyGateCount: assessment.enemyGateCount,
    playerGateCount: assessment.playerGateCount,
    immediateBaseThreat: playerIntel.some((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, state.bases.Enemy) <= 2),
    activeBaseThreat:
      assessment.baseDefenseUrgency > 220 ||
      playerIntel.some((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, state.bases.Enemy) <= 2),
    predictedEnemyBasePressure: assessment.predictedEnemyBasePressure,
    gateLockoutCombatPressure: scoreEnemyGateLockoutCombatPressure(state, playerIntel)
  });
}

function resolveEnemyStrategicPhaseFromSnapshot(
  state: GameState,
  signals: {
    enemyGateCount: number;
    playerGateCount: number;
    immediateBaseThreat?: boolean;
    activeBaseThreat: boolean;
    predictedEnemyBasePressure: number;
    gateLockoutCombatPressure?: number;
  }
): EnemyStrategicPhase {
  const gateCount = (state.gates ?? []).length;
  if (state.baseOccupation.Enemy > 0 || signals.immediateBaseThreat) {
    return "BaseDefenseEmergency";
  }
  const lockoutCombatPressure = signals.gateLockoutCombatPressure ?? scoreEnemyGateLockoutCombatPressure(state, getPlayerIntelForEnemy(state));
  if (
    gateCount > 0 &&
    signals.enemyGateCount === 0 &&
    signals.playerGateCount === gateCount &&
    lockoutCombatPressure >= ENEMY_GATE_LOCKOUT_COMBAT_PRESSURE_THRESHOLD &&
    !hasEnemyGateLockoutCounterattackSucceeded(state, getPlayerIntelForEnemy(state))
  ) {
    return "GateLockoutCombat";
  }
  if (signals.activeBaseThreat || signals.predictedEnemyBasePressure > 220) {
    return "BaseDefenseEmergency";
  }
  if (state.baseOccupation.Player > 0) {
    return "BaseHold";
  }
  if (gateCount > 0 && signals.enemyGateCount === gateCount) {
    return isEnemyBaseAssaultReady(state) ? "BaseAssault" : "BothGatesOwned";
  }
  if (signals.enemyGateCount === 1) {
    return "OneGateOwned";
  }
  if (gateCount > 0 && signals.playerGateCount === gateCount) {
    return "Recovery";
  }
  return "OpeningGateRace";
}

const ENEMY_GATE_LOCKOUT_COMBAT_PRESSURE_THRESHOLD = 190;

function scoreEnemyGateLockoutCombatPressure(state: GameState, playerIntel: PlayerUnitIntel[]): number {
  const gates = state.gates ?? [];
  if (!gates.length || !gates.every((gate) => gate.owner === "Player")) {
    return 0;
  }

  return playerIntel.reduce((score, intel) => {
    const nearestGateDistance = gates.reduce((best, gate) => Math.min(best, hexDistance(intel.predictedCoord, gate.coord)), Number.POSITIVE_INFINITY);
    const unitValue = getUnitInstanceValue(state, intel.unit);
    const definition = getUnitDefinition(intel.unit.type);
    const gatePressure =
      nearestGateDistance <= 3
        ? unitValue * 0.68 + (definition.humanBased ? 58 : 0)
        : nearestGateDistance <= 7
          ? unitValue * 0.38 + (definition.humanBased ? 34 : 0)
          : 0;
    const frontLinePressure = isCoordPastEnemyFrontLine(state, "Player", intel.predictedCoord)
      ? unitValue * 0.42 + (definition.humanBased ? 42 : 0)
      : 0;
    const gateIntentPressure = intel.likelyObjective === "WestGate" || intel.likelyObjective === "EastGate" ? 46 : 0;
    return score + (gatePressure + frontLinePressure + gateIntentPressure) * intel.confidence;
  }, 0);
}

function hasEnemyGateLockoutCounterattackSucceeded(state: GameState, playerIntel: PlayerUnitIntel[] = getPlayerIntelForEnemy(state)): boolean {
  const gates = state.gates ?? [];
  if (state.difficulty !== "Hard" || !gates.length || !gates.every((gate) => gate.owner === "Player")) {
    return false;
  }

  const gate = chooseEnemyGateLockoutSuccessGate(state, playerIntel);
  if (!gate) {
    return false;
  }

  const theatre = estimateGateTheatrePressure(state, gate, 9, playerIntel);
  const enemyPowerReady = theatre.enemy.total >= theatre.player.total * 0.98 || theatre.enemy.combat >= theatre.player.combat * 1.02;
  if (!enemyPowerReady) {
    return false;
  }

  return getOwnerUnits(state, "Enemy")
    .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) >= 0.55)
    .some((unit) => canEnemyHealthyHumanReachOrSafelyApproachGate(state, unit, gate, theatre, playerIntel));
}

function chooseEnemyGateLockoutSuccessGate(state: GameState, playerIntel: PlayerUnitIntel[]): GateState | undefined {
  return [...(state.gates ?? [])]
    .filter((gate) => gate.owner === "Player")
    .map((gate) => {
      const theatre = estimateGateTheatrePressure(state, gate, 9, playerIntel);
      const capturerDistance = getOwnerUnits(state, "Enemy")
        .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) >= 0.55)
        .reduce((best, unit) => Math.min(best, hexDistance(unit.coord, gate.coord)), Number.POSITIVE_INFINITY);
      return {
        gate,
        score: theatre.balance + theatre.enemy.capture * 0.42 - theatre.player.capture * 0.34 - Math.min(12, capturerDistance) * 12 + gate.occupation.Enemy * 70
      };
    })
    .sort((first, second) => second.score - first.score || first.gate.id.localeCompare(second.gate.id))[0]?.gate;
}

function canEnemyHealthyHumanReachOrSafelyApproachGate(
  state: GameState,
  capturer: UnitInstance,
  gate: GateState,
  theatre: GateTheatrePressure,
  playerIntel: PlayerUnitIntel[]
): boolean {
  const stats = getEffectiveUnitStats(state, capturer.owner, capturer.type, capturer.level, capturer.coord, gate.coord);
  const currentDistance = hexDistance(capturer.coord, gate.coord);
  const canReachGate = currentDistance <= getEffectiveRemainingMovementToCoord(state, capturer, gate.coord);
  if (canReachGate && isGateRecaptureRiskLowFromIntel(state, gate, capturer, gate.coord, theatre, playerIntel)) {
    return true;
  }

  return getEnemyLegalMoveCoords(state, capturer)
    .filter((coord) => !sameHex(coord, gate.coord))
    .filter((coord) => hexDistance(coord, gate.coord) < currentDistance)
    .filter((coord) => hexDistance(coord, gate.coord) <= Math.max(4, stats.moveRange + 1))
    .some((coord) => isGateApproachRiskLowFromIntel(state, capturer, coord, gate, theatre, playerIntel));
}

function isGateRecaptureRiskLowFromIntel(
  state: GameState,
  gate: GateState,
  capturer: UnitInstance,
  coord: UnitInstance["coord"],
  theatre: GateTheatrePressure,
  playerIntel: PlayerUnitIntel[]
): boolean {
  const projectedCapturer: UnitInstance = { ...capturer, coord: { ...coord } };
  const predictedDamage = estimatePredictedPlayerDamageToEnemyAtCoordFromIntel(state, projectedCapturer, coord, playerIntel);
  const enemyLocalPower = theatre.enemy.total + estimateGateTheatreUnitPower(state, projectedCapturer, coord, gate, theatre.radius) * 1.08;
  const playerLocalPower = theatre.player.total;
  return predictedDamage < projectedCapturer.health * 0.58 && playerLocalPower <= enemyLocalPower * 1.05 + 28;
}

function isGateApproachRiskLowFromIntel(
  state: GameState,
  capturer: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState,
  theatre: GateTheatrePressure,
  playerIntel: PlayerUnitIntel[]
): boolean {
  const projectedCapturer: UnitInstance = { ...capturer, coord: { ...coord } };
  const predictedDamage = estimatePredictedPlayerDamageToEnemyAtCoordFromIntel(state, projectedCapturer, coord, playerIntel);
  const approachPower = theatre.enemy.total + estimateGateTheatreUnitPower(state, projectedCapturer, coord, gate, theatre.radius) * 0.72;
  return predictedDamage < projectedCapturer.health * 0.48 && theatre.player.total <= approachPower * 1.12 + 42;
}

function getEnemyPreBaseEmergencyThreats(state: GameState, playerIntel: PlayerUnitIntel[] = getPlayerIntelForEnemy(state)): EnemyPreBaseEmergencyThreat[] {
  const gates = state.gates ?? [];
  if (state.difficulty !== "Hard" || !gates.length || !ownerControlsBothGates(state, "Player")) {
    return [];
  }

  const enemyAirPresent = getOwnerUnits(state, "Enemy").some((unit) => getUnitDefinition(unit.type).domain === "Air");
  return playerIntel
    .filter((intel) => intel.age <= 3)
    .map((intel): EnemyPreBaseEmergencyThreat | undefined => {
      const definition = getUnitDefinition(intel.unit.type);
      const nearestGateDistance = gates.reduce((best, gate) => Math.min(best, hexDistance(intel.predictedCoord, gate.coord)), Number.POSITIVE_INFINITY);
      const canPressureGate = gates.some((gate) => canUnitProjectThreatToCoord(state, intel.unit, intel.predictedCoord, gate.coord));
      const canPressureBase = canUnitProjectThreatToCoord(state, intel.unit, intel.predictedCoord, state.bases.Enemy);
      const forwardPressure = isCoordPastEnemyFrontLine(state, "Player", intel.predictedCoord);
      const likelyBasePush = intel.likelyObjective === "EnemyBase";
      if (!likelyBasePush && nearestGateDistance > 8 && !canPressureGate && !canPressureBase && !forwardPressure) {
        return undefined;
      }

      const value = getUnitInstanceValue(state, intel.unit) * intel.confidence;
      const gateBonus = Math.max(0, 9 - nearestGateDistance) * 24;
      const baseDistance = hexDistance(intel.predictedCoord, state.bases.Enemy);
      const baseApproachBonus = Math.max(0, 14 - baseDistance) * 12;
      const roleBonus =
        (definition.humanBased ? 220 : 0) +
        (intel.unit.type === "Artillery" ? 130 : 0) +
        (intel.unit.type === "Tank" || intel.unit.type === "IFV" ? 120 : 0) +
        (intel.unit.type === "Anti-Air" && enemyAirPresent ? 80 : 0) +
        (definition.domain === "Air" || intel.unit.type === "Ghost" || intel.unit.type === "Operator" || intel.unit.type === "Reaper" ? 100 : 0);
      const intentBonus = (likelyBasePush ? 160 : 0) + (canPressureBase ? 140 : 0) + (canPressureGate ? 65 : 0) + (forwardPressure ? 85 : 0);
      return {
        unit: intel.unit,
        coord: { ...intel.predictedCoord },
        score: value + gateBonus + baseApproachBonus + roleBonus + intentBonus
      };
    })
    .filter((threat): threat is EnemyPreBaseEmergencyThreat => Boolean(threat))
    .sort((first, second) => second.score - first.score || first.unit.id.localeCompare(second.unit.id));
}

function chooseEnemyPreBaseEmergencyThreat(
  state: GameState,
  playerIntel: PlayerUnitIntel[] = getPlayerIntelForEnemy(state),
  removerType?: UnitType
): EnemyPreBaseEmergencyThreat | undefined {
  return getEnemyPreBaseEmergencyThreats(state, playerIntel).find((threat) => !removerType || canUnitTargetUnit(removerType, threat.unit.type));
}

function isEnemyBaseAssaultReady(state: GameState): boolean {
  return (
    state.baseOccupation.Player > 0 ||
    isPlayerBaseExposedForHardAttack(state) ||
    getOwnerUnits(state, "Enemy").some(
      (unit) =>
        getUnitDefinition(unit.type).humanBased &&
        unit.health / Math.max(1, unit.maxHealth) > 0.45 &&
        hexDistance(unit.coord, state.bases.Player) <= 12
    )
  );
}

function isEnemyBaseOperationPhase(phase: EnemyStrategicPhase): boolean {
  return phase === "BothGatesOwned" || phase === "BaseAssault" || phase === "BaseHold";
}

function getEnemyStrategicPhaseWeights(phase: EnemyStrategicPhase): {
  gate: number;
  base: number;
  production: number;
  scout: number;
  repair: number;
  defense: number;
  combat: number;
} {
  switch (phase) {
    case "OpeningGateRace":
      return { gate: 1.45, base: 0.48, production: 1.1, scout: 1.15, repair: 0.65, defense: 0.72, combat: 1.05 };
    case "OneGateOwned":
      return { gate: 1.25, base: 0.78, production: 1.05, scout: 1, repair: 0.75, defense: 0.9, combat: 1.12 };
    case "GateLockoutCombat":
      return { gate: 0.92, base: 0.38, production: 1.25, scout: 1.15, repair: 0.55, defense: 1.25, combat: 1.65 };
    case "BothGatesOwned":
      return { gate: 0.45, base: 1.45, production: 1.1, scout: 0.9, repair: 0.8, defense: 0.9, combat: 1 };
    case "BaseAssault":
      return { gate: 0.25, base: 1.65, production: 1.12, scout: 0.85, repair: 0.75, defense: 0.9, combat: 1.05 };
    case "BaseHold":
      return { gate: 0.35, base: 1.9, production: 1.05, scout: 0.75, repair: 0.65, defense: 0.7, combat: 0.8 };
    case "BaseDefenseEmergency":
      return { gate: 0.45, base: 0.25, production: 1.25, scout: 0.65, repair: 0.55, defense: 1.8, combat: 1.25 };
    case "Recovery":
      return { gate: 1.75, base: 0.42, production: 1.15, scout: 0.95, repair: 0.6, defense: 0.95, combat: 1.18 };
  }
}

function estimateEnemyObjectiveClocks(state: GameState, playerIntel: EnemyPlannerPlayerIntel[]): EnemyObjectiveClockEstimate {
  const enemyHumans = getOwnerUnits(state, "Enemy").filter((unit) => getUnitDefinition(unit.type).humanBased);
  const playerHumans = playerIntel.filter((intel) => getUnitDefinition(intel.unit.type).humanBased);
  const enemyTurnsToGates: Partial<Record<GateState["id"], number>> = {};
  const playerTurnsToGates: Partial<Record<GateState["id"], number>> = {};
  for (const gate of state.gates ?? []) {
    enemyTurnsToGates[gate.id] = estimateTurnsForUnitsToCaptureGate(state, enemyHumans, gate, "Enemy");
    playerTurnsToGates[gate.id] = estimateTurnsForIntelToCaptureGate(state, playerHumans, gate);
  }
  const enemyWinForecast = estimateObjectiveWinForecast(state, "Enemy", enemyTurnsToGates, playerTurnsToGates, playerIntel);
  const playerWinForecast = estimateObjectiveWinForecast(state, "Player", playerTurnsToGates, enemyTurnsToGates, playerIntel);
  return {
    enemyTurnsToWin: enemyWinForecast.turnsToWin,
    playerTurnsToWin: playerWinForecast.turnsToWin,
    enemyWinForecast,
    playerWinForecast,
    enemyTurnsToGates,
    playerTurnsToGates
  };
}

function estimateObjectiveWinForecast(
  state: GameState,
  owner: Owner,
  ownerTurnsToGates: Partial<Record<GateState["id"], number>>,
  opponentTurnsToGates: Partial<Record<GateState["id"], number>>,
  playerIntel: EnemyPlannerPlayerIntel[]
): EnemyObjectiveWinForecast {
  const targetBase = owner === "Enemy" ? state.bases.Player : state.bases.Enemy;
  const baseOccupation = owner === "Enemy" ? state.baseOccupation.Player : state.baseOccupation.Enemy;
  const baseOccupationTurnsRemaining = Math.max(0, BASE_CAPTURE_DAYS - baseOccupation);
  const capturers = getObjectiveCapturerEstimates(state, owner, playerIntel);
  const turnsToOwnAllGates = estimateTurnsToOwnAllGates(state, owner, ownerTurnsToGates);
  const turnsToReachBaseAfterGates = estimateTurnsToReachBaseAfterGateControl(state, owner, capturers, targetBase, turnsToOwnAllGates);
  const activeBaseCapture = baseOccupation > 0 && capturers.some((capturer) => sameHex(capturer.coord, targetBase));
  const turnsToWin = activeBaseCapture
    ? baseOccupationTurnsRemaining
    : turnsToOwnAllGates + turnsToReachBaseAfterGates + BASE_CAPTURE_DAYS;
  const likelyCapturer = chooseLikelyObjectiveCapturer(state, owner, capturers, targetBase);
  const capturerSurvivalChance = likelyCapturer ? estimateObjectiveCapturerSurvivalChance(state, likelyCapturer, targetBase, owner) : 0;
  const gateLoss = estimateGateLossRiskBeforeBaseCapture(state, owner, opponentTurnsToGates, turnsToReachBaseAfterGates + baseOccupationTurnsRemaining);
  const confidence = Math.max(0, Math.min(1, (likelyCapturer?.confidence ?? 0) * capturerSurvivalChance * (1 - gateLoss.risk)));
  return {
    owner,
    turnsToWin,
    turnsToOwnAllGates,
    turnsToReachBaseAfterGates,
    baseOccupationTurnsRemaining,
    capturerSurvivalChance,
    gateLossRiskBeforeBaseCapture: gateLoss.risk,
    confidence,
    targetBase,
    likelyCapturerId: likelyCapturer?.id,
    vulnerableGateId: gateLoss.gateId
  };
}

interface ObjectiveCapturerEstimate {
  id: string;
  owner: Owner;
  type: UnitType;
  level: number;
  coord: UnitInstance["coord"];
  health: number;
  maxHealth: number;
  confidence: number;
}

function getObjectiveCapturerEstimates(state: GameState, owner: Owner, playerIntel: EnemyPlannerPlayerIntel[]): ObjectiveCapturerEstimate[] {
  if (owner === "Enemy") {
    return getOwnerUnits(state, "Enemy")
      .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health > 0)
      .map((unit) => ({
        id: unit.id,
        owner: unit.owner,
        type: unit.type,
        level: unit.level,
        coord: { ...unit.coord },
        health: unit.health,
        maxHealth: unit.maxHealth,
        confidence: 1
      }));
  }

  return playerIntel
    .filter((intel) => getUnitDefinition(intel.unit.type).humanBased && intel.unit.health > 0)
    .map((intel) => ({
      id: intel.unit.id,
      owner: intel.unit.owner,
      type: intel.unit.type,
      level: intel.unit.level,
      coord: { ...intel.predictedCoord },
      health: intel.unit.health,
      maxHealth: intel.unit.maxHealth,
      confidence: intel.confidence
    }));
}

function estimateTurnsToOwnAllGates(state: GameState, owner: Owner, turnsToGates: Partial<Record<GateState["id"], number>>): number {
  const gates = state.gates ?? [];
  if (!gates.length) {
    return 0;
  }
  return gates.reduce((turns, gate) => Math.max(turns, gate.owner === owner ? 0 : turnsToGates[gate.id] ?? Number.POSITIVE_INFINITY), 0);
}

function estimateTurnsToReachBaseAfterGateControl(
  state: GameState,
  owner: Owner,
  capturers: ObjectiveCapturerEstimate[],
  targetBase: UnitInstance["coord"],
  turnsToOwnAllGates: number
): number {
  if (!capturers.length) {
    return Number.POSITIVE_INFINITY;
  }
  const bestMove = capturers.reduce((best, capturer) => {
    const stats = getEffectiveUnitStats(state, capturer.owner, capturer.type, capturer.level, capturer.coord, targetBase);
    return Math.max(best, stats.moveRange);
  }, 1);
  if (ownerControlsBothGates(state, owner) || turnsToOwnAllGates === 0) {
    return capturers.reduce((best, capturer) => Math.min(best, Math.ceil(hexDistance(capturer.coord, targetBase) / Math.max(1, bestMove))), Number.POSITIVE_INFINITY);
  }
  const gateApproach = (state.gates ?? []).reduce(
    (best, gate) => Math.min(best, Math.ceil(hexDistance(gate.coord, targetBase) / Math.max(1, bestMove))),
    Number.POSITIVE_INFINITY
  );
  return gateApproach;
}

function chooseLikelyObjectiveCapturer(
  state: GameState,
  owner: Owner,
  capturers: ObjectiveCapturerEstimate[],
  targetBase: UnitInstance["coord"]
): ObjectiveCapturerEstimate | undefined {
  return [...capturers]
    .sort((first, second) => {
      const firstSurvival = estimateObjectiveCapturerSurvivalChance(state, first, targetBase, owner);
      const secondSurvival = estimateObjectiveCapturerSurvivalChance(state, second, targetBase, owner);
      const firstScore = first.confidence * firstSurvival * 100 - hexDistance(first.coord, targetBase) * 5 + first.health;
      const secondScore = second.confidence * secondSurvival * 100 - hexDistance(second.coord, targetBase) * 5 + second.health;
      return secondScore - firstScore || first.id.localeCompare(second.id);
    })[0];
}

function estimateObjectiveCapturerSurvivalChance(
  state: GameState,
  capturer: ObjectiveCapturerEstimate,
  targetBase: UnitInstance["coord"],
  owner: Owner
): number {
  const danger = owner === "Enemy"
    ? estimatePlayerDangerAt(state, toSyntheticUnitInstance(state, capturer), capturer.coord)
    : estimateEnemyDangerAtCoord(state, capturer, capturer.coord);
  const baseDanger = owner === "Enemy"
    ? estimatePlayerDangerAt(state, toSyntheticUnitInstance(state, capturer), targetBase) * 0.35
    : estimateEnemyDangerAtCoord(state, capturer, targetBase) * 0.35;
  const totalDanger = danger + baseDanger;
  return Math.max(0.05, Math.min(0.95, 1 - totalDanger / Math.max(1, capturer.health * 1.8)));
}

function toSyntheticUnitInstance(state: GameState, capturer: ObjectiveCapturerEstimate): UnitInstance {
  return {
    id: capturer.id,
    owner: capturer.owner,
    type: capturer.type,
    level: capturer.level,
    coord: { ...capturer.coord },
    health: capturer.health,
    maxHealth: capturer.maxHealth,
    placedDay: Math.max(1, state.day - 1),
    hasMovedThisDay: false,
    movementSpentThisDay: 0,
    hasAttackedThisDay: false
  };
}

function estimateEnemyDangerAtCoord(state: GameState, target: ObjectiveCapturerEstimate, coord: UnitInstance["coord"]): number {
  return getOwnerUnits(state, "Enemy").reduce((danger, enemy) => {
    if (!canUnitTargetUnit(enemy.type, target.type)) {
      return danger;
    }
    const distance = hexDistance(coord, enemy.coord);
    const stats = getEffectiveUnitStats(state, enemy.owner, enemy.type, enemy.level, enemy.coord, coord);
    const syntheticTarget = toSyntheticUnitInstance(state, target);
    const damage = estimateAttackDamage(state, enemy, syntheticTarget);
    if (distance <= stats.attackRange) {
      return danger + damage * 1.5;
    }
    if (!getUnitDefinition(enemy.type).cannotMoveAndAttack && distance <= stats.attackRange + stats.moveRange) {
      return danger + damage * 0.75;
    }
    return danger;
  }, 0);
}

function estimateGateLossRiskBeforeBaseCapture(
  state: GameState,
  owner: Owner,
  opponentTurnsToGates: Partial<Record<GateState["id"], number>>,
  baseOperationTurns: number
): { risk: number; gateId?: GateState["id"] } {
  const risks = (state.gates ?? [])
    .filter((gate) => gate.owner === owner)
    .map((gate) => {
      const opponentTurns = opponentTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY;
      const occupationRisk = gate.occupation[oppositeOwner(owner)] > 0 ? gate.occupation[oppositeOwner(owner)] / GATE_CAPTURE_DAYS : 0;
      const timeRisk = opponentTurns <= baseOperationTurns ? 0.75 : opponentTurns <= baseOperationTurns + 1 ? 0.45 : 0;
      return { gateId: gate.id, risk: Math.max(occupationRisk, timeRisk) };
    })
    .sort((first, second) => second.risk - first.risk || first.gateId.localeCompare(second.gateId));
  return risks[0] ?? { risk: 0 };
}

function oppositeOwner(owner: Owner): Owner {
  return owner === "Enemy" ? "Player" : "Enemy";
}

function estimateTurnsForUnitsToCaptureGate(state: GameState, units: UnitInstance[], gate: GateState, owner: Owner): number {
  if (gate.owner === owner) {
    return 0;
  }
  const bestDistance = units.reduce((best, unit) => Math.min(best, hexDistance(unit.coord, gate.coord)), Number.POSITIVE_INFINITY);
  if (!Number.isFinite(bestDistance)) {
    return Number.POSITIVE_INFINITY;
  }
  const bestMove = units.reduce((best, unit) => Math.max(best, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord).moveRange), 1);
  return Math.ceil(bestDistance / Math.max(1, bestMove)) + Math.max(0, GATE_CAPTURE_DAYS - gate.occupation[owner]);
}

function estimateTurnsForIntelToCaptureGate(state: GameState, units: EnemyPlannerPlayerIntel[], gate: GateState): number {
  if (gate.owner === "Player") {
    return 0;
  }
  const bestDistance = units.reduce((best, intel) => Math.min(best, hexDistance(intel.predictedCoord, gate.coord)), Number.POSITIVE_INFINITY);
  if (!Number.isFinite(bestDistance)) {
    return Number.POSITIVE_INFINITY;
  }
  const bestMove = units.reduce((best, intel) => Math.max(best, getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, intel.predictedCoord, gate.coord).moveRange), 1);
  return Math.ceil(bestDistance / Math.max(1, bestMove)) + Math.max(0, GATE_CAPTURE_DAYS - gate.occupation.Player);
}

function isEnemyCampaignAssignedGateStillValid(
  state: GameState,
  unit: UnitInstance,
  gateId: GateState["id"] | undefined,
  objectiveClock: EnemyObjectiveClockEstimate
): boolean {
  if (!gateId) {
    return false;
  }
  const gate = (state.gates ?? []).find((candidate) => candidate.id === gateId);
  if (!gate || gate.owner === "Enemy") {
    return false;
  }
  if (isAnotherGateOneTurnFromDecision(state, gateId, objectiveClock)) {
    return false;
  }
  return isEnemyAssignedGateReachable(state, unit, gate);
}

function isEnemyOpeningCaptureGateMission(state: GameState, unit: UnitInstance, mission: EnemyMission | undefined): boolean {
  return (
    usesHardEnemyDoctrine(state) &&
    state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY &&
    getUnitDefinition(unit.type).humanBased &&
    (mission === "CaptureGate" || mission === "ShadowCapturer" || mission === "EscortCapture")
  );
}

function isEnemyOpeningLaneMission(state: GameState, unit: UnitInstance, mission: EnemyMission | undefined): boolean {
  if (!usesHardEnemyDoctrine(state) || state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY) {
    return false;
  }
  if (isEnemyOpeningCaptureGateMission(state, unit, mission)) {
    return true;
  }
  return (
    mission === "Escort" &&
    (isOpeningGateSupportUnit(unit.type) || unit.type === "Artillery" || unit.type === "Anti-Air")
  ) || mission === "PatrolWest" || mission === "PatrolEast" || mission === "Scout";
}

function isAnotherGateOneTurnFromDecision(
  state: GameState,
  assignedGateId: GateState["id"],
  objectiveClock: EnemyObjectiveClockEstimate
): boolean {
  return (state.gates ?? []).some((gate) => {
    if (gate.id === assignedGateId || gate.owner === "Enemy") {
      return false;
    }
    return (
      (objectiveClock.playerTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY) <= 1 ||
      (objectiveClock.enemyTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY) <= 1 ||
      gate.occupation.Player >= GATE_CAPTURE_DAYS - 1 ||
      gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1
    );
  });
}

function isEnemyAssignedGateReachable(state: GameState, unit: UnitInstance, gate: GateState): boolean {
  if (hexDistance(unit.coord, gate.coord) <= getEffectiveRemainingMovementToCoord(state, unit, gate.coord) + 1) {
    return true;
  }

  const cache = activeEnemyTurnPlan
    ? (activeEnemyTurnPlan.cache.assignedGateReachable ??= new Map())
    : (getEnemyEvaluationCache(state).assignedGateReachable ??= new Map());
  const cacheKey = [
    enemyEvaluationMutationEpoch,
    unit.id,
    unit.type,
    unit.level,
    hexId(unit.coord),
    unit.movementSpentThisDay ?? 0,
    unit.hasMovedThisDay ? 1 : 0,
    gate.id,
    hexId(gate.coord),
    gate.owner ?? "None"
  ].join(":");
  const cached = cache.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const reachable = findMovementPath(state, unit, gate.coord) !== undefined;
  cache.set(cacheKey, reachable);
  return reachable;
}

function chooseEnemyCampaignGateForUnit(
  state: GameState,
  unit: UnitInstance,
  rolesByUnitId: Record<string, EnemyMission>,
  mainEffortGateId: GateState["id"] | undefined,
  secondaryGateId: GateState["id"] | undefined,
  objectiveClock: EnemyObjectiveClockEstimate
): GateState["id"] | undefined {
  const mission = rolesByUnitId[unit.id];
  const gates = state.gates ?? [];
  if (!gates.length) {
    return undefined;
  }
  const urgentPlayerGate = gates
    .filter((gate) => objectiveClock.playerTurnsToGates[gate.id] !== undefined && objectiveClock.playerTurnsToGates[gate.id]! <= 1)
    .sort((first, second) => (objectiveClock.playerTurnsToGates[first.id] ?? 99) - (objectiveClock.playerTurnsToGates[second.id] ?? 99))[0];
  if (urgentPlayerGate && getUnitDefinition(unit.type).humanBased) {
    return urgentPlayerGate.id;
  }
  const winningGate = gates
    .filter((gate) => gate.owner !== "Enemy" && gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1)
    .sort((first, second) => second.occupation.Enemy - first.occupation.Enemy || hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord))[0];
  if (winningGate && getUnitDefinition(unit.type).humanBased) {
    return winningGate.id;
  }
  if (state.day <= 8) {
    if (mainEffortGateId && isOpeningGateSupportUnit(unit.type)) {
      return mainEffortGateId;
    }
    const center = state.bases.Enemy.q;
    const laneId = unit.coord.q < center ? "West" : unit.coord.q > center ? "East" : getStableUnitNumber(unit) % 2 === 0 ? "West" : "East";
    const laneGate = gates.find((gate) => gate.id === laneId && gate.owner !== "Enemy");
    if (laneGate) {
      return laneGate.id;
    }
  }
  if (mission === "CaptureGate" || mission === "EscortCapture" || mission === "ShadowCapturer") {
    return mainEffortGateId ?? secondaryGateId;
  }
  if (mission === "DefendGate") {
    return gates.filter((gate) => gate.owner === "Enemy").sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord))[0]?.id;
  }
  if (mission === "Escort" || mission === "Scout" || mission === "PatrolWest" || mission === "PatrolEast") {
    return mainEffortGateId ?? secondaryGateId;
  }
  return undefined;
}

function createEnemyLaneTaskForcePlan(
  state: GameState,
  gateId: GateState["id"],
  assignedGateByUnitId: Record<string, GateState["id"]>,
  rolesByUnitId: Record<string, EnemyMission>,
  previous?: EnemyLaneTaskForcePlan
): EnemyLaneTaskForcePlan {
  const gate = (state.gates ?? []).find((candidate) => candidate.id === gateId);
  const activeClockCapturers =
    gate && state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY && gate.owner !== "Enemy" && gate.occupation.Enemy > 0
      ? getOwnerUnits(state, "Enemy")
          .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.35)
          .filter((unit) => hexDistance(unit.coord, gate.coord) <= 8)
      : [];
  const laneUnits = [
    ...getOwnerUnits(state, "Enemy").filter((unit) => assignedGateByUnitId[unit.id] === gateId),
    ...activeClockCapturers
  ].filter((unit, index, all) => all.findIndex((candidate) => candidate.id === unit.id) === index);
  const laneUnitIds = new Set(laneUnits.map((unit) => unit.id));
  const unitById = new Map(laneUnits.map((unit) => [unit.id, unit]));
  const capturers = laneUnits
    .filter((unit) => getUnitDefinition(unit.type).humanBased)
    .sort((first, second) => scoreCampaignCapturerPriority(state, second, gateId, rolesByUnitId) - scoreCampaignCapturerPriority(state, first, gateId, rolesByUnitId));
  const isLaneCapturer = (id: string | undefined): boolean => {
    const unit = id ? unitById.get(id) : undefined;
    return Boolean(unit && getUnitDefinition(unit.type).humanBased);
  };
  const assessment = getEnemyStrategicAssessment(state);
  const allowBackupCapturer = Boolean(gate && shouldEnemyGatePacketUseBackup(state, assessment, gate));
  const preservePreviousPrincipal = !isEnemyMidGameGateEffortPhase(state, getEnemyStrategicAssessment(state).strategicPhase);
  const principalCapturerId = preservePreviousPrincipal && isLaneCapturer(previous?.principalCapturerId)
    ? previous?.principalCapturerId
    : capturers[0]?.id;
  const backupCapturerId =
    allowBackupCapturer
      ? isLaneCapturer(previous?.backupCapturerId) && previous?.backupCapturerId !== principalCapturerId
        ? previous?.backupCapturerId
        : capturers.find((unit) => unit.id !== principalCapturerId)?.id
      : undefined;
  const stableIds = (previousIds: string[] | undefined, predicate: (unit: UnitInstance) => boolean): string[] => {
    const ids = [
      ...(previousIds ?? []).filter((id) => {
        const unit = unitById.get(id);
        return Boolean(unit && predicate(unit));
      }),
      ...laneUnits.filter(predicate).map((unit) => unit.id)
    ];
    return ids.filter((id, index) => laneUnitIds.has(id) && ids.indexOf(id) === index);
  };
  return {
    id: gateId === "West" ? "WestGateForce" : "EastGateForce",
    gateId,
    principalCapturerId,
    backupCapturerId,
    escortIds: stableIds(previous?.escortIds, (unit) => rolesByUnitId[unit.id] === "Escort" || rolesByUnitId[unit.id] === "EscortCapture"),
    scoutIds: stableIds(previous?.scoutIds, (unit) => isReconUnit(unit.type) || rolesByUnitId[unit.id] === "PatrolWest" || rolesByUnitId[unit.id] === "PatrolEast"),
    supportIds: stableIds(previous?.supportIds, (unit) => isOpeningGateSupportUnit(unit.type) || unit.type === "Artillery" || unit.type === "Anti-Air")
  };
}

function scoreCampaignCapturerPriority(
  state: GameState,
  unit: UnitInstance,
  gateId: GateState["id"],
  rolesByUnitId: Record<string, EnemyMission>
): number {
  const gate = (state.gates ?? []).find((candidate) => candidate.id === gateId);
  const role = rolesByUnitId[unit.id];
  return (
    (role === "CaptureGate" ? 1000 : role === "ShadowCapturer" || role === "EscortCapture" ? 450 : 0) +
    getUnitInstanceValue(state, unit) * 0.3 -
    (gate ? hexDistance(unit.coord, gate.coord) * 16 : 0) +
    unit.health
  );
}

function findEnemyBaseAssaultRoute(state: GameState): UnitInstance["coord"][] {
  const pathfinder = {
    ...createHypotheticalEnemyUnit(state, "Infantry", state.bases.Enemy),
    placedDay: Math.max(1, state.day - 1)
  };
  const path = findMovementPath(
    state,
    pathfinder,
    state.bases.Player
  );
  return path?.slice(0, 12).map((coord) => ({ ...coord })) ?? [];
}

function reconcileEnemyRolesWithCampaign(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  campaignPlan: EnemyCampaignPlan
): void {
  const canCampaignOverride = (unitId: string): boolean => rolesByUnitId[unitId] !== "Repair" && !isEnemyGateLockoutCombatMission(rolesByUnitId[unitId]);

  for (const gateId of ["West", "East"] as GateState["id"][]) {
    const lane = campaignPlan.laneTaskForces[gateId];
    if (lane.principalCapturerId && canCampaignOverride(lane.principalCapturerId) && rolesByUnitId[lane.principalCapturerId] !== "DefendGate") {
      rolesByUnitId[lane.principalCapturerId] = "CaptureGate";
    }
    getOwnerUnits(state, "Enemy")
      .filter((unit) => campaignPlan.assignedGateByUnitId[unit.id] === gateId)
      .filter((unit) => unit.id !== lane.principalCapturerId)
      .filter((unit) => canCampaignOverride(unit.id))
      .filter((unit) => isOpeningGateCaptureSupportUnit(unit))
      .forEach((unit) => {
        rolesByUnitId[unit.id] = unit.id === lane.backupCapturerId ? "ShadowCapturer" : "EscortCapture";
      });
  }

  for (const unit of getOwnerUnits(state, "Enemy")) {
    const role = rolesByUnitId[unit.id];
    if (canCampaignOverride(unit.id) && (role === "Escort" || role === undefined) && getUnitDefinition(unit.type).humanBased && campaignPlan.assignedGateByUnitId[unit.id]) {
      rolesByUnitId[unit.id] = "EscortCapture";
    }
  }

  normalizeHardOpeningGateCaptureSupportRoles(state, rolesByUnitId, campaignPlan);
  applyEnemyBaseAssaultPackageRoles(state, rolesByUnitId, campaignPlan);
  protectThreatenedOwnedGateDefenders(state, rolesByUnitId, campaignPlan);
}

function applyEnemyBaseAssaultPackageRoles(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  campaignPlan: EnemyCampaignPlan
): void {
  if (!ownerControlsBothGates(state, "Enemy")) {
    return;
  }

  const packagePlan = campaignPlan.baseAssaultPackage;
  if (packagePlan.capturerId && rolesByUnitId[packagePlan.capturerId] !== "Repair") {
    const unit = getUnitById(state, packagePlan.capturerId);
    if (!unit || !isEnemyAssignedCapturedGateDefender(state, unit, rolesByUnitId, campaignPlan)) {
      rolesByUnitId[packagePlan.capturerId] = "CaptureBase";
    }
  }
  if (packagePlan.backupCapturerId && rolesByUnitId[packagePlan.backupCapturerId] !== "Repair") {
    const unit = getUnitById(state, packagePlan.backupCapturerId);
    if (!unit || !isEnemyAssignedCapturedGateDefender(state, unit, rolesByUnitId, campaignPlan)) {
      rolesByUnitId[packagePlan.backupCapturerId] = "CaptureBase";
    }
  }
  if (packagePlan.scoutId && rolesByUnitId[packagePlan.scoutId] !== "Repair") {
    const unit = getUnitById(state, packagePlan.scoutId);
    rolesByUnitId[packagePlan.scoutId] = packagePlan.clearBaseTileTargetId || (unit && !isEnemyEndgamePushUnit(unit)) ? "Scout" : "Siege";
  }
  for (const unitId of packagePlan.blockerEscortIds) {
    if (rolesByUnitId[unitId] === "Repair") {
      continue;
    }
    const unit = getUnitById(state, unitId);
    rolesByUnitId[unitId] =
      state.baseOccupation.Player > 0
        ? "ProtectCapturer"
        : unit && getUnitDefinition(unit.type).humanBased
          ? "Escort"
          : "Siege";
  }
  for (const unitId of packagePlan.damageDealerIds) {
    if (rolesByUnitId[unitId] === "Repair") {
      continue;
    }
    const unit = getUnitById(state, unitId);
    rolesByUnitId[unitId] = unit && getUnitDefinition(unit.type).humanBased ? "Escort" : "Siege";
  }

  for (const unit of getOwnerUnits(state, "Enemy")) {
    if (unit.health <= 0) {
      continue;
    }
    if (unit.id === packagePlan.scoutId) {
      continue;
    }
    if (isEnemyAssignedCapturedGateDefender(state, unit, rolesByUnitId, campaignPlan)) {
      continue;
    }
    if (getUnitDefinition(unit.type).humanBased) {
      rolesByUnitId[unit.id] = "CaptureBase";
    } else if (isEnemyBaseAttackCombatUnit(unit) && rolesByUnitId[unit.id] !== "ProtectCapturer") {
      rolesByUnitId[unit.id] = "Siege";
    }
  }
}

function isEnemyAssignedCapturedGateDefender(
  state: GameState,
  unit: UnitInstance,
  rolesByUnitId: Record<string, EnemyMission>,
  campaignPlan: EnemyCampaignPlan
): boolean {
  if (rolesByUnitId[unit.id] !== "DefendGate") {
    return false;
  }
  const assignedGateId = campaignPlan.assignedGateByUnitId[unit.id];
  const assignedGate = assignedGateId ? (state.gates ?? []).find((gate) => gate.id === assignedGateId) : undefined;
  const assignedGateDistance = assignedGate ? hexDistance(unit.coord, assignedGate.coord) : Number.POSITIVE_INFINITY;
  if (
    ownerControlsBothGates(state, "Enemy") &&
    getUnitDefinition(unit.type).humanBased &&
    hexDistance(unit.coord, state.bases.Player) < assignedGateDistance
  ) {
    return false;
  }
  if (assignedGate?.owner === "Enemy") {
    return assignedGateDistance <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS;
  }
  return (state.gates ?? []).some((gate) => gate.owner === "Enemy" && hexDistance(unit.coord, gate.coord) <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS);
}

function isEnemyBaseAttackCombatUnit(unit: UnitInstance): boolean {
  if (getUnitDefinition(unit.type).humanBased || isEnemySupplySupportUnit(unit.type)) {
    return false;
  }
  return unit.type === "Tank" || unit.type === "IFV" || unit.type === "Artillery" || unit.type === "Anti-Air" || unit.type === "Attack Heli" || unit.type === "Jet" || unit.type === "Bomber" || unit.type === "Reaper";
}

function normalizeHardOpeningGateCaptureSupportRoles(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  campaignPlan: EnemyCampaignPlan
): void {
  if (!usesHardEnemyDoctrine(state) || state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY || !(state.gates ?? []).some((gate) => gate.owner !== "Enemy")) {
    return;
  }

  for (const gateId of ["West", "East"] as GateState["id"][]) {
    const lane = campaignPlan.laneTaskForces[gateId];
    getOwnerUnits(state, "Enemy")
      .filter((unit) => campaignPlan.assignedGateByUnitId[unit.id] === gateId)
      .filter((unit) => unit.id !== lane.principalCapturerId)
      .filter((unit) => isOpeningGateCaptureSupportUnit(unit))
      .forEach((unit) => {
        rolesByUnitId[unit.id] = unit.id === lane.backupCapturerId ? "ShadowCapturer" : "EscortCapture";
      });
  }
}

function isOpeningGateCaptureSupportUnit(unit: UnitInstance): boolean {
  return (unit.type === "Infantry" || unit.type === "Operator" || unit.type === "Ghost") && unit.health / Math.max(1, unit.maxHealth) > 0.4;
}

function protectThreatenedOwnedGateDefenders(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  campaignPlan: EnemyCampaignPlan
): void {
  for (const gate of state.gates ?? []) {
    const threatened =
      gate.owner === "Enemy" &&
      (gate.occupation.Player > 0 ||
        (getEnemyStrategicAssessment(state).predictedGatePressure[gate.id] ?? 0) > 45 ||
        getPlayerIntelForEnemy(state).some((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, gate.coord) <= 7));
    if (!threatened) {
      continue;
    }
    const existing = getOwnerUnits(state, "Enemy").some((unit) => rolesByUnitId[unit.id] === "DefendGate" && campaignPlan.assignedGateByUnitId[unit.id] === gate.id);
    if (existing) {
      continue;
    }
    const defender = getOwnerUnits(state, "Enemy")
      .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.35)
      .filter((unit) => hexDistance(unit.coord, gate.coord) <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS)
      .sort((first, second) => hexDistance(first.coord, gate.coord) - hexDistance(second.coord, gate.coord) || getUnitInstanceValue(state, second) - getUnitInstanceValue(state, first))[0];
    if (defender) {
      rolesByUnitId[defender.id] = "DefendGate";
      campaignPlan.assignedGateByUnitId[defender.id] = gate.id;
    }
  }
}

function getEnemyCampaignAssignedGateForUnit(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): GateState | undefined {
  const mission = plan.rolesByUnitId[unit.id];
  const gateId = plan.campaignPlan.assignedGateByUnitId[unit.id];
  const gate = gateId ? (state.gates ?? []).find((candidate) => candidate.id === gateId) : undefined;
  if (!gate || gate.owner === "Enemy") {
    return undefined;
  }
  if (
    getUnitDefinition(unit.type).humanBased &&
    (mission === "CaptureGate" || mission === "ShadowCapturer" || mission === "EscortCapture") &&
    isEnemyAssignedGateReachable(state, unit, gate)
  ) {
    return gate;
  }
  if (isEnemyOpeningLaneMission(state, unit, mission) && isEnemyCampaignAssignedGateStillValid(state, unit, gateId, plan.campaignPlan.objectiveClock)) {
    return gate;
  }
  if (state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY && isEnemyCampaignAssignedGateStillValid(state, unit, gateId, plan.campaignPlan.objectiveClock)) {
    return gate;
  }
  return undefined;
}

function buildEnemyPlannerTaskForces(state: GameState, rolesByUnitId: Record<string, EnemyMission>, campaignPlan?: EnemyCampaignPlan): EnemyTaskForce[] {
  const make = (id: EnemyTaskForceId, objectiveCoord: UnitInstance["coord"]): EnemyTaskForce => ({
    id,
    objectiveCoord,
    members: [],
    escortIds: [],
    scoutIds: [],
    supportIds: []
  });
  const westGate = (state.gates ?? []).find((gate) => gate.id === "West");
  const eastGate = (state.gates ?? []).find((gate) => gate.id === "East");
  const forces: EnemyTaskForce[] = [
    make("BaseDefence", state.bases.Enemy),
    make("BaseAssault", state.bases.Player),
    make("WestGateForce", westGate?.coord ?? state.bases.Player),
    make("EastGateForce", eastGate?.coord ?? state.bases.Player),
    make("Recon", state.bases.Player),
    make("FireSupport", state.bases.Player),
    make("MobileReserve", state.bases.Enemy),
    make("Repair", state.bases.Enemy)
  ];
  const forceForMission = (mission: EnemyMission, unit: UnitInstance): EnemyTaskForce => {
    const basePackage = campaignPlan?.baseAssaultPackage;
    if (
      basePackage &&
      (
        unit.id === basePackage.capturerId ||
        unit.id === basePackage.backupCapturerId ||
        unit.id === basePackage.scoutId ||
        basePackage.blockerEscortIds.includes(unit.id) ||
        basePackage.damageDealerIds.includes(unit.id)
      )
    ) {
      return forces[1];
    }
    if (mission === "DefendBase" || mission === "BaseSentry") return forces[0];
    if (mission === "CaptureBase" || mission === "ProtectCapturer") return forces[1];
    if (mission === "CaptureGate" || mission === "ShadowCapturer" || mission === "EscortCapture" || mission === "DefendGate" || isEnemyGateLockoutCombatMission(mission)) {
      const assignedGateId = campaignPlan?.assignedGateByUnitId[unit.id];
      const nearestGate = assignedGateId
        ? (state.gates ?? []).find((gate) => gate.id === assignedGateId)
        : isEnemyGateLockoutCombatMission(mission)
          ? chooseEnemyGateLockoutCounterattackGate(state, { campaignPlan })
          : [...(state.gates ?? [])].sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord))[0];
      return nearestGate?.id === "East" ? forces[3] : forces[2];
    }
    if (mission === "Scout" || mission === "PatrolWest" || mission === "PatrolEast") return forces[4];
    if (mission === "Siege" || mission === "Escort" || mission === "HuntArtillery" || mission === "InterceptAir") return forces[5];
    if (mission === "Repair") return forces[7];
    return forces[6];
  };

  for (const unit of getOwnerUnits(state, "Enemy")) {
    const mission = rolesByUnitId[unit.id] ?? "Escort";
    const force = forceForMission(mission, unit);
    force.members.push(unit.id);
    const lanePlan =
      force.id === "WestGateForce" || force.id === "EastGateForce"
        ? campaignPlan?.laneTaskForces[force.id === "EastGateForce" ? "East" : "West"]
        : undefined;
    if (lanePlan) {
      force.principalCapturerId = lanePlan.principalCapturerId;
      force.backupCapturerId = lanePlan.backupCapturerId;
    }
    if (force.id === "BaseAssault" && campaignPlan?.baseAssaultPackage) {
      force.principalCapturerId = campaignPlan.baseAssaultPackage.capturerId;
      force.backupCapturerId = campaignPlan.baseAssaultPackage.backupCapturerId;
    }
    if (mission === "ProtectCapturer") {
      force.escortIds.push(unit.id);
    } else if (getUnitDefinition(unit.type).humanBased && (mission === "CaptureBase" || mission === "CaptureGate" || mission === "ShadowCapturer" || mission === "EscortCapture" || mission === "DefendGate" || mission === "ReserveCapturer")) {
      force.capturerId ??= unit.id;
      if (mission === "ShadowCapturer" || mission === "EscortCapture" || mission === "ReserveCapturer") {
        force.escortIds.push(unit.id);
      }
    } else if (isReconUnit(unit.type)) {
      force.scoutIds.push(unit.id);
    } else if (needsReconSupport(unit.type) || unit.type === "Artillery" || unit.type === "Anti-Air" || mission === "SuppressGateZone" || mission === "CoverCounterattack") {
      force.supportIds.push(unit.id);
    } else {
      force.escortIds.push(unit.id);
    }
  }
  return forces;
}

function solveEnemyObjectiveImperatives(state: GameState, plan: EnemyTurnPlan): EnemyObjectiveImperative[] {
  const imperatives: EnemyObjectiveImperative[] = [];
  const enemyHumans = getOwnerUnits(state, "Enemy").filter((unit) => getUnitDefinition(unit.type).humanBased);
  const playerHumans = getOwnerUnits(state, "Player").filter((unit) => getUnitDefinition(unit.type).humanBased);

  // Counter names are from the Alliance perspective: Player means Alliance progress on the Player base.
  for (const unit of enemyHumans.filter((candidate) => sameHex(candidate.coord, state.bases.Player))) {
    if (state.baseOccupation.Player >= BASE_CAPTURE_DAYS - 1) {
      imperatives.push({
        id: `hold-winning-base-${unit.id}`,
        unitId: unit.id,
        targetCoord: { ...state.bases.Player },
        actionKind: "Hold",
        terminal: ENEMY_OBJECTIVE_TERMINAL_SCORE,
        reason: "guaranteed Alliance base capture",
        dependencies: []
      });
    }
  }

  // Enemy means Player progress on the Alliance base.
  for (const player of playerHumans.filter((candidate) => sameHex(candidate.coord, state.bases.Enemy))) {
    if (state.baseOccupation.Enemy >= BASE_CAPTURE_DAYS - 1) {
      const remover = chooseEnemyPlannerRemoverForTarget(state, player, plan);
      imperatives.push({
        id: `prevent-base-loss-${player.id}`,
        unitId: remover?.id,
        targetId: player.id,
        targetCoord: { ...player.coord },
        actionKind: remover && hexDistance(remover.coord, player.coord) <= getEffectiveUnitStats(state, remover.owner, remover.type, remover.level, remover.coord, player.coord).attackRange ? "Attack" : "MoveThenAttack",
        terminal: -ENEMY_OBJECTIVE_TERMINAL_SCORE,
        reason: "prevent immediate Player base capture",
        dependencies: []
      });
    }
  }

  for (const gate of state.gates ?? []) {
    const enemyCapturer = enemyHumans.find((unit) => sameHex(unit.coord, gate.coord));
    if (enemyCapturer && gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1) {
      imperatives.push({
        id: `hold-winning-gate-${gate.id}-${enemyCapturer.id}`,
        unitId: enemyCapturer.id,
        targetCoord: { ...gate.coord },
        actionKind: "Hold",
        terminal: ENEMY_OBJECTIVE_TERMINAL_SCORE * 0.2,
        reason: `hold ${gate.label} capture`,
        dependencies: []
      });
    }

    const playerCapturer = playerHumans.find((unit) => sameHex(unit.coord, gate.coord));
    if (playerCapturer && gate.occupation.Player >= GATE_CAPTURE_DAYS - 1) {
      const openingWinningGateAvailable =
        state.difficulty === "Hard" &&
        state.day <= 12 &&
        (state.gates ?? []).some((candidate) => candidate.id !== gate.id && candidate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1);
      if (openingWinningGateAvailable) {
        continue;
      }
      const remover = chooseEnemyPlannerRemoverForTarget(state, playerCapturer, plan);
      imperatives.push({
        id: `deny-player-gate-${gate.id}-${playerCapturer.id}`,
        unitId: remover?.id,
        targetId: playerCapturer.id,
        targetCoord: { ...gate.coord },
        actionKind: remover && hexDistance(remover.coord, playerCapturer.coord) <= getEffectiveUnitStats(state, remover.owner, remover.type, remover.level, remover.coord, playerCapturer.coord).attackRange ? "Attack" : "MoveThenAttack",
        terminal: -ENEMY_OBJECTIVE_TERMINAL_SCORE * 0.2,
        reason: `deny ${gate.label} capture`,
        dependencies: []
      });
    }
  }

  imperatives.push(...solveEnemyForecastObjectiveImperatives(state, plan, enemyHumans, playerHumans));
  imperatives.push(...findEnemyGateDenialFollowUpImperatives(state, plan, imperatives));

  const clearThenCapture = findEnemyClearThenCaptureImperative(state, plan);
  if (clearThenCapture && !isEnemyGateDenialFollowUpDuplicate(imperatives, clearThenCapture)) {
    imperatives.push(...clearThenCapture);
  }
  const baseBlockerClear = findEnemyBaseBlockerClearImperative(state, plan);
  if (baseBlockerClear && !imperatives.some((imperative) => imperative.targetId === baseBlockerClear.targetId)) {
    imperatives.push(baseBlockerClear);
  }

  return imperatives;
}

function isEnemyGateDenialFollowUpDuplicate(
  existingImperatives: EnemyObjectiveImperative[],
  candidateImperatives: EnemyObjectiveImperative[]
): boolean {
  const candidateCapture = candidateImperatives.find((imperative) => imperative.id.startsWith("capture-after-clear-") && imperative.targetCoord);
  if (!candidateCapture?.targetCoord) {
    return false;
  }
  return existingImperatives.some(
    (imperative) =>
      imperative.id.startsWith("capture-after-gate-denial-") &&
      imperative.targetCoord &&
      sameHex(imperative.targetCoord, candidateCapture.targetCoord!)
  );
}

function solveEnemyForecastObjectiveImperatives(
  state: GameState,
  plan: EnemyTurnPlan,
  enemyHumans: UnitInstance[],
  playerHumans: UnitInstance[]
): EnemyObjectiveImperative[] {
  const imperatives: EnemyObjectiveImperative[] = [];
  const clock = plan.campaignPlan.objectiveClock;
  const enemyTurns = clock.enemyWinForecast.turnsToWin;
  const playerTurns = clock.playerWinForecast.turnsToWin;
  const winImperative =
    enemyTurns <= 3
      ? createEnemyNearTermWinImperative(state, plan, enemyHumans, clock.enemyWinForecast)
      : undefined;
  const lossImperative =
    playerTurns <= 3
      ? createEnemyNearTermLossImperative(state, plan, playerHumans, clock.playerWinForecast)
      : undefined;

  if (winImperative && lossImperative) {
    if (playerTurns <= enemyTurns) {
      imperatives.push(lossImperative);
      if (isEnemyForecastImperativeFreeFollowUp(lossImperative, winImperative)) {
        imperatives.push(winImperative);
      }
    } else {
      imperatives.push(winImperative);
      if (isEnemyForecastImperativeFreeFollowUp(winImperative, lossImperative)) {
        imperatives.push(lossImperative);
      }
    }
    return imperatives;
  }

  if (winImperative) {
    imperatives.push(winImperative);
  }
  if (lossImperative) {
    imperatives.push(lossImperative);
  }

  return imperatives;
}

function isEnemyForecastImperativeFreeFollowUp(primary: EnemyObjectiveImperative, followUp: EnemyObjectiveImperative): boolean {
  if (!followUp.unitId) {
    return false;
  }
  return !primary.unitId || primary.unitId !== followUp.unitId;
}

function createEnemyNearTermWinImperative(
  state: GameState,
  plan: EnemyTurnPlan,
  enemyHumans: UnitInstance[],
  forecast: EnemyObjectiveWinForecast
): EnemyObjectiveImperative | undefined {
  const baseCapturer = enemyHumans.find((unit) => sameHex(unit.coord, state.bases.Player));
  const pressure = ENEMY_OBJECTIVE_TERMINAL_SCORE * (forecast.turnsToWin <= 2 ? 0.72 : 0.42) * forecast.confidence;
  if (baseCapturer && state.baseOccupation.Player > 0) {
    return {
      id: `forecast-hold-base-win-${baseCapturer.id}`,
      unitId: baseCapturer.id,
      targetCoord: { ...state.bases.Player },
      actionKind: "Hold",
      terminal: pressure,
      reason: `preserve ${forecast.turnsToWin}-turn base win`,
      dependencies: []
    };
  }

  if (ownerControlsBothGates(state, "Enemy")) {
    const capturer = enemyHumans
      .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
      .sort((first, second) => hexDistance(first.coord, state.bases.Player) - hexDistance(second.coord, state.bases.Player) || second.health - first.health)[0];
    const moveTo = capturer ? chooseEnemyPlannerClockProgressMove(state, capturer, state.bases.Player, plan) : undefined;
    if (capturer && moveTo) {
      return {
        id: `forecast-move-base-win-${capturer.id}`,
        unitId: capturer.id,
        targetCoord: { ...moveTo },
        actionKind: "Move",
        terminal: pressure,
        reason: `accelerate ${forecast.turnsToWin}-turn base win`,
        dependencies: []
      };
    }
  }

  const winningGate = (state.gates ?? [])
    .filter((gate) => gate.owner !== "Enemy" && (plan.campaignPlan.objectiveClock.enemyTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY) <= 2)
    .sort((first, second) => (plan.campaignPlan.objectiveClock.enemyTurnsToGates[first.id] ?? 99) - (plan.campaignPlan.objectiveClock.enemyTurnsToGates[second.id] ?? 99))[0];
  const gateCapturer = winningGate ? enemyHumans.find((unit) => sameHex(unit.coord, winningGate.coord)) : undefined;
  if (winningGate && gateCapturer) {
    return {
      id: `forecast-hold-gate-win-${winningGate.id}-${gateCapturer.id}`,
      unitId: gateCapturer.id,
      targetCoord: { ...winningGate.coord },
      actionKind: "Hold",
      terminal: pressure * 0.7,
      reason: `complete ${forecast.turnsToWin}-turn gate-to-base win path`,
      dependencies: []
    };
  }

  return undefined;
}

function createEnemyNearTermLossImperative(
  state: GameState,
  plan: EnemyTurnPlan,
  playerHumans: UnitInstance[],
  forecast: EnemyObjectiveWinForecast
): EnemyObjectiveImperative | undefined {
  const pressure = -ENEMY_OBJECTIVE_TERMINAL_SCORE * (forecast.turnsToWin <= 2 ? 0.68 : 0.38) * forecast.confidence;
  const baseCapturer = playerHumans.find((unit) => sameHex(unit.coord, state.bases.Enemy));
  if (baseCapturer) {
    const remover = chooseEnemyPlannerRemoverForTarget(state, baseCapturer, plan);
    if (remover) {
      return {
        id: `forecast-prevent-base-loss-${baseCapturer.id}`,
        unitId: remover.id,
        targetId: baseCapturer.id,
        targetCoord: { ...baseCapturer.coord },
        actionKind: hexDistance(remover.coord, baseCapturer.coord) <= getEffectiveUnitStats(state, remover.owner, remover.type, remover.level, remover.coord, baseCapturer.coord).attackRange ? "Attack" : "MoveThenAttack",
        terminal: pressure,
        reason: `prevent ${forecast.turnsToWin}-turn base loss`,
        dependencies: []
      };
    }
  }

  const threatenedGate = (state.gates ?? []).find((gate) => gate.id === forecast.vulnerableGateId) ??
    (state.gates ?? [])
      .filter((gate) => (plan.campaignPlan.objectiveClock.playerTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY) <= 2)
      .sort((first, second) => (plan.campaignPlan.objectiveClock.playerTurnsToGates[first.id] ?? 99) - (plan.campaignPlan.objectiveClock.playerTurnsToGates[second.id] ?? 99))[0];
  const playerCapturer = threatenedGate
    ? playerHumans
        .filter((unit) => hexDistance(unit.coord, threatenedGate.coord) <= 1)
        .sort((first, second) => hexDistance(first.coord, threatenedGate.coord) - hexDistance(second.coord, threatenedGate.coord))[0]
    : undefined;
  if (playerCapturer) {
    const remover = chooseEnemyPlannerRemoverForTarget(state, playerCapturer, plan);
    if (remover) {
      return {
        id: `forecast-deny-gate-loss-${threatenedGate!.id}-${playerCapturer.id}`,
        unitId: remover.id,
        targetId: playerCapturer.id,
        targetCoord: { ...playerCapturer.coord },
        actionKind: hexDistance(remover.coord, playerCapturer.coord) <= getEffectiveUnitStats(state, remover.owner, remover.type, remover.level, remover.coord, playerCapturer.coord).attackRange ? "Attack" : "MoveThenAttack",
        terminal: pressure * 0.75,
        reason: `break ${forecast.turnsToWin}-turn player gate-to-base win path`,
        dependencies: []
      };
    }
  }

  const defender = getOwnerUnits(state, "Enemy")
    .filter((unit) => canUnitTargetUnit(unit.type, "Infantry"))
    .sort((first, second) => hexDistance(first.coord, state.bases.Enemy) - hexDistance(second.coord, state.bases.Enemy) || first.id.localeCompare(second.id))[0];
  const moveTo = defender ? chooseEnemyPlannerClockProgressMove(state, defender, state.bases.Enemy, plan) : undefined;
  if (defender && moveTo) {
    return {
      id: `forecast-defend-base-loss-${defender.id}`,
      unitId: defender.id,
      targetCoord: { ...moveTo },
      actionKind: "Move",
      terminal: pressure * 0.55,
      reason: `pre-position against ${forecast.turnsToWin}-turn base loss`,
      dependencies: []
    };
  }

  return undefined;
}

function chooseEnemyPlannerClockProgressMove(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance["coord"],
  plan: EnemyTurnPlan
): UnitInstance["coord"] | undefined {
  const currentDistance = hexDistance(unit.coord, target);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0 || currentDistance === 0) {
    return undefined;
  }
  const path = findMovementPath(state, unit, target);
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (canMoveUnitTo(state, unit, coord) && hexDistance(coord, target) < currentDistance) {
        return coord;
      }
    }
  }
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => hexDistance(coord, target) < currentDistance)
    .sort((first, second) => {
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return hexDistance(first, target) - hexDistance(second, target) || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
}

function reconcileEnemyRolesAfterImperatives(state: GameState, plan: EnemyTurnPlan): void {
  for (const imperative of plan.objectiveImperatives) {
    if (!imperative.unitId) {
      continue;
    }

    const unit = getUnitById(state, imperative.unitId);
    if (!unit || unit.owner !== "Enemy") {
      continue;
    }

    if (imperative.id.startsWith("deny-player-gate-") || imperative.id.startsWith("forecast-deny-gate-loss-")) {
      if (isEnemyGateLockoutCombatMission(plan.rolesByUnitId[unit.id])) {
        continue;
      }
      if (
        ownerControlsBothGates(state, "Enemy") &&
        getUnitDefinition(unit.type).humanBased &&
        hexDistance(unit.coord, state.bases.Player) < (state.gates ?? []).reduce((best, gate) => Math.min(best, hexDistance(unit.coord, gate.coord)), Number.POSITIVE_INFINITY)
      ) {
        continue;
      }
      plan.rolesByUnitId[unit.id] = "DefendGate";
      continue;
    }

    if (imperative.id.startsWith("prevent-base-loss-") || imperative.id.startsWith("forecast-prevent-base-loss-") || imperative.id.startsWith("forecast-defend-base-loss-")) {
      plan.rolesByUnitId[unit.id] = "DefendBase";
      continue;
    }

    if (!getUnitDefinition(unit.type).humanBased) {
      continue;
    }

    if (imperative.id.startsWith("hold-winning-gate-") || imperative.id.startsWith("forecast-hold-gate-win-")) {
      plan.rolesByUnitId[unit.id] = "CaptureGate";
    } else if (imperative.id.startsWith("hold-winning-base-") || imperative.id.startsWith("forecast-hold-base-win-") || imperative.id.startsWith("forecast-move-base-win-")) {
      plan.rolesByUnitId[unit.id] = "CaptureBase";
    } else if (imperative.id.startsWith("capture-after-clear-") || imperative.id.startsWith("capture-after-gate-denial-")) {
      plan.rolesByUnitId[unit.id] = imperative.targetCoord && sameHex(imperative.targetCoord, state.bases.Player) ? "CaptureBase" : "CaptureGate";
    }
  }
}

function isEnemyPlannerDecisiveMoment(state: GameState, plan: EnemyTurnPlan): boolean {
  if (
    plan.objectiveImperatives.length > 0 ||
    state.baseOccupation.Player > 0 ||
    state.baseOccupation.Enemy > 0 ||
    plan.campaignPlan.objectiveClock.enemyWinForecast.turnsToWin <= 3 ||
    plan.campaignPlan.objectiveClock.playerWinForecast.turnsToWin <= 3
  ) {
    return true;
  }

  if ((state.gates ?? []).some((gate) => gate.occupation.Player > 0 || gate.occupation.Enemy > 0)) {
    return true;
  }

  if ((state.gates ?? []).some((gate) => gate.owner === "Enemy" && (plan.strategicSnapshot.predictedGatePressure[gate.id] ?? 0) > 65)) {
    return true;
  }

  return plan.playerIntel.some(
    (intel) =>
      intel.age === 0 &&
      (intel.unit.type === "Anti-Air" ||
        getUnitDefinition(intel.unit.type).humanBased ||
        isCoordInEnemyHomeArea(state, intel.predictedCoord) ||
        (state.gates ?? []).some((gate) => hexDistance(intel.predictedCoord, gate.coord) <= 2))
  );
}

function chooseEnemyPlannerRemoverForTarget(state: GameState, target: UnitInstance, plan: EnemyTurnPlan): UnitInstance | undefined {
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => canUnitTargetUnit(unit.type, target.type))
    .filter((unit) => isEnemyFireSupportAttackIntelAuthorized(state, unit, target, plan))
    .map((unit) => {
      const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord);
      const distance = hexDistance(unit.coord, target.coord);
      const canAttackNow = distance <= stats.attackRange;
      const canMoveAttack = !isMoveAttackExclusiveUnit(unit.type) && distance <= stats.attackRange + getEffectiveRemainingMovementToCoord(state, unit, target.coord);
      return {
        unit,
        score: (canAttackNow ? 200 : canMoveAttack ? 120 : 0) + getExpectedAttackOutcome(state, unit, target).killProbability * 100 - distance * 4
      };
    })
    .filter((entry) => entry.score > 0)
    .sort((first, second) => second.score - first.score || first.unit.id.localeCompare(second.unit.id))[0]?.unit;
}

function findEnemyGateDenialFollowUpImperatives(
  state: GameState,
  plan: EnemyTurnPlan,
  imperatives: EnemyObjectiveImperative[]
): EnemyObjectiveImperative[] {
  const followUps: EnemyObjectiveImperative[] = [];
  for (const denial of imperatives.filter((imperative) => imperative.id.startsWith("deny-player-gate-") || imperative.id.startsWith("forecast-deny-gate-loss-"))) {
    if (!denial.unitId || !denial.targetId || !denial.targetCoord) {
      continue;
    }

    const playerCapturer = getUnitById(state, denial.targetId);
    const clearer = getUnitById(state, denial.unitId);
    const gate = (state.gates ?? []).find((candidate) => sameHex(candidate.coord, denial.targetCoord!));
    if (!playerCapturer || !clearer || playerCapturer.owner !== "Player" || !gate || !sameHex(playerCapturer.coord, gate.coord)) {
      continue;
    }

    const outcome = getExpectedAttackOutcome(state, clearer, playerCapturer);
    if (outcome.killProbability < 0.82) {
      continue;
    }

    const occupier = chooseEnemyGateDenialFollowUpCapturer(state, gate, playerCapturer, clearer, plan);
    if (!occupier) {
      continue;
    }

    followUps.push({
      id: `capture-after-gate-denial-${gate.id}-${occupier.id}-${playerCapturer.id}`,
      unitId: occupier.id,
      targetCoord: { ...gate.coord },
      actionKind: "Move",
      terminal: Math.abs(denial.terminal) * 0.72,
      reason: `occupy ${gate.label} after denial`,
      dependencies: [clearer.id]
    });
  }
  return followUps;
}

function chooseEnemyGateDenialFollowUpCapturer(
  state: GameState,
  gate: GateState,
  playerCapturer: UnitInstance,
  clearer: UnitInstance,
  plan: EnemyTurnPlan
): UnitInstance | undefined {
  const afterClear = cloneState(state);
  afterClear.units = afterClear.units.filter((unit) => unit.id !== playerCapturer.id);
  const gateRoleIds = new Set(
    Object.entries(plan.rolesByUnitId)
      .filter(([, role]) => role === "CaptureGate" || role === "DefendGate" || role === "ShadowCapturer" || role === "EscortCapture")
      .map(([unitId]) => unitId)
  );
  return getOwnerUnits(afterClear, "Enemy")
    .filter((unit) => unit.id !== clearer.id)
    .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => canMoveUnitTo(afterClear, unit, gate.coord))
    .sort((first, second) => {
      const firstRole = gateRoleIds.has(first.id) ? 80 : 0;
      const secondRole = gateRoleIds.has(second.id) ? 80 : 0;
      return (
        secondRole - firstRole ||
        hexDistance(first.coord, gate.coord) - hexDistance(second.coord, gate.coord) ||
        getUnitInstanceValue(afterClear, second) - getUnitInstanceValue(afterClear, first) ||
        first.id.localeCompare(second.id)
      );
    })[0];
}

function findEnemyClearThenCaptureImperative(state: GameState, plan: EnemyTurnPlan): EnemyObjectiveImperative[] | undefined {
  const objective = ownerControlsBothGates(state, "Enemy") || state.baseOccupation.Player > 0
    ? state.bases.Player
    : chooseGateObjective(state, "Enemy", state.bases.Enemy)?.coord;
  if (!objective) {
    return undefined;
  }
  const blocker = getOwnerUnits(state, "Player").find((unit) => sameHex(unit.coord, objective));
  if (!blocker) {
    return undefined;
  }
  const packageCapturer = plan.campaignPlan.baseAssaultPackage.capturerId
    ? getUnitById(state, plan.campaignPlan.baseAssaultPackage.capturerId)
    : undefined;
  const capturer =
    packageCapturer && getUnitDefinition(packageCapturer.type).humanBased && canEnemyUnitReachObjectiveThisTurn(state, packageCapturer, objective)
      ? packageCapturer
      : getOwnerUnits(state, "Enemy").find(
          (unit) => getUnitDefinition(unit.type).humanBased && canEnemyUnitReachObjectiveThisTurn(state, unit, objective)
        );
  const packageClearers = plan.campaignPlan.baseAssaultPackage.damageDealerIds
    .map((unitId) => getUnitById(state, unitId))
    .filter((unit): unit is UnitInstance => Boolean(unit && canUnitTargetUnit(unit.type, blocker.type)))
    .filter((unit) => isEnemyFireSupportAttackIntelAuthorized(state, unit, blocker, plan))
    .filter((unit) => {
      const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, blocker.coord);
      const distance = hexDistance(unit.coord, blocker.coord);
      return distance <= stats.attackRange || (!isMoveAttackExclusiveUnit(unit.type) && distance <= stats.attackRange + getEffectiveRemainingMovementToCoord(state, unit, blocker.coord));
    })
    .sort((first, second) => getExpectedAttackOutcome(state, second, blocker).killProbability - getExpectedAttackOutcome(state, first, blocker).killProbability || first.id.localeCompare(second.id));
  const clearer = packageClearers[0] ?? chooseEnemyPlannerRemoverForTarget(state, blocker, plan);
  if (!capturer || !clearer) {
    return undefined;
  }
  return [
    {
      id: `clear-blocker-${clearer.id}-${blocker.id}`,
      unitId: clearer.id,
      targetId: blocker.id,
      targetCoord: { ...blocker.coord },
      actionKind: hexDistance(clearer.coord, blocker.coord) <= getEffectiveUnitStats(state, clearer.owner, clearer.type, clearer.level, clearer.coord, blocker.coord).attackRange ? "Attack" : "MoveThenAttack",
      terminal: ENEMY_OBJECTIVE_TERMINAL_SCORE * 0.5,
      reason: "clear blocker for capture",
      dependencies: []
    },
    {
      id: `capture-after-clear-${capturer.id}`,
      unitId: capturer.id,
      targetCoord: { ...objective },
      actionKind: "Move",
      terminal: ENEMY_OBJECTIVE_TERMINAL_SCORE * 0.45,
      reason: "enter objective after blocker clear",
      dependencies: [clearer.id]
    }
  ];
}

function findEnemyBaseBlockerClearImperative(state: GameState, plan: EnemyTurnPlan): EnemyObjectiveImperative | undefined {
  if (!ownerControlsBothGates(state, "Enemy") && state.baseOccupation.Player <= 0) {
    return undefined;
  }

  const blocker = getOwnerUnits(state, "Player").find((unit) => sameHex(unit.coord, state.bases.Player));
  if (!blocker) {
    return undefined;
  }

  const clearer = getOwnerUnits(state, "Enemy")
    .filter((unit) => canUnitTargetUnit(unit.type, blocker.type))
    .filter((unit) => isEnemyFireSupportAttackIntelAuthorized(state, unit, blocker, plan))
    .filter((unit) => {
      const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, blocker.coord);
      const distance = hexDistance(unit.coord, blocker.coord);
      return distance <= stats.attackRange || (!isMoveAttackExclusiveUnit(unit.type) && distance <= stats.attackRange + getEffectiveRemainingMovementToCoord(state, unit, blocker.coord));
    })
    .sort((first, second) => {
      const firstOutcome = getExpectedAttackOutcome(state, first, blocker);
      const secondOutcome = getExpectedAttackOutcome(state, second, blocker);
      return secondOutcome.killProbability - firstOutcome.killProbability || secondOutcome.expectedDamage - firstOutcome.expectedDamage || first.id.localeCompare(second.id);
    })[0];
  if (!clearer) {
    return undefined;
  }

  return {
    id: `clear-base-blocker-${clearer.id}-${blocker.id}`,
    unitId: clearer.id,
    targetId: blocker.id,
    targetCoord: { ...blocker.coord },
    actionKind: hexDistance(clearer.coord, blocker.coord) <= getEffectiveUnitStats(state, clearer.owner, clearer.type, clearer.level, clearer.coord, blocker.coord).attackRange ? "Attack" : "MoveThenAttack",
    terminal: ENEMY_OBJECTIVE_TERMINAL_SCORE * 0.42,
    reason: "clear base blocker under fog",
    dependencies: []
  };
}

function canEnemyUnitReachObjectiveThisTurn(state: GameState, unit: UnitInstance, objective: UnitInstance["coord"]): boolean {
  const effectiveMove = getEffectiveRemainingMovementToCoord(state, unit, objective);
  return hexDistance(unit.coord, objective) <= effectiveMove;
}

function getEffectiveRemainingMovementToCoord(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const destinationMove = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, coord).moveRange - (unit.movementSpentThisDay ?? 0);
  return Math.max(0, Math.min(getRemainingMovementPoints(state, unit), destinationMove));
}

function buildEnemyActivationDependencies(state: GameState, plan: EnemyTurnPlan): Record<string, string[]> {
  const dependencies: Record<string, string[]> = {};
  const add = (unitId: string | undefined, dependsOn: string | undefined): void => {
    if (!unitId || !dependsOn || unitId === dependsOn) {
      return;
    }
    dependencies[unitId] ??= [];
    if (!dependencies[unitId].includes(dependsOn)) {
      dependencies[unitId].push(dependsOn);
    }
  };

  for (const imperative of plan.objectiveImperatives) {
    for (const dependency of imperative.dependencies) {
      add(imperative.unitId, dependency);
    }
  }

  const scouts = getOwnerUnits(state, "Enemy").filter((unit) => isReconUnit(unit.type));
  const fireSupport = getOwnerUnits(state, "Enemy").filter((unit) => needsReconSupport(unit.type) || unit.type === "Artillery" || unit.type === "Anti-Air");
  const scout = scouts.sort((first, second) => scoreEnemyPlannerActivation(state, second, plan) - scoreEnemyPlannerActivation(state, first, plan))[0];
  if (scout && plan.strategicSnapshot.scoutNeed > 40) {
    for (const support of fireSupport) {
      add(support.id, scout.id);
    }
  }

  if (plan.campaignPlan.phase === "GateLockoutCombat") {
    const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
    const lockoutScout = gate ? chooseEnemyGateLockoutReconDependencyScout(state, plan, gate) : undefined;
    if (gate && lockoutScout) {
      for (const unit of getOwnerUnits(state, "Enemy")) {
        if (unit.id === lockoutScout.id || !shouldEnemyGateLockoutUnitWaitForRecon(state, unit, plan.rolesByUnitId[unit.id], gate)) {
          continue;
        }
        add(unit.id, lockoutScout.id);
      }
    }
  }

  const sentry = getOwnerUnits(state, "Enemy").find((unit) => (plan.rolesByUnitId[unit.id] ?? "") === "BaseSentry");
  if (sentry) {
    for (const unit of getOwnerUnits(state, "Enemy").filter((candidate) => plan.rolesByUnitId[candidate.id] === "CaptureGate")) {
      add(unit.id, sentry.id);
    }
  }
  return dependencies;
}

function chooseEnemyGateLockoutReconDependencyScout(state: GameState, plan: EnemyTurnPlan, gate: GateState): UnitInstance | undefined {
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => plan.rolesByUnitId[unit.id] === "Scout")
    .filter((unit) => isEnemyGateLockoutReconUnit(unit.type))
    .sort((first, second) => scoreEnemyGateLockoutReconCandidate(state, second, gate) - scoreEnemyGateLockoutReconCandidate(state, first, gate) || first.id.localeCompare(second.id))[0];
}

function shouldEnemyGateLockoutUnitWaitForRecon(state: GameState, unit: UnitInstance, mission: EnemyMission | undefined, gate: GateState): boolean {
  if (unit.health <= 0 || mission === "Repair" || mission === "Scout") {
    return false;
  }
  const definition = getUnitDefinition(unit.type);
  if (definition.domain === "Air" && (isEnemyGateLockoutClearingMission(mission) || mission === "HuntArtillery" || mission === "Siege" || mission === "Escort")) {
    return true;
  }
  if (
    definition.humanBased &&
    (mission === "ReserveCapturer" || mission === "CaptureGate") &&
    (unit.type === "Infantry" || unit.health / Math.max(1, unit.maxHealth) <= 0.75 || hexDistance(unit.coord, gate.coord) <= 6)
  ) {
    return true;
  }
  return false;
}

function chooseEnemyPlannerActivationOrder(state: GameState, plan: EnemyTurnPlan): string[] {
  const units = getOwnerUnits(state, "Enemy")
    .filter((unit) => unit.placedDay !== state.day)
    .map((unit) => ({
      unit,
      score: scoreEnemyPlannerActivation(state, unit, plan)
    }))
    .sort((first, second) => second.score - first.score || first.unit.id.localeCompare(second.unit.id))
    .map((entry) => entry.unit.id);
  const ordered: string[] = [];
  const orderedSet = new Set<string>();
  const remaining = new Set(units);
  while (remaining.size > 0) {
    const ready = [...remaining].find((unitId) => (plan.activationDependencies[unitId] ?? []).every((dependency) => orderedSet.has(dependency) || !remaining.has(dependency)));
    const chosen = ready ?? [...remaining][0];
    ordered.push(chosen);
    orderedSet.add(chosen);
    remaining.delete(chosen);
  }
  return ordered;
}

function scoreEnemyPlannerActivation(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): number {
  const imperative = plan.objectiveImperatives.find((entry) => entry.unitId === unit.id);
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const attack = getEnemyPlannerAttackTargets(state, unit, plan).sort((first, second) => second.score - first.score)[0];
  const openingGateEntryBonus =
    state.day <= 12 &&
    getUnitDefinition(unit.type).humanBased &&
    (state.gates ?? []).some((gate) => gate.owner !== "Enemy" && hexDistance(unit.coord, gate.coord) <= 2)
      ? 220
      : 0;
  return (
    (imperative ? Math.abs(imperative.terminal) : 0) +
    (mission === "DefendBase" ? 500 :
      mission === "BaseSentry" ? 250 :
      mission === "PatrolWest" || mission === "PatrolEast" ? (state.day <= 5 ? 220 : 120) :
      mission === "Scout" ? 140 :
      mission === "CaptureGate" ? (state.day <= 12 ? 190 : 120) :
      mission === "ProtectCapturer" ? 180 :
      mission === "Escort" ? (state.day <= 12 ? 150 : 80) :
      80) +
    (attack?.score ?? 0) +
    openingGateEntryBonus +
    getUnitInstanceValue(state, unit) * 0.05
  );
}

function enumerateEnemyCompoundActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyCompoundAction[] {
  const immediateBaseLossImperative = plan.objectiveImperatives.some((imperative) => imperative.unitId === unit.id && imperative.id.startsWith("prevent-base-loss-"));
  const antiAirThreatMap = getEnemyAntiAirThreatMap(state, plan);
  if (!immediateBaseLossImperative && shouldEnemyAttemptRepairRetreat(state, unit)) {
    const retreat = chooseEnemyPlannerRetreatMove(state, unit, plan, reservedDestinations);
    if (retreat) {
      const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: retreat }, reservedDestinations, reservedExpectedDamage);
      if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
        return [action];
      }
    }
  }
  const priorityBaseAssaultActions = enumerateEnemyPriorityBaseAssaultActions(
    state,
    unit,
    plan,
    reservedDestinations,
    reservedExpectedDamage
  );
  if (priorityBaseAssaultActions.length) {
    return priorityBaseAssaultActions;
  }
  const activeGateClockMove = chooseEnemyActiveGateClockMove(state, unit, plan);
  if (activeGateClockMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: activeGateClockMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const highAltitudeSuppressionAction = chooseEnemyHighAltitudePrioritySuppressionAction(
    state,
    unit,
    plan,
    reservedDestinations,
    reservedExpectedDamage,
    antiAirThreatMap
  );
  if (highAltitudeSuppressionAction) {
    return [highAltitudeSuppressionAction];
  }
  const immediateTacticalAttacks = enumerateEnemyImmediateTacticalAttackActions(
    state,
    unit,
    plan,
    reservedDestinations,
    reservedExpectedDamage,
    antiAirThreatMap
  );
  if (immediateTacticalAttacks.length) {
    return immediateTacticalAttacks;
  }

  const lockoutBreakoutMove = !immediateBaseLossImperative && shouldForceGateLockoutBreakout(state, unit, plan)
    ? chooseEnemyPlannerForcedGateBreakoutMove(state, unit, plan)
    : undefined;
  if (lockoutBreakoutMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: lockoutBreakoutMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const occupiedGate = (state.gates ?? []).find((gate) => sameHex(gate.coord, unit.coord));
  if (occupiedGate && shouldEnemyNonCapturerHoldGateAsOnlyBlocker(state, unit, occupiedGate)) {
    const attack = getEnemyPlannerAttackTargets(state, unit, plan)[0];
    if (attack) {
      const action = createEnemyCompoundAction(
        state,
        unit,
        plan,
        "Attack",
        { attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
        reservedDestinations,
        reservedExpectedDamage
      );
      if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
        return [action];
      }
    }
    return [createEnemyCompoundAction(state, unit, plan, "Hold", {}, reservedDestinations, reservedExpectedDamage)];
  }
  const forced = getPlausibleEnemyCompoundActions(
    state,
    unit,
    plan,
    enumerateForcedEnemyCompoundActions(state, unit, plan, reservedDestinations, reservedExpectedDamage)
  );
  if (forced.length) {
    return forced;
  }

  const openingCaptureGateProgressMove = chooseHardOpeningCaptureGateProgressMove(state, unit, plan, reservedDestinations);
  if (openingCaptureGateProgressMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: openingCaptureGateProgressMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const hardObjectiveActions = getPlausibleEnemyCompoundActions(
    state,
    unit,
    plan,
    enumerateHardObjectiveEnemyCompoundActions(state, unit, plan, reservedDestinations, reservedExpectedDamage)
  );
  if (hardObjectiveActions.length) {
    return hardObjectiveActions;
  }
  if (shouldEnemyAttemptRepairRetreat(state, unit)) {
    const retreat = chooseEnemyPlannerRetreatMove(state, unit, plan, reservedDestinations);
    if (retreat) {
      const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: retreat }, reservedDestinations, reservedExpectedDamage);
      if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
        return [action];
      }
    }
  }
  const nonCapturerGateTileMove = chooseEnemyPlannerNonCapturerGateTileMove(state, unit, plan);
  if (nonCapturerGateTileMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: nonCapturerGateTileMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const gateBlockerMove = chooseEnemyPlannerGateBlockerMove(state, unit, plan);
  if (gateBlockerMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: gateBlockerMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const scoutGateStandoffMove = chooseEnemyPlannerScoutGateStandoffMove(state, unit, plan);
  if (scoutGateStandoffMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: scoutGateStandoffMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const forcedOpeningPatrolMove = chooseEnemyPlannerForcedOpeningPatrolMove(state, unit, plan, reservedDestinations);
  if (forcedOpeningPatrolMove) {
    if (isEnemyAirMoveCandidateAllowed(state, unit, forcedOpeningPatrolMove, plan, antiAirThreatMap)) {
      const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedOpeningPatrolMove }, reservedDestinations, reservedExpectedDamage);
      if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
        return [action];
      }
    }
  }
  const earlyPatrolMove = chooseEnemyPlannerEarlyPatrolPriorityMove(state, unit, plan, reservedDestinations);
  if (earlyPatrolMove && isEnemyAirMoveCandidateAllowed(state, unit, earlyPatrolMove, plan, antiAirThreatMap)) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: earlyPatrolMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  if (shouldEnemyPlannerOpeningGateCapturerHold(state, unit, plan)) {
    return [createEnemyCompoundAction(state, unit, plan, "Hold", {}, reservedDestinations, reservedExpectedDamage)];
  }
  const forcedOpeningGateCapturerMove = chooseEnemyPlannerOpeningGateCapturerMove(state, unit, plan, reservedDestinations);
  if (forcedOpeningGateCapturerMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedOpeningGateCapturerMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const forcedGateEntryMove = chooseEnemyPlannerForcedOpeningGateEntryMove(state, unit, plan);
  if (forcedGateEntryMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedGateEntryMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const forcedMidgameCenterControlMove = chooseEnemyPlannerMidgameCenterControlMove(state, unit, plan);
  if (forcedMidgameCenterControlMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedMidgameCenterControlMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const forcedEarlyArmorFormationMove = chooseEnemyPlannerEarlyArmorFormationMove(state, unit, plan, reservedDestinations);
  if (forcedEarlyArmorFormationMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedEarlyArmorFormationMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const forcedOpeningGateEscortMove = chooseEnemyPlannerOpeningGateEscortMove(state, unit, plan, reservedDestinations);
  if (forcedOpeningGateEscortMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedOpeningGateEscortMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const forcedFireSupportStagingMove = chooseEnemyPlannerFireSupportMove(state, unit, plan);
  if (forcedFireSupportStagingMove && shouldForceEnemyFireSupportCenterStaging(state, unit, forcedFireSupportStagingMove, plan)) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedFireSupportStagingMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
    if (isHardOpeningDoctrineActive(state) && unit.coord.r > getEnemyCenterSupportStagingCoord(state, plan).r + 2) {
      return [action];
    }
  }
  if (shouldEnemyPlannerOpeningGateSupportHold(state, unit, plan)) {
    return [createEnemyCompoundAction(state, unit, plan, "Hold", {}, reservedDestinations, reservedExpectedDamage)];
  }
  const forcedBaseAssaultMove = chooseEnemyPlannerForcedBaseAssaultMove(state, unit, plan);
  if (forcedBaseAssaultMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedBaseAssaultMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const forcedEndgamePushMove = chooseEnemyPlannerEndgamePushMove(state, unit, plan);
  if (forcedEndgamePushMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedEndgamePushMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const forcedGateBreakoutMove = chooseEnemyPlannerForcedGateBreakoutMove(state, unit, plan);
  if (forcedGateBreakoutMove) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: forcedGateBreakoutMove }, reservedDestinations, reservedExpectedDamage);
    if (isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
      return [action];
    }
  }
  const actions: EnemyCompoundAction[] = [];
  actions.push(createEnemyCompoundAction(state, unit, plan, "Hold", {}, reservedDestinations, reservedExpectedDamage));

  for (const attack of getEnemyPlannerAttackOptions(state, unit, plan, reservedExpectedDamage)) {
    actions.push(createEnemyCompoundAction(
      state,
      unit,
      plan,
      "Attack",
      { attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
      reservedDestinations,
      reservedExpectedDamage
    ));
  }

  const committedMoveCoords = uniqueCoords([
    chooseEnemyPlannerCommittedBaseAssaultMove(state, unit, plan),
    chooseEnemyPlannerBaseHoldProtectionMove(state, unit, plan),
    chooseEnemyPlannerEndgamePushMove(state, unit, plan),
    chooseEnemyPlannerMidgameCenterControlMove(state, unit, plan),
    chooseEnemyPlannerOpeningGateCapturerMove(state, unit, plan, reservedDestinations),
    chooseEnemyPlannerOpeningGateEscortMove(state, unit, plan, reservedDestinations),
    chooseEnemyPlannerSupplyTruckSupportMove(state, unit, plan),
    chooseEnemyPlannerFireSupportMove(state, unit, plan),
    chooseEnemyPlannerOpeningPatrolMove(state, unit, plan, reservedDestinations)
  ].filter((coord): coord is UnitInstance["coord"] => Boolean(coord)));
  const moveCoords = uniqueCoords([...committedMoveCoords, ...getEnemyPlannerCandidateMoveCoords(state, unit, plan, reservedDestinations)])
    .slice(0, getEnemyPlannerMoveCandidateCap(state, unit, plan) + committedMoveCoords.length);
  for (const moveTo of moveCoords) {
    if (isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap)) {
      actions.push(createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, reservedDestinations, reservedExpectedDamage));
    }
    if (!isMoveAttackExclusiveUnit(unit.type)) {
      const movedUnit: UnitInstance = {
        ...unit,
        coord: { ...moveTo },
        movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, moveTo)
      };
      for (const attack of getEnemyPlannerAttackOptions(state, movedUnit, plan, reservedExpectedDamage)) {
        if (!isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap, {
          targetId: attack.target.id,
          expectedOutcome: attack.outcome
        })) {
          continue;
        }
        actions.push(createEnemyCompoundAction(
          state,
          unit,
          plan,
          "MoveThenAttack",
          { moveTo, attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
          reservedDestinations,
          reservedExpectedDamage
        ));
        if (!shouldEnemyAttemptRepairRetreat(state, unit)) {
          for (const retreatTo of getEnemyMoveAttackRetreatCoords(state, unit, movedUnit, attack, plan, reservedDestinations, antiAirThreatMap).slice(0, 2)) {
            actions.push(createEnemyCompoundAction(
              state,
              unit,
              plan,
              "MoveAttackRetreat",
              {
                moveTo,
                retreatTo,
                attackAt: attack.target.coord,
                targetId: attack.target.id,
                targetType: attack.target.type,
                expectedOutcome: attack.outcome
              },
              reservedDestinations,
              reservedExpectedDamage
            ));
          }
        }
      }
    }
  }

  if (!isMoveAttackExclusiveUnit(unit.type)) {
    const attacks = getEnemyPlannerAttackOptions(state, unit, plan, reservedExpectedDamage);
    const bestPostAttackMove = moveCoords[0];
    if (bestPostAttackMove) {
      for (const attack of attacks) {
        const postAttackMoveAllowed = isEnemyAirMoveCandidateAllowed(state, unit, bestPostAttackMove, plan, antiAirThreatMap, {
          targetId: attack.target.id,
          expectedOutcome: attack.outcome
        });
        if (postAttackMoveAllowed) {
          actions.push(createEnemyCompoundAction(
            state,
            unit,
            plan,
            "AttackThenMove",
            {
              moveTo: bestPostAttackMove,
              attackAt: attack.target.coord,
              targetId: attack.target.id,
              targetType: attack.target.type,
              expectedOutcome: attack.outcome
            },
            reservedDestinations,
            reservedExpectedDamage
          ));
        }
      }
    }
  }

  const plausibleActions = getPlausibleEnemyCompoundActions(state, unit, plan, actions)
    .sort((first, second) => compareEnemyCompoundActionsForPlanning(state, unit, plan, first, second))
    .slice(0, ENEMY_PLANNER_ACTION_CAP);
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (
    !plausibleActions.length &&
    getUnitDefinition(unit.type).humanBased &&
    (mission === "CaptureBase" || (ownerControlsBothGates(state, "Enemy") && isEnemyBaseOperationPhase(plan.campaignPlan.phase)))
  ) {
    const moveTo = chooseEnemyHardObjectiveMove(state, unit, state.bases.Player, plan, reservedDestinations);
    if (moveTo) {
      return [createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, reservedDestinations, reservedExpectedDamage)];
    }
    const fallback = getEnemyLegalMoveCoords(state, unit)
      .filter((coord) => canMoveUnitTo(state, unit, coord))
      .filter((coord) => hexDistance(coord, state.bases.Player) < hexDistance(unit.coord, state.bases.Player))
      .sort((first, second) => hexDistance(first, state.bases.Player) - hexDistance(second, state.bases.Player) || hexId(first).localeCompare(hexId(second)))[0];
    if (fallback) {
      return [createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: fallback }, reservedDestinations, reservedExpectedDamage)];
    }
  }
  return plausibleActions;
}

function chooseEnemyActiveGateClockMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (!getUnitDefinition(unit.type).humanBased || unit.hasMovedThisDay) {
    return undefined;
  }

  const gate = (state.gates ?? [])
    .filter((candidate) => candidate.owner !== "Enemy" && candidate.occupation.Enemy > 0)
    .filter((candidate) => !sameHex(unit.coord, candidate.coord))
    .filter((candidate) => canMoveUnitTo(state, unit, candidate.coord))
    .filter((candidate) => isGateSafeForRecapture(state, candidate, unit, plan))
    .sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord) || second.occupation.Enemy - first.occupation.Enemy)[0];
  return gate?.coord;
}

function enumerateEnemyPriorityBaseAssaultActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyCompoundAction[] {
  if (!isHardEndgameDoctrineActive(state, plan) || unit.placedDay === state.day) {
    return [];
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission === "CaptureBase" && getUnitDefinition(unit.type).humanBased && !unit.hasMovedThisDay) {
    const objectiveActions = getPlausibleEnemyCompoundActions(
      state,
      unit,
      plan,
      enumerateHardObjectiveEnemyCompoundActions(state, unit, plan, reservedDestinations, reservedExpectedDamage)
    );
    if (objectiveActions.length) {
      return objectiveActions;
    }
  }

  if (mission !== "Siege" || !isEnemyBaseAttackCombatUnit(unit)) {
    return [];
  }

  if (!isCoordInPlayerBaseAssaultArea(state, unit.coord)) {
    const moveTo = chooseEnemyPlannerForcedBaseAttackMove(state, unit, plan);
    if (moveTo) {
      const move = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, reservedDestinations, reservedExpectedDamage);
      if (isEnemyCompoundActionPlausiblyLegal(state, unit, move, plan)) {
        return [move];
      }
    }
  }

  const baseAreaAttackActions = enumerateEnemyPriorityBaseAreaAttackActions(
    state,
    unit,
    plan,
    reservedDestinations,
    reservedExpectedDamage
  );
  if (baseAreaAttackActions.length) {
    return baseAreaAttackActions;
  }

  const baseBlocker = getPlayerBaseTileBlocker(state);
  if (
    baseBlocker &&
    !unit.hasAttackedThisDay &&
    canUnitTargetUnit(unit.type, baseBlocker.type) &&
    canUnitAttackHex(state, unit, baseBlocker.coord)
  ) {
    const blockerAction = createEnemyCompoundAction(
      state,
      unit,
      plan,
      "Attack",
      {
        attackAt: baseBlocker.coord,
        targetId: baseBlocker.id,
        targetType: baseBlocker.type,
        expectedOutcome: getExpectedAttackOutcome(state, unit, baseBlocker)
      },
      reservedDestinations,
      reservedExpectedDamage
    );
    const plausibleBlockerActions = getPlausibleEnemyCompoundActions(state, unit, plan, [blockerAction]);
    if (plausibleBlockerActions.length) {
      return plausibleBlockerActions;
    }
  }

  const moveTo = chooseEnemyPlannerForcedBaseAttackMove(state, unit, plan);
  if (!moveTo) {
    return [];
  }

  const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, reservedDestinations, reservedExpectedDamage);
  return getPlausibleEnemyCompoundActions(state, unit, plan, [action]);
}

function enumerateEnemyPriorityBaseAreaAttackActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyCompoundAction[] {
  if (unit.hasAttackedThisDay) {
    return [];
  }

  const directAttacks = getEnemyPlannerAttackOptions(state, unit, plan, reservedExpectedDamage)
    .filter((attack) => isPlayerBaseAreaAssaultTarget(state, attack.target))
    .map((attack) =>
      createEnemyCompoundAction(
        state,
        unit,
        plan,
        "Attack",
        { attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
        reservedDestinations,
        reservedExpectedDamage
      )
    );

  const canUseMoveAttackSequence = !isMoveAttackExclusiveUnit(unit.type) && !unit.hasMovedThisDay && !shouldEnemyForbidRelocatingForAttack(state, unit);
  const moveThenAttacks = canUseMoveAttackSequence
    ? getEnemyLegalMoveCoords(state, unit)
        .filter((coord) => canMoveUnitTo(state, unit, coord))
        .flatMap((moveTo) => {
          const movedUnit: UnitInstance = {
            ...unit,
            coord: { ...moveTo },
            movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, moveTo)
          };
          return getEnemyPlannerAttackOptions(state, movedUnit, plan, reservedExpectedDamage)
            .filter((attack) => isPlayerBaseAreaAssaultTarget(state, attack.target))
            .map((attack) =>
              createEnemyCompoundAction(
                state,
                unit,
                plan,
                "MoveThenAttack",
                { moveTo, attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
                reservedDestinations,
                reservedExpectedDamage
              )
            );
        })
    : [];

  return getPlausibleEnemyCompoundActions(state, unit, plan, [...directAttacks, ...moveThenAttacks])
    .sort((first, second) => compareEnemyCompoundActionsForPlanning(state, unit, plan, first, second))
    .slice(0, ENEMY_PLANNER_ACTION_CAP);
}

function chooseEnemyHighAltitudePrioritySuppressionAction(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>,
  antiAirThreatMap: EnemyAntiAirThreatMap
): EnemyCompoundAction | undefined {
  if (unit.type !== "Bomber" || unit.hasAttackedThisDay || unit.placedDay === state.day) {
    return undefined;
  }

  const directAntiAir = getEnemyPlannerAttackOptions(state, unit, plan, reservedExpectedDamage).find((attack) => attack.target.type === "Anti-Air");
  if (directAntiAir) {
    return createEnemyCompoundAction(
      state,
      unit,
      plan,
      "Attack",
      { attackAt: directAntiAir.target.coord, targetId: directAntiAir.target.id, targetType: directAntiAir.target.type, expectedOutcome: directAntiAir.outcome },
      reservedDestinations,
      reservedExpectedDamage
    );
  }

  if (!unit.hasMovedThisDay) {
    const mobileThreat =
      getPlayerMobileAirThreatsCoveringCoord(state, unit, unit.coord, plan).length > 0 ||
      isEnemyAirCoordInVisibleMobileThreatReach(state, unit, unit.coord);
    const directAttack = getEnemyPlannerAttackOptions(state, unit, plan, reservedExpectedDamage).find((attack) => attack.target.type !== "Anti-Air");
    if (mobileThreat && directAttack) {
      const moveTo = getEnemyLegalMoveCoords(state, unit)
        .filter((coord) => canMoveUnitTo(state, unit, coord))
        .filter((coord) => !isEnemyAirCoordInVisibleMobileThreatReach(state, unit, coord))
        .sort((first, second) => hexDistance(second, unit.coord) - hexDistance(first, unit.coord) || hexId(first).localeCompare(hexId(second)))[0];
      if (moveTo) {
        return createEnemyCompoundAction(
          state,
          unit,
          plan,
          "AttackThenMove",
          { moveTo, attackAt: directAttack.target.coord, targetId: directAttack.target.id, targetType: directAttack.target.type, expectedOutcome: directAttack.outcome },
          reservedDestinations,
          reservedExpectedDamage
        );
      }
    }

    for (const moveTo of getEnemyLegalMoveCoords(state, unit)) {
      if (!canMoveUnitTo(state, unit, moveTo)) {
        continue;
      }
      const movedUnit: UnitInstance = {
        ...unit,
        coord: { ...moveTo },
        movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, moveTo)
      };
      const antiAirAttack = getEnemyPlannerAttackOptions(state, movedUnit, plan, reservedExpectedDamage).find((attack) => attack.target.type === "Anti-Air");
      if (
        antiAirAttack &&
        isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap, {
          targetId: antiAirAttack.target.id,
          expectedOutcome: antiAirAttack.outcome
        })
      ) {
        return createEnemyCompoundAction(
          state,
          unit,
          plan,
          "MoveThenAttack",
          { moveTo, attackAt: antiAirAttack.target.coord, targetId: antiAirAttack.target.id, targetType: antiAirAttack.target.type, expectedOutcome: antiAirAttack.outcome },
          reservedDestinations,
          reservedExpectedDamage
        );
      }
    }
  }

  return undefined;
}

function isEnemyAirCoordInVisibleMobileThreatReach(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"]
): boolean {
  if (getUnitDefinition(unit.type).domain !== "Air") {
    return false;
  }
  const visibleTargetIds = getVisiblePlayerUnitsForEnemy(state).map((target) => target.id);
  return getOwnerUnits(state, "Player")
    .filter((target) => visibleTargetIds.includes(target.id))
    .some((target) => {
      if (getUnitDefinition(target.type).domain !== "Air" || !canUnitTargetUnit(target.type, unit.type)) {
        return false;
      }
      const stats = getEffectiveUnitStats(state, target.owner, target.type, target.level, target.coord, coord);
      const reach = stats.attackRange + (getUnitDefinition(target.type).cannotMoveAndAttack ? 0 : stats.moveRange);
      return hexDistance(target.coord, coord) <= reach;
    });
}

function enumerateEnemyImmediateTacticalAttackActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>,
  antiAirThreatMap: EnemyAntiAirThreatMap
): EnemyCompoundAction[] {
  if (unit.hasAttackedThisDay || unit.placedDay === state.day) {
    return [];
  }

  const directAttacks = getEnemyPlannerAttackOptions(state, unit, plan, reservedExpectedDamage)
    .map((attack) =>
      createEnemyCompoundAction(
        state,
        unit,
        plan,
        "Attack",
        { attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
        reservedDestinations,
        reservedExpectedDamage
      )
    );

  const mustHoldCurrentTile = shouldEnemyForbidRelocatingForAttack(state, unit);
  const moveThenAttacks = isMoveAttackExclusiveUnit(unit.type) || unit.hasMovedThisDay || mustHoldCurrentTile
    ? []
    : enumerateEnemyImmediateMoveThenAttackActions(state, unit, plan, reservedDestinations, reservedExpectedDamage, antiAirThreatMap);
  const attackThenMoves = isMoveAttackExclusiveUnit(unit.type) || unit.hasMovedThisDay || mustHoldCurrentTile
    ? []
    : enumerateEnemyImmediateAttackThenMoveActions(state, unit, plan, reservedDestinations, reservedExpectedDamage, antiAirThreatMap);
  const moveAttackRetreats = isMoveAttackExclusiveUnit(unit.type) || unit.hasMovedThisDay || mustHoldCurrentTile || shouldEnemyAttemptRepairRetreat(state, unit)
    ? []
    : enumerateEnemyImmediateMoveAttackRetreatActions(state, unit, plan, reservedDestinations, reservedExpectedDamage, antiAirThreatMap);

  const plausibleDirectAttacks = getPlausibleEnemyCompoundActions(state, unit, plan, directAttacks)
    .filter((action) => shouldEnemyPreferImmediateTacticalAttack(state, unit, action, plan))
    .sort((first, second) => compareEnemyCompoundActionsForPlanning(state, unit, plan, first, second))
    .slice(0, ENEMY_PLANNER_ACTION_CAP);
  const tacticalActions = getPlausibleEnemyCompoundActions(state, unit, plan, [...plausibleDirectAttacks, ...attackThenMoves, ...moveThenAttacks, ...moveAttackRetreats])
    .filter((action) => shouldEnemyPreferImmediateTacticalAttack(state, unit, action, plan))
    .sort((first, second) => compareEnemyCompoundActionsForPlanning(state, unit, plan, first, second));
  const selectedActions = tacticalActions.slice(0, ENEMY_PLANNER_ACTION_CAP);
  for (const kind of ["MoveAttackRetreat", "MoveThenAttack", "AttackThenMove", "Attack"] as EnemyCompoundActionKind[]) {
    if (selectedActions.some((action) => action.kind === kind)) {
      continue;
    }
    const candidate = tacticalActions.find((action) => action.kind === kind);
    if (!candidate) {
      continue;
    }
    const replaceIndex = selectedActions
      .map((action, index) => ({ action, index }))
      .reverse()
      .find(({ action }) => selectedActions.filter((existing) => existing.kind === action.kind).length > 1)?.index ?? selectedActions.length - 1;
    if (replaceIndex >= 0) {
      selectedActions[replaceIndex] = candidate;
    } else if (selectedActions.length < ENEMY_PLANNER_ACTION_CAP) {
      selectedActions.push(candidate);
    }
  }
  return selectedActions;
}

function enumerateEnemyImmediateAttackThenMoveActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>,
  antiAirThreatMap: EnemyAntiAirThreatMap
): EnemyCompoundAction[] {
  const moveCoords = getEnemyImmediatePostAttackMoveCoords(state, unit, plan, reservedDestinations);
  return getEnemyPlannerAttackOptions(state, unit, plan, reservedExpectedDamage)
    .flatMap((attack) =>
      moveCoords
        .filter((moveTo) => isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap, {
          targetId: attack.target.id,
          expectedOutcome: attack.outcome
        }))
        .map((moveTo) =>
          createEnemyCompoundAction(
            state,
            unit,
            plan,
            "AttackThenMove",
            { moveTo, attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
            reservedDestinations,
            reservedExpectedDamage
          )
        )
    )
    .sort((first, second) => compareEnemyCompoundActionsForPlanning(state, unit, plan, first, second))
    .slice(0, getEnemyDynamicMoveSearchCap(state, plan));
}

function getEnemyImmediatePostAttackMoveCoords(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>
): UnitInstance["coord"][] {
  const target = chooseEnemyPlannerOperationalTarget(state, unit, plan);
  const path = findMovementPath(state, unit, target) ?? [];
  const remainingMovement = getRemainingMovementPoints(state, unit);
  const pathStep = path.length && remainingMovement > 0
    ? path[Math.min(path.length, remainingMovement) - 1]
    : undefined;
  const committedMoveCoords = uniqueCoords([
    pathStep,
    chooseEnemyPlannerCommittedBaseAssaultMove(state, unit, plan),
    chooseEnemyPlannerBaseHoldProtectionMove(state, unit, plan),
    chooseEnemyPlannerEndgamePushMove(state, unit, plan),
    chooseEnemyPlannerMidgameCenterControlMove(state, unit, plan),
    chooseEnemyPlannerOpeningGateCapturerMove(state, unit, plan, reservedDestinations),
    chooseEnemyPlannerOpeningGateEscortMove(state, unit, plan, reservedDestinations),
    chooseEnemyPlannerSupplyTruckSupportMove(state, unit, plan),
    chooseEnemyPlannerFireSupportMove(state, unit, plan),
    chooseEnemyPlannerOpeningPatrolMove(state, unit, plan, reservedDestinations)
  ].filter((coord): coord is UnitInstance["coord"] => Boolean(coord)));
  return uniqueCoords([...committedMoveCoords, ...getEnemyPlannerCandidateMoveCoords(state, unit, plan, reservedDestinations)])
    .filter((coord) => !sameHex(coord, unit.coord))
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => {
      const key = getEnemyDestinationReservationKey(unit.type, coord);
      return !reservedDestinations[key] || reservedDestinations[key] === unit.id;
    })
    .slice(0, getEnemyPlannerMoveCandidateCap(state, unit, plan) + committedMoveCoords.length);
}

function enumerateEnemyImmediateMoveThenAttackActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>,
  antiAirThreatMap: EnemyAntiAirThreatMap
): EnemyCompoundAction[] {
  const reservedForOther = (coord: UnitInstance["coord"]): boolean => {
    const key = getEnemyDestinationReservationKey(unit.type, coord);
    return Boolean(reservedDestinations[key] && reservedDestinations[key] !== unit.id);
  };

  return [...getEnemyLegalMoveCoords(state, unit)]
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => !reservedForOther(coord))
    .map((moveTo) => {
      const movedUnit: UnitInstance = {
        ...unit,
        coord: { ...moveTo },
        movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, moveTo)
      };
      const attacks = getEnemyPlannerAttackOptions(state, movedUnit, plan, reservedExpectedDamage)
        .filter((attack) =>
          isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap, {
            targetId: attack.target.id,
            expectedOutcome: attack.outcome
          })
        );
      return attacks.map((attack) =>
        createEnemyCompoundAction(
          state,
          unit,
          plan,
          "MoveThenAttack",
          { moveTo, attackAt: attack.target.coord, targetId: attack.target.id, targetType: attack.target.type, expectedOutcome: attack.outcome },
          reservedDestinations,
          reservedExpectedDamage
        )
      );
    })
    .flat()
    .sort((first, second) => compareEnemyCompoundActionsForPlanning(state, unit, plan, first, second))
    .slice(0, getEnemyDynamicMoveSearchCap(state, plan));
}

function enumerateEnemyImmediateMoveAttackRetreatActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>,
  antiAirThreatMap: EnemyAntiAirThreatMap
): EnemyCompoundAction[] {
  const actions: EnemyCompoundAction[] = [];
  const reservedForOther = (coord: UnitInstance["coord"]): boolean => {
    const key = getEnemyDestinationReservationKey(unit.type, coord);
    return Boolean(reservedDestinations[key] && reservedDestinations[key] !== unit.id);
  };

  for (const moveTo of getEnemyLegalMoveCoords(state, unit)) {
    if (!canMoveUnitTo(state, unit, moveTo) || reservedForOther(moveTo)) {
      continue;
    }

    const movedUnit: UnitInstance = {
      ...unit,
      coord: { ...moveTo },
      movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, moveTo)
    };
    const attacks = getEnemyPlannerAttackOptions(state, movedUnit, plan, reservedExpectedDamage)
      .filter((attack) =>
        isEnemyAirMoveCandidateAllowed(state, unit, moveTo, plan, antiAirThreatMap, {
          targetId: attack.target.id,
          expectedOutcome: attack.outcome,
          moveAttackRetreatAttackTile: true
        })
      );

    for (const attack of attacks) {
      for (const retreatTo of getEnemyMoveAttackRetreatCoords(state, unit, movedUnit, attack, plan, reservedDestinations, antiAirThreatMap).slice(0, 2)) {
        actions.push(createEnemyCompoundAction(
          state,
          unit,
          plan,
          "MoveAttackRetreat",
          {
            moveTo,
            retreatTo,
            attackAt: attack.target.coord,
            targetId: attack.target.id,
            targetType: attack.target.type,
            expectedOutcome: attack.outcome
          },
          reservedDestinations,
          reservedExpectedDamage
        ));
      }
    }
  }

  return actions
    .sort((first, second) => compareEnemyCompoundActionsForPlanning(state, unit, plan, first, second))
    .slice(0, getEnemyDynamicMoveSearchCap(state, plan));
}

function getEnemyMoveAttackRetreatCoords(
  state: GameState,
  unit: UnitInstance,
  movedUnit: UnitInstance,
  attack: EnemyPlannerAttackOption,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  antiAirThreatMap: EnemyAntiAirThreatMap
): UnitInstance["coord"][] {
  const attackContext = {
    unitId: unit.id,
    unitType: unit.type,
    targetId: attack.target.id,
    expectedOutcome: attack.outcome
  };
  return getEnemyLegalMoveCoords(state, movedUnit)
    .filter((coord) => canMoveUnitTo(state, movedUnit, coord))
    .filter((coord) => !sameHex(coord, movedUnit.coord))
    .filter((coord) => {
      const key = getEnemyDestinationReservationKey(unit.type, coord);
      return !reservedDestinations[key] || reservedDestinations[key] === unit.id;
    })
    .filter((coord) => isEnemyAirMoveAllowedByThreatMap(state, unit, coord, attackContext, plan, antiAirThreatMap))
    .filter((coord) => isEnemySafeMoveAttackRetreatTile(state, unit, movedUnit.coord, coord, attackContext, plan))
    .sort((first, second) => {
      const firstExchange = getEnemyMoveAttackRetreatExchange(state, unit, movedUnit.coord, first, attackContext, plan);
      const secondExchange = getEnemyMoveAttackRetreatExchange(state, unit, movedUnit.coord, second, attackContext, plan);
      const firstReply = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, first, plan, attackContext);
      const secondReply = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, second, plan, attackContext);
      return (
        Number(secondExchange.allRepliesBelowExpectedDamage) - Number(firstExchange.allRepliesBelowExpectedDamage) ||
        firstReply - secondReply ||
        hexDistance(first, state.bases.Enemy) - hexDistance(second, state.bases.Enemy) ||
        hexId(first).localeCompare(hexId(second))
      );
    });
}

function isEnemySafeMoveAttackRetreatTile(
  state: GameState,
  unit: UnitInstance,
  attackCoord: UnitInstance["coord"],
  retreatCoord: UnitInstance["coord"],
  attackContext: { targetId?: string; expectedOutcome?: ExpectedAttackOutcome },
  plan: EnemyTurnPlan
): boolean {
  const health = Math.max(1, unit.health);
  const improvementMargin = Math.max(6, health * 0.14);
  const exchange = getEnemyMoveAttackRetreatExchange(state, unit, attackCoord, retreatCoord, attackContext, plan);
  const favorableTrade = exchange.retreatReplyDamage < exchange.usefulDamage;
  if (favorableTrade) {
    return (
      !isEnemyPlannerOneShotExposed(state, unit, retreatCoord, plan) ||
      isEnemyPlannerOneShotExposed(state, unit, unit.coord, plan) ||
      exchange.retreatReplyDamage < health
    );
  }
  if (exchange.retreatReplyDamage > exchange.attackReplyDamage - improvementMargin) {
    return false;
  }
  if (exchange.retreatReplyDamage >= health * 0.75) {
    return false;
  }
  if (isEnemyPlannerOneShotExposed(state, unit, retreatCoord, plan) && !isEnemyPlannerOneShotExposed(state, unit, unit.coord, plan)) {
    return false;
  }
  return exchange.retreatReplyDamage <= exchange.currentReplyDamage + improvementMargin || exchange.retreatReplyDamage <= health * 0.38;
}

function getEnemyMoveAttackRetreatExchange(
  state: GameState,
  unit: UnitInstance,
  attackCoord: UnitInstance["coord"],
  retreatCoord: UnitInstance["coord"],
  attackContext: { targetId?: string; expectedOutcome?: ExpectedAttackOutcome },
  plan: EnemyTurnPlan
): {
  expectedDamage: number;
  usefulDamage: number;
  currentReplyDamage: number;
  attackReplyDamage: number;
  retreatReplyDamage: number;
  worstReplyDamage: number;
  allRepliesBelowExpectedDamage: boolean;
} {
  const expectedDamage = attackContext.expectedOutcome?.expectedDamage ?? 0;
  const usefulDamage = getUsefulExpectedDamage(attackContext.targetId ? getUnitById(state, attackContext.targetId) : undefined, expectedDamage);
  const currentReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, unit.coord, plan, attackContext);
  const attackReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, attackCoord, plan, attackContext);
  const retreatReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, retreatCoord, plan, attackContext);
  const worstReplyDamage = Math.max(currentReplyDamage, attackReplyDamage, retreatReplyDamage);
  return {
    expectedDamage,
    usefulDamage,
    currentReplyDamage,
    attackReplyDamage,
    retreatReplyDamage,
    worstReplyDamage,
    allRepliesBelowExpectedDamage: usefulDamage > 0 && worstReplyDamage < usefulDamage
  };
}

function getEnemyAttackExchangeReplyCoords(
  unit: UnitInstance,
  action: EnemyCompoundAction
): UnitInstance["coord"][] {
  if (!action.targetId || !action.expectedOutcome) {
    return [];
  }

  if (action.kind === "Attack") {
    return [unit.coord];
  }

  if (action.kind === "AttackThenMove") {
    return uniqueCoords([unit.coord, action.moveTo].filter((coord): coord is UnitInstance["coord"] => Boolean(coord)));
  }

  if (action.kind === "MoveThenAttack") {
    return uniqueCoords([unit.coord, action.moveTo].filter((coord): coord is UnitInstance["coord"] => Boolean(coord)));
  }

  if (action.kind === "MoveAttackRetreat") {
    return uniqueCoords([unit.coord, action.moveTo, action.retreatTo].filter((coord): coord is UnitInstance["coord"] => Boolean(coord)));
  }

  return [];
}

function getEnemyAttackExchange(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan
): {
  expectedDamage: number;
  usefulDamage: number;
  replyDamages: number[];
  worstReplyDamage: number;
  allRepliesBelowExpectedDamage: boolean;
} {
  const expectedDamage = action.expectedOutcome?.expectedDamage ?? 0;
  const usefulDamage = getUsefulExpectedDamage(action.targetId ? getUnitById(state, action.targetId) : undefined, expectedDamage);
  const attackContext = { targetId: action.targetId, expectedOutcome: action.expectedOutcome };
  const replyDamages = getEnemyAttackExchangeReplyCoords(unit, action).map((coord) =>
    estimatePlayerLikelyReplyDamageAtPlanner(state, unit, coord, plan, attackContext)
  );
  const worstReplyDamage = replyDamages.length ? Math.max(...replyDamages) : Number.POSITIVE_INFINITY;
  return {
    expectedDamage,
    usefulDamage,
    replyDamages,
    worstReplyDamage,
    allRepliesBelowExpectedDamage: usefulDamage > 0 && replyDamages.length > 0 && worstReplyDamage < usefulDamage
  };
}

function scoreEnemyFavorableAttackExchange(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan
): number {
  if (!action.targetId || !action.expectedOutcome) {
    return 0;
  }

  const exchange = getEnemyAttackExchange(state, unit, action, plan);
  if (!exchange.allRepliesBelowExpectedDamage) {
    return scoreEnemyAcceptableAggressiveAttackExchange(state, unit, action, plan, exchange);
  }

  const usefulDamage = exchange.usefulDamage;
  const damageMargin = usefulDamage - exchange.worstReplyDamage;
  const sequenceBonus =
    action.kind === "MoveAttackRetreat" ? 280 :
    action.kind === "MoveThenAttack" ? 240 :
    action.kind === "AttackThenMove" ? 220 :
    190;
  return sequenceBonus + usefulDamage * 18 + damageMargin * 24 + action.expectedOutcome.killProbability * 180;
}

function scoreEnemyAcceptableAggressiveAttackExchange(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan,
  exchange: {
    expectedDamage: number;
    usefulDamage: number;
    replyDamages: number[];
    worstReplyDamage: number;
    allRepliesBelowExpectedDamage: boolean;
  }
): number {
  if (!isEnemyRiskBudgetCombatUnit(unit) || !action.expectedOutcome) {
    return 0;
  }

  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  if (isEnemyPlannerOneShotExposed(state, unit, finalCoord, plan)) {
    return 0;
  }

  const health = Math.max(1, unit.health);
  if (exchange.worstReplyDamage >= health * getEnemyCatastrophicExposureRatio(state, unit, action, plan)) {
    return 0;
  }

  const budget = getEnemyTacticalReplyDamageBudget(state, unit, action, finalCoord, plan);
  if (exchange.worstReplyDamage > budget) {
    return 0;
  }

  const payoff = getEnemyActionAttackPayoff(state, action, plan);
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  const ownValue = getUnitInstanceValue(state, unit);
  const materialSwing = target ? targetValueTradeScore(state, target, action.expectedOutcome.killProbability, payoff.usefulDamage) : 0;
  if (target && target.health <= Math.max(2, exchange.worstReplyDamage * 0.18) && exchange.worstReplyDamage > payoff.usefulDamage * 5 && !payoff.objectiveTarget) {
    return 0;
  }
  const budgetMargin = budget - exchange.worstReplyDamage;
  const objectiveTempo = payoff.objectiveTarget ? 260 : 0;
  const highValueKill = payoff.killProbability >= 0.45 && payoff.targetValue >= ownValue * 0.85 ? 120 : 0;
  const usefulTrade = payoff.usefulDamage >= Math.max(3, exchange.worstReplyDamage * 0.42) || payoff.killProbability >= 0.58 || payoff.objectiveTarget;
  if (!usefulTrade || materialSwing + objectiveTempo + highValueKill < 120) {
    return 0;
  }

  const sequenceBonus =
    action.kind === "MoveAttackRetreat" ? 230 :
    action.kind === "MoveThenAttack" ? 210 :
    action.kind === "AttackThenMove" ? 170 :
    135;
  return sequenceBonus + materialSwing + objectiveTempo + highValueKill + Math.max(0, budgetMargin) * 12;
}

function targetValueTradeScore(state: GameState, target: UnitInstance, killProbability: number, usefulDamage: number): number {
  const targetValue = getUnitInstanceValue(state, target);
  const damageShare = Math.min(1, usefulDamage / Math.max(1, target.health));
  return targetValue * (killProbability * 1.25 + damageShare * 0.32) + usefulDamage * 12;
}

function shouldEnemyPreferImmediateTacticalAttack(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  if (!action.targetId || !action.expectedOutcome) {
    return false;
  }

  const target = getUnitById(state, action.targetId);
  if (!target || target.owner !== "Player") {
    return false;
  }

  if (action.kind === "Attack") {
    return true;
  }

  return Boolean(action.moveTo);
}

function shouldForceGateLockoutBreakout(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  return (
    state.difficulty === "Hard" &&
    (plan.campaignPlan.phase === "Recovery" || plan.campaignPlan.phase === "GateLockoutCombat") &&
    getUnitDefinition(unit.type).humanBased &&
    unit.health / Math.max(1, unit.maxHealth) > 0.35 &&
    getOwnerUnits(state, "Enemy").filter((ally) => getUnitDefinition(ally.type).humanBased).length > 0
  );
}

function chooseEnemyPlannerCommittedBaseAssaultMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const mission = plan.rolesByUnitId[unit.id];
  const baseThreat = getEnemyBaseThreat(state);
  const alreadyForced = plan.objectiveImperatives.some((imperative) => imperative.unitId === unit.id && imperative.terminal < 0);
  const assaultEligible =
    (mission === "CaptureBase" ||
      (hexDistance(unit.coord, state.bases.Player) < hexDistance(unit.coord, state.bases.Enemy) && unit.health / Math.max(1, unit.maxHealth) > 0.45)) &&
    !alreadyForced &&
    !isActiveEnemyBaseThreat(state, baseThreat);
  if (!assaultEligible || !getUnitDefinition(unit.type).humanBased || (!ownerControlsBothGates(state, "Enemy") && !isPlayerBaseExposedForHardAttack(state))) {
    return undefined;
  }
  if (sameHex(unit.coord, state.bases.Player) || state.baseOccupation.Enemy >= BASE_CAPTURE_DAYS - 1) {
    return undefined;
  }
  const currentDistance = hexDistance(unit.coord, state.bases.Player);
  const path = findMovementPath(state, unit, state.bases.Player);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (!path?.length || remainingMovement <= 0) {
    return getEnemyLegalMoveCoords(state, unit)
      .filter((coord) => hexDistance(coord, state.bases.Player) < currentDistance)
      .sort((first, second) => hexDistance(first, state.bases.Player) - hexDistance(second, state.bases.Player) || hexId(first).localeCompare(hexId(second)))[0];
  }
  for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
    const coord = path[steps - 1];
    if (canMoveUnitTo(state, unit, coord) && hexDistance(coord, state.bases.Player) < currentDistance) {
      return coord;
    }
  }
  return undefined;
}

function chooseEnemyPlannerForcedBaseAssaultMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (plan.rolesByUnitId[unit.id] !== "CaptureBase" || !getUnitDefinition(unit.type).humanBased || (!ownerControlsBothGates(state, "Enemy") && !isPlayerBaseExposedForHardAttack(state))) {
    return undefined;
  }
  return chooseEnemyPlannerCommittedBaseAssaultMove(state, unit, plan);
}

function chooseEnemyPlannerEndgamePushMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (
    !isHardEndgameDoctrineActive(state, plan) ||
    !isEnemyEndgamePushUnit(unit) ||
    unit.placedDay === state.day ||
    shouldEnemyAttemptRepairRetreat(state, unit)
  ) {
    return undefined;
  }

  const target = chooseEnemyEndgamePushTarget(state, unit, plan);
  if (!target) {
    return undefined;
  }
  const currentDistance = hexDistance(unit.coord, target);
  if (currentDistance <= 1 && isCoordInPlayerBaseAssaultArea(state, unit.coord) && canEnemyUnitAttackVisiblePlayerBaseAreaTarget(state, unit, plan)) {
    return undefined;
  }

  const safeProgress = (coord: UnitInstance["coord"]): boolean => {
    if (!canMoveUnitTo(state, unit, coord)) {
      return false;
    }
    if (plan.rolesByUnitId[unit.id] === "Siege" && isEnemyBaseAttackCombatUnit(unit) && !isEnemyBaseAssaultCombatMovementAllowed(state, unit, coord, plan)) {
      return false;
    }
    const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
    return danger < unit.health && !isEnemyPlannerOneShotExposed(state, unit, coord, plan);
  };
  const remainingMovement = getRemainingMovementPoints(state, unit);
  const path = findMovementPath(state, unit, target);
  if (remainingMovement <= 0) {
    return undefined;
  }
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (safeProgress(coord) && scoreEnemyEndgamePushCoord(state, unit, coord, target, plan) > scoreEnemyEndgamePushCoord(state, unit, unit.coord, target, plan) + 15) {
        return coord;
      }
    }
  }

  const currentScore = scoreEnemyEndgamePushCoord(state, unit, unit.coord, target, plan);
  return getEnemyLegalMoveCoords(state, unit)
    .filter(safeProgress)
    .map((coord) => ({
      coord,
      score: scoreEnemyEndgamePushCoord(state, unit, coord, target, plan)
    }))
    .filter((entry) => entry.score > currentScore + 15)
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function chooseEnemyPlannerForcedBaseAttackMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (
    !isHardEndgameDoctrineActive(state, plan) ||
    !isEnemyBaseAttackCombatUnit(unit) ||
    plan.rolesByUnitId[unit.id] !== "Siege" ||
    unit.placedDay === state.day
  ) {
    return undefined;
  }

  if (isEnemyBaseAssaultFireCoveragePosition(state, unit, unit.coord, plan)) {
    return undefined;
  }

  const target = chooseEnemyBaseAssaultPenetrationTarget(state, unit, plan);
  if (!target) {
    return undefined;
  }

  const currentScore = scoreEnemyBaseAssaultPenetrationCoord(state, unit, unit.coord, target, plan);
  const currentBaseDistance = hexDistance(unit.coord, state.bases.Player);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  const legalProgressEntries = (): Array<{ coord: UnitInstance["coord"]; score: number }> =>
    getEnemyLegalMoveCoords(state, unit)
      .filter((coord) => !sameHex(coord, state.bases.Player))
      .filter((coord) => canMoveUnitTo(state, unit, coord))
      .filter((coord) => isEnemyBaseAssaultCombatMovementAllowed(state, unit, coord, plan))
      .map((coord) => ({
        coord,
        score: scoreEnemyBaseAssaultPenetrationCoord(state, unit, coord, target, plan)
      }));

  const directProgress = legalProgressEntries()
    .filter((entry) => hexDistance(entry.coord, state.bases.Player) < currentBaseDistance)
    .sort((first, second) => second.score - first.score || second.coord.r - first.coord.r || hexDistance(first.coord, target) - hexDistance(second.coord, target) || hexId(first.coord).localeCompare(hexId(second.coord)));
  if (!isCoordInPlayerBaseAssaultArea(state, unit.coord)) {
    const playerAreaEntry = directProgress.find((entry) => isCoordInPlayerBaseAssaultArea(state, entry.coord));
    if (playerAreaEntry) {
      return playerAreaEntry.coord;
    }
  } else if (directProgress.length > 0) {
    return directProgress[0].coord;
  }

  const path = findMovementPath(state, unit, target);
  if (path?.length && remainingMovement > 0) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (
        !sameHex(coord, state.bases.Player) &&
        canMoveUnitTo(state, unit, coord) &&
        isEnemyBaseAssaultCombatMovementAllowed(state, unit, coord, plan) &&
        scoreEnemyBaseAssaultPenetrationCoord(state, unit, coord, target, plan) > currentScore + 20
      ) {
        return coord;
      }
    }
  }

  return legalProgressEntries()
    .filter((entry) => entry.score > currentScore + 20)
    .sort((first, second) => second.score - first.score || second.coord.r - first.coord.r || hexDistance(first.coord, target) - hexDistance(second.coord, target) || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function chooseEnemyEndgamePushTarget(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (!isHardEndgameDoctrineActive(state, plan) || !isEnemyEndgamePushUnit(unit)) {
    return undefined;
  }

  if (plan.rolesByUnitId[unit.id] === "Siege") {
    return chooseEnemyBaseAssaultPenetrationTarget(state, unit, plan);
  }

  const targetablePlayer = plan.playerIntel
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .filter((intel) => intel.age <= 4)
    .sort((first, second) => scoreEnemyEndgamePlayerTarget(state, unit, second) - scoreEnemyEndgamePlayerTarget(state, unit, first))[0];
  if (targetablePlayer) {
    return targetablePlayer.predictedCoord;
  }

  return chooseEnemyBaseAssaultPenetrationTarget(state, unit, plan);
}

function chooseEnemyBaseAssaultPenetrationTarget(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const visibleBaseAreaTarget = plan.playerIntel
    .filter((intel) => intel.age <= 2)
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .filter((intel) => isPlayerBaseAreaAssaultTarget(state, { ...intel.unit, coord: intel.predictedCoord }))
    .sort((first, second) => scoreEnemyPlayerBaseAreaTargetPriority(state, unit, { ...second.unit, coord: second.predictedCoord }, plan) - scoreEnemyPlayerBaseAreaTargetPriority(state, unit, { ...first.unit, coord: first.predictedCoord }, plan))[0];
  if (visibleBaseAreaTarget) {
    return visibleBaseAreaTarget.predictedCoord;
  }

  const searchRadius = Math.max(7, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, state.bases.Player).moveRange + 4);
  const candidates = getPassableCoordsNear(state, state.bases.Player, searchRadius)
    .filter((coord) => !sameHex(coord, state.bases.Player))
    .filter((coord) => canUnitEndMovementAt(state, unit, coord) || sameHex(coord, unit.coord));
  return candidates
    .map((coord) => ({
      coord,
      score: scoreEnemyBaseAssaultPenetrationCoord(state, unit, coord, coord, plan)
    }))
    .sort((first, second) => second.score - first.score || second.coord.r - first.coord.r || hexDistance(first.coord, state.bases.Player) - hexDistance(second.coord, state.bases.Player) || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function scoreEnemyBaseAssaultPenetrationCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  target: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, state.bases.Player);
  const assaultMinRow = getPlayerBaseAssaultAreaMinRow(state);
  const rowPressure = Math.max(0, coord.r) * 54;
  const playerArea = isCoordInPlayerBaseAssaultArea(state, coord) ? 900 : -(assaultMinRow - coord.r) * 120;
  const baseDistance = hexDistance(coord, state.bases.Player);
  const targetDistance = hexDistance(coord, target);
  const attackBand =
    baseDistance <= stats.attackRange
      ? 320 + Math.max(0, stats.attackRange - baseDistance) * 24
      : -baseDistance * 22;
  const targetBand = targetDistance <= stats.attackRange ? 220 : -targetDistance * 18;
  const fireCoverage = scoreEnemyBaseAssaultFireCoverage(state, unit, coord, plan);
  const congestionPenalty = getOwnerUnits(state, "Enemy")
    .filter((ally) => ally.id !== unit.id && hexDistance(ally.coord, coord) <= 1)
    .length * 36;
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  return rowPressure + playerArea + attackBand + targetBand + fireCoverage - congestionPenalty - danger * 0.16;
}

function isEnemyBaseAssaultFireCoveragePosition(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): boolean {
  return isCoordInPlayerBaseAssaultArea(state, coord) && scoreEnemyBaseAssaultFireCoverage(state, unit, coord, plan) >= 520;
}

function scoreEnemyBaseAssaultFireCoverage(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  if (!isEnemyBaseAttackCombatUnit(unit)) {
    return 0;
  }

  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, state.bases.Player);
  const coverageCoords = getEnemyPlayerBaseFireCoverageCoords(state);
  const coveredBackline = coverageCoords
    .filter((coverageCoord) => hexDistance(coord, coverageCoord) <= stats.attackRange)
    .length;
  const visibleCoverage = plan.playerIntel.reduce((score, intel) => {
    if (!canUnitTargetUnit(unit.type, intel.unit.type) || !isPlayerBaseAreaAssaultTarget(state, { ...intel.unit, coord: intel.predictedCoord })) {
      return score;
    }
    return score + (hexDistance(coord, intel.predictedCoord) <= stats.attackRange ? scoreEnemyPlayerBaseAreaTargetPriority(state, unit, { ...intel.unit, coord: intel.predictedCoord }, plan) * 0.38 * intel.confidence : 0);
  }, 0);
  const laneQ = getEnemyBaseAssaultFireLaneQ(state, unit);
  const laneScore = Math.max(0, 8 - Math.abs(coord.q - laneQ)) * 34;
  const idealDistance =
    unit.type === "Artillery" || unit.type === "Anti-Air"
      ? Math.max(2, stats.attackRange - 1)
      : unit.type === "Attack Heli"
        ? Math.max(2, stats.attackRange)
        : Math.max(1, Math.min(stats.attackRange, 3));
  const standoffScore = Math.max(0, 5 - Math.abs(hexDistance(coord, state.bases.Player) - idealDistance)) * 46;
  return coveredBackline * 175 + visibleCoverage + laneScore + standoffScore;
}

function getEnemyPlayerBaseFireCoverageCoords(state: GameState): UnitInstance["coord"][] {
  return getEnemyPlayerBaseBackLineCoords(state);
}

function getEnemyBaseAssaultFireLaneQ(state: GameState, unit: UnitInstance): number {
  const offsets = [-4, -2, 0, 2, 4, -6, 6, -1, 1, -3, 3, -5, 5];
  const offset = offsets[getStableUnitNumber(unit) % offsets.length] ?? 0;
  return Math.max(0, Math.min(state.map.width - 1, state.bases.Player.q + offset));
}

function chooseEnemyBaseAttackFiringPosition(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (!isEnemyBaseAttackCombatUnit(unit)) {
    return undefined;
  }

  const searchRadius = Math.max(6, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, state.bases.Player).attackRange + 4);
  const candidates = getPassableCoordsNear(state, state.bases.Player, searchRadius)
    .filter((coord) => !sameHex(coord, state.bases.Player))
    .filter((coord) => canUnitEndMovementAt(state, unit, coord) || sameHex(coord, unit.coord));
  return candidates
    .map((coord) => ({
      coord,
      score: scoreEnemyBaseAttackFiringPosition(state, unit, coord, plan)
    }))
    .filter((entry) => entry.score > 0)
    .sort((first, second) => second.score - first.score || hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord) || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function isEnemyBaseAttackFiringPosition(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): boolean {
  return scoreEnemyBaseAttackFiringPosition(state, unit, coord, plan) >= 720;
}

function scoreEnemyBaseAttackFiringPosition(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  if (!isEnemyBaseAttackCombatUnit(unit)) {
    return 0;
  }

  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, state.bases.Player);
  const baseDistance = hexDistance(coord, state.bases.Player);
  const baseCoverage = baseDistance <= stats.attackRange ? 760 + Math.max(0, stats.attackRange - baseDistance) * 18 : -baseDistance * 34;
  const backLineCoverage = getEnemyPlayerBaseBackLineCoords(state)
    .filter((backLineCoord) => hexDistance(coord, backLineCoord) <= stats.attackRange)
    .length * 95;
  const playerCoverage = plan.playerIntel.reduce((score, intel) => {
    if (!canUnitTargetUnit(unit.type, intel.unit.type) || !isPlayerBaseAreaAssaultTarget(state, { ...intel.unit, coord: intel.predictedCoord })) {
      return score;
    }
    return score + (hexDistance(coord, intel.predictedCoord) <= stats.attackRange ? scoreEnemyPlayerBaseAreaTargetPriority(state, unit, { ...intel.unit, coord: intel.predictedCoord }, plan) * 0.42 * intel.confidence : 0);
  }, 0);
  const assaultMinRow = getPlayerBaseAssaultAreaMinRow(state);
  const playerAreaCommitment = isCoordInPlayerBaseAssaultArea(state, coord) ? 520 : Math.max(0, coord.r - (assaultMinRow - 4)) * 90;
  const surroundOffset = Math.min(4, Math.abs(coord.q - state.bases.Player.q)) * 28;
  const tooClosePenalty = baseDistance === 0 ? 1200 : baseDistance === 1 && stats.attackRange > 1 ? 70 : 0;
  const congestionPenalty = getOwnerUnits(state, "Enemy")
    .filter((ally) => ally.id !== unit.id && hexDistance(ally.coord, coord) <= 1)
    .length * 42;
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  const routeDistance = hexDistance(unit.coord, coord);
  return baseCoverage + backLineCoverage + playerCoverage + playerAreaCommitment + surroundOffset - tooClosePenalty - congestionPenalty - danger * 0.18 - routeDistance * 5;
}

function canEnemyUnitAttackVisiblePlayerBaseAreaTarget(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  return getEnemyPlannerAttackTargets(state, unit, plan).some((attack) => isPlayerBaseAreaAssaultTarget(state, attack.target));
}

function getEnemyPlayerBaseBackLineCoords(state: GameState): UnitInstance["coord"][] {
  return getPassableCoordsNear(state, state.bases.Player, 3)
    .filter((coord) => coord.r >= state.bases.Player.r - 3);
}

function scoreEnemyEndgamePlayerTarget(state: GameState, unit: UnitInstance, intel: EnemyPlannerPlayerIntel): number {
  const empireBonus = isCoordInPlayerBaseAssaultArea(state, intel.predictedCoord) ? 260 : 0;
  const baseProximity = Math.max(0, 10 - hexDistance(intel.predictedCoord, state.bases.Player)) * 18;
  return (getUnitInstanceValue(state, intel.unit) * 1.1 + getCounterPriorityBonus(unit.type, { ...intel.unit, coord: intel.predictedCoord }) + empireBonus + baseProximity - hexDistance(unit.coord, intel.predictedCoord) * 5) * intel.confidence;
}

function scoreEnemyEndgamePushCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  target: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  const assaultMinRow = getPlayerBaseAssaultAreaMinRow(state);
  const empireBonus = isCoordInPlayerBaseAssaultArea(state, coord) ? 420 : coord.r >= assaultMinRow - 4 ? 120 : 0;
  const progress = Math.max(0, hexDistance(unit.coord, target) - hexDistance(coord, target)) * 85;
  const rowProgress = Math.max(-2, coord.r - unit.coord.r) * 140;
  const basePressure = Math.max(0, 14 - hexDistance(coord, state.bases.Player)) * 10;
  const playerCoverage = plan.playerIntel
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .reduce((score, intel) => {
      const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, intel.predictedCoord);
      return score + (hexDistance(coord, intel.predictedCoord) <= stats.attackRange + stats.moveRange ? getUnitInstanceValue(state, intel.unit) * 0.16 * intel.confidence : 0);
    }, 0);
  const adjacentAllies = getOwnerUnits(state, "Enemy")
    .filter((ally) => ally.id !== unit.id && hexDistance(ally.coord, coord) <= 1)
    .length;
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  return empireBonus + progress + rowProgress + basePressure + playerCoverage - adjacentAllies * 44 - danger * 0.55;
}

function isEnemyEndgamePushUnit(unit: UnitInstance): boolean {
  if (unit.health / Math.max(1, unit.maxHealth) <= 0.35 || getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  return unit.type === "Tank" || unit.type === "IFV" || unit.type === "Artillery" || unit.type === "Anti-Air" || unit.type === "Attack Heli" || unit.type === "Jet" || unit.type === "Bomber" || unit.type === "Reaper";
}

function chooseEnemyPlannerBaseHoldProtectionMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const capturer = getEnemyBaseHoldCapturer(state, plan);
  if (!capturer || unit.id === capturer.id || unit.placedDay === state.day) {
    return undefined;
  }

  const currentScore = scoreEnemyBaseHoldProtectionCoord(state, unit, unit.coord, capturer, plan);
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => !sameHex(coord, state.bases.Player))
    .map((coord) => ({
      coord,
      score: scoreEnemyBaseHoldProtectionCoord(state, unit, coord, capturer, plan)
    }))
    .filter((entry) => entry.score > currentScore + 35)
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function getEnemyBaseHoldCapturer(state: GameState, plan?: EnemyTurnPlan): UnitInstance | undefined {
  if (state.baseOccupation.Player <= 0) {
    return undefined;
  }

  const packaged = plan?.campaignPlan.baseAssaultPackage.capturerId
    ? getUnitById(state, plan.campaignPlan.baseAssaultPackage.capturerId)
    : undefined;
  if (packaged && packaged.owner === "Enemy" && getUnitDefinition(packaged.type).humanBased && sameHex(packaged.coord, state.bases.Player)) {
    return packaged;
  }

  return getOwnerUnits(state, "Enemy").find((unit) => getUnitDefinition(unit.type).humanBased && sameHex(unit.coord, state.bases.Player));
}

function getBaseHoldThreateningPlayerUnits(state: GameState, capturer: UnitInstance, plan: EnemyTurnPlan): UnitInstance[] {
  const threatIds = new Set(
    plan.playerIntel
      .filter((intel) => isPlayerUnitThreateningBaseHoldCapturerNextTurn(state, intel.unit, capturer, intel.predictedCoord))
      .map((intel) => intel.unit.id)
  );
  return getOwnerUnits(state, "Player")
    .filter((unit) => threatIds.has(unit.id) || isPlayerUnitThreateningBaseHoldCapturerNextTurn(state, unit, capturer, unit.coord));
}

function isPlayerUnitThreateningBaseHoldCapturerNextTurn(
  state: GameState,
  playerUnit: UnitInstance,
  capturer: UnitInstance,
  projectedCoord: UnitInstance["coord"]
): boolean {
  if (!canUnitTargetUnit(playerUnit.type, capturer.type)) {
    return false;
  }
  const stats = getEffectiveUnitStats(state, playerUnit.owner, playerUnit.type, playerUnit.level, projectedCoord, capturer.coord);
  const reach = stats.attackRange + (getUnitDefinition(playerUnit.type).cannotMoveAndAttack ? 0 : stats.moveRange);
  return hexDistance(projectedCoord, capturer.coord) <= reach;
}

function scoreEnemyBaseHoldProtectionCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  capturer: UnitInstance,
  plan: EnemyTurnPlan
): number {
  if (state.baseOccupation.Player <= 0 || sameHex(coord, state.bases.Player)) {
    return unit.id === capturer.id ? 0 : -500;
  }

  const role = plan.rolesByUnitId[unit.id];
  const packagePlan = plan.campaignPlan.baseAssaultPackage;
  const threats = getBaseHoldThreateningPlayerUnits(state, capturer, plan);
  const adjacentSupport = hexDistance(coord, capturer.coord) === 1 ? 420 : hexDistance(coord, capturer.coord) === 2 ? 210 : 0;
  const approachBlock = getEnemyBaseHoldApproachCorridorCoords(state, threats)
    .reduce((score, approach) => score + (sameHex(coord, approach) ? 460 : hexDistance(coord, approach) === 1 ? 140 : 0), 0);
  const backupDistance = getUnitDefinition(unit.type).humanBased
    ? Math.max(0, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, state.bases.Player).moveRange - hexDistance(coord, state.bases.Player) + 1) * 180
    : 0;
  const packageBonus =
    unit.id === packagePlan.backupCapturerId
      ? 380
      : packagePlan.blockerEscortIds.includes(unit.id)
        ? 260
        : packagePlan.damageDealerIds.includes(unit.id)
          ? 120
          : 0;
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  const threatProximity = threats.reduce((score, threat) => score + Math.max(0, 5 - hexDistance(coord, threat.coord)) * 22, 0);
  const roleBonus = role === "CaptureBase" || role === "ProtectCapturer" || role === "Escort" || role === "Siege" || role === "Scout" ? 120 : 0;
  return adjacentSupport + approachBlock + backupDistance + packageBonus + threatProximity + roleBonus - danger * 0.75;
}

function getEnemyBaseHoldApproachCorridorCoords(state: GameState, threats: UnitInstance[]): UnitInstance["coord"][] {
  const byId = new Map<string, UnitInstance["coord"]>();
  for (const threat of threats) {
    const path = findMovementPath(state, threat, state.bases.Player);
    const effectiveMoveToBase = Math.max(1, getEffectiveUnitStats(state, threat.owner, threat.type, threat.level, threat.coord, state.bases.Player).moveRange);
    for (const coord of (path ?? []).slice(0, effectiveMoveToBase)) {
      if (hexDistance(coord, state.bases.Player) <= 3) {
        byId.set(hexId(coord), coord);
      }
    }
  }
  for (const hex of state.map.hexes) {
    if (hex.passable && hexDistance(hex.coord, state.bases.Player) === 1) {
      byId.set(hex.id, hex.coord);
    }
  }
  return [...byId.values()];
}

function chooseEnemyPlannerForcedGateBreakoutMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const assessment = getEnemyStrategicAssessment(state);
  const gatePressureKnown =
    (state.day <= 16 || assessment.strategicPhase === "GateLockoutCombat") &&
    (state.gates ?? []).some((gate) => getKnownPlayerUnitsForEnemy(state).some((player) => hexDistance(player.coord, gate.coord) <= 4));
  if (
    !usesHardEnemyDoctrine(state) ||
    assessment.enemyGateCount > 0 ||
    (assessment.playerGateCount <= 0 && !gatePressureKnown) ||
    !getUnitDefinition(unit.type).humanBased
  ) {
    return undefined;
  }
  const target =
    assessment.strategicPhase === "GateLockoutCombat"
      ? [...(state.gates ?? [])]
          .filter((gate) => gate.owner !== "Enemy")
          .sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord) || getKnownGatePressure(state, first) - getKnownGatePressure(state, second))[0]
      : gatePressureKnown
      ? [...(state.gates ?? [])]
          .filter((gate) => gate.owner !== "Enemy")
          .sort((first, second) => getKnownGatePressure(state, first) - getKnownGatePressure(state, second) || hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord))[0]
      : chooseEnemyGateRoleTarget(state, "CaptureGate") ?? chooseGateObjective(state, "Enemy", unit.coord, unit, plan);
  if (!target) {
    return undefined;
  }
  const safeBreakoutProgress = (coord: UnitInstance["coord"]): boolean =>
    !sameHex(coord, target.coord) || isGateSafeForRecapture(state, target, unit, plan);
  const currentDistance = hexDistance(unit.coord, target.coord);
  const path = findMovementPath(state, unit, target.coord);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (!path?.length || remainingMovement <= 0) {
    return getEnemyLegalMoveCoords(state, unit)
      .filter((coord) => hexDistance(coord, target.coord) < currentDistance)
      .filter(safeBreakoutProgress)
      .sort((first, second) => hexDistance(first, target.coord) - hexDistance(second, target.coord) || hexId(first).localeCompare(hexId(second)))[0];
  }
  for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
    const coord = path[steps - 1];
    if (canMoveUnitTo(state, unit, coord) && hexDistance(coord, target.coord) < currentDistance && safeBreakoutProgress(coord)) {
      return coord;
    }
  }
  return undefined;
}

function getKnownGatePressure(state: GameState, gate: GateState): number {
  return getKnownPlayerUnitsForEnemy(state)
    .filter((unit) => hexDistance(unit.coord, gate.coord) <= 4)
    .reduce((total, unit) => total + getUnitInstanceValue(state, unit), 0);
}

function isEnemyOpeningPatrolAtGateStandoff(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (state.day > 7 || (!isReconUnit(unit.type) && !isPatrolCapableUnit(unit.type))) {
    return false;
  }
  const center = state.bases.Enemy.q;
  const mission = plan.rolesByUnitId[unit.id];
  const gate =
    mission === "PatrolWest"
      ? (state.gates ?? []).find((candidate) => candidate.id === "West")
      : mission === "PatrolEast"
        ? (state.gates ?? []).find((candidate) => candidate.id === "East")
        : unit.coord.q <= center
          ? (state.gates ?? []).find((candidate) => candidate.id === "West")
          : (state.gates ?? []).find((candidate) => candidate.id === "East");
  return Boolean(gate && !sameHex(unit.coord, gate.coord) && hexDistance(unit.coord, gate.coord) <= 2);
}

function chooseEnemyPlannerNonCapturerGateTileMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (unit.owner !== "Enemy" || getUnitDefinition(unit.type).humanBased) {
    return undefined;
  }

  const gate = (state.gates ?? []).find((candidate) => sameHex(candidate.coord, unit.coord));
  if (!gate || shouldEnemyNonCapturerHoldGateAsOnlyBlocker(state, unit, gate)) {
    return undefined;
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => !sameHex(coord, gate.coord))
    .sort((first, second) => {
      const firstDistance = hexDistance(first, gate.coord);
      const secondDistance = hexDistance(second, gate.coord);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      const firstSupport = Math.max(0, 3 - firstDistance) * 24 + getEnemyPlannerSupportScore(state, unit, first) - firstDanger;
      const secondSupport = Math.max(0, 3 - secondDistance) * 24 + getEnemyPlannerSupportScore(state, unit, second) - secondDanger;
      return secondSupport - firstSupport || firstDistance - secondDistance || hexId(first).localeCompare(hexId(second));
    })[0];
}

function shouldEnemyNonCapturerHoldGateAsOnlyBlocker(state: GameState, unit: UnitInstance, gate: GateState): boolean {
  if (getUnitDefinition(unit.type).domain !== "Ground") {
    return false;
  }

  const playerCaptureThreat = getKnownPlayerUnitsForEnemy(state).some(
    (player) => getUnitDefinition(player.type).humanBased && !sameHex(player.coord, gate.coord) && hexDistance(player.coord, gate.coord) <= getEffectiveUnitStats(state, player.owner, player.type, player.level, player.coord, gate.coord).moveRange
  );
  if (!playerCaptureThreat && gate.occupation.Player <= 0) {
    return false;
  }

  return !getOwnerUnits(state, "Enemy").some((ally) => {
    if (ally.id === unit.id || !getUnitDefinition(ally.type).humanBased || ally.health / Math.max(1, ally.maxHealth) <= 0.35) {
      return false;
    }
    return sameHex(ally.coord, gate.coord) || hexDistance(ally.coord, gate.coord) <= getRemainingMovementPoints(state, ally);
  });
}

function chooseEnemyPlannerGateBlockerMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (state.day > 16 || getUnitDefinition(unit.type).humanBased) {
    return undefined;
  }

  const gate = (state.gates ?? []).find((candidate) => candidate.owner !== "Enemy" && sameHex(candidate.coord, unit.coord));
  if (!gate) {
    return undefined;
  }

  const capturerCommitted = getOwnerUnits(state, "Enemy").some(
    (ally) => ally.id !== unit.id && getUnitDefinition(ally.type).humanBased && (plan.rolesByUnitId[ally.id] === "CaptureGate" || hexDistance(ally.coord, gate.coord) <= 5)
  );
  if (!capturerCommitted) {
    return undefined;
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => !sameHex(coord, gate.coord))
    .sort((first, second) => {
      const firstDistance = hexDistance(first, gate.coord);
      const secondDistance = hexDistance(second, gate.coord);
      const firstSupport = Math.max(0, 3 - firstDistance) * 20 - estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondSupport = Math.max(0, 3 - secondDistance) * 20 - estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return secondSupport - firstSupport || firstDistance - secondDistance || hexId(first).localeCompare(hexId(second));
    })[0];
}

function chooseEnemyPlannerScoutGateStandoffMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const mission = plan.rolesByUnitId[unit.id];
  if (mission !== "Scout" && mission !== "PatrolWest" && mission !== "PatrolEast") {
    return undefined;
  }
  if (!isReconUnit(unit.type) && !isPatrolCapableUnit(unit.type)) {
    return undefined;
  }

  const gate = (state.gates ?? []).find((candidate) => sameHex(candidate.coord, unit.coord));
  if (!gate) {
    return undefined;
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => !sameHex(coord, gate.coord) && hexDistance(coord, gate.coord) <= 2)
    .sort((first, second) => {
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      const firstSupport = getEnemyPlannerSupportScore(state, unit, first);
      const secondSupport = getEnemyPlannerSupportScore(state, unit, second);
      return firstDanger - secondDanger || secondSupport - firstSupport || hexId(first).localeCompare(hexId(second));
    })[0];
}

function chooseEnemyPlannerEarlyPatrolPriorityMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  if (state.day > 10 || (!isReconUnit(unit.type) && !isPatrolCapableUnit(unit.type))) {
    return undefined;
  }
  const mission = plan.rolesByUnitId[unit.id];
  if (mission !== "Scout" && mission !== "PatrolWest" && mission !== "PatrolEast" && unit.type !== "Attack Heli") {
    return undefined;
  }
  return chooseEnemyPlannerOpeningPatrolMove(state, unit, plan, reservedDestinations);
}

function chooseEnemyPlannerForcedOpeningPatrolMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  const mission = plan.rolesByUnitId[unit.id];
  if (state.day > 7 || (mission !== "PatrolWest" && mission !== "PatrolEast")) {
    return undefined;
  }
  const gate = (state.gates ?? []).find((candidate) => candidate.id === (mission === "PatrolWest" ? "West" : "East"));
  if (!gate) {
    return undefined;
  }
  const distance = hexDistance(unit.coord, gate.coord);
  if (distance <= 2 || distance > 7) {
    return undefined;
  }
  const missionForUnit = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const forcedGateMove = getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => !sameHex(coord, gate.coord))
    .filter((coord) => coord.r <= gate.coord.r - 2)
    .filter((coord) => hexDistance(coord, gate.coord) <= 2)
    .filter((coord) => !isGateHex(state, coord) || !isHardOpeningIfvGateOccupancyForbidden(state, unit))
    .sort((first, second) => {
      const firstPenalty = getEnemyParallelAdvancePenalty(state, unit, first, missionForUnit, plan, reservedDestinations);
      const secondPenalty = getEnemyParallelAdvancePenalty(state, unit, second, missionForUnit, plan, reservedDestinations);
      const firstReveal = getEnemyScoutFogRevealScore(state, unit, first);
      const secondReveal = getEnemyScoutFogRevealScore(state, unit, second);
      return firstPenalty - secondPenalty || hexDistance(first, gate.coord) - hexDistance(second, gate.coord) || secondReveal - firstReveal || hexId(first).localeCompare(hexId(second));
    })[0];
  return forcedGateMove ?? chooseEnemyPlannerOpeningPatrolMove(state, unit, plan, reservedDestinations);
}

function shouldEnemyPlannerOpeningGateCapturerHold(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (plan.rolesByUnitId[unit.id] !== "CaptureGate" || !getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  return (state.gates ?? []).some((gate) => gate.owner !== "Enemy" && sameHex(unit.coord, gate.coord));
}

function shouldRejectOpeningCaptureGateHold(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (chooseHardOpeningCaptureGateProgressMove(state, unit, plan)) {
    return true;
  }

  const role = plan.rolesByUnitId[unit.id];
  return (
    state.difficulty === "Hard" &&
    state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY &&
    (role === "ShadowCapturer" || role === "EscortCapture") &&
    Boolean(chooseEnemyPlannerOpeningGateEscortMove(state, unit, plan))
  );
}

function chooseHardOpeningCaptureGateProgressMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  if (!isHardOpeningCaptureGateCommitmentRequired(state, unit, plan)) {
    return undefined;
  }

  const target = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
  if (!target) {
    return undefined;
  }

  const currentDistance = hexDistance(unit.coord, target.coord);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0) {
    return undefined;
  }

  const safeProgress = (coord: UnitInstance["coord"]): boolean => {
    if (hexDistance(coord, target.coord) >= currentDistance || !canMoveUnitTo(state, unit, coord)) {
      return false;
    }
    if (sameHex(coord, target.coord)) {
      if (!isGateSafeForRecapture(state, target, unit, plan)) {
        return false;
      }
      if (shouldEnemyGateCaptureTrustCoveredStaleIntel(state, target, unit, plan)) {
        return true;
      }
    }
    const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
    return danger < unit.health && !isEnemyPlannerOneShotExposed(state, unit, coord, plan);
  };

  const path = findMovementPath(state, unit, target.coord);
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (safeProgress(coord) && getEnemyParallelAdvancePenalty(state, unit, coord, plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit), plan, reservedDestinations) === 0) {
        return coord;
      }
    }
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter(safeProgress)
    .sort((first, second) => {
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
      return (
        getEnemyParallelAdvancePenalty(state, unit, first, mission, plan, reservedDestinations) -
          getEnemyParallelAdvancePenalty(state, unit, second, mission, plan, reservedDestinations) ||
        hexDistance(first, target.coord) - hexDistance(second, target.coord) ||
        firstDanger - secondDanger ||
        hexId(first).localeCompare(hexId(second))
      );
    })[0];
}

function isHardOpeningCaptureGateCommitmentRequired(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (
    !usesHardEnemyDoctrine(state) ||
    state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY ||
    plan.rolesByUnitId[unit.id] !== "CaptureGate" ||
    !getUnitDefinition(unit.type).humanBased ||
    unit.health / Math.max(1, unit.maxHealth) <= 0.4
  ) {
    return false;
  }

  const target = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
  return Boolean(target && !sameHex(unit.coord, target.coord));
}

function chooseEnemyPlannerForcedOpeningGateEntryMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (state.day > 12 || plan.rolesByUnitId[unit.id] !== "CaptureGate" || !getUnitDefinition(unit.type).humanBased) {
    return undefined;
  }
  const gate = (state.gates ?? [])
    .filter((candidate) => candidate.owner !== "Enemy")
    .filter((candidate) => hexDistance(unit.coord, candidate.coord) <= 2)
    .sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord))[0];
  if (!gate || sameHex(unit.coord, gate.coord) || !canMoveUnitTo(state, unit, gate.coord) || !isGateSafeForRecapture(state, gate, unit, plan)) {
    return undefined;
  }
  return gate.coord;
}

function shouldEnemyPlannerOpeningGateSupportHold(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  return false;
}

function chooseEnemyPlannerMidgameCenterControlMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (
    !isHardMidgameDoctrineActive(state, plan) ||
    (unit.type !== "Tank" && unit.type !== "IFV") ||
    unit.placedDay === state.day ||
    isActiveEnemyBaseThreat(state, getEnemyBaseThreat(state))
  ) {
    return undefined;
  }

  const target = chooseEnemyMidgameCenterControlTarget(state, unit, plan);
  if (!target || hexDistance(unit.coord, target) <= 1) {
    return undefined;
  }

  const currentDistance = hexDistance(unit.coord, target);
  const safeProgress = (coord: UnitInstance["coord"]): boolean => {
    if (!canMoveUnitTo(state, unit, coord) || hexDistance(coord, target) >= currentDistance) {
      return false;
    }
    const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
    return isEnemyArmorCommitmentProgressAllowed(state, unit, coord, target, danger, plan);
  };
  const path = findMovementPath(state, unit, target);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0) {
    return undefined;
  }
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (safeProgress(coord)) {
        return coord;
      }
    }
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter(safeProgress)
    .sort((first, second) => {
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return hexDistance(first, target) - hexDistance(second, target) || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
}

function chooseEnemyMidgameCenterControlTarget(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const gates = state.gates ?? [];
  const uncapturedGates = gates.filter((gate) => gate.owner !== "Enemy");
  if (!uncapturedGates.length) {
    return undefined;
  }

  const center = getEnemyMidgameCenterStagingCoord(state);
  const assignedGate = getEnemyCampaignAssignedGateForUnit(state, unit, plan) ?? chooseEnemyPlannerOpeningGateSupportTarget(state, unit, plan);
  const assignedGateIsHeavy = Boolean(assignedGate && scoreEnemyMidgameGateDefense(state, assignedGate, plan) >= 260);
  const hasOneGate = gates.some((gate) => gate.owner === "Enemy") && uncapturedGates.length > 0;
  const centerSecured = isEnemyMidgameCenterSecured(state, plan);
  if ((hasOneGate || assignedGateIsHeavy) && !centerSecured) {
    return center;
  }
  if (hasOneGate && centerSecured) {
    return (assignedGate && assignedGate.owner !== "Enemy" ? assignedGate : uncapturedGates.sort((first, second) => scoreOpeningGateSupportTarget(state, unit, second, plan) - scoreOpeningGateSupportTarget(state, unit, first, plan))[0])?.coord;
  }
  return undefined;
}

function scoreEnemyMidgameGateDefense(state: GameState, gate: GateState, plan: EnemyTurnPlan): number {
  return plan.playerIntel
    .filter((intel) => intel.age <= 3 && hexDistance(intel.predictedCoord, gate.coord) <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS)
    .reduce((score, intel) => score + getUnitInstanceValue(state, intel.unit) * intel.confidence, gate.occupation.Player * 80);
}

function isEnemyMidgameCenterSecured(state: GameState, plan: EnemyTurnPlan): boolean {
  const center = getEnemyMidgameCenterStagingCoord(state);
  const enemyCenterPower = getOwnerUnits(state, "Enemy")
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => unit.type === "Tank" || unit.type === "IFV" || unit.type === "Artillery" || unit.type === "Anti-Air")
    .filter((unit) => hexDistance(unit.coord, center) <= 4)
    .reduce((score, unit) => score + getUnitInstanceValue(state, unit) * 0.45, 0);
  const playerCenterPower = plan.playerIntel
    .filter((intel) => intel.age <= 3 && hexDistance(intel.predictedCoord, center) <= 5)
    .reduce((score, intel) => score + getUnitInstanceValue(state, intel.unit) * intel.confidence, 0);
  return enemyCenterPower >= Math.max(180, playerCenterPower + 80);
}

function chooseEnemyPlannerOpeningGateCapturerMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  if (usesHardEnemyDoctrine(state) && state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY) {
    return chooseHardOpeningCaptureGateProgressMove(state, unit, plan, reservedDestinations);
  }
  if (!usesHardEnemyDoctrine(state) && state.day > 12) {
    return undefined;
  }
  if (plan.rolesByUnitId[unit.id] !== "CaptureGate" || !getUnitDefinition(unit.type).humanBased) {
    return undefined;
  }
  const target = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
  if (!target || sameHex(unit.coord, target.coord)) {
    return undefined;
  }
  const currentDistance = hexDistance(unit.coord, target.coord);
  const path = findMovementPath(state, unit, target.coord);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0) {
    return undefined;
  }
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (canMoveUnitTo(state, unit, coord) && hexDistance(coord, target.coord) < currentDistance && (!sameHex(coord, target.coord) || isGateSafeForRecapture(state, target, unit, plan))) {
        return coord;
      }
    }
  }
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => hexDistance(coord, target.coord) < currentDistance)
    .filter((coord) => !sameHex(coord, target.coord) || isGateSafeForRecapture(state, target, unit, plan))
    .sort((first, second) => hexDistance(first, target.coord) - hexDistance(second, target.coord) || hexId(first).localeCompare(hexId(second)))[0];
}

function chooseEnemyPlannerOpeningGateEscortMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  const gatePressure = hasActivePlayerGatePressure(state);
  const gateSupportLastDay = usesHardEnemyDoctrine(state) ? (gatePressure ? 22 : 16) : gatePressure ? 22 : 12;
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (
    state.day > gateSupportLastDay ||
    (mission !== "Escort" && mission !== "ShadowCapturer" && mission !== "EscortCapture") ||
    (unit.type !== "Infantry" && !isOpeningGateSupportUnit(unit.type) && !getUnitDefinition(unit.type).humanBased)
  ) {
    return undefined;
  }
  const target = chooseEnemyPlannerOpeningGateSupportTarget(state, unit, plan);
  if (!target) {
    return undefined;
  }
  if (mission === "ShadowCapturer" || mission === "EscortCapture") {
    return chooseEnemyPlannerShadowCapturerMove(state, unit, plan, target);
  }
  if (usesHardEnemyDoctrine(state) && state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY && isOpeningArmorSupportUnit(unit.type)) {
    return chooseEnemyPlannerOpeningGateArmorSupportMove(state, unit, plan, target, reservedDestinations);
  }
  const supportRadius = usesHardEnemyDoctrine(state) && state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY && target.owner !== "Enemy"
    ? 1
    : unit.type === "Infantry" ? 3 : 2;
  if (hexDistance(unit.coord, target.coord) <= supportRadius) {
    return undefined;
  }
  const bestAttack = getEnemyPlannerAttackTargets(state, unit, plan)[0];
  if (bestAttack && (bestAttack.score > 180 || hexDistance(bestAttack.target.coord, target.coord) <= 3)) {
    return undefined;
  }
  const currentDistance = hexDistance(unit.coord, target.coord);
  const legalMoves = getEnemyLegalMoveCoords(state, unit);
  return legalMoves
    .filter((coord) => hexDistance(coord, target.coord) < currentDistance)
    .filter((coord) => !sameHex(coord, target.coord))
    .filter((coord) => !isReservedCaptureTileForEnemySupport(state, unit, coord, target, plan))
    .sort((first, second) => {
      const firstDistance = hexDistance(first, target.coord);
      const secondDistance = hexDistance(second, target.coord);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      const firstCapturerSupport = getOpeningGateCapturerSupportScore(state, first, target, plan);
      const secondCapturerSupport = getOpeningGateCapturerSupportScore(state, second, target, plan);
      return (
        Math.abs(firstDistance - supportRadius) - Math.abs(secondDistance - supportRadius) ||
        firstDistance - secondDistance ||
        secondCapturerSupport - firstCapturerSupport ||
        firstDanger - secondDanger ||
        hexId(first).localeCompare(hexId(second))
      );
    })[0];
}

function chooseEnemyPlannerOpeningGateArmorSupportMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  gate: GateState,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  const supportCoord = chooseEnemyPlannerOpeningGateArmorSupportCoord(state, unit, plan, gate);
  if (!supportCoord) {
    return chooseEnemyPlannerOpeningGateArmorFallbackMove(state, unit, plan, gate);
  }

  if (sameHex(unit.coord, supportCoord)) {
    return undefined;
  }

  const currentDistance = hexDistance(unit.coord, supportCoord);
  const path = findMovementPath(state, unit, supportCoord);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0) {
    return undefined;
  }
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (
        canMoveUnitTo(state, unit, coord) &&
        hexDistance(coord, supportCoord) < currentDistance &&
        !shouldOpeningArmorSupportAvoidCoord(state, unit, coord, gate, plan)
      ) {
        return coord;
      }
    }
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => hexDistance(coord, supportCoord) < currentDistance)
    .filter((coord) => !shouldOpeningArmorSupportAvoidCoord(state, unit, coord, gate, plan))
    .sort((first, second) => {
      const firstDistance = hexDistance(first, supportCoord);
      const secondDistance = hexDistance(second, supportCoord);
      const firstGateDistance = hexDistance(first, gate.coord);
      const secondGateDistance = hexDistance(second, gate.coord);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
      return (
        firstDistance - secondDistance ||
        getEnemyParallelAdvancePenalty(state, unit, first, mission, plan, reservedDestinations) -
          getEnemyParallelAdvancePenalty(state, unit, second, mission, plan, reservedDestinations) ||
        Math.abs(firstGateDistance - 2) - Math.abs(secondGateDistance - 2) ||
        firstDanger - secondDanger ||
        hexId(first).localeCompare(hexId(second))
      );
    })[0];
}

function chooseEnemyPlannerEarlyArmorFormationMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  if (
    !usesHardEnemyDoctrine(state) ||
    state.day > 12 ||
    (unit.type !== "Tank" && unit.type !== "IFV") ||
    unit.hasMovedThisDay ||
    unit.placedDay === state.day ||
    getEnemyPlannerAttackTargets(state, unit, plan).some((target) => target.score > 130)
  ) {
    return undefined;
  }

  const gate = chooseEnemyPlannerOpeningGateSupportTarget(state, unit, plan);
  if (!gate) {
    return undefined;
  }

  const supportCoord = chooseEnemyPlannerOpeningGateArmorSupportCoord(state, unit, plan, gate);
  if (!supportCoord || sameHex(unit.coord, supportCoord)) {
    return undefined;
  }

  const edgePinned = unit.coord.q <= 1 || unit.coord.q >= state.map.width - 2;
  const isolated = getOwnerUnits(state, "Enemy")
    .filter((ally) => ally.id !== unit.id && (ally.type === "Tank" || ally.type === "IFV" || getUnitDefinition(ally.type).humanBased))
    .every((ally) => hexDistance(unit.coord, ally.coord) > 4);
  const gatePressure = getKnownPlayerUnitsForEnemy(state).some((playerUnit) => hexDistance(playerUnit.coord, gate.coord) <= 6);
  const currentSupportScore = scoreEnemyGateTheatreDefensePosition(state, unit, unit.coord, gate, plan);
  const targetSupportScore = scoreEnemyGateTheatreDefensePosition(state, unit, supportCoord, gate, plan);
  const farFromSupport = hexDistance(unit.coord, supportCoord) > 2;
  if (!edgePinned && !isolated && !gatePressure && !farFromSupport && targetSupportScore <= currentSupportScore + 45) {
    return undefined;
  }

  const currentDistance = hexDistance(unit.coord, supportCoord);
  const path = findMovementPath(state, unit, supportCoord);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  const currentEdgePenalty = getEnemyOpeningArmorMapEdgePenalty(state, unit.coord);
  const safeProgress = (coord: UnitInstance["coord"]): boolean => {
    if (!canMoveUnitTo(state, unit, coord) || hexDistance(coord, supportCoord) >= currentDistance) {
      return false;
    }
    if (currentEdgePenalty > 0 && getEnemyOpeningArmorMapEdgePenalty(state, coord) > 0) {
      return false;
    }
    const key = getEnemyDestinationReservationKey(unit.type, coord);
    if (reservedDestinations[key] && reservedDestinations[key] !== unit.id) {
      return false;
    }
    const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
    return isEnemyArmorCommitmentProgressAllowed(state, unit, coord, supportCoord, danger, plan);
  };

  if (path?.length && remainingMovement > 0) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (safeProgress(coord)) {
        return coord;
      }
    }
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter(safeProgress)
    .sort((first, second) => {
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return hexDistance(first, supportCoord) - hexDistance(second, supportCoord) || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
}

function isEnemyArmorCommitmentProgressAllowed(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  objective: UnitInstance["coord"],
  danger: number,
  plan: EnemyTurnPlan
): boolean {
  if (isEnemyPlannerOneShotExposed(state, unit, coord, plan)) {
    return false;
  }
  if (!isEnemyArmorGroundCommitmentUnit(state, unit, plan)) {
    return danger < unit.health;
  }

  const currentDistance = hexDistance(unit.coord, objective);
  const nextDistance = hexDistance(coord, objective);
  const progress = currentDistance - nextDistance;
  if (progress <= 0) {
    return danger < unit.health;
  }

  const healthRatio = unit.health / Math.max(1, unit.maxHealth);
  const riskBudget = healthRatio >= 0.72 ? 1.45 : healthRatio >= 0.55 ? 1.18 : 0.9;
  const support = getEnemyPlannerSupportScore(state, unit, coord);
  const supportedRiskBonus = support >= 24 ? 0.12 : 0;
  return danger < unit.health * (riskBudget + supportedRiskBonus);
}

function isEnemyArmorGroundCommitmentUnit(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  return (
    state.difficulty === "Hard" &&
    (unit.type === "Tank" || unit.type === "IFV") &&
    unit.owner === "Enemy" &&
    unit.health / Math.max(1, unit.maxHealth) > 0.48 &&
    state.day <= 16 &&
    !ownerControlsBothGates(state, "Enemy") &&
    !isActiveEnemyBaseThreat(state, getEnemyBaseThreat(state)) &&
    Boolean(getEnemyArmorGroundCommitmentObjective(state, unit, plan))
  );
}

function getEnemyArmorGroundCommitmentObjective(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan
): UnitInstance["coord"] | undefined {
  if (unit.type !== "Tank" && unit.type !== "IFV") {
    return undefined;
  }

  const midgameTarget = isHardMidgameDoctrineActive(state, plan)
    ? chooseEnemyMidgameCenterControlTarget(state, unit, plan)
    : undefined;
  if (midgameTarget) {
    return midgameTarget;
  }

  const gate = state.day <= 16 ? chooseEnemyPlannerOpeningGateSupportTarget(state, unit, plan) : undefined;
  if (!gate) {
    return undefined;
  }

  return chooseEnemyPlannerOpeningGateArmorSupportCoord(state, unit, plan, gate) ?? gate.coord;
}

function getEnemyOpeningArmorMapEdgePenalty(state: GameState, coord: UnitInstance["coord"]): number {
  return Math.max(0, 2 - coord.q) + Math.max(0, coord.q - (state.map.width - 3));
}

function chooseEnemyPlannerOpeningGateArmorSupportCoord(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  gate: GateState
): UnitInstance["coord"] | undefined {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
  const approachHexes = getOpeningGatePlayerApproachCoords(state, gate);
  return state.map.hexes
    .filter((hex) => hex.passable)
    .map((hex) => hex.coord)
    .filter((coord) => coord.q >= 2 && coord.q <= state.map.width - 3)
    .filter((coord) => hexDistance(coord, gate.coord) >= 1 && hexDistance(coord, gate.coord) <= 3)
    .filter((coord) => canEnemyGateSupportPositionTargetGate(state, unit, coord, gate))
    .filter((coord) => !shouldOpeningArmorSupportAvoidCoord(state, unit, coord, gate, plan))
    .map((coord) => {
      const gateDistance = hexDistance(coord, gate.coord);
      const currentProgress = hexDistance(unit.coord, coord);
      const approachCoverage = approachHexes.reduce((score, approach) => {
        const distance = hexDistance(coord, approach);
        return score + (distance <= stats.attackRange ? 36 + Math.max(0, stats.attackRange - distance) * 5 : 0);
      }, 0);
      const capturerSupport = getOpeningGateCapturerSupportScore(state, coord, gate, plan);
      const laneSideScore = gate.id === "West" ? Math.max(0, state.bases.Enemy.q - coord.q) * 2 : Math.max(0, coord.q - state.bases.Enemy.q) * 2;
      const ifvScoutScore = unit.type === "IFV" ? scoreEnemyOpeningIfvScoutSupportCoord(state, unit, coord, gate) : 0;
      const gatePressure = getKnownPlayerUnitsForEnemy(state).filter((playerUnit) => hexDistance(playerUnit.coord, gate.coord) <= 6).length;
      const idealGateDistance = gatePressure > 0 || unit.type === "Tank" ? 3 : 2;
      const mapEdgePenalty = Math.max(0, 2 - coord.q) * 70 + Math.max(0, coord.q - (state.map.width - 3)) * 70;
      const centerCohesion = Math.max(0, 10 - Math.abs(coord.q - state.bases.Enemy.q)) * (gatePressure > 0 ? 6 : 2);
      const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
      const occupancyPenalty = getOwnerUnits(state, "Enemy").filter((ally) => ally.id !== unit.id && sameHex(ally.coord, coord)).length * 90;
      return {
        coord,
        score:
          approachCoverage +
          capturerSupport * 0.7 +
          (unit.type === "IFV" ? laneSideScore * 0.35 : laneSideScore) +
          ifvScoutScore +
          centerCohesion +
          Math.max(0, 4 - gateDistance) * 18 -
          Math.abs(gateDistance - idealGateDistance) * 34 -
          currentProgress * 4 -
          danger * 0.55 -
          mapEdgePenalty -
          occupancyPenalty
      };
    })
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function canEnemyGateSupportPositionTargetGate(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState
): boolean {
  if (getUnitDefinition(unit.type).cannotAttack) {
    return false;
  }

  if (!canOwnerOperateAcrossFrontLine(state, unit.owner, coord) || !canOwnerOperateAcrossFrontLine(state, unit.owner, gate.coord)) {
    return false;
  }

  const canTargetGateOccupier = UNIT_DEFINITIONS.some((definition) => definition.humanBased && canUnitTargetUnit(unit.type, definition.type));
  if (!canTargetGateOccupier) {
    return false;
  }

  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, gate.coord);
  return hexDistance(coord, gate.coord) <= stats.attackRange;
}

function scoreEnemyOpeningIfvScoutSupportCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState
): number {
  const gateDistance = hexDistance(coord, gate.coord);
  const center = getEnemyOpeningCenterStagingCoord(state);
  const centerDistance = hexDistance(coord, center);
  const visibility = getEnemyScoutFogRevealScore(state, unit, coord);
  const gateStandoff = gateDistance >= 1 && gateDistance <= 3 ? 92 - Math.abs(gateDistance - 2) * 18 : -120;
  const centerCoverage = Math.max(0, 9 - centerDistance) * 16;
  const gateLaneCoverage = getGateSideHexes(state, gate).has(hexId(coord)) ? 44 : 0;
  const mapEdgePenalty = Math.max(0, 2 - coord.q) * 72 + Math.max(0, coord.q - (state.map.width - 3)) * 72;
  return visibility * 6 + gateStandoff + centerCoverage + gateLaneCoverage - mapEdgePenalty;
}

function chooseEnemyPlannerOpeningGateArmorFallbackMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  gate: GateState
): UnitInstance["coord"] | undefined {
  const hasCapturer = hasEnemyGateCapturerAssigned(state, gate, plan);
  if (!hasCapturer && !isHardOpeningIfvGateOccupancyForbidden(state, unit) && canMoveUnitTo(state, unit, gate.coord)) {
    return gate.coord;
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => !shouldOpeningArmorSupportAvoidCoord(state, unit, coord, gate, plan))
    .filter((coord) => hexDistance(coord, gate.coord) < hexDistance(unit.coord, gate.coord))
    .sort((first, second) => {
      const firstDistance = hexDistance(first, gate.coord);
      const secondDistance = hexDistance(second, gate.coord);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return Math.abs(firstDistance - 2) - Math.abs(secondDistance - 2) || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
}

function shouldOpeningArmorSupportAvoidCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState,
  plan: EnemyTurnPlan
): boolean {
  if (!sameHex(coord, gate.coord)) {
    return false;
  }
  return isHardOpeningIfvGateOccupancyForbidden(state, unit) || hasEnemyGateCapturerAssigned(state, gate, plan);
}

function isHardOpeningIfvGateOccupancyForbidden(state: GameState, unit: UnitInstance): boolean {
  return isHardOpeningDoctrineActive(state) && state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY && unit.owner === "Enemy" && unit.type === "IFV";
}

function hasEnemyGateCapturerAssigned(state: GameState, gate: GateState, plan: EnemyTurnPlan): boolean {
  return getOwnerUnits(state, "Enemy").some((ally) => {
    if (!getUnitDefinition(ally.type).humanBased || plan.campaignPlan.assignedGateByUnitId[ally.id] !== gate.id) {
      return false;
    }
    const role = plan.rolesByUnitId[ally.id];
    return role === "CaptureGate" || role === "ShadowCapturer" || role === "EscortCapture";
  });
}

function getOpeningGatePlayerApproachCoords(state: GameState, gate: GateState): UnitInstance["coord"][] {
  const rows = [1, 2, 3].map((offset) => Math.min(state.map.height - 1, gate.coord.r + offset));
  const columns = [-2, -1, 0, 1, 2].map((offset) => Math.max(0, Math.min(state.map.width - 1, gate.coord.q + offset)));
  const coords = rows.flatMap((r) => columns.map((q) => ({ q, r })));
  return uniqueCoords(coords).filter((coord) => Boolean(getHex(state.map, coord)));
}

function chooseEnemyPlannerShadowCapturerMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  gate: GateState
): UnitInstance["coord"] | undefined {
  const gateEntry = chooseEnemyPlannerSupportCapturerGateEntryMove(state, unit, plan, gate);
  if (gateEntry) {
    return gateEntry;
  }

  const gateDistance = hexDistance(unit.coord, gate.coord);
  const gateStagingMove = chooseEnemyPlannerOpeningGateEscortFallbackMove(state, unit, plan, gate, 2);
  if (gateStagingMove) {
    return gateStagingMove;
  }
  if (gateDistance <= 2 && !sameHex(unit.coord, gate.coord)) {
    return undefined;
  }

  const anchor = chooseEnemyPlannerShadowCapturerAnchor(state, unit, plan, gate);
  if (!anchor) {
    return chooseEnemyPlannerOpeningGateEscortFallbackMove(state, unit, plan, gate, 2);
  }

  const currentDistance = hexDistance(unit.coord, anchor.coord);
  if (
    state.difficulty === "Hard" &&
    state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY &&
    gate.owner !== "Enemy" &&
    gateDistance > 3
  ) {
    return chooseEnemyPlannerOpeningGateEscortFallbackMove(state, unit, plan, gate, 1);
  }
  if (currentDistance >= 1 && currentDistance <= 3 && gateDistance <= 3 && !sameHex(unit.coord, gate.coord)) {
    return undefined;
  }

  const legalMoves = getEnemyLegalMoveCoords(state, unit);
  const trailingMoves = legalMoves
    .filter((coord) => !sameHex(coord, gate.coord))
    .filter((coord) => {
      const anchorDistance = hexDistance(coord, anchor.coord);
      return anchorDistance >= 1 && anchorDistance <= 3;
    });
  const candidates = trailingMoves.length
    ? trailingMoves
    : legalMoves.filter((coord) => !sameHex(coord, gate.coord) && hexDistance(coord, anchor.coord) < currentDistance);

  return candidates
    .sort((first, second) => {
      const firstAnchorDistance = hexDistance(first, anchor.coord);
      const secondAnchorDistance = hexDistance(second, anchor.coord);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return (
        Math.abs(firstAnchorDistance - 2) - Math.abs(secondAnchorDistance - 2) ||
        hexDistance(first, gate.coord) - hexDistance(second, gate.coord) ||
        firstDanger - secondDanger ||
        hexId(first).localeCompare(hexId(second))
      );
    })[0];
}

function chooseEnemyPlannerSupportCapturerGateEntryMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  gate: GateState
): UnitInstance["coord"] | undefined {
  const role = plan.rolesByUnitId[unit.id];
  if (
    (role !== "ShadowCapturer" && role !== "EscortCapture") ||
    gate.owner === "Enemy" ||
    sameHex(unit.coord, gate.coord) ||
    !getUnitDefinition(unit.type).humanBased ||
    !canMoveUnitTo(state, unit, gate.coord) ||
    !isGateSafeForRecapture(state, gate, unit, plan)
  ) {
    return undefined;
  }

  const alliedHumanOnGate = getOwnerUnits(state, "Enemy").some((ally) => ally.id !== unit.id && getUnitDefinition(ally.type).humanBased && sameHex(ally.coord, gate.coord));
  if (alliedHumanOnGate) {
    return undefined;
  }

  const principal = getOwnerUnits(state, "Enemy").find(
    (ally) =>
      ally.id !== unit.id &&
      getUnitDefinition(ally.type).humanBased &&
      plan.rolesByUnitId[ally.id] === "CaptureGate" &&
      plan.campaignPlan.assignedGateByUnitId[ally.id] === gate.id
  );
  if (principal && !principal.hasMovedThisDay && hexDistance(principal.coord, gate.coord) <= 1) {
    return undefined;
  }

  return gate.coord;
}

function chooseEnemyPlannerShadowCapturerAnchor(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  gate: GateState
): UnitInstance | undefined {
  const lane = plan.campaignPlan.laneTaskForces[gate.id];
  const principal = lane.principalCapturerId
    ? state.units.find((candidate) => candidate.id === lane.principalCapturerId && candidate.owner === "Enemy" && candidate.id !== unit.id)
    : undefined;
  if (principal) {
    return principal;
  }

  return getOwnerUnits(state, "Enemy")
    .filter((ally) => ally.id !== unit.id && plan.campaignPlan.assignedGateByUnitId[ally.id] === gate.id)
    .filter((ally) => plan.rolesByUnitId[ally.id] === "CaptureGate")
    .sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord) || first.id.localeCompare(second.id))[0];
}

function chooseEnemyPlannerOpeningGateEscortFallbackMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  target: GateState,
  supportRadius: number
): UnitInstance["coord"] | undefined {
  if (hexDistance(unit.coord, target.coord) <= supportRadius && !sameHex(unit.coord, target.coord)) {
    return undefined;
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => hexDistance(coord, target.coord) < hexDistance(unit.coord, target.coord))
    .filter((coord) => !sameHex(coord, target.coord))
    .filter((coord) => !isReservedCaptureTileForEnemySupport(state, unit, coord, target, plan))
    .sort((first, second) => {
      const firstDistance = hexDistance(first, target.coord);
      const secondDistance = hexDistance(second, target.coord);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return Math.abs(firstDistance - supportRadius) - Math.abs(secondDistance - supportRadius) || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
}

function chooseEnemyPlannerOpeningGateSupportTarget(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): GateState | undefined {
  const gates = (state.gates ?? []).filter((gate) => gate.owner !== "Enemy");
  if (!gates.length) {
    return undefined;
  }

  const assignedGateId = plan.campaignPlan.assignedGateByUnitId[unit.id];
  const assignedGate = assignedGateId ? gates.find((gate) => gate.id === assignedGateId) : undefined;
  if (assignedGate) {
    return assignedGate;
  }

  const winningGate = gates
    .filter((gate) => gate.occupation.Enemy > 0)
    .sort((first, second) => second.occupation.Enemy - first.occupation.Enemy || scoreOpeningGateSupportTarget(state, unit, second, plan) - scoreOpeningGateSupportTarget(state, unit, first, plan))[0];
  if (winningGate && state.day <= 16) {
    return winningGate;
  }

  return gates.sort((first, second) => scoreOpeningGateSupportTarget(state, unit, second, plan) - scoreOpeningGateSupportTarget(state, unit, first, plan))[0];
}

function isReservedCaptureTileForEnemySupport(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState,
  plan: EnemyTurnPlan
): boolean {
  if (!sameHex(coord, gate.coord) || getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  return getOwnerUnits(state, "Enemy").some((ally) => {
    if (ally.id === unit.id || !getUnitDefinition(ally.type).humanBased) {
      return false;
    }
    const role = plan.rolesByUnitId[ally.id];
    return (role === "CaptureGate" || role === "ShadowCapturer" || role === "EscortCapture") && hexDistance(ally.coord, gate.coord) <= 5;
  });
}

function scoreOpeningGateSupportTarget(state: GameState, unit: UnitInstance, gate: GateState, plan: EnemyTurnPlan): number {
  const knownPressure = getKnownPlayerUnitsForEnemy(state).filter((player) => hexDistance(player.coord, gate.coord) <= 5).length * 70;
  const assignedCapturers = getOwnerUnits(state, "Enemy").filter((ally) => {
    if (!getUnitDefinition(ally.type).humanBased || plan.rolesByUnitId[ally.id] !== "CaptureGate") {
      return false;
    }
    const target = chooseEnemyPlannerGateTargetForUnit(state, ally, plan);
    return target ? target.id === gate.id : hexDistance(ally.coord, gate.coord) <= 7;
  }).length;
  const nearbySupport = getOwnerUnits(state, "Enemy").filter((ally) => ally.id !== unit.id && !getUnitDefinition(ally.type).humanBased && hexDistance(ally.coord, gate.coord) <= 4).length;
  return (
    gate.occupation.Enemy * 240 +
    gate.occupation.Player * 170 +
    (gate.owner === "Player" ? 110 : 0) +
    assignedCapturers * 120 +
    knownPressure -
    nearbySupport * 42 -
    hexDistance(unit.coord, gate.coord) * 9
  );
}

function getOpeningGateCapturerSupportScore(state: GameState, coord: UnitInstance["coord"], gate: GateState, plan: EnemyTurnPlan): number {
  return getOwnerUnits(state, "Enemy")
    .filter((ally) => getUnitDefinition(ally.type).humanBased && plan.rolesByUnitId[ally.id] === "CaptureGate")
    .filter((ally) => {
      const target = chooseEnemyPlannerGateTargetForUnit(state, ally, plan);
      return target ? target.id === gate.id : hexDistance(ally.coord, gate.coord) <= 7;
    })
    .reduce((score, ally) => score + Math.max(0, 5 - hexDistance(coord, ally.coord)) * 18, 0);
}

function chooseEnemyPlannerFireSupportMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (unit.type !== "Artillery" && unit.type !== "Anti-Air") {
    return undefined;
  }
  if (getEnemyPlannerAttackTargets(state, unit, plan).length > 0) {
    return undefined;
  }
  const openingCenterPush = chooseEnemyPlannerOpeningCenterSupportMove(state, unit, plan);
  if (openingCenterPush) {
    return openingCenterPush;
  }
  const airCoverageMove = chooseEnemyPlannerAntiAirCoverageMove(state, unit, plan);
  if (airCoverageMove) {
    return airCoverageMove;
  }

  const target = chooseEnemyFireSupportPosition(state, unit);
  const currentDistance = hexDistance(unit.coord, target);
  if (currentDistance <= 1) {
    return undefined;
  }
  const path = findMovementPath(state, unit, target);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0) {
    return undefined;
  }
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (canMoveUnitTo(state, unit, coord) && hexDistance(coord, target) < currentDistance) {
        return coord;
      }
    }
  }
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => hexDistance(coord, target) < currentDistance)
    .sort((first, second) => hexDistance(first, target) - hexDistance(second, target) || hexId(first).localeCompare(hexId(second)))[0];
}

function shouldForceEnemyFireSupportCenterStaging(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): boolean {
  if (
    (unit.type !== "Artillery" && unit.type !== "Anti-Air") ||
    !isHardCenterSupportDoctrineActive(state, plan) ||
    shouldEnemyAttemptRepairRetreat(state, unit) ||
    getEnemyPlannerAttackTargets(state, unit, plan).length > 0
  ) {
    return false;
  }

  const target = getEnemyCenterSupportStagingCoord(state, plan);
  const currentDistance = hexDistance(unit.coord, target);
  return currentDistance > 1 && hexDistance(coord, target) < currentDistance;
}

function chooseEnemyPlannerAntiAirCoverageMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (unit.type !== "Anti-Air") {
    return undefined;
  }

  const threat = chooseEnemyPlannerAntiAirCoverageThreat(state, unit, plan);
  if (!threat) {
    return undefined;
  }

  const currentScore = scoreEnemyAntiAirCoverageCoord(state, unit, unit.coord, threat, plan);
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .map((coord) => ({
      coord,
      score: scoreEnemyAntiAirCoverageCoord(state, unit, coord, threat, plan)
    }))
    .filter((entry) => entry.score > currentScore + 40)
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function chooseEnemyPlannerAntiAirCoverageThreat(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan
): EnemyPlannerPlayerIntel | undefined {
  return plan.playerIntel
    .filter((intel) => getUnitDefinition(intel.unit.type).domain === "Air")
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .filter((intel) => intel.age <= 2 || intel.confidence >= 0.55)
    .sort((first, second) => scoreEnemyPlannerAntiAirThreat(state, unit, second, plan) - scoreEnemyPlannerAntiAirThreat(state, unit, first, plan))[0];
}

function scoreEnemyPlannerAntiAirThreat(state: GameState, unit: UnitInstance, intel: EnemyPlannerPlayerIntel, plan: EnemyTurnPlan): number {
  const distance = hexDistance(unit.coord, intel.predictedCoord);
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, intel.predictedCoord);
  const insideAttackRange = distance <= stats.attackRange ? 180 : 0;
  const outsideSightButReachable = distance > stats.visibilityRange && distance <= stats.attackRange ? 260 : 0;
  const currentVisibilityGap = Math.max(0, distance - stats.visibilityRange) * 70;
  return (
    getUnitInstanceValue(state, intel.unit) * 0.9 +
    getCounterPriorityBonus(unit.type, { ...intel.unit, coord: intel.predictedCoord }) +
    insideAttackRange +
    outsideSightButReachable +
    currentVisibilityGap +
    getEnemyPlannerCombatPressure(state, plan) * 0.08
  ) * intel.confidence;
}

function scoreEnemyAntiAirCoverageCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  threat: EnemyPlannerPlayerIntel,
  plan: EnemyTurnPlan
): number {
  if (isEnemyPlannerOneShotExposed(state, unit, coord, plan)) {
    return -100000;
  }

  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  if (danger >= unit.health * 1.8) {
    return -100000;
  }

  const currentDistance = hexDistance(unit.coord, threat.predictedCoord);
  const distance = hexDistance(coord, threat.predictedCoord);
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, threat.predictedCoord);
  const seesThreat = distance <= stats.visibilityRange;
  const attacksThreat = distance <= stats.attackRange;
  const closes = currentDistance - distance;
  const sightGap = Math.max(0, distance - stats.visibilityRange);
  const attackGap = Math.max(0, distance - stats.attackRange);

  return (
    (seesThreat ? 520 : 0) +
    (attacksThreat ? 170 : 0) +
    Math.max(0, closes) * 90 -
    sightGap * 80 -
    attackGap * 120 +
    Math.max(0, 7 - distance) * 24 +
    getEnemyPlannerSupportScore(state, unit, coord) -
    danger * 8
  ) * threat.confidence;
}

function chooseEnemyPlannerSupplyTruckSupportMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (!isEnemySupplySupportUnit(unit.type) || shouldEnemyAttemptRepairRetreat(state, unit)) {
    return undefined;
  }

  const openingCenterPush = chooseEnemyPlannerOpeningCenterSupportMove(state, unit, plan);
  if (openingCenterPush) {
    return openingCenterPush;
  }

  const currentScore = scoreEnemySupplyTruckSupportCoord(state, unit, unit.coord, plan);
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .map((coord) => ({
      coord,
      score: scoreEnemySupplyTruckSupportCoord(state, unit, coord, plan)
    }))
    .filter((entry) => entry.score > currentScore + 20)
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function chooseEnemyPlannerOpeningCenterSupportMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (
    !isHardCenterSupportDoctrineActive(state, plan) ||
    (unit.type !== "Artillery" && unit.type !== "Anti-Air" && !isEnemySupplySupportUnit(unit.type))
  ) {
    return undefined;
  }

  const target = getEnemyCenterSupportStagingCoord(state, plan);
  const currentDistance = hexDistance(unit.coord, target);
  if (currentDistance <= 1) {
    return undefined;
  }

  const safeProgress = (coord: UnitInstance["coord"]): boolean => {
    if (!canMoveUnitTo(state, unit, coord) || hexDistance(coord, target) >= currentDistance) {
      return false;
    }
    const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
    if (isEnemySupplySupportUnit(unit.type) && danger > 0) {
      return false;
    }
    return danger <= Math.max(0, unit.health - 2) && !isEnemyPlannerOneShotExposed(state, unit, coord, plan);
  };
  const path = findMovementPath(state, unit, target);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0) {
    return undefined;
  }
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (safeProgress(coord)) {
        return coord;
      }
    }
  }

  const safeFallback = getEnemyLegalMoveCoords(state, unit)
    .filter(safeProgress)
    .sort((first, second) => {
      const firstDistance = hexDistance(first, target);
      const secondDistance = hexDistance(second, target);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return firstDistance - secondDistance || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
  if (safeFallback) {
    return safeFallback;
  }

  if (isHardOpeningDoctrineActive(state) && unit.coord.r > target.r + 2) {
    return getEnemyLegalMoveCoords(state, unit)
      .filter((coord) => canMoveUnitTo(state, unit, coord))
      .filter((coord) => hexDistance(coord, target) < currentDistance)
      .filter((coord) => coord.r < unit.coord.r)
      .sort((first, second) => {
        const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
        const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
        return hexDistance(first, target) - hexDistance(second, target) || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
      })[0];
  }

  return undefined;
}

function scoreEnemySupplyTruckSupportCoord(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  const currentDanger = estimatePlayerDangerAtPlanner(state, unit, unit.coord, plan);
  if (isEnemyPlannerOneShotExposed(state, unit, coord, plan)) {
    return -100000;
  }
  const gateFightCommitment = isEnemyGateFightCommitmentPhase(plan.campaignPlan.phase);
  if (danger > 0 && (!gateFightCommitment || danger >= unit.health * 0.42)) {
    return -100000;
  }

  const anchor = chooseEnemySupplyTruckSupportAnchor(state, unit, plan);
  const repairsDamagedAlly =
    isEnemySupplySupportUnit(unit.type) &&
    getOwnerUnits(state, "Enemy").some(
      (ally) =>
        ally.id !== unit.id &&
        !isEnemySupplySupportUnit(ally.type) &&
        getUnitDefinition(ally.type).domain === "Ground" &&
        ally.health < ally.maxHealth &&
        hexDistance(coord, ally.coord) <= SUPPLY_TRUCK_REPAIR_RANGE
    );
  if (
    isEnemySupplySupportUnit(unit.type) &&
    isEnemyBaseOperationPhase(plan.campaignPlan.phase) &&
    getBattlefieldArea(state, coord) === getOwnerEnemyArea(unit.owner) &&
    !repairsDamagedAlly
  ) {
    return -100000;
  }
  const anchorScore = anchor ? Math.max(0, 18 - hexDistance(coord, anchor)) * 12 : 0;
  const anchorDistance = anchor ? hexDistance(coord, anchor) : Number.POSITIVE_INFINITY;
  const supportBandScore =
    anchor && coord.r <= anchor.r && anchorDistance >= 2 && anchorDistance <= SUPPLY_TRUCK_REPAIR_RANGE
      ? 210 - Math.abs(anchorDistance - 3) * 34
      : anchor && anchorDistance > SUPPLY_TRUCK_REPAIR_RANGE
        ? -Math.min(260, (anchorDistance - SUPPLY_TRUCK_REPAIR_RANGE) * 58)
        : 0;
  const overtakePenalty = anchor && coord.r > anchor.r ? 120 + (coord.r - anchor.r) * 28 : 0;
  const unsupportedRetreatPenalty =
    currentDanger <= 0 && anchor && coord.r < unit.coord.r && anchorDistance > 3
      ? 150 + (unit.coord.r - coord.r) * 36
      : 0;
  const allyScore = getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id || isEnemySupplySupportUnit(ally.type) || plan.rolesByUnitId[ally.id] === "Repair") {
      return score;
    }

    const distance = hexDistance(coord, ally.coord);
    const damaged = ally.health < ally.maxHealth;
    const repairCoverage = damaged && distance <= SUPPLY_TRUCK_REPAIR_RANGE
      ? 150 + Math.ceil((ally.maxHealth - ally.health) / Math.max(1, ally.maxHealth) * 120) + getUnitInstanceValue(state, ally) * 0.25
      : 0;
    const mission = plan.rolesByUnitId[ally.id] ?? assignEnemyMission(state, ally);
    const combatSupport =
      mission === "CaptureGate" ||
      mission === "DefendGate" ||
      mission === "CaptureBase" ||
      mission === "ProtectCapturer" ||
      mission === "Escort" ||
      mission === "Siege" ||
      isEnemyGateLockoutCombatMission(mission);
    const supportBand = combatSupport && distance >= 2 && distance <= 4 ? 115 - Math.abs(distance - 3) * 24 : 0;
    return score + repairCoverage + supportBand;
  }, 0);

  const overextensionPenalty = isCoordPastEnemyFrontLine(state, "Enemy", coord) && !ownerControlsBothGates(state, "Enemy") ? 180 : 0;
  const gateFightTempo = gateFightCommitment ? coord.r * 2.5 : 0;
  const dangerPenalty = danger > 0 ? danger * 55 + 180 : 0;
  return (
    anchorScore +
    supportBandScore +
    allyScore +
    scoreEnemyCommandHelicopterDropAnchor(state, unit, coord, plan) +
    coord.r * 1.5 +
    gateFightTempo -
    overextensionPenalty -
    overtakePenalty -
    unsupportedRetreatPenalty -
    dangerPenalty
  );
}

function scoreEnemyCommandHelicopterDropAnchor(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  if (!isEnemyCommandHelicopter(unit.type)) {
    return 0;
  }

  const captureUnitTypes = ENEMY_CAPTURE_UNIT_TYPES.filter((unitType) => (state.enemyEconomy.inventory[unitType] ?? 0) > 0);
  if (!captureUnitTypes.length) {
    return 0;
  }

  const futureAnchor: UnitInstance = {
    ...unit,
    coord: { ...coord },
    placedDay: Math.max(0, state.day - 1),
    hasMovedThisDay: false,
    movementSpentThisDay: 0,
    hasProvidedPlacementThisDay: false
  };
  const targets = getEnemyCommandHelicopterDropTargets(state, plan);
  return targets.reduce((best, target) => {
    const unitType = captureUnitTypes.find((candidate) => canSupplyTruckProvidePlacementAt(state, futureAnchor, target.coord, candidate));
    if (!unitType) {
      return best;
    }

    const distance = hexDistance(coord, target.coord);
    const exactDrop = distance === 1 ? 640 : distance === 2 ? 210 : 0;
    const progress = Math.max(0, hexDistance(unit.coord, target.coord) - distance) * 34;
    return Math.max(best, target.priority + exactDrop + progress - distance * 18);
  }, 0);
}

function getEnemyCommandHelicopterDropTargets(state: GameState, plan: EnemyTurnPlan): Array<{ coord: UnitInstance["coord"]; priority: number }> {
  const targets: Array<{ coord: UnitInstance["coord"]; priority: number }> = [];
  for (const gate of state.gates ?? []) {
    if (gate.owner === "Enemy") {
      continue;
    }
    const pressure = plan.strategicSnapshot.gateCaptureOpportunity[gate.id] ?? 0;
    const occupation = gate.occupation.Enemy * 120 + gate.occupation.Player * 150;
    targets.push({
      coord: gate.coord,
      priority: 180 + plan.strategicSnapshot.gateUrgency * 0.42 + pressure * 0.5 + occupation
    });
  }

  if (ownerControlsBothGates(state, "Enemy")) {
    targets.push({
      coord: state.bases.Player,
      priority: 240 + plan.strategicSnapshot.baseAttackUrgency * 0.55 + plan.strategicSnapshot.playerBaseVulnerability * 0.32
    });
  }

  return targets.sort((first, second) => second.priority - first.priority);
}

function chooseEnemySupplyTruckSupportAnchor(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const damagedAlly = getOwnerUnits(state, "Enemy")
    .filter((ally) => ally.id !== unit.id && !isEnemySupplySupportUnit(ally.type) && getUnitDefinition(ally.type).domain === "Ground" && ally.health < ally.maxHealth && plan.rolesByUnitId[ally.id] !== "Repair")
    .sort((first, second) => scoreEnemySupplyTruckAnchorUnit(state, second, plan) - scoreEnemySupplyTruckAnchorUnit(state, first, plan))[0];
  if (damagedAlly) {
    return damagedAlly.coord;
  }

  const combatAlly = getOwnerUnits(state, "Enemy")
    .filter((ally) => ally.id !== unit.id && !isEnemySupplySupportUnit(ally.type) && plan.rolesByUnitId[ally.id] !== "Repair")
    .sort((first, second) => scoreEnemySupplyTruckAnchorUnit(state, second, plan) - scoreEnemySupplyTruckAnchorUnit(state, first, plan))[0];
  if (combatAlly) {
    return combatAlly.coord;
  }

  const gate = chooseGateObjective(state, "Enemy", unit.coord, unit, plan);
  return gate?.coord ?? state.bases.Player;
}

function scoreEnemySupplyTruckAnchorUnit(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): number {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const damaged = unit.health < unit.maxHealth ? 180 + getUnitInstanceValue(state, unit) * 0.45 : 0;
  const combat =
    mission === "CaptureGate" ||
    mission === "DefendGate" ||
    mission === "CaptureBase" ||
    mission === "ProtectCapturer" ||
    mission === "Escort" ||
    mission === "Siege" ||
    isEnemyGateLockoutCombatMission(mission)
      ? 120
      : 0;
  const forward = Math.max(0, unit.coord.r - state.bases.Enemy.r) * 4;
  return damaged + combat + forward + getUnitInstanceValue(state, unit) * 0.08;
}

function chooseEnemyPlannerGateTargetForUnit(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): GateState | undefined {
  const openingGateTargetLastDay = state.difficulty === "Hard" ? 16 : 12;
  if (state.difficulty === "Hard" && state.day <= openingGateTargetLastDay && (state.gates ?? []).some((gate) => gate.occupation.Player > 0 || gate.occupation.Enemy > 0)) {
    const winningGate = (state.gates ?? [])
      .filter((gate) => gate.owner !== "Enemy" && gate.occupation.Enemy > 0)
      .sort((first, second) => second.occupation.Enemy - first.occupation.Enemy || scoreOpeningGateFallback(state, second) - scoreOpeningGateFallback(state, first))[0];
    if (winningGate) {
      return winningGate;
    }
  }
  const campaignGate = getEnemyCampaignAssignedGateForUnit(state, unit, plan);
  if (campaignGate) {
    return campaignGate;
  }
  const force = plan.taskForces.find(
    (taskForce) =>
      (taskForce.capturerId === unit.id || taskForce.members.includes(unit.id)) &&
      (taskForce.id === "WestGateForce" || taskForce.id === "EastGateForce")
  );
  const assignedGate = force ? (state.gates ?? []).find((gate) => sameHex(gate.coord, force.objectiveCoord)) : undefined;
  if (
    assignedGate &&
    isHardOpeningGateRace(state) &&
    unit.type === "Infantry" &&
    plan.rolesByUnitId[unit.id] === "CaptureGate" &&
    assignedGate.owner !== "Enemy" &&
    (state.gates ?? []).every((gate) => gate.occupation.Player <= 0 && gate.occupation.Enemy <= 0)
  ) {
    return assignedGate;
  }
  if (state.day <= openingGateTargetLastDay) {
    const openingGate = (state.gates ?? [])
      .filter((gate) => gate.owner !== "Enemy")
      .sort((first, second) => scoreOpeningGateFallback(state, second) - scoreOpeningGateFallback(state, first))[0];
    const overrideMargin =
      assignedGate && (assignedGate.occupation.Player > 0 || openingGate?.occupation.Enemy)
        ? 20
        : 120;
    if (openingGate && (!assignedGate || scoreOpeningGateFallback(state, openingGate) > scoreOpeningGateFallback(state, assignedGate) + overrideMargin)) {
      return openingGate;
    }
  }
  if (assignedGate) {
    return assignedGate;
  }
  return chooseEnemyGateRoleTarget(state, "CaptureGate") ?? chooseGateObjective(state, "Enemy", unit.coord, unit, plan);
}

function chooseEnemyPlannerOpeningPatrolMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  const mission = plan.rolesByUnitId[unit.id];
  if (state.day > 10) {
    return undefined;
  }
  if (!isReconUnit(unit.type) && !isPatrolCapableUnit(unit.type)) {
    return undefined;
  }
  const west = (state.gates ?? []).find((gate) => gate.id === "West");
  const east = (state.gates ?? []).find((gate) => gate.id === "East");
  const center = state.bases.Enemy.q;
  const laneTarget =
    mission === "PatrolWest"
      ? getEnemyOpeningScoutTarget(state, "West", unit, plan)
      : mission === "PatrolEast"
        ? getEnemyOpeningScoutTarget(state, "East", unit, plan)
        : unit.coord.q <= center
          ? west ? getEnemyOpeningScoutTarget(state, "West", unit, plan) : undefined
          : east ? getEnemyOpeningScoutTarget(state, "East", unit, plan) : undefined;
  const target = laneTarget ?? chooseEnemyOperationalTarget(state, unit);
  const isLaneCoord = (coord: UnitInstance["coord"]): boolean =>
    mission === "PatrolWest" ? coord.q <= center : mission === "PatrolEast" ? coord.q >= center : true;
  const revealScore = (coord: UnitInstance["coord"]): number => getEnemyScoutFogRevealScore(state, unit, coord);
  if (hexDistance(unit.coord, target) <= 2) {
    return undefined;
  }
  const path = findMovementPath(state, unit, target);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0) {
    return undefined;
  }
  const legalLaneMoves = (): UnitInstance["coord"][] =>
    getEnemyLegalMoveCoords(state, unit)
      .filter(isLaneCoord)
      .filter((coord) => !isGateHex(state, coord) || !isHardOpeningIfvGateOccupancyForbidden(state, unit));
  const patrolGate =
    mission === "PatrolWest"
      ? west
      : mission === "PatrolEast"
        ? east
        : unit.coord.q <= center
          ? west
          : east;
  if (state.difficulty === "Hard" && state.day <= 7 && patrolGate && hexDistance(unit.coord, patrolGate.coord) <= 7 && hexDistance(unit.coord, patrolGate.coord) > 2) {
    const gateStandoffMove = legalLaneMoves()
      .filter((coord) => !sameHex(coord, patrolGate.coord))
      .filter((coord) => coord.r <= patrolGate.coord.r - 2)
      .filter((coord) => hexDistance(coord, patrolGate.coord) <= 2)
      .sort((first, second) => {
        const missionForUnit = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
        const firstPenalty = getEnemyParallelAdvancePenalty(state, unit, first, missionForUnit, plan, reservedDestinations);
        const secondPenalty = getEnemyParallelAdvancePenalty(state, unit, second, missionForUnit, plan, reservedDestinations);
        return (
          firstPenalty - secondPenalty ||
          hexDistance(first, patrolGate.coord) - hexDistance(second, patrolGate.coord) ||
          revealScore(second) - revealScore(first) ||
          hexId(first).localeCompare(hexId(second))
        );
      })[0];
    if (gateStandoffMove) {
      return gateStandoffMove;
    }
  }
  if (state.difficulty === "Hard" && state.day <= 7 && unit.coord.r < target.r) {
    const currentDistance = hexDistance(unit.coord, target);
    const directProgressMove = legalLaneMoves()
      .filter((coord) => coord.r > unit.coord.r && hexDistance(coord, target) < currentDistance)
      .sort((first, second) => {
        const firstDistance = hexDistance(first, target);
        const secondDistance = hexDistance(second, target);
        const firstReveal = revealScore(first);
        const secondReveal = revealScore(second);
        const firstRowProgress = first.r - unit.coord.r;
        const secondRowProgress = second.r - unit.coord.r;
        const firstSpacingPenalty = getEnemyParallelAdvancePenalty(state, unit, first, plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit), plan, reservedDestinations);
        const secondSpacingPenalty = getEnemyParallelAdvancePenalty(state, unit, second, plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit), plan, reservedDestinations);
        return (
          firstSpacingPenalty - secondSpacingPenalty ||
          secondReveal - firstReveal ||
          firstDistance - secondDistance ||
          secondRowProgress - firstRowProgress ||
          hexId(first).localeCompare(hexId(second))
        );
      })[0];
    if (directProgressMove) {
      return directProgressMove;
    }
  }
  if (!path?.length) {
    return legalLaneMoves()
      .sort((first, second) => {
        const missionForUnit = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
        return (
          getEnemyParallelAdvancePenalty(state, unit, first, missionForUnit, plan, reservedDestinations) -
            getEnemyParallelAdvancePenalty(state, unit, second, missionForUnit, plan, reservedDestinations) ||
          revealScore(second) - revealScore(first) ||
          hexDistance(first, target) - hexDistance(second, target) ||
          hexId(first).localeCompare(hexId(second))
        );
      })[0];
  }
  const pathMove = Array.from({ length: Math.min(path.length, remainingMovement) }, (_item, index) => path[index])
    .filter((coord) =>
      isLaneCoord(coord) &&
      canMoveUnitTo(state, unit, coord) &&
      getEnemyParallelAdvancePenalty(state, unit, coord, plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit), plan, reservedDestinations) === 0
    )
    .sort((first, second) =>
      revealScore(second) - revealScore(first) ||
      hexDistance(first, target) - hexDistance(second, target) ||
      hexId(first).localeCompare(hexId(second))
    )[0];
  if (pathMove) {
    return pathMove;
  }
  return legalLaneMoves()
    .sort((first, second) => {
      const missionForUnit = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
      return (
        getEnemyParallelAdvancePenalty(state, unit, first, missionForUnit, plan, reservedDestinations) -
          getEnemyParallelAdvancePenalty(state, unit, second, missionForUnit, plan, reservedDestinations) ||
        revealScore(second) - revealScore(first) ||
        hexDistance(first, target) - hexDistance(second, target) ||
        hexId(first).localeCompare(hexId(second))
      );
    })[0];
}

function getEnemyOpeningScoutTarget(
  state: GameState,
  lane: GateState["id"],
  unit: UnitInstance,
  plan: EnemyTurnPlan
): UnitInstance["coord"] {
  if (!isHardOpeningDoctrineActive(state) || (unit.type !== "IFV" && unit.type !== "Attack Heli")) {
    return getEnemyPatrolCoord(state, lane, unit);
  }

  const gate = (state.gates ?? []).find((candidate) => candidate.id === lane);
  const gatePatrol = getEnemyPatrolCoord(state, lane, unit);
  if (!gate || hexDistance(unit.coord, gate.coord) > 3) {
    return gatePatrol;
  }

  const frontRows = getFrontLineRows(state);
  const centerQ = state.bases.Enemy.q;
  const sideQ = lane === "West"
    ? Math.max(0, Math.floor((gate.coord.q + centerQ) / 2) - 2)
    : Math.min(state.map.width - 1, Math.ceil((gate.coord.q + centerQ) / 2) + 2);
  const nmlEntryRow = Math.max(frontRows.enemyLineRow + 1, gate.coord.r);
  const nmlCenterRow = Math.floor((frontRows.enemyLineRow + frontRows.playerLineRow) / 2);
  const desiredRow = hexDistance(unit.coord, gate.coord) <= 2 || plan.rolesByUnitId[unit.id] === "Scout"
    ? nmlCenterRow
    : nmlEntryRow;
  return getNearestPassableCoord(state, {
    q: sideQ,
    r: Math.max(frontRows.enemyLineRow, Math.min(frontRows.playerLineRow - 1, desiredRow))
  });
}

function chooseEnemyPlannerRetreatMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>
): UnitInstance["coord"] | undefined {
  const currentDanger = estimatePlayerDangerAtPlanner(state, unit, unit.coord, plan);
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => {
      const key = getEnemyDestinationReservationKey(unit.type, coord);
      return !reservedDestinations[key] || reservedDestinations[key] === unit.id;
    })
    .map((coord) => {
      const repairDistance = getNearestEnemyRepairDistance(state, coord, unit.type);
      const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
      const rowProgress = unit.coord.r - coord.r;
      const repairProgress = getNearestEnemyRepairDistance(state, unit.coord, unit.type) - repairDistance;
      return {
        coord,
        score: (currentDanger - danger) * 3 + Math.max(0, repairProgress) * 70 + rowProgress * 18 - repairDistance * 16 + getEnemyPlannerSupportScore(state, unit, coord)
      };
    })
    .filter((entry) => getNearestEnemyRepairDistance(state, entry.coord, unit.type) < getNearestEnemyRepairDistance(state, unit.coord, unit.type) || entry.score > 120)
    .sort((first, second) => second.score - first.score || getNearestEnemyRepairDistance(state, first.coord, unit.type) - getNearestEnemyRepairDistance(state, second.coord, unit.type))[0]?.coord;
}

function enumerateForcedEnemyCompoundActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyCompoundAction[] {
  const imperative = plan.objectiveImperatives.find((entry) => entry.unitId === unit.id);
  if (!imperative) {
    return [];
  }

  if (imperative.actionKind === "Hold") {
    return [createEnemyCompoundAction(state, unit, plan, "Hold", {}, reservedDestinations, reservedExpectedDamage)];
  }

  if (imperative.targetId) {
    const target = state.units.find((candidate) => candidate.id === imperative.targetId && candidate.owner === "Player");
    if (target) {
      if (!isEnemyFireSupportAttackIntelAuthorized(state, unit, target, plan)) {
        return [];
      }
      const outcome = getExpectedAttackOutcome(state, unit, target);
      const direct = createEnemyCompoundAction(
        state,
        unit,
        plan,
        hexDistance(unit.coord, target.coord) <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord).attackRange ? "Attack" : "MoveThenAttack",
        {
          moveTo: imperative.actionKind === "MoveThenAttack" ? chooseEnemyPlannerAttackEnablingMove(state, unit, target, plan) : undefined,
          attackAt: target.coord,
          targetId: target.id,
          targetType: target.type,
          expectedOutcome: outcome
        },
        reservedDestinations,
        reservedExpectedDamage
      );
      return [direct];
    }
  }

  if (imperative.targetCoord) {
    return [createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: imperative.targetCoord }, reservedDestinations, reservedExpectedDamage)];
  }
  return [];
}

function enumerateHardObjectiveEnemyCompoundActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyCompoundAction[] {
  if (!getUnitDefinition(unit.type).humanBased) {
    return [];
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission === "CaptureGate" || mission === "DefendGate") {
    const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    if (!gate) {
      return [];
    }

    const blocker = chooseEnemyVisibleObjectiveBlocker(state, unit, gate.coord, plan);
    const blockerAction = blocker ? createEnemyObjectiveBlockerAction(state, unit, blocker, plan, reservedDestinations, reservedExpectedDamage) : undefined;
    if (blockerAction) {
      return [blockerAction];
    }

    if (sameHex(unit.coord, gate.coord)) {
      return [createEnemyCompoundAction(state, unit, plan, "Hold", {}, reservedDestinations, reservedExpectedDamage)];
    }

    const moveTo = chooseEnemyHardObjectiveMove(state, unit, gate.coord, plan, reservedDestinations);
    return moveTo ? [createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, reservedDestinations, reservedExpectedDamage)] : [];
  }

  if (mission === "CaptureBase" || mission === "DefendBase") {
    const targetCoord = mission === "CaptureBase" ? state.bases.Player : state.bases.Enemy;
    const blocker = mission === "CaptureBase"
      ? chooseEnemyVisiblePlayerBaseTileBlocker(state, unit, plan)
      : chooseEnemyVisibleObjectiveBlocker(state, unit, targetCoord, plan);
    const blockerAction = blocker ? createEnemyObjectiveBlockerAction(state, unit, blocker, plan, reservedDestinations, reservedExpectedDamage) : undefined;
    if (blockerAction) {
      return [blockerAction];
    }

    if (sameHex(unit.coord, targetCoord)) {
      return [createEnemyCompoundAction(state, unit, plan, "Hold", {}, reservedDestinations, reservedExpectedDamage)];
    }

    const moveTo = chooseEnemyHardObjectiveMove(state, unit, targetCoord, plan, reservedDestinations);
    return moveTo ? [createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, reservedDestinations, reservedExpectedDamage)] : [];
  }

  return [];
}

function chooseEnemyVisiblePlayerBaseTileBlocker(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan
): UnitInstance | undefined {
  const visibleTargetIds = getEnemyPlannerVisibleTargetIds(plan);
  return getOwnerUnits(state, "Player")
    .filter((target) => visibleTargetIds.has(target.id))
    .filter((target) => sameHex(target.coord, state.bases.Player) && canUnitTargetUnit(unit.type, target.type))
    .sort((first, second) => scoreEnemyObjectiveBlockerTarget(state, unit, second, plan) - scoreEnemyObjectiveBlockerTarget(state, unit, first, plan))[0];
}

function chooseEnemyPlannerGateObjectiveForUnit(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan, mission: EnemyMission): GateState | undefined {
  if (mission === "DefendGate") {
    const imperativeGate = plan.objectiveImperatives
      .filter((imperative) => imperative.unitId === unit.id && imperative.id.startsWith("deny-player-gate-"))
      .map((imperative) => (state.gates ?? []).find((gate) => imperative.targetCoord && sameHex(gate.coord, imperative.targetCoord)))
      .find((gate): gate is GateState => Boolean(gate));
    if (imperativeGate) {
      return imperativeGate;
    }

    return (
      chooseEnemyGateRoleTarget(state, "DefendGate") ??
      chooseEnemyGateDefenseObjective(state, unit.coord) ??
      (state.gates ?? [])
        .filter((gate) => gate.owner === "Enemy")
        .sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord))[0]
    );
  }

  return chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
}

function chooseEnemyVisibleObjectiveBlocker(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): UnitInstance | undefined {
  const visibleTargetIds = getEnemyPlannerVisibleTargetIds(plan);
  return getOwnerUnits(state, "Player")
    .filter((target) => visibleTargetIds.has(target.id))
    .filter((target) => isEnemyTargetNearObjective(state, target, coord) && canUnitTargetUnit(unit.type, target.type))
    .sort((first, second) => scoreEnemyObjectiveBlockerTarget(state, unit, second, plan) - scoreEnemyObjectiveBlockerTarget(state, unit, first, plan))[0];
}

function scoreEnemyObjectiveBlockerTarget(state: GameState, unit: UnitInstance, target: UnitInstance, plan?: EnemyTurnPlan): number {
  const outcome = getExpectedAttackOutcome(state, unit, target);
  const usefulDamage = getUsefulExpectedDamage(target, outcome.expectedDamage);
  const capturer = getUnitDefinition(target.type).humanBased ? 260 : 0;
  return getEnemyObjectiveBlockerTargetPriority(state, target, plan) + outcome.killProbability * 420 + usefulDamage * 18 + getUnitInstanceValue(state, target) * 0.5 + capturer;
}

function scoreEnemyObjectiveBlockerReservation(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance,
  action: EnemyCompoundAction,
  reserved: { expectedDamage: number; killProbability: number; unitIds: string[] } | undefined,
  plan: EnemyTurnPlan
): number {
  if (!action.expectedOutcome || !isEnemyObjectiveBlockerTarget(state, target, plan)) {
    return 0;
  }

  const alreadyClearing = isEnemyReservedDamageLikelyClearingTarget(target, reserved);
  if (alreadyClearing) {
    return -520;
  }

  const combinedExpectedDamage = (reserved?.expectedDamage ?? 0) + action.expectedOutcome.expectedDamage;
  const combinedKillProbability = 1 - (1 - (reserved?.killProbability ?? 0)) * (1 - action.expectedOutcome.killProbability);
  const completesClear = combinedExpectedDamage >= target.health || combinedKillProbability >= 0.82;
  const remainingDamageNeed = Math.max(0, target.health - (reserved?.expectedDamage ?? 0));
  const usefulDamage = Math.min(remainingDamageNeed, action.expectedOutcome.expectedDamage);
  const baseTile = sameHex(target.coord, state.bases.Player) || sameHex(target.coord, state.bases.Enemy);
  const gateTile = (state.gates ?? []).some((gate) => sameHex(gate.coord, target.coord));
  const gateTheatre = gateTile || (state.gates ?? []).some((gate) => getEnemyGateTheatreTargetPriority(state, target, gate) > 0);
  const phaseWeight = baseTile || plan.strategicSnapshot.strategicPhase === "BaseAssault" || plan.strategicSnapshot.strategicPhase === "BaseHold" ? 1.25 : gateTheatre ? 1.08 : 1;
  const imperativeBonus = plan.objectiveImperatives.some((imperative) => imperative.targetId === target.id) ? 420 : 0;
  return (
    280 +
    imperativeBonus +
    usefulDamage * 42 +
    action.expectedOutcome.killProbability * 360 +
    (completesClear ? 760 : 0)
  ) * phaseWeight;
}

function isEnemyObjectiveBlockerTarget(state: GameState, target: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (target.owner !== "Player") {
    return false;
  }
  if (plan.objectiveImperatives.some((imperative) => imperative.targetId === target.id && imperative.reason.includes("blocker"))) {
    return true;
  }
  if (getEnemyObjectiveBlockerTargetPriority(state, target, plan) > 0) {
    return true;
  }
  if (!isEnemyObjectiveTileBlockedByTarget(state, target)) {
    return false;
  }
  return canEnemyHumanEnterObjectiveAfterBlockerClear(state, target.coord, target);
}

function getEnemyObjectiveBlockerTargetPriority(state: GameState, target: UnitInstance, plan?: EnemyTurnPlan): number {
  if (target.owner !== "Player") {
    return 0;
  }

  if (sameHex(target.coord, state.bases.Player) && (ownerControlsBothGates(state, "Enemy") || state.baseOccupation.Player > 0)) {
    const baseClock = state.baseOccupation.Player > 0 ? 620 + state.baseOccupation.Player * 260 : 0;
    const packageNeed = plan?.campaignPlan.baseAssaultPackage.clearBaseTileTargetId === target.id ? 540 : 0;
    return 2_600 + baseClock + packageNeed;
  }

  const gate = (state.gates ?? []).find((candidate) => sameHex(candidate.coord, target.coord));
  const theatreGate = gate ?? (state.gates ?? [])
    .filter((candidate) => hexDistance(target.coord, candidate.coord) <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS)
    .sort((first, second) => hexDistance(target.coord, first.coord) - hexDistance(target.coord, second.coord))[0];
  if (!theatreGate) {
    return 0;
  }

  const aiNeedsGate =
    theatreGate.owner !== "Enemy" ||
    theatreGate.occupation.Player > 0 ||
    theatreGate.occupation.Enemy > 0 ||
    plan?.campaignPlan.mainEffortGateId === theatreGate.id ||
    plan?.campaignPlan.secondaryGateId === theatreGate.id;
  if (!aiNeedsGate) {
    return 0;
  }

  const theatreDistance = hexDistance(target.coord, theatreGate.coord);
  const theatreTarget = getEnemyGateTheatreTargetPriority(state, target, theatreGate);
  if (!gate && theatreDistance > ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS && theatreTarget <= 0) {
    return 0;
  }

  const ownership = theatreGate.owner !== "Enemy" ? 1_200 : 520;
  const captureClock = theatreGate.occupation.Player * 340 + theatreGate.occupation.Enemy * 220;
  const lockout = getEnemyGateLockoutOpportunityScore(state, theatreGate, plan?.playerIntel).total * 0.42;
  const humanBlocker = getUnitDefinition(target.type).humanBased ? 260 : 0;
  const directBlocker = gate ? 760 : 0;
  return ownership + captureClock + lockout + humanBlocker + directBlocker + theatreTarget;
}

function isEnemyObjectiveTileBlockedByTarget(state: GameState, target: UnitInstance): boolean {
  if (sameHex(target.coord, state.bases.Player)) {
    return ownerControlsBothGates(state, "Enemy") || state.baseOccupation.Player > 0;
  }
  if (sameHex(target.coord, state.bases.Enemy)) {
    return state.baseOccupation.Enemy > 0 || getUnitDefinition(target.type).humanBased;
  }
  return (state.gates ?? []).some((gate) => sameHex(gate.coord, target.coord));
}

function canEnemyHumanEnterObjectiveAfterBlockerClear(state: GameState, coord: UnitInstance["coord"], blocker: UnitInstance): boolean {
  const otherOccupier = state.units.some((unit) => unit.id !== blocker.id && sameHex(unit.coord, coord));
  if (otherOccupier) {
    return false;
  }
  return getOwnerUnits(state, "Enemy").some((unit) => {
    if (!getUnitDefinition(unit.type).humanBased || unit.placedDay === state.day || unit.hasMovedThisDay) {
      return false;
    }
    return hexDistance(unit.coord, coord) <= getRemainingMovementPoints(state, unit);
  });
}

function isEnemyReservedDamageLikelyClearingTarget(
  target: UnitInstance,
  reserved: { expectedDamage: number; killProbability: number; unitIds: string[] } | undefined
): boolean {
  return Boolean(reserved && (reserved.expectedDamage >= target.health || reserved.killProbability >= 0.82));
}

function createEnemyObjectiveBlockerAction(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyCompoundAction | undefined {
  const outcome = getExpectedAttackOutcome(state, unit, target);
  const attackRange = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord).attackRange;
  if (hexDistance(unit.coord, target.coord) <= attackRange) {
    return createEnemyCompoundAction(
      state,
      unit,
      plan,
      "Attack",
      { attackAt: target.coord, targetId: target.id, targetType: target.type, expectedOutcome: outcome },
      reservedDestinations,
      reservedExpectedDamage
    );
  }

  if (isMoveAttackExclusiveUnit(unit.type)) {
    return undefined;
  }

  const moveTo = chooseEnemyPlannerAttackEnablingMove(state, unit, target, plan);
  if (!moveTo) {
    return undefined;
  }

  return createEnemyCompoundAction(
    state,
    unit,
    plan,
    "MoveThenAttack",
    { moveTo, attackAt: target.coord, targetId: target.id, targetType: target.type, expectedOutcome: outcome },
    reservedDestinations,
    reservedExpectedDamage
  );
}

function chooseEnemyHardObjectiveMove(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>
): UnitInstance["coord"] | undefined {
  const currentDistance = hexDistance(unit.coord, target);
  const remainingMovement = getRemainingMovementPoints(state, unit);
  if (remainingMovement <= 0) {
    return undefined;
  }

  const targetGate = (state.gates ?? []).find((gate) => gate.owner !== "Enemy" && sameHex(gate.coord, target));
  const reservedForOther = (coord: UnitInstance["coord"]): boolean => {
    const key = getEnemyDestinationReservationKey(unit.type, coord);
    return Boolean(reservedDestinations[key] && reservedDestinations[key] !== unit.id);
  };
  const safeObjectiveMove = (coord: UnitInstance["coord"]): boolean =>
    !targetGate || !sameHex(coord, targetGate.coord) || !getUnitDefinition(unit.type).humanBased || isGateSafeForRecapture(state, targetGate, unit, plan);
  const path = findMovementPath(state, unit, target);
  if (path?.length) {
    for (let steps = Math.min(path.length, remainingMovement); steps >= 1; steps -= 1) {
      const coord = path[steps - 1];
      if (!reservedForOther(coord) && canMoveUnitTo(state, unit, coord) && hexDistance(coord, target) < currentDistance && safeObjectiveMove(coord)) {
        return coord;
      }
    }
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => !reservedForOther(coord))
    .filter((coord) => hexDistance(coord, target) < currentDistance)
    .filter(safeObjectiveMove)
    .sort((first, second) => {
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return hexDistance(first, target) - hexDistance(second, target) || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
}

function chooseEnemyPlannerAttackEnablingMove(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance,
  plan: EnemyTurnPlan
): UnitInstance["coord"] | undefined {
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => hexDistance(coord, target.coord) <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, target.coord).attackRange)
    .sort((first, second) => hexDistance(first, target.coord) - hexDistance(second, target.coord) || hexId(first).localeCompare(hexId(second)))
    .slice(0, Math.max(8, ENEMY_PLANNER_SEARCH_MOVE_CAP * 3))
    .sort((first, second) => scoreEnemyPlannerPosition(state, unit, second, plan, {}, {}) - scoreEnemyPlannerPosition(state, unit, first, plan, {}, {}))[0];
}

function getEnemyPlannerCandidateMoveCoords(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>
): UnitInstance["coord"][] {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const center = state.bases.Enemy.q;
  const isOpeningPatrolLaneCoord = (coord: UnitInstance["coord"]): boolean => {
    if (state.day > 10) {
      return true;
    }
    if (mission === "PatrolWest") {
      return coord.q <= center;
    }
    if (mission === "PatrolEast") {
      return coord.q >= center;
    }
    return true;
  };
  const target = chooseEnemyPlannerOperationalTarget(state, unit, plan);
  const path = findMovementPath(state, unit, target) ?? [];
  const pathStep = path.length ? path[Math.min(path.length, Math.max(1, getRemainingMovementPoints(state, unit))) - 1] : undefined;
  const legalMoves = getEnemyLegalMoveCoords(state, unit);
  const currentDistance = hexDistance(unit.coord, target);
  const moveCandidateCap = getEnemyPlannerMoveCandidateCap(state, unit, plan);
  const cheapPoolMultiplier = moveCandidateCap > ENEMY_PLANNER_SEARCH_MOVE_CAP ? 7 : 4;
  const cheapMovePool = [...legalMoves]
    .sort((first, second) => {
      const firstProgress = currentDistance - hexDistance(first, target);
      const secondProgress = currentDistance - hexDistance(second, target);
      return secondProgress - firstProgress || hexDistance(first, target) - hexDistance(second, target) || hexId(first).localeCompare(hexId(second));
    })
    .slice(0, Math.max(12, ENEMY_PLANNER_SEARCH_MOVE_CAP * cheapPoolMultiplier));
  const scored = cheapMovePool
    .map((coord) => ({
      coord,
      score: scoreEnemyPlannerPosition(state, unit, coord, plan, reservedDestinations, {})
    }))
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))
    .slice(0, moveCandidateCap)
    .map((entry) => entry.coord);
  const keyCoords = [
    pathStep,
    target,
    shouldEnemyRetreatForRepair(state, unit) ? getNearestEnemyRepairCoord(state, unit.coord, unit.type) : undefined,
    ...plan.taskForces
      .filter((taskForce) => taskForce.members.includes(unit.id))
      .map((taskForce) => taskForce.objectiveCoord)
  ].filter((coord): coord is UnitInstance["coord"] => Boolean(coord));
  const aggressiveStageCoords = getEnemyPlannerAggressiveStageMoveCoords(state, unit, plan, reservedDestinations);
  const candidates = [...keyCoords, ...aggressiveStageCoords, ...scored]
    .filter((coord) => !sameHex(coord, unit.coord))
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => {
      const key = getEnemyDestinationReservationKey(unit.type, coord);
      return !reservedDestinations[key] || reservedDestinations[key] === unit.id;
    });
  const laneCandidates = candidates.filter(isOpeningPatrolLaneCoord);
  return uniqueCoords(laneCandidates.length ? laneCandidates : candidates).slice(0, moveCandidateCap);
}

function getEnemyPlannerMoveCandidateCap(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): number {
  if (!shouldEnemyUseTempoMoveSearch(state, unit, plan)) {
    return ENEMY_PLANNER_SEARCH_MOVE_CAP;
  }
  return getEnemyDynamicMoveSearchCap(state, plan);
}

function getEnemyDynamicMoveSearchCap(state: GameState, plan?: EnemyTurnPlan): number {
  const initiative = plan?.strategicSnapshot?.initiativePressure ?? 0;
  const phase = plan?.campaignPlan?.phase ?? plan?.strategicSnapshot?.strategicPhase;

  let cap = ENEMY_PLANNER_SEARCH_MOVE_CAP;

  if (initiative >= 70) cap += 1;
  if (initiative >= 140) cap += 1;
  if (
    phase === "Recovery" ||
    phase === "GateLockoutCombat" ||
    phase === "OpeningGateRace"
  ) {
    cap += 1;
  }

  return Math.min(8, cap);
}

function shouldEnemyUseTempoMoveSearch(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (state.difficulty !== "Hard" || unit.owner !== "Enemy" || unit.health / Math.max(1, unit.maxHealth) < 0.68) {
    return false;
  }
  if (!isEnemyRiskBudgetCombatUnit(unit) && !getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission === "Repair" || mission === "DefendBase" || mission === "BaseSentry") {
    return false;
  }
  return (
    getEnemyPlannerCombatPressure(state, plan) >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD ||
    plan.strategicSnapshot.strategicPhase === "GateLockoutCombat" ||
    plan.strategicSnapshot.strategicPhase === "Recovery" ||
    (state.gates ?? []).some((gate) => gate.owner !== "Enemy" || gate.occupation.Player > 0)
  );
}

function getEnemyPlannerAggressiveStageMoveCoords(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>
): UnitInstance["coord"][] {
  if (!shouldEnemySeekAggressiveStage(state, unit, plan)) {
    return [];
  }

  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit), plan);
  const currentDistance = hexDistance(unit.coord, objective);
  const reservedForOther = (coord: UnitInstance["coord"]): boolean => {
    const key = getEnemyDestinationReservationKey(unit.type, coord);
    return Boolean(reservedDestinations[key] && reservedDestinations[key] !== unit.id);
  };

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => !sameHex(coord, unit.coord))
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => !reservedForOther(coord))
    .map((coord) => ({
      coord,
      score: scoreEnemyAggressiveStageCoord(state, unit, coord, plan, objective, currentDistance)
    }))
    .filter((entry) => entry.score > 0)
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))
    .slice(0, Math.max(2, getEnemyDynamicMoveSearchCap(state, plan) - ENEMY_PLANNER_SEARCH_MOVE_CAP + 1))
    .map((entry) => entry.coord);
}

function shouldEnemySeekAggressiveStage(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (state.difficulty !== "Hard" || unit.owner !== "Enemy") {
    return false;
  }
  if (unit.health / Math.max(1, unit.maxHealth) < 0.55) {
    return false;
  }
  if (isEnemySupplySupportUnit(unit.type) || getUnitDefinition(unit.type).cannotAttack) {
    return false;
  }
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission === "Repair" || mission === "BaseSentry" || mission === "DefendBase") {
    return false;
  }
  if (state.baseOccupation.Enemy > 0 || plan.strategicSnapshot.strategicPhase === "BaseDefenseEmergency") {
    return false;
  }
  return (plan.strategicSnapshot.initiativePressure ?? 0) >= 70;
}

function scoreEnemyAggressiveStageCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  objective: UnitInstance["coord"],
  currentDistance: number
): number {
  if (isEnemyPlannerOneShotExposed(state, unit, coord, plan)) {
    return Number.NEGATIVE_INFINITY;
  }

  const action = createUnevaluatedEnemyCompoundAction(unit, plan, "Move", { moveTo: coord });
  const finalReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, coord, plan, action);
  const currentReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, unit.coord, plan);
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  const health = Math.max(1, unit.health);
  const definition = getUnitDefinition(unit.type);
  const supportScore = getEnemyPlannerSupportScore(state, unit, coord);
  const nextTurnAttackValue = estimateEnemyBestPotentialAttackValue(state, unit, plan, coord);
  const objectiveProgress = currentDistance - hexDistance(coord, objective);
  const baseProgress = hexDistance(unit.coord, state.bases.Player) - hexDistance(coord, state.bases.Player);
  const gateContest = isEnemyTempoGateContestMove(state, unit, coord, plan);
  const localSuperiority = scoreEnemyLocalSuperiorityTempo(state, unit, coord, plan);
  const supportAdvance = scoreEnemyAggressiveStageSupportAdvance(state, unit, coord);
  const coveredSupport = scoreEnemyAggressiveStageCoveredSupport(state, unit, coord);
  const supportCoverage = scoreEnemySupportStagingCoverage(state, unit, coord, plan);
  const supportStagingUnit = isEnemyFireSupportStagingUnit(unit.type);

  if (definition.domain === "Air" && !isEnemyAirMoveAllowedByThreatMap(state, unit, coord, action, plan)) {
    return Number.NEGATIVE_INFINITY;
  }
  if (finalReplyDamage >= health * getEnemyCatastrophicExposureRatio(state, unit, action, plan)) {
    return Number.NEGATIVE_INFINITY;
  }
  if (unit.health / Math.max(1, unit.maxHealth) < 0.68 && objectiveProgress <= 0 && !gateContest) {
    return Number.NEGATIVE_INFINITY;
  }
  if (supportStagingUnit && coveredSupport <= 0) {
    return Number.NEGATIVE_INFINITY;
  }
  if (supportStagingUnit && supportCoverage < 42 && objectiveProgress <= 0 && !gateContest) {
    return Number.NEGATIVE_INFINITY;
  }
  if (supportStagingUnit && finalReplyDamage > 0 && coveredSupport < 56) {
    return Number.NEGATIVE_INFINITY;
  }
  if (finalReplyDamage > getEnemyAggressiveStageReplyDamageBudget(state, unit, coord, plan, {
    supportScore,
    nextTurnAttackValue,
    gateContest,
    objectiveProgress,
    coveredSupport,
    supportCoverage
  })) {
    return Number.NEGATIVE_INFINITY;
  }

  const initiative = plan.strategicSnapshot.initiativePressure ?? 0;
  const initiativeScore = Math.min(120, initiative * 0.35);
  const progressScore = Math.max(0, objectiveProgress) * 54 + Math.max(0, baseProgress) * 18;
  const gateScore = gateContest ? 110 : 0;
  const nextAttackScore = Math.min(180, nextTurnAttackValue * 0.12);
  const supportScoreValue = Math.min(120, supportScore * 1.9) + supportAdvance + coveredSupport + supportCoverage;
  const superiorityScore = localSuperiority * 0.75;
  const riskCost = finalReplyDamage * (supportStagingUnit ? 6.8 : 3.8) + danger * (supportStagingUnit ? 1.15 : 0.9) + Math.max(0, finalReplyDamage - currentReplyDamage) * (supportStagingUnit ? 2.8 : 2.2);

  return initiativeScore + progressScore + gateScore + nextAttackScore + supportScoreValue + superiorityScore - riskCost;
}

function getEnemyAggressiveStageReplyDamageBudget(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  context: {
    supportScore: number;
    nextTurnAttackValue: number;
    gateContest: boolean;
    objectiveProgress: number;
    coveredSupport: number;
    supportCoverage: number;
  }
): number {
  const health = Math.max(1, unit.health);
  if (isEnemyFireSupportStagingUnit(unit.type)) {
    const coveredRatio = context.coveredSupport >= 80 ? 0.2 : context.coveredSupport > 0 ? 0.16 : 0.1;
    const coverageBonus = context.supportCoverage >= 90 || context.nextTurnAttackValue >= 500 ? 0.03 : context.supportCoverage >= 42 ? 0.015 : 0;
    return health * Math.min(0.24, coveredRatio + coverageBonus);
  }
  const tempoBudget = getEnemyTempoExposureDamageBudget(state, unit, coord, plan, {
    initiative: plan.strategicSnapshot.initiativePressure ?? 0,
    supportScore: context.supportScore,
    potentialAttackValue: context.nextTurnAttackValue,
    gateContest: context.gateContest,
    objectiveProgress: context.objectiveProgress,
    materiallyEvenOrBehind: getEnemyKnownMaterialAdvantageRatio(plan) <= 1.12
  });
  return Math.min(health * 0.72, Math.max(health * 0.22, tempoBudget));
}

function scoreEnemyAggressiveStageSupportAdvance(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  return getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id || !isEnemyAggressiveStageAdvanceUnit(ally)) {
      return score;
    }
    const distance = hexDistance(coord, ally.coord);
    return score + (distance >= 1 && distance <= 3 ? 34 : distance === 4 ? 18 : 0);
  }, 0);
}

function scoreEnemyAggressiveStageCoveredSupport(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  if (!isEnemyFireSupportStagingUnit(unit.type)) {
    return 0;
  }
  return getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id || !isEnemyAggressiveStageAdvanceUnit(ally)) {
      return score;
    }
    const distance = hexDistance(coord, ally.coord);
    return score + (distance >= 2 && distance <= 4 ? 64 - Math.abs(distance - 3) * 8 : 0);
  }, 0);
}

function scoreEnemySupportStagingCoverage(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  if (!isEnemyFireSupportStagingUnit(unit.type)) {
    return 0;
  }

  const coveredAdvances = getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id || !isEnemyAggressiveStageAdvanceUnit(ally)) {
      return score;
    }
    const distance = hexDistance(coord, ally.coord);
    return score + (distance >= 2 && distance <= 4 ? 26 - Math.abs(distance - 3) * 4 : 0);
  }, 0);

  const fireCoverage = plan.playerIntel.reduce((score, intel) => {
    if (!canUnitTargetUnit(unit.type, intel.unit.type)) {
      return score;
    }
    const target = { ...intel.unit, coord: { ...intel.predictedCoord } };
    const distance = hexDistance(coord, target.coord);
    const range = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, target.coord).attackRange;
    const inRange = distance <= range;
    const nearRange = !inRange && distance <= range + 2;
    if (!inRange && !nearRange) {
      return score;
    }
    const objectiveRelevant =
      getUnitDefinition(target.type).humanBased ||
      target.type === "Artillery" ||
      target.type === "Anti-Air" ||
      isEnemyTargetNearObjective(state, target, coord);
    const targetValue = Math.min(58, getUnitInstanceValue(state, target) * 0.12);
    const rangeScore = inRange ? 58 : 28;
    return score + (rangeScore + targetValue + (objectiveRelevant ? 34 : 0)) * intel.confidence;
  }, 0);

  return Math.min(180, coveredAdvances + fireCoverage);
}

function isEnemyFireSupportStagingUnit(unitType: UnitType): boolean {
  return unitType === "Artillery" || unitType === "Anti-Air";
}

function isEnemyAggressiveStageAdvanceUnit(unit: UnitInstance): boolean {
  return unit.owner === "Enemy" && (unit.type === "Tank" || unit.type === "IFV" || unit.type === "Ghost" || unit.type === "Operator" || unit.type === "Reaper");
}

function uniqueCoords(coords: UnitInstance["coord"][]): UnitInstance["coord"][] {
  const seen = new Set<string>();
  const result: UnitInstance["coord"][] = [];
  for (const coord of coords) {
    const id = hexId(coord);
    if (seen.has(id)) {
      continue;
    }
    seen.add(id);
    result.push({ ...coord });
  }
  return result;
}

function chooseEnemyPlannerOperationalTarget(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] {
  const imperative = plan.objectiveImperatives.find((entry) => entry.unitId === unit.id && entry.targetCoord);
  if (imperative?.targetCoord) {
    return imperative.targetCoord;
  }
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const gateLockoutTarget = isEnemyGateLockoutCombatMission(mission)
    ? chooseEnemyGateLockoutRoleTargetCoord(state, unit, mission, plan)
    : undefined;
  if (gateLockoutTarget) {
    return gateLockoutTarget;
  }
  if (mission === "DefendGate") {
    const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    const anchor = gate ? chooseEnemyGateTheatreDefenseAnchorCoord(state, unit, gate, plan) : undefined;
    if (anchor) {
      return anchor;
    }
  }
  if (
    state.day > 10 &&
    mission !== "Repair" &&
    mission !== "CaptureGate" &&
    mission !== "DefendGate" &&
    getEnemyPlannerCombatPressure(state, plan) >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD
  ) {
    const combatTarget = chooseEnemyPlannerCombatTargetCoord(state, unit, plan);
    if (combatTarget) {
      return combatTarget;
    }
  }
  if (mission === "PatrolWest" || mission === "PatrolEast" || mission === "Scout") {
    return chooseEnemyStrategicScoutTarget(state, unit, plan)?.coord ?? chooseEnemyOperationalTarget(state, unit);
  }
  const endgamePushTarget = chooseEnemyEndgamePushTarget(state, unit, plan);
  if (endgamePushTarget) {
    return endgamePushTarget;
  }
  const force = plan.taskForces.find((taskForce) => taskForce.members.includes(unit.id));
  if (force) {
    return force.objectiveCoord;
  }
  if (mission === "Repair") {
    return getNearestEnemyRepairCoord(state, unit.coord, unit.type);
  }

  if (isEnemySupplySupportUnit(unit.type)) {
    return chooseEnemySupplyTruckSupportAnchor(state, unit, plan) ?? state.bases.Player;
  }
  return chooseEnemyOperationalTarget(state, unit);
}

function chooseEnemyPlannerCombatTargetCoord(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  return plan.playerIntel
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .sort((first, second) => scoreEnemyPlannerCombatTargetCoord(state, unit, second, plan) - scoreEnemyPlannerCombatTargetCoord(state, unit, first, plan))
    [0]?.predictedCoord;
}

function scoreEnemyPlannerCombatTargetCoord(state: GameState, unit: UnitInstance, intel: EnemyPlannerPlayerIntel, plan: EnemyTurnPlan): number {
  const targetValue = getUnitInstanceValue(state, intel.unit);
  const forwardLine = Math.floor(state.map.height * 0.5);
  const forwardDepth = Math.max(0, forwardLine - intel.predictedCoord.r);
  const enemyAreaBonus = isCoordInEnemyHomeArea(state, intel.predictedCoord) ? 120 : 0;
  const baseProximity = Math.max(0, getEnemyBaseResponseRadius(state) + 8 - hexDistance(intel.predictedCoord, state.bases.Enemy)) * 14;
  const counterPriority = getCounterPriorityBonus(unit.type, { ...intel.unit, coord: intel.predictedCoord });
  const missionPressure = getEnemyPlannerCombatPressure(state, plan) * 0.12;
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const lockoutGate = isEnemyGateLockoutCombatMission(mission) ? chooseEnemyGateLockoutCounterattackGate(state, plan) : undefined;
  const gateZoneBonus = lockoutGate
    ? Math.max(0, 8 - hexDistance(intel.predictedCoord, lockoutGate.coord)) * (isEnemyGateLockoutClearingMission(mission) ? 44 : 22)
    : 0;
  const reservePenalty = mission === "ReserveCapturer" && !actionableReserveCapturerTarget(state, intel, lockoutGate) ? 80 : 0;
  return (targetValue * 1.1 + forwardDepth * 30 + enemyAreaBonus + baseProximity + counterPriority + missionPressure + gateZoneBonus - reservePenalty) * intel.confidence;
}

function actionableReserveCapturerTarget(state: GameState, intel: EnemyPlannerPlayerIntel, gate: GateState | undefined): boolean {
  return Boolean(gate && getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, gate.coord) <= 2);
}

function chooseEnemyCombatTargetCoord(state: GameState, unit: UnitInstance): UnitInstance["coord"] | undefined {
  return getPlayerIntelForEnemy(state)
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .sort((first, second) => scoreEnemyCombatTargetCoord(state, unit, second) - scoreEnemyCombatTargetCoord(state, unit, first))
    [0]?.predictedCoord;
}

function scoreEnemyCombatTargetCoord(state: GameState, unit: UnitInstance, intel: PlayerUnitIntel): number {
  const forwardLine = Math.floor(state.map.height * 0.5);
  const forwardDepth = Math.max(0, forwardLine - intel.predictedCoord.r);
  const enemyAreaBonus = isCoordInEnemyHomeArea(state, intel.predictedCoord) ? 120 : 0;
  const baseProximity = Math.max(0, getEnemyBaseResponseRadius(state) + 8 - hexDistance(intel.predictedCoord, state.bases.Enemy)) * 14;
  return (getUnitInstanceValue(state, intel.unit) * 1.1 + forwardDepth * 30 + enemyAreaBonus + baseProximity + getCounterPriorityBonus(unit.type, { ...intel.unit, coord: intel.predictedCoord })) * intel.confidence;
}

function getEnemyPlannerAttackTargets(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan
): Array<{ target: UnitInstance; outcome: ExpectedAttackOutcome; score: number }> {
  if (unit.hasAttackedThisDay || unit.placedDay === state.day) {
    return [];
  }

  const cache = getEnemyEvaluationCache(state);
  cache.plannerAttackTargets ??= new Map();
  const cacheKey = `${unit.id}:${hexId(unit.coord)}:${unit.health}:${unit.level}:${unit.hasAttackedThisDay ? 1 : 0}`;
  const cached = cache.plannerAttackTargets.get(cacheKey);
  if (cached) {
    return cached;
  }

  const visibleTargetIds = getEnemyPlannerVisibleTargetIds(plan);
  const targets = getOwnerUnits(state, "Player")
    .filter((target) => visibleTargetIds.has(target.id))
    .filter((target) => canUnitTargetUnit(unit.type, target.type) && hexDistance(unit.coord, target.coord) <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord).attackRange)
    .filter((target) => !isEnemyHighAltitudeEdgeAntiAirSuppressionTarget(unit, target))
    .filter((target) => isEnemyFireSupportAttackIntelAuthorized(state, unit, target, plan))
    .map((target) => {
      const outcome = getExpectedAttackOutcome(state, unit, target);
      return {
        target,
        outcome,
        score: scoreEnemyPlannerAttackTarget(state, unit, target, outcome, plan)
      };
    })
    .sort((first, second) => second.score - first.score || first.target.id.localeCompare(second.target.id));
  cache.plannerAttackTargets.set(cacheKey, targets);
  return targets;
}

function isEnemyHighAltitudeEdgeAntiAirSuppressionTarget(
  attacker: UnitInstance,
  target: UnitInstance
): boolean {
  if (!isEnemyPriorityAntiAirHunter(attacker.type) || target.type !== "Anti-Air") {
    return false;
  }
  return hexDistance(attacker.coord, target.coord) > getUnitDefinition(attacker.type).attackRange;
}

function getEnemyPlannerAttackOptions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>,
  limit?: number
): Array<{ target: UnitInstance; outcome: ExpectedAttackOutcome; score: number }> {
  const targets = getEnemyPlannerAttackTargets(state, unit, plan);
  const selected = limit === undefined ? [...targets] : targets.slice(0, limit);
  for (const candidate of targets) {
    const reserved = reservedExpectedDamage[candidate.target.id];
    if (!reserved || selected.some((entry) => entry.target.id === candidate.target.id)) {
      continue;
    }
    if (isEnemyReservedDamageLikelyClearingTarget(candidate.target, reserved)) {
      continue;
    }
    if (scoreEnemyFocusFireTargetPriority(state, candidate.target, plan) <= 0) {
      continue;
    }
    selected.push(candidate);
  }
  return selected.sort((first, second) => second.score - first.score || first.target.id.localeCompare(second.target.id));
}

function getEnemyPlannerVisibleTargetIds(plan: EnemyTurnPlan): Set<string> {
  plan.cache.visibleTargetIds ??= new Set(
    plan.playerIntel.filter((intel) => intel.age === 0 && intel.observedCoord).map((intel) => intel.unit.id)
  );
  return plan.cache.visibleTargetIds;
}

function isEnemyFireSupportAttackIntelAuthorized(
  state: GameState,
  attacker: UnitInstance,
  target: UnitInstance,
  plan: EnemyTurnPlan
): boolean {
  if (!isUncertaintySensitiveFireSupport(attacker.type)) {
    return true;
  }

  const intel = plan.playerIntel.find((entry) => entry.unit.id === target.id);
  if (intel?.age === 0 && intel.observedCoord) {
    return true;
  }

  if (isHighObjectiveFireSupportPayoff(state, target)) {
    return true;
  }

  if (!intel) {
    return false;
  }

  const predictedTarget = sameHex(intel.predictedCoord, target.coord) || hexDistance(intel.predictedCoord, target.coord) <= 1;
  const beliefAtTarget = intel.currentBeliefs.some((belief) => sameHex(belief.coord, target.coord) && belief.weight * intel.confidence >= 0.5);
  const freshScoutTrail = intel.age <= 1 && intel.confidence >= 0.82 && (predictedTarget || beliefAtTarget);
  const highConfidenceBelief = intel.confidence >= 0.72 && (beliefAtTarget || (predictedTarget && intel.age <= 2));
  return freshScoutTrail || highConfidenceBelief;
}

function isUncertaintySensitiveFireSupport(unitType: UnitType): boolean {
  return unitType === "Artillery" || unitType === "Bomber" || unitType === "Reaper";
}

function isHighObjectiveFireSupportPayoff(state: GameState, target: UnitInstance): boolean {
  if (getUnitDefinition(target.type).humanBased && sameHex(target.coord, state.bases.Enemy) && state.baseOccupation.Enemy >= BASE_CAPTURE_DAYS - 2) {
    return true;
  }
  if (sameHex(target.coord, state.bases.Player) && (ownerControlsBothGates(state, "Enemy") || state.baseOccupation.Player > 0)) {
    return true;
  }
  return (state.gates ?? []).some(
    (gate) =>
      sameHex(target.coord, gate.coord) &&
      (gate.occupation.Player >= GATE_CAPTURE_DAYS - 1 || gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1)
  );
}

function getExpectedAttackOutcome(state: GameState, attacker: UnitInstance, target: UnitInstance): ExpectedAttackOutcome {
  const cacheKey = [
    attacker.id,
    attacker.type,
    attacker.level,
    attacker.health,
    attacker.maxHealth,
    hexId(attacker.coord),
    target.id,
    target.type,
    target.level,
    target.health,
    target.maxHealth,
    hexId(target.coord)
  ].join(":");
  const cache = activeEnemyTurnPlan
    ? (activeEnemyTurnPlan.cache.expectedAttackOutcomes ??= new Map())
    : (getEnemyEvaluationCache(state).expectedAttackOutcomes ??= new Map());
  const cached = cache.get(cacheKey);
  if (cached) {
    return cached;
  }

  const stealth = isStealthAttack(state, attacker, target);
  const normalDamage = calculateAttackDamage(state, attacker, target.type, { critical: false, stealth });
  const criticalDamage = calculateAttackDamage(state, attacker, target.type, { critical: true, stealth });
  const missProbability = ATTACK_MISS_CHANCE;
  const criticalDamageProbability = (1 - missProbability) * CRITICAL_HIT_CHANCE;
  const normalDamageProbability = (1 - missProbability) * (1 - CRITICAL_HIT_CHANCE);
  const expectedDamage = normalDamageProbability * normalDamage + criticalDamageProbability * criticalDamage;
  const outcome = {
    missProbability,
    normalDamageProbability,
    normalDamage,
    criticalDamageProbability,
    criticalDamage,
    expectedDamage,
    killProbability:
      (normalDamage >= target.health ? normalDamageProbability : 0) +
      (criticalDamage >= target.health ? criticalDamageProbability : 0)
  };
  cache.set(cacheKey, outcome);
  return outcome;
}

function getUsefulExpectedDamage(target: UnitInstance | undefined, expectedDamage: number): number {
  const boundedExpectedDamage = Math.max(0, expectedDamage);
  return target ? Math.min(Math.max(0, target.health), boundedExpectedDamage) : boundedExpectedDamage;
}

function estimateAttackDamage(state: GameState, attacker: UnitInstance, target: UnitInstance): number {
  if (activeEnemyTurnPlan || attacker.owner === "Enemy" || target.owner === "Enemy") {
    return getExpectedAttackOutcome(state, attacker, target).normalDamage;
  }

  return estimateAttackDamageRaw(state, attacker, target);
}

function scoreEnemyPlannerAttackTarget(
  state: GameState,
  attacker: UnitInstance,
  target: UnitInstance,
  outcome: ExpectedAttackOutcome,
  plan: EnemyTurnPlan
): number {
  const targetValue = getUnitInstanceValue(state, target);
  const blockerPriority = getEnemyObjectiveBlockerTargetPriority(state, target, plan);
  const objective =
    getUnitDefinition(target.type).humanBased && sameHex(target.coord, state.bases.Enemy)
      ? 500 + state.baseOccupation.Enemy * 180
      : getUnitDefinition(target.type).humanBased && (state.gates ?? []).some((gate) => sameHex(gate.coord, target.coord) && gate.occupation.Player > 0)
        ? 220
        : 0;
  const supplyTruckPriority = getPlayerSupplyTruckTargetPriority(target);
  const supportAsset = isEnemySupplySupportUnit(target.type) ? supplyTruckPriority : isReconUnit(target.type) ? 36 : isSpecialUnit(target.type) ? 92 : target.type === "Artillery" || target.type === "Anti-Air" ? 72 : 0;
  const focusPriority = scoreEnemyFocusFireTargetPriority(state, target, plan);
  const baseAreaAssaultPriority =
    isEnemyBaseAttackCombatUnit(attacker) && isEnemyBaseOperationPhase(plan.campaignPlan.phase)
      ? scoreEnemyPlayerBaseAreaTargetPriority(state, attacker, target, plan)
      : 0;
  const airDefenseSuppression =
    isEnemyPriorityAntiAirHunter(attacker.type) && target.type === "Anti-Air"
      ? 2400 + getUnitInstanceValue(state, attacker) * 1.8 + (isEnemyAntiAirBlockingAttackAsset(state, target, plan) ? 900 : 0)
      : 0;
  const ownBaseDistance = hexDistance(target.coord, state.bases.Enemy);
  const forwardPressure = Math.max(0, Math.floor(state.map.height * 0.44) - target.coord.r) * 18;
  const enemyAreaPressure = isCoordInEnemyHomeArea(state, target.coord) ? getEnemyPlannerCombatPressure(state, plan) * 0.55 : 0;
  const baseZone = Math.max(0, getEnemyBaseResponseRadius(state) + 4 - ownBaseDistance) * 32;
  const counterThreat =
    canUnitTargetUnit(target.type, attacker.type) &&
    hexDistance(attacker.coord, target.coord) <= getEffectiveUnitStats(state, target.owner, target.type, target.level, target.coord, attacker.coord).attackRange
      ? 78
      : 0;
  const usefulDamage = getUsefulExpectedDamage(target, outcome.expectedDamage);
  return blockerPriority + baseAreaAssaultPriority + focusPriority + airDefenseSuppression + usefulDamage * 18 + outcome.killProbability * (targetValue + 310) + objective + supportAsset + forwardPressure + enemyAreaPressure + baseZone + counterThreat;
}

function scoreEnemyFocusFireTargetPriority(state: GameState, target: UnitInstance, plan: EnemyTurnPlan): number {
  if (target.owner !== "Player") {
    return 0;
  }

  const definition = getUnitDefinition(target.type);
  const targetValue = getUnitInstanceValue(state, target);
  const capturer =
    definition.humanBased
      ? 360 +
        (sameHex(target.coord, state.bases.Enemy) ? 220 + state.baseOccupation.Enemy * 120 : 0) +
        (state.gates ?? []).reduce((score, gate) => score + (hexDistance(target.coord, gate.coord) <= 1 ? 90 + gate.occupation.Player * 70 : 0), 0)
      : 0;
  const artillery = target.type === "Artillery" ? 300 : 0;
  const antiAir = isEnemyAntiAirBlockingAttackAsset(state, target, plan) ? 280 : target.type === "Anti-Air" ? 150 : 0;
  const supplyTruck = getPlayerSupplyTruckTargetPriority(target);
  const woundedHighValue = target.health / Math.max(1, target.maxHealth) <= 0.55 && targetValue >= 90 ? 180 + Math.min(180, targetValue * 0.85) : 0;
  const gateArmor =
    (target.type === "Tank" || target.type === "IFV") &&
    (state.gates ?? []).some((gate) => hexDistance(target.coord, gate.coord) <= ENEMY_GATE_THEATRE_OBJECTIVE_RADIUS)
      ? target.type === "Tank" ? 170 : 145
      : 0;
  const gateClearance = (state.gates ?? []).some((gate) => isGateClearanceTarget(state, target, gate, plan)) ? 180 : 0;
  const infantry = target.type === "Infantry" ? 80 : 0;
  return capturer + artillery + antiAir + supplyTruck + woundedHighValue + gateArmor + gateClearance + infantry;
}

function isEnemyAntiAirBlockingAttackAsset(state: GameState, target: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (target.type !== "Anti-Air") {
    return false;
  }

  const enemyAirPresent = getOwnerUnits(state, "Enemy").some((unit) => getUnitDefinition(unit.type).domain === "Air");
  const airAttackNeed =
    plan.strategicSnapshot.airExploitationOpportunity > 120 ||
    plan.campaignPlan.phase === "GateLockoutCombat" ||
    plan.objectiveImperatives.some((imperative) => imperative.targetId && getUnitById(state, imperative.targetId)?.owner === "Player");
  const nearGateTheatre = (state.gates ?? []).some((gate) => hexDistance(target.coord, gate.coord) <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS);
  const nearBaseApproach = hexDistance(target.coord, state.bases.Player) <= 8 || hexDistance(target.coord, state.bases.Enemy) <= getEnemyBaseResponseRadius(state) + 4;
  return enemyAirPresent && airAttackNeed && (nearGateTheatre || nearBaseApproach);
}

function scoreEnemyFocusFireReservation(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance,
  action: EnemyCompoundAction,
  reserved: { expectedDamage: number; killProbability: number; unitIds: string[] } | undefined,
  plan: EnemyTurnPlan
): number {
  if (!action.expectedOutcome || !reserved || reserved.unitIds.includes(unit.id) || isEnemyReservedDamageLikelyClearingTarget(target, reserved)) {
    return 0;
  }

  const priority = scoreEnemyFocusFireTargetPriority(state, target, plan);
  if (priority <= 0) {
    return 0;
  }

  const usefulDamage = getUsefulExpectedDamage(target, action.expectedOutcome.expectedDamage);
  const finishingBlow = action.expectedOutcome.expectedDamage >= target.health || action.expectedOutcome.killProbability >= 0.58;
  const combinedKillProbability = 1 - (1 - reserved.killProbability) * (1 - action.expectedOutcome.killProbability);
  const likelyCombinedKill = usefulDamage >= target.health * 0.72 || combinedKillProbability >= 0.72;
  const existingFocus = Math.min(3, reserved.unitIds.length);
  return (
    Math.min(360, priority * 0.42) +
    usefulDamage * 24 +
    action.expectedOutcome.killProbability * 280 +
    existingFocus * 45 +
    (finishingBlow ? 320 : 0) +
    (likelyCombinedKill ? 180 : 0)
  );
}

function createEnemyCompoundAction(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  kind: EnemyCompoundActionKind,
  input: {
    moveTo?: UnitInstance["coord"];
    retreatTo?: UnitInstance["coord"];
    attackAt?: UnitInstance["coord"];
    targetId?: string;
    targetType?: UnitType;
    expectedOutcome?: ExpectedAttackOutcome;
  },
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyCompoundAction {
  const action = createUnevaluatedEnemyCompoundAction(unit, plan, kind, input);
  action.breakdown = evaluateEnemyCompoundAction(state, unit, action, plan, reservedDestinations, reservedExpectedDamage);
  return action;
}

function createUnevaluatedEnemyCompoundAction(
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  kind: EnemyCompoundActionKind,
  input: {
    moveTo?: UnitInstance["coord"];
    retreatTo?: UnitInstance["coord"];
    attackAt?: UnitInstance["coord"];
    targetId?: string;
    targetType?: UnitType;
    expectedOutcome?: ExpectedAttackOutcome;
  }
): EnemyCompoundAction {
  return {
    id: `${unit.id}:${kind}:${input.moveTo ? hexId(input.moveTo) : "hold"}:${input.retreatTo ? hexId(input.retreatTo) : "none"}:${input.targetId ?? "none"}`,
    unitId: unit.id,
    unitType: unit.type,
    kind,
    moveTo: input.moveTo ? { ...input.moveTo } : undefined,
    retreatTo: input.retreatTo ? { ...input.retreatTo } : undefined,
    attackAt: input.attackAt ? { ...input.attackAt } : undefined,
    targetId: input.targetId,
    targetType: input.targetType,
    expectedOutcome: input.expectedOutcome,
    dependencies: plan.activationDependencies[unit.id] ?? [],
    breakdown: createEmptyEnemyPlannerScoreBreakdown()
  };
}

function getEnemyCompoundActionFinalCoord(unit: UnitInstance, action: EnemyCompoundAction): UnitInstance["coord"] {
  return action.retreatTo ?? action.moveTo ?? unit.coord;
}

function getEnemyCompoundActionReservedCoord(action: EnemyCompoundAction): UnitInstance["coord"] | undefined {
  return action.retreatTo ?? action.moveTo;
}

function createEmptyEnemyPlannerScoreBreakdown(): EnemyPlannerScoreBreakdown {
  return {
    terminal: 0,
    baseCaptureClock: 0,
    gateCaptureClock: 0,
    backupCapturerValue: 0,
    replacementDistance: 0,
    material: 0,
    expectedDamage: 0,
    expectedLoss: 0,
    killProbability: 0,
    attackArea: 0,
    movementArea: 0,
    sightArea: 0,
    income: 0,
    territoryControl: 0,
    informationGain: 0,
    opportunityCost: 0,
    tempoRisk: 0,
    initiative: 0,
    support: 0,
    formation: 0,
    congestion: 0,
    taskProgress: 0,
    repairValue: 0,
    opponentReplyRisk: 0,
    doctrine: 0,
    total: 0
  };
}

function evaluateEnemyCompoundAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyPlannerScoreBreakdown {
  const breakdown = createEmptyEnemyPlannerScoreBreakdown();
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const imperative = plan.objectiveImperatives.find((entry) => entry.unitId === unit.id);
  const danger = estimatePlayerDangerAtPlanner(state, unit, finalCoord, plan);
  const currentDanger = estimatePlayerDangerAtPlanner(state, unit, unit.coord, plan);
  const value = getUnitInstanceValue(state, unit);
  const riskBudgetDiscount = getEnemyRiskBudgetDiscount(state, unit, action, finalCoord, plan);

  if (imperative) {
    if (imperative.actionKind === "Hold" && action.kind === "Hold") {
      breakdown.terminal += Math.abs(imperative.terminal);
    } else if (imperative.actionKind === "Move" && action.moveTo && imperative.targetCoord && sameHex(action.moveTo, imperative.targetCoord)) {
      breakdown.terminal += Math.abs(imperative.terminal);
    } else if (imperative.targetId && action.targetId === imperative.targetId) {
      breakdown.terminal += Math.abs(imperative.terminal) * Math.max(0.25, action.expectedOutcome?.killProbability ?? 0.25);
    } else {
      breakdown.terminal -= Math.abs(imperative.terminal);
    }
  }

  if (state.baseOccupation.Player >= BASE_CAPTURE_DAYS - 1 && getUnitDefinition(unit.type).humanBased && sameHex(unit.coord, state.bases.Player) && action.kind !== "Hold") {
    breakdown.terminal -= ENEMY_OBJECTIVE_TERMINAL_SCORE;
  }
  if (state.baseOccupation.Enemy >= BASE_CAPTURE_DAYS - 1 && getOwnerUnits(state, "Player").some((player) => getUnitDefinition(player.type).humanBased && sameHex(player.coord, state.bases.Enemy))) {
    const actionTarget = action.targetId ? getUnitById(state, action.targetId) : undefined;
    if (!actionTarget || actionTarget.owner !== "Player" || !sameHex(actionTarget.coord, state.bases.Enemy)) {
      breakdown.terminal -= ENEMY_OBJECTIVE_TERMINAL_SCORE;
    }
  }

  breakdown.baseCaptureClock += scoreEnemyBaseCaptureClockPreservation(state, unit, action, finalCoord, danger, currentDanger, plan);
  breakdown.gateCaptureClock += scoreEnemyGateCaptureClockPreservation(state, unit, action, finalCoord, danger, currentDanger, plan);
  breakdown.baseCaptureClock += scoreEnemyBaseCaptureClockAcceleration(state, unit, action, finalCoord, danger, plan);
  breakdown.gateCaptureClock += scoreEnemyGateCaptureClockAcceleration(state, unit, action, finalCoord, danger, plan);
  const replacementCapturerScore = scoreEnemyReplacementCapturerAction(state, unit, action, finalCoord, danger, plan);
  breakdown.backupCapturerValue += replacementCapturerScore.backupCapturerValue;
  breakdown.replacementDistance += replacementCapturerScore.replacementDistance;
  breakdown.terminal += scoreEnemyBaseHoldSurvivalAction(state, unit, action, finalCoord, danger, plan);
  breakdown.baseCaptureClock += scoreEnemyBaseCaptureClockAction(state, unit, action, mission, finalCoord, danger, plan);
  for (const gate of state.gates ?? []) {
    breakdown.gateCaptureClock += scoreEnemyGateCaptureClockAction(state, unit, action, mission, gate, finalCoord, danger, plan);
    breakdown.income += getUnitDefinition(unit.type).humanBased && sameHex(finalCoord, gate.coord)
      ? gate.owner === "Enemy" ? 10 : getGateIncomeBonusForEconomy(state.enemyEconomy) * 18
      : 0;
  }

  if (action.expectedOutcome && action.targetId) {
    const target = getUnitById(state, action.targetId);
    const reserved = reservedExpectedDamage[action.targetId];
    const phaseWeights = getEnemyStrategicPhaseWeights(plan.strategicSnapshot.strategicPhase);
    const objectiveBlockerNeedsDamage =
      target &&
      isEnemyObjectiveBlockerTarget(state, target, plan) &&
      !isEnemyReservedDamageLikelyClearingTarget(target, reserved);
    const overkillPenalty = reserved && reserved.killProbability >= 0.78 && getEnemyPlannerAttackTargets(state, unit, plan).length > 1 && !objectiveBlockerNeedsDamage ? 160 : 0;
    const combatPressureMultiplier =
      target && (getEnemyPlannerCombatPressure(state, plan) >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD || plan.strategicSnapshot.strategicPhase === "GateLockoutCombat")
        ? (target.coord.r <= Math.floor(state.map.height * 0.5) ? 1.55 : 1.18) * phaseWeights.combat
        : 1;
    breakdown.terminal += target ? scoreEnemyObjectiveBlockerReservation(state, unit, target, action, reserved, plan) : 0;
    breakdown.terminal += objectiveBlockerNeedsDamage ? 1400 : 0;
    breakdown.gateCaptureClock += target ? scoreEnemyGateLockoutClearAction(state, target, action, plan) : 0;
    breakdown.material += target ? scoreEnemyFocusFireReservation(state, unit, target, action, reserved, plan) : 0;
    breakdown.taskProgress += target ? scoreEnemyBaseAreaAssaultAttackAction(state, unit, target, action, finalCoord, mission, plan) : 0;
    const usefulDamage = getUsefulExpectedDamage(target, action.expectedOutcome.expectedDamage);
    breakdown.expectedDamage += usefulDamage * 20 * combatPressureMultiplier;
    breakdown.killProbability += action.expectedOutcome.killProbability * 340 * combatPressureMultiplier;
    breakdown.material += target ? (getUnitInstanceValue(state, target) * action.expectedOutcome.killProbability * 1.8 + usefulDamage * 9) * combatPressureMultiplier : 0;
    breakdown.congestion -= overkillPenalty;
  }

  const roleScarcityMultiplier = getEnemyRoleScarcityMultiplier(state, unit, plan);
  breakdown.expectedLoss -= danger * getEnemyExpectedLossWeight(state, unit, action, finalCoord, mission, plan, value) * roleScarcityMultiplier * riskBudgetDiscount;
  breakdown.expectedLoss -= scoreEnemySupplyTruckDamageRisk(state, unit, finalCoord, plan, action);
  breakdown.expectedLoss += Math.max(0, currentDanger - danger) * 1.7;
  breakdown.expectedLoss += scoreEnemyPostAttackRetreatMove(state, unit, action, finalCoord, plan);
  breakdown.material += scoreEnemyFavorableAttackExchange(state, unit, action, plan);
  const areaScore = scoreEnemyActionAreaChange(state, unit, action, finalCoord, mission);
  breakdown.attackArea += areaScore.attackArea;
  breakdown.movementArea += areaScore.movementArea;
  breakdown.sightArea += areaScore.sightArea;
  const informationGain = getEnemyPlannerInformationGain(state, unit, finalCoord);
  const scoutInformationMultiplier =
    mission === "Scout" || mission === "PatrolWest" || mission === "PatrolEast"
      ? 12
      : isReconUnit(unit.type)
        ? 5
        : 1.2;
  breakdown.informationGain += informationGain * scoutInformationMultiplier;
  breakdown.informationGain += scoreEnemyWeightedFogRevealFrom(state, unit, finalCoord) * scoutInformationMultiplier;
  breakdown.informationGain += scoreEnemyObjectiveDirectedScoutPosition(state, unit, finalCoord, plan);
  breakdown.territoryControl += scoreEnemyTerritoryControlAction(state, unit, action, finalCoord);
  breakdown.territoryControl += scoreEnemyPathDenial(state, unit, finalCoord, plan);
  breakdown.opportunityCost += scoreEnemyActionOpportunityCost(state, unit, action, finalCoord, plan, danger);
  breakdown.tempoRisk += scoreEnemyTempoRiskAction(state, unit, action, finalCoord, plan);
  breakdown.support += getEnemyPlannerSupportScore(state, unit, finalCoord);
  breakdown.formation += getEnemyPlannerFormationScore(state, unit, finalCoord, mission);
  breakdown.formation += getEnemyPlannerSpacingScore(state, unit, finalCoord, mission, plan);
  breakdown.congestion -= getEnemyPlannerCongestionPenalty(state, unit, finalCoord, reservedDestinations);
  breakdown.congestion -= getEnemyParallelAdvancePenalty(state, unit, finalCoord, mission, plan, reservedDestinations);
  breakdown.taskProgress += getEnemyPlannerTaskProgressScore(state, unit, finalCoord, plan);
  breakdown.taskProgress += scoreEnemyCombatObjectiveFollowThrough(state, unit, action, finalCoord, mission, plan);
  breakdown.initiative += scoreEnemyInitiativeAction(state, unit, action, finalCoord, mission, plan);
  breakdown.repairValue += mission === "Repair" ? Math.max(0, 10 - getNearestEnemyRepairDistance(state, finalCoord, unit.type)) * 18 : 0;
  breakdown.opponentReplyRisk -= estimateEnemyPlannerOpponentReplyRisk(state, unit, finalCoord, plan) * riskBudgetDiscount;
  breakdown.opponentReplyRisk -= estimateEnemyFogThreatAtPlanner(state, unit, finalCoord, plan) * 0.25 * riskBudgetDiscount;
  breakdown.doctrine -= getEnemyFrontLineStandoffPenalty(state, unit, finalCoord, mission) * riskBudgetDiscount;
  breakdown.doctrine += scoreEnemyFrontLineTrapAction(state, unit, action, finalCoord, plan);
  breakdown.doctrine += scoreEnemyGateTheatreDefenseAction(state, unit, action, finalCoord, mission, plan);
  breakdown.doctrine -= getEnemyArmorGroundCommitmentRetreatPenalty(state, unit, action, finalCoord, plan);
  breakdown.doctrine -= getEnemyFrontLineOverextensionRisk(state, unit, finalCoord, mission, plan) * riskBudgetDiscount;
  breakdown.doctrine += scoreEnemyOpponentProfileTacticalCounter(state, unit, action, finalCoord, mission, plan);
  breakdown.doctrine += scoreEnemyStrategyPlaybookTacticalBehavior(state, unit, action, finalCoord, mission, plan);
  breakdown.doctrine += scoreEnemyFireSupportCenterStagingAction(state, unit, action, finalCoord, plan);
  breakdown.doctrine += getEnemyPlannerDoctrineScore(state, unit, action, plan);
  breakdown.total =
    breakdown.terminal +
    breakdown.baseCaptureClock +
    breakdown.gateCaptureClock +
    breakdown.backupCapturerValue +
    breakdown.replacementDistance +
    breakdown.material +
    breakdown.expectedDamage +
    breakdown.expectedLoss +
    breakdown.killProbability +
    breakdown.attackArea +
    breakdown.movementArea +
    breakdown.sightArea +
    breakdown.income +
    breakdown.territoryControl +
    breakdown.informationGain +
    breakdown.opportunityCost +
    breakdown.tempoRisk +
    breakdown.initiative +
    breakdown.support +
    breakdown.formation +
    breakdown.congestion +
    breakdown.taskProgress +
    breakdown.repairValue +
    breakdown.opponentReplyRisk +
    breakdown.doctrine;
  return breakdown;
}

function scoreEnemyActionAreaChange(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission
): EnemyActionAreaMetrics {
  if (!getEnemyCompoundActionReservedCoord(action) || sameHex(finalCoord, unit.coord)) {
    return { attackArea: 0, movementArea: 0, sightArea: 0 };
  }

  const current = getEnemyActionAreaMetrics(state, unit, unit.coord);
  const next = getEnemyActionAreaMetrics(state, unit, finalCoord);
  const sightWeight =
    mission === "Scout" || mission === "PatrolWest" || mission === "PatrolEast"
      ? ENEMY_SIGHT_AREA_SCORE_WEIGHT * 2
      : isReconUnit(unit.type)
        ? ENEMY_SIGHT_AREA_SCORE_WEIGHT * 1.5
        : ENEMY_SIGHT_AREA_SCORE_WEIGHT;

  return {
    attackArea: (next.attackArea - current.attackArea) * ENEMY_ATTACK_AREA_SCORE_WEIGHT,
    movementArea: (next.movementArea - current.movementArea) * ENEMY_MOVEMENT_AREA_SCORE_WEIGHT,
    sightArea: (next.sightArea - current.sightArea) * sightWeight
  };
}

function getEnemyActionAreaMetrics(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): EnemyActionAreaMetrics {
  const cache = getEnemyEvaluationCache(state);
  cache.actionAreaMetrics ??= new Map();
  const cacheKey = `${unit.id}:${unit.owner}:${unit.type}:${unit.level}:${hexId(coord)}`;
  const cached = cache.actionAreaMetrics.get(cacheKey);
  if (cached) {
    return cached;
  }

  const projectedVisibleHexIds = getEnemyProjectedUnitSightHexIds(state, unit, coord);
  const metrics: EnemyActionAreaMetrics = {
    attackArea: countEnemyAttackAreaHexes(state, unit, coord),
    movementArea: countEnemyMovementAreaHexes(state, unit, coord, projectedVisibleHexIds),
    sightArea: countEnemySightAreaHexes(state, unit, coord)
  };
  cache.actionAreaMetrics.set(cacheKey, metrics);
  return metrics;
}

function countEnemyAttackAreaHexes(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  if (getUnitDefinition(unit.type).cannotAttack || !canOwnerOperateAcrossFrontLine(state, unit.owner, coord)) {
    return 0;
  }

  let count = 0;
  for (const hex of state.map.hexes) {
    if (!canOwnerOperateAcrossFrontLine(state, unit.owner, hex.coord)) {
      continue;
    }

    const attackRange = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, hex.coord).attackRange;
    if (attackRange > 0 && hexDistance(coord, hex.coord) <= attackRange) {
      count += 1;
    }
  }
  return count;
}

function countEnemyMovementAreaHexes(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  visibleHexIds: Set<string>
): number {
  const projectedUnit: UnitInstance = {
    ...unit,
    coord: { ...coord },
    placedDay: Math.min(unit.placedDay, state.day - 1),
    hasMovedThisDay: false,
    movementSpentThisDay: 0,
    hasAttackedThisDay: false
  };
  return getLegalMoveCoordsWithVisibility(state, projectedUnit, visibleHexIds).length;
}

function getEnemyProjectedUnitSightHexIds(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): Set<string> {
  const visible = new Set(getEnemyVisibleHexIds(state));
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord);
  const minQ = Math.max(0, coord.q - stats.visibilityRange);
  const maxQ = Math.min(state.map.width - 1, coord.q + stats.visibilityRange);
  const minR = Math.max(0, coord.r - stats.visibilityRange);
  const maxR = Math.min(state.map.height - 1, coord.r + stats.visibilityRange);

  for (let r = minR; r <= maxR; r += 1) {
    for (let q = minQ; q <= maxQ; q += 1) {
      const hex = getHex(state.map, { q, r });
      if (!hex) {
        continue;
      }

      const visibilityRange = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, hex.coord).visibilityRange;
      if (hexDistance(coord, hex.coord) <= visibilityRange) {
        visible.add(hex.id);
      }
    }
  }

  return visible;
}

function countEnemySightAreaHexes(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord);
  const minQ = Math.max(0, coord.q - stats.visibilityRange);
  const maxQ = Math.min(state.map.width - 1, coord.q + stats.visibilityRange);
  const minR = Math.max(0, coord.r - stats.visibilityRange);
  const maxR = Math.min(state.map.height - 1, coord.r + stats.visibilityRange);
  let count = 0;

  for (let r = minR; r <= maxR; r += 1) {
    for (let q = minQ; q <= maxQ; q += 1) {
      const hex = getHex(state.map, { q, r });
      if (!hex) {
        continue;
      }

      const visibilityRange = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, hex.coord).visibilityRange;
      if (hexDistance(coord, hex.coord) <= visibilityRange) {
        count += 1;
      }
    }
  }

  return count;
}

function getEnemyExpectedLossWeight(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan,
  value: number
): number {
  const defaultWeight = value > 100 ? 4.2 : 3.1;
  if (state.difficulty === "Hard" && action.kind !== "Hold" && isEnemyRiskBudgetCombatUnit(unit)) {
    const missionObjective = chooseEnemyCombatFollowThroughObjective(state, unit, mission, plan);
    const progress = hexDistance(unit.coord, missionObjective) - hexDistance(finalCoord, missionObjective);
    const materialRatio = getEnemyKnownMaterialAdvantageRatio(plan);
    const payoff = getEnemyActionAttackPayoff(state, action, plan);
    const pressure = getEnemyPlannerCombatPressure(state, plan);
    const tempoJustification = getEnemyTempoRiskJustificationScore(state, unit, action, finalCoord, mission, plan);
    let multiplier = 1;
    if (materialRatio >= 1.45) {
      multiplier -= 0.22;
    } else if (materialRatio >= 1.18) {
      multiplier -= 0.12;
    }
    if (progress > 0) {
      multiplier -= Math.min(0.18, progress * 0.05);
    }
    if (payoff.score >= 300 || payoff.objectiveTarget) {
      multiplier -= 0.16;
    } else if (payoff.score >= 160) {
      multiplier -= 0.08;
    }
    if (pressure >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD && (progress > 0 || action.targetId)) {
      multiplier -= 0.07;
    }
    if (tempoJustification >= 140) {
      multiplier -= Math.min(0.1, tempoJustification * 0.00045);
    }
    return defaultWeight * Math.max(0.58, multiplier);
  }
  if (state.difficulty !== "Hard" || action.kind === "Hold" || !getUnitDefinition(unit.type).humanBased) {
    return defaultWeight;
  }

  if ((mission === "CaptureGate" || mission === "ShadowCapturer" || mission === "EscortCapture" || mission === "DefendGate") && isEnemyGateFightCommitmentPhase(plan.campaignPlan.phase)) {
    const gate = chooseEnemyPlannerGateTargetForUnit(state, unit, plan) ?? chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    if (gate && gate.owner !== "Enemy" && hexDistance(finalCoord, gate.coord) < hexDistance(unit.coord, gate.coord)) {
      return defaultWeight * (sameHex(finalCoord, gate.coord) ? 0.34 : 0.55);
    }
  }

  if ((mission === "CaptureBase" || mission === "ProtectCapturer") && isEnemyBaseOperationPhase(plan.campaignPlan.phase) && hexDistance(finalCoord, state.bases.Player) < hexDistance(unit.coord, state.bases.Player)) {
    return defaultWeight * 0.62;
  }

  return defaultWeight;
}

function getEnemyRoleScarcityMultiplier(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): number {
  if (unit.owner !== "Enemy") {
    return 1;
  }

  const allies = getOwnerUnits(state, "Enemy").filter((ally) => ally.id !== unit.id);
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const playerHasAir = plan.playerIntel.some((intel) => getUnitDefinition(intel.unit.type).domain === "Air");
  const activeFront = plan.campaignPlan.phase === "GateLockoutCombat" || plan.campaignPlan.phase === "BaseAssault" || plan.campaignPlan.phase === "BaseHold";
  const criticalImperative = plan.objectiveImperatives.some((imperative) => imperative.unitId === unit.id && Math.abs(imperative.terminal) >= ENEMY_OBJECTIVE_TERMINAL_SCORE * 0.45);
  let multiplier = 1;

  if (criticalImperative) {
    multiplier = Math.max(multiplier, 1.75);
  }

  if (
    unit.type === "Anti-Air" &&
    playerHasAir &&
    !allies.some((ally) => ally.type === "Anti-Air")
  ) {
    multiplier = Math.max(multiplier, 1.5);
  }

  if (
    isEnemySupplySupportUnit(unit.type) &&
    activeFront &&
    !allies.some((ally) => isEnemySupplySupportUnit(ally.type)) &&
    getOwnerUnits(state, "Enemy").some((ally) => ally.id !== unit.id && isEnemyFrontlineRepairCandidate(state, ally))
  ) {
    multiplier = Math.max(multiplier, 1.6);
  }

  if (
    getUnitDefinition(unit.type).humanBased &&
    (mission === "CaptureGate" || mission === "ShadowCapturer" || mission === "EscortCapture" || mission === "CaptureBase" || mission === "ProtectCapturer") &&
    !allies.some((ally) => getUnitDefinition(ally.type).humanBased && hexDistance(ally.coord, unit.coord) <= 8)
  ) {
    multiplier = Math.max(multiplier, 1.35);
  }

  if (
    (mission === "DefendBase" || mission === "BaseSentry") &&
    !allies.some((ally) => isEnemyBaseDefenseResponder(state, ally))
  ) {
    multiplier = Math.max(multiplier, 1.35);
  }

  if (isReconUnit(unit.type) && !allies.some((ally) => isReconUnit(ally.type))) {
    multiplier = Math.max(multiplier, 1.2);
  }

  if (activeFront && isEnemyScarceCombatRole(state, unit, allies)) {
    multiplier = Math.max(multiplier, 1.2);
  }

  return multiplier;
}

function isEnemyFrontlineRepairCandidate(state: GameState, unit: UnitInstance): boolean {
  if (unit.owner !== "Enemy" || isEnemySupplySupportUnit(unit.type) || getUnitDefinition(unit.type).domain !== "Ground") {
    return false;
  }
  return unit.health < unit.maxHealth && (isEnemyBaseAttackCombatUnit(unit) || needsReconSupport(unit.type) || isSpecialUnit(unit.type));
}

function isEnemyBaseDefenseResponder(state: GameState, unit: UnitInstance): boolean {
  return unit.owner === "Enemy" && hexDistance(unit.coord, state.bases.Enemy) <= getEnemyBaseResponseRadius(state) && (getUnitDefinition(unit.type).humanBased || isEnemyBaseAttackCombatUnit(unit) || unit.type === "Anti-Air");
}

function isEnemyScarceCombatRole(state: GameState, unit: UnitInstance, allies: UnitInstance[]): boolean {
  if (unit.type === "Anti-Air" || unit.type === "Artillery" || unit.type === "Tank" || unit.type === "IFV") {
    return !allies.some((ally) => ally.type === unit.type);
  }
  if (isSpecialUnit(unit.type)) {
    return !allies.some((ally) => isSpecialUnit(ally.type));
  }
  return false;
}

function scoreEnemyBaseAreaAssaultAttackAction(
  state: GameState,
  unit: UnitInstance,
  target: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  if (
    !isEnemyBaseOperationPhase(plan.campaignPlan.phase) ||
    !isEnemyBaseAttackCombatUnit(unit) ||
    mission !== "Siege" ||
    !action.expectedOutcome ||
    !isPlayerBaseAreaAssaultTarget(state, target)
  ) {
    return 0;
  }

  const priority = scoreEnemyPlayerBaseAreaTargetPriority(state, unit, target, plan);
  const currentBaseDistance = hexDistance(unit.coord, state.bases.Player);
  const nextBaseDistance = hexDistance(finalCoord, state.bases.Player);
  const currentTargetDistance = hexDistance(unit.coord, target.coord);
  const nextTargetDistance = hexDistance(finalCoord, target.coord);
  const baseProgress = Math.max(0, currentBaseDistance - nextBaseDistance) * 110;
  const targetProgress = Math.max(0, currentTargetDistance - nextTargetDistance) * 62;
  const playerAreaPressure = isCoordInPlayerBaseAssaultArea(state, finalCoord) ? 320 : 0;
  const sequenceBonus = action.kind === "MoveThenAttack" ? 190 : action.kind === "Attack" ? 140 : action.kind === "AttackThenMove" ? 80 : 0;
  const usefulDamage = getUsefulExpectedDamage(target, action.expectedOutcome.expectedDamage);
  return priority * 0.7 + usefulDamage * 48 + action.expectedOutcome.killProbability * 960 + baseProgress + targetProgress + playerAreaPressure + sequenceBonus;
}

function scoreEnemyPostAttackRetreatMove(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  if (action.kind !== "Move" || !unit.hasAttackedThisDay || sameHex(finalCoord, unit.coord)) {
    return 0;
  }

  const currentReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, unit.coord, plan);
  const finalReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, finalCoord, plan);
  const reduction = currentReplyDamage - finalReplyDamage;
  const health = Math.max(1, unit.health);
  const value = getUnitInstanceValue(state, unit);
  const valueWeight = value >= 140 ? 4.2 : value >= 90 ? 3.2 : 2.35;
  const survivalSwing =
    (currentReplyDamage >= health ? 260 : currentReplyDamage >= health * 0.65 ? 130 : currentReplyDamage >= health * 0.35 ? 58 : 0) -
    (finalReplyDamage >= health ? 340 : finalReplyDamage >= health * 0.65 ? 150 : finalReplyDamage >= health * 0.35 ? 64 : 0);
  const safeLandingBonus = reduction > 0 && finalReplyDamage < health * 0.35 ? 52 : 0;
  const exposedLandingPenalty = finalReplyDamage > currentReplyDamage && finalReplyDamage >= health * 0.35 ? Math.min(180, (finalReplyDamage - currentReplyDamage) * 3.5) : 0;
  return reduction * valueWeight + survivalSwing + safeLandingBonus - exposedLandingPenalty;
}

function scoreEnemyTerritoryControlAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"]
): number {
  if (action.kind !== "Move" && action.kind !== "MoveThenAttack" && action.kind !== "AttackThenMove" && action.kind !== "MoveAttackRetreat") {
    return 0;
  }

  return getCachedEnemyTerritoryControlDelta(state, unit, finalCoord) * 5.5;
}

function getCachedEnemyControlledTerritoryCount(state: GameState): number {
  const cache = getEnemyEvaluationCache(state);
  if (cache.enemyControlledTerritoryCount === undefined) {
    cache.enemyControlledTerritoryCount = getOwnerControlledTerritoryCount(state, "Enemy");
  }
  return cache.enemyControlledTerritoryCount;
}

function getCachedEnemyTerritoryControlDelta(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"]
): number {
  const cache = getEnemyEvaluationCache(state);
  cache.enemyTerritoryControlDeltas ??= new Map();

  const key = `${unit.id}:${hexId(unit.coord)}:${hexId(finalCoord)}`;
  const cached = cache.enemyTerritoryControlDeltas.get(key);
  if (cached !== undefined) {
    return cached;
  }

  const current = getCachedEnemyControlledTerritoryCount(state);
  const projected = getOwnerControlledTerritoryCount(projectEnemyUnitCoordForScoring(state, unit, finalCoord), "Enemy");
  const delta = projected - current;
  cache.enemyTerritoryControlDeltas.set(key, delta);
  return delta;
}

function scoreEnemyPathDenial(state: GameState, unit: UnitInstance, finalCoord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  if (sameHex(unit.coord, finalCoord) || getUnitDefinition(unit.type).domain === "Air") {
    return 0;
  }

  const danger = estimatePlayerDangerAtPlanner(state, unit, finalCoord, plan) + estimateEnemyFogThreatAtPlanner(state, unit, finalCoord, plan) * 0.35;
  if (danger >= unit.health * 1.1 && !plan.objectiveImperatives.some((imperative) => imperative.unitId === unit.id)) {
    return 0;
  }

  const projectedState = projectEnemyUnitCoordForScoring(state, unit, finalCoord);
  const objectives = getEnemyPathDenialObjectives(state, plan);
  const playerCapturers = plan.playerIntel.filter((intel) => getUnitDefinition(intel.unit.type).humanBased);
  const distanceDelay = playerCapturers.reduce((score, intel) => {
    const playerUnit = { ...intel.unit, coord: { ...intel.predictedCoord } };
    return score + objectives.reduce((objectiveScore, objective) => {
      const currentPath = findMovementPath(state, playerUnit, objective, { allowFutureMovement: true })?.length ?? hexDistance(playerUnit.coord, objective);
      const blockedPath = findMovementPath(projectedState, playerUnit, objective, { allowFutureMovement: true })?.length ?? (sameHex(finalCoord, objective) ? currentPath + 3 : hexDistance(playerUnit.coord, objective));
      const delay = Math.max(0, blockedPath - currentPath);
      const nearObjective = Math.max(0, 6 - hexDistance(finalCoord, objective)) * 10;
      return objectiveScore + (delay * 30 + nearObjective * 0.55) * intel.confidence;
    }, 0);
  }, 0);

  const directGateBlock = (state.gates ?? []).reduce((score, gate) => {
    if (!sameHex(finalCoord, gate.coord)) {
      return score;
    }
    const playerPressure = gate.occupation.Player * 105 + plan.playerIntel.filter((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, gate.coord) <= 3).length * 45;
    return score + 120 + playerPressure;
  }, 0);
  const baseBlock = sameHex(finalCoord, state.bases.Enemy) && (state.baseOccupation.Enemy > 0 || plan.playerIntel.some((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, state.bases.Enemy) <= 2))
    ? 330
    : 0;
  const chokepoint = getPassableCoordsNear(state, finalCoord, 1).length <= 4 ? 45 : 0;
  const screening = getEnemyPathDenialScreeningScore(state, unit, finalCoord);
  return Math.min(420, distanceDelay + directGateBlock + baseBlock + chokepoint + screening);
}

function getEnemyPathDenialObjectives(state: GameState, plan: EnemyTurnPlan): UnitInstance["coord"][] {
  const gateObjectives = (state.gates ?? [])
    .filter((gate) => gate.owner === "Enemy" || gate.occupation.Player > 0 || gate.occupation.Enemy > 0 || plan.campaignPlan.mainEffortGateId === gate.id || plan.campaignPlan.secondaryGateId === gate.id)
    .map((gate) => gate.coord);
  return uniqueCoords([state.bases.Enemy, ...gateObjectives]);
}

function getEnemyPathDenialScreeningScore(state: GameState, unit: UnitInstance, finalCoord: UnitInstance["coord"]): number {
  return getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id) {
      return score;
    }
    const distance = hexDistance(finalCoord, ally.coord);
    if (distance > 2) {
      return score;
    }
    const valuableScreenedUnit =
      ally.type === "Artillery" ||
      isEnemySupplySupportUnit(ally.type) ||
      ally.health <= ally.maxHealth * 0.45 ||
      getUnitDefinition(ally.type).humanBased;
    return score + (valuableScreenedUnit ? Math.max(0, 3 - distance) * 32 : 0);
  }, 0);
}

function projectEnemyUnitCoordForScoring(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): GameState {
  return {
    ...state,
    units: state.units.map((candidate) =>
      candidate.id === unit.id ? { ...candidate, coord: { ...coord } } : candidate
    )
  };
}

function scoreEnemyActionOpportunityCost(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  danger: number
): number {
  let score = 0;
  const attackReady = !unit.hasAttackedThisDay && unit.placedDay !== state.day;
  const moved = !sameHex(finalCoord, unit.coord);

  if (attackReady && !action.targetId) {
    const currentAttack = estimateEnemyBestPotentialAttackValue(state, unit, plan, unit.coord);
    const finalAttack = !isMoveAttackExclusiveUnit(unit.type) ? estimateEnemyBestPotentialAttackValue(state, unit, plan, finalCoord) : 0;
    const bestAttack = Math.max(currentAttack, finalAttack);
    if (bestAttack > 0) {
      const dynamicCap = Math.max(480, Math.min(1600, bestAttack * 0.75));
      const multiplier = getEnemyOpportunityCostMultiplier(state, unit, plan, bestAttack);
      score -= Math.min(dynamicCap, (bestAttack * 0.32 + danger * 1.15) * multiplier);
    }
  }

  if (!moved && getRemainingMovementPoints(state, unit) > 0 && (action.kind === "Hold" || isMoveAttackExclusiveUnit(unit.type))) {
    const movementBenefit = estimateEnemyBestPureMovementBenefit(state, unit, plan);
    if (movementBenefit > 0) {
      score -= movementBenefit * (action.targetId && isMoveAttackExclusiveUnit(unit.type) ? 0.82 : 1);
    }
  }

  return score;
}

function getEnemyOpportunityCostMultiplier(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan, bestAttack: number): number {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  let multiplier = 1;
  const baseDefenseEmergency =
    state.baseOccupation.Enemy > 0 ||
    plan.playerIntel.some((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, state.bases.Enemy) <= 2);
  if (baseDefenseEmergency) {
    multiplier *= 1.45;
  }

  if (
    plan.campaignPlan.phase === "GateLockoutCombat" ||
    (state.gates ?? []).some((gate) => gate.occupation.Player > 0 || gate.occupation.Enemy > 0 || gate.owner !== "Enemy")
  ) {
    multiplier *= 1.25;
  }

  if (plan.campaignPlan.phase === "BaseAssault" || mission === "CaptureBase" || mission === "ProtectCapturer") {
    multiplier *= 1.25;
  }

  if (bestAttack >= 1200 || plan.objectiveImperatives.some((imperative) => imperative.unitId === unit.id && imperative.targetId)) {
    multiplier *= 1.2;
  } else if (bestAttack < 520 && !baseDefenseEmergency && plan.campaignPlan.phase !== "GateLockoutCombat") {
    multiplier *= 0.72;
  }

  return multiplier;
}

function estimateEnemyBestPotentialAttackValue(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  coord: UnitInstance["coord"]
): number {
  if (unit.hasAttackedThisDay) {
    return 0;
  }

  const attacker: UnitInstance = sameHex(coord, unit.coord)
    ? unit
    : {
        ...unit,
        coord: { ...coord },
        movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, coord)
      };
  return getEnemyPlannerAttackOptions(state, attacker, plan, {}, 3).reduce((best, attack) => {
    const usefulDamage = getUsefulExpectedDamage(attack.target, attack.outcome.expectedDamage);
    const damageValue = usefulDamage * 20 + attack.outcome.killProbability * 340;
    const materialValue = getUnitInstanceValue(state, attack.target) * attack.outcome.killProbability * 1.8;
    return Math.max(best, attack.score * 0.45 + damageValue + materialValue);
  }, 0);
}

function estimateEnemyBestPureMovementBenefit(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): number {
  const currentDanger = estimatePlayerDangerAtPlanner(state, unit, unit.coord, plan);
  const currentTerritory = getOwnerControlledTerritoryCount(state, "Enemy");
  return getEnemyLegalMoveCoords(state, unit).reduce((best, coord) => {
    if (!canMoveUnitTo(state, unit, coord)) {
      return best;
    }

    const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
    const territory = getOwnerControlledTerritoryCount(projectEnemyUnitCoordForScoring(state, unit, coord), "Enemy") - currentTerritory;
    const benefit =
      Math.max(0, getEnemyPlannerTaskProgressScore(state, unit, coord, plan)) +
      Math.max(0, currentDanger - danger) * 1.7 +
      scoreEnemyWeightedFogRevealFrom(state, unit, coord) * 1.2 +
      territory * 5.5 +
      getEnemyPlannerSupportScore(state, unit, coord) * 0.35;
    return Math.max(best, benefit);
  }, 0);
}

function getEnemyArmorGroundCommitmentRetreatPenalty(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  if (
    (action.kind !== "AttackThenMove" && action.kind !== "MoveAttackRetreat") ||
    !isEnemyArmorGroundCommitmentUnit(state, unit, plan)
  ) {
    return 0;
  }

  const objective = getEnemyArmorGroundCommitmentObjective(state, unit, plan);
  if (!objective) {
    return 0;
  }

  const commitmentCoord = action.kind === "MoveAttackRetreat" && action.moveTo ? action.moveTo : unit.coord;
  const commitmentDistance = hexDistance(commitmentCoord, objective);
  const finalDistance = hexDistance(finalCoord, objective);
  const lostGround = finalDistance - commitmentDistance;
  if (lostGround <= 0) {
    return 0;
  }

  const attackContext = action.targetId
    ? { targetId: action.targetId, expectedOutcome: action.expectedOutcome }
    : undefined;
  const commitmentReply = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, commitmentCoord, plan, attackContext);
  const finalReply = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, finalCoord, plan, attackContext);
  const survivalRetreat =
    commitmentReply >= unit.health * 0.9 &&
    finalReply <= Math.max(unit.health * 0.45, commitmentReply * 0.55);
  if (survivalRetreat) {
    return Math.max(0, lostGround - 1) * 90;
  }

  const currentDistance = hexDistance(unit.coord, objective);
  const resetsBehindStart = finalDistance >= currentDistance ? 160 : 0;
  const sequencePenalty = action.kind === "MoveAttackRetreat" ? 170 : 95;
  return lostGround * 260 + resetsBehindStart + sequencePenalty;
}

function scoreEnemyBaseCaptureClockAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  mission: EnemyMission,
  finalCoord: UnitInstance["coord"],
  danger: number,
  plan: EnemyTurnPlan
): number {
  if (!getUnitDefinition(unit.type).humanBased) {
    return 0;
  }

  let score = 0;
  const phaseWeights = getEnemyStrategicPhaseWeights(plan.strategicSnapshot.strategicPhase);
  const objective = mission === "CaptureBase" ? state.bases.Player : mission === "DefendBase" ? state.bases.Enemy : undefined;
  if (sameHex(finalCoord, state.bases.Player)) {
    const surviveBonus = danger < unit.health * 0.75 ? 220 : danger < unit.health ? 90 : -260;
    const clockBonus = state.baseOccupation.Player >= BASE_CAPTURE_DAYS - 1 ? 920 : 320 + state.baseOccupation.Player * 170;
    score += (clockBonus + surviveBonus) * phaseWeights.base;
  }

  if (state.baseOccupation.Enemy > 0 || plan.playerIntel.some((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, state.bases.Enemy) <= 2)) {
    const stoppedCapture =
      action.targetId &&
      getOwnerUnits(state, "Player").some((target) => target.id === action.targetId && getUnitDefinition(target.type).humanBased && sameHex(target.coord, state.bases.Enemy));
    if (stoppedCapture) {
      score += (720 + state.baseOccupation.Enemy * 180 + (action.expectedOutcome?.killProbability ?? 0) * 420) * phaseWeights.defense;
    } else if (mission === "DefendBase") {
      score += Math.max(0, getEnemyBaseResponseRadius(state) + 2 - hexDistance(finalCoord, state.bases.Enemy)) * 46 * phaseWeights.defense;
    }
  }

  if (objective) {
    const currentDistance = hexDistance(unit.coord, objective);
    const nextDistance = hexDistance(finalCoord, objective);
    if (!sameHex(finalCoord, objective) && !action.targetId) {
      score += (currentDistance - nextDistance) * 95 * (mission === "DefendBase" ? phaseWeights.defense : phaseWeights.base);
      if (nextDistance >= currentDistance && action.kind !== "Hold") {
        score -= 520;
      }
    }
  }

  return score;
}

function scoreEnemyBaseCaptureClockPreservation(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  danger: number,
  currentDanger: number,
  plan: EnemyTurnPlan
): number {
  if (!getUnitDefinition(unit.type).humanBased || state.baseOccupation.Player <= 0 || !sameHex(unit.coord, state.bases.Player)) {
    return 0;
  }

  if (sameHex(finalCoord, state.bases.Player)) {
    const survival = danger < unit.health * 0.75 ? 380 : danger < unit.health ? 140 : -520;
    return 1050 + state.baseOccupation.Player * 620 + survival;
  }

  if (isCaptureClockDepartureJustified(state, unit, action, finalCoord, danger, currentDanger, plan)) {
    return 0;
  }

  const almostCapturedPenalty = state.baseOccupation.Player >= BASE_CAPTURE_DAYS - 1 ? 4200 : state.baseOccupation.Player >= BASE_CAPTURE_DAYS - 2 ? 2500 : 900;
  return -(1800 + state.baseOccupation.Player * 850 + almostCapturedPenalty);
}

function scoreEnemyGateCaptureClockPreservation(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  danger: number,
  currentDanger: number,
  plan: EnemyTurnPlan
): number {
  if (!getUnitDefinition(unit.type).humanBased) {
    return 0;
  }

  const gate = (state.gates ?? []).find((candidate) => sameHex(candidate.coord, unit.coord) && candidate.owner !== "Enemy" && candidate.occupation.Enemy > 0);
  if (!gate) {
    return 0;
  }

  if (sameHex(finalCoord, gate.coord)) {
    const survival = danger < unit.health * 0.75 ? 320 : danger < unit.health ? 110 : -460;
    return 820 + gate.occupation.Enemy * 520 + survival;
  }

  if (isCaptureClockDepartureJustified(state, unit, action, finalCoord, danger, currentDanger, plan)) {
    return 0;
  }

  const almostCapturedPenalty = gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1 ? 3200 : gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 2 ? 1900 : 620;
  return -(1250 + gate.occupation.Enemy * 680 + almostCapturedPenalty);
}

function scoreEnemyBaseCaptureClockAcceleration(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  danger: number,
  plan: EnemyTurnPlan
): number {
  if (!getUnitDefinition(unit.type).humanBased || !ownerControlsBothGates(state, "Enemy")) {
    return 0;
  }

  const currentDistance = hexDistance(unit.coord, state.bases.Player);
  const nextDistance = hexDistance(finalCoord, state.bases.Player);
  if (sameHex(finalCoord, state.bases.Player)) {
    const activeClockBonus = state.baseOccupation.Player > 0 ? state.baseOccupation.Player * 560 : 0;
    const survival = danger < unit.health * 0.75 ? 260 : danger < unit.health ? 80 : -380;
    return 740 + activeClockBonus + survival;
  }

  if (state.baseOccupation.Player > 0 && nextDistance <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, finalCoord, state.bases.Player).moveRange) {
    return 280 + state.baseOccupation.Player * 180;
  }

  if (nextDistance < currentDistance && (plan.campaignPlan.phase === "BothGatesOwned" || plan.campaignPlan.phase === "BaseAssault" || plan.campaignPlan.phase === "BaseHold")) {
    return (currentDistance - nextDistance) * 105;
  }

  return 0;
}

function scoreEnemyGateCaptureClockAcceleration(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  danger: number,
  plan: EnemyTurnPlan
): number {
  if (!getUnitDefinition(unit.type).humanBased) {
    return 0;
  }

  const targetGate = chooseEnemyPlannerGateTargetForUnit(state, unit, plan) ??
    (state.gates ?? [])
      .filter((gate) => gate.owner !== "Enemy")
      .sort((first, second) => scoreEnemyGateCaptureObjective(state, unit.coord, second) - scoreEnemyGateCaptureObjective(state, unit.coord, first))[0];
  if (!targetGate || targetGate.owner === "Enemy") {
    return 0;
  }

  const currentDistance = hexDistance(unit.coord, targetGate.coord);
  const nextDistance = hexDistance(finalCoord, targetGate.coord);
  const safeForRecapture = isGateSafeForRecapture(state, targetGate, unit, plan);
  if (sameHex(finalCoord, targetGate.coord)) {
    const survival = danger < unit.health * 0.75 ? 240 : danger < unit.health ? 70 : -340;
    if (!safeForRecapture) {
      return -560 + survival * 0.12;
    }
    return 640 + targetGate.occupation.Enemy * 470 + survival;
  }

  if (!safeForRecapture) {
    return scoreEnemyUnsafeGateRecaptureStaging(state, unit, finalCoord, targetGate, plan, danger);
  }

  if (targetGate.occupation.Enemy > 0 && nextDistance <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, finalCoord, targetGate.coord).moveRange) {
    return 220 + targetGate.occupation.Enemy * 145;
  }

  if (nextDistance < currentDistance && isEnemyGateContinuityPhase(plan.campaignPlan.phase)) {
    return (currentDistance - nextDistance) * 92;
  }

  return 0;
}

function scoreEnemyUnsafeGateRecaptureStaging(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"],
  gate: GateState,
  plan: EnemyTurnPlan,
  danger: number
): number {
  if (gate.owner === "Enemy" || sameHex(finalCoord, gate.coord) || isGateSafeForRecapture(state, gate, unit, plan)) {
    return 0;
  }

  const distanceToGate = hexDistance(finalCoord, gate.coord);
  if (distanceToGate < 1 || distanceToGate > 5) {
    return 0;
  }

  const moveRange = Math.max(1, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, finalCoord, gate.coord).moveRange);
  const friendlyCombatCover = getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id || ally.health / Math.max(1, ally.maxHealth) <= 0.35 || !isEnemyGateClearingCoverUnit(ally.type)) {
      return score;
    }

    const allyGateDistance = hexDistance(ally.coord, gate.coord);
    const allyDistance = hexDistance(finalCoord, ally.coord);
    const forwardCover = allyGateDistance < distanceToGate ? 78 : 0;
    const closeCover = allyDistance <= 1 ? 82 : allyDistance <= 2 ? 54 : allyDistance <= 3 ? 24 : 0;
    const fireSupport = allyGateDistance <= 5 ? getUnitInstanceValue(state, ally) * 0.28 : 0;
    return score + forwardCover + closeCover + fireSupport;
  }, 0);
  if (friendlyCombatCover <= 0) {
    return 0;
  }

  const readyToEnter = distanceToGate <= moveRange + 1 ? 96 : distanceToGate <= moveRange + 3 ? 42 : 0;
  const preferredBand = distanceToGate >= 2 && distanceToGate <= 4 ? 74 : 18;
  const survival = danger < unit.health * 0.5 ? 64 : danger < unit.health ? 22 : -120;
  return Math.min(420, friendlyCombatCover + readyToEnter + preferredBand + survival);
}

function isEnemyGateClearingCoverUnit(unitType: UnitType): boolean {
  return (
    unitType === "Tank" ||
    unitType === "IFV" ||
    unitType === "Artillery" ||
    unitType === "Reaper" ||
    unitType === "Bomber" ||
    unitType === "Anti-Air" ||
    unitType === "Ghost" ||
    unitType === "Operator"
  );
}

function scoreEnemyReplacementCapturerAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  danger: number,
  plan: EnemyTurnPlan
): { backupCapturerValue: number; replacementDistance: number } {
  if (!getUnitDefinition(unit.type).humanBased || unit.health <= 0) {
    return { backupCapturerValue: 0, replacementDistance: 0 };
  }

  const contexts = getEnemyReplacementCapturerContexts(state, plan);
  if (!contexts.length) {
    return { backupCapturerValue: 0, replacementDistance: 0 };
  }

  let backupCapturerValue = 0;
  let replacementDistance = 0;
  for (const context of contexts) {
    if (!isEnemyReplacementCapturerCandidateForContext(state, unit, context, plan)) {
      continue;
    }

    const existingBackup = getEnemyReplacementCapturerCountForContext(state, unit.id, context, plan);
    const distance = hexDistance(finalCoord, context.coord);
    const moveRange = Math.max(1, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, finalCoord, context.coord).moveRange);
    const turnsToReplace = sameHex(finalCoord, context.coord) ? 0 : Math.ceil(distance / moveRange);
    const healthRatio = unit.health / Math.max(1, unit.maxHealth);
    const assignedBackup = context.backupCapturerId === unit.id;
    const fragileMultiplier = existingBackup === 0 ? 1.35 : 0.75;
    const phaseMultiplier = context.kind === "Base" ? getEnemyStrategicPhaseWeights(plan.campaignPlan.phase).base : getEnemyStrategicPhaseWeights(plan.campaignPlan.phase).gate;
    const activeClockMultiplier = context.activeClock > 0 ? 1 + context.activeClock * 0.22 : 1;
    const survivability = danger < unit.health * 0.75 ? 1 : danger < unit.health ? 0.65 : 0.25;
    const replacementWindowScore =
      turnsToReplace <= 1
        ? 760
        : turnsToReplace === 2
          ? 380
          : turnsToReplace === 3
            ? 140
            : -Math.min(360, (turnsToReplace - 3) * 95);
    const continuousDistanceScore = Math.max(0, moveRange * 4 - distance) * 22 - distance * 6;
    const valueScore = (220 + unit.health * 12 + getUnitInstanceValue(state, unit) * 0.45 + (assignedBackup ? 360 : 0)) * fragileMultiplier * survivability;
    const distanceScore = (replacementWindowScore + continuousDistanceScore) * fragileMultiplier * activeClockMultiplier;

    if (sameHex(finalCoord, context.coord) && context.activeCapturerId && context.activeCapturerId !== unit.id) {
      replacementDistance -= 420;
      continue;
    }

    backupCapturerValue += valueScore * phaseMultiplier;
    replacementDistance += distanceScore * phaseMultiplier;
    if (assignedBackup && action.kind === "Hold" && turnsToReplace > 1) {
      replacementDistance -= 260 * phaseMultiplier;
    }
  }

  return { backupCapturerValue, replacementDistance };
}

interface EnemyReplacementCapturerContext {
  kind: "Gate" | "Base";
  coord: UnitInstance["coord"];
  gateId?: GateState["id"];
  activeCapturerId?: string;
  backupCapturerId?: string;
  activeClock: number;
}

function getEnemyReplacementCapturerContexts(state: GameState, plan: EnemyTurnPlan): EnemyReplacementCapturerContext[] {
  const contexts: EnemyReplacementCapturerContext[] = [];
  const basePackage = plan.campaignPlan.baseAssaultPackage;
  const baseCapturer =
    getEnemyBaseHoldCapturer(state, plan) ??
    (basePackage.capturerId ? getUnitById(state, basePackage.capturerId) : undefined);
  if (
    state.baseOccupation.Player > 0 ||
    ownerControlsBothGates(state, "Enemy") ||
    plan.campaignPlan.phase === "BaseAssault" ||
    plan.campaignPlan.phase === "BaseHold"
  ) {
    contexts.push({
      kind: "Base",
      coord: { ...state.bases.Player },
      activeCapturerId: baseCapturer?.owner === "Enemy" && getUnitDefinition(baseCapturer.type).humanBased ? baseCapturer.id : undefined,
      backupCapturerId: basePackage.backupCapturerId,
      activeClock: state.baseOccupation.Player
    });
  }

  for (const gate of state.gates ?? []) {
    const lane = plan.campaignPlan.laneTaskForces[gate.id];
    const activeGateCapturer =
      getOwnerUnits(state, "Enemy").find((candidate) => getUnitDefinition(candidate.type).humanBased && sameHex(candidate.coord, gate.coord)) ??
      (lane.principalCapturerId ? getUnitById(state, lane.principalCapturerId) : undefined);
    if (gate.owner !== "Enemy" || gate.occupation.Enemy > 0 || lane.principalCapturerId || lane.backupCapturerId) {
      contexts.push({
        kind: "Gate",
        coord: { ...gate.coord },
        gateId: gate.id,
        activeCapturerId: activeGateCapturer?.owner === "Enemy" && getUnitDefinition(activeGateCapturer.type).humanBased ? activeGateCapturer.id : undefined,
        backupCapturerId: lane.backupCapturerId,
        activeClock: gate.occupation.Enemy
      });
    }
  }

  return contexts;
}

function isEnemyReplacementCapturerCandidateForContext(
  state: GameState,
  unit: UnitInstance,
  context: EnemyReplacementCapturerContext,
  plan: EnemyTurnPlan
): boolean {
  if (!getUnitDefinition(unit.type).humanBased || unit.id === context.activeCapturerId) {
    return false;
  }
  const role = plan.rolesByUnitId[unit.id];
  if (context.kind === "Base") {
    return (
      unit.id === context.backupCapturerId ||
      role === "CaptureBase" ||
      role === "ProtectCapturer" ||
      plan.campaignPlan.baseAssaultPackage.blockerEscortIds.includes(unit.id)
    );
  }
  return (
    unit.id === context.backupCapturerId ||
    plan.campaignPlan.assignedGateByUnitId[unit.id] === context.gateId ||
    role === "CaptureGate" ||
    role === "ShadowCapturer" ||
    role === "EscortCapture"
  );
}

function getEnemyReplacementCapturerCountForContext(
  state: GameState,
  excludedUnitId: string,
  context: EnemyReplacementCapturerContext,
  plan: EnemyTurnPlan
): number {
  return getOwnerUnits(state, "Enemy").filter((ally) => {
    if (ally.id === excludedUnitId || ally.id === context.activeCapturerId || !getUnitDefinition(ally.type).humanBased) {
      return false;
    }
    if (!isEnemyReplacementCapturerCandidateForContext(state, ally, context, plan)) {
      return false;
    }
    const distance = hexDistance(ally.coord, context.coord);
    const moveRange = Math.max(1, getEffectiveUnitStats(state, ally.owner, ally.type, ally.level, ally.coord, context.coord).moveRange);
    return Math.ceil(distance / moveRange) <= 1;
  }).length;
}

function isCaptureClockDepartureJustified(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  danger: number,
  currentDanger: number,
  plan: EnemyTurnPlan
): boolean {
  if (currentDanger >= unit.health && danger <= unit.health * 0.45) {
    return true;
  }
  if (currentDanger >= unit.health * 1.35 && danger < currentDanger * 0.55) {
    return true;
  }
  if (shouldEnemyGateLockoutPreserveDamagedCombatPower(state, unit)) {
    const repairCoord = getNearestEnemyRepairCoord(state, unit.coord, unit.type);
    const repairProgress = hexDistance(finalCoord, repairCoord) < hexDistance(unit.coord, repairCoord);
    const saferPosition = danger < currentDanger || danger < unit.health * 0.65;
    if (repairProgress || saferPosition) {
      return true;
    }
  }
  return plan.objectiveImperatives.some((imperative) =>
    imperative.terminal > 0 &&
    imperative.unitId === unit.id &&
    (
      (imperative.actionKind === "Hold" && action.kind === "Hold") ||
      (imperative.actionKind === "Move" && action.moveTo && imperative.targetCoord && sameHex(action.moveTo, imperative.targetCoord)) ||
      (imperative.targetId && action.targetId === imperative.targetId)
    )
  );
}

function scoreEnemyBaseHoldSurvivalAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  danger: number,
  plan: EnemyTurnPlan
): number {
  const capturer = getEnemyBaseHoldCapturer(state, plan);
  if (!capturer) {
    return 0;
  }

  const threats = getBaseHoldThreateningPlayerUnits(state, capturer, plan);
  let score = 0;
  if (unit.id === capturer.id) {
    if (sameHex(finalCoord, state.bases.Player) && action.kind === "Hold") {
      score += 2200 + state.baseOccupation.Player * 650 - danger * 6;
    } else {
      score -= 5200 + state.baseOccupation.Player * 900;
    }
    return score;
  }

  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  if (target && target.owner === "Player" && threats.some((threat) => threat.id === target.id)) {
    const usefulDamage = getUsefulExpectedDamage(target, action.expectedOutcome?.expectedDamage ?? 0);
    const lethal = (action.expectedOutcome?.expectedDamage ?? 0) >= target.health;
    score +=
      1450 +
      (action.expectedOutcome?.killProbability ?? 0) * 2600 +
      usefulDamage * 95 +
      (lethal ? 1250 : 0);
  }

  score += scoreEnemyBaseHoldProtectionCoord(state, unit, finalCoord, capturer, plan);

  if (getUnitDefinition(unit.type).humanBased && !sameHex(finalCoord, state.bases.Player)) {
    const replacementDistance = hexDistance(finalCoord, state.bases.Player);
    const replacementReach = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, finalCoord, state.bases.Player).moveRange;
    if (replacementDistance <= replacementReach) {
      score += unit.id === plan.campaignPlan.baseAssaultPackage.backupCapturerId ? 1150 : 720;
    } else if (replacementDistance <= replacementReach + 2) {
      score += 280;
    }
  }

  const adjacentBodyguards = getOwnerUnits(state, "Enemy").filter((ally) => ally.id !== capturer.id && ally.id !== unit.id && hexDistance(ally.coord, capturer.coord) === 1).length;
  if (hexDistance(finalCoord, capturer.coord) === 1) {
    score += Math.max(0, 2 - adjacentBodyguards) * 260;
  }

  if (threats.length > 0 && action.kind === "Hold" && !sameHex(finalCoord, state.bases.Player)) {
    score -= 320;
  }

  return score;
}

function scoreEnemyGateCaptureClockAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  mission: EnemyMission,
  gate: GateState,
  finalCoord: UnitInstance["coord"],
  danger: number,
  plan: EnemyTurnPlan
): number {
  if (!getUnitDefinition(unit.type).humanBased) {
    return 0;
  }

  let score = 0;
  const phaseWeights = getEnemyStrategicPhaseWeights(plan.strategicSnapshot.strategicPhase);
  const hostileOrNeutralGate = gate.owner !== "Enemy";
  const safeForRecapture = !hostileOrNeutralGate || isGateSafeForRecapture(state, gate, unit, plan);
  if (sameHex(finalCoord, gate.coord)) {
    const surviveBonus = danger < unit.health * 0.75 ? 180 : danger < unit.health ? 70 : -220;
    const occupyingOwnedGate = gate.owner === "Enemy";
    const createCapture = !occupyingOwnedGate ? 290 + gate.occupation.Enemy * 190 - gate.occupation.Player * 150 : 0;
    const defendOwnedGate = occupyingOwnedGate ? 120 + gate.occupation.Player * 220 : 0;
    if (!safeForRecapture) {
      score += (-720 + surviveBonus * 0.15) * phaseWeights.gate;
    } else {
      score += (createCapture + defendOwnedGate + surviveBonus) * phaseWeights.gate;
    }
    if (!occupyingOwnedGate && safeForRecapture && gate.occupation.Enemy >= GATE_CAPTURE_DAYS - 1) {
      score += 780 * phaseWeights.gate;
    }
  }

  const playerCapturing = gate.occupation.Player > 0 || plan.playerIntel.some(
    (intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, gate.coord) <= 1
  );
  if (playerCapturing) {
    const stoppedCapture =
      action.targetId &&
      getOwnerUnits(state, "Player").some((target) => target.id === action.targetId && getUnitDefinition(target.type).humanBased && sameHex(target.coord, gate.coord));
    if (stoppedCapture) {
      score += (650 + gate.occupation.Player * 260 + (action.expectedOutcome?.killProbability ?? 0) * 360) * phaseWeights.gate;
    } else if (mission === "DefendGate") {
      score += Math.max(0, 7 - hexDistance(finalCoord, gate.coord)) * 58 * phaseWeights.gate;
    }
  }

  if (mission === "CaptureGate" || mission === "DefendGate") {
    const target = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    if (target && target.id === gate.id && !sameHex(finalCoord, gate.coord) && !action.targetId) {
      const currentDistance = hexDistance(unit.coord, gate.coord);
      const nextDistance = hexDistance(finalCoord, gate.coord);
      if (!safeForRecapture && mission === "CaptureGate") {
        score += (Math.max(0, currentDistance - nextDistance) * 24 + scoreEnemyUnsafeGateRecaptureStaging(state, unit, finalCoord, gate, plan, danger)) * phaseWeights.gate;
      } else {
        score += (currentDistance - nextDistance) * 110 * phaseWeights.gate;
      }
      if (nextDistance >= currentDistance && action.kind !== "Hold") {
        score -= 620;
      }
    }
  }

  if (state.difficulty === "Hard" && gate.owner !== "Enemy") {
    const wouldCompleteBothGateControl = (state.gates ?? []).filter((candidate) => candidate.id !== gate.id).every((candidate) => candidate.owner === "Enemy");
    if (wouldCompleteBothGateControl) {
      const lockout = getEnemyGateLockoutOpportunityScore(state, gate, plan.playerIntel);
      score += (240 + lockout.total * 1.15) * phaseWeights.gate;
    }
  }

  return score;
}

function scoreEnemyGateLockoutClearAction(
  state: GameState,
  target: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan
): number {
  if (state.difficulty !== "Hard" || target.owner !== "Player" || !action.expectedOutcome) {
    return 0;
  }

  const gate =
    (state.gates ?? []).find((candidate) => candidate.owner !== "Enemy" && sameHex(candidate.coord, target.coord)) ??
    (state.gates ?? [])
      .filter((candidate) => candidate.owner !== "Enemy" && isGateClearanceTarget(state, target, candidate, plan))
      .sort((first, second) => getEnemyGateTheatreTargetPriority(state, target, second) - getEnemyGateTheatreTargetPriority(state, target, first) || first.id.localeCompare(second.id))[0];
  if (!gate) {
    return 0;
  }

  const lockout = getEnemyGateLockoutOpportunityScore(state, gate, plan.playerIntel);
  if (lockout.total <= 0) {
    return 0;
  }

  const blockerBonus = getUnitDefinition(target.type).humanBased ? 180 : isGateClearanceTarget(state, target, gate, plan) ? 150 : 90;
  const usefulDamage = getUsefulExpectedDamage(target, action.expectedOutcome.expectedDamage);
  const clearProbability = Math.max(action.expectedOutcome.killProbability, Math.min(1, usefulDamage / Math.max(1, target.health)) * 0.55);
  return (lockout.total * 0.82 + blockerBonus + usefulDamage * 18) * clearProbability;
}

function scoreEnemyGateTheatreDefenseAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  if (state.difficulty !== "Hard" || mission !== "DefendGate") {
    return 0;
  }

  const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
  if (!gate) {
    return 0;
  }

  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  const phaseWeights = getEnemyStrategicPhaseWeights(plan.strategicSnapshot.strategicPhase);
  let score = 0;
  if (target && isEnemyGateTheatreDefenseTarget(state, target, gate, plan)) {
    const priority = Math.max(130, getEnemyGateTheatreTargetPriority(state, target, gate));
    const clearValue = isGateClearanceTarget(state, target, gate, plan) ? 150 : 0;
    const reinforcementCutoff = isPlayerGateReinforcementApproach(state, target.coord, gate) ? 110 : 0;
    const expectedDamage = getUsefulExpectedDamage(target, action.expectedOutcome?.expectedDamage ?? 0);
    const killProbability = action.expectedOutcome?.killProbability ?? 0;
    score += priority * 0.65 + clearValue + reinforcementCutoff + expectedDamage * 18 + killProbability * 420;
  }

  const currentPosition = scoreEnemyGateTheatreDefensePosition(state, unit, unit.coord, gate, plan);
  const finalPosition = scoreEnemyGateTheatreDefensePosition(state, unit, finalCoord, gate, plan);
  if (action.kind === "Hold" && finalPosition > 0) {
    score += finalPosition * 0.78;
  } else {
    score += Math.max(-110, finalPosition - currentPosition) * 1.15 + finalPosition * 0.18;
  }

  if (!getUnitDefinition(unit.type).humanBased && sameHex(finalCoord, gate.coord) && gate.occupation.Player <= 0) {
    score -= 140;
  }

  return score * phaseWeights.defense;
}

function scoreEnemyPlannerPosition(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): number {
  const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo: coord }, reservedDestinations, reservedExpectedDamage);
  return action.breakdown.total;
}

function getEnemyFrontLineStandoffPenalty(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  mission: EnemyMission
): number {
  if (
    unit.owner !== "Enemy" ||
    ownerControlsBothGates(state, "Enemy") ||
    mission === "CaptureGate" ||
    mission === "DefendGate" ||
    isEnemyGateLockoutClearingMission(mission) ||
    mission === "DefendBase" ||
    mission === "BaseSentry" ||
    mission === "Repair"
  ) {
    return 0;
  }

  const playerLineRow = getFrontLineRows(state).playerLineRow;
  const rowsFromBlockedLine = playerLineRow - coord.r;
  if (rowsFromBlockedLine < 1 || rowsFromBlockedLine > 2) {
    return 0;
  }

  const playerThreat = getPlayerIntelForEnemy(state).reduce((threat, intel) => {
    const distance = hexDistance(coord, intel.predictedCoord);
    return threat + (distance <= getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, intel.predictedCoord, coord).attackRange + 1 ? intel.confidence : 0);
  }, 0);
  const exposure = rowsFromBlockedLine === 1 ? 900 : 140;
  return exposure + Math.min(120, playerThreat * 42);
}

function scoreEnemyFrontLineTrapAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  if (state.difficulty !== "Hard" || unit.owner !== "Enemy" || !getUnitDefinition(unit.type).humanBased || ownerControlsBothGates(state, "Enemy")) {
    return 0;
  }
  const gate = (state.gates ?? []).find((candidate) => candidate.owner === "Player" && sameHex(candidate.coord, finalCoord));
  if (!gate) {
    return 0;
  }

  const trappedValue = estimatePlayerFrontLineAttritionTrapValue(state, plan);
  if (trappedValue <= 0) {
    return 0;
  }
  const progressAfterAction = sameHex(unit.coord, gate.coord) && action.kind === "Hold"
    ? Math.min(GATE_CAPTURE_DAYS, gate.occupation.Enemy + 1)
    : Math.max(1, gate.occupation.Enemy);
  const progressRatio = progressAfterAction / GATE_CAPTURE_DAYS;
  const completionBonus = progressAfterAction >= GATE_CAPTURE_DAYS ? 420 : progressAfterAction >= GATE_CAPTURE_DAYS - 1 ? 260 : 90;
  const tempoBonus = Math.max(0, 4 - hexDistance(finalCoord, state.bases.Enemy)) * 18 + getEnemyStrategicAssessment(state).gateLockoutLeverage * 0.22;
  return trappedValue * (0.42 + progressRatio * 0.58) + completionBonus + tempoBonus;
}

function estimatePlayerFrontLineAttritionTrapValue(state: GameState, plan: EnemyTurnPlan): number {
  const currentlySafeFromAttrition = ownerControlsBothGates(state, "Player");
  const intelValue = plan.playerIntel.reduce((score, intel) => {
    if (!isCoordPastEnemyFrontLine(state, "Player", intel.predictedCoord)) {
      return score;
    }
    const value = getUnitInstanceValue(state, intel.unit);
    const projectedDamage = Math.max(1, Math.ceil(intel.unit.health * FRONT_LINE_ATTRITION_PERCENT));
    const materialDamage = Math.min(value, projectedDamage * 9 + value * 0.28);
    const tempo = getUnitDefinition(intel.unit.type).humanBased ? 80 : value > 120 ? 120 : 45;
    return score + (materialDamage + tempo) * intel.confidence;
  }, 0);
  return currentlySafeFromAttrition ? intelValue : intelValue * 0.35;
}

function getEnemyFrontLineOverextensionRisk(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  if (unit.owner !== "Enemy" || state.difficulty !== "Hard" || !ownerControlsBothGates(state, "Enemy") || !isCoordPastEnemyFrontLine(state, "Enemy", coord)) {
    return 0;
  }
  const gateLossRisk = estimateEnemyBothGateControlLossRisk(state, plan);
  if (gateLossRisk <= 0) {
    return 0;
  }
  const baseClockJustification = getEnemyBaseCaptureClockJustification(state, unit, coord, mission);
  const value = getUnitInstanceValue(state, unit);
  const attritionDamage = Math.max(1, Math.ceil(unit.health * FRONT_LINE_ATTRITION_PERCENT));
  const attritionCost = value * 0.34 + attritionDamage * 8;
  const expensiveMultiplier = value >= 140 ? 1.55 : value >= 95 ? 1.2 : 0.75;
  const distancePastLine = Math.max(0, coord.r - getFrontLineRows(state).playerLineRow);
  const exposure = attritionCost * expensiveMultiplier + distancePastLine * 18;
  return Math.max(0, exposure * gateLossRisk - baseClockJustification);
}

function scoreEnemyOpponentProfileTacticalCounter(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  if (state.difficulty !== "Hard") {
    return 0;
  }

  const profile = plan.doctrine.opponentProfile ?? plan.strategicSnapshot.opponentProfile;
  let score = 0;
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;

  if (profile.kind === "GateRusher" || profile.gateRush >= 0.62) {
    if (target && getUnitDefinition(target.type).humanBased && isCoordNearAnyGate(state, target.coord, 3)) {
      score += 260 + (action.expectedOutcome?.killProbability ?? 0) * 520 + getUsefulExpectedDamage(target, action.expectedOutcome?.expectedDamage ?? 0) * 42;
    }
    const threatenedGate = chooseEnemyGateDefenseObjective(state, unit.coord);
    if (threatenedGate) {
      const currentDistance = hexDistance(unit.coord, threatenedGate.coord);
      const nextDistance = hexDistance(finalCoord, threatenedGate.coord);
      score += Math.max(0, currentDistance - nextDistance) * 72;
      if (mission === "DefendGate" && sameHex(finalCoord, threatenedGate.coord)) {
        score += 180;
      }
    }
  }

  if (profile.kind === "Turtle" || profile.turtle >= 0.58) {
    if (isReconUnit(unit.type)) {
      score += getEnemyPlannerInformationGain(state, unit, finalCoord) * 1.4;
      if (isCoordNearAnyGate(state, finalCoord, 4)) {
        score += 80;
      }
    }
    if (!ownerControlsBothGates(state, "Enemy")) {
      const gate = chooseGateObjective(state, "Enemy", unit.coord, unit, plan);
      if (gate) {
        score += Math.max(0, hexDistance(unit.coord, gate.coord) - hexDistance(finalCoord, gate.coord)) * 58;
      }
    } else {
      score += Math.max(0, hexDistance(unit.coord, state.bases.Player) - hexDistance(finalCoord, state.bases.Player)) * (mission === "CaptureBase" ? 82 : 36);
    }
  }

  if (profile.kind === "AirHeavy" || profile.airBias >= 0.5) {
    if (target && getUnitDefinition(target.type).domain === "Air" && canUnitTargetUnit(unit.type, target.type)) {
      score += 180 + getUnitInstanceValue(state, target) * 0.6 + (action.expectedOutcome?.killProbability ?? 0) * 420;
    }
    if (canCounterHighAltitudeAir(unit.type)) {
      const highAltitudeThreat = getPlayerIntelForEnemy(state)
        .filter((intel) => isHighAltitudeAirUnit(intel.unit.type))
        .sort((first, second) => hexDistance(finalCoord, first.predictedCoord) - hexDistance(finalCoord, second.predictedCoord))[0];
      if (highAltitudeThreat) {
        score += Math.max(0, 10 - hexDistance(finalCoord, highAltitudeThreat.predictedCoord)) * 34;
      }
    }
    score -= getEnemyUnsupportedGroundClusterPenalty(state, unit, finalCoord);
  }

  if (profile.kind === "FastSpecial" || profile.fastSpecial >= 0.58) {
    if (target && isSpecialUnit(target.type)) {
      score += 190 + getUnitInstanceValue(state, target) * 0.55 + (action.expectedOutcome?.killProbability ?? 0) * 460;
    }
    if (mission === "BaseSentry" || mission === "DefendBase") {
      score += Math.max(0, getEnemyBaseResponseRadius(state) + 4 - hexDistance(finalCoord, state.bases.Enemy)) * 24;
    }
  }

  return score;
}

function scoreEnemyStrategyPlaybookTacticalBehavior(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  if (state.difficulty !== "Hard") {
    return 0;
  }

  const playbook = plan.doctrine.strategyPlaybook;
  let score = 0;
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;

  if (playbook.requiredBehaviors.includes("WinHoldGates")) {
    const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission) ?? chooseGateObjective(state, "Enemy", unit.coord, unit, plan);
    if (gate) {
      const progress = hexDistance(unit.coord, gate.coord) - hexDistance(finalCoord, gate.coord);
      score += Math.max(0, progress) * 84 * playbook.gateEconomyPriority;
      if (sameHex(finalCoord, gate.coord) && getUnitDefinition(unit.type).humanBased) {
        score += (gate.owner === "Enemy" ? 260 : 340) * playbook.gateEconomyPriority;
      }
      if (target && isEnemyTargetNearObjective(state, target, gate.coord)) {
        score += (240 + (action.expectedOutcome?.killProbability ?? 0) * 520) * playbook.gateEconomyPriority;
      }
    }
  }

  if (playbook.requiredBehaviors.includes("DenyPlayerAir")) {
    if (target && getUnitDefinition(target.type).domain === "Air" && canUnitTargetUnit(unit.type, target.type)) {
      score += 230 + getUnitInstanceValue(state, target) * 0.7 + (action.expectedOutcome?.killProbability ?? 0) * 520;
    }
    if (canCounterAir(unit.type)) {
      const airThreat = getPlayerIntelForEnemy(state)
        .filter((intel) => getUnitDefinition(intel.unit.type).domain === "Air")
        .filter((intel) => !isHighAltitudeAirUnit(intel.unit.type) || canCounterHighAltitudeAir(unit.type))
        .sort((first, second) => hexDistance(finalCoord, first.predictedCoord) - hexDistance(finalCoord, second.predictedCoord))[0];
      if (airThreat) {
        score += Math.max(0, 9 - hexDistance(finalCoord, airThreat.predictedCoord)) * 28 * playbook.airCounterPriority;
      }
    }
  }

  if (playbook.requiredBehaviors.includes("DelayObjectiveClock")) {
    const clockTarget = target && getUnitDefinition(target.type).humanBased && isPlayerObjectiveClockThreat(state, target, plan);
    if (clockTarget) {
      score += 260 + (action.expectedOutcome?.killProbability ?? 0) * 560 + getUsefulExpectedDamage(target, action.expectedOutcome?.expectedDamage ?? 0) * 44;
    } else if (action.targetId && !target) {
      score -= 120;
    } else if (action.targetId && target && !isPlayerObjectiveClockThreat(state, target, plan)) {
      score -= 80;
    }
    const threatenedObjective = choosePlayerObjectiveClockThreatCoord(state, plan);
    if (threatenedObjective) {
      score += Math.max(0, hexDistance(unit.coord, threatenedObjective) - hexDistance(finalCoord, threatenedObjective)) * 48;
    }
  }

  return score;
}

function scoreEnemyFireSupportCenterStagingAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  if (
    (unit.type !== "Artillery" && unit.type !== "Anti-Air") ||
    !isHardCenterSupportDoctrineActive(state, plan) ||
    shouldEnemyAttemptRepairRetreat(state, unit)
  ) {
    return 0;
  }

  const target = getEnemyCenterSupportStagingCoord(state, plan);
  const currentDistance = hexDistance(unit.coord, target);
  const nextDistance = hexDistance(finalCoord, target);
  if (currentDistance <= 1) {
    return nextDistance <= 1 ? 80 : -120;
  }

  const progress = currentDistance - nextDistance;
  const attacksNow = Boolean(action.targetId && action.expectedOutcome);
  const progressScore = progress * (attacksNow ? 48 : 150);
  const usefulBand = nextDistance <= 2 ? 130 : nextDistance <= 4 ? 70 : 0;
  const noMansLandBonus = getBattlefieldArea(state, finalCoord) === "No Man's Land" ? 70 : 0;
  const lostGroundPenalty = progress < 0 && !attacksNow ? Math.abs(progress) * 190 + 120 : 0;
  const holdPenalty = action.kind === "Hold" && currentDistance > 2 && !attacksNow ? 180 : 0;
  return progressScore + usefulBand + noMansLandBonus - lostGroundPenalty - holdPenalty;
}

function isPlayerObjectiveClockThreat(state: GameState, target: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (target.owner !== "Player" || !getUnitDefinition(target.type).humanBased) {
    return false;
  }
  if (sameHex(target.coord, state.bases.Enemy) || hexDistance(target.coord, state.bases.Enemy) <= getEnemyBaseResponseRadius(state)) {
    return true;
  }
  return (state.gates ?? []).some((gate) => gate.owner === "Enemy" && (gate.occupation.Player > 0 || (plan.strategicSnapshot.predictedGatePressure[gate.id] ?? 0) > 55) && hexDistance(target.coord, gate.coord) <= 2);
}

function choosePlayerObjectiveClockThreatCoord(state: GameState, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const baseThreat = getEnemyBaseThreat(state);
  if (baseThreat && getUnitDefinition(baseThreat.type).humanBased) {
    return baseThreat.coord;
  }
  const gate = (state.gates ?? [])
    .filter((candidate) => candidate.owner === "Enemy" && (candidate.occupation.Player > 0 || (plan.strategicSnapshot.predictedGatePressure[candidate.id] ?? 0) > 55))
    .sort((first, second) => (second.occupation.Player + (plan.strategicSnapshot.predictedGatePressure[second.id] ?? 0) * 0.01) - (first.occupation.Player + (plan.strategicSnapshot.predictedGatePressure[first.id] ?? 0) * 0.01))[0];
  return gate?.coord;
}

function isCoordNearAnyGate(state: GameState, coord: UnitInstance["coord"], radius: number): boolean {
  return (state.gates ?? []).some((gate) => hexDistance(coord, gate.coord) <= radius);
}

function getEnemyUnsupportedGroundClusterPenalty(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  if (getUnitDefinition(unit.type).domain !== "Ground" || canCounterAir(unit.type)) {
    return 0;
  }

  const nearbyGroundAllies = getOwnerUnits(state, "Enemy").filter(
    (ally) => ally.id !== unit.id && getUnitDefinition(ally.type).domain === "Ground" && hexDistance(ally.coord, coord) <= 2
  );
  if (nearbyGroundAllies.length < 2) {
    return 0;
  }

  const nearbyAntiAirCover = getOwnerUnits(state, "Enemy").some(
    (ally) =>
      ally.id !== unit.id &&
      canCounterAir(ally.type) &&
      hexDistance(ally.coord, coord) <= getEffectiveUnitStats(state, ally.owner, ally.type, ally.level, ally.coord, coord).attackRange + 1
  );
  if (nearbyAntiAirCover) {
    return 0;
  }

  const projectedAirThreats = getPlayerIntelForEnemy(state).filter((intel) => {
    if (getUnitDefinition(intel.unit.type).domain !== "Air") {
      return false;
    }
    return canUnitProjectThreatToCoord(state, intel.unit, intel.predictedCoord, coord);
  });
  return projectedAirThreats.length ? 150 + nearbyGroundAllies.length * 58 + projectedAirThreats.length * 62 : 0;
}

function estimateEnemyBothGateControlLossRisk(state: GameState, plan: EnemyTurnPlan): number {
  if (!ownerControlsBothGates(state, "Enemy")) {
    return 1;
  }
  const gateRisks = (state.gates ?? []).map((gate) => {
    const playerOccupation = gate.occupation.Player / GATE_CAPTURE_DAYS;
    const knownCapturerPressure = plan.playerIntel.reduce((pressure, intel) => {
      if (!getUnitDefinition(intel.unit.type).humanBased) {
        return pressure;
      }
      const distance = hexDistance(intel.predictedCoord, gate.coord);
      if (distance > 6) {
        return pressure;
      }
      return pressure + Math.max(0, 7 - distance) * 0.045 * intel.confidence;
    }, 0);
    const forecastPressure = Math.max(0, (plan.strategicSnapshot.predictedGatePressure[gate.id] ?? 0) / 360);
    return Math.min(1, playerOccupation * 1.1 + knownCapturerPressure + forecastPressure);
  });
  return Math.min(1, Math.max(0, ...gateRisks));
}

function getEnemyBaseCaptureClockJustification(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  mission: EnemyMission
): number {
  if (mission !== "CaptureBase" && state.baseOccupation.Player <= 0) {
    return 0;
  }
  const baseDistance = hexDistance(coord, state.bases.Player);
  const activeClock = state.baseOccupation.Player > 0 ? 260 + state.baseOccupation.Player * 260 : 0;
  const nearBase = Math.max(0, 7 - baseDistance) * 65;
  const capturer = getUnitDefinition(unit.type).humanBased ? 160 : 0;
  return activeClock + nearBase + capturer;
}

function estimatePlayerDangerAtPlanner(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  plan.cache.plannerDanger ??= new Map();
  const cacheKey = `${unit.id}:${unit.type}:${unit.health}:${unit.maxHealth}:${unit.level}:${hexId(coord)}`;
  const cached = plan.cache.plannerDanger.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const danger = plan.playerIntel.reduce((totalDanger, intel) => {
    if (!canUnitTargetUnit(intel.unit.type, unit.type)) {
      return totalDanger;
    }
    const damage = estimateAttackDamage(state, intel.unit, unit);
    const threat = intel.currentBeliefs.reduce((total, belief) => {
      const distance = hexDistance(coord, belief.coord);
      const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, belief.coord, coord);
      if (distance <= stats.attackRange) {
        const lethalPenalty = damage >= unit.health ? getUnitInstanceValue(state, unit) * 0.85 + damage * 2.4 : 0;
        const antiAirTrapPenalty = intel.unit.type === "Anti-Air" && getUnitDefinition(unit.type).domain === "Air"
          ? getUnitInstanceValue(state, unit) * 1.2 + damage * 3.2
          : 0;
        return total + (damage * 1.8 + lethalPenalty + antiAirTrapPenalty) * belief.weight;
      }
      if (!getUnitDefinition(intel.unit.type).cannotMoveAndAttack && distance <= stats.attackRange + stats.moveRange) {
        const chaseLethalPenalty = damage >= unit.health ? getUnitInstanceValue(state, unit) * 0.32 + damage : 0;
        return total + (damage * 0.75 + chaseLethalPenalty) * belief.weight;
      }
      return total;
    }, 0);
    return totalDanger + threat * intel.confidence;
  }, 0);
  plan.cache.plannerDanger.set(cacheKey, danger);
  return danger;
}

function estimateEnemyFogThreatAtPlanner(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  plan.cache.plannerFogThreat ??= new Map();
  const cacheKey = `${unit.id}:${unit.type}:${unit.health}:${unit.maxHealth}:${unit.level}:${hexId(coord)}`;
  const cached = plan.cache.plannerFogThreat.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const visibleHexes = getEnemyVisibleHexIds(state);
  const unseenNearby = state.map.hexes.filter((hex) => hex.passable && !visibleHexes.has(hex.id) && hexDistance(hex.coord, coord) <= 3);
  const approachLane = getEnemyFogApproachLanePressure(state, coord);
  const staleIntelThreat = plan.playerIntel.reduce((threat, intel) => {
    if (intel.age <= 0 || !canUnitTargetUnit(intel.unit.type, unit.type)) {
      return threat;
    }
    const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, intel.predictedCoord, coord);
    const reach = stats.attackRange + (getUnitDefinition(intel.unit.type).cannotMoveAndAttack ? 0 : stats.moveRange) + Math.min(2, intel.age);
    if (hexDistance(coord, intel.predictedCoord) > reach) {
      return threat;
    }
    const damage = estimateAttackDamage(state, { ...intel.unit, coord: intel.predictedCoord }, unit);
    return threat + damage * intel.confidence * (0.32 + Math.min(0.26, intel.age * 0.06));
  }, 0);

  const compositionThreat = plan.playerIntel.reduce((threat, intel) => {
    if (!canUnitTargetUnit(intel.unit.type, unit.type)) {
      return threat;
    }
    const damage = estimateAttackDamage(state, { ...intel.unit, coord: intel.predictedCoord }, unit);
    const plausibleCoverage =
      getUnitDefinition(unit.type).domain === "Air" && intel.unit.type === "Anti-Air"
        ? 1.15
        : getUnitInstanceValue(state, unit) >= 120 || unit.health <= unit.maxHealth * 0.45
          ? 0.48
          : 0.28;
    return threat + damage * intel.confidence * plausibleCoverage;
  }, 0);

  const unseenLaneThreat = unseenNearby.length * approachLane * 5.5;
  const baseThreat =
    staleIntelThreat +
    Math.min(180, compositionThreat * Math.min(1, unseenNearby.length / 4)) +
    Math.min(180, unseenLaneThreat);
  const multiplier = getEnemyFogThreatUnitMultiplier(state, unit, coord, plan);
  const threat = baseThreat * multiplier;
  plan.cache.plannerFogThreat.set(cacheKey, threat);
  return threat;
}

function getEnemyFogApproachLanePressure(state: GameState, coord: UnitInstance["coord"]): number {
  const gatePressure = (state.gates ?? []).reduce((best, gate) => {
    const nearGate = Math.max(0, 7 - hexDistance(coord, gate.coord));
    const betweenPlayerAndGate = hexDistance(coord, state.bases.Player) < hexDistance(state.bases.Enemy, state.bases.Player) && coord.r >= gate.coord.r - 5;
    const contested = gate.owner !== "Enemy" || gate.occupation.Player > 0 || gate.occupation.Enemy > 0;
    return Math.max(best, nearGate * (contested ? 1.2 : 0.75) + (betweenPlayerAndGate ? 2 : 0));
  }, 0);
  const enemyBaseApproach = Math.max(0, getEnemyBaseResponseRadius(state) + 5 - hexDistance(coord, state.bases.Enemy));
  const playerBaseRoute = Math.max(0, 11 - hexDistance(coord, state.bases.Player)) * 0.45;
  return Math.max(gatePressure, enemyBaseApproach, playerBaseRoute);
}

function getEnemyFogThreatUnitMultiplier(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  let multiplier = 1;
  if (isReconUnit(unit.type) || plan.rolesByUnitId[unit.id] === "Scout" || plan.rolesByUnitId[unit.id] === "PatrolWest" || plan.rolesByUnitId[unit.id] === "PatrolEast") {
    multiplier *= 0.45;
  }
  if (getUnitInstanceValue(state, unit) >= 120 || unit.health <= unit.maxHealth * 0.45) {
    multiplier *= 1.25;
  }
  if (isEnemySupplySupportUnit(unit.type)) {
    multiplier *= 1.55;
  }
  if (
    getUnitDefinition(unit.type).domain === "Air" &&
    plan.playerIntel.some((intel) => intel.unit.type === "Anti-Air" && hexDistance(coord, intel.predictedCoord) <= 9)
  ) {
    multiplier *= 1.6;
  }
  if (plan.objectiveImperatives.some((imperative) => imperative.unitId === unit.id && Math.abs(imperative.terminal) >= ENEMY_OBJECTIVE_TERMINAL_SCORE * 0.4)) {
    multiplier *= 0.58;
  }
  return multiplier;
}

function getEnemyPlannerInformationGain(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const visible = getEnemyVisibleHexIds(state);
  return countNewVisibleHexesFrom(state, coord, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord).visibilityRange, visible, unit.owner, unit.type, unit.level);
}

function getEnemyScoutFogRevealScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  if (!isReconUnit(unit.type) && !isPatrolCapableUnit(unit.type)) {
    return 0;
  }
  return getEnemyPlannerInformationGain(state, unit, coord);
}

function getEnemyPlannerSupportScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  return getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id) {
      return score;
    }
    const distance = hexDistance(coord, ally.coord);
    const genericSupport = distance <= 2 ? 9 : distance <= 5 ? 3.5 : 0;
    return score + genericSupport + scoreEnemyRoleAwareSupportPair(state, unit, coord, ally);
  }, 0);
}

function scoreEnemyRoleAwareSupportPair(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], ally: UnitInstance): number {
  const distance = hexDistance(coord, ally.coord);
  if (distance > 5) {
    return 0;
  }

  const unitDefinition = getUnitDefinition(unit.type);
  const allyDefinition = getUnitDefinition(ally.type);
  const antiAirCover =
    (unit.type === "Anti-Air" && (allyDefinition.domain === "Air" || ally.type === "Artillery") && distance >= 1 && distance <= 4) ||
    (ally.type === "Anti-Air" && (unitDefinition.domain === "Air" || unit.type === "Artillery") && distance >= 1 && distance <= 4);
  if (antiAirCover) {
    return 28 - Math.abs(distance - 2) * 4;
  }

  const infantryScreensHeavy =
    ((unit.type === "Infantry" || unit.type === "Operator") && (ally.type === "Tank" || ally.type === "IFV" || ally.type === "Artillery")) ||
    ((ally.type === "Infantry" || ally.type === "Operator") && (unit.type === "Tank" || unit.type === "IFV" || unit.type === "Artillery"));
  if (infantryScreensHeavy && distance >= 1 && distance <= 2) {
    return 22;
  }

  const supplySupportsDamaged =
    (isEnemySupplySupportUnit(unit.type) && ally.health < ally.maxHealth && !isEnemySupplySupportUnit(ally.type) && getUnitDefinition(ally.type).domain === "Ground" && distance <= SUPPLY_TRUCK_REPAIR_RANGE + 1) ||
    (isEnemySupplySupportUnit(ally.type) && unit.health < unit.maxHealth && !isEnemySupplySupportUnit(unit.type) && getUnitDefinition(unit.type).domain === "Ground" && distance <= SUPPLY_TRUCK_REPAIR_RANGE + 1);
  if (supplySupportsDamaged) {
    return 34;
  }

  const armorNearCapturer =
    ((unit.type === "Tank" || unit.type === "IFV") && allyDefinition.humanBased && distance >= 1 && distance <= 3) ||
    ((ally.type === "Tank" || ally.type === "IFV") && unitDefinition.humanBased && distance >= 1 && distance <= 3);
  if (armorNearCapturer) {
    return 24 - Math.abs(distance - 2) * 3;
  }

  const fastSupportForScout =
    ((isReconUnit(unit.type) && needsReconSupport(ally.type)) || (isReconUnit(ally.type) && needsReconSupport(unit.type))) &&
    distance >= 2 &&
    distance <= 5;
  if (fastSupportForScout) {
    return 16;
  }

  const artilleryProtected =
    (unit.type === "Artillery" && (allyDefinition.humanBased || ally.type === "Tank" || ally.type === "IFV") && distance >= 1 && distance <= 2) ||
    (ally.type === "Artillery" && (unitDefinition.humanBased || unit.type === "Tank" || unit.type === "IFV") && distance >= 1 && distance <= 2);
  if (artilleryProtected) {
    return 26;
  }

  return 0;
}

function getEnemyPlannerFormationScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], mission: EnemyMission): number {
  if (mission === "BaseSentry" || mission === "DefendBase") {
    return Math.max(0, 8 - hexDistance(coord, state.bases.Enemy)) * 12;
  }
  if (mission === "CaptureBase") {
    return Math.max(0, 14 - hexDistance(coord, state.bases.Player)) * 6;
  }
  return 0;
}

function getEnemyPlannerSpacingScore(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  if (isEnemyTightFormationJustified(state, unit, coord, mission, plan)) {
    return 0;
  }

  const unitDomain = getUnitDefinition(unit.type).domain;
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  const currentDanger = estimatePlayerDangerAtPlanner(state, unit, unit.coord, plan);
  const dangerRelief = currentDanger - danger;
  const tacticalNecessity =
    danger >= unit.health * 0.7 ||
    dangerRelief >= Math.max(3, unit.health * 0.28) ||
    mission === "ProtectCapturer" ||
    mission === "CoverCounterattack";
  const pressureScale = tacticalNecessity ? 0.45 : 1;

  return getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id) {
      return score;
    }

    const sameDomain = getUnitDefinition(ally.type).domain === unitDomain;
    const distance = hexDistance(coord, ally.coord);
    const closePenalty =
      distance === 0 ? 150 :
      distance === 1 ? 92 :
      distance === 2 && sameDomain ? 36 :
      distance === 3 && sameDomain ? 10 :
      0;
    const spacingBonus =
      sameDomain && distance >= 4 && distance <= 6
        ? mission === "CaptureGate" || mission === "CaptureBase" || isEnemyGateLockoutCombatMission(mission) ? 18 : 12
        : 0;

    return score - closePenalty * pressureScale + spacingBonus;
  }, 0);
}

function isEnemyTightFormationJustified(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): boolean {
  if (mission === "Repair" || mission === "DefendBase" || mission === "BaseSentry") {
    return true;
  }

  if (isEnemySupplySupportUnit(unit.type)) {
    return true;
  }

  if (unit.health < unit.maxHealth && isEnemyRepairCoord(state, coord, unit.type)) {
    return true;
  }

  if (mission === "CaptureGate" || mission === "DefendGate") {
    const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    if (gate && sameHex(coord, gate.coord) && getUnitDefinition(unit.type).humanBased) {
      return true;
    }
  }

  if (mission === "CaptureBase" && sameHex(coord, state.bases.Player) && getUnitDefinition(unit.type).humanBased) {
    return true;
  }

  return false;
}

function getEnemyPlannerCongestionPenalty(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  reservedDestinations: Record<string, string>
): number {
  const key = getEnemyDestinationReservationKey(unit.type, coord);
  const reservationPenalty = reservedDestinations[key] && reservedDestinations[key] !== unit.id ? 120 : 0;
  const localCrowding = getOwnerUnits(state, "Enemy").filter((ally) => ally.id !== unit.id && hexDistance(ally.coord, coord) <= 1).length * 10;
  return reservationPenalty + localCrowding;
}

function getEnemyParallelAdvancePenalty(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>
): number {
  if (isEnemyTightFormationJustified(state, unit, coord, mission, plan)) {
    return 0;
  }

  const unitDomain = getUnitDefinition(unit.type).domain;
  let penalty = 0;

  for (const ally of getOwnerUnits(state, "Enemy")) {
    if (ally.id === unit.id || getUnitDefinition(ally.type).domain !== unitDomain) {
      continue;
    }

    const allyMission = plan.rolesByUnitId[ally.id] ?? assignEnemyMission(state, ally);
    if (!enemyUnitsShareParallelObjective(state, unit, ally, mission, allyMission, plan)) {
      continue;
    }

    penalty = Math.max(penalty, getEnemyParallelAdvanceDistancePenalty(hexDistance(coord, ally.coord)));
  }

  for (const reservation of getEnemyReservedDestinationEntries(reservedDestinations)) {
    if (reservation.unitId === unit.id || reservation.domain !== unitDomain) {
      continue;
    }

    const ally = getUnitById(state, reservation.unitId);
    if (!ally || ally.owner !== "Enemy") {
      continue;
    }

    const allyMission = plan.rolesByUnitId[ally.id] ?? assignEnemyMission(state, ally);
    if (!enemyUnitsShareParallelObjective(state, unit, ally, mission, allyMission, plan)) {
      continue;
    }

    penalty = Math.max(penalty, getEnemyParallelAdvanceDistancePenalty(hexDistance(coord, reservation.coord)) + 24);
  }

  const tacticalScale = mission === "ProtectCapturer" || mission === "CoverCounterattack" ? 0.55 : 1;
  return Math.round(penalty * tacticalScale);
}

function getEnemyParallelAdvanceDistancePenalty(distance: number): number {
  if (distance <= 0) {
    return 220;
  }
  if (distance === 1) {
    return 140;
  }
  if (distance === 2) {
    return 35;
  }
  return 0;
}

function getEnemyReservedDestinationEntries(
  reservedDestinations: Record<string, string>
): Array<{ unitId: string; domain: UnitDomain; coord: UnitInstance["coord"] }> {
  return Object.entries(reservedDestinations)
    .map(([key, unitId]) => {
      const separator = key.indexOf(":");
      if (separator < 0) {
        return undefined;
      }

      const domain = key.slice(0, separator) as UnitDomain;
      if (domain !== "Ground" && domain !== "Air") {
        return undefined;
      }

      const coord = parseHexId(key.slice(separator + 1));
      if (!Number.isFinite(coord.q) || !Number.isFinite(coord.r)) {
        return undefined;
      }

      return { unitId, domain, coord };
    })
    .filter((entry): entry is { unitId: string; domain: UnitDomain; coord: UnitInstance["coord"] } => Boolean(entry));
}

function enemyUnitsShareParallelObjective(
  state: GameState,
  unit: UnitInstance,
  ally: UnitInstance,
  mission: EnemyMission,
  allyMission: EnemyMission,
  plan: EnemyTurnPlan
): boolean {
  if (mission === "Repair" || allyMission === "Repair" || mission === "DefendBase" || allyMission === "DefendBase" || mission === "BaseSentry" || allyMission === "BaseSentry") {
    return false;
  }

  if (isEnemySupplySupportUnit(unit.type) || isEnemySupplySupportUnit(ally.type)) {
    return false;
  }

  const unitGate = getEnemyCampaignAssignedGateForUnit(state, unit, plan);
  const allyGate = getEnemyCampaignAssignedGateForUnit(state, ally, plan);
  if (unitGate && allyGate) {
    return unitGate.id === allyGate.id;
  }

  if (mission === allyMission && (mission === "PatrolWest" || mission === "PatrolEast" || mission === "Scout")) {
    return true;
  }

  const unitForce = plan.taskForces.find((taskForce) => taskForce.members.includes(unit.id));
  const allyForce = plan.taskForces.find((taskForce) => taskForce.members.includes(ally.id));
  if (unitForce && allyForce) {
    return unitForce.id === allyForce.id || sameHex(unitForce.objectiveCoord, allyForce.objectiveCoord);
  }

  const unitTarget = chooseEnemyPlannerOperationalTarget(state, unit, plan);
  const allyTarget = chooseEnemyPlannerOperationalTarget(state, ally, plan);
  return sameHex(unitTarget, allyTarget);
}

function getEnemyPlannerTaskProgressScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  const target = chooseEnemyPlannerOperationalTarget(state, unit, plan);
  const currentDistance = hexDistance(unit.coord, target);
  const nextDistance = hexDistance(coord, target);
  const combatPressure = getPlayerForwardPressure(state);
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const missionMultiplier = isEnemyGateLockoutCombatMission(mission) ? 1.18 : combatPressure > 260 ? 0.35 : combatPressure > 120 ? 0.62 : 1;
  const gateLockoutBonus =
    isEnemyGateLockoutCombatMission(mission) && nextDistance <= currentDistance
      ? Math.max(0, 7 - nextDistance) * (mission === "ReserveCapturer" ? 8 : 18)
      : 0;
  return (currentDistance - nextDistance) * (getUnitDefinition(unit.type).humanBased ? 34 : 16) * missionMultiplier + gateLockoutBonus;
}

function scoreEnemyCombatObjectiveFollowThrough(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  if (!action.targetId || !action.expectedOutcome || !action.moveTo || action.expectedOutcome.killProbability < 0.55) {
    return 0;
  }

  const target = getUnitById(state, action.targetId);
  if (!target) {
    return 0;
  }

  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, mission, plan);
  const currentDistance = hexDistance(unit.coord, objective);
  const nextDistance = hexDistance(finalCoord, objective);
  const progress = currentDistance - nextDistance;
  if (progress <= 0) {
    return 0;
  }

  const targetValue = getUnitInstanceValue(state, target);
  const phaseWeights = getEnemyStrategicPhaseWeights(plan.strategicSnapshot.strategicPhase);
  const objectiveWeight =
    mission === "CaptureGate" || mission === "DefendGate" || mission === "CaptureBase" || mission === "ProtectCapturer" || isEnemyGateLockoutCombatMission(mission)
      ? 28
      : 18;
  const killWeight = action.expectedOutcome.killProbability * Math.min(90, 24 + targetValue * 0.22);
  const sequencePreference = action.kind === "MoveThenAttack" ? 18 : action.kind === "MoveAttackRetreat" ? 14 : action.kind === "AttackThenMove" ? 8 : 0;
  return (progress * objectiveWeight + killWeight + sequencePreference) * phaseWeights.combat;
}

function chooseEnemyCombatFollowThroughObjective(
  state: GameState,
  unit: UnitInstance,
  mission: EnemyMission,
  plan: EnemyTurnPlan
): UnitInstance["coord"] {
  if (mission === "CaptureGate" || mission === "DefendGate") {
    return chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission)?.coord ?? chooseEnemyPlannerOperationalTarget(state, unit, plan);
  }
  if (mission === "CaptureBase") {
    return state.bases.Player;
  }
  if (mission === "DefendBase") {
    return state.bases.Enemy;
  }
  if (mission === "ProtectCapturer") {
    return getOwnerUnits(state, "Enemy").find((ally) => getUnitDefinition(ally.type).humanBased && sameHex(ally.coord, state.bases.Player))?.coord ?? state.bases.Player;
  }
  const gateLockoutTarget = isEnemyGateLockoutCombatMission(mission)
    ? chooseEnemyGateLockoutRoleTargetCoord(state, unit, mission, plan)
    : undefined;
  if (gateLockoutTarget) {
    return gateLockoutTarget;
  }
  return chooseEnemyPlannerOperationalTarget(state, unit, plan);
}

function scoreEnemyTempoRiskAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  if (state.difficulty !== "Hard" || action.kind === "Hold" || !isEnemyRiskBudgetCombatUnit(unit) || unit.health / Math.max(1, unit.maxHealth) < 0.68) {
    return 0;
  }

  const replyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, finalCoord, plan, action);
  if (replyDamage <= 0 || isEnemyPlannerOneShotExposed(state, unit, finalCoord, plan)) {
    return 0;
  }

  const health = Math.max(1, unit.health);
  if (replyDamage >= health * 0.64 || replyDamage > getEnemyTacticalReplyDamageBudget(state, unit, action, finalCoord, plan)) {
    return 0;
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const justification = getEnemyTempoRiskJustificationScore(state, unit, action, finalCoord, mission, plan);
  if (justification < 90) {
    return 0;
  }

  const riskRatio = replyDamage / health;
  const usefulRiskBandBonus = riskRatio >= 0.25 && riskRatio <= 0.5 ? 54 : riskRatio < 0.25 ? 22 : -36;
  return justification + usefulRiskBandBonus - Math.max(0, riskRatio - 0.5) * 420;
}

function scoreEnemyInitiativeAction(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  const initiativePressure = plan.strategicSnapshot.initiativePressure ?? 0;
  if (initiativePressure <= 0 || mission === "Repair" || mission === "BaseSentry" || mission === "DefendBase") {
    return 0;
  }
  if (state.baseOccupation.Enemy > 0 || plan.strategicSnapshot.strategicPhase === "BaseDefenseEmergency") {
    return 0;
  }

  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, mission, plan);
  const objectiveProgress = hexDistance(unit.coord, objective) - hexDistance(finalCoord, objective);
  const baseProgress = hexDistance(unit.coord, state.bases.Player) - hexDistance(finalCoord, state.bases.Player);
  const gateContest = isEnemyTempoGateContestMove(state, unit, finalCoord, plan);
  const nextTurnThreat = Math.min(220, estimateEnemyBestPotentialAttackValue(state, unit, plan, finalCoord) * 0.11);
  const support = Math.min(120, getEnemyPlannerSupportScore(state, unit, finalCoord) * 2);
  const packetSupport = Math.min(120, scoreEnemyAggressiveStageSupportAdvance(state, unit, finalCoord));
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  const objectiveAttack =
    target && action.expectedOutcome && isEnemyInitiativeObjectiveTarget(state, target, plan)
      ? 160 + Math.min(60, action.expectedOutcome.killProbability * 90 + getUsefulExpectedDamage(target, action.expectedOutcome.expectedDamage) * 2)
      : 0;

  let score = Math.min(180, initiativePressure * (action.kind === "Hold" ? 0.18 : 0.34));
  score += Math.max(0, objectiveProgress) * 70;
  score += Math.max(0, baseProgress) * 24;
  score += gateContest ? 120 : 0;
  score += nextTurnThreat;
  score += Math.max(support, packetSupport);
  score += objectiveAttack;

  if (action.kind === "Hold" && initiativePressure >= 140 && !shouldEnemyInitiativeHoldBeExcused(state, unit, finalCoord, mission, plan, target)) {
    score -= 95;
  }

  return score;
}

function isEnemyInitiativeObjectiveTarget(state: GameState, target: UnitInstance, plan: EnemyTurnPlan): boolean {
  return (
    isEnemyObjectiveBlockerTarget(state, target, plan) ||
    scoreEnemyFocusFireTargetPriority(state, target, plan) >= 160 ||
    isEnemyTargetNearAnyObjective(state, target, plan) ||
    plan.objectiveImperatives.some((imperative) => imperative.targetId === target.id)
  );
}

function shouldEnemyInitiativeHoldBeExcused(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan,
  target: UnitInstance | undefined
): boolean {
  if (target && isEnemyInitiativeObjectiveTarget(state, target, plan)) {
    return true;
  }
  if (mission === "CaptureGate" || mission === "DefendGate") {
    const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    if (gate && sameHex(finalCoord, gate.coord) && (gate.occupation.Enemy > 0 || gate.occupation.Player > 0 || gate.owner !== "Enemy")) {
      return true;
    }
  }
  if (mission === "CaptureBase" && sameHex(finalCoord, state.bases.Player)) {
    return true;
  }
  return estimatePlayerDangerAtPlanner(state, unit, finalCoord, plan) >= unit.health * 0.55;
}

function getEnemyTempoRiskJustificationScore(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  if (mission === "Repair" || mission === "DefendBase" || mission === "BaseSentry") {
    return 0;
  }

  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, mission, plan);
  const objectiveProgress = hexDistance(unit.coord, objective) - hexDistance(finalCoord, objective);
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  const targetTempo = target
    ? (isEnemyObjectiveBlockerTarget(state, target, plan) ? 120 : 0) +
      (isEnemyTargetNearAnyObjective(state, target, plan) ? 72 : 0) +
      getEnemyActionAttackPayoff(state, action, plan).score * 0.18
    : 0;
  const objectiveTempo = Math.max(0, objectiveProgress) * (isEnemyGateLockoutCombatMission(mission) ? 70 : mission === "CaptureGate" || mission === "DefendGate" ? 62 : 42);
  const gateContestMove = isEnemyTempoGateContestMove(state, unit, finalCoord, plan) ? 86 : 0;
  const nextTurnAttackValue = Math.min(140, estimateEnemyBestPotentialAttackValue(state, unit, plan, finalCoord) * 0.08);
  const nextTurnThreat = scoreEnemyNextTurnThreatFromCoord(state, unit, finalCoord, plan);
  const localSuperiority = scoreEnemyLocalSuperiorityTempo(state, unit, finalCoord, plan);
  const gateContest = scoreEnemyGateContestTempo(state, unit, finalCoord, mission, plan);
  const counterPressure = scoreEnemyCounterPressureTempo(state, unit, finalCoord, plan);
  return objectiveTempo + targetTempo + gateContestMove + nextTurnAttackValue + nextTurnThreat + localSuperiority + gateContest + counterPressure;
}

function isEnemyTempoGateContestMove(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): boolean {
  if (sameHex(unit.coord, finalCoord)) {
    return false;
  }

  return (state.gates ?? []).some((gate) => {
    const predictedPressure = plan.strategicSnapshot.predictedGatePressure[gate.id] ?? 0;
    const playerControlsOrPressuresGate =
      gate.owner === "Player" ||
      gate.occupation.Player > 0 ||
      predictedPressure >= 65;
    if (!playerControlsOrPressuresGate) {
      return false;
    }

    return hexDistance(finalCoord, gate.coord) <= 3 && hexDistance(finalCoord, gate.coord) < hexDistance(unit.coord, gate.coord);
  });
}

function isEnemyTargetNearAnyObjective(state: GameState, target: UnitInstance, plan: EnemyTurnPlan): boolean {
  return (
    hexDistance(target.coord, state.bases.Enemy) <= getEnemyBaseResponseRadius(state) ||
    hexDistance(target.coord, state.bases.Player) <= 5 ||
    (state.gates ?? []).some((gate) => gate.owner !== "Enemy" && hexDistance(target.coord, gate.coord) <= 3) ||
    plan.objectiveImperatives.some((imperative) => imperative.targetId === target.id)
  );
}

function scoreEnemyNextTurnThreatFromCoord(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  if (getUnitDefinition(unit.type).cannotAttack) {
    return 0;
  }

  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord);
  const canMoveAndAttack = !getUnitDefinition(unit.type).cannotMoveAndAttack;
  const threatReach = stats.attackRange + (canMoveAndAttack ? Math.max(0, stats.moveRange - 1) : 0);
  return Math.min(
    150,
    plan.playerIntel.reduce((score, intel) => {
      if (!canUnitTargetUnit(unit.type, intel.unit.type) || hexDistance(coord, intel.predictedCoord) > threatReach) {
        return score;
      }
      const value = getUnitInstanceValue(state, intel.unit);
      const objectiveBonus = getUnitDefinition(intel.unit.type).humanBased || isEnemyTargetNearAnyObjective(state, { ...intel.unit, coord: intel.predictedCoord }, plan) ? 36 : 0;
      return score + (value * 0.18 + objectiveBonus) * intel.confidence;
    }, 0)
  );
}

function scoreEnemyLocalSuperiorityTempo(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  const enemyPower = getOwnerUnits(state, "Enemy").reduce((total, ally) => {
    const allyCoord = ally.id === unit.id ? coord : ally.coord;
    return hexDistance(allyCoord, coord) <= 4 ? total + getUnitInstanceValue(state, ally) : total;
  }, 0);
  const playerPower = plan.playerIntel.reduce((total, intel) => {
    return hexDistance(intel.predictedCoord, coord) <= 4 ? total + getUnitInstanceValue(state, intel.unit) * intel.confidence : total;
  }, 0);
  if (enemyPower < 70 || playerPower <= 0) {
    return 0;
  }
  const ratio = enemyPower / Math.max(1, playerPower);
  return ratio >= 1.45 ? 120 : ratio >= 1.15 ? 72 : 0;
}

function scoreEnemyGateContestTempo(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  mission: EnemyMission,
  plan: EnemyTurnPlan
): number {
  const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission) ?? chooseGateObjective(state, "Enemy", unit.coord, unit, plan);
  if (!gate || gate.owner === "Enemy") {
    return 0;
  }
  const currentDistance = hexDistance(unit.coord, gate.coord);
  const nextDistance = hexDistance(coord, gate.coord);
  const contestBand = nextDistance <= 2 ? 74 : nextDistance <= 4 ? 38 : 0;
  return Math.max(0, currentDistance - nextDistance) * 44 + contestBand + gate.occupation.Player * 42;
}

function scoreEnemyCounterPressureTempo(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  if (getEnemyPlannerCombatPressure(state, plan) < ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD) {
    return 0;
  }
  const combatTarget = chooseEnemyPlannerCombatTargetCoord(state, unit, plan);
  if (!combatTarget) {
    return 0;
  }
  const progress = hexDistance(unit.coord, combatTarget) - hexDistance(coord, combatTarget);
  return Math.max(0, progress) * 48;
}

function estimateEnemyPlannerOpponentReplyRisk(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  let risk = 0;
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  if (getUnitDefinition(unit.type).humanBased && sameHex(coord, state.bases.Player)) {
    risk += danger * 0.35;
  }
  if (!getOwnerUnits(state, "Enemy").some((ally) => ally.id !== unit.id && (plan.rolesByUnitId[ally.id] === "BaseSentry" || plan.rolesByUnitId[ally.id] === "DefendBase"))) {
    risk += plan.strategicSnapshot.predictedEnemyBasePressure * 0.6;
  }
  if (danger >= unit.health * 0.8) {
    risk += getUnitInstanceValue(state, unit) * (getUnitInstanceValue(state, unit) > 120 ? 1.15 : 0.72);
  }
  if (isEnemyPlannerOneShotExposed(state, unit, coord, plan)) {
    risk += getUnitInstanceValue(state, unit) * 1.4 + 160;
  }
  return risk;
}

function isEnemyPlannerOneShotExposed(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): boolean {
  plan.cache.plannerOneShotExposure ??= new Map();
  const cacheKey = `${unit.id}:${unit.type}:${unit.health}:${unit.maxHealth}:${unit.level}:${hexId(coord)}`;
  const cached = plan.cache.plannerOneShotExposure.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const exposed = plan.playerIntel.some((intel) => {
    if (!canUnitTargetUnit(intel.unit.type, unit.type)) {
      return false;
    }
    const playerUnit = { ...intel.unit, coord: intel.predictedCoord };
    const damage = estimateAttackDamage(state, playerUnit, unit);
    if (damage < unit.health) {
      return false;
    }
    return intel.currentBeliefs.some((belief) => {
      const distance = hexDistance(coord, belief.coord);
      const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, belief.coord, coord);
      return (
        distance <= stats.attackRange ||
        (!getUnitDefinition(intel.unit.type).cannotMoveAndAttack && distance <= stats.attackRange + stats.moveRange)
      );
    });
  });
  plan.cache.plannerOneShotExposure.set(cacheKey, exposed);
  return exposed;
}

function getEnemyPlannerDoctrineScore(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): number {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
  const closeChoiceScale = 1;
  const combatPressure = getPlayerForwardPressure(state);
  let score = 0;
  if (mission === "CaptureGate" || mission === "DefendGate") {
    score += plan.strategicSnapshot.gateUrgency * 0.08;
  }
  if (isEnemyGateLockoutCombatMission(mission)) {
    const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
    if (gate) {
      const currentDistance = hexDistance(unit.coord, gate.coord);
      const nextDistance = hexDistance(finalCoord, gate.coord);
      const desiredBandBonus =
        mission === "ReserveCapturer"
          ? nextDistance >= 2 && nextDistance <= 4 ? 90 : -55
          : mission === "SuppressGateZone"
            ? nextDistance >= 2 && nextDistance <= 6 ? 86 : -40
            : nextDistance <= 3 ? 82 : 0;
      score += (currentDistance - nextDistance) * (mission === "ReserveCapturer" ? 22 : 48) + desiredBandBonus;
    }
  }
  if (mission === "Scout") {
    score += combatPressure > 120 ? -45 : plan.strategicSnapshot.scoutNeed * 0.08;
  }
  if (mission === "BaseSentry") {
    const baseDistance = hexDistance(finalCoord, state.bases.Enemy);
    const currentBaseDistance = hexDistance(unit.coord, state.bases.Enemy);
    score += Math.max(0, 8 - baseDistance) * 42;
    score += (currentBaseDistance - baseDistance) * 36;
    if (baseDistance > 6) {
      score -= (baseDistance - 6) * 95 + 160;
    }
  }
  if (mission === "CaptureBase") {
    score += plan.strategicSnapshot.baseAttackUrgency * 0.08;
  }
  if (mission === "Siege" && isEnemyBaseOperationPhase(plan.campaignPlan.phase) && isEnemyBaseAttackCombatUnit(unit)) {
    const currentDistance = hexDistance(unit.coord, state.bases.Player);
    const nextDistance = hexDistance(finalCoord, state.bases.Player);
    const attacksBaseArea = target ? isPlayerBaseAreaAssaultTarget(state, target) : false;
    const rowProgress = finalCoord.r - unit.coord.r;
    score += Math.max(0, currentDistance - nextDistance) * (attacksBaseArea ? 92 : 145);
    score += rowProgress * (attacksBaseArea ? 110 : 230);
    score += isCoordInPlayerBaseAssaultArea(state, finalCoord) ? 520 : 0;
    if (!attacksBaseArea && finalCoord.r < getPlayerBaseAssaultAreaMinRow(state) && rowProgress <= 0 && action.kind !== "AttackThenMove") {
      score -= 620;
    }
    if (!attacksBaseArea && nextDistance > currentDistance && action.kind !== "AttackThenMove") {
      score -= 360;
    }
  }
  const phaseWeights = getEnemyStrategicPhaseWeights(plan.strategicSnapshot.strategicPhase);
  if (action.targetId) {
    score += (150 + combatPressure * 0.45) * phaseWeights.combat;
  } else if (combatPressure > 180 && (mission === "Scout" || mission === "CaptureGate" || mission === "PatrolWest" || mission === "PatrolEast")) {
    score -= 130;
  } else if ((combatPressure >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD || plan.strategicSnapshot.strategicPhase === "GateLockoutCombat") && mission !== "Repair") {
    const combatTarget = chooseEnemyPlannerCombatTargetCoord(state, unit, plan);
    if (combatTarget) {
      const currentDistance = hexDistance(unit.coord, combatTarget);
      const nextDistance = hexDistance(finalCoord, combatTarget);
      score += (currentDistance - nextDistance) * 42 * phaseWeights.combat;
      if (nextDistance > currentDistance && action.kind !== "AttackThenMove") {
        score -= 65;
      }
    }
  }
  return score * closeChoiceScale;
}

function getEnemyPlannerCombatPressure(state: GameState, plan: EnemyTurnPlan): number {
  if (plan.cache.combatPressure !== undefined) {
    return plan.cache.combatPressure;
  }

  const forwardLine = Math.floor(state.map.height * 0.5);
  plan.cache.combatPressure = plan.playerIntel.reduce((score, intel) => {
    const depth = Math.max(0, forwardLine - intel.predictedCoord.r);
    if (depth <= 0) {
      return score;
    }
    const enemyAreaMultiplier = isCoordInEnemyHomeArea(state, intel.predictedCoord) ? 1.55 : 1;
    const baseProximity = Math.max(0, getEnemyBaseResponseRadius(state) + 8 - hexDistance(intel.predictedCoord, state.bases.Enemy)) * 12;
    return score + (getUnitInstanceValue(state, intel.unit) * 0.58 * enemyAreaMultiplier + depth * 24 + baseProximity) * intel.confidence;
  }, 0);
  return plan.cache.combatPressure;
}

function isCoordInEnemyHomeArea(state: GameState, coord: UnitInstance["coord"]): boolean {
  return getBattlefieldArea(state, coord) === "Alliance";
}

function getPlayerForwardPressure(state: GameState): number {
  const cache = getEnemyEvaluationCache(state);
  if (cache.playerForwardPressure !== undefined) {
    return cache.playerForwardPressure;
  }

  const forwardLine = Math.floor(state.map.height * 0.44);
  cache.playerForwardPressure = getPlayerIntelForEnemy(state).reduce((score, intel) => {
    const depth = Math.max(0, forwardLine - intel.predictedCoord.r);
    if (depth <= 0) {
      return score;
    }
    return score + (getUnitInstanceValue(state, intel.unit) * 0.38 + depth * 22) * intel.confidence;
  }, 0);
  return cache.playerForwardPressure;
}

function isEnemyCompoundActionPlausiblyLegal(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  if (isScoutActionRecklesslyExposed(state, unit, finalCoord, action, plan)) {
    return false;
  }
  if (shouldRejectEnemyAirThreatStall(state, unit, action, plan)) {
    return false;
  }
  if (action.kind === "Hold" && shouldRejectOpeningCaptureGateHold(state, unit, plan)) {
    return false;
  }
  if ((action.kind === "Move" || action.kind === "MoveThenAttack" || action.kind === "AttackThenMove" || action.kind === "MoveAttackRetreat") && action.moveTo && !canMoveUnitTo(state, unit, action.moveTo)) {
    return false;
  }
  if (shouldRejectEnemyUnsafeNonCaptureMove(state, unit, action, plan)) {
    return false;
  }
  if ((action.kind === "MoveThenAttack" || action.kind === "AttackThenMove" || action.kind === "MoveAttackRetreat") && isMoveAttackExclusiveUnit(unit.type)) {
    return false;
  }
  if (action.kind === "MoveAttackRetreat" && !isEnemyMoveAttackRetreatLegsLegal(state, unit, action)) {
    return false;
  }
  if (action.kind === "Attack" && action.attackAt && !canUnitAttackHex(state, unit, action.attackAt)) {
    return false;
  }
  if (action.targetId) {
    const target = getUnitById(state, action.targetId);
    if (target && !isEnemyFireSupportAttackIntelAuthorized(state, unit, target, plan)) {
      return false;
    }
  }
  if (!isEnemyActionAllowedByStrategicStructure(state, unit, action, plan)) {
    return false;
  }
  const moveThreatContext =
    action.kind === "MoveAttackRetreat"
      ? { ...action, moveAttackRetreatAttackTile: true }
      : action;
  if (action.moveTo && !isEnemyAirMoveAllowedByThreatMap(state, unit, action.moveTo, moveThreatContext, plan)) {
    return false;
  }
  if (action.retreatTo && !isEnemyAirMoveAllowedByThreatMap(state, unit, action.retreatTo, action, plan)) {
    return false;
  }
  return true;
}

function shouldRejectEnemyUnsafeNonCaptureMove(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  const finalCoord = getEnemyCompoundActionReservedCoord(action);
  if (!finalCoord || sameHex(finalCoord, unit.coord) || isEnemyCaptureRiskExemptAction(state, unit, action, plan)) {
    return false;
  }
  const finalReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, finalCoord, plan, action);
  const currentReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, unit.coord, plan);
  if (finalReplyDamage <= 0 && isEnemyAssignedObjectiveProgressMove(state, unit, finalCoord, plan)) {
    return false;
  }
  if (isEnemyActiveGateClockEntryMove(state, unit, finalCoord)) {
    return false;
  }
  if (isEnemyBaseHoldProtectionProgressMove(state, unit, finalCoord, plan)) {
    return false;
  }
  if (shouldRejectEnemySupplyTruckDamageRisk(unit, finalReplyDamage, currentReplyDamage)) {
    return true;
  }
  if (isCommittedObjectiveCaptureAdvanceExposureJustified(state, unit, finalCoord, plan, finalReplyDamage)) {
    return false;
  }
  if (isEnemyEndgameBaseProgressExposureAcceptable(state, unit, finalCoord, plan, finalReplyDamage)) {
    return false;
  }
  if (isCommittedBaseAssaultCombatAdvanceExposureJustified(state, unit, finalCoord, plan, finalReplyDamage)) {
    return false;
  }
  const health = Math.max(1, unit.health);
  if (
    action.kind === "Move" &&
    !action.targetId &&
    finalReplyDamage >= health * 0.5 &&
    !isEnemyAssignedObjectiveProgressMove(state, unit, finalCoord, plan) &&
    !isEnemyTempoGateContestMove(state, unit, finalCoord, plan)
  ) {
    return true;
  }
  if (isEnemyCombatExposureWithinRiskBudget(state, unit, action, finalCoord, plan, finalReplyDamage, currentReplyDamage)) {
    return false;
  }
  const improvementMargin = Math.max(6, health * 0.12);
  const finalFogThreat = estimateEnemyFogThreatAtPlanner(state, unit, finalCoord, plan);
  const currentFogThreat = estimateEnemyFogThreatAtPlanner(state, unit, unit.coord, plan);
  if (
    finalFogThreat > currentFogThreat + Math.max(90, health * (isReconUnit(unit.type) ? 2.2 : 1.25)) &&
    finalFogThreat >= health * (isEnemySupplySupportUnit(unit.type) ? 1.1 : isReconUnit(unit.type) ? 2.4 : 1.65) &&
    !isEnemyNonAttackingExposureMoveJustified(state, unit, finalCoord, plan)
  ) {
    return true;
  }
  if (finalReplyDamage < currentReplyDamage - improvementMargin) {
    return false;
  }

  const finalOneShot = isEnemyPlannerOneShotExposed(state, unit, finalCoord, plan);
  const currentOneShot = isEnemyPlannerOneShotExposed(state, unit, unit.coord, plan);
  if (finalOneShot && !currentOneShot) {
    return true;
  }

  const significantDamage = health * 0.34;
  const heavyDamage = health * 0.5;
  const nearLethalDamage = health * 0.82;
  const worsensBySignificantAmount = finalReplyDamage - currentReplyDamage >= Math.max(6, health * 0.18);
  if (finalReplyDamage >= nearLethalDamage && finalReplyDamage > currentReplyDamage * 0.8) {
    return true;
  }

  if (isEnemyTempoExposureWithinRiskBudget(state, unit, action, finalCoord, plan, finalReplyDamage, currentReplyDamage)) {
    return false;
  }

  if (
    action.kind === "Move" &&
    !action.targetId &&
    finalReplyDamage > 0 &&
    finalReplyDamage >= currentReplyDamage - Math.max(2, health * 0.08) &&
    !isEnemyNonAttackingExposureMoveJustified(state, unit, finalCoord, plan)
  ) {
    return true;
  }

  if (finalReplyDamage >= heavyDamage && finalReplyDamage >= currentReplyDamage - improvementMargin) {
    return true;
  }
  return finalReplyDamage >= significantDamage && (currentReplyDamage < significantDamage || worsensBySignificantAmount);
}

function getEnemyRiskBudgetDiscount(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  if (state.baseOccupation.Enemy > 0 || plan.campaignPlan.phase === "BaseDefenseEmergency" || plan.strategicSnapshot.strategicPhase === "BaseDefenseEmergency") {
    return 1;
  }

  const finalReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, finalCoord, plan, action);
  const currentReplyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, unit.coord, plan);
  if (
    isEnemyCombatExposureWithinRiskBudget(state, unit, action, finalCoord, plan, finalReplyDamage, currentReplyDamage) ||
    isEnemyTempoExposureWithinRiskBudget(state, unit, action, finalCoord, plan, finalReplyDamage, currentReplyDamage)
  ) {
    return 0.58;
  }

  return 1;
}

function isEnemyTempoExposureWithinRiskBudget(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  finalReplyDamage: number,
  currentReplyDamage: number
): boolean {
  if (!isEnemyTempoRiskBudgetCombatUnit(unit) || finalReplyDamage <= 0 || unit.health / Math.max(1, unit.maxHealth) < 0.45) {
    return false;
  }

  if (isEnemyPlannerOneShotExposed(state, unit, finalCoord, plan)) {
    return false;
  }

  if (getUnitDefinition(unit.type).domain === "Air" && !isEnemyAirMoveAllowedByThreatMap(state, unit, finalCoord, action, plan)) {
    return false;
  }

  if ((unit.type === "Artillery" || unit.type === "Anti-Air") && getEnemyPlannerSupportScore(state, unit, finalCoord) < 24) {
    return false;
  }

  const health = Math.max(1, unit.health);
  if (finalReplyDamage >= health * getEnemyCatastrophicExposureRatio(state, unit, action, plan)) {
    return false;
  }

  const initiative = plan.strategicSnapshot.initiativePressure ?? 0;
  if (initiative < 85) {
    return false;
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, mission, plan);
  const objectiveProgress = hexDistance(unit.coord, objective) - hexDistance(finalCoord, objective);
  const tempoJustification = getEnemyTempoRiskJustificationScore(state, unit, action, finalCoord, mission, plan);
  const supportScore = getEnemyPlannerSupportScore(state, unit, finalCoord);
  const potentialAttackValue = estimateEnemyBestPotentialAttackValue(state, unit, plan, finalCoord);
  const gateContest = isEnemyTempoGateContestMove(state, unit, finalCoord, plan);
  const supportStagingUnit = isEnemyFireSupportStagingUnit(unit.type);
  const coveredSupport = supportStagingUnit ? scoreEnemyAggressiveStageCoveredSupport(state, unit, finalCoord) : 0;
  const supportCoverage = supportStagingUnit ? scoreEnemySupportStagingCoverage(state, unit, finalCoord, plan) : 0;
  if (
    supportStagingUnit &&
    (
      action.kind !== "Move" ||
      Boolean(action.targetId) ||
      coveredSupport < 56 ||
      supportCoverage < 42 ||
      (finalReplyDamage > 0 && supportCoverage < 90)
    )
  ) {
    return false;
  }
  const materiallyEvenOrBehind = getEnemyKnownMaterialAdvantageRatio(plan) <= 1.12;
  const hasTempoReason =
    objectiveProgress > 0 ||
    tempoJustification >= 100 ||
    gateContest ||
    potentialAttackValue >= 520 ||
    (supportScore >= 36 && (objectiveProgress >= 0 || potentialAttackValue >= 260 || gateContest)) ||
    (supportScore >= 24 && potentialAttackValue >= 420) ||
    (materiallyEvenOrBehind && (objectiveProgress > 0 || gateContest || potentialAttackValue >= 300 || (initiative >= 140 && supportScore >= 24)));
  if (!hasTempoReason) {
    return false;
  }

  const budget = getEnemyTempoExposureDamageBudget(state, unit, finalCoord, plan, {
    initiative,
    supportScore,
    potentialAttackValue,
    gateContest,
    objectiveProgress,
    materiallyEvenOrBehind,
    supportCoverage
  });
  if (finalReplyDamage > budget) {
    return false;
  }

  if (action.kind === "Move" && !action.targetId && finalReplyDamage >= health * 0.5 && !gateContest && potentialAttackValue < 520 && tempoJustification < 140) {
    return false;
  }

  if (finalReplyDamage >= currentReplyDamage + Math.max(8, health * 0.18) && tempoJustification < 140 && potentialAttackValue < 700 && !gateContest) {
    return false;
  }

  return true;
}

function isEnemyTempoRiskBudgetCombatUnit(unit: UnitInstance): boolean {
  if (unit.owner !== "Enemy" || isEnemySupplySupportUnit(unit.type) || getUnitDefinition(unit.type).cannotAttack) {
    return false;
  }
  return isEnemyBaseAttackCombatUnit(unit) || isSpecialUnit(unit.type) || unit.type === "Operator" || unit.type === "Ghost" || unit.type === "Anti-Air";
}

function getEnemyTempoExposureDamageBudget(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  context: {
    initiative: number;
    supportScore: number;
    potentialAttackValue: number;
    gateContest: boolean;
    objectiveProgress: number;
    materiallyEvenOrBehind: boolean;
    supportCoverage?: number;
  }
): number {
  const health = Math.max(1, unit.health);
  const baseRatio =
    unit.type === "Tank" ? 0.5 :
    unit.type === "IFV" ? 0.46 :
    unit.type === "Reaper" ? 0.44 :
    unit.type === "Attack Heli" ? 0.4 :
    unit.type === "Ghost" || unit.type === "Operator" ? 0.36 :
    unit.type === "Artillery" || unit.type === "Anti-Air" ? 0.24 :
    0.34;

  let ratio = baseRatio;
  if (context.initiative >= 140) ratio += 0.04;
  if (context.initiative >= 220) ratio += 0.03;
  if (context.supportScore >= 36) ratio += 0.05;
  else if (context.supportScore >= 24) ratio += 0.03;
  if (context.potentialAttackValue >= 700) ratio += 0.05;
  else if (context.potentialAttackValue >= 420) ratio += 0.03;
  if (context.gateContest) ratio += 0.04;
  if (context.objectiveProgress > 0) ratio += Math.min(0.05, context.objectiveProgress * 0.02);
  if (context.materiallyEvenOrBehind) ratio += 0.03;

  if (isEnemyFireSupportStagingUnit(unit.type)) {
    ratio = Math.min(context.supportCoverage && context.supportCoverage >= 90 ? 0.24 : 0.2, ratio);
  }
  if (getUnitDefinition(unit.type).domain === "Air") {
    ratio = Math.min(unit.type === "Reaper" ? 0.58 : 0.52, ratio);
  }

  const scarceRoleCap = getEnemyRoleScarcityMultiplier(state, unit, plan) > 1.15 ? 0.58 : 0.72;
  return health * Math.min(scarceRoleCap, 0.72, ratio);
}

function isEnemyCombatExposureWithinRiskBudget(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  finalReplyDamage: number,
  currentReplyDamage: number
): boolean {
  if (!isEnemyRiskBudgetCombatUnit(unit) || finalReplyDamage <= 0) {
    return false;
  }

  if (unit.health / Math.max(1, unit.maxHealth) < 0.68) {
    return false;
  }

  if (isEnemyPlannerOneShotExposed(state, unit, finalCoord, plan)) {
    return false;
  }

  const health = Math.max(1, unit.health);
  if (finalReplyDamage >= health * getEnemyCatastrophicExposureRatio(state, unit, action, plan)) {
    return false;
  }

  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit), plan);
  const objectiveProgress = hexDistance(unit.coord, objective) - hexDistance(finalCoord, objective);
  const attackPayoff = getEnemyActionAttackPayoff(state, action, plan);
  const materialRatio = getEnemyKnownMaterialAdvantageRatio(plan);
  const materiallyAhead = materialRatio >= 1.18;
  const pressureAdvance = getEnemyPlannerCombatPressure(state, plan) >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD && objectiveProgress > 0;
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const tempoJustification = getEnemyTempoRiskJustificationScore(state, unit, action, finalCoord, mission, plan);
  const initiativePressure = plan.strategicSnapshot.initiativePressure ?? 0;
  const nextTurnAttackValue = estimateEnemyBestPotentialAttackValue(state, unit, plan, finalCoord);
  const tempoGateContest = isEnemyTempoGateContestMove(state, unit, finalCoord, plan);
  const supportedAdvance = getEnemyPlannerSupportScore(state, unit, finalCoord) >= 24 && objectiveProgress >= 0;
  const materialCounterPressure = materialRatio <= 1.12 && (objectiveProgress > 0 || nextTurnAttackValue >= 260 || tempoGateContest || supportedAdvance);
  const tempoAdvance =
    initiativePressure >= 85 &&
    (
      objectiveProgress > 0 ||
      nextTurnAttackValue >= 260 ||
      tempoGateContest ||
      supportedAdvance ||
      materialCounterPressure
    );
  const hasPositiveReason = action.targetId !== undefined || objectiveProgress > 0 || attackPayoff.score >= 160 || materiallyAhead || pressureAdvance || tempoJustification >= 100 || tempoAdvance;
  if (!hasPositiveReason) {
    return false;
  }

  const budget = getEnemyTacticalReplyDamageBudget(state, unit, action, finalCoord, plan);
  if (finalReplyDamage > budget) {
    return false;
  }

  if (action.kind === "Move" && !action.targetId && finalReplyDamage >= currentReplyDamage + Math.max(8, health * 0.18) && objectiveProgress <= 0 && !materiallyAhead && tempoJustification < 140) {
    return false;
  }

  return true;
}

function isEnemyRiskBudgetCombatUnit(unit: UnitInstance): boolean {
  if (unit.owner !== "Enemy" || isEnemySupplySupportUnit(unit.type) || getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  if (unit.type === "Anti-Air") {
    return false;
  }
  return isEnemyBaseAttackCombatUnit(unit) || unit.type === "Operator";
}

function getEnemyKnownMaterialAdvantageRatio(plan: EnemyTurnPlan): number {
  return plan.strategicSnapshot.enemy.totalValue / Math.max(1, plan.strategicSnapshot.player.totalValue);
}

function getEnemyCatastrophicExposureRatio(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan
): number {
  const payoff = getEnemyActionAttackPayoff(state, action, plan);
  const advantage = getEnemyKnownMaterialAdvantageRatio(plan);
  const decisivePayoff = payoff.killProbability >= 0.72 || payoff.objectiveTarget || payoff.targetValue >= getUnitInstanceValue(state, unit) * 1.25;
  const advantageBonus = advantage >= 1.45 ? 0.12 : advantage >= 1.18 ? 0.06 : 0;
  return decisivePayoff ? 1.05 + advantageBonus : 0.92 + advantageBonus;
}

function getEnemyTacticalReplyDamageBudget(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  const health = Math.max(1, unit.health);
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, mission, plan);
  const objectiveProgress = Math.max(0, hexDistance(unit.coord, objective) - hexDistance(finalCoord, objective));
  const materialRatio = getEnemyKnownMaterialAdvantageRatio(plan);
  const materialBonusRatio = Math.max(0, Math.min(0.28, (materialRatio - 1) * 0.24));
  const combatPressureBonus = getEnemyPlannerCombatPressure(state, plan) >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD ? 0.08 : 0;
  const initiativePressure = plan.strategicSnapshot.initiativePressure ?? 0;
  const initiativeBonusRatio = Math.min(0.14, initiativePressure * 0.0005);
  const support = getEnemyPlannerSupportScore(state, unit, finalCoord);
  const supportBonusRatio = support >= 48 ? 0.12 : support >= 24 ? 0.07 : 0;
  const progressBonusRatio = Math.min(0.2, objectiveProgress * 0.06);
  const payoff = getEnemyActionAttackPayoff(state, action, plan);
  const payoffBudget = payoff.score * 0.018 + payoff.usefulDamage * 0.65 + payoff.killProbability * health * 0.28;
  const tempoJustification = getEnemyTempoRiskJustificationScore(state, unit, action, finalCoord, mission, plan);
  const tempoBonusRatio = tempoJustification >= 220 ? 0.14 : tempoJustification >= 140 ? 0.1 : tempoJustification >= 90 ? 0.06 : 0;
  const rolePenaltyRatio = getEnemyRoleScarcityMultiplier(state, unit, plan) > 1.15 ? 0.08 : 0;
  const highValuePenaltyRatio = getUnitInstanceValue(state, unit) >= 150 ? 0.06 : 0;
  const baseRatio = unit.type === "Tank" || unit.type === "IFV" ? 0.46 : unit.type === "Artillery" ? 0.38 : 0.34;
  const ratioBudget = health * Math.max(
    0.22,
    baseRatio + materialBonusRatio + combatPressureBonus + initiativeBonusRatio + supportBonusRatio + progressBonusRatio + tempoBonusRatio - rolePenaltyRatio - highValuePenaltyRatio
  );
  const cap = health * (payoff.score >= 320 || objectiveProgress > 0 || tempoJustification >= 140 ? 0.88 : 0.72);
  return Math.min(cap, ratioBudget + payoffBudget);
}

function getEnemyActionAttackPayoff(
  state: GameState,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan
): { score: number; usefulDamage: number; killProbability: number; targetValue: number; objectiveTarget: boolean } {
  if (!action.targetId || !action.expectedOutcome) {
    return { score: 0, usefulDamage: 0, killProbability: 0, targetValue: 0, objectiveTarget: false };
  }

  const target = getUnitById(state, action.targetId);
  const usefulDamage = getUsefulExpectedDamage(target, action.expectedOutcome.expectedDamage);
  const killProbability = action.expectedOutcome.killProbability;
  const targetValue = target ? getUnitInstanceValue(state, target) : 0;
  const objectiveTarget = target ? isEnemyObjectiveBlockerTarget(state, target, plan) || plan.objectiveImperatives.some((imperative) => imperative.targetId === target.id) : false;
  const objectiveBonus = objectiveTarget ? 260 : 0;
  const scarceTargetBonus = target && (target.type === "Artillery" || target.type === "Anti-Air" || isEnemySupplySupportUnit(target.type)) ? 120 : 0;
  return {
    score: usefulDamage * 18 + killProbability * (targetValue * 0.9 + 260) + objectiveBonus + scarceTargetBonus,
    usefulDamage,
    killProbability,
    targetValue,
    objectiveTarget
  };
}

function isEnemyAssignedObjectiveProgressMove(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): boolean {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission === "CaptureGate" || mission === "ShadowCapturer" || mission === "EscortCapture") {
    const gate = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
    return Boolean(gate && hexDistance(finalCoord, gate.coord) < hexDistance(unit.coord, gate.coord));
  }
  if (mission === "CaptureBase" || mission === "ProtectCapturer") {
    return hexDistance(finalCoord, state.bases.Player) < hexDistance(unit.coord, state.bases.Player);
  }
  return false;
}

function isEnemyBaseHoldProtectionProgressMove(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): boolean {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (state.baseOccupation.Player <= 0 || (mission !== "ProtectCapturer" && mission !== "CaptureBase")) {
    return false;
  }
  if (sameHex(finalCoord, state.bases.Player)) {
    return false;
  }
  return hexDistance(finalCoord, state.bases.Player) < hexDistance(unit.coord, state.bases.Player);
}

function isEnemyActiveGateClockEntryMove(state: GameState, unit: UnitInstance, finalCoord: UnitInstance["coord"]): boolean {
  if (!getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  return (state.gates ?? []).some((gate) => gate.owner !== "Enemy" && gate.occupation.Enemy > 0 && sameHex(finalCoord, gate.coord));
}

function shouldRejectEnemySupplyTruckDamageRisk(unit: UnitInstance, finalReplyDamage: number, currentReplyDamage: number): boolean {
  if (unit.owner !== "Enemy" || !isEnemySupplySupportUnit(unit.type)) {
    return false;
  }

  return finalReplyDamage > 0 && finalReplyDamage >= currentReplyDamage;
}

function isEnemyEndgameBaseProgressExposureAcceptable(
  state: GameState,
  unit: UnitInstance,
  finalCoord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  replyDamage: number
): boolean {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission !== "CaptureBase" || !getUnitDefinition(unit.type).humanBased || !isHardEndgameDoctrineActive(state, plan)) {
    return false;
  }
  if (!isEnemyAssignedObjectiveProgressMove(state, unit, finalCoord, plan)) {
    return false;
  }
  return replyDamage < unit.health * 0.68;
}

function isCommittedBaseAssaultCombatAdvanceExposureJustified(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  replyDamage: number
): boolean {
  const role = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (!isEnemyBaseAssaultCombatMission(state, unit, role, plan) || replyDamage <= 0 || replyDamage >= unit.health) {
    return false;
  }
  if (isEnemyPlannerOneShotExposed(state, unit, coord, plan)) {
    return false;
  }
  if (!isEnemyBaseAssaultCombatMovementAllowed(state, unit, coord, plan)) {
    return false;
  }
  if (coord.r <= unit.coord.r || hexDistance(coord, state.bases.Player) >= hexDistance(unit.coord, state.bases.Player)) {
    return false;
  }

  return ownerControlsBothGates(state, "Enemy");
}

function isCommittedObjectiveCaptureAdvanceExposureJustified(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  replyDamage: number
): boolean {
  if (unit.owner !== "Enemy" || !getUnitDefinition(unit.type).humanBased || replyDamage <= 0 || replyDamage >= unit.health) {
    return false;
  }

  const role = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (isEnemyPlannerOneShotExposed(state, unit, coord, plan)) {
    return false;
  }

  if (role === "CaptureBase" || role === "ProtectCapturer") {
    return isCommittedBaseCaptureAdvanceExposureJustified(state, unit, coord, plan);
  }

  if (role !== "CaptureGate" && role !== "ShadowCapturer" && role !== "EscortCapture") {
    return false;
  }

  const gate = chooseEnemyPlannerGateTargetForUnit(state, unit, plan) ?? getEnemyCampaignAssignedGateForUnit(state, unit, plan);
  if (!gate || gate.owner === "Enemy" || sameHex(unit.coord, gate.coord) || hexDistance(coord, gate.coord) >= hexDistance(unit.coord, gate.coord)) {
    return false;
  }

  return getCommittedEnemyGateCapturerCount(state, gate, plan, unit.id) >= 3;
}

function isCommittedBaseCaptureAdvanceExposureJustified(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): boolean {
  if (
    !ownerControlsBothGates(state, "Enemy") ||
    sameHex(unit.coord, state.bases.Player) ||
    hexDistance(coord, state.bases.Player) >= hexDistance(unit.coord, state.bases.Player)
  ) {
    return false;
  }

  return getCommittedEnemyBaseCapturerCount(state, plan, unit.id) >= 3;
}

function getCommittedEnemyGateCapturerCount(state: GameState, gate: GateState, plan: EnemyTurnPlan, includedUnitId?: string): number {
  return getOwnerUnits(state, "Enemy").filter((ally) => {
    if (!getUnitDefinition(ally.type).humanBased || ally.health / Math.max(1, ally.maxHealth) <= 0.4) {
      return false;
    }
    const role = plan.rolesByUnitId[ally.id];
    if (role !== "CaptureGate" && role !== "ShadowCapturer" && role !== "EscortCapture") {
      return false;
    }
    return ally.id === includedUnitId || plan.campaignPlan.assignedGateByUnitId[ally.id] === gate.id;
  }).length;
}

function getCommittedEnemyBaseCapturerCount(state: GameState, plan: EnemyTurnPlan, includedUnitId?: string): number {
  const packagePlan = plan.campaignPlan.baseAssaultPackage;
  return getOwnerUnits(state, "Enemy").filter((ally) => {
    if (!getUnitDefinition(ally.type).humanBased || ally.health / Math.max(1, ally.maxHealth) <= 0.4) {
      return false;
    }
    const role = plan.rolesByUnitId[ally.id];
    return (
      ally.id === includedUnitId ||
      role === "CaptureBase" ||
      ally.id === packagePlan.capturerId ||
      ally.id === packagePlan.backupCapturerId ||
      packagePlan.blockerEscortIds.includes(ally.id)
    );
  }).length;
}

function isEnemyMoveAttackRetreatLegsLegal(state: GameState, unit: UnitInstance, action: EnemyCompoundAction): boolean {
  if (!action.moveTo || !action.retreatTo || !action.attackAt || !canMoveUnitTo(state, unit, action.moveTo)) {
    return false;
  }

  const movedUnit: UnitInstance = {
    ...unit,
    coord: { ...action.moveTo },
    movementSpentThisDay: (unit.movementSpentThisDay ?? 0) + hexDistance(unit.coord, action.moveTo)
  };
  if (!canUnitAttackHex(state, movedUnit, action.attackAt)) {
    return false;
  }
  return canMoveUnitTo(state, movedUnit, action.retreatTo);
}

function isEnemyCaptureRiskExemptAction(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  if (mission === "CaptureGate" || mission === "DefendGate") {
    const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    if (gate && sameHex(finalCoord, gate.coord) && gate.occupation.Enemy > 0 && getUnitDefinition(unit.type).humanBased) {
      return true;
    }
    if (gate && sameHex(finalCoord, gate.coord) && getUnitDefinition(unit.type).humanBased && isGateSafeForRecapture(state, gate, unit, plan)) {
      return true;
    }
  }

  if (mission === "CaptureBase" && sameHex(finalCoord, state.bases.Player) && getUnitDefinition(unit.type).humanBased) {
    return true;
  }

  return plan.objectiveImperatives.some((imperative) => {
    if (imperative.unitId && imperative.unitId !== unit.id) {
      return false;
    }
    if (!imperative.targetCoord || !sameHex(finalCoord, imperative.targetCoord)) {
      return false;
    }
    return sameHex(imperative.targetCoord, state.bases.Player) || Boolean((state.gates ?? []).some((gate) => sameHex(gate.coord, imperative.targetCoord!)));
  });
}

function isEnemyNonAttackingExposureMoveJustified(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): boolean {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission === "Repair" || mission === "DefendBase" || mission === "BaseSentry") {
    return true;
  }

  if (unit.health < unit.maxHealth && isEnemyRepairCoord(state, coord, unit.type)) {
    return true;
  }

  if (mission === "CaptureGate" || mission === "DefendGate") {
    const gate = chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission);
    return Boolean(gate && sameHex(coord, gate.coord) && getUnitDefinition(unit.type).humanBased);
  }

  return mission === "CaptureBase" && sameHex(coord, state.bases.Player) && getUnitDefinition(unit.type).humanBased;
}

function estimatePlayerLikelyReplyDamageAtPlanner(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  action?: { targetId?: string; expectedOutcome?: ExpectedAttackOutcome }
): number {
  plan.cache.plannerReplyDamage ??= new Map();
  const actionKey = action?.targetId && action.expectedOutcome
    ? `${action.targetId}:${action.expectedOutcome.killProbability.toFixed(3)}`
    : "none";
  const cacheKey = `${unit.id}:${unit.type}:${unit.health}:${unit.maxHealth}:${unit.level}:${hexId(coord)}:${actionKey}`;
  const cached = plan.cache.plannerReplyDamage.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const targetSurvivalMultiplierById: Record<string, number> = {};
  if (action?.targetId && action.expectedOutcome) {
    targetSurvivalMultiplierById[action.targetId] = Math.max(0.05, 1 - action.expectedOutcome.killProbability);
  }

  const replyDamage = plan.playerIntel.reduce((totalDamage, intel) => {
    if (!canUnitTargetUnit(intel.unit.type, unit.type)) {
      return totalDamage;
    }
    const survivalMultiplier = targetSurvivalMultiplierById[intel.unit.id] ?? 1;
    const damage = estimateAttackDamage(state, intel.unit, unit) * survivalMultiplier;
    const replyDamage = intel.currentBeliefs.reduce((total, belief) => {
      const distance = hexDistance(coord, belief.coord);
      const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, belief.coord, coord);
      if (distance <= stats.attackRange) {
        return total + damage * belief.weight;
      }
      if (!getUnitDefinition(intel.unit.type).cannotMoveAndAttack && distance <= stats.attackRange + stats.moveRange) {
        return total + damage * 0.85 * belief.weight;
      }
      return total;
    }, 0);
    return totalDamage + replyDamage * intel.confidence;
  }, 0);
  plan.cache.plannerReplyDamage.set(cacheKey, replyDamage);
  return replyDamage;
}

function scoreEnemySupplyTruckDamageRisk(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  action?: { targetId?: string; expectedOutcome?: ExpectedAttackOutcome }
): number {
  if (unit.owner !== "Enemy" || !isEnemySupplySupportUnit(unit.type)) {
    return 0;
  }

  const replyDamage = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, coord, plan, action);
  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  const damageRisk = Math.max(replyDamage, danger);
  if (damageRisk <= 0) {
    return 0;
  }

  return 4_000 + damageRisk * 240 + getUnitInstanceValue(state, unit) * 3;
}

function getPlausibleEnemyCompoundActions(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  actions: EnemyCompoundAction[]
): EnemyCompoundAction[] {
  return actions.filter((action) => isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan));
}

function isAirUnitExposedToStationaryAntiAir(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  action: EnemyAirActionPayoffContext,
  plan?: EnemyTurnPlan
): boolean {
  return !isEnemyAirMoveAllowedByThreatMap(state, unit, coord, action, plan);
}

function isEnemyAirMoveAllowedByThreatMap(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  action: EnemyAirActionPayoffContext,
  plan?: EnemyTurnPlan,
  threatMap = getEnemyAntiAirThreatMap(state, plan)
): boolean {
  if (getUnitDefinition(unit.type).domain !== "Air") {
    return true;
  }

  const coveringThreats = getAntiAirThreatsCoveringCoord(state, unit, coord, threatMap);
  if (coveringThreats.length && !isDecisiveAirActionPayoff(state, action, coveringThreats)) {
    return false;
  }

  const mobileAirThreats = getPlayerMobileAirThreatsCoveringCoord(state, unit, coord, plan);
  if (mobileAirThreats.length && !isDecisiveMobileAirThreatPayoff(state, action, mobileAirThreats)) {
    return false;
  }
  return true;
}

function isEnemyAirMoveCandidateAllowed(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  threatMap: EnemyAntiAirThreatMap,
  action?: Partial<EnemyAirActionPayoffContext>
): boolean {
  return isEnemyAirMoveAllowedByThreatMap(
    state,
    unit,
    coord,
    {
      unitType: unit.type,
      unitId: unit.id,
      ...action
    },
    plan,
    threatMap
  );
}

function getEnemyAntiAirThreatMap(state: GameState, plan?: EnemyTurnPlan): EnemyAntiAirThreatMap {
  const cache = getEnemyEvaluationCache(state);
  if (cache.antiAirThreatMap && cache.antiAirThreatMapPlan === plan) {
    return cache.antiAirThreatMap;
  }

  cache.antiAirThreatMap = buildEnemyAntiAirThreatMap(state, plan);
  cache.antiAirThreatMapPlan = plan;
  return cache.antiAirThreatMap;
}

function buildEnemyAntiAirThreatMap(state: GameState, plan?: EnemyTurnPlan): EnemyAntiAirThreatMap {
  const threats: EnemyAntiAirThreat[] = [];
  const addThreat = (threat: EnemyAntiAirThreat): void => {
    const key = `${threat.id}:${hexId(threat.coord)}`;
    if (threats.some((existing) => `${existing.id}:${hexId(existing.coord)}` === key)) {
      return;
    }
    threats.push(threat);
  };

  for (const antiAir of getKnownAntiAirThreatsForEnemy(state, plan)) {
    addThreat({
      id: antiAir.id,
      coord: { ...antiAir.coord },
      unit: antiAir,
      confidence: 1,
      probable: false
    });
  }

  for (const antiAir of getAntiAirBeliefThreatsForEnemy(state, plan)) {
    addThreat({
      id: antiAir.unit.id,
      coord: { ...antiAir.coord },
      unit: { ...antiAir.unit, coord: { ...antiAir.coord } },
      confidence: antiAir.confidence,
      probable: false
    });
  }

  for (const coord of getProbableAntiAirAmbushCoordsForEnemy(state, plan)) {
    addThreat({
      id: `probable-aa-${hexId(coord)}`,
      coord: { ...coord },
      confidence: 0.55,
      probable: true
    });
  }

  return { threats };
}

function getAntiAirThreatsCoveringCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  threatMap: EnemyAntiAirThreatMap
): EnemyAntiAirThreat[] {
  return threatMap.threats.filter((threat) => {
    const owner: Owner = threat.unit?.owner ?? "Player";
    const level = threat.unit?.level ?? state.economy.unitLevels["Anti-Air"] ?? 1;
    if (!canUnitTargetUnit("Anti-Air", unit.type)) {
      return false;
    }
    const stats = getEffectiveUnitStats(state, owner, "Anti-Air", level, threat.coord, coord);
    return hexDistance(coord, threat.coord) <= stats.attackRange;
  });
}

function getPlayerMobileAirThreatsCoveringCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan?: EnemyTurnPlan
): UnitInstance[] {
  if (getUnitDefinition(unit.type).domain !== "Air") {
    return [];
  }

  const threatsById = new Map<string, UnitInstance>();
  for (const intel of plan?.playerIntel ?? getEnemyPlannerPlayerIntel(state)) {
    if (
      getUnitDefinition(intel.unit.type).domain !== "Air" ||
      !canUnitTargetUnit(intel.unit.type, unit.type) ||
      intel.confidence < 0.35
    ) {
      continue;
    }

    const beliefs = intel.currentBeliefs;
    for (const belief of beliefs) {
      if (belief.weight * intel.confidence < 0.12) {
        continue;
      }
      const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, belief.coord, coord);
      const reach = stats.attackRange + (getUnitDefinition(intel.unit.type).cannotMoveAndAttack ? 0 : stats.moveRange);
      if (hexDistance(belief.coord, coord) <= reach) {
        threatsById.set(intel.unit.id, { ...intel.unit, coord: { ...belief.coord } });
        break;
      }
    }
  }
  return Array.from(threatsById.values());
}

function getKnownAntiAirThreatsForEnemy(state: GameState, plan?: EnemyTurnPlan): UnitInstance[] {
  const cache = getEnemyEvaluationCache(state);
  if (cache.knownAntiAirThreats && cache.knownAntiAirThreatsPlan === plan) {
    return cache.knownAntiAirThreats;
  }

  const threatsById = new Map<string, UnitInstance>();
  const add = (unit: UnitInstance): void => {
    if (unit.owner === "Player" && unit.type === "Anti-Air") {
      threatsById.set(unit.id, unit);
    }
  };

  for (const intel of plan?.playerIntel ?? []) {
    if (intel.unit.type !== "Anti-Air") {
      continue;
    }
    add({ ...intel.unit, coord: { ...intel.predictedCoord } });
  }

  for (const intel of getPlayerIntelForEnemy(state)) {
    if (intel.unit.type === "Anti-Air") {
      add({ ...intel.unit, coord: { ...intel.predictedCoord } });
    }
  }

  cache.knownAntiAirThreats = Array.from(threatsById.values());
  cache.knownAntiAirThreatsPlan = plan;
  return cache.knownAntiAirThreats;
}

function getAntiAirBeliefThreatsForEnemy(state: GameState, plan?: EnemyTurnPlan): Array<{ unit: UnitInstance; coord: UnitInstance["coord"]; confidence: number }> {
  if (!plan) {
    return [];
  }

  return plan.playerIntel
    .filter((intel) => intel.unit.type === "Anti-Air")
    .flatMap((intel) => [...intel.currentBeliefs, ...intel.nextTurnRepositionZone]
      .filter((belief) => belief.weight * intel.confidence >= 0.12)
      .map((belief) => ({
        unit: intel.unit,
        coord: belief.coord,
        confidence: belief.weight * intel.confidence
      })));
}

function getProbableAntiAirAmbushCoordsForEnemy(state: GameState, plan?: EnemyTurnPlan): UnitInstance["coord"][] {
  const playerIntel = plan?.playerIntel ?? getEnemyPlannerPlayerIntel(state);
  const antiAirIntel = playerIntel.filter((intel) => intel.unit.type === "Anti-Air");
  const playerCanProduceAntiAir = canOwnerProduceUnit(state, "Player", "Anti-Air");
  if ((state.day < 8 || !playerCanProduceAntiAir) && !antiAirIntel.length) {
    return [];
  }

  const coords: UnitInstance["coord"][] = [];
  const add = (coord: UnitInstance["coord"] | undefined): void => {
    if (coord && isPassableMapCoord(state, coord)) {
      coords.push({ ...coord });
    }
  };
  const addNearby = (coord: UnitInstance["coord"] | undefined, radius: number): void => {
    if (!coord) {
      return;
    }
    for (const candidate of getPassableCoordsNear(state, coord, radius)) {
      add(candidate);
    }
  };

  for (const intel of antiAirIntel) {
    add(intel.lastSeenCoord);
    add(intel.predictedCoord);
    for (const belief of [
      ...intel.currentBeliefs.filter((belief) => belief.weight * intel.confidence >= 0.08),
      ...intel.nextTurnRepositionZone.filter((belief) => belief.weight * intel.confidence >= 0.07),
      ...intel.longTermProjection.filter((belief) => belief.weight * intel.confidence >= 0.1)
    ]) {
      add(belief.coord);
    }
    addNearby(intel.lastSeenCoord, Math.min(2, Math.max(1, intel.age)));
  }

  const pressureGates = (state.gates ?? []).filter(
    (gate) =>
      gate.owner === "Player" ||
      gate.occupation.Player > 0 ||
      playerIntel.some((intel) => hexDistance(intel.predictedCoord, gate.coord) <= 4)
  );
  if (playerCanProduceAntiAir) {
    for (const gate of pressureGates) {
      for (const coord of [
      gate.coord,
      { q: gate.coord.q, r: Math.min(state.map.height - 1, gate.coord.r + 2) },
      { q: Math.max(0, gate.coord.q - 2), r: Math.min(state.map.height - 1, gate.coord.r + 1) },
      { q: Math.min(state.map.width - 1, gate.coord.q + 2), r: Math.min(state.map.height - 1, gate.coord.r + 1) }
      ]) {
        add(coord);
      }
    }

    for (const gate of (state.gates ?? []).filter((candidate) => candidate.owner === "Player" || pressureGates.some((pressureGate) => pressureGate.id === candidate.id))) {
      const sideHexes = getGateSideHexes(state, gate);
      const sideCandidates = state.map.hexes
        .filter((hex) => hex.passable && sideHexes.has(hex.id) && hexDistance(hex.coord, gate.coord) <= 5)
        .sort((first, second) => hexDistance(first.coord, gate.coord) - hexDistance(second.coord, gate.coord) || first.id.localeCompare(second.id))
        .slice(0, 8);
      for (const hex of sideCandidates) {
        add(hex.coord);
      }
    }

    add({ q: state.bases.Player.q, r: Math.max(0, state.bases.Player.r - 3) });
    for (const protectedCoord of getLikelyPlayerAntiAirProtectedCoords(state, playerIntel)) {
      addNearby(protectedCoord, 2);
    }
  }

  return uniqueCoords(coords).slice(0, 36);
}

function isPassableMapCoord(state: GameState, coord: UnitInstance["coord"]): boolean {
  return state.map.hexes.some((hex) => hex.passable && sameHex(hex.coord, coord));
}

function getPassableCoordsNear(state: GameState, coord: UnitInstance["coord"], radius: number): UnitInstance["coord"][] {
  return state.map.hexes
    .filter((hex) => hex.passable && hexDistance(hex.coord, coord) <= radius)
    .sort((first, second) => hexDistance(first.coord, coord) - hexDistance(second.coord, coord) || first.id.localeCompare(second.id))
    .map((hex) => ({ ...hex.coord }));
}

function getLikelyPlayerAntiAirProtectedCoords(state: GameState, playerIntel: EnemyPlannerPlayerIntel[]): UnitInstance["coord"][] {
  const coords: UnitInstance["coord"][] = [];
  for (const intel of playerIntel) {
    if (intel.unit.type === "Artillery") {
      coords.push(intel.predictedCoord);
    }
    if (
      getUnitDefinition(intel.unit.type).domain === "Ground" &&
      (getUnitInstanceValue(state, intel.unit) >= 82 ||
        intel.unit.type === "Tank" ||
        (state.gates ?? []).some((gate) => hexDistance(intel.predictedCoord, gate.coord) <= 2))
    ) {
      coords.push(intel.predictedCoord);
    }
  }

  for (const gate of state.gates ?? []) {
    if (gate.owner === "Player" || gate.occupation.Player > 0) {
      coords.push(gate.coord);
    }
  }
  coords.push(state.bases.Player);
  return uniqueCoords(coords);
}

function shouldRejectEnemyAirThreatStall(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): boolean {
  if (getUnitDefinition(unit.type).domain !== "Air" || action.moveTo || unit.hasMovedThisDay || getRemainingMovementPoints(state, unit) <= 0) {
    return false;
  }

  const currentAction: EnemyAirActionPayoffContext = {
    unitId: unit.id,
    unitType: unit.type,
    targetId: action.targetId,
    expectedOutcome: action.expectedOutcome
  };
  if (isEnemyAirMoveAllowedByThreatMap(state, unit, unit.coord, currentAction, plan)) {
    return false;
  }

  const visible = getVisibleHexIdsForOwner(state, "Enemy");
  return getLegalMoveCoordsWithVisibility(state, unit, visible).some((coord) =>
    canMoveUnitTo(state, unit, coord) &&
    isEnemyAirMoveAllowedByThreatMap(state, unit, coord, currentAction, plan)
  );
}

function isDecisiveAirActionPayoff(state: GameState, action: EnemyAirActionPayoffContext, coveringThreats: EnemyAntiAirThreat[]): boolean {
  if (!action.targetId) {
    return false;
  }

  const target = getUnitById(state, action.targetId);
  if (!target) {
    return false;
  }
  if (isImmediateObjectiveLossPending(state, target)) {
    return true;
  }

  if (target.type === "Anti-Air") {
    if (isHighAltitudeAntiAirSuppressionPayoff(state, action, target, coveringThreats)) {
      return true;
    }
    return isAntiAirCoverageReliablyClearedByAction(state, action, target, coveringThreats);
  }

  return false;
}

function isHighAltitudeAntiAirSuppressionPayoff(
  state: GameState,
  action: EnemyAirActionPayoffContext,
  target: UnitInstance,
  coveringThreats: EnemyAntiAirThreat[]
): boolean {
  const outcome = action.expectedOutcome;
  if (!outcome || !isEnemyPriorityAntiAirHunter(action.unitType)) {
    return false;
  }

  const independentCoverage = coveringThreats.some((threat) => {
    if (threat.unit) {
      return threat.unit.id !== target.id;
    }
    if (action.unitType === "Bomber" && !action.moveAttackRetreatAttackTile) {
      return false;
    }
    return !threat.probable || hexDistance(threat.coord, target.coord) > 2;
  });
  if (independentCoverage) {
    return false;
  }

  const health = Math.max(1, target.health);
  if (action.moveAttackRetreatAttackTile) {
    return outcome.expectedDamage >= health * 0.75 || outcome.normalDamage >= health || outcome.criticalDamage >= health;
  }
  if (action.unitType !== "Bomber") {
    return false;
  }
  return outcome.expectedDamage > 0 || outcome.killProbability >= 0.45 || outcome.normalDamage >= health;
}

function isMoveAttackRetreatAntiAirSuppressionPayoff(
  state: GameState,
  action: EnemyAirActionPayoffContext,
  target: UnitInstance,
  coveringThreats: EnemyAntiAirThreat[]
): boolean {
  const outcome = action.expectedOutcome;
  if (!outcome || !isEnemyPriorityAntiAirHunter(action.unitType)) {
    return false;
  }

  const independentCoverage = coveringThreats.some((threat) => {
    if (threat.unit) {
      return threat.unit.id !== target.id;
    }
    return !threat.probable || hexDistance(threat.coord, target.coord) > 2;
  });
  if (independentCoverage) {
    return false;
  }

  const health = Math.max(1, target.health);
  return outcome.expectedDamage >= health * 0.75 || outcome.normalDamage >= health || outcome.criticalDamage >= health;
}

function isDecisiveMobileAirThreatPayoff(state: GameState, action: EnemyAirActionPayoffContext, mobileAirThreats: UnitInstance[]): boolean {
  if (!action.targetId) {
    return false;
  }

  const target = getUnitById(state, action.targetId);
  if (!target) {
    return false;
  }
  if (isImmediateObjectiveLossPending(state, target)) {
    return true;
  }
  if (!mobileAirThreats.some((threat) => threat.id === target.id)) {
    return false;
  }

  const outcome = action.expectedOutcome;
  if (!outcome) {
    return false;
  }

  const expensiveAirframe = action.unitType === "Bomber" || action.unitType === "Reaper";
  const requiredKillProbability = expensiveAirframe ? 0.94 : 0.86;
  const maxMissProbability = expensiveAirframe ? 0.08 : 0.14;
  return (
    outcome.killProbability + 1e-9 >= requiredKillProbability &&
    outcome.missProbability - 1e-9 <= maxMissProbability &&
    outcome.expectedDamage >= Math.max(1, target.health)
  );
}

function isAntiAirCoverageReliablyClearedByAction(
  state: GameState,
  action: EnemyAirActionPayoffContext,
  target: UnitInstance,
  coveringThreats: EnemyAntiAirThreat[]
): boolean {
  const outcome = action.expectedOutcome;
  if (!outcome) {
    return false;
  }
  const independentCoverage = coveringThreats.some((threat) => {
    if (threat.unit) {
      return threat.unit.id !== target.id;
    }
    return !threat.probable || hexDistance(threat.coord, target.coord) > 2;
  });
  if (independentCoverage) {
    return false;
  }

  const expensiveAirframe = action.unitType === "Bomber" || action.unitType === "Reaper";
  const requiredKillProbability = expensiveAirframe ? 0.96 : 0.9;
  const maxMissProbability = expensiveAirframe ? 0.06 : 0.12;
  if (outcome.killProbability + 1e-9 < requiredKillProbability || outcome.missProbability - 1e-9 > maxMissProbability) {
    return false;
  }

  const health = Math.max(1, target.health);
  const expectedDamageRatio = outcome.expectedDamage / health;
  const normalKills = outcome.normalDamage >= health;
  const criticalKills = outcome.criticalDamage >= health;
  const criticalFishing = !normalKills && criticalKills;
  if (expectedDamageRatio + 1e-9 < (expensiveAirframe ? 1.08 : 1) || (!normalKills && !criticalKills)) {
    return false;
  }
  if (criticalFishing && outcome.criticalDamageProbability < (expensiveAirframe ? 0.9 : 0.72)) {
    return false;
  }

  if (!expensiveAirframe) {
    return true;
  }

  const attacker = action.unitId ? getUnitById(state, action.unitId) : undefined;
  const attackerValue = attacker ? getUnitInstanceValue(state, attacker) : getUnitTypeValue(state, "Enemy", action.unitType);
  const targetValue = getUnitInstanceValue(state, target);
  const expectedRemovalValue = targetValue * outcome.killProbability + targetValue * Math.min(1, expectedDamageRatio) * 0.2;
  const expectedExposureCost = attackerValue * ((1 - outcome.killProbability) * 0.9 + outcome.missProbability * 0.45);
  return expectedRemovalValue >= expectedExposureCost || (outcome.killProbability >= 0.99 && expectedDamageRatio >= 1.2);
}

function isImmediateObjectiveLossPending(state: GameState, target: UnitInstance): boolean {
  if (!getUnitDefinition(target.type).humanBased) {
    return false;
  }
  if (sameHex(target.coord, state.bases.Enemy) && state.baseOccupation.Enemy >= BASE_CAPTURE_DAYS - 1) {
    return true;
  }
  return (state.gates ?? []).some((gate) => sameHex(target.coord, gate.coord) && gate.occupation.Player >= GATE_CAPTURE_DAYS - 1);
}

function isScoutActionRecklesslyExposed(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan
): boolean {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const openingIfvScout = isHardOpeningIfvGateOccupancyForbidden(state, unit);
  if (!openingIfvScout && mission !== "Scout" && mission !== "PatrolWest" && mission !== "PatrolEast") {
    return false;
  }
  if (!isReconUnit(unit.type) && !isPatrolCapableUnit(unit.type)) {
    return false;
  }

  if (isGateHex(state, coord)) {
    return true;
  }

  if (action.targetId && (action.expectedOutcome?.killProbability ?? 0) >= 0.78) {
    return false;
  }

  const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
  if (isEnemyPlannerOneShotExposed(state, unit, coord, plan)) {
    return true;
  }

  const healthRatio = unit.health / Math.max(1, unit.maxHealth);
  const dangerLimit = unit.health * (healthRatio < 0.6 ? 0.34 : 0.52);
  if (isScoutInsideKnownPlayerThreatEnvelope(state, unit, coord, plan, healthRatio < 0.6 ? 0.2 : 0.3)) {
    return true;
  }
  if (danger < dangerLimit) {
    return false;
  }

  return plan.playerIntel.some((intel) => {
    if (!canUnitTargetUnit(intel.unit.type, unit.type)) {
      return false;
    }
    const playerUnit = { ...intel.unit, coord: intel.predictedCoord };
    const damage = estimateAttackDamage(state, playerUnit, unit);
    if (damage < unit.health * 0.35) {
      return false;
    }
    return intel.currentBeliefs.some((belief) => {
      const distance = hexDistance(coord, belief.coord);
      const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, belief.coord, coord);
      return distance <= stats.attackRange || (!getUnitDefinition(intel.unit.type).cannotMoveAndAttack && distance <= stats.attackRange + stats.moveRange);
    });
  });
}

function isScoutInsideKnownPlayerThreatEnvelope(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan,
  healthDamageRatio: number
): boolean {
  return plan.playerIntel.some((intel) => {
    if (!canUnitTargetUnit(intel.unit.type, unit.type)) {
      return false;
    }

    const playerUnit = { ...intel.unit, coord: intel.predictedCoord };
    const damage = estimateAttackDamage(state, playerUnit, unit);
    if (damage < unit.health * healthDamageRatio) {
      return false;
    }

    return intel.currentBeliefs.some((belief) => {
      const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, belief.coord, coord);
      const threatReach = stats.attackRange + (getUnitDefinition(intel.unit.type).cannotMoveAndAttack ? 0 : stats.moveRange);
      return hexDistance(coord, belief.coord) <= threatReach;
    });
  });
}

function isGateHex(state: GameState, coord: UnitInstance["coord"]): boolean {
  return (state.gates ?? []).some((gate) => sameHex(gate.coord, coord));
}

function getEnemyDestinationReservationKey(unitType: UnitType, coord: UnitInstance["coord"]): string {
  const domain: UnitDomain = getUnitDefinition(unitType).domain;
  return `${domain}:${hexId(coord)}`;
}

function reserveEnemyActionDestination(action: EnemyCompoundAction, reservations: Record<string, string>): void {
  const destination = getEnemyCompoundActionReservedCoord(action);
  if (!destination) {
    return;
  }
  reservations[getEnemyDestinationReservationKey(action.unitType, destination)] = action.unitId;
}

function cloneReservedExpectedDamage(
  reserved: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }> {
  return Object.fromEntries(
    Object.entries(reserved).map(([targetId, value]) => [
      targetId,
      {
        expectedDamage: value.expectedDamage,
        killProbability: value.killProbability,
        unitIds: [...value.unitIds]
      }
    ])
  );
}

function reserveEnemyActionExpectedDamage(
  action: EnemyCompoundAction,
  reserved: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): void {
  if (!action.targetId || !action.expectedOutcome) {
    return;
  }
  const existing = reserved[action.targetId] ?? { expectedDamage: 0, killProbability: 0, unitIds: [] };
  existing.expectedDamage += action.expectedOutcome.expectedDamage;
  existing.killProbability = 1 - (1 - existing.killProbability) * (1 - action.expectedOutcome.killProbability);
  if (!existing.unitIds.includes(action.unitId)) {
    existing.unitIds.push(action.unitId);
  }
  reserved[action.targetId] = existing;
}

function compareEnemyCompoundActionsForPlanning(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  first: EnemyCompoundAction,
  second: EnemyCompoundAction
): number {
  const directObjectivePreference = compareDirectObjectiveAttackPreference(state, unit, plan, first, second);
  if (directObjectivePreference !== 0) {
    return directObjectivePreference;
  }
  const scoreDelta = second.breakdown.total - first.breakdown.total;
  const simplePreference = compareEffectivelyTiedAttackComplexity(state, unit, plan, first, second, scoreDelta);
  if (simplePreference !== 0) {
    return simplePreference;
  }
  if (scoreDelta !== 0) {
    return scoreDelta;
  }
  const firstTie = getEnemyCombatObjectiveTieBreakScore(state, unit, first, plan);
  const secondTie = getEnemyCombatObjectiveTieBreakScore(state, unit, second, plan);
  return secondTie - firstTie || first.id.localeCompare(second.id);
}

function compareDirectObjectiveAttackPreference(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  first: EnemyCompoundAction,
  second: EnemyCompoundAction
): number {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (mission !== "CaptureGate" && mission !== "DefendGate") {
    return 0;
  }
  if (!first.targetId || first.targetId !== second.targetId) {
    return 0;
  }
  const target = getUnitById(state, first.targetId);
  if (!target || !canUnitAttackHex(state, unit, target.coord)) {
    return 0;
  }
  const directRank = (action: EnemyCompoundAction): number =>
    action.kind === "Attack" ? 0 :
    action.kind === "AttackThenMove" ? 1 :
    action.kind === "MoveThenAttack" ? 2 :
    action.kind === "MoveAttackRetreat" ? 3 :
    4;
  return directRank(first) - directRank(second);
}

function compareEffectivelyTiedAttackComplexity(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  first: EnemyCompoundAction,
  second: EnemyCompoundAction,
  scoreDelta: number
): number {
  if (Math.abs(scoreDelta) > 35 || first.targetId !== second.targetId || !first.targetId) {
    return 0;
  }

  if (first.kind === "Attack" && isEnemyComplexAttackAction(second) && !doesEnemyComplexAttackImproveMeasurably(state, unit, first, second, plan)) {
    return -1;
  }
  if (second.kind === "Attack" && isEnemyComplexAttackAction(first) && !doesEnemyComplexAttackImproveMeasurably(state, unit, second, first, plan)) {
    return 1;
  }
  return 0;
}

function isEnemyComplexAttackAction(action: EnemyCompoundAction): boolean {
  return action.kind === "MoveAttackRetreat" || action.kind === "MoveThenAttack" || action.kind === "AttackThenMove";
}

function doesEnemyComplexAttackImproveMeasurably(
  state: GameState,
  unit: UnitInstance,
  simpleAttack: EnemyCompoundAction,
  complexAttack: EnemyCompoundAction,
  plan: EnemyTurnPlan
): boolean {
  const simpleFinal = getEnemyCompoundActionFinalCoord(unit, simpleAttack);
  const complexFinal = getEnemyCompoundActionFinalCoord(unit, complexAttack);
  const simpleReply = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, simpleFinal, plan, simpleAttack);
  const complexReply = estimatePlayerLikelyReplyDamageAtPlanner(state, unit, complexFinal, plan, complexAttack);
  if (complexReply + Math.max(2, unit.health * 0.08) < simpleReply) {
    return true;
  }

  const simpleDanger = estimatePlayerDangerAtPlanner(state, unit, simpleFinal, plan);
  const complexDanger = estimatePlayerDangerAtPlanner(state, unit, complexFinal, plan);
  if (complexDanger + Math.max(2, unit.health * 0.08) < simpleDanger) {
    return true;
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, mission, plan);
  if (hexDistance(complexFinal, objective) < hexDistance(simpleFinal, objective)) {
    return true;
  }

  if (scoreEnemyPathDenial(state, unit, complexFinal, plan) > scoreEnemyPathDenial(state, unit, simpleFinal, plan) + 20) {
    return true;
  }

  const complexFormation = getEnemyPlannerSupportScore(state, unit, complexFinal) + getEnemyPlannerFormationScore(state, unit, complexFinal, mission);
  const simpleFormation = getEnemyPlannerSupportScore(state, unit, simpleFinal) + getEnemyPlannerFormationScore(state, unit, simpleFinal, mission);
  if (complexFormation > simpleFormation + 20) {
    return true;
  }

  if (complexAttack.kind === "MoveAttackRetreat") {
    const attackCoord = complexAttack.moveTo ?? unit.coord;
    const retreatCoord = complexAttack.retreatTo ?? complexFinal;
    const exchange = getEnemyMoveAttackRetreatExchange(state, unit, attackCoord, retreatCoord, complexAttack, plan);
    return exchange.retreatReplyDamage + Math.max(2, unit.health * 0.08) < exchange.attackReplyDamage;
  }

  return false;
}

function getEnemyCombatObjectiveTieBreakScore(state: GameState, unit: UnitInstance, action: EnemyCompoundAction, plan: EnemyTurnPlan): number {
  if (!action.targetId || !action.expectedOutcome) {
    return 0;
  }
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const objective = chooseEnemyCombatFollowThroughObjective(state, unit, mission, plan);
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
  const progress = hexDistance(unit.coord, objective) - hexDistance(finalCoord, objective);
  const killScore = action.expectedOutcome.killProbability >= 0.55 ? 100 : 0;
  const sequenceScore = action.kind === "MoveThenAttack" ? 12 : action.kind === "MoveAttackRetreat" ? 10 : action.kind === "AttackThenMove" ? 6 : action.kind === "Attack" ? 2 : 0;
  return killScore + Math.max(0, progress) * 25 + sequenceScore;
}

function getEnemyActionListTieBreak(actions: EnemyCompoundAction[]): string {
  return actions.map(getEnemyActionTieBreak).join("|");
}

function appendEnemyActionTieBreak(existing: string, action: EnemyCompoundAction): string {
  const next = getEnemyActionTieBreak(action);
  return existing ? `${existing}|${next}` : next;
}

function getEnemyActionTieBreak(action: EnemyCompoundAction): string {
  return `${getEnemyActionKindTieBreakRank(action)}:${action.id}`;
}

function getEnemyActionKindTieBreakRank(action: EnemyCompoundAction): number {
  if (action.targetId && action.expectedOutcome?.killProbability && action.expectedOutcome.killProbability >= 0.55) {
    if (action.kind === "MoveThenAttack") return 0;
    if (action.kind === "MoveAttackRetreat") return 1;
    if (action.kind === "AttackThenMove") return 2;
    if (action.kind === "Attack") return 3;
  }
  if (action.kind === "Move") return 4;
  if (action.kind === "Hold") return 5;
  return 6;
}

function applyExpectedEnemyCompoundActionForPlanning(state: GameState, action: EnemyCompoundAction): void {
  const unit = state.units.find((candidate) => candidate.id === action.unitId && candidate.owner === "Enemy");
  if (!unit) {
    return;
  }
  if ((action.kind === "Move" || action.kind === "MoveThenAttack" || action.kind === "MoveAttackRetreat") && action.moveTo && canMoveUnitTo(state, unit, action.moveTo)) {
    applyPlanningMove(state, unit, action.moveTo);
  }
  if ((action.kind === "Attack" || action.kind === "MoveThenAttack" || action.kind === "AttackThenMove" || action.kind === "MoveAttackRetreat") && action.targetId && !unit.hasAttackedThisDay) {
    applyPlanningExpectedAttack(state, unit, action);
  }
  if (action.kind === "AttackThenMove" && action.moveTo && canMoveUnitTo(state, unit, action.moveTo)) {
    applyPlanningMove(state, unit, action.moveTo);
  }
  if (action.kind === "MoveAttackRetreat" && action.retreatTo && canMoveUnitTo(state, unit, action.retreatTo)) {
    applyPlanningMove(state, unit, action.retreatTo);
  }
}

function applyPlanningMove(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): void {
  const moveCost = hexDistance(unit.coord, coord);
  unit.coord = { ...coord };
  unit.movementSpentThisDay = (unit.movementSpentThisDay ?? 0) + moveCost;
  unit.hasMovedThisDay = unit.movementSpentThisDay >= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord).moveRange;
  invalidateEnemyEvaluationCache();
}

function applyPlanningExpectedAttack(state: GameState, unit: UnitInstance, action: EnemyCompoundAction): void {
  const target = state.units.find((candidate) => candidate.id === action.targetId && candidate.owner === "Player");
  if (!target || !action.expectedOutcome) {
    return;
  }
  unit.hasAttackedThisDay = true;
  target.health -= Math.floor(action.expectedOutcome.expectedDamage);
  if (target.health <= 0 || action.expectedOutcome.killProbability >= 0.82) {
    state.units = state.units.filter((candidate) => candidate.id !== target.id);
  }
  invalidateEnemyEvaluationCache();
}

function executeEnemyCompoundAction(state: GameState, action: EnemyCompoundAction, plan: EnemyTurnPlan, context?: EngineDispatchContext): boolean {
  const unit = state.units.find((candidate) => candidate.id === action.unitId && candidate.owner === "Enemy");
  if (!unit) {
    return true;
  }
  debugEnemyPlanner(formatEnemyPlannerActionDebug(action));
  return executeEnemyCompoundActionDirect(state, unit, action, plan, context);
}

function withEnemyActionLogDetail<T>(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan | undefined,
  context: EngineDispatchContext | undefined,
  callback: () => T
): T {
  if (!context || unit.owner !== "Enemy") {
    return callback();
  }

  context.enemyUnitLogDetails ??= {};
  const previous = context.enemyUnitLogDetails[unit.id];
  context.enemyUnitLogDetails[unit.id] = createEnemyActionLogDetail(state, unit, action, plan);
  try {
    return callback();
  } finally {
    if (previous) {
      context.enemyUnitLogDetails[unit.id] = previous;
    } else {
      delete context.enemyUnitLogDetails[unit.id];
    }
  }
}

function createEnemyActionLogDetail(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan?: EnemyTurnPlan
): EnemyUnitLogDetail {
  const mission = plan?.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  return {
    mission,
    why: formatEnemyActionLogWhy(state, unit, action, plan, mission)
  };
}

function formatEnemyActionLogWhy(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan: EnemyTurnPlan | undefined,
  mission: EnemyMission
): string {
  const parts: string[] = [];
  const objective = plan ? describeEnemyMissionObjective(state, unit, mission, plan) : undefined;
  const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);

  if (objective && (action.moveTo || action.retreatTo)) {
    const currentDistance = hexDistance(unit.coord, objective.coord);
    const finalDistance = hexDistance(finalCoord, objective.coord);
    if (sameHex(finalCoord, objective.coord)) {
      parts.push(`reaches ${objective.label}`);
    } else if (finalDistance < currentDistance) {
      parts.push(`moves ${currentDistance - finalDistance} closer to ${objective.label}`);
    } else {
      parts.push(`positions for ${objective.label}`);
    }
  }

  if (action.targetType && action.expectedOutcome) {
    parts.push(`targets ${action.targetType}, ${Math.round(action.expectedOutcome.expectedDamage)} expected damage, ${Math.round(action.expectedOutcome.killProbability * 100)}% kill`);
  }

  const scoreSummary = formatEnemyActionScoreSummary(action.breakdown);
  if (scoreSummary) {
    parts.push(scoreSummary);
  }

  if (!parts.length) {
    parts.push(action.kind === "Move" ? `best ${mission} movement available` : `best ${mission} action available`);
  }

  return parts.join("; ");
}

function describeEnemyMissionObjective(
  state: GameState,
  unit: UnitInstance,
  mission: EnemyMission,
  plan: EnemyTurnPlan
): { label: string; coord: UnitInstance["coord"] } | undefined {
  if (mission === "CaptureBase") {
    return { label: `Player Base ${displayHexId(state.map, state.bases.Player)}`, coord: state.bases.Player };
  }

  if (mission === "DefendBase" || mission === "BaseSentry") {
    return { label: `Enemy Base ${displayHexId(state.map, state.bases.Enemy)}`, coord: state.bases.Enemy };
  }

  if (mission === "ProtectCapturer") {
    const capturer = getEnemyBaseHoldCapturer(state, plan);
    return capturer ? { label: `${capturer.type} capturer ${displayHexId(state.map, capturer.coord)}`, coord: capturer.coord } : undefined;
  }

  if (mission === "Repair") {
    return { label: "nearest repair support", coord: finalRepairObjectiveCoord(state, unit) ?? unit.coord };
  }

  const gate =
    mission === "PatrolWest" || mission === "PatrolEast"
      ? (state.gates ?? []).find((candidate) => candidate.id === (mission === "PatrolWest" ? "West" : "East"))
      : mission === "CaptureGate" || mission === "ShadowCapturer" || mission === "EscortCapture"
        ? chooseEnemyPlannerGateTargetForUnit(state, unit, plan)
        : mission === "DefendGate" || isEnemyGateLockoutCombatMission(mission)
          ? chooseEnemyPlannerGateObjectiveForUnit(state, unit, plan, mission)
          : undefined;

  if (gate) {
    return { label: `${gate.label} ${displayHexId(state.map, gate.coord)}`, coord: gate.coord };
  }

  if (plan.secondaryObjective && (mission === "Scout" || mission === "Escort" || mission === "Siege" || mission === "InterceptAir" || mission === "HuntArtillery")) {
    return { label: `secondary objective ${displayHexId(state.map, plan.secondaryObjective)}`, coord: plan.secondaryObjective };
  }

  return { label: `primary objective ${displayHexId(state.map, plan.primaryObjective)}`, coord: plan.primaryObjective };
}

function finalRepairObjectiveCoord(state: GameState, unit: UnitInstance): UnitInstance["coord"] | undefined {
  return getOwnerUnits(state, "Enemy")
    .filter((candidate) => candidate.id !== unit.id && isEnemySupplySupportUnit(candidate.type))
    .sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord) || first.id.localeCompare(second.id))[0]?.coord;
}

function formatEnemyActionScoreSummary(breakdown: EnemyPlannerScoreBreakdown): string {
  const objective =
    breakdown.baseCaptureClock +
    breakdown.gateCaptureClock +
    breakdown.backupCapturerValue +
    breakdown.replacementDistance +
    breakdown.income +
    breakdown.taskProgress;
  const material = breakdown.material + breakdown.expectedDamage + breakdown.killProbability;
  const risk = breakdown.expectedLoss + breakdown.opponentReplyRisk;
  const support = breakdown.support + breakdown.formation + breakdown.repairValue;
  const intel = breakdown.informationGain + breakdown.territoryControl;
  const components = [
    ["terminal", breakdown.terminal],
    ["objective", objective],
    ["material", material],
    ["risk", risk],
    ["intel", intel],
    ["support", support],
    ["congestion", breakdown.congestion],
    ["doctrine", breakdown.doctrine],
    ["tempo", breakdown.opportunityCost + breakdown.tempoRisk],
    ["initiative", breakdown.initiative]
  ] as Array<[string, number]>;
  const strongest = components
    .filter(([, value]) => Math.abs(value) >= 1)
    .sort((first, second) => Math.abs(second[1]) - Math.abs(first[1]))
    .slice(0, 3)
    .map(([label, value]) => `${label} ${formatSignedScore(value)}`);

  return strongest.length ? `score ${Math.round(breakdown.total)} (${strongest.join(", ")})` : "";
}

function formatSignedScore(value: number): string {
  const rounded = Math.round(value);
  return `${rounded >= 0 ? "+" : ""}${rounded}`;
}

function executeEnemyCompoundActionDirect(
  state: GameState,
  unit: UnitInstance,
  action: EnemyCompoundAction,
  plan?: EnemyTurnPlan,
  context?: EngineDispatchContext
): boolean {
  if (action.kind === "Hold") {
    return !plan || !shouldRejectOpeningCaptureGateHold(state, unit, plan);
  }

  if ((action.kind === "MoveThenAttack" || action.kind === "AttackThenMove" || action.kind === "MoveAttackRetreat") && isMoveAttackExclusiveUnit(unit.type)) {
    return false;
  }

  if (plan && !isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan)) {
    return false;
  }

  if (action.kind === "Attack") {
    if (!action.attackAt || !canUnitAttackHex(state, unit, action.attackAt)) {
      return false;
    }
    const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
    if (plan && target && !isEnemyFireSupportAttackIntelAuthorized(state, unit, target, plan)) {
      return false;
    }
    withEnemyActionLogDetail(state, unit, action, plan, context, () => attackHexWithUnit(state, unit, action.attackAt!, context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    return true;
  }

  if (action.kind === "Move") {
    if (!action.moveTo || !canMoveUnitTo(state, unit, action.moveTo)) {
      return false;
    }
    if (isAirUnitExposedToStationaryAntiAir(state, unit, action.moveTo, { ...action, moveAttackRetreatAttackTile: true }, plan)) {
      return false;
    }
    withEnemyActionLogDetail(state, unit, action, plan, context, () => moveUnitTo(state, unit, action.moveTo!, "preserve", context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    return true;
  }

  if (action.kind === "MoveThenAttack") {
    if (!action.moveTo || !canMoveUnitTo(state, unit, action.moveTo)) {
      return false;
    }
    if (isAirUnitExposedToStationaryAntiAir(state, unit, action.moveTo, action, plan)) {
      return false;
    }
    withEnemyActionLogDetail(state, unit, action, plan, context, () => moveUnitTo(state, unit, action.moveTo!, "preserve", context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    const moved = state.units.find((candidate) => candidate.id === unit.id && candidate.owner === "Enemy");
    if (!moved || !action.attackAt || !canUnitAttackHex(state, moved, action.attackAt)) {
      return true;
    }
    const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
    if (plan && target && !isEnemyFireSupportAttackIntelAuthorized(state, moved, target, plan)) {
      return true;
    }
    withEnemyActionLogDetail(state, moved, action, plan, context, () => attackHexWithUnit(state, moved, action.attackAt!, context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    return true;
  }

  if (action.kind === "AttackThenMove") {
    if (!action.attackAt || !canUnitAttackHex(state, unit, action.attackAt)) {
      return false;
    }
    const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
    if (plan && target && !isEnemyFireSupportAttackIntelAuthorized(state, unit, target, plan)) {
      return false;
    }
    withEnemyActionLogDetail(state, unit, action, plan, context, () => attackHexWithUnit(state, unit, action.attackAt!, context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    const attacker = state.units.find((candidate) => candidate.id === unit.id && candidate.owner === "Enemy");
    if (!attacker || !action.moveTo || !canMoveUnitTo(state, attacker, action.moveTo)) {
      return true;
    }
    if (isAirUnitExposedToStationaryAntiAir(state, attacker, action.moveTo, action, plan)) {
      return true;
    }
    withEnemyActionLogDetail(state, attacker, action, plan, context, () => moveUnitTo(state, attacker, action.moveTo!, "preserve", context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    return true;
  }

  if (action.kind === "MoveAttackRetreat") {
    if (!isEnemyMoveAttackRetreatLegsLegal(state, unit, action)) {
      return false;
    }
    if (!action.moveTo || !action.retreatTo || !action.attackAt) {
      return false;
    }
    if (isAirUnitExposedToStationaryAntiAir(state, unit, action.moveTo, action, plan)) {
      return false;
    }
    withEnemyActionLogDetail(state, unit, action, plan, context, () => moveUnitTo(state, unit, action.moveTo!, "preserve", context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    const moved = state.units.find((candidate) => candidate.id === unit.id && candidate.owner === "Enemy");
    if (!moved || !canUnitAttackHex(state, moved, action.attackAt)) {
      return true;
    }
    const target = action.targetId ? getUnitById(state, action.targetId) : undefined;
    if (plan && target && !isEnemyFireSupportAttackIntelAuthorized(state, moved, target, plan)) {
      return true;
    }
    withEnemyActionLogDetail(state, moved, action, plan, context, () => attackHexWithUnit(state, moved, action.attackAt!, context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    const attacker = state.units.find((candidate) => candidate.id === unit.id && candidate.owner === "Enemy");
    if (!attacker || !canMoveUnitTo(state, attacker, action.retreatTo)) {
      return true;
    }
    if (isAirUnitExposedToStationaryAntiAir(state, attacker, action.retreatTo, action, plan)) {
      return true;
    }
    withEnemyActionLogDetail(state, attacker, action, plan, context, () => moveUnitTo(state, attacker, action.retreatTo!, "preserve", context, { refreshFog: false }));
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    return true;
  }

  return false;
}

function executeEnemyLocalFallback(state: GameState, unitId: string, plan: EnemyTurnPlan, context?: EngineDispatchContext): void {
  const unit = state.units.find((candidate) => candidate.id === unitId && candidate.owner === "Enemy");
  if (!unit) {
    return;
  }
  const antiAirFallback = chooseEnemyAirAntiAirLocalFallbackAction(state, unit, plan);
  if (antiAirFallback && executeEnemyCompoundActionDirect(state, unit, antiAirFallback, undefined, context)) {
    return;
  }
  const strategicFallback = chooseEnemyStrategicLocalFallbackAction(state, unit, plan);
  if (strategicFallback && executeEnemyCompoundActionDirect(state, unit, strategicFallback, plan, context)) {
    return;
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (isEnemyBaseAssaultCombatMission(state, unit, mission, plan)) {
    return;
  }

  const action = enumerateEnemyCompoundActions(state, unit, plan, {}, {})
    .filter((candidate) => candidate.kind !== "Hold")
    .sort((first, second) => second.breakdown.total - first.breakdown.total || first.id.localeCompare(second.id))[0];
  if (action && action.breakdown.total > 0) {
    executeEnemyCompoundActionDirect(state, unit, action, plan, context);
  }
}

function chooseEnemyStrategicLocalFallbackAction(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): EnemyCompoundAction | undefined {
  return (
    chooseEnemyRepairLocalFallbackAction(state, unit, plan) ??
    chooseEnemyUnifiedBaseAssaultForcedAction(state, unit, plan) ??
    chooseEnemyAirAntiAirLocalFallbackAction(state, unit, plan) ??
    chooseEnemyCaptureGateLocalFallbackAction(state, unit, plan) ??
    chooseEnemyRoutineObjectiveLocalFallbackAction(state, unit, plan)
  );
}

function chooseEnemyRepairLocalFallbackAction(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): EnemyCompoundAction | undefined {
  if (!shouldEnemyAttemptRepairRetreat(state, unit)) {
    return undefined;
  }
  const moveTo = chooseEnemyRepairFallbackMove(state, unit, plan);
  return moveTo ? createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, {}, {}) : undefined;
}

function chooseEnemyRepairFallbackMove(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const repairContext: EnemyAirActionPayoffContext = {
    unitId: unit.id,
    unitType: unit.type
  };
  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => getNearestEnemyRepairDistance(state, coord, unit.type) < getNearestEnemyRepairDistance(state, unit.coord, unit.type))
    .filter((coord) => isEnemyAirMoveAllowedByThreatMap(state, unit, coord, repairContext, plan))
    .sort((first, second) => getNearestEnemyRepairDistance(state, first, unit.type) - getNearestEnemyRepairDistance(state, second, unit.type) || first.r - second.r || hexId(first).localeCompare(hexId(second)))[0]
    ?? chooseEnemyPlannerRetreatMove(state, unit, plan, {});
}

function chooseEnemyRoutineObjectiveLocalFallbackAction(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): EnemyCompoundAction | undefined {
  return chooseEnemyRoutineObjectiveAction(state, unit, plan, {}, {});
}

function chooseEnemyRoutineObjectiveAction(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string>,
  reservedExpectedDamage: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }>
): EnemyCompoundAction | undefined {
  const repairMove = shouldEnemyAttemptRepairRetreat(state, unit)
    ? chooseEnemyRoutineUnreservedMove(state, unit, chooseEnemyRepairFallbackMove(state, unit, plan), reservedDestinations)
    : undefined;
  const moveTo =
    repairMove ??
    chooseEnemyPlannerOpeningGateCapturerMove(state, unit, plan, reservedDestinations) ??
    chooseEnemyPlannerOpeningGateEscortMove(state, unit, plan, reservedDestinations) ??
    chooseEnemyRoutineUnreservedMove(state, unit, chooseEnemyPlannerForcedBaseAssaultMove(state, unit, plan), reservedDestinations) ??
    chooseEnemyRoutineUnreservedMove(state, unit, chooseEnemyPlannerEndgamePushMove(state, unit, plan), reservedDestinations) ??
    chooseEnemyRoutineUnreservedMove(state, unit, chooseEnemyPlannerForcedGateBreakoutMove(state, unit, plan), reservedDestinations) ??
    chooseEnemyRoutineUnreservedMove(state, unit, chooseEnemyPlannerMidgameCenterControlMove(state, unit, plan), reservedDestinations) ??
    chooseEnemyRoutineUnreservedMove(state, unit, chooseEnemyPlannerEarlyArmorFormationMove(state, unit, plan, reservedDestinations), reservedDestinations) ??
    chooseEnemyRoutineUnreservedMove(state, unit, chooseEnemyPlannerSupplyTruckSupportMove(state, unit, plan), reservedDestinations) ??
    chooseEnemyRoutineUnreservedMove(state, unit, chooseEnemyPlannerFireSupportMove(state, unit, plan), reservedDestinations) ??
    chooseEnemyRoutineObjectiveProgressMove(state, unit, plan, reservedDestinations);

  if (moveTo) {
    const action = createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, reservedDestinations, reservedExpectedDamage);
    return isEnemyCompoundActionPlausiblyLegal(state, unit, action, plan) ? action : undefined;
  }

  return undefined;
}

function chooseEnemyRoutineUnreservedMove(
  state: GameState,
  unit: UnitInstance,
  moveTo: UnitInstance["coord"] | undefined,
  reservedDestinations: Record<string, string>
): UnitInstance["coord"] | undefined {
  if (!moveTo) {
    return undefined;
  }
  const key = getEnemyDestinationReservationKey(unit.type, moveTo);
  return !reservedDestinations[key] || reservedDestinations[key] === unit.id ? moveTo : undefined;
}

function chooseEnemyRoutineObjectiveProgressMove(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  reservedDestinations: Record<string, string> = {}
): UnitInstance["coord"] | undefined {
  if (isEnemySupplySupportUnit(unit.type)) {
    return undefined;
  }

  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  const definition = getUnitDefinition(unit.type);
  const isGateLaneUnit =
    mission === "CaptureGate" ||
    mission === "DefendGate" ||
    mission === "ShadowCapturer" ||
    mission === "EscortCapture" ||
    mission === "Escort" ||
    isOpeningGateSupportUnit(unit.type) ||
    unit.type === "Artillery" ||
    unit.type === "Anti-Air";
  const gate =
    getEnemyCampaignAssignedGateForUnit(state, unit, plan) ??
    chooseEnemyPlannerOpeningGateSupportTarget(state, unit, plan) ??
    chooseEnemyGateRoleTarget(state, "CaptureGate") ??
    chooseGateObjective(state, "Enemy", unit.coord, unit, plan) ??
    (isGateLaneUnit
      ? [...(state.gates ?? [])].sort((first, second) =>
          (first.owner === "Enemy" ? 0 : 1) - (second.owner === "Enemy" ? 0 : 1) ||
          hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord) ||
          first.id.localeCompare(second.id)
        )[0]
      : undefined);

  const target = gate && isGateLaneUnit
    ? gate.coord
    : chooseEnemyPlannerOperationalTarget(state, unit, plan);
  if (!target) {
    return undefined;
  }

  const desiredRadius =
    gate && (mission === "CaptureGate" || mission === "DefendGate")
      ? 0
      : gate && (unit.type === "Artillery" || unit.type === "Anti-Air")
        ? 3
        : gate
          ? 2
          : mission === "CaptureBase" || mission === "DefendBase" || definition.humanBased
            ? 0
            : Math.min(2, Math.max(0, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target).attackRange - 1));
  const currentDistance = hexDistance(unit.coord, target);
  if (currentDistance <= desiredRadius) {
    return undefined;
  }

  return getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => {
      const key = getEnemyDestinationReservationKey(unit.type, coord);
      return !reservedDestinations[key] || reservedDestinations[key] === unit.id;
    })
    .filter((coord) => hexDistance(coord, target) < currentDistance)
    .filter((coord) => {
      if (gate && sameHex(coord, gate.coord) && mission !== "CaptureGate" && mission !== "DefendGate") {
        return false;
      }
      if (gate && mission === "CaptureGate" && sameHex(coord, gate.coord)) {
        return isGateSafeForRecapture(state, gate, unit, plan);
      }
      const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
      if (isEnemySupplySupportUnit(unit.type) && danger > 0) {
        return false;
      }
      return danger < unit.health && !isEnemyPlannerOneShotExposed(state, unit, coord, plan);
    })
    .sort((first, second) => {
      const firstDistance = hexDistance(first, target);
      const secondDistance = hexDistance(second, target);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return firstDistance - secondDistance || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];
}

function chooseEnemyCaptureGateLocalFallbackAction(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): EnemyCompoundAction | undefined {
  if (plan.rolesByUnitId[unit.id] !== "CaptureGate" || !getUnitDefinition(unit.type).humanBased) {
    return undefined;
  }

  const target = chooseEnemyPlannerGateTargetForUnit(state, unit, plan);
  if (!target || sameHex(unit.coord, target.coord)) {
    return undefined;
  }

  const currentDistance = hexDistance(unit.coord, target.coord);
  const moveTo = getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => hexDistance(coord, target.coord) < currentDistance)
    .filter((coord) => !sameHex(coord, target.coord) || isGateSafeForRecapture(state, target, unit, plan))
    .filter((coord) => {
      const danger = estimatePlayerDangerAtPlanner(state, unit, coord, plan);
      return danger < unit.health && !isEnemyPlannerOneShotExposed(state, unit, coord, plan);
    })
    .sort((first, second) => {
      const firstDistance = hexDistance(first, target.coord);
      const secondDistance = hexDistance(second, target.coord);
      const firstDanger = estimatePlayerDangerAtPlanner(state, unit, first, plan);
      const secondDanger = estimatePlayerDangerAtPlanner(state, unit, second, plan);
      return firstDistance - secondDistance || firstDanger - secondDanger || hexId(first).localeCompare(hexId(second));
    })[0];

  return moveTo ? createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, {}, {}) : undefined;
}

function chooseEnemyAirAntiAirLocalFallbackAction(state: GameState, unit: UnitInstance, plan: EnemyTurnPlan): EnemyCompoundAction | undefined {
  if (getUnitDefinition(unit.type).domain !== "Air") {
    return undefined;
  }

  const threatMap = getEnemyAntiAirThreatMap(state, plan);
  const safeAntiAirAttack = chooseEnemySafeAntiAirFallbackAttack(state, unit, plan, threatMap);
  if (safeAntiAirAttack) {
    return safeAntiAirAttack;
  }

  const currentCoverage = getAntiAirThreatsCoveringCoord(state, unit, unit.coord, threatMap).length;
  const moveTo = getEnemyLegalMoveCoords(state, unit)
    .filter((coord) => canMoveUnitTo(state, unit, coord))
    .filter((coord) => isEnemyAirMoveCandidateAllowed(state, unit, coord, plan, threatMap))
    .filter((coord) => getAntiAirThreatsCoveringCoord(state, unit, coord, threatMap).length === 0)
    .filter((coord) => !isEnemyAirCoordInKnownAntiAirRange(state, unit, coord, plan))
    .sort((first, second) => {
      const firstRetreat = scoreEnemyAirAntiAirFallbackRetreatCoord(state, unit, first, threatMap);
      const secondRetreat = scoreEnemyAirAntiAirFallbackRetreatCoord(state, unit, second, threatMap);
      return secondRetreat - firstRetreat || hexDistance(first, state.bases.Enemy) - hexDistance(second, state.bases.Enemy) || hexId(first).localeCompare(hexId(second));
    })[0];

  if (!moveTo) {
    return undefined;
  }

  const moveCoverage = getAntiAirThreatsCoveringCoord(state, unit, moveTo, threatMap).length;
  return currentCoverage > 0 || moveCoverage === 0
    ? createEnemyCompoundAction(state, unit, plan, "Move", { moveTo }, {}, {})
    : undefined;
}

function isEnemyAirCoordInKnownAntiAirRange(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): boolean {
  if (getUnitDefinition(unit.type).domain !== "Air") {
    return false;
  }
  return getKnownAntiAirThreatsForEnemy(state, plan).some((antiAir) => {
    if (!canUnitTargetUnit(antiAir.type, unit.type)) {
      return false;
    }
    const range = getEffectiveUnitStats(state, antiAir.owner, antiAir.type, antiAir.level, antiAir.coord, coord).attackRange;
    return hexDistance(antiAir.coord, coord) <= range;
  });
}

function chooseEnemySafeAntiAirFallbackAttack(
  state: GameState,
  unit: UnitInstance,
  plan: EnemyTurnPlan,
  threatMap: EnemyAntiAirThreatMap
): EnemyCompoundAction | undefined {
  if (unit.hasAttackedThisDay || unit.placedDay === state.day) {
    return undefined;
  }

  const currentCoverage = getAntiAirThreatsCoveringCoord(state, unit, unit.coord, threatMap);
  return getOwnerUnits(state, "Player")
    .filter((target) => target.type === "Anti-Air" && canUnitTargetUnit(unit.type, target.type))
    .filter((target) => hexDistance(unit.coord, target.coord) <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord).attackRange)
    .map((target) => ({ target, outcome: getExpectedAttackOutcome(state, unit, target) }))
    .filter(({ target, outcome }) => {
      if (outcome.killProbability < 0.9) {
        return false;
      }
      const remainingCoverage = currentCoverage.filter((threat) => threat.id !== target.id);
      return remainingCoverage.length === 0;
    })
    .sort((first, second) => second.outcome.killProbability - first.outcome.killProbability || first.target.id.localeCompare(second.target.id))
    .map(({ target, outcome }) =>
      createEnemyCompoundAction(state, unit, plan, "Attack", {
        attackAt: target.coord,
        targetId: target.id,
        targetType: target.type,
        expectedOutcome: outcome
      }, {}, {})
    )[0];
}

function scoreEnemyAirAntiAirFallbackRetreatCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  threatMap: EnemyAntiAirThreatMap
): number {
  const nearestThreatDistance = threatMap.threats.reduce((best, threat) => Math.min(best, hexDistance(coord, threat.coord)), Number.POSITIVE_INFINITY);
  const currentNearestThreatDistance = threatMap.threats.reduce((best, threat) => Math.min(best, hexDistance(unit.coord, threat.coord)), Number.POSITIVE_INFINITY);
  const baseRetreat = Math.max(0, hexDistance(unit.coord, state.bases.Enemy) - hexDistance(coord, state.bases.Enemy)) * 12;
  const threatRetreat = Number.isFinite(nearestThreatDistance) && Number.isFinite(currentNearestThreatDistance)
    ? (nearestThreatDistance - currentNearestThreatDistance) * 24 + nearestThreatDistance * 6
    : 0;
  return threatRetreat + baseRetreat - estimatePlayerDangerAt(state, unit, coord) * 0.2;
}

function formatEnemyPlannerActionDebug(action: EnemyCompoundAction): string {
  const move = action.moveTo ? ` -> ${hexId(action.moveTo)}` : "";
  const retreat = action.retreatTo ? ` => ${hexId(action.retreatTo)}` : "";
  const target = action.targetType ? ` target ${action.targetType}` : "";
  const b = action.breakdown;
  return `${action.kind} ${action.unitType}${move}${retreat}${target}
  terminal: ${Math.round(b.terminal)}
  material: ${Math.round(b.material + b.expectedDamage + b.killProbability)}
  objective: ${Math.round(b.baseCaptureClock + b.gateCaptureClock + b.backupCapturerValue + b.replacementDistance + b.income + b.taskProgress)}
  expected retaliation: ${Math.round(b.expectedLoss + b.opponentReplyRisk)}
  congestion: ${Math.round(b.congestion)}
  doctrine: ${Math.round(b.doctrine)}
  total: ${Math.round(b.total)}`;
}

