let enemyEvaluationCache: EnemyEvaluationCache | null = null;
let activeEnemyTurnPlan: EnemyTurnPlan | null = null;
let enemyEvaluationMutationEpoch = 0;

function getEnemyEvaluationCache(state: GameState): EnemyEvaluationCache {
  if (!enemyEvaluationCache || enemyEvaluationCache.state !== state) {
    enemyEvaluationCache = {
      state,
      baseThreatComputed: false
    };
  }

  return enemyEvaluationCache;
}

function invalidateEnemyEvaluationCache(): void {
  enemyEvaluationMutationEpoch += 1;
  if (activeEnemyTurnPlan) {
    invalidateEnemyTurnPlanCache(activeEnemyTurnPlan);
  }
  if (activeEnemyTurnPlan && enemyEvaluationCache) {
    enemyEvaluationCache.ownerUnits = undefined;
    enemyEvaluationCache.unitsById = undefined;
    enemyEvaluationCache.visibleHexIds = undefined;
    enemyEvaluationCache.knownPlayerUnits = undefined;
    enemyEvaluationCache.playerIntel = undefined;
    enemyEvaluationCache.playerForwardPressure = undefined;
    enemyEvaluationCache.strategicAssessment = undefined;
    enemyEvaluationCache.influenceMap = undefined;
    enemyEvaluationCache.roleAssignments = undefined;
    enemyEvaluationCache.plannerAttackTargets = undefined;
    enemyEvaluationCache.expectedAttackOutcomes = undefined;
    enemyEvaluationCache.assignedGateReachable = undefined;
    enemyEvaluationCache.plannerDanger = undefined;
    enemyEvaluationCache.plannerFogThreat = undefined;
    enemyEvaluationCache.plannerOneShotExposure = undefined;
    enemyEvaluationCache.legalMoveCoords = undefined;
    enemyEvaluationCache.legalMoveCoordIds = undefined;
    enemyEvaluationCache.placementObjectiveRoutes = undefined;
    enemyEvaluationCache.actionAreaMetrics = undefined;
    enemyEvaluationCache.enemyControlledTerritoryCount = undefined;
    enemyEvaluationCache.enemyTerritoryControlDeltas = undefined;
    enemyEvaluationCache.unitInstanceValues = undefined;
    enemyEvaluationCache.unitTypeValues = undefined;
    enemyEvaluationCache.knownAntiAirThreats = undefined;
    enemyEvaluationCache.knownAntiAirThreatsPlan = undefined;
    enemyEvaluationCache.antiAirThreatMap = undefined;
    enemyEvaluationCache.antiAirThreatMapPlan = undefined;
    enemyEvaluationCache.baseThreatComputed = false;
    enemyEvaluationCache.baseThreat = undefined;
    return;
  }

  clearEnemyEvaluationCache();
}

function invalidateEnemyTurnPlanCache(plan: EnemyTurnPlan): void {
  plan.cache.combatPressure = undefined;
  plan.cache.visibleHexIds = undefined;
  plan.cache.visibleTargetIds = undefined;
  plan.cache.expectedAttackOutcomes = undefined;
  plan.cache.assignedGateReachable = undefined;
  plan.cache.plannerDanger = undefined;
  plan.cache.plannerFogThreat = undefined;
  plan.cache.plannerOneShotExposure = undefined;
  plan.cache.plannerReplyDamage = undefined;
}

function clearEnemyEvaluationCache(): void {
  enemyEvaluationCache = null;
}

function synchronizeEnemyFogInPlace(state: GameState): void {
  const next = updateFog(state);
  state.fog = next.fog;
  state.gates = next.gates;
  state.spottedUnits = next.spottedUnits;
}

function refreshEnemyPlannerLiveIntel(state: GameState, plan: EnemyTurnPlan, options: { synchronizeFog?: boolean } = {}): void {
  if (options.synchronizeFog !== false) {
    synchronizeEnemyFogInPlace(state);
  }
  invalidateEnemyEvaluationCache();
  plan.playerIntel = getEnemyPlannerPlayerIntel(state);
}

function getAiDifficultyConfig(state: GameState): AiDifficultyConfig {
  if (state.difficulty === "Easy") {
    return {
      maxPlacementsPerTurn: 3,
      maxEconomyPurchasesPerTurn: 4,
      productionScoreThreshold: 154,
      highPriorityResearchThreshold: 125,
      economyResearchScoreBonus: 36,
      unitUpgradeResearchScoreMultiplier: 0.45,
      gateCaptureOpportunityMultiplier: 0.08,
      playerBaseVulnerabilityMultiplier: 0.2,
      strategicRoleRetention: 0.36
    };
  }

  if (state.difficulty === "Medium") {
    return {
      maxPlacementsPerTurn: 8,
      maxEconomyPurchasesPerTurn: 4,
      productionScoreThreshold: 132,
      highPriorityResearchThreshold: 105,
      economyResearchScoreBonus: 16,
      unitUpgradeResearchScoreMultiplier: 0.5,
      gateCaptureOpportunityMultiplier: 0.82,
      playerBaseVulnerabilityMultiplier: 0.55,
      strategicRoleRetention: 0.72
    };
  }

  return {
    maxPlacementsPerTurn: 10,
    maxEconomyPurchasesPerTurn: 7,
    productionScoreThreshold: 112,
    highPriorityResearchThreshold: 90,
    economyResearchScoreBonus: 0,
    unitUpgradeResearchScoreMultiplier: 0.35,
    gateCaptureOpportunityMultiplier: 1,
    playerBaseVulnerabilityMultiplier: 1,
    strategicRoleRetention: 1
  };
}

function getEnemyBaseResponseRadius(state: GameState): number {
  return state.difficulty === "Hard" ? HARD_ENEMY_BASE_RESPONSE_RADIUS : ENEMY_BASE_RESPONSE_RADIUS;
}

function getEnemyGateDisadvantage(state: GameState): number {
  const playerGateCount = (state.gates ?? []).filter((gate) => gate.owner === "Player").length;
  const enemyGateCount = (state.gates ?? []).filter((gate) => gate.owner === "Enemy").length;
  return Math.max(0, playerGateCount - enemyGateCount);
}

function getEnemyRoutineProductionQueueLimit(state: GameState): number {
  const capacity = Math.max(1, state.enemyEconomy.productionCapacityLevel);
  if (state.difficulty !== "Hard") {
    return capacity;
  }

  const cashBacklog = state.enemyEconomy.moneyPoundsBn >= 180 ? 3 : state.enemyEconomy.moneyPoundsBn >= 120 ? 2 : capacity;
  const specialCaptureBacklog = ownerHasBuilding(state, "Enemy", "Special Services") && state.day >= 12 && state.enemyEconomy.moneyPoundsBn >= 80 ? 2 : capacity;
  const dayBacklog = state.day >= 12 ? cashBacklog : Math.min(2, cashBacklog);
  return Math.max(capacity, specialCaptureBacklog, Math.min(MAX_QUEUE_ITEMS, dayBacklog));
}

function getEnemyRoutineResearchQueueLimit(state: GameState): number {
  return Math.max(1, state.enemyEconomy.researchCapacityLevel);
}

function isEnemyQueueTimingNearTerm(timing: EnemyQueueTiming, horizonDays: number): boolean {
  return timing.waitDays <= horizonDays && timing.totalDays <= horizonDays + Math.max(1, timing.completeDay - timing.startedDay);
}

function estimateEnemyProductionTiming(state: GameState, unitType: UnitType): EnemyQueueTiming {
  if (state.enemyEconomy.productionQueue.length < MAX_QUEUE_ITEMS) {
    const timing = estimateQueuedWorkTiming(
      state.day,
      state.enemyEconomy.productionCapacityLevel,
      getProductionWorkPerDay(state.enemyEconomy),
      state.enemyEconomy.productionQueue.map((job) => ({
        startedDay: job.startedDay,
        completeDay: job.availableDay,
        requiredWork: getProductionDays(job.unitType) * JOB_WORK_PER_DAY,
        active: job.startedDay < state.day && job.availableDay > state.day,
        candidate: false
      })),
      {
        startedDay: state.day,
        completeDay: state.day + getProductionDays(unitType),
        requiredWork: getProductionDays(unitType) * JOB_WORK_PER_DAY,
        active: false,
        candidate: true
      }
    );
    if (timing) {
      return timing;
    }
  }

  const fallbackStart = state.day + Math.max(0, state.enemyEconomy.productionQueue.length - state.enemyEconomy.productionCapacityLevel + 1);
  const fallbackComplete = fallbackStart + getProductionDays(unitType);
  return {
    startedDay: fallbackStart,
    completeDay: fallbackComplete,
    waitDays: Math.max(0, fallbackStart - state.day),
    totalDays: Math.max(0, fallbackComplete - state.day)
  };
}

function estimateEnemyResearchTiming(state: GameState, option: EnemyResearchOption): EnemyQueueTiming {
  const startLevel = getNextResearchStartLevel(state.enemyEconomy, option.type, option.unitType);
  if (state.enemyEconomy.researchQueue.length < MAX_QUEUE_ITEMS) {
    const candidateDays = getResearchDays(option.type, option.unitType, state.enemyEconomy, startLevel);
    const timing = estimateQueuedWorkTiming(
      state.day,
      state.enemyEconomy.researchCapacityLevel,
      getResearchWorkPerDay(state.enemyEconomy),
      state.enemyEconomy.researchQueue.map((job) => ({
        startedDay: job.startedDay,
        completeDay: job.completeDay,
        requiredWork: getResearchRequiredWork(job.type, job.unitType, state.enemyEconomy, getResearchJobStartLevel(job, state.enemyEconomy)),
        active: job.startedDay < state.day && job.completeDay > state.day,
        candidate: false
      })),
      {
        startedDay: state.day,
        completeDay: state.day + candidateDays,
        requiredWork: getResearchRequiredWork(option.type, option.unitType, state.enemyEconomy, startLevel),
        active: false,
        candidate: true
      }
    );
    if (timing) {
      return timing;
    }
  }

  const fallbackStart = state.day + Math.max(0, state.enemyEconomy.researchQueue.length - state.enemyEconomy.researchCapacityLevel + 1);
  const fallbackComplete = fallbackStart + getResearchDays(option.type, option.unitType, state.enemyEconomy, startLevel);
  return {
    startedDay: fallbackStart,
    completeDay: fallbackComplete,
    waitDays: Math.max(0, fallbackStart - state.day),
    totalDays: Math.max(0, fallbackComplete - state.day)
  };
}

function estimateQueuedWorkTiming(
  currentDay: number,
  capacity: number,
  workPerDay: number,
  jobs: Array<{ startedDay: number; completeDay: number; requiredWork: number; active: boolean; candidate: boolean }>,
  candidate: { startedDay: number; completeDay: number; requiredWork: number; active: boolean; candidate: boolean }
): EnemyQueueTiming | undefined {
  const lanes = getInitialWorkLanes(
    jobs
      .filter((job) => job.active)
      .map((job) => job.completeDay),
    capacity,
    currentDay
  );

  const pendingJobs = [...jobs.filter((job) => job.completeDay > currentDay && !job.active), candidate]
    .sort((first, second) => first.startedDay - second.startedDay || first.completeDay - second.completeDay);
  for (const job of pendingJobs) {
    const laneIndex = getEarliestWorkLaneIndex(lanes);
    const schedule = scheduleWorkOnLane(lanes[laneIndex], job.requiredWork, workPerDay);
    lanes[laneIndex] = schedule.lane;
    if (job.candidate) {
      return {
        startedDay: schedule.startedDay,
        completeDay: schedule.completeDay,
        waitDays: Math.max(0, schedule.startedDay - currentDay),
        totalDays: Math.max(0, schedule.completeDay - currentDay)
      };
    }
  }

  return undefined;
}

function isEconomyOrThroughputResearch(type: ResearchType): boolean {
  return type === "Efficiency" || type === "ProductionCapacity" || type === "ResearchCapacity" || type === "ProductionSpeed" || type === "ResearchSpeed";
}

function isCriticalEnemyTechResearchOption(state: GameState, option: EnemyResearchOption): boolean {
  if (option.type === "UnlockSpecialServices" && !ownerHasBuilding(state, "Enemy", "Special Services")) {
    return true;
  }

  return option.type === "UnlockDroneFactory" && ownerHasBuilding(state, "Enemy", "Special Services") && !ownerHasBuilding(state, "Enemy", "Drone Factory");
}

function createEnemyResearchFeasibilityContext(state: GameState): EnemyResearchFeasibilityContext {
  const config = getAiDifficultyConfig(state);
  return {
    config,
    criticalTechReserve: 0,
    productionReserve: 0,
    queueLimit: getEnemyRoutineResearchQueueLimit(state),
    queueHorizonDays: state.difficulty === "Hard" ? ENEMY_RESEARCH_QUEUE_HORIZON_DAYS : Number.POSITIVE_INFINITY
  };
}

function getEnemyResearchOptions(state: GameState): EnemyResearchOption[] {
  const config = getAiDifficultyConfig(state);
  const assessment = getEnemyStrategicAssessment(state);
  const options: EnemyResearchOption[] = [];
  const addOption = (type: ResearchType, unitType?: UnitType): void => {
    if (type === "UnlockSpecialServices" && state.day < 12) {
      return;
    }

    const startLevel = getNextResearchStartLevel(state.enemyEconomy, type, unitType);
    if (!canStartResearch(state, "Enemy", type, unitType, { ignoreMoney: canEnemySpendGainOnResearchLine(state, type, unitType, startLevel) })) {
      return;
    }

    const cost = getResearchCost(type, unitType, state.enemyEconomy, startLevel);
    options.push({
      type,
      unitType,
      cost,
      score: getDifficultyAdjustedResearchScore(config, scoreEnemyResearchOption(state, type, unitType), type) - cost * 0.4
    });
  };

  for (const researchType of ENEMY_RESEARCH_TYPES) {
    addOption(researchType);
  }
  for (const unitType of ENEMY_UNIT_TYPES) {
    addOption("UnitUpgrade", unitType);
  }

  const sortedOptions = options.sort((first, second) => second.score - first.score || first.cost - second.cost);
  const gateDisadvantage = getEnemyGateDisadvantage(state);
  if (state.difficulty === "Hard") {
    const specialServicesOption = sortedOptions.find(
      (option) => option.type === "UnlockSpecialServices" && option.score > 0 && canEnemyAffordResearchOption(state, option)
    );
    if (
      specialServicesOption &&
      (state.day >= 8 || gateDisadvantage > 0 || assessment.player.totalValue > 120 || assessment.forecast.specialPipelineNeed > 90)
    ) {
      specialServicesOption.score += 40;
    }
    if (specialServicesOption && state.day >= 12) {
      specialServicesOption.score += 1_200;
    }

    const droneFactoryOption = sortedOptions.find(
      (option) => option.type === "UnlockDroneFactory" && option.score > 0 && canEnemyAffordResearchOption(state, option)
    );
    if (
      droneFactoryOption &&
      (state.day >= 14 ||
        gateDisadvantage > 0 ||
        assessment.forecast.reaperPipelineNeed > 130 ||
        getPlayerArtilleryPressure(state) > 70 ||
        assessment.player.totalValue > 170)
    ) {
      droneFactoryOption.score += 40;
    }
    if (droneFactoryOption && state.day >= 12) {
      droneFactoryOption.score += 1_350;
    }
  }

  if (state.difficulty === "Hard" && state.enemyEconomy.researchQueue.length === 0 && state.day >= 8) {
    const economyOption = sortedOptions.find(
      (option) => isEconomyOrThroughputResearch(option.type) && option.score > 0 && canEnemyAffordResearchOption(state, option)
    );
    if (economyOption) {
      const advancedInfrastructureOnline =
        ownerHasBuilding(state, "Enemy", "Special Services") && ownerHasBuilding(state, "Enemy", "Drone Factory");
      economyOption.score += advancedInfrastructureOnline ? 80 : 20;
    }
  }

  return sortedOptions.sort((first, second) => second.score - first.score || first.cost - second.cost);
}

function isEnemyResearchOptionFeasible(
  state: GameState,
  option: EnemyResearchOption,
  context: EnemyResearchFeasibilityContext
): boolean {
  if (option.score <= 0 || !canEnemyAffordResearchOption(state, option)) {
    return false;
  }

  const criticalTech = isCriticalEnemyTechResearchOption(state, option);

  const strategicException = criticalTech || option.type === "UnlockSpecialServices" || option.type === "UnlockDroneFactory";

  if (state.enemyEconomy.researchQueue.length >= context.queueLimit) {
    return false;
  }

  const timing = estimateEnemyResearchTiming(state, option);
  if (state.difficulty === "Hard" && !strategicException && !isEnemyQueueTimingNearTerm(timing, context.queueHorizonDays)) {
    return false;
  }

  return true;
}

function chooseEnemyResearchOption(
  state: GameState,
  context = createEnemyResearchFeasibilityContext(state)
): EnemyResearchOption | undefined {
  return getEnemyResearchOptions(state).find((option) => isEnemyResearchOptionFeasible(state, option, context));
}


function getDifficultyAdjustedResearchScore(config: AiDifficultyConfig, score: number, type: ResearchType): number {
  if (type === "UnitUpgrade") {
    return score * config.unitUpgradeResearchScoreMultiplier;
  }

  if (type === "Efficiency" || type === "ProductionCapacity" || type === "ResearchCapacity" || type === "ProductionSpeed" || type === "ResearchSpeed") {
    return score + config.economyResearchScoreBonus;
  }

  return score;
}

function scoreEnemyResearchOption(state: GameState, type: ResearchType, unitType?: UnitType): number {
  const economy = state.enemyEconomy;
  const assessment = getEnemyStrategicAssessment(state);
  const playerArmyValue = getKnownPlayerUnitsForEnemy(state).reduce((total, unit) => total + getUnitInstanceValue(state, unit), 0);
  const captureNeed = getEnemyCaptureNeed(state);
  const gateDisadvantage = getEnemyGateDisadvantage(state);
  const combatPressure = getPlayerForwardPressure(state);

  if (type === "UnlockSpecialServices") {
    const starvingForEfficiency = isEnemyEfficiencyStarvedForResearch(state);
    const affordableDayTwelvePush = !starvingForEfficiency && state.day >= 12 && canEnemyAffordResearchType(state, type) ? 1_200 : 0;
    const efficiencyStarvationPenalty = starvingForEfficiency ? 1_050 : 0;
    return 112 + affordableDayTwelvePush + assessment.specialPlanUrgency + assessment.forecast.specialPipelineNeed + (assessment.strategyPlan === "FastSpecialServices" ? 80 : 0) + captureNeed * 10 + gateDisadvantage * 38 + Math.min(44, playerArmyValue * 0.08) + Math.max(0, combatPressure - 120) * 0.22 - efficiencyStarvationPenalty;
  }

  if (type === "UnlockDroneFactory") {
    const starvingForEfficiency = isEnemyEfficiencyStarvedForResearch(state);
    const affordableDayTwelvePush = !starvingForEfficiency && state.day >= 12 && canEnemyAffordResearchType(state, type) ? 1_350 : 0;
    const efficiencyStarvationPenalty = starvingForEfficiency ? 1_150 : 0;
    return 128 + affordableDayTwelvePush + assessment.reaperPlanUrgency + assessment.forecast.reaperPipelineNeed + (assessment.strategyPlan === "ReaperTechRush" ? 90 : 0) + gateDisadvantage * 55 + Math.min(70, playerArmyValue * 0.1) + scoreUnitCountersPlayerArmy(state, "Reaper") * 0.32 + Math.max(0, combatPressure - 100) * 0.34 - efficiencyStarvationPenalty;
  }

  if (type === "Efficiency") {
    const nextTurnIncome = getEnemyNextTurnIncome(state);
    const starvingForEfficiency = isEnemyEfficiencyStarvedForResearch(state);
    const earlyGameBonus = Math.max(0, 20 - state.day) * 8;
    const runwayBonus = Math.max(0, 7 - economy.efficiencyLevel) * 22;
    const lowEfficiencyBonus = starvingForEfficiency
      ? Math.max(0, 5 - economy.efficiencyLevel) * 125
      : Math.max(0, 3 - economy.efficiencyLevel) * 42;
    const lowIncomeBonus = starvingForEfficiency
      ? Math.max(0, 10 - nextTurnIncome) * 52
      : Math.max(0, 6 - nextTurnIncome) * 14;
    const lowCashRunwayBonus = starvingForEfficiency ? Math.max(0, 95 - economy.moneyPoundsBn) * 2.4 : 0;
    const gateMultiplier = 1 + assessment.enemyGateCount * 0.32 + assessment.playerGateCount * 0.22;
    return 130 + (assessment.economyUrgency + assessment.forecast.economyInvestmentNeed) * gateMultiplier + (assessment.strategyPlan === "GateEconomy" || assessment.strategyPlan === "DefensiveEconomy" ? 90 : 0) + gateDisadvantage * 48 + earlyGameBonus + runwayBonus + lowEfficiencyBonus + lowIncomeBonus + lowCashRunwayBonus - economy.researchQueue.length * 3;
  }

  if (type === "ProductionCapacity") {
    const earlyGameBonus = Math.max(0, 12 - state.day) * 5;
    const backlogBonus = economy.productionQueue.length >= economy.productionCapacityLevel ? 28 : 0;
    return 32 + assessment.productionThroughputNeed + assessment.forecast.productionScaleNeed + earlyGameBonus + backlogBonus - economy.productionCapacityLevel * 7;
  }

  if (type === "ResearchCapacity") {
    const earlyGameBonus = Math.max(0, 12 - state.day) * 5;
    const backlogBonus = economy.researchQueue.length >= economy.researchCapacityLevel ? 30 : 0;
    return 34 + assessment.researchThroughputNeed + assessment.forecast.researchScaleNeed + earlyGameBonus + backlogBonus - economy.researchCapacityLevel * 8;
  }

  if (type === "ProductionSpeed") {
    const earlyGameBonus = Math.max(0, 14 - state.day) * 4;
    const backlogBonus = economy.productionQueue.length >= economy.productionCapacityLevel ? 24 : 0;
    return 30 + (assessment.productionThroughputNeed + assessment.forecast.productionScaleNeed) * 0.75 + earlyGameBonus + backlogBonus - economy.productionSpeedLevel * 7;
  }

  if (type === "ResearchSpeed") {
    const earlyGameBonus = Math.max(0, 14 - state.day) * 4;
    const backlogBonus = economy.researchQueue.length >= economy.researchCapacityLevel ? 24 : 0;
    return 30 + (assessment.researchThroughputNeed + assessment.forecast.researchScaleNeed) * 0.75 + earlyGameBonus + backlogBonus - economy.researchSpeedLevel * 7;
  }

  if (!unitType) {
    return 0;
  }

  const definition = getUnitDefinition(unitType);
  const useProfile = getEnemyUnitUpgradeUseProfile(state, unitType);
  const counterScore = scoreUnitCountersPlayerArmy(state, unitType);
  const level = economy.unitLevels[unitType];
  const upgradeQuality = getEnemyUnitUpgradeQualityMultiplier(state, unitType);
  if (useProfile.committedUse <= 0) {
    return -100 - level * 20;
  }

  const useScore =
    (useProfile.fieldUpgradeable * 18 +
      Math.max(0, useProfile.fielded - useProfile.fieldUpgradeable) * 10 +
      useProfile.inventory * 5 +
      useProfile.queuedProduction * 12 +
      useProfile.productionIntent * 3) *
    upgradeQuality;
  if (useScore <= 0) {
    return -100 - level * 20;
  }

  const eliteBonus = unitType === "Reaper" ? 42 + assessment.reaperPlanUrgency * 0.16 + assessment.forecast.reaperPipelineNeed * 0.14 : unitType === "Ghost" || unitType === "Operator" ? 14 + assessment.specialPlanUrgency * 0.08 + assessment.forecast.specialPipelineNeed * 0.06 : 0;
  const captureBonus = definition.humanBased ? captureNeed * 3 : 0;
  const activeUseBonus = useProfile.committedUse * 6 * upgradeQuality;
  const doctrineBonus = scoreEnemyDoctrineNeedForUnit(state, unitType) * (useProfile.committedUse > 0 ? 0.12 : 0.06);
  const infantryUpgradePenalty =
    state.difficulty === "Hard" && unitType === "Infantry"
      ? Math.max(0, state.day - 8) * 4 + Math.max(0, getEnemyUnitPresence(state, "Infantry") - 4) * 28
      : 0;
  return 4 + useScore + activeUseBonus + counterScore * 0.18 + doctrineBonus + eliteBonus + captureBonus - level * 9 - infantryUpgradePenalty;
}

function shouldAcceptEnemyProductionCandidate(
  state: GameState,
  unitType: UnitType,
  score: number,
  context: EnemyProductionCandidateContext
): boolean {
  const cost = getProductionCost(unitType);
  const baseThreat = getEnemyBaseThreat(state);
  const urgentDefense = Boolean(baseThreat && canUnitTargetUnit(unitType, baseThreat.type));
  const activeBaseEmergency = isActiveEnemyBaseThreat(state, baseThreat);
  const spendDownForArmy = state.difficulty === "Hard" && shouldHardAiSpendDownForArmy(state, context.assessment);
  const timing = estimateEnemyProductionTiming(state, unitType);
  const routineQueueIsNearTerm = isStrategicEnemyProductionUnit(state, unitType) || isEnemyQueueTimingNearTerm(timing, ENEMY_PRODUCTION_QUEUE_HORIZON_DAYS);
  const wouldArriveObsolete = state.difficulty === "Hard" && isEnemyProductionObsoletedByQueuedUpgrade(state, unitType, timing);
  const endgameReaperDoctrine =
    state.difficulty === "Hard" &&
    unitType === "Reaper" &&
    ownerControlsBothGates(state, "Enemy") &&
    (context.phase === "BothGatesOwned" || context.phase === "BaseAssault" || context.phase === "BaseHold");
  const firstReaperDoctrine = unitType === "Reaper" && shouldEnemyPrioritizeFirstReaperProduction(state);
  const reaperSurvivalAcceptable = unitType !== "Reaper" || isEnemyReaperProductionSurvivalAcceptable(state, context.assessment);
  const playbook = getEnemyStrategyPlaybook(context.assessment);
  const reaperRushNonDelayer =
    playbook.delayObjectiveClockOnly &&
    unitType !== "Reaper" &&
    !isEnemyReaperTechRushDelayProductionUnit(state, unitType, context.assessment) &&
    !urgentDefense;
  const crisisCombatSpend =
    state.difficulty === "Hard" &&
    getPlayerForwardPressure(state) >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD &&
    isHardCrisisCombatProductionUnit(state, unitType);
  const gateLockoutEmergencyProduction =
    state.difficulty === "Hard" &&
    context.phase === "GateLockoutCombat" &&
    isEnemyGateLockoutDirectCombatProductionUnit(unitType);
  const requiredFieldSupportProduction = isEnemyRequiredFieldSupportProductionUnit(state, unitType);
  const expansionProduction =
    isEnemyCombatExpansionProductionUnit(unitType) &&
    score >= getEnemyExpansionProductionScoreThreshold(state, unitType, context);
  if (wouldArriveObsolete) {
    return false;
  }
  if (!reaperSurvivalAcceptable && !endgameReaperDoctrine) {
    return false;
  }
  if (reaperRushNonDelayer) {
    return false;
  }

  return (
    (unitType === "Reaper" &&
      canEnemyAffordProductionUnit(state, unitType)) ||
    (requiredFieldSupportProduction &&
      canEnemyAffordProductionUnit(state, unitType) &&
      routineQueueIsNearTerm) ||
    (urgentDefense &&
      routineQueueIsNearTerm &&
      activeBaseEmergency) ||
    (crisisCombatSpend &&
      score >= context.armySpendDownThreshold &&
      routineQueueIsNearTerm) ||
    (gateLockoutEmergencyProduction &&
      routineQueueIsNearTerm) ||
    (score >= context.scoreThreshold &&
      routineQueueIsNearTerm) ||
    (expansionProduction &&
      routineQueueIsNearTerm) ||
    (spendDownForArmy &&
      score >= context.armySpendDownThreshold &&
      routineQueueIsNearTerm)
  );
}

function isEnemyCombatExpansionProductionUnit(unitType: UnitType): boolean {
  const definition = getUnitDefinition(unitType);
  return !definition.cannotAttack && !isEnemySupplySupportUnit(unitType);
}

function getEnemyExpansionProductionScoreThreshold(
  state: GameState,
  unitType: UnitType,
  context: EnemyProductionCandidateContext
): number {
  const definition = getUnitDefinition(unitType);
  const baseThreshold = Math.min(context.scoreThreshold, context.armySpendDownThreshold);
  const earlyExpansionDiscount = state.day <= 8 ? 24 : state.day <= 16 ? 16 : 8;
  const airDiscount = definition.domain === "Air" ? 12 : 0;
  return Math.max(34, baseThreshold - earlyExpansionDiscount - airDiscount);
}

function isStrategicEnemyProductionUnit(state: GameState, unitType: UnitType): boolean {
  return unitType === "Reaper" || (state.difficulty === "Hard" && (unitType === "Operator" || unitType === "Ghost"));
}

function isEnemyProductionObsoletedByQueuedUpgrade(state: GameState, unitType: UnitType, timing: EnemyQueueTiming): boolean {
  return state.enemyEconomy.researchQueue.some(
    (job) =>
      job.type === "UnitUpgrade" &&
      job.unitType === unitType &&
      job.completeDay <= timing.completeDay &&
      job.completeDay <= timing.startedDay + 1
  );
}

function isHardCombatProductionUnit(unitType: UnitType): boolean {
  return ["Anti-Air", "Artillery", "IFV", "Tank", "Attack Heli", "Jet", "Bomber", "Operator", "Ghost", "Reaper"].includes(unitType);
}

function isEnemyGateLockoutDirectCombatProductionUnit(unitType: UnitType): boolean {
  return unitType === "Tank" || unitType === "IFV" || unitType === "Artillery" || unitType === "Anti-Air" || unitType === "Jet" || unitType === "Bomber" || unitType === "Operator" || unitType === "Ghost" || unitType === "Reaper";
}

function isEnemyGateLockoutResearchCandidatePermitted(state: GameState, plan: EnemyTurnPlan, option: EnemyResearchOption): boolean {
  if (!isEnemyGateLockoutEconomyOverride(state, plan)) {
    return true;
  }

  if (isEconomyOrThroughputResearch(option.type)) {
    return false;
  }

  if (option.type === "UnitUpgrade") {
    return Boolean(option.unitType && countEnemyGateLockoutImmediateUpgradeTargets(state, plan, option.unitType) > 0);
  }

  if (option.type === "UnlockSpecialServices" || option.type === "UnlockDroneFactory") {
    return scoreEnemyGateLockoutCounterUnlockResearch(state, plan, option.type) > 0;
  }

  return false;
}

function scoreEnemyGateLockoutResearchRelevance(state: GameState, plan: EnemyTurnPlan, option: EnemyResearchOption): number {
  if (!isEnemyGateLockoutEconomyOverride(state, plan)) {
    return 0;
  }

  if (option.type === "UnitUpgrade" && option.unitType) {
    const immediateTargets = countEnemyGateLockoutImmediateUpgradeTargets(state, plan, option.unitType);
    if (immediateTargets <= 0) {
      return 0;
    }
    return Math.min(220, immediateTargets * 70 + Math.max(0, scoreUnitCountersPlayerArmy(state, option.unitType)) * 0.35);
  }

  if (option.type === "UnlockSpecialServices" || option.type === "UnlockDroneFactory") {
    return scoreEnemyGateLockoutCounterUnlockResearch(state, plan, option.type);
  }

  return 0;
}

function countEnemyGateLockoutImmediateUpgradeTargets(state: GameState, plan: EnemyTurnPlan, unitType: UnitType): number {
  if (!isEnemyGateLockoutDirectCombatProductionUnit(unitType)) {
    return 0;
  }

  const targetLevel = Math.min(getMaxUnitLevel(unitType), state.enemyEconomy.unitLevels[unitType] + 1);
  const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
  return getOwnerUnits(state, "Enemy").filter((unit) => {
    if (unit.type !== unitType || unit.health <= 0 || getUnitInstanceLevel(state, unit) >= targetLevel) {
      return false;
    }
    if (!gate) {
      return true;
    }
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
    return hexDistance(unit.coord, gate.coord) <= Math.max(7, stats.moveRange + stats.attackRange + 2);
  }).length;
}

function scoreEnemyGateLockoutCounterUnlockResearch(state: GameState, plan: EnemyTurnPlan, researchType: ResearchType): number {
  const unlockedCounterScore = getEnemyGateLockoutUnlockedCounterUnits(state, researchType).reduce(
    (best, unitType) => Math.max(best, scoreEnemyGateLockoutCounterUnitValue(state, plan, unitType)),
    Number.NEGATIVE_INFINITY
  );
  if (!Number.isFinite(unlockedCounterScore)) {
    return 0;
  }

  const availableCounterScore = ENEMY_UNIT_TYPES
    .filter((unitType) => isEnemyGateLockoutDirectCombatProductionUnit(unitType) && canOwnerProduceUnit(state, "Enemy", unitType))
    .reduce((best, unitType) => Math.max(best, scoreEnemyGateLockoutCounterUnitValue(state, plan, unitType)), Number.NEGATIVE_INFINITY);
  const availableComparison = Number.isFinite(availableCounterScore) ? availableCounterScore : 0;
  if (unlockedCounterScore < 260 || unlockedCounterScore < availableComparison + 35) {
    return 0;
  }

  return Math.min(260, unlockedCounterScore - availableComparison + 90);
}

function getEnemyGateLockoutUnlockedCounterUnits(state: GameState, researchType: ResearchType): UnitType[] {
  if (researchType === "UnlockSpecialServices" && !ownerHasBuilding(state, "Enemy", "Special Services")) {
    return ["Operator", "Ghost"];
  }

  if (
    researchType === "UnlockDroneFactory" &&
    ownerHasBuilding(state, "Enemy", "Special Services") &&
    !ownerHasBuilding(state, "Enemy", "Drone Factory")
  ) {
    return ["Reaper"];
  }

  return [];
}

function scoreEnemyGateLockoutCounterUnitValue(state: GameState, plan: EnemyTurnPlan, unitType: UnitType): number {
  if (!isEnemyGateLockoutDirectCombatProductionUnit(unitType)) {
    return Number.NEGATIVE_INFINITY;
  }
  return (
    scoreEnemyProductionChoice(state, unitType) +
    getEnemyPhaseEconomyProductionPriority(state, plan, unitType) +
    Math.max(0, scoreUnitCountersPlayerArmy(state, unitType)) * 0.45
  );
}

function hasAffordableEnemyGateLockoutDirectCombatProduction(state: GameState, plan: EnemyTurnPlan): boolean {
  return (
    isEnemyGateLockoutEconomyOverride(state, plan) &&
    state.enemyEconomy.productionQueue.length < getEnemyRoutineProductionQueueLimit(state) &&
    ENEMY_UNIT_TYPES.some((unitType) =>
      isEnemyGateLockoutDirectCombatProductionUnit(unitType) &&
      canOwnerProduceUnit(state, "Enemy", unitType) &&
      canEnemyAffordProductionUnit(state, unitType)
    )
  );
}

function isEnemyGateLockoutCappedCapturerProduction(state: GameState, plan: EnemyTurnPlan, unitType: UnitType): boolean {
  return (
    isEnemyGateLockoutEconomyOverride(state, plan) &&
    getUnitDefinition(unitType).humanBased &&
    !isEnemyGateLockoutDirectCombatProductionUnit(unitType) &&
    getEnemyHealthyCapturerPipelineCount(state) > 1
  );
}

function getEnemyHealthyCapturerPipelineCount(state: GameState): number {
  return ENEMY_CAPTURE_UNIT_TYPES.reduce(
    (total, unitType) =>
      total +
      getOwnerUnits(state, "Enemy").filter((unit) => unit.type === unitType && unit.health / Math.max(1, unit.maxHealth) > 0.45).length +
      (state.enemyEconomy.inventory[unitType] ?? 0) +
      state.enemyEconomy.productionQueue.filter((job) => job.unitType === unitType).length,
    0
  );
}

function isHardCrisisCombatProductionUnit(state: GameState, unitType: UnitType): boolean {
  if (unitType === "Infantry" || unitType === "Attack Heli" || unitType === "IFV") {
    return false;
  }
  if (unitType === "Anti-Air") {
    return getEnemyStrategicAssessment(state).player.airCount > 0 || getKnownPlayerUnitsForEnemy(state).some((unit) => getUnitDefinition(unit.type).domain === "Air");
  }
  return ["Artillery", "Tank", "Jet", "Bomber", "Operator", "Ghost", "Reaper"].includes(unitType);
}

function getEnemyFirstResearchReserveFloor(state: GameState): number {
  return 0;
}

function scoreEnemyProductionChoice(state: GameState, unitType: UnitType): number {
  const definition = getUnitDefinition(unitType);
  const cost = getProductionCost(unitType);
  const assessment = getEnemyStrategicAssessment(state);
  const presence = getEnemyUnitPresence(state, unitType);
  const captureNeed = getEnemyCaptureNeed(state);
  const playerUnits = getKnownPlayerUnitsForEnemy(state);
  const playerAirCount = playerUnits.filter((unit) => getUnitDefinition(unit.type).domain === "Air").length;
  const baseThreat = getEnemyBaseThreat(state);
  const activeBaseEmergency = isActiveEnemyBaseThreat(state, baseThreat);
  const gateDisadvantage = getEnemyGateDisadvantage(state);
  const artilleryPressure = getPlayerArtilleryPressure(state);
  const infantryPresence = getEnemyUnitPresence(state, "Infantry");
  const artilleryPresence = getEnemyUnitPresence(state, "Artillery");
  const antiAirPresence = getEnemyUnitPresence(state, "Anti-Air");
  const tankPresence = getEnemyUnitPresence(state, "Tank");
  const commandHelicopterPresence = getEnemyUnitPresence(state, "Command Heli");
  const advancedBuildingAvailable =
    ownerHasBuilding(state, "Enemy", "Special Services") || ownerHasBuilding(state, "Enemy", "Drone Factory");
  const forwardPressure = getPlayerForwardPressure(state);
  const forwardPlayerUnits = playerUnits.filter((unit) => unit.coord.r <= Math.floor(state.map.height * 0.5));
  const forwardAirCount = forwardPlayerUnits.filter((unit) => getUnitDefinition(unit.type).domain === "Air").length;
  const forwardGroundValue = forwardPlayerUnits
    .filter((unit) => getUnitDefinition(unit.type).domain !== "Air")
    .reduce((total, unit) => total + getUnitInstanceValue(state, unit), 0);
  const contestedEnemyHalf = state.difficulty === "Hard" && forwardPressure >= ENEMY_COMBAT_PRESSURE_RESPONSE_THRESHOLD && forwardPlayerUnits.length >= 2;
  const activeGateClock = (state.gates ?? []).some((gate) => gate.occupation.Player > 0 || gate.occupation.Enemy > 0);
  const enemyGateBlocker = (state.gates ?? []).some((gate) => gate.owner !== "Enemy" && getKnownPlayerUnitsForEnemy(state).some((unit) => sameHex(unit.coord, gate.coord)));
  const antiAirProductionRisk = getEnemyAntiAirProductionRisk(state, assessment);
  const highAltitudeLayer = getEnemyHighAltitudeLayerAssessment(state, assessment, antiAirProductionRisk);

  let score = getDefaultEnemyProductionScore(unitType);
  score += getEnemyArmyExpansionProductionBonus(state, unitType);
  score += scoreUnitCountersPlayerArmy(state, unitType) * 0.9;
  score += scoreEnemyDoctrineNeedForUnit(state, unitType);
  const effectiveCaptureNeed = state.difficulty === "Hard" && activeBaseEmergency && unitType === "Infantry" ? 0 : captureNeed;
  const captureMultiplier =
    state.difficulty === "Hard" && unitType === "Infantry"
      ? state.day <= 8 && infantryPresence < 4.5 ? 10 : 2
      : state.difficulty === "Hard" && isSpecialUnit(unitType)
        ? 30
        : 22;
  score += definition.humanBased ? effectiveCaptureNeed * captureMultiplier : -Math.max(0, captureNeed - 2) * 4;
  score += unitType === "Reaper" ? 145 + assessment.reaperPlanUrgency * 0.9 + assessment.forecast.reaperPipelineNeed * 1.05 + gateDisadvantage * 80 : 0;
  score += unitType === "Ghost" ? 98 + assessment.scoutNeed * 0.34 + assessment.gateUrgency * 0.3 + assessment.forecast.specialPipelineNeed * 0.32 + gateDisadvantage * 40 + captureNeed * 18 + (assessment.strategyPlan === "GateEconomy" ? 22 : 0) : 0;
  score += unitType === "Operator" ? 84 + assessment.specialPlanUrgency * 0.32 + assessment.antiAirNeed * 0.26 + assessment.forecast.specialPipelineNeed * 0.34 + gateDisadvantage * 32 + captureNeed * 13 : 0;
  score += unitType === "Bomber" ? gateDisadvantage * 28 + assessment.player.groundCount * 14 + artilleryPressure * 0.9 : 0;
  score += unitType === "Artillery" ? 48 + gateDisadvantage * 24 + assessment.player.groundCount * 10 + Math.max(0, 2 - artilleryPresence) * 30 : 0;
  score += unitType === "Anti-Air" ? 36 + Math.max(0, 2 - antiAirPresence) * 26 + assessment.player.highValueAirCount * 20 : 0;
  score += unitType === "Tank" ? 42 + gateDisadvantage * 20 + assessment.player.groundCount * 8 + Math.max(0, 3 - tankPresence) * 18 : 0;
  score += unitType === "Attack Heli" ? gateDisadvantage * 10 + artilleryPressure * 0.18 : 0;
  score += unitType === "Command Heli" ? scoreEnemyCommandHelicopterProductionNeed(state, assessment, captureNeed) : 0;
  score += getEnemyLateReaperProductionBias(state, unitType);
  score += unitType === "Reaper" ? artilleryPressure * 0.75 : 0;
  score += unitType === "Jet" ? assessment.player.highValueAirCount * 28 : 0;
  score += unitType === "Infantry" && assessment.strategyPlan === "GroundCaptureSwarm" && state.difficulty !== "Hard" ? 44 : 0;
  score += (unitType === "Tank" || unitType === "IFV" || unitType === "Attack Heli") && assessment.strategyPlan === "GroundCaptureSwarm" ? 28 : 0;
  score += unitType === "Anti-Air" && assessment.strategyPlan === "DefensiveEconomy" ? 20 : 0;
  score += getEnemyStrategicPhaseProductionBonus(state, unitType, assessment);
  score += getEnemyOpponentProfileProductionCounterScore(state, unitType, assessment);
  score += getEnemyStrategyPlaybookProductionScore(state, unitType, assessment, antiAirProductionRisk);
  score += getEnemyHighAltitudeLayerProductionAdjustment(state, unitType, assessment, highAltitudeLayer);
  score += state.difficulty === "Hard" ? getHardDoctrineProductionBonus(state, unitType, captureNeed) : definition.humanBased ? assessment.gateUrgency * 0.18 + assessment.baseAttackUrgency * 0.16 + captureNeed * 14 : 0;
  score += state.difficulty === "Hard" && unitType === "IFV" && state.day <= 18 ? 28 : 0;
  score += state.difficulty === "Hard" && unitType === "Attack Heli" && state.day <= 18 ? 18 : 0;
  score += state.difficulty === "Hard" && (unitType === "IFV" || unitType === "Attack Heli") && assessment.scoutNeed > 45 ? assessment.scoutNeed * (unitType === "IFV" ? 0.32 : 0.24) : 0;
  score += state.difficulty === "Hard" && unitType === "Tank" && state.day >= 8 ? 36 + assessment.groundExploitationOpportunity * 0.22 : 0;
  score += state.difficulty === "Hard" && unitType === "Tank" && canEnemyAffordProductionUnit(state, "Tank")
    ? 68 + Math.max(0, getEnemyUnitPresence(state, "IFV") - getEnemyUnitPresence(state, "Tank")) * 42
    : 0;
  score += state.difficulty === "Hard" && (unitType === "Jet" || unitType === "Bomber") && state.day >= 12 ? 52 + assessment.player.totalValue * 0.05 : 0;
  score += state.difficulty === "Hard" && forwardPressure > 100 && (unitType === "Reaper" || unitType === "Ghost" || unitType === "Operator" || unitType === "Bomber" || unitType === "Tank" || unitType === "Artillery") ? forwardPressure * 0.34 : 0;
  score += state.difficulty === "Hard" && forwardPressure > 180 && unitType === "Anti-Air" && playerAirCount > 0 ? forwardPressure * 0.28 : 0;
  score -= state.difficulty === "Hard" && forwardPressure > 100 && (unitType === "IFV" || unitType === "Attack Heli") ? forwardPressure * 0.26 : 0;
  score -= state.difficulty === "Hard" && unitType === "IFV" && canEnemyAffordProductionUnit(state, "Tank")
    ? Math.max(0, getEnemyUnitPresence(state, "IFV") - 2) * 64
    : 0;
  score -= state.difficulty === "Hard" && (unitType === "Jet" || unitType === "Bomber") && state.day <= 8 ? 62 : 0;
  score += playerAirCount > 0 && canCounterAir(unitType) ? playerAirCount * 24 + assessment.antiAirNeed * 0.45 : 0;
  score += state.difficulty === "Hard" && definition.humanBased && activeGateClock ? 95 + captureNeed * 18 : 0;
  score += state.difficulty === "Hard" && definition.humanBased && state.baseOccupation.Player > 0 ? 140 + state.baseOccupation.Player * 55 : 0;
  score += state.difficulty === "Hard" && (unitType === "Tank" || unitType === "Artillery" || unitType === "Bomber" || unitType === "Reaper") && enemyGateBlocker ? 84 : 0;
  score += state.difficulty === "Hard" && unitType === "Anti-Air" && forwardAirCount > 0 ? 70 + forwardAirCount * 28 : 0;
  score += state.difficulty === "Hard" && (unitType === "IFV" || unitType === "Attack Heli") && artilleryPressure > 80 ? 45 : 0;
  score += getEnemyAntiAirRiskProductionAdjustment(state, unitType, assessment, antiAirProductionRisk);
  score += baseThreat && canUnitTargetUnit(unitType, baseThreat.type)
    ? baseThreat.score * (state.difficulty === "Hard" && unitType === "Infantry" ? 0.12 : 0.55)
    : 0;
  score += assessment.forecast.lossRisk > 180 && canUnitTargetUnit(unitType, baseThreat?.type ?? "Infantry") ? assessment.forecast.lossRisk * 0.18 : 0;
  score -= presence * (9 + cost * 0.25);
  score -= cost * 0.3 + getProductionDays(unitType) * 1.8;

  if (state.difficulty === "Hard" && unitType === "Infantry" && (state.day > 10 || getEnemyUnitPresence(state, "Infantry") >= 5)) {
    score -= 34 + Math.max(0, getEnemyUnitPresence(state, "Infantry") - 4) * 14 + gateDisadvantage * 18;
  }

  if (state.difficulty === "Hard" && unitType === "Infantry") {
    score -= Math.max(0, infantryPresence - 2) * (advancedBuildingAvailable ? 48 : 34);
    score -= artilleryPressure * 0.45;
    score -= state.day > 10 ? 46 : 0;
    score -= advancedBuildingAvailable && state.day > 10 ? 76 : 0;
    score -= infantryPresence >= 4.5 ? 80 : 0;
    score -= activeBaseEmergency ? 90 + gateDisadvantage * 28 : 0;
  }

  if (state.difficulty === "Hard" && unitType === "Attack Heli") {
    const hasSpecialServices = ownerHasBuilding(state, "Enemy", "Special Services");
    score -= state.day >= 18 ? 52 : state.day >= 12 ? 24 : 0;
    score -= hasSpecialServices ? 42 : 0;
    score -= !hasSpecialServices && state.day >= 12 ? 34 : 0;
    score -= assessment.player.specialCount > 0 ? 64 : 0;
    score -= Math.max(0, getEnemyUnitPresence(state, "Attack Heli") - 1.5) * 28;
  }

  if (state.difficulty === "Hard" && unitType === "Command Heli") {
    score -= commandHelicopterPresence >= 1.5 ? 72 + Math.max(0, commandHelicopterPresence - 1.5) * 46 : 0;
    score -= activeBaseEmergency ? 80 : 0;
    score -= assessment.antiAirNeed > 120 ? 44 : 0;
  }

  if (state.difficulty === "Hard" && (unitType === "Operator" || unitType === "Ghost")) {
    score += Math.max(0, 3 - getEnemyUnitPresence(state, unitType)) * 36;
    score += assessment.player.specialCount > 0 ? 58 : 0;
    score += state.day >= 18 ? 44 : state.day >= 12 ? 24 : 0;
    score += unitType === "Ghost" ? 36 : 10;
  }

  if (contestedEnemyHalf) {
    const directRemovalValue = forwardPlayerUnits.reduce((total, playerUnit) => {
      if (!canUnitTargetUnit(unitType, playerUnit.type)) {
        return total;
      }
      const effectiveness = EFFECTIVENESS_MULTIPLIERS[getAttackEffectiveness(unitType, playerUnit.type)];
      const enemyAreaBonus = isCoordInEnemyHomeArea(state, playerUnit.coord) ? 1.35 : 1;
      return total + getUnitInstanceValue(state, playerUnit) * effectiveness * enemyAreaBonus;
    }, 0);
    score += directRemovalValue * (isSpecialUnit(unitType) || unitType === "Tank" || unitType === "Bomber" ? 0.62 : 0.34);

    if (unitType === "Anti-Air") {
      score -= forwardAirCount > 0 ? Math.max(0, antiAirPresence - forwardAirCount) * 86 : 240 + antiAirPresence * 92;
    }
    if (unitType === "Artillery") {
      score -= Math.max(0, artilleryPresence - 1) * 94;
      score -= forwardGroundValue > 220 ? 70 : 0;
    }
    if (unitType === "Tank" || unitType === "Bomber" || unitType === "Reaper" || unitType === "Ghost" || unitType === "Operator") {
      score += Math.min(180, forwardPressure * 0.42);
    }
  }

  if (playerUnits.length === 0 && !definition.humanBased && getEnemyCaptureNeed(state) > 3) {
    score -= 12;
  }

  if (definition.targetDomains?.length === 1 && definition.targetDomains[0] === "Air" && playerAirCount === 0) {
    score -= 26;
  }

  if (assessment.reaperPlanUrgency > 130 && unitType !== "Reaper" && !definition.humanBased && !baseThreat) {
    score -= Math.max(0, getProductionCost("Reaper") - state.enemyEconomy.moneyPoundsBn) * 0.9;
  }

  return score;
}

function scoreEnemyCommandHelicopterProductionNeed(state: GameState, assessment: EnemyStrategicAssessment, captureNeed: number): number {
  if (!canOwnerProduceUnit(state, "Enemy", "Command Heli")) {
    return 0;
  }

  const supportPresence = getEnemyUnitPresence(state, "Supply Truck") + getEnemyUnitPresence(state, "Command Heli");
  const damagedFrontlineGround = getOwnerUnits(state, "Enemy").filter((unit) => isEnemyFrontlineRepairCandidate(state, unit)).length;
  const captureInventory = ENEMY_CAPTURE_UNIT_TYPES.reduce((total, unitType) => total + Math.max(0, state.enemyEconomy.inventory[unitType] ?? 0), 0);
  const contestedGateCount = (state.gates ?? []).filter((gate) => gate.owner !== "Enemy" || gate.occupation.Player > 0 || gate.occupation.Enemy > 0).length;
  const activeObjectivePhase = isEnemyGateContinuityPhase(assessment.strategicPhase) || isEnemyBaseOperationPhase(assessment.strategicPhase);

  return (
    Math.max(0, 1.2 - supportPresence) * 78 +
    damagedFrontlineGround * 42 +
    captureInventory * 34 +
    captureNeed * 16 +
    contestedGateCount * 28 +
    (activeObjectivePhase ? assessment.gateUrgency * 0.26 + assessment.baseAttackUrgency * 0.16 : 0) +
    (state.day >= 8 ? 28 : 0)
  );
}

function getEnemyStrategicPhaseProductionBonus(state: GameState, unitType: UnitType, assessment: EnemyStrategicAssessment): number {
  const definition = getUnitDefinition(unitType);
  const baseThreat = getEnemyBaseThreat(state);
  switch (assessment.strategicPhase) {
    case "OpeningGateRace":
      return definition.humanBased ? 54 : unitType === "Tank" || unitType === "IFV" ? 32 : isReconUnit(unitType) ? 22 : 0;
    case "OneGateOwned":
      return definition.humanBased ? 42 : unitType === "Tank" || unitType === "IFV" || unitType === "Artillery" ? 24 : 0;
    case "GateLockoutCombat":
      return definition.humanBased ? 34 : unitType === "Tank" || unitType === "IFV" || unitType === "Artillery" || unitType === "Reaper" ? 58 : isReconUnit(unitType) ? 28 : 0;
    case "Recovery":
      return definition.humanBased ? 72 : unitType === "Tank" || unitType === "IFV" || unitType === "Artillery" ? 36 : 0;
    case "BothGatesOwned":
      return definition.humanBased ? 58 : unitType === "Tank" || unitType === "Artillery" || unitType === "Bomber" || unitType === "Reaper" ? 42 : 0;
    case "BaseAssault":
      return definition.humanBased ? 68 : unitType === "Tank" || unitType === "Artillery" || unitType === "Bomber" || unitType === "Reaper" ? 56 : 0;
    case "BaseHold":
      return definition.humanBased ? 86 : unitType === "Tank" || unitType === "Artillery" || unitType === "Bomber" || unitType === "Reaper" ? 34 : 0;
    case "BaseDefenseEmergency":
      return baseThreat && canUnitTargetUnit(unitType, baseThreat.type)
        ? 96
        : unitType === "Tank" || unitType === "Artillery" || unitType === "Anti-Air" || unitType === "Reaper"
          ? 42
          : 0;
  }
}

function getEnemyAntiAirProductionRisk(state: GameState, assessment: EnemyStrategicAssessment): EnemyAntiAirProductionRisk {
  const threatMap = getEnemyAntiAirThreatMap(state, activeEnemyTurnPlan ?? undefined);
  const gateCoverage: Partial<Record<GateState["id"], number>> = {};
  for (const gate of state.gates ?? []) {
    gateCoverage[gate.id] = threatMap.threats.reduce((total, threat) => total + scoreAntiAirProductionThreatCoverage(state, threat, gate.coord, 2), 0);
  }
  const gateValues = Object.values(gateCoverage);
  const gateDensity = gateValues.reduce((total, value) => total + value, 0);
  const bothGatesCovered = (state.gates ?? []).length >= 2 && (state.gates ?? []).every((gate) => (gateCoverage[gate.id] ?? 0) >= 0.65);
  const baseApproachCoords = [
    state.bases.Player,
    { q: state.bases.Player.q, r: Math.max(0, state.bases.Player.r - 2) },
    { q: Math.max(0, state.bases.Player.q - 2), r: state.bases.Player.r },
    { q: Math.min(state.map.width - 1, state.bases.Player.q + 2), r: state.bases.Player.r }
  ];
  const baseApproachDensity = baseApproachCoords.reduce(
    (total, coord) => total + threatMap.threats.reduce((sum, threat) => sum + scoreAntiAirProductionThreatCoverage(state, threat, coord, 2), 0),
    0
  ) / Math.max(1, baseApproachCoords.length);
  const phaseDensity =
    isEnemyGateContinuityPhase(assessment.strategicPhase)
      ? gateDensity + (bothGatesCovered ? 0.8 : 0)
      : isEnemyBaseOperationPhase(assessment.strategicPhase)
        ? Math.max(baseApproachDensity, gateDensity * 0.55)
        : assessment.strategicPhase === "BaseDefenseEmergency"
          ? Math.max(baseApproachDensity, gateDensity) * 0.45
          : Math.max(baseApproachDensity, gateDensity);
  return {
    gateCoverage,
    gateDensity,
    bothGatesCovered,
    baseApproachDensity,
    phaseDensity,
    knownThreatCount: threatMap.threats.filter((threat) => !threat.probable).length,
    probableThreatCount: threatMap.threats.filter((threat) => threat.probable).length
  };
}

function scoreAntiAirProductionThreatCoverage(
  state: GameState,
  threat: EnemyAntiAirThreat,
  coord: UnitInstance["coord"],
  buffer: number
): number {
  const owner: Owner = threat.unit?.owner ?? "Player";
  const level = threat.unit?.level ?? state.economy.unitLevels["Anti-Air"] ?? 1;
  const stats = getEffectiveUnitStats(state, owner, "Anti-Air", level, threat.coord, coord);
  const distance = hexDistance(threat.coord, coord);
  if (distance <= stats.attackRange) {
    return threat.confidence * (threat.probable ? 0.82 : 1);
  }
  if (distance <= stats.attackRange + buffer) {
    return threat.confidence * (threat.probable ? 0.42 : 0.58);
  }
  return 0;
}

function getEnemyAntiAirRiskProductionAdjustment(
  state: GameState,
  unitType: UnitType,
  assessment: EnemyStrategicAssessment,
  risk: EnemyAntiAirProductionRisk
): number {
  if (state.difficulty !== "Hard" || risk.phaseDensity <= 0) {
    return 0;
  }

  const gatePhase = isEnemyGateContinuityPhase(assessment.strategicPhase);
  const bothGatePenalty = gatePhase && risk.bothGatesCovered ? 1 : 0;
  if (unitType === "Attack Heli") {
    return -risk.phaseDensity * 64 - bothGatePenalty * 135;
  }
  if (unitType === "Bomber") {
    return -risk.phaseDensity * 54 - bothGatePenalty * 105 - (assessment.airExploitationOpportunity < 220 ? 32 : 0);
  }
  if (unitType === "Jet") {
    return -risk.phaseDensity * 28 - bothGatePenalty * 45;
  }
  if (unitType === "Reaper") {
    return isEnemyReaperProductionSurvivalAcceptable(state, assessment, risk)
      ? Math.max(-44, -risk.phaseDensity * 16)
      : -risk.phaseDensity * 72 - 140;
  }

  if (unitType === "Ghost") {
    return risk.phaseDensity * 24 + bothGatePenalty * 46;
  }
  if (unitType === "Operator") {
    return risk.phaseDensity * 22 + bothGatePenalty * 40;
  }
  if (unitType === "Tank") {
    return risk.phaseDensity * 18 + bothGatePenalty * 32;
  }
  if (unitType === "Artillery") {
    return risk.phaseDensity * 26 + bothGatePenalty * 42;
  }
  return 0;
}

function getEnemyGateLockoutAirCounterattackProductionAdjustment(
  state: GameState,
  plan: EnemyTurnPlan,
  unitType: UnitType
): number {
  if (state.difficulty !== "Hard" || plan.campaignPlan.phase !== "GateLockoutCombat") {
    return 0;
  }

  const airPlan = assessEnemyGateLockoutAirCounterattack(state, plan);
  const isHighAltitudeAttack = unitType === "Bomber" || unitType === "Reaper" || unitType === "Jet";
  const isGroundOrSpecialRemover =
    unitType === "Tank" ||
    unitType === "Artillery" ||
    unitType === "Ghost" ||
    unitType === "Operator" ||
    unitType === "IFV";

  if (airPlan.bothGateAntiAirDensity) {
    if (isHighAltitudeAttack) {
      const expensiveAirPenalty = unitType === "Bomber" || unitType === "Reaper" ? 230 : 125;
      return -(expensiveAirPenalty + airPlan.targetGateCoverage * 95);
    }
    return isGroundOrSpecialRemover ? 125 + airPlan.targetGateCoverage * 72 : 0;
  }

  if (!airPlan.antiAirAbsentOrClearable || airPlan.clusteredDefenderCount < 2) {
    return isHighAltitudeAttack ? -Math.max(0, airPlan.targetGateCoverage - 0.35) * 85 : 0;
  }

  if (unitType === "Bomber") {
    return 185 + airPlan.clusteredGroundValue * 0.42 + Math.max(0, 4 - getProductionDays(unitType)) * 18;
  }
  if (unitType === "Reaper") {
    return 165 + (airPlan.clusteredGroundValue + airPlan.clusteredAirValue) * 0.34;
  }
  if (unitType === "Jet") {
    return airPlan.clusteredAirValue > 0 ? 125 + airPlan.clusteredAirValue * 0.48 : airPlan.targetGateCoverage <= 0.15 ? 42 : 0;
  }

  return 0;
}

function assessEnemyGateLockoutAirCounterattack(state: GameState, plan: EnemyTurnPlan): EnemyGateLockoutAirCounterattackAssessment {
  const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
  const risk = getEnemyAntiAirProductionRisk(state, plan.strategicSnapshot);
  if (!gate) {
    return {
      targetGateCoverage: 0,
      bothGateAntiAirDensity: risk.bothGatesCovered,
      antiAirAbsentOrClearable: !risk.bothGatesCovered && risk.phaseDensity < 0.45,
      clusteredGroundValue: 0,
      clusteredAirValue: 0,
      clusteredDefenderCount: 0
    };
  }

  const threatMap = getEnemyAntiAirThreatMap(state, plan);
  const targetGateCoverage = risk.gateCoverage[gate.id] ?? 0;
  const bothGateAntiAirDensity =
    risk.bothGatesCovered ||
    ((state.gates ?? []).length >= 2 && (state.gates ?? []).every((candidate) => (risk.gateCoverage[candidate.id] ?? 0) >= 0.85));
  const antiAirThreatsNearGate = threatMap.threats.filter((threat) => scoreAntiAirProductionThreatCoverage(state, threat, gate.coord, 2) > 0);
  const knownAntiAirThreatsNearGate = antiAirThreatsNearGate.filter((threat) => !threat.probable);
  const antiAirAbsentOrClearable =
    (knownAntiAirThreatsNearGate.length === 0 && targetGateCoverage < 0.9) ||
    (knownAntiAirThreatsNearGate.length > 0 && knownAntiAirThreatsNearGate.every((threat) => canEnemyGateLockoutClearAntiAirThreat(state, threat, plan)));
  const clusteredDefenders = plan.playerIntel
    .filter((intel) => intel.age <= 3)
    .filter((intel) => hexDistance(intel.predictedCoord, gate.coord) <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS)
    .filter((intel) => getUnitDefinition(intel.unit.type).humanBased || intel.unit.type === "Tank" || intel.unit.type === "IFV" || intel.unit.type === "Artillery" || intel.unit.type === "Anti-Air" || getUnitDefinition(intel.unit.type).domain === "Air");
  const clusteredGroundValue = clusteredDefenders
    .filter((intel) => getUnitDefinition(intel.unit.type).domain !== "Air")
    .reduce((total, intel) => total + getUnitInstanceValue(state, intel.unit) * intel.confidence, 0);
  const clusteredAirValue = clusteredDefenders
    .filter((intel) => getUnitDefinition(intel.unit.type).domain === "Air")
    .reduce((total, intel) => total + getUnitInstanceValue(state, intel.unit) * intel.confidence, 0);

  return {
    gate,
    targetGateCoverage,
    bothGateAntiAirDensity,
    antiAirAbsentOrClearable,
    clusteredGroundValue,
    clusteredAirValue,
    clusteredDefenderCount: clusteredDefenders.length
  };
}

function canEnemyGateLockoutClearAntiAirThreat(state: GameState, threat: EnemyAntiAirThreat, plan: EnemyTurnPlan): boolean {
  if (!threat.unit || threat.probable) {
    return false;
  }

  const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
  return getOwnerUnits(state, "Enemy").some((unit) => {
    if (unit.health / Math.max(1, unit.maxHealth) <= 0.35 || getUnitDefinition(unit.type).domain === "Air" || !canUnitTargetUnit(unit.type, threat.unit!.type)) {
      return false;
    }
    const distance = hexDistance(unit.coord, threat.coord);
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, threat.coord);
    const reach = stats.attackRange + (getUnitDefinition(unit.type).cannotMoveAndAttack ? 0 : stats.moveRange);
    if (distance > reach + 1) {
      return false;
    }
    const projected = estimateAttackDamage(state, unit, threat.unit!);
    return projected >= threat.unit!.health * 0.72 || Boolean(gate && getEnemyGateTheatreTargetPriority(state, threat.unit!, gate) > 0);
  });
}

function getEnemyHighAltitudeLayerAssessment(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  antiAirRisk = getEnemyAntiAirProductionRisk(state, assessment)
): EnemyHighAltitudeLayerAssessment {
  const playerHighAltitudeIntel = getPlayerIntelForEnemy(state).filter((intel) => isHighAltitudeAirUnit(intel.unit.type));
  const playerHighAltitudePressure = playerHighAltitudeIntel.reduce((score, intel) => {
    const basePressure = Math.max(0, getEnemyBaseResponseRadius(state) + 4 - hexDistance(intel.predictedCoord, state.bases.Enemy)) * 18;
    const gatePressure = (state.gates ?? []).reduce(
      (total, gate) => total + Math.max(0, 7 - hexDistance(intel.predictedCoord, gate.coord)) * (gate.owner === "Player" ? 18 : 10),
      0
    );
    return score + (getUnitInstanceValue(state, intel.unit) * 0.72 + basePressure + gatePressure) * intel.confidence;
  }, 0);
  const enemyHighAltitudeCount = getOwnerUnits(state, "Enemy").filter((unit) => isHighAltitudeAirUnit(unit.type)).length;
  const queuedHighAltitudeCount = state.enemyEconomy.productionQueue.filter((job) => isHighAltitudeAirUnit(job.unitType)).length;
  const enemyAntiAirReadyCount =
    getEnemyUnitPresence(state, "Anti-Air") +
    (state.enemyEconomy.inventory["Anti-Air"] ?? 0) +
    state.enemyEconomy.productionQueue.filter((job) => job.unitType === "Anti-Air").length * 0.65;
  const playerAntiAirThreatCount = antiAirRisk.knownThreatCount + antiAirRisk.probableThreatCount * 0.55;
  const exploitOpportunity = Math.max(
    0,
    assessment.airExploitationOpportunity +
      assessment.player.groundCount * 48 +
      Math.max(0, assessment.player.groundCount - playerAntiAirThreatCount * 2) * 36 -
      antiAirRisk.phaseDensity * 190 -
      playerAntiAirThreatCount * 82
  );
  const conservativeRisk =
    antiAirRisk.phaseDensity * 128 +
    antiAirRisk.knownThreatCount * 76 +
    antiAirRisk.probableThreatCount * 38 +
    (antiAirRisk.bothGatesCovered ? 190 : 0);
  const antiAirResponseUrgency = Math.max(
    0,
    playerHighAltitudePressure +
      assessment.player.highValueAirCount * 145 +
      Math.max(0, assessment.player.highValueAirCount - enemyAntiAirReadyCount) * 125 -
      enemyAntiAirReadyCount * 78
  );

  return {
    playerHighAltitudeCount: assessment.player.highValueAirCount,
    playerHighAltitudePressure,
    enemyHighAltitudeCount,
    enemyHighAltitudeReadyCount: enemyHighAltitudeCount + queuedHighAltitudeCount + (state.enemyEconomy.inventory["Jet"] ?? 0) + (state.enemyEconomy.inventory["Bomber"] ?? 0) + (state.enemyEconomy.inventory["Reaper"] ?? 0),
    enemyAntiAirReadyCount,
    playerAntiAirThreatCount,
    exploitOpportunity,
    conservativeRisk,
    antiAirResponseUrgency
  };
}

function getEnemyHighAltitudeLayerProductionAdjustment(
  state: GameState,
  unitType: UnitType,
  assessment: EnemyStrategicAssessment,
  layer: EnemyHighAltitudeLayerAssessment
): number {
  if (state.difficulty !== "Hard") {
    return 0;
  }

  if (unitType === "Anti-Air") {
    return (
      layer.antiAirResponseUrgency * 0.92 +
      (layer.playerHighAltitudeCount > 0 ? 145 : 0) +
      Math.max(0, layer.playerHighAltitudeCount + 1 - layer.enemyAntiAirReadyCount) * 74
    );
  }

  if (unitType === "Jet") {
    const counterBonus = layer.playerHighAltitudeCount > 0 ? 110 + layer.playerHighAltitudePressure * 0.28 : 0;
    const escortOwnLayer = layer.enemyHighAltitudeReadyCount > 0 ? 32 : 0;
    return counterBonus + escortOwnLayer - Math.max(0, layer.conservativeRisk - 220) * 0.18;
  }

  if (unitType === "Reaper") {
    const exploitBonus = layer.exploitOpportunity * 0.38 + (layer.playerAntiAirThreatCount <= 0.15 ? 88 : 0);
    const highAltitudeCounterBonus = layer.playerHighAltitudeCount > 0 ? 68 + layer.playerHighAltitudePressure * 0.18 : 0;
    return exploitBonus + highAltitudeCounterBonus - layer.conservativeRisk * 0.36;
  }

  if (unitType === "Bomber") {
    const exploitBonus = layer.exploitOpportunity * 0.52 + (layer.playerAntiAirThreatCount <= 0.15 ? 116 : 0);
    return exploitBonus - layer.conservativeRisk * 0.48;
  }

  if (layer.playerHighAltitudeCount > 0 && !canCounterHighAltitudeAir(unitType) && getUnitDefinition(unitType).domain === "Ground" && !getUnitDefinition(unitType).humanBased) {
    return -Math.min(96, layer.antiAirResponseUrgency * 0.22);
  }

  return 0;
}

function isEnemyReaperProductionSurvivalAcceptable(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  risk = getEnemyAntiAirProductionRisk(state, assessment)
): boolean {
  if (risk.phaseDensity < 1.1) {
    return true;
  }
  if (isEnemyBaseOperationPhase(assessment.strategicPhase) && risk.baseApproachDensity < 0.9) {
    return true;
  }
  if (assessment.reaperPlanUrgency > 190 && assessment.airExploitationOpportunity > 240 && !risk.bothGatesCovered) {
    return true;
  }
  return false;
}

function getHardDoctrineProductionBonus(state: GameState, unitType: UnitType, captureNeed: number): number {
  const assessment = getEnemyStrategicAssessment(state);
  if (unitType === "Infantry") {
    const openingGateBonus = state.day <= 8 ? assessment.gateUrgency * 0.08 : 0;
    const emergencyCaptureBonus = state.difficulty === "Hard" ? 0 : getEnemyBaseThreat(state) ? captureNeed * 5 : 0;
    return openingGateBonus + emergencyCaptureBonus;
  }

  if (unitType === "Operator" || unitType === "Ghost") {
    return assessment.gateUrgency * 0.26 + assessment.baseAttackUrgency * 0.22 + captureNeed * 22;
  }

  if (unitType === "Reaper") {
    return assessment.baseAttackUrgency * 0.22 + assessment.gateUrgency * 0.16;
  }

  if (unitType === "IFV" || unitType === "Tank" || unitType === "Attack Heli" || unitType === "Artillery" || unitType === "Bomber") {
    return assessment.groundExploitationOpportunity * 0.22 + assessment.baseAttackUrgency * 0.1 + assessment.gateUrgency * 0.1;
  }

  return 0;
}

function findEnemyPlacementCoord(state: GameState, unitType: UnitType, plan?: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  const doctrineCoord = chooseOpeningDoctrineCenterPlacementCoord(state, unitType);
  if (doctrineCoord) {
    return doctrineCoord;
  }

  const supplyTruckCoord = chooseEnemyMidgameSupplyTruckPlacementCoord(state, unitType, plan);
  if (supplyTruckCoord) {
    return supplyTruckCoord;
  }

  const campaignRouteCoord = chooseEnemyCampaignRoutePlacementCoord(state, unitType, plan);
  if (campaignRouteCoord) {
    return campaignRouteCoord;
  }

  const openingGate = chooseOpeningGatePlacementTarget(state, unitType, plan);
  return getLegalPlacementCoords(state, "Enemy", unitType)
    .map((coord) => ({
      coord,
      score:
        scoreEnemyPlacementCoord(state, unitType, coord, plan) +
        (openingGate ? scoreOpeningGatePlacementCoord(state, unitType, coord, openingGate) : 0) +
        scoreOpeningDoctrinePlacementCoord(state, unitType, coord, openingGate)
    }))
    .sort((first, second) => second.score - first.score)[0]?.coord;
}

function chooseEnemyCampaignRoutePlacementCoord(
  state: GameState,
  unitType: UnitType,
  plan?: EnemyTurnPlan
): UnitInstance["coord"] | undefined {
  if (
    !plan ||
    !getUnitDefinition(unitType).humanBased ||
    !isEnemyGateContinuityPhase(plan.campaignPlan.phase) ||
    plan.campaignPlan.phase === "OpeningGateRace"
  ) {
    return undefined;
  }
  const gate = chooseEnemyCampaignPlacementGateTarget(state, unitType, plan);
  if (!gate) {
    return undefined;
  }

  return getLegalPlacementCoords(state, "Enemy", unitType)
    .map((coord) => ({
      coord,
      route: estimateEnemyPlacementObjectiveRoute(state, unitType, coord, gate.coord),
      laneDistance: Math.abs(coord.q - getOpeningGateTopLaneQ(state, gate))
    }))
    .filter((entry) => entry.route.reachable)
    .sort((first, second) =>
      first.route.routeDistance - second.route.routeDistance ||
      first.laneDistance - second.laneDistance ||
      hexDistance(first.coord, gate.coord) - hexDistance(second.coord, gate.coord) ||
      hexId(first.coord).localeCompare(hexId(second.coord))
    )[0]?.coord;
}

function chooseEnemyMidgameSupplyTruckPlacementCoord(state: GameState, unitType: UnitType, plan?: EnemyTurnPlan): UnitInstance["coord"] | undefined {
  if (
    state.difficulty !== "Hard" ||
    state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY ||
    getUnitDefinition(unitType).domain !== "Ground" ||
    plan?.campaignPlan.phase === "BaseDefenseEmergency" ||
    isActiveEnemyBaseThreat(state, getEnemyBaseThreat(state))
  ) {
    return undefined;
  }

  const target = chooseEnemyDeploymentTarget(state, unitType, plan);
  const center = getEnemyMidgameCenterStagingCoord(state);
  const commitmentBonus = plan && isEnemyGateFightCommitmentPhase(plan.campaignPlan.phase) ? 900 : 0;
  return getLegalPlacementCoords(state, "Enemy", unitType)
    .filter((coord) => isEnemySupplyTruckPlacementCoord(state, coord, unitType))
    .map((coord) => {
      const placementAnchor = getEnemySupplyPlacementAnchor(state, coord, unitType);
      const nearestSupplyDistance = getOwnerUnits(state, "Enemy")
        .filter((unit) => isEnemySupplySupportUnit(unit.type))
        .reduce((best, unit) => Math.min(best, hexDistance(unit.coord, coord)), Number.POSITIVE_INFINITY);
      const route = estimateEnemyPlacementObjectiveRoute(state, unitType, coord, target);
      const commandHelicopterGateDrop =
        placementAnchor &&
        isEnemyCommandHelicopter(placementAnchor.type) &&
        getUnitDefinition(unitType).humanBased &&
        (state.gates ?? []).some((gate) => gate.owner !== "Enemy" && sameHex(coord, gate.coord))
          ? 2_400
          : 0;
      return {
        coord,
        score:
          commitmentBonus +
          commandHelicopterGateDrop +
          Math.max(0, 5 - nearestSupplyDistance) * 90 +
          Math.max(0, 18 - route.routeDistance) * (plan && isEnemyGateFightCommitmentPhase(plan.campaignPlan.phase) ? 26 : 16) -
          (route.reachable ? 0 : 120) +
          Math.max(0, 14 - hexDistance(coord, center)) * 18 +
          coord.r * (plan && isEnemyGateFightCommitmentPhase(plan.campaignPlan.phase) ? 6 : 3) -
          Math.abs(coord.q - state.bases.Enemy.q) * 2
      };
    })
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))[0]?.coord;
}

function chooseOpeningDoctrineCenterPlacementCoord(state: GameState, unitType: UnitType): UnitInstance["coord"] | undefined {
  if (!isHardOpeningInitialDeployment(state) || (unitType !== "Artillery" && unitType !== "Anti-Air" && unitType !== "Supply Truck")) {
    return undefined;
  }

  const target = getEnemyOpeningCenterStagingCoord(state);
  return getLegalPlacementCoords(state, "Enemy", unitType)
    .map((coord) => {
      const nearbyCenterSupport = getOwnerUnits(state, "Enemy")
        .filter((unit) => unit.type === "Artillery" || unit.type === "Anti-Air" || unit.type === "Supply Truck")
        .filter((unit) => hexDistance(unit.coord, coord) <= 1)
        .length;
      return {
        coord,
        centerDistance: Math.abs(coord.q - target.q),
        targetDistance: hexDistance(coord, target),
        nearbyCenterSupport
      };
    })
    .sort((first, second) =>
      first.centerDistance - second.centerDistance ||
      first.targetDistance - second.targetDistance ||
      first.nearbyCenterSupport - second.nearbyCenterSupport ||
      first.coord.q - second.coord.q ||
      first.coord.r - second.coord.r
    )[0]?.coord;
}

function chooseOpeningGatePlacementTarget(state: GameState, unitType: UnitType, plan?: EnemyTurnPlan): GateState | undefined {
  if (!isHardOpeningGateRace(state) || (!getUnitDefinition(unitType).humanBased && !isPatrolCapableUnit(unitType) && !isOpeningGateSupportUnit(unitType))) {
    return undefined;
  }

  const gates = state.gates ?? [];
  const west = gates.find((gate) => gate.id === "West");
  const east = gates.find((gate) => gate.id === "East");
  if (!west || !east) {
    return undefined;
  }

  const doctrineGate = chooseOpeningDoctrinePlacementGateTarget(state, unitType);
  if (doctrineGate) {
    return doctrineGate;
  }

  const campaignGate = chooseEnemyCampaignPlacementGateTarget(state, unitType, plan);
  if (campaignGate && campaignGate.owner !== "Enemy" && isOpeningGateSupportUnit(unitType)) {
    return campaignGate;
  }

  const westCommitment = getOpeningGateLaneCommitment(state, "West");
  const eastCommitment = getOpeningGateLaneCommitment(state, "East");
  if (westCommitment !== eastCommitment) {
    return westCommitment < eastCommitment ? west : east;
  }

  if (campaignGate && campaignGate.owner !== "Enemy") {
    return campaignGate;
  }

  const westScore = scoreOpeningGateFallback(state, west);
  const eastScore = scoreOpeningGateFallback(state, east);
  return westScore >= eastScore ? west : east;
}

function chooseEnemyCampaignPlacementGateTarget(
  state: GameState,
  unitType: UnitType,
  plan?: EnemyTurnPlan,
  coord?: UnitInstance["coord"]
): GateState | undefined {
  const campaign = plan?.campaignPlan ?? (state as GameStateWithEnemyCampaign).enemyCampaignPlan;
  if (!campaign) {
    return undefined;
  }
  if (campaign.phase === "BothGatesOwned" || campaign.phase === "BaseAssault" || campaign.phase === "BaseHold") {
    return undefined;
  }

  const gates = state.gates ?? [];
  const byId = (gateId?: GateState["id"]): GateState | undefined => gateId ? gates.find((gate) => gate.id === gateId) : undefined;
  const candidates = [byId(campaign.mainEffortGateId), byId(campaign.secondaryGateId), ...gates]
    .filter((gate): gate is GateState => Boolean(gate))
    .filter((gate, index, all) => all.findIndex((candidate) => candidate.id === gate.id) === index);
  const capturer = getUnitDefinition(unitType).humanBased;
  const support = isEnemyCampaignPlacementSupportUnit(unitType);
  if (!capturer && !support && !isReconUnit(unitType)) {
    return undefined;
  }

  const origin = coord ?? state.bases.Enemy;
  return candidates
    .filter((gate) => gate.owner !== "Enemy" || gate.occupation.Player > 0 || campaign.phase === "Recovery" || campaign.phase === "GateLockoutCombat" || gate.id === campaign.mainEffortGateId)
    .sort((first, second) => {
      const firstUrgency = scoreEnemyCampaignPlacementGateUrgency(state, first, campaign, origin, capturer);
      const secondUrgency = scoreEnemyCampaignPlacementGateUrgency(state, second, campaign, origin, capturer);
      return secondUrgency - firstUrgency || first.id.localeCompare(second.id);
    })[0];
}

function scoreEnemyCampaignPlacementGateUrgency(
  state: GameState,
  gate: GateState,
  campaign: EnemyCampaignPlan,
  origin: UnitInstance["coord"],
  capturer: boolean
): number {
  const enemyTurns = campaign.objectiveClock.enemyTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY;
  const playerTurns = campaign.objectiveClock.playerTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY;
  return (
    (gate.id === campaign.mainEffortGateId ? 520 : 0) +
    (gate.id === campaign.secondaryGateId ? 180 : 0) +
    (gate.owner !== "Enemy" ? (capturer ? 360 : 210) : 0) +
    gate.occupation.Player * 85 +
    gate.occupation.Enemy * (capturer ? 95 : 40) +
    (playerTurns <= 1 ? 420 : playerTurns <= 2 ? 190 : 0) +
    (enemyTurns <= 1 ? 340 : enemyTurns <= 2 ? 160 : 0) -
    hexDistance(origin, gate.coord) * 7
  );
}

function isEnemyCampaignPlacementSupportUnit(unitType: UnitType): boolean {
  return unitType === "Supply Truck" || unitType === "Anti-Air" || unitType === "Artillery" || isOpeningGateSupportUnit(unitType) || isPatrolCapableUnit(unitType);
}

function isEnemyBaseOperationPlacementPhase(phase: EnemyStrategicPhase | undefined): boolean {
  return phase === "BothGatesOwned" || phase === "BaseAssault" || phase === "BaseHold";
}

function chooseEnemyCampaignBasePlacementTarget(state: GameState, unitType: UnitType, plan?: EnemyTurnPlan): UnitInstance["coord"] {
  const campaign = plan?.campaignPlan ?? (state as GameStateWithEnemyCampaign).enemyCampaignPlan;
  if (unitType === "Anti-Air") {
    const airThreat = choosePlayerHighAltitudeThreatForEnemy(state);
    if (airThreat) {
      return airThreat.predictedCoord;
    }
  }
  const baseBlocker = getPlayerBaseTileBlocker(state) ?? getPlayerBaseAreaDefender(state);
  if (baseBlocker && canUnitTargetUnit(unitType, baseBlocker.type)) {
    return baseBlocker.coord;
  }
  const route = campaign?.baseAssaultRoute ?? [];
  return route[Math.min(route.length - 1, Math.max(0, Math.floor(route.length * 0.65)))] ?? state.bases.Player;
}

function scoreEnemyCampaignPlacementCoord(
  state: GameState,
  unitType: UnitType,
  coord: UnitInstance["coord"],
  plan?: EnemyTurnPlan
): number {
  const campaign = plan?.campaignPlan ?? (state as GameStateWithEnemyCampaign).enemyCampaignPlan;
  if (!campaign || !usesHardEnemyDoctrine(state)) {
    return 0;
  }

  const definition = getUnitDefinition(unitType);
  const gate =
    state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY
      ? chooseOpeningGatePlacementTarget(state, unitType, plan) ?? chooseEnemyCampaignPlacementGateTarget(state, unitType, plan, coord)
      : chooseEnemyCampaignPlacementGateTarget(state, unitType, plan, coord);
  const gatePhase = isEnemyGateContinuityPhase(campaign.phase);
  let score = 0;
  if (campaign.phase === "GateLockoutCombat") {
    return 0;
  }

  if (gate && gatePhase) {
    const laneDistance = Math.abs(coord.q - getOpeningGateTopLaneQ(state, gate));
    const gateRoute = estimateEnemyPlacementObjectiveRoute(state, unitType, coord, gate.coord);
    const gateDistance = gateRoute.routeDistance;
    const routeDetour = Math.max(0, gateRoute.routeDistance - gateRoute.geometricDistance);
    const laneWeight = definition.humanBased ? 36 : unitType === "Tank" || unitType === "IFV" ? 24 : unitType === "Anti-Air" || unitType === "Artillery" ? 18 : 14;
    const distanceWeight = definition.humanBased ? 12 : unitType === "Tank" || unitType === "IFV" ? 9 : 6;
    score += Math.max(0, 18 - laneDistance) * laneWeight;
    score += Math.max(0, 26 - gateDistance) * distanceWeight;
    score -= laneDistance > 10 ? 120 : 0;
    score -= routeDetour * (definition.humanBased ? 30 : 18);
    score -= gateRoute.reachable ? 0 : 220;
    if (gate.id === campaign.mainEffortGateId) {
      score += definition.humanBased ? 220 : 130;
    }
    if (gate.occupation.Player > 0 || gate.occupation.Enemy > 0) {
      score += definition.humanBased ? 160 : 80;
    }
    if (unitType === "Tank" || unitType === "IFV") {
      score += Math.max(0, 7 - Math.abs(coord.q - gate.coord.q)) * 10;
    }
    if (unitType === "Anti-Air" || unitType === "Artillery") {
      const sideSight = getGateSideSightStrategicScore(state, gate);
      score += sideSight * 0.08;
    }
    return score;
  }

  if (isEnemyBaseOperationPlacementPhase(campaign.phase)) {
    const target = chooseEnemyCampaignBasePlacementTarget(state, unitType, plan);
    const route = campaign.baseAssaultRoute.length ? campaign.baseAssaultRoute : [state.bases.Player];
    const routeDistance = route.reduce((best, routeCoord) => Math.min(best, hexDistance(coord, routeCoord)), Number.POSITIVE_INFINITY);
    const targetRoute = estimateEnemyPlacementObjectiveRoute(state, unitType, coord, target);
    const targetDistance = targetRoute.routeDistance;
    const targetDetour = Math.max(0, targetRoute.routeDistance - targetRoute.geometricDistance);
    const baseWeight =
      definition.humanBased ? 20 :
      unitType === "Tank" || unitType === "IFV" ? 16 :
      unitType === "Artillery" ? 18 :
      unitType === "Anti-Air" ? 14 :
      isReconUnit(unitType) ? 12 :
      8;
    score += Math.max(0, 28 - targetDistance) * baseWeight;
    score += Math.max(0, 14 - routeDistance) * (baseWeight + 4);
    score -= targetDetour * (baseWeight + 8);
    score -= targetRoute.reachable ? 0 : 240;
    if (unitType === "Artillery") {
      score += Math.max(0, 16 - targetDistance) * 18;
    }
    if (unitType === "Anti-Air") {
      score += scoreEnemyHighAltitudeLayerPlacement(state, unitType, coord, plan) * 0.8;
    }
    return score;
  }

  if (campaign.phase === "BaseDefenseEmergency") {
    const baseThreat = getEnemyBaseThreat(state);
    if (baseThreat) {
      score += Math.max(0, getEnemyBaseResponseRadius(state) + 4 - hexDistance(coord, baseThreat.coord)) * (canUnitTargetUnit(unitType, baseThreat.type) ? 32 : 14);
    }
  }

  return score;
}

function getOpeningGateLaneCommitment(state: GameState, lane: GateState["id"]): number {
  const west = (state.gates ?? []).find((gate) => gate.id === "West");
  const east = (state.gates ?? []).find((gate) => gate.id === "East");
  if (!west || !east) {
    return 0;
  }

  const westLaneQ = getOpeningGateTopLaneQ(state, west);
  const eastLaneQ = getOpeningGateTopLaneQ(state, east);
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => getUnitDefinition(unit.type).humanBased || isPatrolCapableUnit(unit.type))
    .filter((unit) => {
      const westDistance = Math.abs(unit.coord.q - westLaneQ);
      const eastDistance = Math.abs(unit.coord.q - eastLaneQ);
      return lane === "West" ? westDistance <= eastDistance : eastDistance < westDistance;
    })
    .reduce((total, unit) => total + (getUnitDefinition(unit.type).humanBased ? 1 : 0.75), 0);
}

function scoreOpeningGatePlacementCoord(state: GameState, unitType: UnitType, coord: UnitInstance["coord"], gate: GateState): number {
  const laneQ = getOpeningGateTopLaneQ(state, gate);
  const laneDistance = Math.abs(coord.q - laneQ);
  const laneBonus = Math.max(0, 12 - laneDistance) * (getUnitDefinition(unitType).humanBased ? 28 : 12);
  const edgePenalty = laneDistance > 14 ? 80 : 0;
  return laneBonus - edgePenalty;
}

function chooseOpeningDoctrinePlacementGateTarget(state: GameState, unitType: UnitType): GateState | undefined {
  if (!isHardOpeningInitialDeployment(state)) {
    return undefined;
  }

  const gates = state.gates ?? [];
  const west = gates.find((gate) => gate.id === "West");
  const east = gates.find((gate) => gate.id === "East");
  if (!west || !east) {
    return undefined;
  }

  if (unitType === "Infantry") {
    return chooseOpeningDoctrineUnderfilledLane(state, unitType, 3);
  }
  if (unitType === "Tank") {
    return chooseOpeningDoctrineUnderfilledLane(state, unitType, 1);
  }
  if (unitType === "IFV") {
    return gates.find((gate) => gate.id === getEnemySeededOpeningMainEffortGateId(state));
  }
  if (unitType === "Attack Heli") {
    return gates.find((gate) => gate.id === getOppositeGateId(getEnemySeededOpeningMainEffortGateId(state)));
  }
  return undefined;
}

function chooseOpeningDoctrineUnderfilledLane(state: GameState, unitType: UnitType, desiredPerLane: number): GateState | undefined {
  const gates = state.gates ?? [];
  const west = gates.find((gate) => gate.id === "West");
  const east = gates.find((gate) => gate.id === "East");
  if (!west || !east) {
    return undefined;
  }

  const westCount = countOpeningDoctrineLaneUnits(state, unitType, "West");
  const eastCount = countOpeningDoctrineLaneUnits(state, unitType, "East");
  if (westCount < desiredPerLane || eastCount < desiredPerLane) {
    return westCount <= eastCount ? west : east;
  }

  return westCount <= eastCount ? west : east;
}

function countOpeningDoctrineLaneUnits(state: GameState, unitType: UnitType, gateId: GateState["id"]): number {
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => unit.type === unitType)
    .filter((unit) => gateId === "West" ? unit.coord.q <= state.bases.Enemy.q : unit.coord.q > state.bases.Enemy.q)
    .length;
}

function scoreOpeningDoctrinePlacementCoord(
  state: GameState,
  unitType: UnitType,
  coord: UnitInstance["coord"],
  gate: GateState | undefined
): number {
  if (!isHardOpeningInitialDeployment(state)) {
    return 0;
  }

  if (unitType === "Artillery" || unitType === "Anti-Air" || unitType === "Supply Truck") {
    const target = getEnemyOpeningCenterStagingCoord(state);
    const centerDistance = Math.abs(coord.q - target.q);
    const centerLaneScore = Math.max(0, 14 - centerDistance) * 130;
    const backRowSpread = getOwnerUnits(state, "Enemy")
      .filter((unit) => unit.type === "Artillery" || unit.type === "Anti-Air" || unit.type === "Supply Truck")
      .filter((unit) => hexDistance(unit.coord, coord) <= 1)
      .length * 35;
    return 5_000 + centerLaneScore - centerDistance * 90 - hexDistance(coord, target) * 9 - backRowSpread;
  }

  if (!gate) {
    return 0;
  }

  const laneQ = getOpeningGateTopLaneQ(state, gate);
  const laneDistance = Math.abs(coord.q - laneQ);
  const wrongSidePenalty = gate.id === "West"
    ? coord.q > state.bases.Enemy.q ? 8_000 : 0
    : coord.q <= state.bases.Enemy.q ? 8_000 : 0;
  const typeWeight =
    unitType === "Infantry" ? 96 :
    unitType === "Tank" ? 92 :
    unitType === "IFV" ? 110 :
    unitType === "Attack Heli" ? 88 :
    0;
  return 5_000 + Math.max(0, 16 - laneDistance) * typeWeight - laneDistance * 18 - wrongSidePenalty;
}

function getOpeningGateTopLaneQ(state: GameState, gate: GateState): number {
  const rowOffset = Math.floor(gate.coord.r / 2);
  return Math.max(0, Math.min(state.map.width - 1, gate.id === "West" ? gate.coord.q + rowOffset : gate.coord.q - rowOffset));
}

function assignEnemyMission(state: GameState, unit: UnitInstance): EnemyMission {
  const assignedMission = activeEnemyTurnPlan?.day === state.day
    ? activeEnemyTurnPlan.rolesByUnitId[unit.id]
    : getEnemyRoleAssignments(state)[unit.id];
  const assessment = getEnemyStrategicAssessment(state);
  const definition = getUnitDefinition(unit.type);
  const healthRatio = unit.health / Math.max(1, unit.maxHealth);
  const baseThreat = getEnemyBaseThreat(state);

  if (assessment.baseDefenseUrgency > (state.difficulty === "Hard" ? 115 : 160) && isActiveEnemyBaseThreat(state, baseThreat) && baseThreat && canUnitTargetUnit(unit.type, baseThreat.type)) {
    return "DefendBase";
  }

  if (shouldEnemyRetreatForRepair(state, unit)) {
    return "Repair";
  }

  if (assignedMission) {
    return assignedMission;
  }

  if (state.difficulty === "Hard" && definition.humanBased && healthRatio > 0.4) {
    if (isEnemyGateContinuityPhase(assessment.strategicPhase)) {
      return chooseEnemyGateDefenseObjective(state, unit.coord) ? "DefendGate" : "CaptureGate";
    }
    if (isEnemyBaseOperationPhase(assessment.strategicPhase)) {
      return "CaptureBase";
    }
  }

  if (
    state.difficulty === "Hard" &&
    definition.humanBased &&
    hexDistance(unit.coord, state.bases.Player) < hexDistance(unit.coord, state.bases.Enemy) &&
    healthRatio > 0.45 &&
    isPlayerBaseExposedForHardAttack(state)
  ) {
    return "CaptureBase";
  }

  if (assessment.antiAirNeed > 40 && canCounterAir(unit.type)) {
    const highAltitudeThreat = getPlayerIntelForEnemy(state).some((intel) => isHighAltitudeAirUnit(intel.unit.type));
    if (highAltitudeThreat && !canCounterHighAltitudeAir(unit.type)) {
      return isReconUnit(unit.type) ? "Scout" : "Escort";
    }
    return "InterceptAir";
  }

  if (isReconUnit(unit.type) && (assessment.scoutNeed > 45 || assessment.strategyPlan === "ReaperTechRush" || (state.difficulty === "Hard" && (unit.type === "IFV" || unit.type === "Attack Heli") && state.day <= 18))) {
    return "Scout";
  }

  if (unit.type === "Artillery") {
    return "Siege";
  }

  if (isEnemySupplySupportUnit(unit.type)) {
    return "Escort";
  }

  if (needsReconSupport(unit.type)) {
    return "Escort";
  }

  const config = getAiDifficultyConfig(state);
  const gateMissionThreshold =
    state.difficulty === "Hard"
      ? assessment.baseAttackUrgency * (assessment.playerBaseVulnerability > 220 ? 0.9 : 0.62)
      : assessment.baseAttackUrgency * (1 - config.gateCaptureOpportunityMultiplier * 0.55);
  if (definition.humanBased && assessment.gateUrgency > gateMissionThreshold && healthRatio > 0.4) {
    return chooseEnemyGateDefenseObjective(state, unit.coord) ? "DefendGate" : "CaptureGate";
  }

  if (state.difficulty === "Hard" && definition.humanBased && canAssignEnemyBaseSentry(state) && isHardGateAssaultFutile(state)) {
    return "BaseSentry";
  }

  if (definition.humanBased) {
    return "CaptureBase";
  }

  if (unit.type === "Bomber" || unit.type === "Reaper") {
    return assessment.opponentProfile.groundBias > 0.55 ? "HuntArtillery" : "Siege";
  }

  return "Escort";
}

function getEnemyRoleAssignments(state: GameState): Record<string, EnemyMission> {
  const cache = getEnemyEvaluationCache(state);
  if (cache.roleAssignments) {
    return cache.roleAssignments;
  }

  cache.roleAssignments = scaleEnemyStrategicRolesForDifficulty(state, buildHardEnemyRoleAssignments(state));
  return cache.roleAssignments;
}

function usesHardEnemyDoctrine(state: GameState): boolean {
  return state.difficulty === "Hard" || state.difficulty === "Medium" || state.difficulty === "Easy";
}

function scaleEnemyStrategicRolesForDifficulty(
  state: GameState,
  assignments: Record<string, EnemyMission>
): Record<string, EnemyMission> {
  if (state.difficulty === "Hard") {
    return assignments;
  }

  const entries = Object.entries(assignments);
  if (!entries.length) {
    return assignments;
  }

  const config = getAiDifficultyConfig(state);
  const mandatory = entries.filter(([unitId, mission]) => isMandatoryEnemyRoleForDifficulty(state, unitId, mission));
  const optional = entries
    .filter(([unitId, mission]) => !isMandatoryEnemyRoleForDifficulty(state, unitId, mission))
    .sort((first, second) => scoreEnemyRoleRetention(state, second[0], second[1]) - scoreEnemyRoleRetention(state, first[0], first[1]) || first[0].localeCompare(second[0]));
  const optionalLimit = Math.max(0, Math.ceil(optional.length * config.strategicRoleRetention));
  return Object.fromEntries([...mandatory, ...optional.slice(0, optionalLimit)]);
}

function scaleEnemyStrategicRolesInPlaceForDifficulty(state: GameState, assignments: Record<string, EnemyMission>): void {
  if (state.difficulty === "Hard") {
    return;
  }

  const scaled = scaleEnemyStrategicRolesForDifficulty(state, assignments);
  for (const unitId of Object.keys(assignments)) {
    if (!scaled[unitId]) {
      delete assignments[unitId];
    }
  }
  Object.assign(assignments, scaled);
}

function isMandatoryEnemyRoleForDifficulty(state: GameState, unitId: string, mission: EnemyMission): boolean {
  if (mission === "Repair" || mission === "DefendBase" || mission === "ProtectCapturer") {
    return true;
  }

  const unit = getUnitById(state, unitId);
  if (!unit) {
    return false;
  }

  return (
    (mission === "CaptureBase" && state.baseOccupation.Enemy > 0 && getUnitDefinition(unit.type).humanBased) ||
    (mission === "DefendGate" && (state.gates ?? []).some((gate) => gate.owner === "Enemy" && gate.occupation.Player > 0))
  );
}

function scoreEnemyRoleRetention(state: GameState, unitId: string, mission: EnemyMission): number {
  const unit = getUnitById(state, unitId);
  const unitValue = unit ? getUnitInstanceValue(state, unit) : 0;
  const roleScore =
    mission === "CaptureBase" ? 220 :
    mission === "CaptureGate" || mission === "DefendGate" ? 190 :
    mission === "ShadowCapturer" || mission === "EscortCapture" ? 145 :
    mission === "Scout" ? 115 :
    mission === "Siege" ? 105 :
    mission === "Escort" ? 80 :
    60;
  return roleScore + unitValue * 0.2;
}

function buildMediumEnemyRoleAssignments(state: GameState): Record<string, EnemyMission> {
  const assessment = getEnemyStrategicAssessment(state);
  const assignments: Record<string, EnemyMission> = {};
  const gate = (state.gates ?? [])
    .filter((candidate) => candidate.owner !== "Enemy")
    .sort((first, second) => scoreEnemyGateRoleObjective(state, second) - scoreEnemyGateRoleObjective(state, first))[0];

  if (!gate) {
    return assignments;
  }

  const opportunity = assessment.gateCaptureOpportunity[gate.id] ?? 0;
  const worthDetouring = opportunity > 75 || assessment.gateUrgency > assessment.baseAttackUrgency * 0.6;
  if (!worthDetouring || isEnemyBaseCaptureCritical(state)) {
    return assignments;
  }

  const candidate = getOwnerUnits(state, "Enemy")
    .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.45)
    .sort((first, second) => scoreGateRoleCandidate(state, second, gate) - scoreGateRoleCandidate(state, first, gate))[0];

  if (candidate) {
    assignments[candidate.id] = "CaptureGate";
  }

  return assignments;
}

function preserveStableOpeningGateCaptureRoles(
  state: GameState,
  candidates: UnitInstance[],
  assignments: Record<string, EnemyMission>
): void {
  const previous = (state as GameStateWithEnemyCampaign).enemyCampaignPlan;
  if (!usesHardEnemyDoctrine(state) || state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY || !previous) {
    return;
  }

  const objectiveClock = estimateEnemyObjectiveClocks(state, getEnemyPlannerPlayerIntel(state));
  candidates
    .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.4)
    .filter((unit) => isEnemyCampaignAssignedGateStillValid(state, unit, previous.assignedGateByUnitId[unit.id], objectiveClock))
    .forEach((unit) => {
      assignments[unit.id] = isOpeningGateCaptureSupportUnit(unit) ? "ShadowCapturer" : "EscortCapture";
    });
}

function preserveActiveObjectiveClockRoles(
  state: GameState,
  candidates: UnitInstance[],
  assignments: Record<string, EnemyMission>
): void {
  if (!usesHardEnemyDoctrine(state)) {
    return;
  }

  const previous = (state as GameStateWithEnemyCampaign).enemyCampaignPlan;
  const candidatesById = new Map(candidates.map((unit) => [unit.id, unit]));
  const assignObjectiveRole = (unit: UnitInstance | undefined, mission: EnemyMission): void => {
    if (!unit || assignments[unit.id] || shouldEnemyRetreatForRepair(state, unit)) {
      return;
    }
    assignments[unit.id] = mission;
  };

  if (previous) {
    for (const gateId of ["West", "East"] as GateState["id"][]) {
      const gate = (state.gates ?? []).find((candidate) => candidate.id === gateId);
      if (!gate || !shouldPreserveEnemyGateLaneAgainstCombat(state, gate, previous)) {
        continue;
      }
      const lane = previous.laneTaskForces[gateId];
      for (const unitId of [lane.backupCapturerId, ...lane.escortIds, ...lane.supportIds]) {
        const unit = unitId ? candidatesById.get(unitId) : undefined;
        if (!unit || !isEnemyAssignedGateReachable(state, unit, gate)) {
          continue;
        }
        if (getUnitDefinition(unit.type).humanBased) {
          assignObjectiveRole(unit, unit.id === lane.backupCapturerId ? "ShadowCapturer" : "EscortCapture");
        } else {
          assignObjectiveRole(unit, "Escort");
        }
      }
    }

    if (shouldPreserveEnemyBasePackageAgainstCombat(state, previous)) {
      const packagePlan = previous.baseAssaultPackage;
      for (const unitId of packagePlan.blockerEscortIds) {
        assignObjectiveRole(candidatesById.get(unitId), state.baseOccupation.Player > 0 ? "ProtectCapturer" : "Escort");
      }
      for (const unitId of packagePlan.damageDealerIds) {
        const unit = candidatesById.get(unitId);
        if (unit) {
          assignObjectiveRole(unit, getUnitDefinition(unit.type).humanBased ? "Escort" : "Siege");
        }
      }
      assignObjectiveRole(packagePlan.scoutId ? candidatesById.get(packagePlan.scoutId) : undefined, "Scout");
    }
  }

  for (const gate of state.gates ?? []) {
    if (gate.owner === "Enemy" || gate.occupation.Enemy <= 0) {
      continue;
    }
    candidates
      .filter((unit) => !assignments[unit.id])
      .filter((unit) => !getUnitDefinition(unit.type).humanBased)
      .filter((unit) => isOpeningGateSupportUnit(unit.type) || unit.type === "Artillery" || unit.type === "Anti-Air")
      .filter((unit) => isEnemyAssignedGateReachable(state, unit, gate))
      .sort((first, second) => hexDistance(first.coord, gate.coord) - hexDistance(second.coord, gate.coord) || getUnitInstanceValue(state, second) - getUnitInstanceValue(state, first))
      .slice(0, 2)
      .forEach((unit) => assignObjectiveRole(unit, "Escort"));
  }
}

function assignOneGateFollowThroughCapturer(
  state: GameState,
  candidates: UnitInstance[],
  assignments: Record<string, EnemyMission>
): void {
  if (!usesHardEnemyDoctrine(state) || ownerControlsBothGates(state, "Enemy")) {
    return;
  }
  const gates = state.gates ?? [];
  if (gates.filter((gate) => gate.owner === "Enemy").length !== 1) {
    return;
  }
  const targetGate = gates
    .filter((gate) => gate.owner !== "Enemy")
    .sort((first, second) => scoreEnemyGateRoleObjective(state, second) - scoreEnemyGateRoleObjective(state, first) || first.id.localeCompare(second.id))[0];
  if (!targetGate) {
    return;
  }
  const candidate = candidates
    .filter((unit) => !assignments[unit.id])
    .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.4)
    .filter((unit) => isEnemyAssignedGateReachable(state, unit, targetGate))
    .sort((first, second) => {
      const firstDistance = hexDistance(first.coord, targetGate.coord);
      const secondDistance = hexDistance(second.coord, targetGate.coord);
      return firstDistance - secondDistance || scoreGateRoleCandidate(state, second, targetGate) - scoreGateRoleCandidate(state, first, targetGate) || first.id.localeCompare(second.id);
    })[0];
  if (candidate) {
    assignments[candidate.id] = "CaptureGate";
  }
}

function shouldPreserveEnemyGateLaneAgainstCombat(
  state: GameState,
  gate: GateState,
  campaignPlan: EnemyCampaignPlan
): boolean {
  const lane = campaignPlan.laneTaskForces[gate.id];
  const principal = lane.principalCapturerId ? getUnitById(state, lane.principalCapturerId) : undefined;
  const laneHasActiveCapturer =
    Boolean(principal && principal.health > 0 && getUnitDefinition(principal.type).humanBased && hexDistance(principal.coord, gate.coord) <= 3);
  if (gate.owner === "Enemy") {
    return gate.occupation.Player > 0 || campaignPlan.phase === "OneGateOwned";
  }
  return (
    gate.occupation.Enemy > 0 ||
    (laneHasActiveCapturer && isEnemyGateContinuityPhase(campaignPlan.phase))
  );
}

function shouldPreserveEnemyBasePackageAgainstCombat(state: GameState, campaignPlan: EnemyCampaignPlan): boolean {
  return (
    ownerControlsBothGates(state, "Enemy") ||
    state.baseOccupation.Player > 0 ||
    campaignPlan.phase === "BothGatesOwned" ||
    campaignPlan.phase === "BaseAssault" ||
    campaignPlan.phase === "BaseHold"
  );
}

function buildHardEnemyRoleAssignments(state: GameState): Record<string, EnemyMission> {
  const assignments: Record<string, EnemyMission> = {};
  const assessment = getEnemyStrategicAssessment(state);
  const units = getOwnerUnits(state, "Enemy").filter((unit) => unit.health > 0);
  const unassigned = (): UnitInstance[] => units.filter((unit) => !assignments[unit.id]);
  const assign = (unit: UnitInstance | undefined, mission: EnemyMission): void => {
    if (unit) {
      assignments[unit.id] = mission;
    }
  };

  const baseThreat = getEnemyBaseThreat(state);
  const activeBaseThreat = isActiveEnemyBaseThreat(state, baseThreat);
  const defenseResponderLimit = getEnemyDefenseResponderLimit(state, assessment);
  if (activeBaseThreat && baseThreat) {
    unassigned()
      .filter((unit) => canUnitTargetUnit(unit.type, baseThreat.type))
      .sort((first, second) => scoreBaseDefenseCandidate(state, second, baseThreat.coord) - scoreBaseDefenseCandidate(state, first, baseThreat.coord))
      .slice(0, Math.min(defenseResponderLimit, assessment.baseDefenseUrgency > 260 ? 4 : 2))
      .forEach((unit) => assign(unit, "DefendBase"));
  }

  unassigned()
    .filter((unit) => shouldEnemyRetreatForRepair(state, unit))
    .forEach((unit) => assign(unit, "Repair"));

  if (ownerControlsBothGates(state, "Enemy") && !isHardGateAssaultFutile(state) && (isPlayerBaseExposedForHardAttack(state) || (assessment.playerBaseVulnerability > 150 && assessment.baseAttackUrgency > assessment.gateUrgency * 1.15))) {
    unassigned()
      .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.45)
      .sort((first, second) => scoreBaseAttackCandidate(state, second) - scoreBaseAttackCandidate(state, first))
      .slice(0, 4)
      .forEach((unit) => assign(unit, "CaptureBase"));
  }

  assignBestPatrolScout(state, assignments, "West");
  assignBestPatrolScout(state, assignments, "East");

  const gatePressure = assessment.gateUrgency > 60 || assessment.gateLockoutLeverage > 70 || state.day <= 16;
  if (gatePressure) {
    for (const gate of [...(state.gates ?? [])].sort((first, second) => scoreEnemyGateRoleObjective(state, second) - scoreEnemyGateRoleObjective(state, first))) {
      if (!shouldAssignHardGateRole(state, gate)) {
        continue;
      }

      const mission: EnemyMission = gate.owner === "Enemy" ? "DefendGate" : "CaptureGate";
      const candidate = unassigned()
        .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.4)
        .sort((first, second) => scoreGateRoleCandidate(state, second, gate) - scoreGateRoleCandidate(state, first, gate))[0];
      assign(candidate, mission);
      assignEnemyGatePacketRoles(state, assessment, gate, units, assignments);
    }
  }

  assignEnemyBaseSentryGroup(state, assessment, unassigned, assign, activeBaseThreat, baseThreat, false, Object.values(assignments).filter(isEnemyBaseDefenseResponderMission).length);

  if (ownerControlsBothGates(state, "Enemy") && !isHardGateAssaultFutile(state)) {
    const desiredBaseCapturers = assessment.playerBaseVulnerability > 250 ? 5 : assessment.playerBaseVulnerability > 150 ? 4 : assessment.phase === "early" ? 2 : 3;
    unassigned()
      .filter((unit) => getUnitDefinition(unit.type).humanBased && unit.health / Math.max(1, unit.maxHealth) > 0.45)
      .sort((first, second) => scoreBaseAttackCandidate(state, second) - scoreBaseAttackCandidate(state, first))
      .slice(0, desiredBaseCapturers)
      .forEach((unit) => assign(unit, "CaptureBase"));
  }

  return assignments;
}

function shouldAssignHardGateRole(state: GameState, gate: GateState): boolean {
  const assessment = getEnemyStrategicAssessment(state);
  if (usesHardEnemyDoctrine(state) && state.day > 10 && getPlayerForwardPressure(state) >= ENEMY_COMBAT_PRESSURE_CRISIS_THRESHOLD) {
    return (gate.owner === "Enemy" && gate.occupation.Player > 0) || gate.owner === "Player" || gate.occupation.Player > 0;
  }

  if (assessment.enemyGateCount === 0 && gate.owner !== "Enemy") {
    const theatre = estimateGateTheatrePressure(state, gate);
    return gate.occupation.Enemy > 0 || state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY || theatre.recaptureFeasible || theatre.enemy.total > theatre.player.total * 0.55;
  }

  if (gate.owner === "Enemy") {
    return (assessment.predictedGatePressure[gate.id] ?? 0) > 45 || gate.occupation.Player > 0 || assessment.gateLockoutLeverage > 130 || (state.day <= 18 && gate.occupation.Enemy > 0);
  }

  const opportunity = assessment.gateCaptureOpportunity[gate.id] ?? 0;
  if (gate.owner === null) {
    return state.day <= 12 || opportunity > 35 || assessment.gateLockoutLeverage > 70;
  }

  const theatre = estimateGateTheatrePressure(state, gate);
  return (
    opportunity > (theatre.recaptureFeasible ? 85 : 145) ||
    (assessment.gateLockoutLeverage > 70 && theatre.enemy.total > theatre.player.total * 0.55) ||
    (state.day <= 12 && opportunity > 25)
  );
}

function assignOpeningGateInfantry(
  state: GameState,
  candidates: UnitInstance[],
  assignments: Record<string, EnemyMission>
): void {
  if (!(state.gates ?? []).some((gate) => gate.owner !== "Enemy")) {
    return;
  }

  const previous = (state as GameStateWithEnemyCampaign).enemyCampaignPlan;
  const objectiveClock = previous && usesHardEnemyDoctrine(state) && state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY
    ? estimateEnemyObjectiveClocks(state, getEnemyPlannerPlayerIntel(state))
    : undefined;
  const assignedOpeningGate = (unit: UnitInstance): GateState | undefined => {
    const gateId = previous?.assignedGateByUnitId[unit.id];
    if (!gateId || !objectiveClock || !isEnemyCampaignAssignedGateStillValid(state, unit, gateId, objectiveClock)) {
      return undefined;
    }
    return (state.gates ?? []).find((gate) => gate.id === gateId);
  };

  candidates
    .filter((unit) => isOpeningGateCaptureSupportUnit(unit))
    .sort((first, second) => {
      const firstGate = assignedOpeningGate(first) ?? chooseEnemyGateRoleTarget(state, "CaptureGate") ?? chooseGateObjective(state, "Enemy", first.coord);
      const secondGate = assignedOpeningGate(second) ?? chooseEnemyGateRoleTarget(state, "CaptureGate") ?? chooseGateObjective(state, "Enemy", second.coord);
      const firstDistance = firstGate ? hexDistance(first.coord, firstGate.coord) : 0;
      const secondDistance = secondGate ? hexDistance(second.coord, secondGate.coord) : 0;
      return firstDistance - secondDistance || first.id.localeCompare(second.id);
    })
    .forEach((unit) => {
      assignments[unit.id] = "CaptureGate";
    });
}

function assignOpeningGateSupport(
  state: GameState,
  candidates: UnitInstance[],
  assignments: Record<string, EnemyMission>
): void {
  if (state.difficulty !== "Hard" || state.day > 16 || !(state.gates ?? []).some((gate) => gate.owner !== "Enemy")) {
    return;
  }

  const activeGatePressure = hasActivePlayerGatePressure(state);
  const openingRace = state.day <= 10 && (state.gates ?? []).some((gate) => gate.owner === null);
  const missingPatrolLaneCount = state.day <= 8
    ? (["West", "East"] as GateState["id"][]).filter((lane) => !assignmentsHasPatrolLane(assignments, lane)).length
    : 0;
  const reservedPatrolCandidateIds = new Set(
    candidates
      .filter((unit) => isPatrolCapableUnit(unit.type) && unit.health / Math.max(1, unit.maxHealth) > 0.45)
      .sort((first, second) => {
        const firstRecon = isReconUnit(first.type) ? 120 : 0;
        const secondRecon = isReconUnit(second.type) ? 120 : 0;
        const firstSpeed = getEffectiveUnitStats(state, first.owner, first.type, first.level, first.coord).moveRange;
        const secondSpeed = getEffectiveUnitStats(state, second.owner, second.type, second.level, second.coord).moveRange;
        return secondRecon - firstRecon || secondSpeed - firstSpeed || first.id.localeCompare(second.id);
      })
      .slice(0, missingPatrolLaneCount)
      .map((unit) => unit.id)
  );
  const armorCandidates = candidates
    .filter((unit) => isOpeningArmorSupportUnit(unit.type) && unit.health / Math.max(1, unit.maxHealth) > 0.4)
    .filter((unit) => !(openingRace && reservedPatrolCandidateIds.has(unit.id)));
  const assessment = getEnemyStrategicAssessment(state);
  const packetSupportTarget = Math.max(
    1,
    ...(state.gates ?? [])
      .filter((gate) => gate.owner !== "Enemy")
      .map((gate) => getEnemyGatePacketTargetSize(state, assessment, gate) - 1)
  );
  const desiredSupport = state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY
    ? Math.min(armorCandidates.length, packetSupportTarget)
    : Math.max(openingRace || activeGatePressure ? 2 : 1, Math.min(packetSupportTarget, 3));
  armorCandidates
    .sort((first, second) => scoreOpeningGateSupportCandidate(state, second) - scoreOpeningGateSupportCandidate(state, first) || first.id.localeCompare(second.id))
    .slice(0, desiredSupport)
    .forEach((unit) => {
      assignments[unit.id] = "Escort";
    });
}

function applyOpeningDoctrineRoleAssignments(state: GameState, assignments: Record<string, EnemyMission>): void {
  if (!isHardOpeningDoctrineActive(state)) {
    return;
  }

  const patrolMissionForGate = (gateId: GateState["id"]): EnemyMission => gateId === "West" ? "PatrolWest" : "PatrolEast";
  const assignIfAvailable = (unit: UnitInstance, mission: EnemyMission): void => {
    if (assignments[unit.id] === "Repair" || assignments[unit.id] === "DefendBase" || assignments[unit.id] === "BaseSentry" || isEnemyGateLockoutCombatMission(assignments[unit.id])) {
      return;
    }
    assignments[unit.id] = mission;
  };

  getOwnerUnits(state, "Enemy")
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .forEach((unit) => {
      if (unit.type === "Tank") {
        assignIfAvailable(unit, "Escort");
      } else if (unit.type === "IFV") {
        const gateId = getOpeningDoctrineUnitSideGateId(state, unit);
        const sameSideIfvs = getOwnerUnits(state, "Enemy")
          .filter((candidate) => candidate.type === "IFV" && candidate.id.localeCompare(unit.id) < 0)
          .filter((candidate) => getOpeningDoctrineUnitSideGateId(state, candidate) === gateId)
          .length;
        assignIfAvailable(unit, sameSideIfvs === 0 ? patrolMissionForGate(gateId) : "Scout");
      } else if (unit.type === "Attack Heli") {
        assignIfAvailable(unit, patrolMissionForGate(getOpeningDoctrineUnitSideGateId(state, unit)));
      } else if (unit.type === "Artillery" || unit.type === "Anti-Air" || isEnemySupplySupportUnit(unit.type)) {
        assignIfAvailable(unit, isEnemySupplySupportUnit(unit.type) ? "Escort" : "Siege");
      }
    });
}

function applyOpeningDoctrineGateAssignments(
  state: GameState,
  rolesByUnitId: Record<string, EnemyMission>,
  assignedGateByUnitId: Record<string, GateState["id"]>
): void {
  if (!isHardOpeningDoctrineActive(state)) {
    return;
  }

  const gates = state.gates ?? [];
  const assign = (unit: UnitInstance | undefined, gateId: GateState["id"]): void => {
    if (!unit || rolesByUnitId[unit.id] === "Repair" || rolesByUnitId[unit.id] === "DefendBase" || rolesByUnitId[unit.id] === "BaseSentry" || isEnemyGateLockoutCombatMission(rolesByUnitId[unit.id])) {
      return;
    }
    if (!gates.some((gate) => gate.id === gateId && gate.owner !== "Enemy")) {
      return;
    }
    assignedGateByUnitId[unit.id] = gateId;
  };
  const healthy = getOwnerUnits(state, "Enemy").filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35);
  const byLaneDistance = (gateId: GateState["id"]) => (first: UnitInstance, second: UnitInstance): number => {
    const gate = gates.find((candidate) => candidate.id === gateId);
    if (!gate) {
      return first.id.localeCompare(second.id);
    }
    return hexDistance(first.coord, gate.coord) - hexDistance(second.coord, gate.coord) || first.id.localeCompare(second.id);
  };

  healthy
    .filter((unit) => unit.type === "Infantry")
    .forEach((unit) => assign(unit, getOpeningDoctrineUnitSideGateId(state, unit)));

  const tanks = healthy.filter((unit) => unit.type === "Tank");
  const westTank = [...tanks].sort(byLaneDistance("West"))[0];
  assign(westTank, "West");
  tanks
    .filter((unit) => unit.id !== westTank?.id)
    .sort(byLaneDistance("East"))
    .slice(0, 1)
    .forEach((unit) => assign(unit, "East"));

  healthy
    .filter((unit) => unit.type === "IFV" || unit.type === "Attack Heli")
    .forEach((unit) => assign(unit, getOpeningDoctrineUnitSideGateId(state, unit)));
}

function getOpeningDoctrineUnitSideGateId(state: GameState, unit: UnitInstance): GateState["id"] {
  const west = (state.gates ?? []).find((gate) => gate.id === "West");
  const east = (state.gates ?? []).find((gate) => gate.id === "East");
  if (!west || !east) {
    return unit.coord.q <= state.bases.Enemy.q ? "West" : "East";
  }
  const westDistance = Math.abs(unit.coord.q - getOpeningGateTopLaneQ(state, west));
  const eastDistance = Math.abs(unit.coord.q - getOpeningGateTopLaneQ(state, east));
  return westDistance <= eastDistance ? "West" : "East";
}

function scoreOpeningGateSupportCandidate(state: GameState, unit: UnitInstance): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord);
  const targetGate = chooseGateObjective(state, "Enemy", unit.coord);
  const distance = targetGate ? hexDistance(unit.coord, targetGate.coord) : hexDistance(unit.coord, state.bases.Player);
  const armorTempo = unit.type === "Tank" ? 90 : unit.type === "IFV" ? 64 : unit.type === "Attack Heli" ? 52 : 0;
  return getUnitInstanceValue(state, unit) * 0.32 + stats.moveRange * 14 + armorTempo - distance * 8;
}

function getEnemyGatePacketTargetSize(state: GameState, assessment: EnemyStrategicAssessment, gate: GateState): number {
  let size = 2;
  const playerGatePressureHigh =
    gate.owner === "Player" ||
    gate.occupation.Player > 0 ||
    gate.occupation.Enemy > 0 ||
    (assessment.predictedGatePressure[gate.id] ?? 0) >= 120 ||
    getKnownPlayerUnitsForEnemy(state).some((unit) => getUnitDefinition(unit.type).humanBased && hexDistance(unit.coord, gate.coord) <= 3);
  const behindOnGates = assessment.playerGateCount > assessment.enemyGateCount;

  if (assessment.initiativePressure >= 80) {
    size += 1;
  }
  if (assessment.initiativePressure >= 150 || playerGatePressureHigh || behindOnGates) {
    size += 1;
  }

  return Math.min(4, size);
}

function shouldEnemyGatePacketUseBackup(state: GameState, assessment: EnemyStrategicAssessment, gate: GateState): boolean {
  const contested = gate.occupation.Player > 0 || gate.occupation.Enemy > 0 || gate.owner === "Player";
  return contested || assessment.playerGateCount > assessment.enemyGateCount || assessment.initiativePressure >= 150;
}

function assignEnemyGatePacketRoles(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  gate: GateState,
  units: UnitInstance[],
  assignments: Record<string, EnemyMission>
): void {
  const principalMission: EnemyMission = gate.owner === "Enemy" ? "DefendGate" : "CaptureGate";
  const hasPrincipal = units.some((unit) => assignments[unit.id] === principalMission && getUnitDefinition(unit.type).humanBased && isEnemyAssignedGateReachable(state, unit, gate));
  if (!hasPrincipal) {
    return;
  }

  const targetSize = getEnemyGatePacketTargetSize(state, assessment, gate);
  let assigned = 1;
  const available = (): UnitInstance[] => units
    .filter((unit) => !assignments[unit.id])
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => isEnemyAssignedGateReachable(state, unit, gate));
  const assignBest = (candidates: UnitInstance[], mission: EnemyMission | ((unit: UnitInstance) => EnemyMission)): boolean => {
    if (assigned >= targetSize) {
      return false;
    }
    const unit = candidates
      .sort((first, second) => scoreEnemyGatePacketSupportCandidate(state, second, gate) - scoreEnemyGatePacketSupportCandidate(state, first, gate) || first.id.localeCompare(second.id))[0];
    if (!unit) {
      return false;
    }
    assignments[unit.id] = typeof mission === "function" ? mission(unit) : mission;
    assigned += 1;
    return true;
  };

  assignBest(available().filter((unit) => isEnemyGatePacketCombatSupportUnit(unit.type)), "Escort");
  assignBest(
    available().filter((unit) => isEnemyGatePacketFireSupportUnit(unit.type) || (isReconUnit(unit.type) && !getUnitDefinition(unit.type).humanBased)),
    (unit) => isEnemyGatePacketFireSupportUnit(unit.type) ? "Siege" : "Scout"
  );
  if (shouldEnemyGatePacketUseBackup(state, assessment, gate)) {
    assignBest(available().filter((unit) => getUnitDefinition(unit.type).humanBased), gate.owner === "Enemy" ? "DefendGate" : "EscortCapture");
  }
  while (assigned < targetSize) {
    if (
      !assignBest(
        available().filter((unit) => isEnemyGatePacketCombatSupportUnit(unit.type) || isEnemyGatePacketFireSupportUnit(unit.type) || isReconUnit(unit.type)),
        (unit) => isEnemyGatePacketFireSupportUnit(unit.type) ? "Siege" : isReconUnit(unit.type) && !isEnemyGatePacketCombatSupportUnit(unit.type) ? "Scout" : "Escort"
      )
    ) {
      break;
    }
  }
}

function isEnemyGatePacketCombatSupportUnit(unitType: UnitType): boolean {
  return unitType === "Tank" || unitType === "IFV" || unitType === "Reaper" || unitType === "Attack Heli";
}

function isEnemyGatePacketFireSupportUnit(unitType: UnitType): boolean {
  return unitType === "Artillery" || unitType === "Anti-Air";
}

function scoreEnemyGatePacketSupportCandidate(state: GameState, unit: UnitInstance, gate: GateState): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
  const combat = isEnemyGatePacketCombatSupportUnit(unit.type) ? 120 : 0;
  const fireSupport = isEnemyGatePacketFireSupportUnit(unit.type) ? 95 : 0;
  const scout = isReconUnit(unit.type) ? 70 : 0;
  const capturer = getUnitDefinition(unit.type).humanBased ? 48 : 0;
  return getUnitInstanceValue(state, unit) * 0.32 + unit.health * 1.4 + stats.moveRange * 10 + stats.attackRange * 8 + combat + fireSupport + scout + capturer - hexDistance(unit.coord, gate.coord) * 12;
}

function hasActivePlayerGatePressure(state: GameState): boolean {
  return (state.gates ?? []).some(
    (gate) =>
      gate.owner === "Player" ||
      gate.occupation.Player > 0 ||
      getKnownPlayerUnitsForEnemy(state).some((unit) => getUnitDefinition(unit.type).humanBased && hexDistance(unit.coord, gate.coord) <= 4)
  );
}

function isHardGateAssaultFutile(state: GameState): boolean {
  if (!usesHardEnemyDoctrine(state) || getEnemyGateDisadvantage(state) < 2) {
    return false;
  }

  const assessment = getEnemyStrategicAssessment(state);
  if (assessment.enemyGateCount === 0) {
    return false;
  }

  const gatePressure = (assessment.predictedGatePressure.West ?? 0) + (assessment.predictedGatePressure.East ?? 0);
  const localKnownPressure = (state.gates ?? []).reduce(
    (total, gate) => total + getKnownPlayerUnitsForEnemy(state).filter((unit) => hexDistance(unit.coord, gate.coord) <= 7).length * 55,
    0
  );
  const gateOpportunity = Math.max(assessment.gateCaptureOpportunity.West ?? 0, assessment.gateCaptureOpportunity.East ?? 0);
  return gatePressure + localKnownPressure > 260 && gateOpportunity < 120;
}

function assignEnemyCombatResponseRoles(
  state: GameState,
  units: UnitInstance[],
  assignments: Record<string, EnemyMission>,
  combatPressure: number
): void {
  const visiblePlayerAir = getPlayerIntelForEnemy(state).some((intel) => getUnitDefinition(intel.unit.type).domain === "Air");
  const assign = (unit: UnitInstance, mission: EnemyMission): void => {
    const existing = assignments[unit.id];
    if (existing && isProtectedEnemyObjectiveRole(existing) && !canOverrideProtectedEnemyObjectiveRoleForCombat(state, unit, existing)) {
      return;
    }
    if (!existing || isGenericEnemyCombatRole(existing)) {
      assignments[unit.id] = mission;
    }
  };

  const candidates = units
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => !shouldEnemyGateLockoutPreserveDamagedCombatPower(state, unit))
    .filter((unit) => !shouldPreserveAssignedEnemyObjectiveRoleAgainstCombat(state, unit, assignments[unit.id]))
    .filter((unit) => !getUnitDefinition(unit.type).humanBased)
    .filter((unit) => isHardCombatProductionUnit(unit.type) || isSpecialUnit(unit.type))
    .sort((first, second) => scoreEnemyCombatResponseCandidate(state, second, combatPressure) - scoreEnemyCombatResponseCandidate(state, first, combatPressure));

  for (const unit of candidates) {
    if (visiblePlayerAir && canCounterAir(unit.type)) {
      assign(unit, "InterceptAir");
      continue;
    }
    if (unit.type === "Artillery" || unit.type === "Tank" || unit.type === "Bomber" || unit.type === "Reaper") {
      assign(unit, "HuntArtillery");
      continue;
    }
    if (unit.type === "Anti-Air") {
      assign(unit, visiblePlayerAir ? "InterceptAir" : "Siege");
      continue;
    }
    assign(unit, "Escort");
  }
}

function assignEnemyGateLockoutCombatRoles(
  state: GameState,
  units: UnitInstance[],
  assignments: Record<string, EnemyMission>
): void {
  const gate = chooseEnemyGateLockoutCounterattackGate(state);
  if (!gate) {
    return;
  }

  const canReassign = (unit: UnitInstance): boolean => {
    const existing = assignments[unit.id];
    return (
      !existing ||
      existing === "CaptureGate" ||
      existing === "ShadowCapturer" ||
      existing === "EscortCapture" ||
      existing === "Escort" ||
      existing === "Siege" ||
      (existing === "BaseSentry" && unit.type === "Tank") ||
      (existing === "DefendGate" && !getUnitDefinition(unit.type).humanBased) ||
      existing === "HuntArtillery" ||
      existing === "InterceptAir" ||
      isEnemyGateLockoutCombatMission(existing)
    );
  };
  const assign = (unit: UnitInstance, mission: EnemyMission): void => {
    if (canReassign(unit)) {
      assignments[unit.id] = mission;
    }
  };

  const reconScout = chooseEnemyGateLockoutReconScout(state, units, gate, assignments);
  if (reconScout) {
    assignments[reconScout.id] = "Scout";
  }

  const combatUnits = units
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => isEnemyGateLockoutCombatUnit(unit.type))
    .filter((unit) => !shouldEnemyGateLockoutPreserveDamagedCombatPower(state, unit))
    .filter(canReassign)
    .sort((first, second) => scoreEnemyGateLockoutCombatRoleCandidate(state, second, gate) - scoreEnemyGateLockoutCombatRoleCandidate(state, first, gate) || first.id.localeCompare(second.id));

  let coverAssigned = combatUnits.some((unit) => assignments[unit.id] === "CoverCounterattack");
  for (const unit of combatUnits) {
    if (unit.type === "Anti-Air") {
      assign(unit, "CoverCounterattack");
      coverAssigned = true;
      continue;
    }
    if (!coverAssigned && (unit.type === "IFV" || unit.type === "Tank" || unit.type === "Reaper" || unit.type === "Bomber")) {
      assign(unit, "CoverCounterattack");
      coverAssigned = true;
      continue;
    }
    if (unit.type === "Artillery" || unit.type === "Reaper" || unit.type === "Bomber") {
      assign(unit, "SuppressGateZone");
      continue;
    }
    assign(unit, "ClearGateApproach");
  }

  units
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.4)
    .filter((unit) => isEnemyGateLockoutReserveCapturer(unit.type))
    .filter(canReassign)
    .sort((first, second) => scoreGateRoleCandidate(state, second, gate) - scoreGateRoleCandidate(state, first, gate) || first.id.localeCompare(second.id))
    .forEach((unit) => assign(unit, "ReserveCapturer"));
}

function assignEnemyPreBaseEmergencySentryLine(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  units: UnitInstance[],
  assignments: Record<string, EnemyMission>
): void {
  if (!canAssignEnemyBaseSentry(state) || assessment.strategicPhase !== "GateLockoutCombat" || getEnemyPreBaseEmergencyThreats(state).length <= 0) {
    return;
  }

  const targetCount = getEnemyBaseSentryTargetCount(state, assessment, false, undefined, false);
  const currentCount = Object.values(assignments).filter(isEnemyBaseDefenseResponderMission).length;
  if (currentCount >= targetCount) {
    return;
  }

  units
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => isGoodBaseSentryUnit(unit.type))
    .filter((unit) => hexDistance(unit.coord, state.bases.Enemy) <= getEnemyBaseResponseRadius(state) + 3)
    .filter((unit) => assignments[unit.id] !== "Repair" && assignments[unit.id] !== "DefendBase")
    .sort((first, second) => scoreBaseSentryCandidate(state, second) - scoreBaseSentryCandidate(state, first) || first.id.localeCompare(second.id))
    .slice(0, Math.max(0, targetCount - currentCount))
    .forEach((unit) => {
      assignments[unit.id] = "BaseSentry";
    });
}

function chooseEnemyGateLockoutReconScout(
  state: GameState,
  units: UnitInstance[],
  gate: GateState,
  assignments: Record<string, EnemyMission>
): UnitInstance | undefined {
  return units
    .filter((unit) => unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .filter((unit) => isEnemyGateLockoutReconUnit(unit.type))
    .filter((unit) => {
      const existing = assignments[unit.id];
      return (
        !existing ||
        existing === "Scout" ||
        existing === "PatrolWest" ||
        existing === "PatrolEast" ||
        existing === "Escort" ||
        existing === "Siege" ||
        existing === "HuntArtillery" ||
        existing === "InterceptAir" ||
        existing === "ClearGateApproach" ||
        existing === "SuppressGateZone" ||
        existing === "CoverCounterattack"
      );
    })
    .sort((first, second) => scoreEnemyGateLockoutReconCandidate(state, second, gate) - scoreEnemyGateLockoutReconCandidate(state, first, gate) || first.id.localeCompare(second.id))[0];
}

function isEnemyGateLockoutReconUnit(unitType: UnitType): boolean {
  return isReconUnit(unitType) || unitType === "IFV" || unitType === "Ghost" || unitType === "Operator" || unitType === "Reaper";
}

function scoreEnemyGateLockoutReconCandidate(state: GameState, unit: UnitInstance, gate: GateState): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
  const distance = hexDistance(unit.coord, gate.coord);
  const typeBonus =
    unit.type === "Attack Heli" ? 120 :
      unit.type === "IFV" ? 105 :
        unit.type === "Ghost" ? 96 :
          unit.type === "Reaper" ? 82 :
            unit.type === "Jet" ? 72 :
              unit.type === "Bomber" ? 58 :
                unit.type === "Operator" ? 48 :
                  0;
  return stats.visibilityRange * 34 + stats.moveRange * 18 + getUnitInstanceValue(state, unit) * 0.18 + typeBonus - distance * 9;
}

function isEnemyGateLockoutCombatMission(role: EnemyMission | undefined): boolean {
  return role === "ClearGateApproach" || role === "SuppressGateZone" || role === "CoverCounterattack" || role === "ReserveCapturer";
}

function isEnemyGateLockoutClearingMission(role: EnemyMission | undefined): boolean {
  return role === "ClearGateApproach" || role === "SuppressGateZone" || role === "CoverCounterattack";
}

function isEnemyGateLockoutCombatUnit(unitType: UnitType): boolean {
  return (
    unitType === "Tank" ||
    unitType === "IFV" ||
    unitType === "Artillery" ||
    unitType === "Reaper" ||
    unitType === "Jet" ||
    unitType === "Bomber" ||
    unitType === "Ghost" ||
    unitType === "Operator" ||
    unitType === "Anti-Air"
  );
}

function isEnemyGateLockoutReserveCapturer(unitType: UnitType): boolean {
  return getUnitDefinition(unitType).humanBased && unitType !== "Ghost" && unitType !== "Operator";
}

function scoreEnemyGateLockoutCombatRoleCandidate(state: GameState, unit: UnitInstance, gate: GateState): number {
  const value = getUnitInstanceValue(state, unit);
  const distance = hexDistance(unit.coord, gate.coord);
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
  const typeBonus =
    unit.type === "Tank" ? 90 :
      unit.type === "IFV" ? 76 :
        unit.type === "Artillery" ? 84 :
          unit.type === "Reaper" ? 82 :
            unit.type === "Jet" ? 74 :
              unit.type === "Bomber" ? 78 :
                unit.type === "Anti-Air" ? 68 :
                  unit.type === "Ghost" ? 72 :
                    unit.type === "Operator" ? 64 :
                      0;
  return value * 0.72 + unit.health * 2 + stats.attackRange * 18 + stats.moveRange * 12 + typeBonus - distance * 10;
}

function isProtectedEnemyObjectiveRole(role: EnemyMission | undefined): boolean {
  return role === "CaptureGate" || role === "CaptureBase" || role === "DefendGate" || role === "ProtectCapturer" || role === "ShadowCapturer" || role === "EscortCapture";
}

function isGenericEnemyCombatRole(role: EnemyMission | undefined): boolean {
  return role === "InterceptAir" || role === "HuntArtillery" || role === "Siege" || role === "Escort";
}

function shouldPreserveAssignedEnemyObjectiveRoleAgainstCombat(state: GameState, unit: UnitInstance, role: EnemyMission | undefined): boolean {
  return isProtectedEnemyObjectiveRole(role) && !canOverrideProtectedEnemyObjectiveRoleForCombat(state, unit, role);
}

function canOverrideProtectedEnemyObjectiveRoleForCombat(state: GameState, unit: UnitInstance, role: EnemyMission | undefined): boolean {
  if (shouldEnemyRetreatForRepair(state, unit)) {
    return true;
  }
  if (isEnemyImmediateObjectiveDenialNeeded(state, unit)) {
    return true;
  }
  return isEnemyObjectiveRolePathImpossible(state, unit, role);
}

function isEnemyImmediateObjectiveDenialNeeded(state: GameState, unit: UnitInstance): boolean {
  const baseThreat = getEnemyBaseThreat(state);
  if (baseThreat && isActiveEnemyBaseThreat(state, baseThreat) && canUnitTargetUnit(unit.type, baseThreat.type)) {
    return true;
  }
  if (state.baseOccupation.Enemy >= BASE_CAPTURE_DAYS - 1) {
    return canUnitTargetUnit(unit.type, "Infantry") || canUnitTargetUnit(unit.type, "Ghost") || canUnitTargetUnit(unit.type, "Operator");
  }
  return (state.gates ?? []).some((gate) => gate.owner === "Enemy" && gate.occupation.Player >= GATE_CAPTURE_DAYS - 1 && isEnemyAssignedGateReachable(state, unit, gate));
}

function isEnemyObjectiveRolePathImpossible(state: GameState, unit: UnitInstance, role: EnemyMission | undefined): boolean {
  if (role === "CaptureGate" || role === "DefendGate" || role === "ShadowCapturer" || role === "EscortCapture") {
    const previous = (state as GameStateWithEnemyCampaign).enemyCampaignPlan;
    const gateId = previous?.assignedGateByUnitId[unit.id];
    const gate = gateId ? (state.gates ?? []).find((candidate) => candidate.id === gateId) : undefined;
    return Boolean(gate && !isEnemyAssignedGateReachable(state, unit, gate));
  }
  if (role === "CaptureBase" || role === "ProtectCapturer") {
    return findMovementPath(state, unit, state.bases.Player) === undefined && hexDistance(unit.coord, state.bases.Player) > getEffectiveRemainingMovementToCoord(state, unit, state.bases.Player) + 2;
  }
  return false;
}

function scoreEnemyCombatResponseCandidate(state: GameState, unit: UnitInstance, combatPressure: number): number {
  const target = chooseEnemyCombatTargetCoord(state, unit);
  const targetScore = target ? Math.max(0, 18 - hexDistance(unit.coord, target)) * 14 : 0;
  const pressureBonus = combatPressure >= ENEMY_COMBAT_PRESSURE_CRISIS_THRESHOLD ? 80 : 0;
  return getUnitInstanceValue(state, unit) * 0.4 + targetScore + pressureBonus - (unit.type === "Infantry" ? 120 : 0);
}

function scoreBaseDefenseCandidate(state: GameState, unit: UnitInstance, threatCoord: UnitInstance["coord"]): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, threatCoord);
  const distance = hexDistance(unit.coord, threatCoord);
  const attackSoon = distance <= stats.attackRange + stats.moveRange ? 70 : 0;
  const infantryPenalty = state.difficulty === "Hard" && unit.type === "Infantry" ? 90 : 0;
  return getUnitInstanceValue(state, unit) * 0.45 + attackSoon - distance * 9 - infantryPenalty;
}

function isGoodBaseSentryUnit(unitType: UnitType): boolean {
  return ["Anti-Air", "IFV", "Tank", "Operator", "Ghost", "Reaper"].includes(unitType);
}

function canAssignEnemyBaseSentry(state: GameState): boolean {
  return ownerControlsBothGates(state, "Player");
}

function enforceEnemyBaseSentryGateRequirement(state: GameState, assignments: Record<string, EnemyMission>): void {
  if (canAssignEnemyBaseSentry(state)) {
    return;
  }

  for (const [unitId, mission] of Object.entries(assignments)) {
    if (mission === "BaseSentry") {
      delete assignments[unitId];
    }
  }
}

function isEnemyBaseDefenseResponderMission(mission: EnemyMission): boolean {
  return mission === "BaseSentry" || mission === "DefendBase";
}

function assignEnemyBaseSentryGroup(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  unassigned: () => UnitInstance[],
  assign: (unit: UnitInstance | undefined, mission: EnemyMission) => void,
  activeBaseThreat: boolean,
  baseThreat: (UnitInstance & { score: number }) | undefined,
  frontLineInterdiction = false,
  currentDefenseResponderCount = 0
): void {
  if (!shouldAssignEnemyBaseSentry(state, assessment, activeBaseThreat, baseThreat)) {
    return;
  }

  const targetCount = getEnemyBaseSentryTargetCount(state, assessment, activeBaseThreat, baseThreat, frontLineInterdiction);
  unassigned()
    .filter((unit) => isGoodBaseSentryUnit(unit.type) && unit.health / Math.max(1, unit.maxHealth) > 0.35)
    .sort((first, second) => scoreBaseSentryCandidate(state, second, baseThreat) - scoreBaseSentryCandidate(state, first, baseThreat) || first.id.localeCompare(second.id))
    .slice(0, Math.max(0, targetCount - currentDefenseResponderCount))
    .forEach((unit) => assign(unit, "BaseSentry"));
}

function getEnemyBaseSentryTargetCount(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  activeBaseThreat: boolean,
  baseThreat: (UnitInstance & { score: number }) | undefined,
  frontLineInterdiction: boolean
): number {
  if (!canAssignEnemyBaseSentry(state)) {
    return 0;
  }

  const limit = getEnemyDefenseResponderLimit(state, assessment);
  if (limit <= 0) {
    return 0;
  }
  if (activeBaseThreat || state.baseOccupation.Enemy > 0 || isPlayerHumanBaseThreatNearEnemyBase(state)) {
    return limit;
  }
  if (assessment.strategicPhase === "GateLockoutCombat" && getEnemyPreBaseEmergencyThreats(state).length > 0) {
    return Math.min(limit, frontLineInterdiction ? 1 : limit);
  }
  if (frontLineInterdiction || baseThreat || assessment.predictedEnemyBasePressure > 160 || isFastSpecialBaseSentryProfile(state, assessment)) {
    return Math.min(limit, 1);
  }
  return 0;
}

function getEnemyDefenseResponderLimit(state: GameState, assessment: EnemyStrategicAssessment): number {
  const playerIntel = getPlayerIntelForEnemy(state);
  const immediateHumanThreat = playerIntel.some(
    (intel) => intel.age <= 2 && getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, state.bases.Enemy) <= 2
  );
  if (state.baseOccupation.Enemy > 0 || immediateHumanThreat) {
    return 3;
  }

  const playerOwnsBothGates = ownerControlsBothGates(state, "Player");
  const nearBaseThreats = playerIntel.filter((intel) => {
    if (intel.age > 3) {
      return false;
    }
    const definition = getUnitDefinition(intel.unit.type);
    const distance = hexDistance(intel.predictedCoord, state.bases.Enemy);
    const responseRange = getEnemyBaseResponseRadius(state) + (definition.humanBased ? 3 : 6);
    return (
      distance <= responseRange ||
      intel.likelyObjective === "EnemyBase" ||
      canUnitProjectThreatToCoord(state, intel.unit, intel.predictedCoord, state.bases.Enemy)
    );
  });

  if (playerOwnsBothGates) {
    if (nearBaseThreats.length >= 2) {
      return 2;
    }
    if (nearBaseThreats.length === 1) {
      return assessment.initiativePressure >= 120 ? 1 : 2;
    }
    if (getEnemyPreBaseEmergencyThreats(state, playerIntel).length > 0 || assessment.predictedEnemyBasePressure > 160 || isFastSpecialBaseSentryProfile(state, assessment)) {
      return 1;
    }
    return 0;
  }

  if (nearBaseThreats.length > 0 || assessment.predictedEnemyBasePressure > 160) {
    return 1;
  }

  return 0;
}

function scoreBaseSentryCandidate(state: GameState, unit: UnitInstance, baseThreat?: (UnitInstance & { score: number })): number {
  const distance = hexDistance(unit.coord, state.bases.Enemy);
  const value = getUnitInstanceValue(state, unit);
  const threats = getEnemyBaseSentryThreats(state, baseThreat);
  const counterScore = threats.reduce((best, threat) => {
    if (!canUnitTargetUnit(unit.type, threat.type)) {
      return best;
    }
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, threat.coord);
    const threatDistance = hexDistance(unit.coord, threat.coord);
    const attackSoon = threatDistance <= stats.attackRange ? 130 : threatDistance <= stats.attackRange + stats.moveRange ? 80 : 0;
    const capturerBonus = getUnitDefinition(threat.type).humanBased ? 120 : 40;
    const supportBonus = canUnitProjectThreatToCoord(state, threat, threat.coord, state.bases.Enemy) ? 60 : 0;
    return Math.max(best, attackSoon + capturerBonus + supportBonus + getUnitInstanceValue(state, threat) * 0.22);
  }, 0);
  const antiCaptureBonus = canUnitTargetUnit(unit.type, "Infantry") || canUnitTargetUnit(unit.type, "Ghost") || canUnitTargetUnit(unit.type, "Operator") ? 42 : 0;
  const antiAirSupportBonus = threats.some((threat) => getUnitDefinition(threat.type).domain === "Air") && canCounterAir(unit.type) ? 95 : 0;
  const baseProximityBonus = Math.max(0, getEnemyBaseResponseRadius(state) + 4 - distance) * 9;
  const infantryMismatchPenalty =
    threats.some((threat) => getUnitDefinition(threat.type).humanBased) && !threats.some((threat) => getUnitDefinition(threat.type).humanBased && canUnitTargetUnit(unit.type, threat.type))
      ? 115
      : 0;
  return value * 0.25 + counterScore + antiCaptureBonus + antiAirSupportBonus + baseProximityBonus - distance * 5 - infantryMismatchPenalty;
}

function getEnemyBaseSentryThreats(state: GameState, baseThreat?: (UnitInstance & { score: number })): UnitInstance[] {
  const threats: UnitInstance[] = [];
  if (baseThreat) {
    threats.push(baseThreat);
  }

  if (ownerControlsBothGates(state, "Player")) {
    for (const threat of getEnemyPreBaseEmergencyThreats(state)) {
      threats.push({ ...threat.unit, coord: { ...threat.coord } });
    }
  }

  for (const intel of getPlayerIntelForEnemy(state)) {
    const definition = getUnitDefinition(intel.unit.type);
    const distance = hexDistance(intel.predictedCoord, state.bases.Enemy);
    const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, intel.predictedCoord, state.bases.Enemy);
    const nearBase = distance <= getEnemyBaseResponseRadius(state) + stats.moveRange * (definition.humanBased ? 2 : 1) + 2;
    const baseIntent = intel.likelyObjective === "EnemyBase";
    const supportThreat = !definition.humanBased && distance <= getEnemyBaseResponseRadius(state) + 8 && canUnitProjectThreatToCoord(state, intel.unit, intel.predictedCoord, state.bases.Enemy);
    if (intel.age <= 3 && (nearBase || baseIntent || supportThreat)) {
      threats.push({ ...intel.unit, coord: { ...intel.predictedCoord } });
    }
  }

  const seen = new Set<string>();
  return threats.filter((threat) => {
    if (seen.has(threat.id)) {
      return false;
    }
    seen.add(threat.id);
    return true;
  });
}

function assignOpeningPatrolScout(state: GameState, assignments: Record<string, EnemyMission>, lane: GateState["id"]): void {
  if (!usesHardEnemyDoctrine(state) || state.day > 8 || assignmentsHasPatrolLane(assignments, lane)) {
    return;
  }
  const gate = (state.gates ?? []).find((candidate) => candidate.id === lane);
  const target = gate?.coord ?? getEnemyPatrolCoord(state, lane);
  const center = state.bases.Enemy.q;
  const mission: EnemyMission = lane === "West" ? "PatrolWest" : "PatrolEast";
  const incumbent = getOwnerUnits(state, "Enemy")
    .filter((unit) => !assignments[unit.id] && isPatrolCapableUnit(unit.type) && unit.health / Math.max(1, unit.maxHealth) > 0.45)
    .filter((unit) => hexDistance(unit.coord, target) <= 7)
    .sort((first, second) => hexDistance(first.coord, target) - hexDistance(second.coord, target) || first.id.localeCompare(second.id))[0];
  if (incumbent) {
    assignments[incumbent.id] = mission;
    return;
  }

  const candidate = getOwnerUnits(state, "Enemy")
    .filter((unit) => !assignments[unit.id] && isPatrolCapableUnit(unit.type) && unit.health / Math.max(1, unit.maxHealth) > 0.45)
    .sort((first, second) => {
      const firstLane = lane === "West" ? center - first.coord.q : first.coord.q - center;
      const secondLane = lane === "West" ? center - second.coord.q : second.coord.q - center;
      const firstFastScout = first.type === "Attack Heli" ? 110 : 0;
      const secondFastScout = second.type === "Attack Heli" ? 110 : 0;
      const firstScore = Math.max(-8, firstLane) * 16 - hexDistance(first.coord, target) * 12 + (hexDistance(first.coord, target) <= 4 ? 160 : 0) + firstFastScout;
      const secondScore = Math.max(-8, secondLane) * 16 - hexDistance(second.coord, target) * 12 + (hexDistance(second.coord, target) <= 4 ? 160 : 0) + secondFastScout;
      return secondScore - firstScore || first.id.localeCompare(second.id);
    })[0];
  if (candidate) {
    assignments[candidate.id] = mission;
  }
}

function assignmentsHasPatrolLane(assignments: Record<string, EnemyMission>, lane: GateState["id"]): boolean {
  const mission: EnemyMission = lane === "West" ? "PatrolWest" : "PatrolEast";
  return Object.values(assignments).includes(mission);
}

function shouldAssignEnemyBaseSentry(
  state: GameState,
  assessment: EnemyStrategicAssessment,
  activeBaseThreat: boolean,
  baseThreat: (UnitInstance & { score: number }) | undefined
): boolean {
  if (!canAssignEnemyBaseSentry(state)) {
    return false;
  }

  if (activeBaseThreat || state.baseOccupation.Enemy > 0 || assessment.predictedEnemyBasePressure > 120) {
    return true;
  }

  if (assessment.strategicPhase === "GateLockoutCombat" && getEnemyPreBaseEmergencyThreats(state).length > 0) {
    return true;
  }

  if (isPlayerHumanBaseThreatNearEnemyBase(state) || isFastSpecialBaseSentryProfile(state, assessment)) {
    return true;
  }

  if (state.difficulty === "Hard" && state.day >= getEarliestPossiblePlayerBaseThreatDay(state)) {
    return true;
  }

  const responseRadius = getEnemyBaseResponseRadius(state);
  return Boolean(baseThreat && hexDistance(baseThreat.coord, state.bases.Enemy) <= responseRadius);
}

function isPlayerHumanBaseThreatNearEnemyBase(state: GameState): boolean {
  const responseRadius = getEnemyBaseResponseRadius(state);
  return getPlayerIntelForEnemy(state).some((intel) => {
    if (!getUnitDefinition(intel.unit.type).humanBased || intel.age > 2) {
      return false;
    }
    const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, intel.predictedCoord);
    return hexDistance(intel.predictedCoord, state.bases.Enemy) <= responseRadius + stats.moveRange * 2;
  });
}

function isFastSpecialBaseSentryProfile(state: GameState, assessment: EnemyStrategicAssessment): boolean {
  if (assessment.opponentProfile.kind !== "FastSpecial" && assessment.opponentProfile.fastSpecial < 0.58) {
    return false;
  }
  return state.day >= 8 && getPlayerIntelForEnemy(state).some((intel) => intel.age <= 3 && isSpecialUnit(intel.unit.type));
}

function getEarliestPossiblePlayerBaseThreatDay(state: GameState): number {
  const plausibleHumanMove = UNIT_DEFINITIONS
    .map((unit) => unit.type)
    .filter((unitType) => getUnitDefinition(unitType).humanBased)
    .filter((unitType) => !getUnitDefinition(unitType).availableTo || getUnitDefinition(unitType).availableTo?.includes("Player"))
    .filter((unitType) => canOwnerProduceUnit(state, "Player", unitType) || getOwnerUnits(state, "Player").some((unit) => unit.type === unitType))
    .reduce((best, unitType) => Math.max(best, getEffectiveUnitStats(state, "Player", unitType, state.economy.unitLevels[unitType]).moveRange), 3);
  return Math.ceil(hexDistance(state.bases.Player, state.bases.Enemy) / Math.max(1, plausibleHumanMove)) + 1;
}

function assignBestPatrolScout(state: GameState, assignments: Record<string, EnemyMission>, lane: GateState["id"]): void {
  if (assignmentsHasPatrolLane(assignments, lane)) {
    return;
  }
  const mission: EnemyMission = lane === "West" ? "PatrolWest" : "PatrolEast";
  const target = getEnemyPatrolCoord(state, lane);
  const candidate = getOwnerUnits(state, "Enemy")
    .filter((unit) => !assignments[unit.id] && isPatrolCapableUnit(unit.type) && unit.health / Math.max(1, unit.maxHealth) > 0.45)
    .sort((first, second) => {
      const center = state.bases.Enemy.q;
      const earlyLaneBias = state.difficulty === "Hard" && state.day <= 8;
      const firstFastScout = first.type === "Attack Heli" ? 120 : 0;
      const secondFastScout = second.type === "Attack Heli" ? 120 : 0;
      const firstLaneScore = earlyLaneBias ? (lane === "West" ? center - first.coord.q : first.coord.q - center) * 8 : 0;
      const secondLaneScore = earlyLaneBias ? (lane === "West" ? center - second.coord.q : second.coord.q - center) * 8 : 0;
      const firstScore = firstFastScout + (isReconUnit(first.type) ? 80 : 0) + getEffectiveUnitStats(state, first.owner, first.type, first.level, first.coord).visibilityRange * 5 - hexDistance(first.coord, target) * 4 + firstLaneScore;
      const secondScore = secondFastScout + (isReconUnit(second.type) ? 80 : 0) + getEffectiveUnitStats(state, second.owner, second.type, second.level, second.coord).visibilityRange * 5 - hexDistance(second.coord, target) * 4 + secondLaneScore;
      return secondScore - firstScore;
    })[0];

  if (candidate) {
    assignments[candidate.id] = mission;
  }
}

function isPatrolCapableUnit(unitType: UnitType): boolean {
  return isReconUnit(unitType) || unitType === "IFV" || unitType === "Operator";
}

function isOpeningGateSupportUnit(unitType: UnitType): boolean {
  return unitType === "Tank" || unitType === "IFV" || unitType === "Attack Heli";
}

function isOpeningArmorSupportUnit(unitType: UnitType): boolean {
  return unitType === "Tank" || unitType === "IFV";
}

function scoreGateRoleCandidate(state: GameState, unit: UnitInstance, gate: GateState): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord);
  const assessment = getEnemyStrategicAssessment(state);
  const config = getAiDifficultyConfig(state);
  const opportunity = assessment.gateCaptureOpportunity[gate.id] ?? 0;
  const pressure = assessment.predictedGatePressure[gate.id] ?? 0;
  const frontLineLeverage = gate.owner !== "Enemy" ? assessment.gateLockoutLeverage * 0.34 : assessment.gateLockoutLeverage * 0.16;
  const gateScore = gate.owner === "Enemy" ? pressure * 0.35 + frontLineLeverage : opportunity * 0.24 * config.gateCaptureOpportunityMultiplier + frontLineLeverage;
  const infantryGatePressureBonus = hasActivePlayerGatePressure(state) || gate.owner === "Player" || gate.occupation.Player > 0 ? 56 : -54;
  const captureUnitBonus = unit.type === "Ghost" ? 130 : unit.type === "Operator" ? 92 : unit.type === "Infantry" ? infantryGatePressureBonus : 0;
  return getUnitInstanceValue(state, unit) * 0.28 + stats.moveRange * 8 + gateScore + captureUnitBonus - hexDistance(unit.coord, gate.coord) * 9;
}

function scoreBaseAttackCandidate(state: GameState, unit: UnitInstance): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord);
  const assessment = getEnemyStrategicAssessment(state);
  const config = getAiDifficultyConfig(state);
  return (
    getUnitInstanceValue(state, unit) * 0.22 +
    stats.moveRange * 10 +
    assessment.playerBaseVulnerability * 0.16 * config.playerBaseVulnerabilityMultiplier -
    (ownerControlsBothGates(state, "Enemy") ? 0 : 96) -
    hexDistance(unit.coord, state.bases.Player) * 4
  );
}

function isPlayerBaseExposedForHardAttack(state: GameState): boolean {
  if (!usesHardEnemyDoctrine(state)) {
    return false;
  }

  const enemyCapturerClose = getOwnerUnits(state, "Enemy").some(
    (unit) => getUnitDefinition(unit.type).humanBased && hexDistance(unit.coord, state.bases.Player) <= 18
  );
  if (!enemyCapturerClose) {
    return false;
  }

  const visibleDefenderForce = getPlayerIntelForEnemy(state).reduce((total, intel) => {
    const distance = hexDistance(intel.predictedCoord, state.bases.Player);
    return total + (distance <= 10 ? getUnitInstanceValue(state, intel.unit) * intel.confidence : 0);
  }, 0);
  return visibleDefenderForce < 70;
}

function shouldEnemyRetreatForRepair(state: GameState, unit: UnitInstance): boolean {
  if (isEnemyRepairCoord(state, unit.coord, unit.type) || unit.health >= unit.maxHealth) {
    return false;
  }

  const healthRatio = unit.health / Math.max(1, unit.maxHealth);
  const value = getUnitInstanceValue(state, unit);
  const danger = estimatePlayerDangerAt(state, unit, unit.coord);
  const highValue = isEnemyHighValueRepairPreservationUnit(unit.type);
  const assessment = getEnemyStrategicAssessment(state);
  const phaseWeights = getEnemyStrategicPhaseWeights(assessment.strategicPhase);
  const humanBased = getUnitDefinition(unit.type).humanBased;
  const critical = healthRatio < 0.24 || danger > unit.health * 1.35;

  if (shouldEnemyGateLockoutPreserveDamagedCombatPower(state, unit)) {
    return true;
  }
  if (
    highValue &&
    healthRatio < 0.75 &&
    getNearestEnemyRepairDistance(state, unit.coord, unit.type) <= getRemainingMovementPoints(state, unit)
  ) {
    return true;
  }

  if (shouldHoldForBaseDefense(state, unit)) {
    const activeBaseOccupant = state.baseOccupation.Enemy > 0 || getOwnerUnits(state, "Player").some((player) => sameHex(player.coord, state.bases.Enemy));
    if (activeBaseOccupant || !highValue || healthRatio > 0.34) {
      return false;
    }
  }

  if (shouldEnemyObjectiveClockVetoRepair(state, unit, critical)) {
    return false;
  }

  if (state.difficulty === "Hard" && assessment.strategicPhase === "GateLockoutCombat" && highValue && canEnemyUnitMakeImmediateKill(state, unit)) {
    return false;
  }

  if (isEnemyUnitStrandedBeyondFrontLine(state, unit)) {
    return true;
  }

  if (state.difficulty === "Hard" && humanBased && !critical) {
    const gateTarget = chooseGateObjective(state, "Enemy", unit.coord);
    if (
      isEnemyGateContinuityPhase(assessment.strategicPhase) &&
      gateTarget &&
      hexDistance(unit.coord, gateTarget.coord) <= 6
    ) {
      return false;
    }
    if (isEnemyBaseOperationPhase(assessment.strategicPhase) && hexDistance(unit.coord, state.bases.Player) <= 8) {
      return false;
    }
  }

  const repairThreshold = Math.max(highValue ? 0.34 : 0.24, (highValue ? 0.55 : 0.34) * phaseWeights.repair);
  return healthRatio < repairThreshold && ((highValue && healthRatio < 0.38 * phaseWeights.repair) || danger > unit.health * 0.5 || value > 75);
}

function shouldEnemyAttemptRepairRetreat(state: GameState, unit: UnitInstance): boolean {
  if (shouldEnemyRetreatForRepair(state, unit)) {
    return true;
  }
  return isEnemyLowHealthHighValueRepairCandidate(state, unit);
}

function isEnemyLowHealthHighValueRepairCandidate(state: GameState, unit: UnitInstance): boolean {
  if (
    unit.owner !== "Enemy" ||
    isEnemyRepairCoord(state, unit.coord, unit.type) ||
    !isEnemyHighValueRepairPreservationUnit(unit.type) ||
    unit.health / Math.max(1, unit.maxHealth) > 0.34
  ) {
    return false;
  }
  return state.baseOccupation.Enemy <= 0 && !getOwnerUnits(state, "Player").some((player) => sameHex(player.coord, state.bases.Enemy));
}

function shouldEnemyObjectiveClockVetoRepair(state: GameState, unit: UnitInstance, survivalVeryPoor: boolean): boolean {
  if (state.difficulty !== "Hard" || unit.owner !== "Enemy" || survivalVeryPoor || !getUnitDefinition(unit.type).humanBased) {
    return false;
  }
  if (shouldEnemyGateLockoutPreserveDamagedCombatPower(state, unit)) {
    return false;
  }

  return (
    canEnemyHumanCompleteGateClockWithin(state, unit, 2) ||
    canEnemyHumanDenyGateClockWithin(state, unit, 2) ||
    canEnemyHumanCompleteBaseClockWithin(state, unit, 2) ||
    canEnemyHumanDenyBaseClockWithin(state, unit, 2)
  );
}

function shouldEnemyGateLockoutPreserveDamagedCombatPower(state: GameState, unit: UnitInstance): boolean {
  if (
    state.difficulty !== "Hard" ||
    getEnemyStrategicAssessment(state).strategicPhase !== "GateLockoutCombat" ||
    unit.owner !== "Enemy" ||
    !isEnemyHighValueRepairPreservationUnit(unit.type)
  ) {
    return false;
  }

  const healthRatio = unit.health / Math.max(1, unit.maxHealth);
  const danger = estimatePlayerDangerAt(state, unit, unit.coord);
  const likelyToDie = danger >= unit.health * 0.82 || (healthRatio <= 0.42 && danger >= unit.health * 0.45);
  if (healthRatio > 0.58 || !likelyToDie) {
    return false;
  }

  return !canEnemyUnitMakeImmediateKill(state, unit);
}

function isEnemyHighValueRepairPreservationUnit(unitType: UnitType): boolean {
  return (
    unitType === "Tank" ||
    unitType === "IFV" ||
    unitType === "Artillery" ||
    unitType === "Anti-Air" ||
    unitType === "Attack Heli" ||
    unitType === "Jet" ||
    unitType === "Bomber" ||
    isSpecialUnit(unitType)
  );
}

function canEnemyUnitMakeImmediateKill(state: GameState, unit: UnitInstance): boolean {
  if (unit.hasAttackedThisDay || unit.placedDay === state.day) {
    return false;
  }

  const visibleTargetIds = new Set(
    getPlayerIntelForEnemy(state)
      .filter((intel) => intel.age === 0 && intel.confidence >= 0.75)
      .map((intel) => intel.unit.id)
  );
  return getOwnerUnits(state, "Player").some((target) => {
    if (!visibleTargetIds.has(target.id) || !canUnitTargetUnit(unit.type, target.type)) {
      return false;
    }
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, target.coord);
    if (hexDistance(unit.coord, target.coord) > stats.attackRange) {
      return false;
    }
    const outcome = getExpectedAttackOutcome(state, unit, target);
    return outcome.killProbability >= 0.58 || outcome.expectedDamage >= target.health;
  });
}

function canEnemyHumanCompleteGateClockWithin(state: GameState, unit: UnitInstance, turns: number): boolean {
  return (state.gates ?? []).some((gate) => gate.owner !== "Enemy" && getEnemyUnitTurnsToGateClock(state, unit, gate, "Enemy") <= turns);
}

function canEnemyHumanDenyGateClockWithin(state: GameState, unit: UnitInstance, turns: number): boolean {
  const playerIntel = getEnemyPlannerPlayerIntel(state);
  const objectiveClock = estimateEnemyObjectiveClocks(state, playerIntel);
  return (state.gates ?? []).some((gate) => {
    const playerTurns = objectiveClock.playerTurnsToGates[gate.id] ?? Number.POSITIVE_INFINITY;
    return playerTurns <= turns && getEnemyUnitTurnsToGateClock(state, unit, gate, "Enemy") <= turns;
  });
}

function canEnemyHumanCompleteBaseClockWithin(state: GameState, unit: UnitInstance, turns: number): boolean {
  if (!ownerControlsBothGates(state, "Enemy")) {
    return false;
  }
  return getEnemyUnitTurnsToBaseClock(state, unit, state.bases.Player, state.baseOccupation.Player) <= turns;
}

function canEnemyHumanDenyBaseClockWithin(state: GameState, unit: UnitInstance, turns: number): boolean {
  if (state.baseOccupation.Enemy <= 0) {
    return false;
  }
  const remainingPlayerTurns = Math.max(0, BASE_CAPTURE_DAYS - state.baseOccupation.Enemy);
  return remainingPlayerTurns <= turns && getEnemyUnitTurnsToBaseClock(state, unit, state.bases.Enemy, 0) <= turns;
}

function getEnemyUnitTurnsToGateClock(state: GameState, unit: UnitInstance, gate: GateState, owner: Owner): number {
  const moveTurns = getEnemyUnitTurnsToCoord(state, unit, gate.coord);
  if (!Number.isFinite(moveTurns)) {
    return Number.POSITIVE_INFINITY;
  }
  const retainedProgress = sameHex(unit.coord, gate.coord) ? gate.occupation[owner] : 0;
  return moveTurns + Math.max(0, GATE_CAPTURE_DAYS - retainedProgress);
}

function getEnemyUnitTurnsToBaseClock(state: GameState, unit: UnitInstance, base: UnitInstance["coord"], retainedOccupation: number): number {
  const moveTurns = getEnemyUnitTurnsToCoord(state, unit, base);
  if (!Number.isFinite(moveTurns)) {
    return Number.POSITIVE_INFINITY;
  }
  const progress = sameHex(unit.coord, base) ? retainedOccupation : 0;
  return moveTurns + Math.max(0, BASE_CAPTURE_DAYS - progress);
}

function getEnemyUnitTurnsToCoord(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  if (sameHex(unit.coord, coord)) {
    return 0;
  }
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, coord);
  return Math.ceil(hexDistance(unit.coord, coord) / Math.max(1, stats.moveRange));
}

function isEnemyUnitStrandedBeyondFrontLine(state: GameState, unit: UnitInstance): boolean {
  return unit.owner === "Enemy" && isCoordPastEnemyFrontLine(state, "Enemy", unit.coord) && !ownerControlsBothGates(state, "Enemy");
}

function shouldHoldForBaseDefense(state: GameState, unit: UnitInstance): boolean {
  if (unit.owner !== "Enemy") {
    return false;
  }

  const baseThreat = getEnemyBaseThreat(state);
  if (!isActiveEnemyBaseThreat(state, baseThreat) || !baseThreat || !canUnitTargetUnit(unit.type, baseThreat.type)) {
    return false;
  }

  const threatCanCapture = getUnitDefinition(baseThreat.type).humanBased;
  if (!threatCanCapture && state.baseOccupation.Enemy <= 0 && !sameHex(baseThreat.coord, state.bases.Enemy)) {
    return false;
  }

  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, baseThreat.coord);
  const distance = hexDistance(unit.coord, baseThreat.coord);
  return state.baseOccupation.Enemy > 0 || sameHex(baseThreat.coord, state.bases.Enemy) || distance <= stats.attackRange + stats.moveRange;
}

function getNearestEnemyBackRowCoord(state: GameState, coord: UnitInstance["coord"]): UnitInstance["coord"] {
  return state.map.hexes
    .filter((hex) => isOwnerBackRow(state, "Enemy", hex.coord))
    .sort((first, second) => hexDistance(coord, first.coord) - hexDistance(coord, second.coord))[0]?.coord ?? state.bases.Enemy;
}

function isEnemyRepairCoord(state: GameState, coord: UnitInstance["coord"], unitType?: UnitType): boolean {
  const canUseSupplyTruckRepair = !unitType || getUnitDefinition(unitType).domain === "Ground";
  return (
    isOwnerBackRow(state, "Enemy", coord) ||
    (canUseSupplyTruckRepair && getOwnerUnits(state, "Enemy").some((unit) => isEnemySupplySupportUnit(unit.type) && hexDistance(unit.coord, coord) <= SUPPLY_TRUCK_REPAIR_RANGE))
  );
}

function getEnemyRepairCoords(state: GameState, unitType?: UnitType): UnitInstance["coord"][] {
  return state.map.hexes
    .filter((hex) => hex.passable && isEnemyRepairCoord(state, hex.coord, unitType))
    .map((hex) => ({ ...hex.coord }));
}

function getNearestEnemyRepairCoord(state: GameState, coord: UnitInstance["coord"], unitType?: UnitType): UnitInstance["coord"] {
  return getEnemyRepairCoords(state, unitType)
    .sort((first, second) => hexDistance(coord, first) - hexDistance(coord, second) || hexId(first).localeCompare(hexId(second)))[0] ?? getNearestEnemyBackRowCoord(state, coord);
}

function getNearestEnemyRepairDistance(state: GameState, coord: UnitInstance["coord"], unitType?: UnitType): number {
  return hexDistance(coord, getNearestEnemyRepairCoord(state, coord, unitType));
}

function isEnemySupplyTruckPlacementCoord(state: GameState, coord: UnitInstance["coord"], unitType?: UnitType): boolean {
  return Boolean(getEnemySupplyPlacementAnchor(state, coord, unitType));
}

function getEnemySupplyPlacementAnchor(state: GameState, coord: UnitInstance["coord"], unitType?: UnitType): UnitInstance | undefined {
  if (unitType && getUnitDefinition(unitType).domain !== "Ground") {
    return undefined;
  }

  return getOwnerUnits(state, "Enemy").find((unit) => canSupplyTruckProvidePlacementAt(state, unit, coord, unitType));
}

function getOwnerUnits(state: GameState, owner: Owner): UnitInstance[] {
  const cache = getEnemyEvaluationCache(state);
  cache.ownerUnits ??= {};
  cache.ownerUnits[owner] ??= state.units.filter((unit) => unit.owner === owner);
  return cache.ownerUnits[owner] ?? [];
}

function getUnitById(state: GameState, unitId: string): UnitInstance | undefined {
  const cache = getEnemyEvaluationCache(state);
  cache.unitsById ??= new Map(state.units.map((unit) => [unit.id, unit]));
  return cache.unitsById.get(unitId);
}

function getKnownPlayerUnitsForEnemy(state: GameState): UnitInstance[] {
  const cache = getEnemyEvaluationCache(state);
  cache.knownPlayerUnits ??= getKnownUnitsForOwner(state, "Enemy");
  return cache.knownPlayerUnits;
}

function getPlayerIntelForEnemy(state: GameState): PlayerUnitIntel[] {
  const cache = getEnemyEvaluationCache(state);
  if (cache.playerIntel) {
    return cache.playerIntel;
  }

  const visibleHexIds = getEnemyVisibleHexIds(state);
  const livePlayerUnitIds = new Set(getOwnerUnits(state, "Player").map((unit) => unit.id));
  const intelById = new Map<string, { unit: UnitInstance; lastSeenDay: number }>();

  for (const unit of getOwnerUnits(state, "Player")) {
    if (visibleHexIds.has(hexId(unit.coord))) {
      intelById.set(unit.id, {
        unit,
        lastSeenDay: state.day
      });
    }
  }

  for (const spottedUnit of Object.values(state.spottedUnits?.Enemy ?? {})) {
    if (!livePlayerUnitIds.has(spottedUnit.id) || intelById.has(spottedUnit.id)) {
      continue;
    }

    intelById.set(spottedUnit.id, {
      unit: spottedUnitToUnitInstance(spottedUnit),
      lastSeenDay: spottedUnit.spottedDay
    });
  }

  cache.playerIntel = Array.from(intelById.values()).map(({ unit, lastSeenDay }) => {
    const age = Math.max(0, state.day - lastSeenDay);
    const likelyObjective = inferPlayerLikelyObjective(state, unit);
    return {
      unit,
      lastSeenDay,
      age,
      confidence: getIntelConfidence(age),
      predictedCoord: projectPlayerUnitCoord(state, unit, likelyObjective, age),
      likelyObjective
    };
  });
  return cache.playerIntel;
}

function getIntelConfidence(age: number): number {
  return Math.max(0.22, 1 - age * 0.11);
}

function inferPlayerLikelyObjective(state: GameState, unit: UnitInstance): PlayerLikelyObjective {
  const definition = getUnitDefinition(unit.type);
  const enemyHumanAtPlayerBase = getOwnerUnits(state, "Enemy").some(
    (enemyUnit) => getUnitDefinition(enemyUnit.type).humanBased && sameHex(enemyUnit.coord, state.bases.Player)
  );

  if (enemyHumanAtPlayerBase || state.baseOccupation.Player > 0) {
    return "PlayerBaseDefense";
  }

  if (unit.type === "Jet" || unit.type === "Anti-Air") {
    return getOwnerUnits(state, "Enemy").some((enemyUnit) => getUnitDefinition(enemyUnit.type).domain === "Air") ? "HuntAir" : "Scout";
  }

  if (unit.type === "Bomber") {
    return getOwnerUnits(state, "Enemy").some((enemyUnit) => getUnitDefinition(enemyUnit.type).domain === "Ground") ? "HuntGround" : "Scout";
  }

  if (definition.humanBased) {
    const gate = choosePredictedPlayerGateObjective(state, unit);
    if (gate) {
      return gate.id === "West" ? "WestGate" : "EastGate";
    }

    return "EnemyBase";
  }

  if (canCounterAir(unit.type) && getOwnerUnits(state, "Enemy").some((enemyUnit) => getUnitDefinition(enemyUnit.type).domain === "Air")) {
    return "HuntAir";
  }

  if (isReconUnit(unit.type)) {
    return "Scout";
  }

  return "HuntGround";
}

function choosePredictedPlayerGateObjective(state: GameState, unit: UnitInstance): GateState | undefined {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord);
  return (state.gates ?? [])
    .filter((gate) => gate.owner !== "Player")
    .map((gate) => {
      const distance = hexDistance(unit.coord, gate.coord);
      const enemyOwnedBonus = gate.owner === "Enemy" ? 90 : 30;
      const reachableSoonBonus = distance <= stats.moveRange * 2 + 2 ? 70 : 0;
      return {
        gate,
        score: enemyOwnedBonus + reachableSoonBonus + gate.occupation.Player * 45 - distance * 7
      };
    })
    .filter((entry) => entry.score > 20)
    .sort((first, second) => second.score - first.score)[0]?.gate;
}

function projectPlayerUnitCoord(
  state: GameState,
  unit: UnitInstance,
  objective: PlayerLikelyObjective,
  age: number
): UnitInstance["coord"] {
  const objectiveCoord = getPlayerObjectiveCoord(state, unit, objective);
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord);
  const projectionRange = Math.max(1, stats.moveRange * Math.min(3, age + 1));

  return state.map.hexes
    .filter((hex) => hex.passable && hexDistance(unit.coord, hex.coord) <= projectionRange)
    .map((hex) => {
      const objectiveDistance = hexDistance(hex.coord, objectiveCoord);
      const currentObjectiveDistance = hexDistance(unit.coord, objectiveCoord);
      const progress = currentObjectiveDistance - objectiveDistance;
      const travelPenalty = hexDistance(unit.coord, hex.coord) * 0.8;
      const forwardPressure = objective === "EnemyBase" ? Math.max(0, unit.coord.r - hex.coord.r) * 2 : 0;
      return {
        coord: hex.coord,
        score: progress * 16 - objectiveDistance * 3 - travelPenalty + forwardPressure
      };
    })
    .sort((first, second) => second.score - first.score)[0]?.coord ?? unit.coord;
}

function getPlayerObjectiveCoord(state: GameState, unit: UnitInstance, objective: PlayerLikelyObjective): UnitInstance["coord"] {
  if (objective === "EnemyBase") {
    return state.bases.Enemy;
  }

  if (objective === "PlayerBaseDefense") {
    return state.bases.Player;
  }

  if (objective === "WestGate" || objective === "EastGate") {
    const gate = (state.gates ?? []).find((candidate) => candidate.id === (objective === "WestGate" ? "West" : "East"));
    return gate?.coord ?? state.bases.Enemy;
  }

  if (objective === "HuntAir") {
    return chooseEnemyUnitObjectiveCoord(state, unit, "Air") ?? state.bases.Enemy;
  }

  if (objective === "HuntGround") {
    return chooseEnemyUnitObjectiveCoord(state, unit, "Ground") ?? state.bases.Enemy;
  }

  return state.bases.Enemy;
}

function chooseEnemyUnitObjectiveCoord(
  state: GameState,
  unit: UnitInstance,
  domain: "Ground" | "Air"
): UnitInstance["coord"] | undefined {
  return getOwnerUnits(state, "Enemy")
    .filter((enemyUnit) => getUnitDefinition(enemyUnit.type).domain === domain && canUnitTargetUnit(unit.type, enemyUnit.type))
    .sort((first, second) => {
      const firstScore = getUnitInstanceValue(state, first) - hexDistance(unit.coord, first.coord) * 7;
      const secondScore = getUnitInstanceValue(state, second) - hexDistance(unit.coord, second.coord) * 7;
      return secondScore - firstScore;
    })[0]?.coord;
}

function getKnownUnitsForOwner(state: GameState, owner: Owner): UnitInstance[] {
  const visibleHexIds = owner === "Enemy" ? getEnemyVisibleHexIds(state) : getVisibleHexIdsForOwner(state, owner);
  const knownUnitsById = new Map<string, UnitInstance>();

  for (const unit of state.units) {
    if (unit.owner === owner || !visibleHexIds.has(hexId(unit.coord))) {
      continue;
    }

    knownUnitsById.set(unit.id, unit);
  }

  const liveUnitIds = new Set(state.units.map((unit) => unit.id));
  for (const spottedUnit of Object.values(state.spottedUnits?.[owner] ?? {})) {
    if (liveUnitIds.has(spottedUnit.id) && !knownUnitsById.has(spottedUnit.id)) {
      knownUnitsById.set(spottedUnit.id, spottedUnitToUnitInstance(spottedUnit));
    }
  }

  return Array.from(knownUnitsById.values());
}

function spottedUnitToUnitInstance(unit: SpottedUnit): UnitInstance {
  return {
    id: unit.id,
    owner: unit.owner,
    type: unit.type,
    level: unit.level ?? 1,
    coord: { ...unit.coord },
    health: unit.health,
    maxHealth: unit.maxHealth,
    placedDay: 0,
    hasMovedThisDay: false,
    movementSpentThisDay: 0,
    hasAttackedThisDay: false
  };
}

function getEnemyVisibleHexIds(state: GameState): Set<string> {
  if (activeEnemyTurnPlan) {
    activeEnemyTurnPlan.cache.visibleHexIds ??= getVisibleHexIdsForOwner(state, "Enemy");
    return activeEnemyTurnPlan.cache.visibleHexIds;
  }

  const cache = getEnemyEvaluationCache(state);
  cache.visibleHexIds ??= getVisibleHexIdsForOwner(state, "Enemy");
  return cache.visibleHexIds;
}

function getEnemyLegalMoveCoords(state: GameState, unit: UnitInstance): UnitInstance["coord"][] {
  const cache = getEnemyEvaluationCache(state);
  cache.legalMoveCoords ??= new Map();
  const cacheKey = `${unit.id}:${unit.type}:${unit.level}:${hexId(unit.coord)}:${unit.movementSpentThisDay ?? 0}:${unit.hasMovedThisDay ? 1 : 0}`;
  const cached = cache.legalMoveCoords.get(cacheKey);
  if (cached) {
    return cached;
  }

  const coords = getLegalMoveCoordsWithVisibility(state, unit, getEnemyVisibleHexIds(state));
  cache.legalMoveCoords.set(cacheKey, coords);
  return coords;
}

function canMoveUnitTo(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): boolean {
  if (unit.owner !== "Enemy") {
    return canMoveUnitToRaw(state, unit, coord);
  }

  const cache = getEnemyEvaluationCache(state);
  cache.legalMoveCoordIds ??= new Map();
  const cacheKey = `${unit.id}:${unit.type}:${unit.level}:${hexId(unit.coord)}:${unit.movementSpentThisDay ?? 0}:${unit.hasMovedThisDay ? 1 : 0}`;
  let coordIds = cache.legalMoveCoordIds.get(cacheKey);
  if (!coordIds) {
    coordIds = new Set(getEnemyLegalMoveCoords(state, unit).map((candidate) => hexId(candidate)));
    cache.legalMoveCoordIds.set(cacheKey, coordIds);
  }
  return coordIds.has(hexId(coord));
}

function getEnemyFrontLineLeverage(state: GameState, playerIntel = getPlayerIntelForEnemy(state)): number {
  return getEnemyGateLockoutOpportunityScore(state, undefined, playerIntel).total;
}

function getEnemyGateLockoutOpportunityScore(
  state: GameState,
  completingGate?: GateState,
  playerIntel = getPlayerIntelForEnemy(state)
): EnemyGateLockoutOpportunityScore {
  const empty: EnemyGateLockoutOpportunityScore = {
    total: 0,
    incomeAdvantage: 0,
    visionAdvantage: 0,
    baseAccessUnlock: 0,
    frontLineAttrition: 0,
    forwardUnitValue: 0,
    forwardUnitCount: 0
  };
  if (ownerControlsBothGates(state, "Enemy")) {
    return empty;
  }
  if (completingGate && completingGate.owner === "Enemy") {
    return empty;
  }

  const gates = state.gates ?? [];
  const wouldOwnBothGates = completingGate
    ? gates.length >= 2 && gates.filter((gate) => gate.id !== completingGate.id).every((gate) => gate.owner === "Enemy")
    : gates.length >= 2 && gates.filter((gate) => gate.owner === "Enemy").length === gates.length - 1;
  if (!wouldOwnBothGates) {
    return empty;
  }

  const forwardIntel = playerIntel.filter((intel) => isCoordPastEnemyFrontLine(state, "Player", intel.predictedCoord));
  const forwardUnitValue = forwardIntel.reduce((total, intel) => total + getUnitInstanceValue(state, intel.unit) * intel.confidence, 0);
  const forwardUnitCount = forwardIntel.reduce((total, intel) => total + intel.confidence, 0);
  const forwardMultiplier = forwardUnitCount > 0 ? 1 : 0.28;
  const enemyBothGateIncome = gates.length * getGateIncomeBonusForEconomy(state.enemyEconomy);
  const currentPlayerGateIncome = gates
    .filter((gate) => gate.owner === "Player" || gate.id === completingGate?.id)
    .length * getGateIncomeBonusForEconomy(state.economy);
  const incomeAdvantage = (enemyBothGateIncome + currentPlayerGateIncome) * 18;
  const visionAdvantage = gates.reduce((score, gate) => {
    const sideSight = getGateSideHexes(state, gate).size * 0.45;
    const forwardPlayerNearGate = forwardIntel.filter((intel) => hexDistance(intel.predictedCoord, gate.coord) <= 7).length * 28;
    return score + sideSight + forwardPlayerNearGate + (gate.id === completingGate?.id ? 42 : 18);
  }, 0);
  const baseAccessUnlock =
    210 +
    Math.max(0, scorePlayerBaseVulnerability(state, playerIntel)) * 0.22 +
    getOwnerUnits(state, "Enemy").filter((unit) => getUnitDefinition(unit.type).humanBased).length * 24;
  const frontLineAttrition = forwardIntel.reduce((score, intel) => {
    if (!isCoordPastEnemyFrontLine(state, "Player", intel.predictedCoord)) {
      return score;
    }

    const distance = hexDistance(intel.predictedCoord, state.bases.Enemy);
    const value = getUnitInstanceValue(state, intel.unit);
    const capturerBonus = getUnitDefinition(intel.unit.type).humanBased ? 36 : 0;
    const baseThreatBonus = Math.max(0, getEnemyBaseResponseRadius(state) + 2 - distance) * 18;
    const occupationBonus = state.baseOccupation.Enemy * 75;
    const attritionDamage = Math.max(1, Math.ceil(intel.unit.health * FRONT_LINE_ATTRITION_PERCENT));
    const attritionPressure = Math.min(value, attritionDamage * 10 + value * 0.26);
    return score + (value * 0.44 + attritionPressure + capturerBonus + baseThreatBonus + occupationBonus) * intel.confidence;
  }, 0);

  const total = (incomeAdvantage + visionAdvantage + baseAccessUnlock) * forwardMultiplier + frontLineAttrition;
  return {
    total,
    incomeAdvantage,
    visionAdvantage,
    baseAccessUnlock,
    frontLineAttrition,
    forwardUnitValue,
    forwardUnitCount
  };
}

interface EnemyInitiativePressureInputs {
  playerGateCount?: number;
  enemyGateCount?: number;
  immediateBaseThreat?: boolean;
  activeBaseThreat?: boolean;
  strategicPhase: EnemyStrategicPhase;
  player?: ArmyComposition;
  enemy?: ArmyComposition;
  predictedGatePressure?: Partial<Record<GateState["id"], number>>;
}

function scoreEnemyInitiativePressure(state: GameState, inputs: EnemyInitiativePressureInputs): number {
  const gateCount = (state.gates ?? []).length;
  const playerGateCount = inputs.playerGateCount ?? 0;
  const enemyGateCount = inputs.enemyGateCount ?? 0;
  const gateDeficit = Math.max(0, playerGateCount - enemyGateCount);

  const enemyHasGateClock = (state.gates ?? []).some(
    (gate) => gate.occupation?.Enemy > 0 && gate.owner !== "Enemy"
  );

  const enemyHasBaseClock = state.baseOccupation?.Player > 0;
  const noEnemyClock = !enemyHasGateClock && !enemyHasBaseClock;

  const playerForwardPressure = getPlayerForwardPressureForEnemyAI(state, inputs);
  const materialRatio = getEnemyKnownMaterialRatioFromAssessment(inputs);
  const playerGatePressure = getEnemyInitiativePlayerGatePressure(state, inputs);

  const neutralOrContestedBoard =
    gateCount > 0 &&
    enemyGateCount < gateCount &&
    !ownerControlsBothGates(state, "Enemy");

  const activeBaseEmergency =
    state.baseOccupation?.Enemy > 0 ||
    inputs.immediateBaseThreat ||
    inputs.activeBaseThreat;

  let raw = 0;

  raw += 45;
  raw += gateDeficit * 85;
  raw += playerGatePressure;
  raw += noEnemyClock ? 55 : 0;
  raw += neutralOrContestedBoard && noEnemyClock ? 45 : 0;
  raw += Math.min(160, playerForwardPressure * 0.35);

  if (inputs.strategicPhase === "OpeningGateRace") raw += 55;
  if (inputs.strategicPhase === "Recovery") raw += 105;
  if (inputs.strategicPhase === "GateLockoutCombat") raw += 145;

  if (materialRatio <= 1.12) raw += 55;

  if (activeBaseEmergency) raw -= 180;

  return Math.max(0, Math.min(420, raw));
}

function getPlayerForwardPressureForEnemyAI(state: GameState, _inputs: EnemyInitiativePressureInputs): number {
  return getPlayerForwardPressure(state);
}

function getEnemyKnownMaterialRatioFromAssessment(inputs: Pick<EnemyInitiativePressureInputs, "enemy" | "player">): number {
  return (inputs.enemy?.totalValue ?? 0) / Math.max(1, inputs.player?.totalValue ?? 0);
}

function getEnemyInitiativePlayerGatePressure(state: GameState, inputs: Pick<EnemyInitiativePressureInputs, "predictedGatePressure">): number {
  const pressure = (state.gates ?? []).reduce((score, gate) => {
    const ownershipPressure = gate.owner === "Player" ? 34 : gate.occupation.Player > 0 ? 24 : 0;
    const forecastPressure = Math.max(0, inputs.predictedGatePressure?.[gate.id] ?? 0) * 0.18;
    return score + ownershipPressure + forecastPressure;
  }, 0);
  return Math.min(95, pressure);
}

function getEnemyInitiativePressureReasons(state: GameState, inputs: EnemyInitiativePressureInputs): string[] {
  const reasons: string[] = ["second-player-counter-pressure"];
  const gateCount = (state.gates ?? []).length;
  const playerGateCount = inputs.playerGateCount ?? 0;
  const enemyGateCount = inputs.enemyGateCount ?? 0;
  const enemyHasGateClock = (state.gates ?? []).some((gate) => gate.occupation?.Enemy > 0 && gate.owner !== "Enemy");
  const enemyHasBaseClock = state.baseOccupation?.Player > 0;
  const playerGatePressure = getEnemyInitiativePlayerGatePressure(state, inputs);
  const playerForwardPressure = getPlayerForwardPressureForEnemyAI(state, inputs);
  const materialRatio = getEnemyKnownMaterialRatioFromAssessment(inputs);

  if (playerGateCount > enemyGateCount) reasons.push("gate-deficit");
  if (playerGatePressure > 0) reasons.push("player-gate-pressure");
  if (!enemyHasGateClock && !enemyHasBaseClock) reasons.push("no-enemy-objective-clock");
  if (gateCount > 0 && enemyGateCount < gateCount && !ownerControlsBothGates(state, "Enemy")) reasons.push("neutral-or-contested-board");
  if (playerForwardPressure > 0) reasons.push("player-forward-pressure");
  if (inputs.strategicPhase === "OpeningGateRace" || inputs.strategicPhase === "Recovery" || inputs.strategicPhase === "GateLockoutCombat") reasons.push(inputs.strategicPhase);
  if (materialRatio <= 1.12) reasons.push("material-even-or-behind");
  if (state.baseOccupation?.Enemy > 0 || inputs.immediateBaseThreat || inputs.activeBaseThreat) reasons.push("base-emergency-clamp");
  return reasons;
}

function getEnemyStrategicAssessment(state: GameState): EnemyStrategicAssessment {
  const cache = getEnemyEvaluationCache(state);
  if (cache.strategicAssessment) {
    return cache.strategicAssessment;
  }

  const config = getAiDifficultyConfig(state);
  const playerIntel = getPlayerIntelForEnemy(state);
  const knownPlayerUnits = playerIntel.map((intel) => intel.unit);
  const player = summarizeArmy(state, knownPlayerUnits);
  const enemy = summarizeArmy(state, getOwnerUnits(state, "Enemy"));
  const playerGateCount = (state.gates ?? []).filter((gate) => gate.owner === "Player").length;
  const enemyGateCount = (state.gates ?? []).filter((gate) => gate.owner === "Enemy").length;
  const gateDisadvantage = Math.max(0, playerGateCount - enemyGateCount);
  const enemyGateIncome = getOwnerGateIncomeBonus(state, "Enemy");
  const playerGateIncome = getOwnerGateIncomeBonus(state, "Player");
  const visibleCoverage = getEnemyVisibleHexIds(state).size / Math.max(1, state.map.hexes.length);
  const phase = state.day <= 10 ? "early" : state.day <= 24 ? "mid" : "late";
  const economy = state.enemyEconomy;
  const moneyPressure = Math.max(0, 52 - economy.moneyPoundsBn) * 0.35;
  const highEndShortfall =
    (ownerHasBuilding(state, "Enemy", "Drone Factory") ? getProductionCost("Reaper") : getResearchCost("UnlockDroneFactory", undefined, economy)) -
    economy.moneyPoundsBn;
  const baseThreat = getEnemyBaseThreat(state);
  const activeBaseThreat = isActiveEnemyBaseThreat(state, baseThreat);
  const enemyCapturingPlayerBase = getOwnerUnits(state, "Enemy").some(
    (unit) => getUnitDefinition(unit.type).humanBased && sameHex(unit.coord, state.bases.Player)
  );
  const predictedEnemyBasePressure = scorePredictedEnemyBasePressure(state, playerIntel);
  const predictedGatePressure = scorePredictedGatePressure(state, playerIntel);
  const gateCaptureOpportunity = scoreEnemyGateCaptureOpportunity(state, playerIntel);
  const gateLockoutLeverage = getEnemyFrontLineLeverage(state, playerIntel);
  const playerBaseVulnerability = scorePlayerBaseVulnerability(state, playerIntel);
  const predictedPlayerBaseDefense = playerIntel.reduce(
    (score, intel) => score + (intel.likelyObjective === "PlayerBaseDefense" ? getUnitInstanceValue(state, intel.unit) * intel.confidence * 0.2 : 0),
    0
  );
  const playerCaptureThreat = playerIntel.filter(
    (intel) =>
      getUnitDefinition(intel.unit.type).humanBased &&
      (hexDistance(intel.predictedCoord, state.bases.Enemy) <= getEnemyBaseResponseRadius(state) || intel.likelyObjective === "EnemyBase")
  ).length;
  const immediateBaseThreat = playerIntel.some((intel) => getUnitDefinition(intel.unit.type).humanBased && hexDistance(intel.predictedCoord, state.bases.Enemy) <= 2);
  const strategicPhase = resolveEnemyStrategicPhaseFromSnapshot(state, {
    enemyGateCount,
    playerGateCount,
    immediateBaseThreat,
    activeBaseThreat,
    predictedEnemyBasePressure,
    gateLockoutCombatPressure: scoreEnemyGateLockoutCombatPressure(state, playerIntel)
  });
  const phaseWeights = getEnemyStrategicPhaseWeights(strategicPhase);
  const initiativeInputs: EnemyInitiativePressureInputs = {
    playerGateCount,
    enemyGateCount,
    immediateBaseThreat,
    activeBaseThreat,
    strategicPhase,
    player,
    enemy,
    predictedGatePressure
  };
  const initiativePressure = scoreEnemyInitiativePressure(state, initiativeInputs);
  const initiativeReasons = getEnemyInitiativePressureReasons(state, initiativeInputs);
  const playerAntiAirThreat = player.antiAirCount + knownPlayerUnits.filter((unit) => ["Jet", "Operator", "Reaper"].includes(unit.type)).length;
  const enemyLongRangeNeedingSight = enemy.artillerySupportCount + getEnemyUnitPresence(state, "Artillery") + getEnemyUnitPresence(state, "Tank") * 0.5;
  const forecast = buildEnemyStrategicForecast(state, {
    phase,
    player,
    enemy,
    enemyGateIncome,
    playerGateIncome,
    predictedEnemyBasePressure,
    predictedGatePressure,
    predictedPlayerBaseDefense,
    gateLockoutLeverage
  });
  const opponentProfile = profileOpponent(state, playerIntel, player, playerGateCount, enemyGateCount);
  const strategyPlan = chooseEnemyStrategyPlan(state, forecast, opponentProfile, {
    phase,
    player,
    enemy,
    predictedEnemyBasePressure
  });
  const budget = buildEnemyBudgetReserve(state, forecast, strategyPlan, opponentProfile);
  const influence = buildEnemyInfluenceMap(state, playerIntel, forecast);

  cache.strategicAssessment = {
    phase,
    strategicPhase,
    knownPlayerUnits,
    player,
    enemy,
    playerGateCount,
    enemyGateCount,
    gateIncomeSwing: enemyGateIncome - playerGateIncome,
    economyUrgency:
      22 +
      Math.max(0, 28 - state.day) * 1.7 +
      Math.max(0, state.day - 12) * 0.9 +
      Math.max(0, playerGateCount - enemyGateCount) * 22 +
      gateDisadvantage * 30 +
      moneyPressure,
    productionThroughputNeed:
      (18 +
        Math.max(0, economy.productionQueue.length - economy.productionCapacityLevel) * 20 +
        Math.max(0, 8 - enemy.totalCount) * 4 +
        (phase === "late" ? 18 : 0)) *
      phaseWeights.production,
    researchThroughputNeed:
      16 +
      Math.max(0, economy.researchQueue.length - economy.researchCapacityLevel) * 22 +
      (phase === "early" ? 24 : phase === "mid" ? 14 : 8),
    scoutNeed:
      (Math.max(0, 0.48 - visibleCoverage) * 140 +
        Math.max(0, 4 - knownPlayerUnits.length) * 14 +
        Math.max(0, enemyLongRangeNeedingSight - enemy.scoutCount) * 18) *
      phaseWeights.scout,
    specialPlanUrgency:
      35 +
      (phase === "early" ? 22 : phase === "mid" ? 44 : 62) +
      player.specialCount * 18 +
      gateDisadvantage * 24 +
      Math.max(0, state.baseOccupation.Player - state.baseOccupation.Enemy) * 24,
    reaperPlanUrgency:
      45 +
      (phase === "early" ? 18 : phase === "mid" ? 58 : 92) +
      Math.max(0, player.totalValue - enemy.totalValue) * 0.08 +
      player.specialCount * 28 +
      gateDisadvantage * 38 +
      Math.max(0, highEndShortfall) * 0.45,
    baseDefenseUrgency:
      ((activeBaseThreat ? baseThreat?.score ?? 0 : 0) +
        predictedEnemyBasePressure * (state.difficulty === "Hard" ? 1.05 : 0.8) +
        playerCaptureThreat * (state.difficulty === "Hard" ? 115 : 80) +
        state.baseOccupation.Enemy * 120 -
        (state.difficulty === "Hard" && state.baseOccupation.Enemy === 0 ? gateDisadvantage * 28 : 0) -
        (state.difficulty === "Hard" ? gateLockoutLeverage * 0.24 : 0)) *
      phaseWeights.defense,
    baseAttackUrgency:
      (42 +
        state.baseOccupation.Player * 120 +
        (enemyCapturingPlayerBase ? 170 : 0) +
        playerBaseVulnerability * 0.85 * config.playerBaseVulnerabilityMultiplier +
        Math.max(0, enemy.captureCount - player.captureCount) * 12 -
        (isEnemyBaseOperationPhase(strategicPhase) ? 0 : 90) -
        predictedPlayerBaseDefense * 0.12) *
      phaseWeights.base,
    playerBaseVulnerability,
    antiAirNeed: player.airCount * 28 + player.highValueAirCount * 46 - enemy.antiAirCount * 26,
    airExploitationOpportunity:
      player.groundCount * 16 +
      Math.max(0, player.groundCount - playerAntiAirThreat * 2) * 34 +
      Math.max(0, player.totalValue - playerAntiAirThreat * 95) * 0.05,
    groundExploitationOpportunity:
      player.airCount * 18 +
      Math.max(0, player.airCount - player.groundCount) * 38 +
      Math.max(0, 2 - player.captureCount) * 34,
    gateUrgency:
      ((state.difficulty === "Hard" ? 56 : 38) +
        Math.max(0, playerGateCount - enemyGateCount) * 44 +
        gateDisadvantage * (state.difficulty === "Hard" ? 32 : 14) +
        gateLockoutLeverage * (state.difficulty === "Hard" ? 0.82 : 0.42) +
        (!isEnemyBaseOperationPhase(strategicPhase) ? Math.max(0, playerBaseVulnerability - 120) * 0.28 : 0) +
        (state.difficulty === "Hard" && enemyGateCount === 0 ? 80 + playerGateCount * 45 : 0) +
        Math.max(0, state.day - 6) * (state.difficulty === "Hard" ? 2.6 : 1.8) +
        (state.difficulty === "Hard" ? Math.max(0, 16 - state.day) * 4 : 0) +
        Math.max(0, -enemyGateIncome + playerGateIncome) * 5 +
        Math.max(0, (gateCaptureOpportunity.West ?? 0) + (gateCaptureOpportunity.East ?? 0)) * 0.22 * config.gateCaptureOpportunityMultiplier +
        Math.max(0, (predictedGatePressure.West ?? 0) + (predictedGatePressure.East ?? 0)) * 0.26) *
      phaseWeights.gate,
    initiativePressure,
    initiativeReasons,
    gateLockoutLeverage,
    gateCaptureOpportunity,
    predictedEnemyBasePressure,
    predictedGatePressure,
    predictedPlayerBaseDefense,
    forecast,
    opponentProfile,
    strategyPlan,
    budget,
    influence
  };
  return cache.strategicAssessment;
}

function buildEnemyStrategicForecast(
  state: GameState,
  inputs: {
    phase: GamePhase;
    player: ArmyComposition;
    enemy: ArmyComposition;
    enemyGateIncome: number;
    playerGateIncome: number;
    predictedEnemyBasePressure: number;
    predictedGatePressure: Partial<Record<GateState["id"], number>>;
    predictedPlayerBaseDefense: number;
    gateLockoutLeverage: number;
  }
): EnemyStrategicForecast {
  const economy = state.enemyEconomy;
  const horizonDays = inputs.phase === "early" ? 8 : inputs.phase === "mid" ? 10 : 12;
  const projectedIncomePerDay = economy.incomePoundsBn - inputs.enemyGateIncome;
  const projectedMoney = economy.moneyPoundsBn + projectedIncomePerDay * horizonDays;
  const gateIncomeDeficit = Math.max(0, inputs.enemyGateIncome - inputs.playerGateIncome);
  const missingSpecialCost = ownerHasBuilding(state, "Enemy", "Special Services") ? 0 : getResearchCost("UnlockSpecialServices", undefined, economy);
  const missingDroneCost = ownerHasBuilding(state, "Enemy", "Drone Factory") ? 0 : getResearchCost("UnlockDroneFactory", undefined, economy);
  const reaperCost = getProductionCost("Reaper");
  const desiredReaperCount = inputs.phase === "early" ? 1 : inputs.phase === "mid" ? 2 : 3;
  const reaperPipelineShortfall = Math.max(0, desiredReaperCount - getEnemyUnitPresence(state, "Reaper"));
  const desiredWarChest =
    18 +
    (inputs.phase === "early" ? 14 : inputs.phase === "mid" ? 34 : 58) +
    missingSpecialCost * 0.8 +
    missingDroneCost * 0.9 +
    reaperPipelineShortfall * reaperCost * 0.75 +
    gateIncomeDeficit * 8 +
    Math.max(0, inputs.player.totalValue - inputs.enemy.totalValue) * 0.03;
  const incomeShortfall = Math.max(0, desiredWarChest / Math.max(1, horizonDays) - projectedIncomePerDay);
  const totalGatePressure = (inputs.predictedGatePressure.West ?? 0) + (inputs.predictedGatePressure.East ?? 0);
  const lossRisk =
    state.baseOccupation.Enemy * 150 +
    inputs.predictedEnemyBasePressure +
    Math.max(0, inputs.player.totalValue - inputs.enemy.totalValue) * 0.08;

  return {
    horizonDays,
    projectedMoney,
    projectedIncomePerDay,
    desiredWarChest,
    economyInvestmentNeed:
      incomeShortfall * 12 +
      Math.max(0, inputs.enemyGateIncome - inputs.playerGateIncome) * 6 +
      Math.max(0, desiredWarChest - projectedMoney) * 0.35,
    productionScaleNeed:
      Math.max(0, economy.productionQueue.length - economy.productionCapacityLevel) * 28 +
      Math.max(0, inputs.player.totalValue - inputs.enemy.totalValue) * 0.05 +
      (inputs.phase === "late" ? 24 : 0),
    researchScaleNeed:
      Math.max(0, economy.researchQueue.length - economy.researchCapacityLevel) * 28 +
      (inputs.phase === "early" ? 26 : inputs.phase === "mid" ? 18 : 12) +
      Math.max(0, reaperPipelineShortfall) * 12,
    specialPipelineNeed:
      missingSpecialCost > 0
        ? 80 + inputs.player.specialCount * 18 + Math.max(0, inputs.player.totalValue - inputs.enemy.totalValue) * 0.05
        : 0,
    reaperPipelineNeed:
      60 +
      missingDroneCost * 2 +
      reaperPipelineShortfall * 48 +
      gateIncomeDeficit * 10 +
      Math.max(0, inputs.player.specialCount) * 22 +
      Math.max(0, inputs.player.totalValue - inputs.enemy.totalValue) * 0.06,
    captureWinPressure:
      state.baseOccupation.Player * 150 +
      Math.max(0, inputs.enemy.captureCount - inputs.player.captureCount) * 18 -
      inputs.predictedPlayerBaseDefense * 0.15,
    lossRisk: lossRisk + totalGatePressure * 0.22,
    gateLockoutLeverage: inputs.gateLockoutLeverage
  };
}

function profileOpponent(
  state: GameState,
  playerIntel: PlayerUnitIntel[],
  player: ArmyComposition,
  playerGateCount: number,
  enemyGateCount: number
): OpponentProfile {
  const total = Math.max(1, player.totalCount);
  const gateIntent = playerIntel.filter((intel) => intel.likelyObjective === "WestGate" || intel.likelyObjective === "EastGate").length;
  const baseIntent = playerIntel.filter((intel) => intel.likelyObjective === "EnemyBase").length;
  const specialIntent = player.specialCount + playerIntel.filter((intel) => isSpecialUnit(intel.unit.type)).length;
  const playerBaseDefenders = playerIntel.filter((intel) => hexDistance(intel.predictedCoord, state.bases.Player) <= 10).length;
  const airBias = player.airCount / total;
  const groundBias = player.groundCount / total;
  const gateRush = gateIntent * 0.28 + Math.max(0, playerGateCount - enemyGateCount) * 0.4;
  const baseRush = baseIntent * 0.22 + state.baseOccupation.Enemy * 0.55;
  const turtle = playerBaseDefenders / total + (state.day > 10 && playerIntel.length <= 2 ? 0.25 : 0);
  const fastSpecial = specialIntent * 0.35 + (state.day <= 18 && player.specialCount > 0 ? 0.5 : 0);
  const economyFirst = playerGateCount * 0.28 + (state.day > 8 && player.totalCount < 5 ? 0.32 : 0);
  const scores: Record<OpponentProfileKind, number> = {
    AirHeavy: airBias,
    GroundHeavy: groundBias,
    GateRusher: gateRush,
    BaseRusher: baseRush,
    Turtle: turtle,
    FastSpecial: fastSpecial,
    EconomyFirst: economyFirst,
    Balanced: 0.35
  };
  const kind = (Object.keys(scores) as OpponentProfileKind[]).sort((first, second) => scores[second] - scores[first])[0];

  return {
    kind,
    airBias,
    groundBias,
    gateRush,
    baseRush,
    turtle,
    fastSpecial,
    economyFirst
  };
}

function chooseEnemyStrategyPlan(
  state: GameState,
  forecast: EnemyStrategicForecast,
  profile: OpponentProfile,
  inputs: {
    phase: GamePhase;
    player: ArmyComposition;
    enemy: ArmyComposition;
    predictedEnemyBasePressure: number;
  }
): EnemyStrategyPlan {
  const gateDisadvantage = getEnemyGateDisadvantage(state);
  const scores: Record<EnemyStrategyPlan, number> = {
    GateEconomy:
      profile.economyFirst * 55 +
      profile.gateRush * 44 +
      gateDisadvantage * 36 +
      forecast.gateLockoutLeverage * 0.76 +
      (!ownerControlsBothGates(state, "Enemy") ? forecast.captureWinPressure * 0.18 : 0) +
      Math.max(0, 18 - state.day) * 2,
    FastSpecialServices:
      (ownerHasBuilding(state, "Enemy", "Special Services") ? -80 : 45) +
      forecast.specialPipelineNeed * 0.55 +
      profile.fastSpecial * 110 +
      gateDisadvantage * 12,
    AirSuperiority: profile.airBias * 90 + inputs.player.highValueAirCount * 32 + gateDisadvantage * 26 + inputs.player.groundCount * 12,
    ReaperTechRush:
      forecast.reaperPipelineNeed +
      gateDisadvantage * 48 +
      (ownerHasBuilding(state, "Enemy", "Drone Factory") ? 28 : 0) +
      (ownerHasBuilding(state, "Enemy", "Special Services") ? 0 : -170) +
      (inputs.phase === "late" ? 45 : inputs.phase === "mid" ? 28 : 8),
    DefensiveEconomy: forecast.lossRisk * 0.58 + inputs.predictedEnemyBasePressure + profile.baseRush * 65 - gateDisadvantage * 38 - forecast.gateLockoutLeverage * 0.22,
    GroundCaptureSwarm:
      forecast.captureWinPressure +
      Math.max(0, inputs.enemy.captureCount - inputs.player.captureCount) * 20 +
      profile.turtle * 34 -
      (!ownerControlsBothGates(state, "Enemy") ? 130 : 0)
  };

  if (forecast.lossRisk > 220) {
    scores.DefensiveEconomy += 160;
  }

  return (Object.keys(scores) as EnemyStrategyPlan[]).sort((first, second) => scores[second] - scores[first])[0];
}

function getEnemyStrategyPlaybook(assessment: EnemyStrategicAssessment): EnemyStrategyPlaybook {
  switch (assessment.strategyPlan) {
    case "GateEconomy":
      return {
        plan: "GateEconomy",
        requiredBehaviors: ["WinHoldGates", "ProtectGateIncome"],
        gateEconomyPriority: 1.25,
        airCounterPriority: 0.35,
        antiAirDonationTolerance: 0.55,
        reaperTechPriority: 0.25,
        delayObjectiveClockOnly: false
      };
    case "AirSuperiority":
      return {
        plan: "AirSuperiority",
        requiredBehaviors: ["ProduceAirCounters", "DenyPlayerAir", "AvoidAntiAirDonations"],
        gateEconomyPriority: 0.45,
        airCounterPriority: 1.35,
        antiAirDonationTolerance: 0.18,
        reaperTechPriority: 0.35,
        delayObjectiveClockOnly: false
      };
    case "ReaperTechRush":
      return {
        plan: "ReaperTechRush",
        requiredBehaviors: ["UnlockDroneFactory", "DelayObjectiveClock", "AvoidNonDelayingSpend"],
        gateEconomyPriority: 0.55,
        airCounterPriority: 0.55,
        antiAirDonationTolerance: 0.35,
        reaperTechPriority: 1.45,
        delayObjectiveClockOnly: true
      };
    default:
      return {
        plan: assessment.strategyPlan,
        requiredBehaviors: [],
        gateEconomyPriority: 0.75,
        airCounterPriority: 0.75,
        antiAirDonationTolerance: 0.5,
        reaperTechPriority: 0.5,
        delayObjectiveClockOnly: false
      };
  }
}

function buildEnemyBudgetReserve(
  state: GameState,
  forecast: EnemyStrategicForecast,
  plan: EnemyStrategyPlan,
  profile: OpponentProfile
): EnemyBudgetReserve {
  const emergencyDefense = forecast.lossRisk > 160 ? Math.min(46, 12 + forecast.lossRisk * 0.1) : 8;
  const economy = Math.min(42, Math.max(0, forecast.economyInvestmentNeed * 0.18 + (profile.economyFirst > 0.5 ? 10 : 0)));
  const tech = Math.min(
    54,
    (ownerHasBuilding(state, "Enemy", "Special Services") ? 0 : getResearchCost("UnlockSpecialServices", undefined, state.enemyEconomy)) +
      (plan === "FastSpecialServices" ? 12 : 0)
  );
  const reaper = Math.min(
    70,
    (ownerHasBuilding(state, "Enemy", "Drone Factory") ? getProductionCost("Reaper") : getResearchCost("UnlockDroneFactory", undefined, state.enemyEconomy)) +
      (plan === "ReaperTechRush" ? 16 : 0)
  );
  const capture = plan === "GroundCaptureSwarm" || plan === "GateEconomy" ? 18 : 8;
  return {
    emergencyDefense,
    economy,
    tech,
    reaper,
    capture,
    total: Math.min(112, Math.max(emergencyDefense, economy, tech, reaper, capture, forecast.desiredWarChest * 0.45))
  };
}

function buildEnemyInfluenceMap(state: GameState, playerIntel: PlayerUnitIntel[], forecast: EnemyStrategicForecast): InfluenceMap {
  const map: InfluenceMap = {};
  const visible = getEnemyVisibleHexIds(state);
  for (const hex of state.map.hexes) {
    const threat = playerIntel.reduce((total, intel) => {
      const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, intel.predictedCoord, hex.coord);
      const distance = hexDistance(hex.coord, intel.predictedCoord);
      if (distance <= stats.attackRange) {
        return total + getUnitInstanceValue(state, intel.unit) * 0.22 * intel.confidence;
      }
      if (distance <= stats.attackRange + stats.moveRange) {
        return total + getUnitInstanceValue(state, intel.unit) * 0.1 * intel.confidence;
      }
      return total;
    }, 0);
    const support = getOwnerUnits(state, "Enemy").reduce((total, unit) => {
      const distance = hexDistance(hex.coord, unit.coord);
      return total + (distance <= 2 ? 18 : distance <= 5 ? 7 : 0);
    }, 0);
    const gate = (state.gates ?? []).reduce((total, gateState) => {
      const distance = hexDistance(hex.coord, gateState.coord);
      if (distance > 5) {
        return total;
      }
      const ownerBonus = gateState.owner === "Enemy" ? 28 : gateState.owner === "Player" ? 44 : 32;
      return total + Math.max(0, 6 - distance) * ownerBonus;
    }, 0);
    const objective =
      Math.max(0, state.map.height - hexDistance(hex.coord, state.bases.Player)) * 1.2 +
      Math.max(0, 8 - hexDistance(hex.coord, state.bases.Enemy)) * (forecast.lossRisk > 160 ? 18 : 2);
    const repair = isOwnerBackRow(state, "Enemy", hex.coord) ? 60 : Math.max(0, 4 - hex.coord.r) * 8;

    map[hex.id] = {
      coord: { ...hex.coord },
      threat,
      support,
      vision: visible.has(hex.id) ? 0 : 16,
      gate,
      objective,
      repair
    };
  }
  return map;
}

function scorePredictedEnemyBasePressure(state: GameState, playerIntel: PlayerUnitIntel[]): number {
  return playerIntel.reduce((score, intel) => {
    const definition = getUnitDefinition(intel.unit.type);
    const distance = hexDistance(intel.predictedCoord, state.bases.Enemy);
    const capturePressure = definition.humanBased ? Math.max(0, getEnemyBaseResponseRadius(state) + 2 - distance) * 28 : 0;
    const firePressure = canUnitProjectThreatToCoord(state, intel.unit, intel.predictedCoord, state.bases.Enemy)
      ? getUnitInstanceValue(state, intel.unit) * 0.12
      : 0;
    return score + (capturePressure + firePressure) * intel.confidence;
  }, 0);
}

function scorePredictedGatePressure(state: GameState, playerIntel: PlayerUnitIntel[]): Partial<Record<GateState["id"], number>> {
  const pressure: Partial<Record<GateState["id"], number>> = {};
  for (const gate of state.gates ?? []) {
    pressure[gate.id] = playerIntel.reduce((score, intel) => {
      const definition = getUnitDefinition(intel.unit.type);
      const distance = hexDistance(intel.predictedCoord, gate.coord);
      const capturePressure = definition.humanBased ? Math.max(0, 8 - distance) * 22 : 0;
      const firePressure = canUnitProjectThreatToCoord(state, intel.unit, intel.predictedCoord, gate.coord)
        ? getUnitInstanceValue(state, intel.unit) * 0.08
        : 0;
      const objectivePressure =
        (gate.id === "West" && intel.likelyObjective === "WestGate") || (gate.id === "East" && intel.likelyObjective === "EastGate")
          ? 55
          : 0;
      return score + (capturePressure + firePressure + objectivePressure) * intel.confidence;
    }, 0);
  }
  return pressure;
}

function estimateGateTheatrePower(state: GameState, owner: Owner, gate: GateState, radius = 9, playerIntel = getPlayerIntelForEnemy(state)): GateTheatrePower {
  const empty: GateTheatrePower = {
    owner,
    gateId: gate.id,
    radius,
    total: 0,
    combat: 0,
    capture: 0,
    artillery: 0,
    armor: 0,
    antiAir: 0,
    air: 0,
    support: 0,
    unitCount: 0,
    damagedPenalty: 0
  };

  const add = (unit: UnitInstance, coord: UnitInstance["coord"], confidence: number): void => {
    const contribution = estimateGateTheatreUnitPower(state, unit, coord, gate, radius) * confidence;
    if (contribution <= 0) {
      return;
    }

    const definition = getUnitDefinition(unit.type);
    const healthRatio = unit.health / Math.max(1, unit.maxHealth);
    empty.unitCount += confidence;
    empty.combat += contribution;
    empty.capture += definition.humanBased ? contribution * 0.72 : 0;
    empty.artillery += unit.type === "Artillery" || unit.type === "Reaper" ? contribution : 0;
    empty.armor += unit.type === "Tank" || unit.type === "IFV" ? contribution : 0;
    empty.antiAir += canCounterAir(unit.type) ? contribution : 0;
    empty.air += definition.domain === "Air" ? contribution : 0;
    empty.support += (isReconUnit(unit.type) ? 0.34 : needsReconSupport(unit.type) ? 0.22 : 0.12) * contribution;
    empty.damagedPenalty += Math.max(0, 0.55 - healthRatio) * getUnitTypeValue(state, unit.owner, unit.type, unit.level) * confidence;
  };

  if (owner === "Player") {
    playerIntel.forEach((intel) => add(intel.unit, intel.predictedCoord, intel.confidence));
  } else {
    getOwnerUnits(state, owner).forEach((unit) => add(unit, unit.coord, 1));
  }

  empty.total =
    empty.combat +
    empty.capture * 0.38 +
    empty.artillery * 0.26 +
    empty.armor * 0.18 +
    empty.antiAir * 0.14 +
    empty.air * 0.2 +
    empty.support -
    empty.damagedPenalty * 0.45;
  return empty;
}

function estimateGateTheatreUnitPower(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState,
  radius: number
): number {
  const definition = getUnitDefinition(unit.type);
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, gate.coord);
  const distance = hexDistance(coord, gate.coord);
  const projection = stats.attackRange + Math.floor(stats.moveRange * 0.65);
  const reachDistance = Math.max(0, distance - radius);
  if (reachDistance > projection + 4) {
    return 0;
  }

  const value = getUnitInstanceValue(state, unit);
  const distanceMultiplier =
    distance <= radius
      ? 1
      : reachDistance <= stats.attackRange
        ? 0.72
        : reachDistance <= projection
          ? 0.46
          : 0.22;
  const roleMultiplier =
    unit.type === "Artillery"
      ? 1.34
      : unit.type === "Tank"
        ? 1.26
        : unit.type === "IFV"
          ? 1.16
          : unit.type === "Reaper"
            ? 1.3
            : unit.type === "Bomber" || unit.type === "Attack Heli"
              ? 1.16
              : unit.type === "Anti-Air"
                ? 0.92
                : definition.humanBased
                  ? 0.98
                  : 1;
  const capturePresence = definition.humanBased && distance <= radius + stats.moveRange ? 26 : 0;
  const fireProjection = stats.attackRange >= 5 || needsReconSupport(unit.type) ? 1.12 : 1;
  return (value * roleMultiplier * fireProjection + capturePresence) * distanceMultiplier;
}

function estimateGateTheatrePressure(state: GameState, gate: GateState, radius = 9, playerIntel = getPlayerIntelForEnemy(state)): GateTheatrePressure {
  const enemy = estimateGateTheatrePower(state, "Enemy", gate, radius, playerIntel);
  const player = estimateGateTheatrePower(state, "Player", gate, radius, playerIntel);
  const balance = enemy.total - player.total;
  const ratio = enemy.total / Math.max(1, player.total);
  const enemyCaptureReady = enemy.capture > 28 || (state.gates ?? []).some((candidate) => candidate.id === gate.id && candidate.occupation.Enemy > 0);
  const playerFortified = player.total > 260 && player.total > enemy.total * 1.35;
  return {
    gateId: gate.id,
    radius,
    enemy,
    player,
    balance,
    ratio,
    recaptureFeasible: enemyCaptureReady && !playerFortified && (ratio >= 0.72 || balance > -110 || gate.occupation.Enemy > 0),
    contested: gate.occupation.Player > 0 || gate.occupation.Enemy > 0 || player.capture > 35 || enemy.capture > 35
  };
}

function isGateSafeForRecapture(state: GameState, gate: GateState, capturer: UnitInstance, plan: EnemyTurnPlan): boolean {
  if (gate.owner === "Enemy" || !getUnitDefinition(capturer.type).humanBased) {
    return true;
  }

  const projectedCapturer: UnitInstance = { ...capturer, coord: { ...gate.coord } };
  const predictedDamage = estimatePredictedPlayerDamageToEnemyAtCoord(state, projectedCapturer, gate.coord, plan);
  const healthBuffer = Math.max(3, projectedCapturer.health * 0.18);
  const coveredStaleRisk = shouldEnemyGateCaptureTrustCoveredStaleIntel(state, gate, projectedCapturer, plan);
  const radius = 7;
  const theatre = estimateGateTheatrePressure(state, gate, radius, plan.playerIntel);
  const capturerContribution = estimateGateTheatreUnitPower(state, projectedCapturer, gate.coord, gate, radius);
  const enemyLocalPower = theatre.enemy.total + capturerContribution * 1.12;
  const playerLocalPower = theatre.player.total;
  const gateThreats = countPlayerGateRecaptureThreats(state, gate, projectedCapturer, plan);
  const enemyBlockers = countEnemyGateBlockers(state, gate, capturer);
  const coverPower = estimateEnemyGateCaptureCoverPower(state, gate, projectedCapturer);

  if (
    isEnemyGateRecaptureCommitmentRiskJustified(
      state,
      gate,
      projectedCapturer,
      plan,
      predictedDamage,
      playerLocalPower,
      enemyLocalPower,
      gateThreats,
      enemyBlockers,
      coverPower
    )
  ) {
    return true;
  }

  if (predictedDamage >= projectedCapturer.health - healthBuffer) {
    return coveredStaleRisk;
  }

  if (playerLocalPower > enemyLocalPower * 1.08 + 42) {
    return coveredStaleRisk;
  }

  if (gateThreats >= 3 && gateThreats > enemyBlockers + 1) {
    return coveredStaleRisk;
  }

  if (gateThreats >= 2 && predictedDamage >= projectedCapturer.health * 0.72 && playerLocalPower > enemyLocalPower * 0.82) {
    return coveredStaleRisk;
  }

  return true;
}

function isEnemyGateRecaptureCommitmentRiskJustified(
  state: GameState,
  gate: GateState,
  capturer: UnitInstance,
  plan: EnemyTurnPlan,
  predictedDamage: number,
  playerLocalPower: number,
  enemyLocalPower: number,
  gateThreats: number,
  enemyBlockers: number,
  coverPower: number
): boolean {
  if (state.difficulty !== "Hard" || gate.owner === "Enemy" || !isEnemyGateFightCommitmentPhase(plan.campaignPlan.phase)) {
    return false;
  }
  if (isActiveEnemyBaseThreat(state, getEnemyBaseThreat(state))) {
    return false;
  }

  const health = Math.max(1, capturer.health);
  const strategicPressure =
    plan.campaignPlan.phase === "GateLockoutCombat" ||
    gate.occupation.Player > 0 ||
    gate.occupation.Enemy > 0 ||
    scoreEnemyGateLockoutCombatPressure(state, plan.playerIntel) >= ENEMY_GATE_LOCKOUT_COMBAT_PRESSURE_THRESHOLD * 0.72;
  if (!strategicPressure) {
    return false;
  }

  const localCover = enemyBlockers >= 2 || coverPower >= 175 || enemyLocalPower >= playerLocalPower * 0.55;
  if (!localCover) {
    return false;
  }

  const overwhelmingThreat = predictedDamage > health * 1.45 || playerLocalPower > enemyLocalPower * 1.65 + coverPower * 0.25 + 120 || gateThreats > enemyBlockers + 3;
  return !overwhelmingThreat;
}

function estimatePredictedPlayerDamageToEnemyAtCoord(
  state: GameState,
  enemyUnit: UnitInstance,
  coord: UnitInstance["coord"],
  plan: EnemyTurnPlan
): number {
  return estimatePredictedPlayerDamageToEnemyAtCoordFromIntel(state, enemyUnit, coord, plan.playerIntel);
}

function estimatePredictedPlayerDamageToEnemyAtCoordFromIntel(
  state: GameState,
  enemyUnit: UnitInstance,
  coord: UnitInstance["coord"],
  playerIntel: PlayerUnitIntel[]
): number {
  return playerIntel.reduce((totalDamage, intel) => {
    if (!canUnitTargetUnit(intel.unit.type, enemyUnit.type)) {
      return totalDamage;
    }

    const damage = estimateAttackDamage(state, { ...intel.unit, coord: { ...intel.predictedCoord } }, enemyUnit);
    const beliefs =
      "currentBeliefs" in intel
        ? (intel as EnemyPlannerPlayerIntel).currentBeliefs
        : [{ coord: intel.predictedCoord, weight: 1 }];
    const threat = beliefs.reduce(
      (total, belief) => {
        const stats = getEffectiveUnitStats(state, intel.unit.owner, intel.unit.type, intel.unit.level, belief.coord, coord);
        const distance = hexDistance(belief.coord, coord);
        if (distance <= stats.attackRange) {
          return total + damage * belief.weight;
        }
        if (!getUnitDefinition(intel.unit.type).cannotMoveAndAttack && distance <= stats.attackRange + stats.moveRange) {
          return total + damage * 0.82 * belief.weight;
        }
        return total;
      },
      0
    );
    return totalDamage + threat * intel.confidence;
  }, 0);
}

function countPlayerGateRecaptureThreats(state: GameState, gate: GateState, capturer: UnitInstance, plan: EnemyTurnPlan): number {
  return countPlayerGateRecaptureThreatsFromIntel(state, gate, capturer, plan.playerIntel);
}

function countPlayerGateRecaptureThreatsFromIntel(
  state: GameState,
  gate: GateState,
  capturer: UnitInstance,
  playerIntel: PlayerUnitIntel[]
): number {
  return playerIntel.reduce((count, intel) => {
    const unit = { ...intel.unit, coord: { ...intel.predictedCoord } };
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
    const threatReach = stats.attackRange + (getUnitDefinition(unit.type).cannotMoveAndAttack ? 0 : stats.moveRange);
    const canThreatenCapturer = canUnitTargetUnit(unit.type, capturer.type) && hexDistance(unit.coord, gate.coord) <= threatReach;
    const canBlockGate = getUnitDefinition(unit.type).humanBased && hexDistance(unit.coord, gate.coord) <= stats.moveRange + 1;
    return count + ((canThreatenCapturer || canBlockGate) && intel.confidence >= 0.45 ? 1 : 0);
  }, 0);
}

function countEnemyGateBlockers(state: GameState, gate: GateState, capturer: UnitInstance): number {
  return getOwnerUnits(state, "Enemy").filter((unit) => {
    if (unit.id === capturer.id || unit.health / Math.max(1, unit.maxHealth) <= 0.35) {
      return false;
    }
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
    const distance = hexDistance(unit.coord, gate.coord);
    const groundBlocker = getUnitDefinition(unit.type).domain === "Ground" && distance <= 2;
    const fireCover = distance <= stats.attackRange + Math.floor(stats.moveRange * 0.5);
    return groundBlocker || fireCover;
  }).length;
}

function isFreshEnemyPlannerPlayerIntel(intel: PlayerUnitIntel): intel is EnemyPlannerPlayerIntel {
  return "observedCoord" in intel && Boolean((intel as EnemyPlannerPlayerIntel).observedCoord) && intel.age === 0;
}

function estimateEnemyGateCaptureCoverPower(state: GameState, gate: GateState, capturer: UnitInstance): number {
  return getOwnerUnits(state, "Enemy").reduce((power, unit) => {
    if (unit.id === capturer.id || unit.health / Math.max(1, unit.maxHealth) <= 0.35) {
      return power;
    }
    const distance = hexDistance(unit.coord, gate.coord);
    if (distance > 5) {
      return power;
    }
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
    const canCoverGate = getUnitDefinition(unit.type).domain === "Ground" && distance <= 2;
    const canProjectFire = canUnitTargetUnit(unit.type, capturer.type) && distance <= stats.attackRange + Math.floor(stats.moveRange * 0.5);
    if (!canCoverGate && !canProjectFire) {
      return power;
    }
    return power + estimateGateTheatreUnitPower(state, unit, unit.coord, gate, 5);
  }, 0);
}

function shouldEnemyGateCaptureTrustCoveredStaleIntel(
  state: GameState,
  gate: GateState,
  capturer: UnitInstance,
  plan: EnemyTurnPlan
): boolean {
  if (gate.owner === "Enemy" || !getUnitDefinition(capturer.type).humanBased) {
    return false;
  }

  const unconfirmedIntel = plan.playerIntel.filter((intel) => !isFreshEnemyPlannerPlayerIntel(intel));
  if (!unconfirmedIntel.length) {
    return false;
  }

  const projectedCapturer: UnitInstance = { ...capturer, coord: { ...gate.coord } };
  const freshIntel = plan.playerIntel.filter(isFreshEnemyPlannerPlayerIntel);
  const freshDamage = estimatePredictedPlayerDamageToEnemyAtCoordFromIntel(state, projectedCapturer, gate.coord, freshIntel);
  const healthBuffer = Math.max(3, projectedCapturer.health * 0.18);
  if (freshDamage >= projectedCapturer.health - healthBuffer) {
    return false;
  }

  const freshThreats = countPlayerGateRecaptureThreatsFromIntel(state, gate, projectedCapturer, freshIntel);
  if (freshThreats >= 2) {
    return false;
  }

  const radius = 7;
  const freshTheatre = estimateGateTheatrePressure(state, gate, radius, freshIntel);
  const capturerContribution = estimateGateTheatreUnitPower(state, projectedCapturer, gate.coord, gate, radius);
  const freshEnemyLocalPower = freshTheatre.enemy.total + capturerContribution * 1.12;
  if (freshTheatre.player.total > freshEnemyLocalPower * 0.92 + 65) {
    return false;
  }

  const blockers = countEnemyGateBlockers(state, gate, projectedCapturer);
  const coverPower = estimateEnemyGateCaptureCoverPower(state, gate, projectedCapturer);
  return blockers >= 3 || coverPower >= 300 || (blockers >= 2 && coverPower >= 190);
}

function chooseEnemyCounterattackGate(state: GameState, radius = 9, playerIntel = getPlayerIntelForEnemy(state)): GateState | undefined {
  return [...(state.gates ?? [])]
    .filter((gate) => gate.owner !== "Enemy")
    .map((gate) => {
      const theatre = estimateGateTheatrePressure(state, gate, radius, playerIntel);
      const assessment = getEnemyStrategicAssessment(state);
      const urgency = (assessment.gateCaptureOpportunity[gate.id] ?? 0) + gate.occupation.Enemy * 120 - gate.occupation.Player * 90;
      const feasibilityBonus = theatre.recaptureFeasible ? 260 : -180;
      const score = theatre.balance + theatre.enemy.capture * 0.5 - theatre.player.capture * 0.4 + urgency + feasibilityBonus;
      return { gate, theatre, score };
    })
    .filter((entry) => entry.theatre.recaptureFeasible || entry.theatre.enemy.total > entry.theatre.player.total * 0.55)
    .sort((first, second) => second.score - first.score || first.gate.id.localeCompare(second.gate.id))[0]?.gate;
}

function chooseEnemyGateLockoutCounterattackGate(state: GameState, plan?: { campaignPlan?: EnemyCampaignPlan }): GateState | undefined {
  const gates = state.gates ?? [];
  const byId = (gateId?: GateState["id"]): GateState | undefined => gateId ? gates.find((gate) => gate.id === gateId) : undefined;
  return (
    chooseEnemyCounterattackGate(state) ??
    byId(plan?.campaignPlan?.mainEffortGateId) ??
    gates
      .filter((gate) => gate.owner !== "Enemy")
      .sort((first, second) => scoreEnemyGateRoleObjective(state, second) - scoreEnemyGateRoleObjective(state, first) || first.id.localeCompare(second.id))[0]
  );
}

function chooseEnemyGateLockoutRoleTargetCoord(
  state: GameState,
  unit: UnitInstance,
  mission: EnemyMission,
  plan?: EnemyTurnPlan
): UnitInstance["coord"] | undefined {
  const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
  if (!gate) {
    return undefined;
  }

  if (mission === "ReserveCapturer") {
    return chooseEnemyGateLockoutStagingCoord(state, unit, gate, 2, 4, plan);
  }
  if (mission === "SuppressGateZone") {
    const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord, gate.coord);
    return chooseEnemyGateLockoutStagingCoord(state, unit, gate, Math.max(2, Math.min(6, stats.attackRange)), Math.max(4, stats.attackRange + 1), plan, {
      requireGateTarget: true
    });
  }
  if (mission === "CoverCounterattack") {
    return chooseEnemyGateLockoutStagingCoord(state, unit, gate, 2, 5, plan, { requireGateTarget: true });
  }
  if (mission === "ClearGateApproach") {
    return chooseEnemyGateLockoutStagingCoord(state, unit, gate, 1, 3, plan, { requireGateTarget: true });
  }
  return gate.coord;
}

function chooseEnemyGateLockoutStagingCoord(
  state: GameState,
  unit: UnitInstance,
  gate: GateState,
  minDistance: number,
  maxDistance: number,
  plan?: EnemyTurnPlan,
  options: { requireGateTarget?: boolean } = {}
): UnitInstance["coord"] | undefined {
  const currentDistance = hexDistance(unit.coord, gate.coord);
  if (
    currentDistance >= minDistance &&
    currentDistance <= maxDistance &&
    !sameHex(unit.coord, gate.coord) &&
    (!options.requireGateTarget || canEnemyGateSupportPositionTargetGate(state, unit, unit.coord, gate))
  ) {
    return unit.coord;
  }

  const desiredDistance = Math.max(minDistance, Math.min(maxDistance, Math.round((minDistance + maxDistance) / 2)));
  let best: { coord: UnitInstance["coord"]; score: number; id: string } | undefined;
  const canStageOnGate = getUnitDefinition(unit.type).humanBased;
  const minQ = Math.max(0, gate.coord.q - maxDistance);
  const maxQ = Math.min(state.map.width - 1, gate.coord.q + maxDistance);
  const minR = Math.max(0, gate.coord.r - maxDistance);
  const maxR = Math.min(state.map.height - 1, gate.coord.r + maxDistance);
  for (let r = minR; r <= maxR; r += 1) {
    for (let q = minQ; q <= maxQ; q += 1) {
      const hex = getHex(state.map, { q, r });
      if (!hex) {
        continue;
      }

      const coord = hex.coord;
      if (!hex.passable || (!canStageOnGate && sameHex(coord, gate.coord))) {
        continue;
      }

      const distance = hexDistance(coord, gate.coord);
      if (distance < minDistance || distance > maxDistance) {
        continue;
      }
      if (options.requireGateTarget && !canEnemyGateSupportPositionTargetGate(state, unit, coord, gate)) {
        continue;
      }

      const score = scoreEnemyGateLockoutStagingCoord(state, unit, coord, gate, desiredDistance, plan);
      const id = hex.id;
      if (!best || score > best.score || (score === best.score && id.localeCompare(best.id) < 0)) {
        best = { coord, score, id };
      }
    }
  }

  return best?.coord ?? (options.requireGateTarget ? undefined : gate.coord);
}

function scoreEnemyGateLockoutStagingCoord(
  state: GameState,
  unit: UnitInstance,
  coord: UnitInstance["coord"],
  gate: GateState,
  desiredDistance: number,
  plan?: EnemyTurnPlan
): number {
  const gateDistance = hexDistance(coord, gate.coord);
  const currentTravel = hexDistance(unit.coord, gate.coord);
  const nextTravel = hexDistance(coord, gate.coord);
  const danger = plan ? estimatePlayerDangerAtPlanner(state, unit, coord, plan) : estimatePlayerDangerAt(state, unit, coord);
  const support = getOwnerUnits(state, "Enemy")
    .filter((ally) => ally.id !== unit.id)
    .reduce((total, ally) => total + Math.max(0, 5 - hexDistance(coord, ally.coord)) * (isEnemyGateLockoutCombatUnit(ally.type) ? 5 : 2), 0);
  const enemySideBias = Math.max(0, hexDistance(coord, state.bases.Player) - hexDistance(coord, state.bases.Enemy)) * 2;
  return (
    Math.max(-2, currentTravel - nextTravel) * 42 +
    support +
    enemySideBias -
    Math.abs(gateDistance - desiredDistance) * 34 -
    danger * 0.58
  );
}

function scoreEnemyGateCaptureOpportunity(state: GameState, playerIntel: PlayerUnitIntel[]): Partial<Record<GateState["id"], number>> {
  const opportunities: Partial<Record<GateState["id"], number>> = {};
  const capturers = getOwnerUnits(state, "Enemy").filter((unit) => getUnitDefinition(unit.type).humanBased);
  for (const gate of state.gates ?? []) {
    if (gate.owner === "Enemy") {
      opportunities[gate.id] = 0;
      continue;
    }

    const nearestCapturerDistance = capturers.reduce(
      (best, unit) => Math.min(best, hexDistance(unit.coord, gate.coord)),
      Number.POSITIVE_INFINITY
    );
    const enemyLocalForce = getOwnerUnits(state, "Enemy").reduce((total, unit) => {
      const distance = hexDistance(unit.coord, gate.coord);
      return total + (distance <= 5 ? getUnitInstanceValue(state, unit) * 0.42 : distance <= 9 ? getUnitInstanceValue(state, unit) * 0.18 : 0);
    }, 0);
    const playerLocalForce = playerIntel.reduce((total, intel) => {
      const distance = hexDistance(intel.predictedCoord, gate.coord);
      return total + (distance <= 5 ? getUnitInstanceValue(state, intel.unit) * 0.48 : distance <= 9 ? getUnitInstanceValue(state, intel.unit) * 0.24 : 0) * intel.confidence;
    }, 0);
    const weakDefenseBonus = Math.max(0, 130 - playerLocalForce);
    const localAdvantage = Math.max(-120, enemyLocalForce - playerLocalForce);
    const theatre = estimateGateTheatrePressure(state, gate, 9, playerIntel);
    const theatreAdvantage = Math.max(-220, Math.min(220, theatre.balance));
    const theatreFeasibility = theatre.recaptureFeasible ? 95 : gate.owner === "Player" ? -130 : -55;
    const approachBonus = Math.max(0, 16 - nearestCapturerDistance) * 12;
    const ownershipBonus = gate.owner === null ? 55 : 92;
    const holdBonus = gate.occupation.Enemy * 50 - gate.occupation.Player * 46;
    const wouldControlBothGates = (state.gates ?? []).filter((candidate) => candidate.id !== gate.id).every((candidate) => candidate.owner === "Enemy");
    const lockoutOpportunity = getEnemyGateLockoutOpportunityScore(state, gate, playerIntel);
    const lockoutBonus = lockoutOpportunity.total > 0
      ? lockoutOpportunity.total * (wouldControlBothGates ? 1.18 : gate.owner === "Player" ? 0.68 : 0.42) + (wouldControlBothGates ? 130 : 0)
      : 0;
    opportunities[gate.id] = ownershipBonus + weakDefenseBonus + localAdvantage * 0.45 + theatreAdvantage * 0.62 + theatreFeasibility + approachBonus + holdBonus + lockoutBonus;
  }
  return opportunities;
}

function scorePlayerBaseVulnerability(state: GameState, playerIntel: PlayerUnitIntel[]): number {
  const enemyCapturers = getOwnerUnits(state, "Enemy").filter((unit) => getUnitDefinition(unit.type).humanBased);
  const nearestCapturerDistance = enemyCapturers.reduce(
    (best, unit) => Math.min(best, hexDistance(unit.coord, state.bases.Player)),
    Number.POSITIVE_INFINITY
  );
  const enemyAttackForce = getOwnerUnits(state, "Enemy").reduce((total, unit) => {
    const distance = hexDistance(unit.coord, state.bases.Player);
    return total + (distance <= 8 ? getUnitInstanceValue(state, unit) * 0.32 : distance <= 14 ? getUnitInstanceValue(state, unit) * 0.14 : 0);
  }, 0);
  const playerDefenderForce = playerIntel.reduce((total, intel) => {
    const distance = hexDistance(intel.predictedCoord, state.bases.Player);
    return total + (distance <= 7 ? getUnitInstanceValue(state, intel.unit) * 0.55 : distance <= 12 ? getUnitInstanceValue(state, intel.unit) * 0.22 : 0) * intel.confidence;
  }, 0);
  const weakDefenseBonus = Math.max(0, 170 - playerDefenderForce);
  const capturerAccess = Math.max(0, 22 - nearestCapturerDistance) * 9;
  const flankOpening = Math.max(scorePlayerBaseFlankOpening(state, playerIntel, "West"), scorePlayerBaseFlankOpening(state, playerIntel, "East"));
  const activeCaptureBonus = state.baseOccupation.Player * 85;
  return weakDefenseBonus + Math.max(-90, enemyAttackForce - playerDefenderForce) * 0.55 + capturerAccess + flankOpening + activeCaptureBonus;
}

function scorePlayerBaseFlankOpening(state: GameState, playerIntel: PlayerUnitIntel[], lane: GateState["id"]): number {
  const laneHexes = getGateSideHexes(state, {
    id: lane,
    label: `${lane} lane`,
    coord: lane === "West" ? { q: 0, r: state.bases.Player.r } : { q: state.map.width - 1, r: state.bases.Player.r },
    owner: null,
    knownOwner: null,
    occupation: { Player: 0, Enemy: 0 }
  });
  const laneEnemyForce = getOwnerUnits(state, "Enemy")
    .filter((unit) => laneHexes.has(hexId(unit.coord)))
    .reduce((total, unit) => total + getUnitInstanceValue(state, unit) * 0.18, 0);
  const lanePlayerForce = playerIntel
    .filter((intel) => laneHexes.has(hexId(intel.predictedCoord)))
    .reduce((total, intel) => total + getUnitInstanceValue(state, intel.unit) * 0.24 * intel.confidence, 0);
  return Math.max(0, 85 + laneEnemyForce - lanePlayerForce * 1.4);
}

function canUnitProjectThreatToCoord(
  state: GameState,
  unit: UnitInstance,
  projectedCoord: UnitInstance["coord"],
  targetCoord: UnitInstance["coord"]
): boolean {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, projectedCoord, targetCoord);
  return hexDistance(projectedCoord, targetCoord) <= stats.attackRange + stats.moveRange;
}

function summarizeArmy(state: GameState, units: UnitInstance[]): ArmyComposition {
  return units.reduce(
    (summary, unit) => {
      const definition = getUnitDefinition(unit.type);
      const value = getUnitInstanceValue(state, unit);
      summary.totalCount += 1;
      summary.totalValue += value;
      summary.groundCount += definition.domain === "Ground" ? 1 : 0;
      summary.airCount += definition.domain === "Air" ? 1 : 0;
      summary.captureCount += definition.humanBased ? 1 : 0;
      summary.antiAirCount += canCounterAir(unit.type) ? 1 : 0;
      summary.scoutCount += isReconUnit(unit.type) ? 1 : 0;
      summary.artillerySupportCount += needsReconSupport(unit.type) ? 1 : 0;
      summary.specialCount += isSpecialUnit(unit.type) ? 1 : 0;
      summary.highValueAirCount += unit.type === "Jet" || unit.type === "Bomber" || unit.type === "Reaper" ? 1 : 0;
      summary.reaperCount += unit.type === "Reaper" ? 1 : 0;
      return summary;
    },
    {
      totalCount: 0,
      totalValue: 0,
      groundCount: 0,
      airCount: 0,
      captureCount: 0,
      antiAirCount: 0,
      scoutCount: 0,
      artillerySupportCount: 0,
      specialCount: 0,
      highValueAirCount: 0,
      reaperCount: 0
    } satisfies ArmyComposition
  );
}

function isReconUnit(unitType: UnitType): boolean {
  return ["IFV", "Attack Heli", "Jet", "Bomber", "Ghost", "Spectral", "Reaper"].includes(unitType);
}

function isEnemySupplySupportUnit(unitType: UnitType): boolean {
  return isSupplyPlacementProvider(unitType);
}

function isEnemyCommandHelicopter(unitType: UnitType): boolean {
  return unitType === "Command Heli";
}

function isEnemyFieldSupportUnit(unitType: UnitType): boolean {
  return ENEMY_FIELD_SUPPORT_UNIT_TYPES.includes(unitType);
}

function hasEnemyFieldedSupportUnit(state: GameState): boolean {
  return getOwnerUnits(state, "Enemy").some((unit) => unit.health > 0 && isEnemyFieldSupportUnit(unit.type));
}

function getEnemyFieldSupportPipelineCount(state: GameState): number {
  const inventory = ENEMY_FIELD_SUPPORT_UNIT_TYPES.reduce((total, unitType) => total + getEnemyInventoryHardLimitCount(state, unitType), 0);
  const queued = state.enemyEconomy.productionQueue.filter((job) => job.owner === "Enemy" && isEnemyFieldSupportUnit(job.unitType)).length;
  return inventory + queued;
}

function isEnemyMissingFieldSupportProduction(state: GameState): boolean {
  return !hasEnemyFieldedSupportUnit(state) && getEnemyFieldSupportPipelineCount(state) <= 0;
}

function isEnemyRequiredFieldSupportProductionUnit(state: GameState, unitType: UnitType): boolean {
  return isEnemyMissingFieldSupportProduction(state) && isEnemyFieldSupportUnit(unitType);
}

function needsReconSupport(unitType: UnitType): boolean {
  return ["Anti-Air", "Artillery", "Tank", "Operator"].includes(unitType);
}

function isSpecialUnit(unitType: UnitType): boolean {
  return ["Operator", "Ghost", "Spectral", "Reaper"].includes(unitType);
}

function getEnemyProductionReserve(state: GameState): number {
  return 0;
}

function getEnemyCriticalTechReserve(state: GameState, assessment = getEnemyStrategicAssessment(state)): number {
  return 0;
}

function shouldHardAiSpendDownForArmy(state: GameState, assessment: EnemyStrategicAssessment): boolean {
  const nearReaperWarChest =
    ownerHasBuilding(state, "Enemy", "Drone Factory") && canEnemyAffordProductionUnit(state, "Reaper");
  if (nearReaperWarChest) {
    return false;
  }

  const fielded = getOwnerUnits(state, "Enemy").length;
  const inventory = ENEMY_UNIT_TYPES.reduce((total, unitType) => total + state.enemyEconomy.inventory[unitType], 0);
  const queued = state.enemyEconomy.productionQueue.length;
  const desiredArmyPipeline = assessment.phase === "early" ? 12 : assessment.phase === "mid" ? 15 : 18;
  return fielded + inventory * 0.7 + queued * 0.9 < desiredArmyPipeline;
}

function getEnemyCaptureNeed(state: GameState): number {
  const capturePresence = getEnemyEffectiveCapturePresence(state);
  const enemyCapturing = getOwnerUnits(state, "Enemy").some((unit) => getUnitDefinition(unit.type).humanBased && sameHex(unit.coord, state.bases.Player));
  const desiredCapturePressure = state.difficulty === "Hard" ? (enemyCapturing ? 4 : 7) : (enemyCapturing ? 3 : 6);
  return Math.max(0, desiredCapturePressure - capturePresence);
}

function getEnemyEffectiveCapturePresence(state: GameState): number {
  const activeCapturePressure = getOwnerUnits(state, "Enemy")
    .filter((unit) => getUnitDefinition(unit.type).humanBased)
    .reduce((total, unit) => {
      const healthRatio = unit.health / Math.max(1, unit.maxHealth);
      const objectiveDistance = getNearestEnemyCaptureObjectiveDistance(state, unit.coord);
      const distanceWeight = objectiveDistance <= 10 ? 1 : objectiveDistance <= 18 ? 0.7 : 0.42;
      const healthWeight = healthRatio >= 0.65 ? 1 : healthRatio >= 0.4 ? 0.65 : 0.25;
      const baseDefensePenalty = hexDistance(unit.coord, state.bases.Enemy) <= 6 && getEnemyBaseThreat(state) ? 0.45 : 1;
      return total + distanceWeight * healthWeight * baseDefensePenalty;
    }, 0);
  const inventoryPressure = ENEMY_CAPTURE_UNIT_TYPES.reduce((total, unitType) => total + state.enemyEconomy.inventory[unitType] * 0.45, 0);
  const queuedPressure = state.enemyEconomy.productionQueue.filter((job) => ENEMY_CAPTURE_UNIT_TYPES.includes(job.unitType)).length * 0.3;
  return activeCapturePressure + inventoryPressure + queuedPressure;
}

function getNearestEnemyCaptureObjectiveDistance(state: GameState, coord: UnitInstance["coord"]): number {
  const objectives = [
    state.bases.Player,
    ...(state.gates ?? []).filter((gate) => gate.owner !== "Enemy").map((gate) => gate.coord)
  ];
  return objectives.reduce((best, objective) => Math.min(best, hexDistance(coord, objective)), Number.POSITIVE_INFINITY);
}

function getEnemyUnitPresence(state: GameState, unitType: UnitType): number {
  const fielded = state.units.filter((unit) => unit.owner === "Enemy" && unit.type === unitType).length;
  const inventory = state.enemyEconomy.inventory[unitType] * 0.8;
  const queued = state.enemyEconomy.productionQueue.filter((job) => job.unitType === unitType).length * 0.55;
  return fielded + inventory + queued;
}

function getEnemyArmyExpansionProductionBonus(state: GameState, unitType: UnitType): number {
  if (!isEnemyCombatExpansionProductionUnit(unitType)) {
    return 0;
  }

  const definition = getUnitDefinition(unitType);
  const combatPresence = ENEMY_UNIT_TYPES
    .filter((candidate) => isEnemyCombatExpansionProductionUnit(candidate))
    .reduce((total, candidate) => total + getEnemyUnitPresence(state, candidate), 0);
  const airPresence = ENEMY_UNIT_TYPES
    .filter((candidate) => getUnitDefinition(candidate).domain === "Air" && isEnemyCombatExpansionProductionUnit(candidate))
    .reduce((total, candidate) => total + getEnemyUnitPresence(state, candidate), 0);
  const desiredCombatPresence =
    state.difficulty === "Hard"
      ? state.day <= 8 ? 18 : state.day <= 18 ? 24 : 30
      : state.day <= 8 ? 14 : state.day <= 18 ? 19 : 24;
  const desiredAirPresence =
    state.difficulty === "Hard"
      ? state.day <= 8 ? 3 : state.day <= 18 ? 5 : 7
      : state.day <= 8 ? 2 : state.day <= 18 ? 3.5 : 5;
  const combatShortfall = Math.max(0, desiredCombatPresence - combatPresence);
  const airShortfall = Math.max(0, desiredAirPresence - airPresence);
  const openProductionLaneBonus = state.enemyEconomy.productionQueue.length < getEnemyRoutineProductionQueueLimit(state) ? 28 : 0;
  const combatBonus = combatShortfall * (definition.domain === "Air" ? 8 : 7);
  const airBonus = definition.domain === "Air" ? airShortfall * 34 : 0;
  return openProductionLaneBonus + combatBonus + airBonus;
}

function getEnemyUnitUpgradeUseProfile(state: GameState, unitType: UnitType): EnemyUnitUpgradeUseProfile {
  const economy = state.enemyEconomy;
  const targetLevel = Math.min(getMaxUnitLevel(unitType), economy.unitLevels[unitType] + 1);
  const fieldedUnits = state.units.filter((unit) => unit.owner === "Enemy" && unit.type === unitType);
  const fielded = fieldedUnits.length;
  const fieldUpgradeable = fieldedUnits.filter((unit) => getUnitInstanceLevel(state, unit) < targetLevel).length;
  const inventory = economy.inventory[unitType] ?? 0;
  const queuedProduction = economy.productionQueue.filter((job) => job.unitType === unitType).length;
  const committedUse = fielded + inventory * 0.8 + queuedProduction * 1.1;
  const productionIntent = getEnemyNearTermProductionIntentForUpgrade(state, unitType);
  return {
    fielded,
    fieldUpgradeable,
    inventory,
    queuedProduction,
    productionIntent,
    committedUse
  };
}

function getEnemyNearTermProductionIntentForUpgrade(state: GameState, unitType: UnitType): number {
  if (!canOwnerProduceUnit(state, "Enemy", unitType)) {
    return 0;
  }

  const productionCost = getProductionCost(unitType);
  const economy = state.enemyEconomy;
  const incomeWindow = Math.max(0, economy.moneyPoundsBn + economy.incomePoundsBn * 2 - productionCost);
  const affordableSoonBonus = economy.moneyPoundsBn >= productionCost ? 22 : Math.min(18, incomeWindow * 1.8);
  if (affordableSoonBonus <= 0) {
    return 0;
  }

  const doctrineScore = Math.max(0, scoreEnemyDoctrineNeedForUnit(state, unitType));
  const counterScore = Math.max(0, scoreUnitCountersPlayerArmy(state, unitType));
  const defaultScore = Math.max(0, getDefaultEnemyProductionScore(unitType));
  const baseThreat = getEnemyBaseThreat(state);
  const baseDefenseBonus = baseThreat && canUnitTargetUnit(unitType, baseThreat.type) ? 28 : 0;
  const score = defaultScore * 0.42 + doctrineScore * 0.36 + counterScore * 0.28 + affordableSoonBonus + baseDefenseBonus;
  const threshold = state.difficulty === "Hard" ? 105 : 132;
  if (score < threshold) {
    return 0;
  }

  return Math.min(2.4, (score - threshold) / 38 + 0.75);
}

function getOwnerArmyValue(state: GameState, owner: Owner): number {
  return getOwnerUnits(state, owner).reduce((total, unit) => total + getUnitInstanceValue(state, unit), 0);
}

function getUnitInstanceValue(state: GameState, unit: UnitInstance): number {
  const cache = getEnemyEvaluationCache(state);
  cache.unitInstanceValues ??= new Map();
  const level = unit.level ?? getEconomy(state, unit.owner).unitLevels[unit.type] ?? 1;
  const cacheKey = `${unit.id}:${unit.owner}:${unit.type}:${level}:${unit.health}:${unit.maxHealth}`;
  const cached = cache.unitInstanceValues.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const healthRatio = unit.maxHealth > 0 ? unit.health / unit.maxHealth : 0;
  const supplyTruckPriority = getPlayerSupplyTruckTargetPriority(unit) * (0.55 + healthRatio * 0.45);
  const enemySupplyTruckPreservation = getEnemySupplyTruckPreservationValue(unit) * (0.55 + healthRatio * 0.45);
  const value = getUnitTypeValue(state, unit.owner, unit.type, unit.level) * (0.35 + healthRatio * 0.65) + supplyTruckPriority + enemySupplyTruckPreservation;
  cache.unitInstanceValues.set(cacheKey, value);
  return value;
}

function getPlayerSupplyTruckTargetPriority(unit: UnitInstance): number {
  return unit.owner === "Player" && isEnemySupplySupportUnit(unit.type) ? (unit.type === "Command Heli" ? 230 : 180) : 0;
}

function getEnemySupplyTruckPreservationValue(unit: UnitInstance): number {
  return unit.owner === "Enemy" && isEnemySupplySupportUnit(unit.type) ? (unit.type === "Command Heli" ? 285 : 220) : 0;
}

function getUnitTypeValue(state: GameState, owner: Owner, unitType: UnitType, levelOverride?: number): number {
  const cache = getEnemyEvaluationCache(state);
  cache.unitTypeValues ??= new Map();
  const level = levelOverride ?? getEconomy(state, owner).unitLevels[unitType] ?? 1;
  const cacheKey = `${owner}:${unitType}:${level}`;
  const cached = cache.unitTypeValues.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const definition = getUnitDefinition(unitType);
  const stats = getEffectiveUnitStats(state, owner, unitType, level);
  const baseDamage = getBaseAttackDamage(unitType, level);
  const eliteBonus = unitType === "Reaper" ? 35 : unitType === "Ghost" || unitType === "Operator" || unitType === "Spectral" ? 18 : 0;
  const value = (
    stats.health * 1.05 +
    baseDamage * 6 +
    stats.moveRange * 2.4 +
    stats.attackRange * 3.4 +
    stats.visibilityRange * 0.8 +
    getProductionCost(unitType) * 1.15 +
    (definition.humanBased ? 24 : 0) +
    eliteBonus
  );
  cache.unitTypeValues.set(cacheKey, value);
  return value;
}

function scoreUnitCountersPlayerArmy(state: GameState, unitType: UnitType): number {
  const playerIntel = getPlayerIntelForEnemy(state);
  if (!playerIntel.length) {
    return getDefaultEnemyProductionScore(unitType) * 0.45;
  }

  return playerIntel.reduce((score, intel) => {
    const playerUnit: UnitInstance = {
      ...intel.unit,
      coord: { ...intel.predictedCoord }
    };
    if (!canUnitTargetUnit(unitType, playerUnit.type)) {
      return score - 5 * intel.confidence;
    }

    const effectiveness = EFFECTIVENESS_MULTIPLIERS[getAttackEffectiveness(unitType, playerUnit.type)];
    const targetValue = getUnitInstanceValue(state, playerUnit);
    const baseDistance = hexDistance(playerUnit.coord, state.bases.Enemy);
    const baseThreat = getUnitDefinition(playerUnit.type).humanBased ? Math.max(0, getEnemyBaseResponseRadius(state) + 2 - baseDistance) * 6 : 0;
    return score + (targetValue * effectiveness * 0.18 + baseThreat + getCounterPriorityBonus(unitType, playerUnit)) * intel.confidence;
  }, 0);
}

function getCounterPriorityBonus(counterType: UnitType, playerUnit: UnitInstance): number {
  const orderBonus = getCombatCounterOrderBonus(counterType, playerUnit.type);
  const orderedCounter = isCombatCounterOrdered(counterType, playerUnit.type);
  let contextualBonus = 0;

  if (playerUnit.type === "Artillery") {
    if (counterType === "Bomber") {
      contextualBonus += 135;
    }
    if (counterType === "Reaper") {
      contextualBonus += 118;
    }
    if (counterType === "Attack Heli") {
      contextualBonus += 54;
    }
    if (counterType === "Ghost" || counterType === "Operator") {
      contextualBonus += 28;
    }
  }

  if (getUnitDefinition(playerUnit.type).domain === "Air") {
    if (counterType === "Anti-Air") {
      contextualBonus += 84;
    }
    if (counterType === "Jet") {
      contextualBonus += 72;
    }
    if (counterType === "Reaper") {
      contextualBonus += 42;
    }
  }

  if (playerUnit.type === "Tank" || playerUnit.type === "IFV") {
    if (counterType === "Bomber" || counterType === "Reaper") {
      contextualBonus += 48;
    }
    if (counterType === "Attack Heli") {
      contextualBonus += 34;
    }
  }

  if (getUnitDefinition(playerUnit.type).humanBased) {
    if (counterType === "IFV") {
      contextualBonus += 44;
    }
    if (counterType === "Artillery" || counterType === "Reaper") {
      contextualBonus += 32;
    }
  }

  return orderedCounter ? orderBonus + contextualBonus * 0.2 : contextualBonus;
}

function getCombatCounterOrderBonus(counterType: UnitType, targetType: UnitType): number {
  const targetDomain = getUnitDefinition(targetType).domain;
  const order = targetDomain === "Air" ? ENEMY_AIR_COMBAT_VALUE_ORDER : ENEMY_GROUND_COMBAT_VALUE_ORDER;
  const rank = order.indexOf(counterType);
  const step = targetDomain === "Air" ? 50 : 42;
  return rank >= 0 ? (order.length - rank - 1) * step : 0;
}

function isCombatCounterOrdered(counterType: UnitType, targetType: UnitType): boolean {
  const targetDomain = getUnitDefinition(targetType).domain;
  const order = targetDomain === "Air" ? ENEMY_AIR_COMBAT_VALUE_ORDER : ENEMY_GROUND_COMBAT_VALUE_ORDER;
  return order.includes(counterType);
}

function getPlayerArtilleryPressure(state: GameState): number {
  return getPlayerIntelForEnemy(state).reduce((score, intel) => {
    if (intel.unit.type !== "Artillery") {
      return score;
    }

    const distanceToEnemyBase = hexDistance(intel.predictedCoord, state.bases.Enemy);
    const baseLinePressure = Math.max(0, getEnemyBaseResponseRadius(state) + 9 - distanceToEnemyBase) * 9;
    const valuePressure = getUnitInstanceValue(state, intel.unit) * 0.55;
    return score + (valuePressure + baseLinePressure + 42) * intel.confidence;
  }, 0);
}

function canCounterAir(unitType: UnitType): boolean {
  return ["Anti-Air", "Attack Heli", "Jet", "Operator", "Reaper"].includes(unitType);
}

function isHighAltitudeAirUnit(unitType: UnitType): boolean {
  return HIGH_ALTITUDE_AIR_UNIT_TYPES.has(unitType);
}

function canCounterHighAltitudeAir(unitType: UnitType): boolean {
  return unitType === "Anti-Air" || unitType === "Attack Heli" || unitType === "Jet" || unitType === "Reaper";
}

function getDefaultEnemyProductionScore(unitType: UnitType): number {
  const scores: Partial<Record<UnitType, number>> = {
    Infantry: 38,
    "Anti-Air": 48,
    Artillery: 56,
    IFV: 54,
    Tank: 76,
    "Attack Heli": 38,
    "Command Heli": 46,
    Jet: 42,
    Bomber: 58,
    Operator: 82,
    Ghost: 88,
    Reaper: 132
  };
  return scores[unitType] ?? 0;
}

function scoreEnemyDoctrineNeedForUnit(state: GameState, unitType: UnitType): number {
  const assessment = getEnemyStrategicAssessment(state);
  const definition = getUnitDefinition(unitType);
  const artilleryPressure = getPlayerArtilleryPressure(state);
  let score = 0;

  if (isReconUnit(unitType)) {
    score += assessment.scoutNeed * (unitType === "Ghost" || unitType === "Reaper" ? 0.72 : 0.42);
    score += state.difficulty === "Hard" && state.day <= 10 ? 36 : 0;
  } else if (needsReconSupport(unitType) && assessment.scoutNeed > 70) {
    score -= assessment.scoutNeed * 0.22;
  }

  if (definition.humanBased && !(state.difficulty === "Hard" && unitType === "Infantry")) {
    score += assessment.baseAttackUrgency * 0.26 + assessment.gateUrgency * 0.22;
    score += assessment.strategyPlan === "GroundCaptureSwarm" ? 44 : 0;
    score += assessment.strategyPlan === "GateEconomy" ? 24 : 0;
  }
  if (state.difficulty === "Hard" && unitType === "Infantry") {
    score += state.day <= 8 ? assessment.gateUrgency * 0.08 : 0;
  }

  if (unitType === "Bomber") {
    score += assessment.airExploitationOpportunity * 0.78;
    score -= Math.max(0, assessment.antiAirNeed) * 0.3;
    score += assessment.strategyPlan === "AirSuperiority" && assessment.opponentProfile.groundBias > 0.55 ? 28 : 0;
    score += artilleryPressure * 0.75;
  }

  if (unitType === "Attack Heli") {
    score += assessment.airExploitationOpportunity * 0.42;
    score -= Math.max(0, assessment.antiAirNeed) * 0.18;
    score += artilleryPressure * 0.2;
  }

  if (unitType === "Jet" || unitType === "Anti-Air") {
    score += Math.max(0, assessment.antiAirNeed) * (unitType === "Anti-Air" ? 0.72 : 0.56);
    score += assessment.strategyPlan === "AirSuperiority" ? 24 : 0;
  }

  if (unitType === "Tank" || unitType === "IFV" || unitType === "Infantry" || unitType === "Attack Heli") {
    const multiplier = unitType === "Tank" ? 0.65 : unitType === "IFV" ? 0.42 : unitType === "Infantry" ? (state.difficulty === "Hard" ? 0.04 : 0.28) : 0.32;
    score += assessment.groundExploitationOpportunity * multiplier;
  }

  if (unitType === "Artillery") {
    score += assessment.player.groundCount * 12 + Math.max(0, assessment.enemy.scoutCount - assessment.enemy.artillerySupportCount) * 18;
  }

  if (unitType === "Reaper") {
    score += assessment.airExploitationOpportunity * 0.42 + assessment.antiAirNeed * 0.24 + assessment.scoutNeed * 0.46;
    score += assessment.strategyPlan === "ReaperTechRush" ? 70 : 0;
    score += artilleryPressure * 0.6;
  }

  return score;
}

function getEnemyOpponentProfileProductionCounterScore(state: GameState, unitType: UnitType, assessment: EnemyStrategicAssessment): number {
  if (state.difficulty !== "Hard") {
    return 0;
  }

  const profile = assessment.opponentProfile;
  const strength = getEnemyOpponentProfileStrength(profile);
  if (strength < 0.48 && profile.kind !== "AirHeavy") {
    return 0;
  }

  let score = 0;
  if (profile.kind === "GateRusher" || profile.gateRush >= 0.62) {
    const gateCapturerThreat = getPlayerIntelForEnemy(state).filter((intel) =>
      getUnitDefinition(intel.unit.type).humanBased &&
      (state.gates ?? []).some((gate) => hexDistance(intel.predictedCoord, gate.coord) <= 3)
    ).length;
    const denialScale = 1 + gateCapturerThreat * 0.35 + Math.max(0, assessment.playerGateCount - assessment.enemyGateCount) * 0.4;
    if (unitType === "Tank" || unitType === "IFV" || unitType === "Artillery" || unitType === "Ghost" || unitType === "Operator" || unitType === "Reaper") {
      score += 70 * denialScale;
    }
    if (getUnitDefinition(unitType).humanBased) {
      score += 42 * denialScale;
    }
    if (unitType === "Bomber" || unitType === "Attack Heli") {
      score -= 34;
    }
  }

  if (profile.kind === "Turtle" || profile.turtle >= 0.58) {
    const bothGateShortfall = ownerControlsBothGates(state, "Enemy") ? 0 : 1;
    if (getUnitDefinition(unitType).humanBased) {
      score += 52 + bothGateShortfall * 58;
    }
    if (isReconUnit(unitType)) {
      score += 68 + assessment.scoutNeed * 0.34;
    }
    if (unitType === "Tank" || unitType === "Artillery" || unitType === "Bomber" || unitType === "Reaper") {
      score += ownerControlsBothGates(state, "Enemy") ? 74 : 36;
    }
    if (unitType === "Anti-Air") {
      score += 24;
    }
  }

  if (profile.kind === "AirHeavy" || profile.airBias >= 0.5) {
    if (unitType === "Anti-Air") {
      score += 120 + assessment.player.highValueAirCount * 38;
    } else if (unitType === "Jet") {
      score += 86 + assessment.player.highValueAirCount * 34;
    } else if (unitType === "Operator" || unitType === "Reaper") {
      score += 42;
    } else if (getUnitDefinition(unitType).domain === "Ground" && !canCounterAir(unitType) && !getUnitDefinition(unitType).humanBased) {
      score -= 36;
    }
  }

  if (profile.kind === "FastSpecial" || profile.fastSpecial >= 0.58) {
    if (unitType === "Ghost" || unitType === "Operator" || unitType === "Reaper") {
      score += 94 + assessment.player.specialCount * 42;
    }
    if (unitType === "Tank" || unitType === "IFV") {
      score += 42 + assessment.player.specialCount * 18;
    }
    if (unitType === "Anti-Air") {
      score += 32;
    }
    if (unitType === "Infantry") {
      score -= 48;
    }
  }

  return score;
}

function getEnemyStrategyPlaybookProductionScore(
  state: GameState,
  unitType: UnitType,
  assessment: EnemyStrategicAssessment,
  antiAirRisk = getEnemyAntiAirProductionRisk(state, assessment)
): number {
  if (state.difficulty !== "Hard") {
    return 0;
  }

  const playbook = getEnemyStrategyPlaybook(assessment);
  const definition = getUnitDefinition(unitType);
  let score = 0;

  if (playbook.requiredBehaviors.includes("WinHoldGates")) {
    const threatenedOwnedGate = (state.gates ?? []).some((gate) => gate.owner === "Enemy" && (gate.occupation.Player > 0 || (assessment.predictedGatePressure[gate.id] ?? 0) > 55));
    const missingGateControl = (state.gates ?? []).some((gate) => gate.owner !== "Enemy");
    if (definition.humanBased) {
      score += (missingGateControl ? 86 : 44) * playbook.gateEconomyPriority;
    }
    if (unitType === "Tank" || unitType === "IFV" || unitType === "Artillery" || unitType === "Ghost" || unitType === "Operator") {
      score += (threatenedOwnedGate ? 112 : 68) * playbook.gateEconomyPriority;
    }
    if (unitType === "Bomber" || unitType === "Attack Heli") {
      score -= 32 * playbook.gateEconomyPriority;
    }
  }

  if (playbook.requiredBehaviors.includes("ProduceAirCounters")) {
    if (unitType === "Anti-Air") {
      score += 130 + assessment.player.airCount * 44 + assessment.player.highValueAirCount * 42;
    } else if (unitType === "Jet") {
      score += 118 + assessment.player.highValueAirCount * 48;
    } else if (unitType === "Operator" || unitType === "Reaper") {
      score += 58 + assessment.player.airCount * 18;
    }
  }

  if (playbook.requiredBehaviors.includes("AvoidAntiAirDonations")) {
    const riskyAircraft = unitType === "Bomber" || unitType === "Attack Heli" || unitType === "Jet" || unitType === "Reaper";
    if (riskyAircraft && antiAirRisk.phaseDensity > playbook.antiAirDonationTolerance) {
      score -= 150 + antiAirRisk.phaseDensity * 70 + antiAirRisk.knownThreatCount * 46;
    }
  }

  if (playbook.requiredBehaviors.includes("DelayObjectiveClock")) {
    if (isEnemyReaperTechRushDelayProductionUnit(state, unitType, assessment)) {
      score += 92;
    } else if (unitType !== "Reaper") {
      score -= 110;
    }
  }

  if (playbook.requiredBehaviors.includes("UnlockDroneFactory")) {
    if (unitType === "Reaper") {
      score += 190 + assessment.forecast.reaperPipelineNeed * 0.45;
    } else if (!ownerHasBuilding(state, "Enemy", "Drone Factory") && !isEnemyReaperTechRushDelayProductionUnit(state, unitType, assessment)) {
      score -= 95;
    }
  }

  return score;
}

function isEnemyReaperTechRushDelayProductionUnit(state: GameState, unitType: UnitType, assessment = getEnemyStrategicAssessment(state)): boolean {
  const baseThreat = getEnemyBaseThreat(state);
  if (baseThreat && canUnitTargetUnit(unitType, baseThreat.type)) {
    return true;
  }
  const playerAirClock = assessment.player.airCount > 0 && canCounterAir(unitType);
  const gateClockThreat = (state.gates ?? []).some((gate) => gate.owner === "Enemy" && (gate.occupation.Player > 0 || (assessment.predictedGatePressure[gate.id] ?? 0) > 65));
  if (gateClockThreat && (unitType === "Tank" || unitType === "IFV" || unitType === "Ghost" || unitType === "Operator" || canUnitTargetUnit(unitType, "Infantry"))) {
    return true;
  }
  if (unitType === "Ghost" || unitType === "Operator" || unitType === "Tank" || unitType === "IFV" || unitType === "Anti-Air" || unitType === "Artillery") {
    return true;
  }
  if (unitType === "Infantry") {
    const readyCaptureStock = ENEMY_CAPTURE_UNIT_TYPES.reduce(
      (total, captureType) =>
        total +
        getOwnerUnits(state, "Enemy").filter((unit) => unit.type === captureType).length +
        (state.enemyEconomy.inventory[captureType] ?? 0),
      0
    );
    return gateClockThreat || readyCaptureStock < 2;
  }
  return unitType === "Reaper";
}

function getEnemyOpponentProfileStrength(profile: OpponentProfile): number {
  switch (profile.kind) {
    case "AirHeavy":
      return profile.airBias;
    case "GroundHeavy":
      return profile.groundBias;
    case "GateRusher":
      return profile.gateRush;
    case "BaseRusher":
      return profile.baseRush;
    case "Turtle":
      return profile.turtle;
    case "FastSpecial":
      return profile.fastSpecial;
    case "EconomyFirst":
      return profile.economyFirst;
    default:
      return 0.35;
  }
}

function choosePlayerHighAltitudeThreatForEnemy(state: GameState): PlayerUnitIntel | undefined {
  return getPlayerIntelForEnemy(state)
    .filter((intel) => isHighAltitudeAirUnit(intel.unit.type))
    .sort((first, second) => scorePlayerHighAltitudeThreatForEnemy(state, second) - scorePlayerHighAltitudeThreatForEnemy(state, first))[0];
}

function scorePlayerHighAltitudeThreatForEnemy(state: GameState, intel: PlayerUnitIntel): number {
  const basePressure = Math.max(0, getEnemyBaseResponseRadius(state) + 4 - hexDistance(intel.predictedCoord, state.bases.Enemy)) * 22;
  const gatePressure = (state.gates ?? []).reduce(
    (total, gate) => total + Math.max(0, 7 - hexDistance(intel.predictedCoord, gate.coord)) * (gate.owner === "Player" ? 20 : 12),
    0
  );
  return (getUnitInstanceValue(state, intel.unit) + basePressure + gatePressure) * intel.confidence;
}

function chooseEnemyHighAltitudeLayerDeploymentTarget(state: GameState, unitType: UnitType): UnitInstance["coord"] | undefined {
  const highAltitudeThreat = choosePlayerHighAltitudeThreatForEnemy(state);
  if (highAltitudeThreat && canCounterHighAltitudeAir(unitType)) {
    return highAltitudeThreat.predictedCoord;
  }

  if (!isHighAltitudeAirUnit(unitType)) {
    return undefined;
  }

  const assessment = getEnemyStrategicAssessment(state);
  const risk = getEnemyAntiAirProductionRisk(state, assessment);
  const layer = getEnemyHighAltitudeLayerAssessment(state, assessment, risk);
  if (layer.playerAntiAirThreatCount > 0.35 || risk.phaseDensity > 0.7) {
    return state.bases.Enemy;
  }

  return getPlayerIntelForEnemy(state)
    .filter((intel) => canUnitTargetUnit(unitType, intel.unit.type))
    .filter((intel) => intel.unit.type !== "Anti-Air")
    .sort((first, second) => getUnitInstanceValue(state, second.unit) * second.confidence - getUnitInstanceValue(state, first.unit) * first.confidence)[0]?.predictedCoord;
}

function scoreEnemyHighAltitudeLayerPlacement(
  state: GameState,
  unitType: UnitType,
  coord: UnitInstance["coord"],
  plan?: EnemyTurnPlan
): number {
  if (state.difficulty !== "Hard") {
    return 0;
  }

  const assessment = getEnemyStrategicAssessment(state);
  const risk = getEnemyAntiAirProductionRisk(state, assessment);
  const layer = getEnemyHighAltitudeLayerAssessment(state, assessment, risk);

  if (unitType === "Anti-Air") {
    const threat = choosePlayerHighAltitudeThreatForEnemy(state);
    if (!threat) {
      return 0;
    }
    const distance = hexDistance(coord, threat.predictedCoord);
    return Math.max(0, 12 - distance) * 28 + layer.antiAirResponseUrgency * 0.16;
  }

  if (!isHighAltitudeAirUnit(unitType)) {
    return 0;
  }

  const hypothetical = createHypotheticalEnemyUnit(state, unitType, coord);
  const coveringThreats = getAntiAirThreatsCoveringCoord(state, hypothetical, coord, getEnemyAntiAirThreatMap(state, plan));
  const deniedAirspacePenalty = coveringThreats.reduce((penalty, threat) => penalty + 220 * threat.confidence * (threat.probable ? 0.65 : 1), 0);
  const exploitationTarget = chooseEnemyHighAltitudeLayerDeploymentTarget(state, unitType);
  const exploitationBonus = exploitationTarget && layer.playerAntiAirThreatCount <= 0.15
    ? Math.max(0, 14 - hexDistance(coord, exploitationTarget)) * (unitType === "Bomber" || unitType === "Reaper" ? 18 : 8)
    : 0;
  return exploitationBonus - deniedAirspacePenalty - layer.conservativeRisk * (unitType === "Reaper" ? 0.08 : 0.12);
}

function scoreEnemyPlacementUnitType(state: GameState, unitType: UnitType): number {
  const definition = getUnitDefinition(unitType);
  return (
    scoreEnemyProductionChoice(state, unitType) +
    (definition.humanBased ? getEnemyCaptureNeed(state) * 14 : 0) +
    (isPatrolCapableUnit(unitType) && state.difficulty === "Hard" && state.day <= 8 ? 190 : 0) +
    (unitType === "Reaper" ? 40 : 0)
  );
}

function estimateEnemyPlacementObjectiveRoute(
  state: GameState,
  unitType: UnitType,
  coord: UnitInstance["coord"],
  target: UnitInstance["coord"]
): { routeDistance: number; geometricDistance: number; reachable: boolean } {
  const cache = getEnemyEvaluationCache(state);
  cache.placementObjectiveRoutes ??= new Map();
  const cacheKey = `${unitType}:${hexId(coord)}:${hexId(target)}`;
  const cached = cache.placementObjectiveRoutes.get(cacheKey);
  if (cached) {
    return cached;
  }

  const geometricDistance = hexDistance(coord, target);
  if (sameHex(coord, target)) {
    const route = { routeDistance: 0, geometricDistance, reachable: true };
    cache.placementObjectiveRoutes.set(cacheKey, route);
    return route;
  }

  const pathfinder = createHypotheticalEnemyUnit(state, unitType, coord);
  const candidateById = new Map<string, UnitInstance["coord"]>();
  for (const candidate of [target, ...getNeighborCoords(state.map, target)]) {
    candidateById.set(hexId(candidate), candidate);
  }

  let best: { routeDistance: number; reachable: boolean } | undefined;
  for (const candidate of candidateById.values()) {
    const hex = getHex(state.map, candidate);
    if (!hex?.passable || !canUnitEndMovementAt(state, pathfinder, candidate)) {
      continue;
    }

    const pathDistance = sameHex(coord, candidate)
      ? 0
      : findMovementPath(state, pathfinder, candidate, { allowFutureMovement: true })?.length;
    if (pathDistance === undefined) {
      continue;
    }

    const routeDistance = pathDistance + hexDistance(candidate, target);
    if (!best || routeDistance < best.routeDistance) {
      best = { routeDistance, reachable: true };
    }
  }

  if (best) {
    const route = { routeDistance: best.routeDistance, geometricDistance, reachable: true };
    cache.placementObjectiveRoutes.set(cacheKey, route);
    return route;
  }

  const route = { routeDistance: geometricDistance + 12, geometricDistance, reachable: false };
  cache.placementObjectiveRoutes.set(cacheKey, route);
  return route;
}

function scoreEnemyPlacementCoord(state: GameState, unitType: UnitType, coord: UnitInstance["coord"], plan?: EnemyTurnPlan): number {
  const definition = getUnitDefinition(unitType);
  const assessment = getEnemyStrategicAssessment(state);
  const mission = getPlacementMissionForUnitType(state, unitType);
  const lockoutTarget = chooseEnemyGateLockoutPlacementTarget(state, unitType, plan);
  const campaignGate = chooseEnemyCampaignPlacementGateTarget(state, unitType, plan, coord);
  const target = lockoutTarget ?? campaignGate?.coord ?? chooseEnemyDeploymentTarget(state, unitType, plan);
  const centerDistance = Math.abs(coord.q - state.bases.Enemy.q);
  const route = estimateEnemyPlacementObjectiveRoute(state, unitType, coord, target);
  const targetDistance = route.routeDistance;
  const sameHexAllies = state.units.filter((unit) => unit.owner === "Enemy" && sameHex(unit.coord, coord)).length;
  const nearbyAllies = state.units.filter((unit) => unit.owner === "Enemy" && hexDistance(unit.coord, coord) <= 3).length;
  const groupingScore =
    state.difficulty === "Hard"
      ? scoreEnemyPlacementSpacing(state, unitType, coord, mission)
      : nearbyAllies * 3 + sameHexAllies * 5;
  let score = -targetDistance * 8 - centerDistance * 0.8 + groupingScore - (route.reachable ? 0 : 180);
  score += getInfluencePositionScore(state, createHypotheticalEnemyUnit(state, unitType, coord), coord, mission) * 0.4;

  const baseThreat = getEnemyBaseThreat(state);
  if (isActiveEnemyBaseThreat(state, baseThreat) && baseThreat) {
    score += Math.max(0, getEnemyBaseResponseRadius(state) + 2 - hexDistance(coord, baseThreat.coord)) * (state.difficulty === "Hard" ? 20 : 14);
    if (canUnitTargetUnit(unitType, baseThreat.type)) {
      score += 30;
    }
  }

  if (definition.humanBased) {
    score += Math.max(0, state.map.width - centerDistance) * 0.5;
    score += assessment.gateUrgency * 0.08;
    score += mission === "CaptureGate" || mission === "DefendGate" ? Math.max(0, 14 - targetDistance) * 4 : 0;
  }

  if (isReconUnit(unitType)) {
    score += assessment.scoutNeed * 0.06 - centerDistance * 0.35;
  }

  if (needsReconSupport(unitType)) {
    const scoutAnchor = getEnemyReconAnchor(state);
    if (scoutAnchor) {
      score += Math.max(0, 9 - hexDistance(coord, scoutAnchor.coord)) * 4;
    }
  }

  score += scoreEnemyCampaignPlacementCoord(state, unitType, coord, plan);
  score += scoreEnemyGateLockoutPlacementCoord(state, unitType, coord, plan);
  score += scoreEnemyHighAltitudeLayerPlacement(state, unitType, coord, plan);
  score += scoreEnemySupplyTruckForwardPlacement(state, unitType, coord, target);

  return score;
}

function scoreEnemySupplyTruckForwardPlacement(
  state: GameState,
  unitType: UnitType,
  coord: UnitInstance["coord"],
  target: UnitInstance["coord"]
): number {
  const anchor = getEnemySupplyPlacementAnchor(state, coord, unitType);
  if (!anchor) {
    return 0;
  }

  const nearestBackRowDistance = state.map.hexes
    .filter((hex) => hex.passable && isOwnerBackRow(state, "Enemy", hex.coord))
    .reduce((best, hex) => {
      const route = estimateEnemyPlacementObjectiveRoute(state, unitType, hex.coord, target);
      return Math.min(best, route.routeDistance);
    }, Number.POSITIVE_INFINITY);
  const route = estimateEnemyPlacementObjectiveRoute(state, unitType, coord, target);
  const forwardGain = nearestBackRowDistance - route.routeDistance;
  const humanBased = getUnitDefinition(unitType).humanBased;
  const commandHelicopterGateDrop =
    isEnemyCommandHelicopter(anchor.type) &&
    humanBased &&
    (state.gates ?? []).some((gate) => gate.owner !== "Enemy" && sameHex(coord, gate.coord))
      ? 1_200
      : 0;
  if (forwardGain <= 0 && commandHelicopterGateDrop <= 0) {
    return -40;
  }

  const hypothetical = createHypotheticalEnemyUnit(state, unitType, coord);
  const dangerPenalty = estimatePlayerDangerAt(state, hypothetical, coord) > 0 ? 120 : 0;
  const commandHelicopterDrop =
    isEnemyCommandHelicopter(anchor.type) && humanBased && sameHex(coord, target)
      ? 620
      : isEnemyCommandHelicopter(anchor.type) && humanBased && hexDistance(coord, target) <= 1
        ? 260
        : 0;
  return 120 + commandHelicopterGateDrop + commandHelicopterDrop + Math.max(0, forwardGain) * 45 - dangerPenalty - (route.reachable ? 0 : 120);
}

function createHypotheticalEnemyUnit(state: GameState, unitType: UnitType, coord: UnitInstance["coord"]): UnitInstance {
  const level = state.enemyEconomy.unitLevels[unitType];
  const maxHealth = getEffectiveUnitHealth(state, "Enemy", unitType, level);
  return {
    id: "hypothetical-enemy",
    owner: "Enemy",
    type: unitType,
    level,
    coord,
    health: maxHealth,
    maxHealth,
    placedDay: state.day,
    hasMovedThisDay: false,
    movementSpentThisDay: 0,
    hasAttackedThisDay: false
  };
}

function getPlacementMissionForUnitType(state: GameState, unitType: UnitType): EnemyMission {
  return assignEnemyMission(state, createHypotheticalEnemyUnit(state, unitType, state.bases.Enemy));
}

function chooseEnemyDeploymentTarget(state: GameState, unitType: UnitType, plan?: EnemyTurnPlan): UnitInstance["coord"] {
  const baseThreat = getEnemyBaseThreat(state);
  if (isActiveEnemyBaseThreat(state, baseThreat) && baseThreat && canUnitTargetUnit(unitType, baseThreat.type)) {
    return baseThreat.coord;
  }

  if (isEnemyBaseOperationPlacementPhase(plan?.campaignPlan.phase)) {
    return chooseEnemyCampaignBasePlacementTarget(state, unitType, plan);
  }

  const lockoutPlacementTarget = chooseEnemyGateLockoutPlacementTarget(state, unitType, plan);
  if (lockoutPlacementTarget) {
    return lockoutPlacementTarget;
  }

  const campaignGate = chooseEnemyCampaignPlacementGateTarget(state, unitType, plan);
  if (campaignGate) {
    return campaignGate.coord;
  }

  const assessment = getEnemyStrategicAssessment(state);
  const gateDeploymentThreshold = state.difficulty === "Hard" ? assessment.baseAttackUrgency * 0.55 : assessment.baseAttackUrgency * 0.8;
  if (getUnitDefinition(unitType).humanBased && assessment.gateUrgency > gateDeploymentThreshold) {
    const gateDefense = chooseEnemyGateDefenseObjective(state, state.bases.Enemy);
    if (gateDefense) {
      return gateDefense.coord;
    }

    const gate = chooseGateObjective(state, "Enemy", state.bases.Enemy);
    if (gate) {
      return gate.coord;
    }
  }

  const highAltitudeTarget = chooseEnemyHighAltitudeLayerDeploymentTarget(state, unitType);
  if (highAltitudeTarget) {
    return highAltitudeTarget;
  }

  const playerTargets = getPlayerIntelForEnemy(state)
    .filter((intel) => canUnitTargetUnit(unitType, intel.unit.type))
    .sort((first, second) => getUnitInstanceValue(state, second.unit) * second.confidence - getUnitInstanceValue(state, first.unit) * first.confidence);
  return playerTargets[0]?.predictedCoord ?? state.bases.Player;
}

function chooseEnemyOperationalTarget(state: GameState, unit: UnitInstance): UnitInstance["coord"] {
  const baseThreat = getEnemyBaseThreat(state);
  const mission = assignEnemyMission(state, unit);
  if (baseThreat && mission === "DefendBase") {
    return baseThreat.coord;
  }

  if (mission === "Repair") {
    return getNearestEnemyRepairCoord(state, unit.coord, unit.type);
  }

  if (
    state.difficulty === "Hard" &&
    mission === "CaptureGate" &&
    getUnitDefinition(unit.type).humanBased &&
    state.day <= 16 &&
    !isEnemyBaseCaptureCritical(state)
  ) {
    const earlyGate = chooseEarlyHardNeutralGateTarget(state, unit);
    if (earlyGate) {
      return earlyGate.coord;
    }
  }

  if (
    state.difficulty === "Hard" &&
    getUnitDefinition(unit.type).humanBased &&
    mission !== "DefendBase" &&
    hexDistance(unit.coord, state.bases.Player) < hexDistance(unit.coord, state.bases.Enemy) &&
    isPlayerBaseExposedForHardAttack(state)
  ) {
    return state.bases.Player;
  }

  if (mission === "BaseSentry") {
    return getEnemyBaseSentryCoord(state, unit);
  }

  if (mission === "PatrolWest" || mission === "PatrolEast") {
    return getEnemyPatrolCoord(state, mission === "PatrolWest" ? "West" : "East", unit);
  }

  const gateLockoutTarget = isEnemyGateLockoutCombatMission(mission)
    ? chooseEnemyGateLockoutRoleTargetCoord(state, unit, mission)
    : undefined;
  if (gateLockoutTarget) {
    return gateLockoutTarget;
  }

  if (state.difficulty === "Hard" && mission === "DefendGate") {
    const gateTarget = chooseEnemyGateRoleTarget(state, mission) ?? chooseEnemyGateDefenseObjective(state, unit.coord);
    const anchor = gateTarget ? chooseEnemyGateTheatreDefenseAnchorCoord(state, unit, gateTarget) : undefined;
    if (anchor) {
      return anchor;
    }
    if (gateTarget) {
      return gateTarget.coord;
    }
  }

  if (state.difficulty === "Hard" && (mission === "CaptureGate" || mission === "DefendGate")) {
    const gateTarget = chooseEnemyGateRoleTarget(state, mission);
    if (gateTarget) {
      return gateTarget.coord;
    }
  }

  if (unit.type === "Artillery" || unit.type === "Anti-Air") {
    return chooseEnemyFireSupportPosition(state, unit);
  }

  if (mission === "InterceptAir") {
    return choosePredictedPlayerTargetByDomain(state, unit, "Air") ?? baseThreat?.coord ?? state.bases.Player;
  }

  if (mission === "HuntArtillery") {
    return choosePredictedPlayerTypeTarget(state, unit, ["Artillery", "Anti-Air", "Tank"]) ?? state.bases.Player;
  }

  const definition = getUnitDefinition(unit.type);
  if (definition.humanBased) {
    const assessment = getEnemyStrategicAssessment(state);
    if (mission === "CaptureBase") {
      return state.bases.Player;
    }

    const config = getAiDifficultyConfig(state);
    const gateTargetThreshold =
      state.difficulty === "Hard"
        ? assessment.baseAttackUrgency * (assessment.playerBaseVulnerability > 220 ? 0.9 : 0.62)
        : assessment.baseAttackUrgency * (1 - config.gateCaptureOpportunityMultiplier * 0.55);
    if (assessment.gateUrgency > gateTargetThreshold && !isEnemyBaseCaptureCritical(state)) {
      return chooseEnemyGateDefenseObjective(state, unit.coord)?.coord ?? chooseGateObjective(state, unit.owner, unit.coord, unit, activeEnemyTurnPlan ?? undefined)?.coord ?? state.bases.Player;
    }
    return state.bases.Player;
  }

  const targetablePlayer = getPlayerIntelForEnemy(state)
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .sort((first, second) => {
      const firstScore = getUnitInstanceValue(state, first.unit) * first.confidence - hexDistance(unit.coord, first.predictedCoord) * 5;
      const secondScore = getUnitInstanceValue(state, second.unit) * second.confidence - hexDistance(unit.coord, second.predictedCoord) * 5;
      return secondScore - firstScore;
    })[0];
  if (targetablePlayer) {
    return targetablePlayer.predictedCoord;
  }

  if (isReconUnit(unit.type)) {
    const scoutTarget = chooseEnemyScoutTarget(state, unit);
    if (scoutTarget) {
      return scoutTarget;
    }
  }

  if (needsReconSupport(unit.type)) {
    const gateDefense = chooseEnemyGateDefenseObjective(state, unit.coord);
    const anchor = getEnemyReconAnchor(state) ?? getEnemyVanguard(state, unit.id);
    if (gateDefense) {
      return gateDefense.coord;
    }
    if (anchor) {
      return anchor.coord;
    }
  }

  return getEnemyVanguard(state, unit.id)?.coord ?? state.bases.Player;
}

function chooseEarlyHardNeutralGateTarget(state: GameState, unit: UnitInstance): GateState | undefined {
  const neutralGates = (state.gates ?? []).filter((gate) => gate.owner === null);
  if (!neutralGates.length) {
    return undefined;
  }

  const uncontested = neutralGates.filter((gate) => gate.occupation.Player <= 0);
  const candidates = uncontested.length ? uncontested : neutralGates;
  const center = state.bases.Enemy.q;
  const preferredLane: GateState["id"] =
    unit.coord.q < center ? "West" : unit.coord.q > center ? "East" : getStableUnitNumber(unit) % 2 === 0 ? "West" : "East";
  const preferredGate = candidates.find((gate) => gate.id === preferredLane);
  if (preferredGate && candidates.length > 1) {
    const preferredScore = scoreOpeningGateFallback(state, preferredGate);
    const alternative = candidates
      .filter((gate) => gate.id !== preferredGate.id)
      .sort((first, second) => scoreOpeningGateFallback(state, second) - scoreOpeningGateFallback(state, first))[0];
    const alternativeScore = alternative ? scoreOpeningGateFallback(state, alternative) : Number.NEGATIVE_INFINITY;
    if (state.day <= 8 && preferredScore >= alternativeScore - 85) {
      return preferredGate;
    }
    if (alternative && alternativeScore > preferredScore) {
      return alternative;
    }
  }

  return candidates.sort((first, second) => {
    if (state.day > 8) {
      const firstKnownPressure = getKnownPlayerUnitsForEnemy(state).filter((playerUnit) => hexDistance(playerUnit.coord, first.coord) <= 8).length * 160;
      const secondKnownPressure = getKnownPlayerUnitsForEnemy(state).filter((playerUnit) => hexDistance(playerUnit.coord, second.coord) <= 8).length * 160;
      const firstScore = scoreEnemyGateCaptureObjective(state, unit.coord, first) - firstKnownPressure - first.occupation.Player * 180;
      const secondScore = scoreEnemyGateCaptureObjective(state, unit.coord, second) - secondKnownPressure - second.occupation.Player * 180;
      return secondScore - firstScore;
    }

    const firstPressure = (getEnemyStrategicAssessment(state).predictedGatePressure[first.id] ?? 0) + first.occupation.Player * 140;
    const secondPressure = (getEnemyStrategicAssessment(state).predictedGatePressure[second.id] ?? 0) + second.occupation.Player * 140;
    return firstPressure - secondPressure;
  })[0];
}

function isHardOpeningGateRace(state: GameState): boolean {
  return usesHardEnemyDoctrine(state) && state.day <= 12 && (state.gates ?? []).some((gate) => gate.owner === null);
}

function scoreOpeningGateFallback(state: GameState, gate: GateState): number {
  const assessment = getEnemyStrategicAssessment(state);
  const knownPressure = getKnownPlayerUnitsForEnemy(state).filter((playerUnit) => hexDistance(playerUnit.coord, gate.coord) <= 8).length * 95;
  const predictedPressure = assessment.predictedGatePressure[gate.id] ?? 0;
  const opportunity = assessment.gateCaptureOpportunity[gate.id] ?? 0;
  return opportunity + gate.occupation.Enemy * 180 - gate.occupation.Player * 220 - knownPressure - predictedPressure * 1.25;
}

function chooseEnemyGateRoleTarget(state: GameState, mission: EnemyMission): GateState | undefined {
  const gates = (state.gates ?? [])
    .filter((gate) => mission === "DefendGate" ? gate.owner === "Enemy" : gate.owner !== "Enemy")
    .filter((gate) => state.difficulty !== "Hard" || shouldAssignHardGateRole(state, gate))
    .sort((first, second) => scoreEnemyGateRoleObjective(state, second) - scoreEnemyGateRoleObjective(state, first));

  if (state.difficulty === "Hard" && mission === "CaptureGate" && state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY) {
    const counterattackGate = chooseEnemyCounterattackGate(state);
    if (counterattackGate && gates.some((gate) => gate.id === counterattackGate.id)) {
      return counterattackGate;
    }
  }

  if (state.difficulty === "Hard" && mission === "CaptureGate" && state.day <= 16) {
    const assessment = getEnemyStrategicAssessment(state);
    const neutralGates = gates.filter((gate) => gate.owner === null);
    const uncontestedNeutralGates = neutralGates.filter((gate) => gate.occupation.Player <= 0);
    const neutralGate = (uncontestedNeutralGates.length > 0 && neutralGates.some((gate) => gate.occupation.Player > 0) ? uncontestedNeutralGates : neutralGates)
      .sort((first, second) => {
        const firstKnownPressure = getKnownPlayerUnitsForEnemy(state).filter((unit) => hexDistance(unit.coord, first.coord) <= 8).length * 80;
        const secondKnownPressure = getKnownPlayerUnitsForEnemy(state).filter((unit) => hexDistance(unit.coord, second.coord) <= 8).length * 80;
        const firstScore = (assessment.gateCaptureOpportunity[first.id] ?? 0) - (assessment.predictedGatePressure[first.id] ?? 0) * 1.4 - firstKnownPressure - first.occupation.Player * 180;
        const secondScore = (assessment.gateCaptureOpportunity[second.id] ?? 0) - (assessment.predictedGatePressure[second.id] ?? 0) * 1.4 - secondKnownPressure - second.occupation.Player * 180;
        return secondScore - firstScore;
      })[0];
    if (neutralGate) {
      return neutralGate;
    }
  }

  return gates[0];
}

function getEnemyBaseSentryCoord(state: GameState, unit: UnitInstance): UnitInstance["coord"] {
  const center = state.bases.Enemy.q;
  const offset = getStableUnitNumber(unit) % 3 === 0 ? -3 : getStableUnitNumber(unit) % 3 === 1 ? 0 : 3;
  return getNearestPassableCoord(state, { q: Math.max(0, Math.min(state.map.width - 1, center + offset)), r: 4 });
}

function getEnemyPatrolCoord(state: GameState, lane: GateState["id"], unit?: UnitInstance): UnitInstance["coord"] {
  const gate = (state.gates ?? []).find((candidate) => candidate.id === lane);
  const earlyHardPatrol = state.difficulty === "Hard" && state.day <= 10;
  const q = earlyHardPatrol
    ? gate?.coord.q ?? Math.floor(state.map.width * (lane === "West" ? 0.18 : 0.82))
    : gate?.coord.q ?? (lane === "West" ? Math.floor(state.map.width * 0.18) : Math.floor(state.map.width * 0.82));
  const earlyOffset = unit && getUnitDefinition(unit.type).humanBased ? 1 : 2;
  const r = Math.max(6, Math.min(state.map.height - 1, (gate?.coord.r ?? Math.floor(state.map.height * 0.5)) - (earlyHardPatrol ? earlyOffset : 3)));
  return getNearestPassableCoord(state, { q, r });
}

function chooseEnemyFireSupportPosition(state: GameState, unit: UnitInstance): UnitInstance["coord"] {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, unit.coord);
  const target = getPlayerIntelForEnemy(state)
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .sort((first, second) => getUnitInstanceValue(state, second.unit) * second.confidence - getUnitInstanceValue(state, first.unit) * first.confidence)[0];
  if (target) {
    const targetApproachOffset = Math.max(1, stats.attackRange - 1);
    const q = Math.max(2, Math.min(state.map.width - 3, target.predictedCoord.q));
    const minR = Math.floor(state.map.height * 0.32);
    const maxR = Math.floor(state.map.height * 0.62);
    const r = Math.max(minR, Math.min(maxR, target.predictedCoord.r - targetApproachOffset));
    return getNearestPassableCoord(state, { q, r });
  }

  return getNearestPassableCoord(state, {
    q: Math.floor(state.map.width * 0.5),
    r: Math.floor(state.map.height * 0.43)
  });
}

function getNearestPassableCoord(state: GameState, coord: UnitInstance["coord"]): UnitInstance["coord"] {
  return [...state.map.hexes]
    .filter((hex) => hex.passable)
    .sort((first, second) => hexDistance(coord, first.coord) - hexDistance(coord, second.coord))[0]?.coord ?? coord;
}

function getStableUnitNumber(unit: UnitInstance): number {
  const match = unit.id.match(/(\d+)$/);
  return match ? Number(match[1]) : 0;
}

function getEnemySeededOpeningMainEffortGateId(state: GameState): GateState["id"] {
  return getStableHashRatio(`${state.seed}|opening-main-effort`) < 0.5 ? "West" : "East";
}

function getOppositeGateId(gateId: GateState["id"]): GateState["id"] {
  return gateId === "West" ? "East" : "West";
}

function isHardOpeningInitialDeployment(state: GameState): boolean {
  return usesHardEnemyDoctrine(state) && state.day === HARD_OPENING_INITIAL_DEPLOYMENT_DAY && (state.gates ?? []).some((gate) => gate.owner === null);
}

function isHardOpeningDoctrineActive(state: GameState): boolean {
  return usesHardEnemyDoctrine(state) && state.day <= HARD_OPENING_GATE_COMMITMENT_LAST_DAY && (state.gates ?? []).some((gate) => gate.owner !== "Enemy");
}

function isHardMidgameDoctrineActive(state: GameState, plan?: EnemyTurnPlan): boolean {
  const phase = plan?.campaignPlan.phase ?? getEnemyStrategicAssessment(state).strategicPhase;
  return (
    usesHardEnemyDoctrine(state) &&
    state.day > HARD_OPENING_GATE_COMMITMENT_LAST_DAY &&
    phase !== "BaseDefenseEmergency" &&
    phase !== "BaseHold" &&
    !ownerControlsBothGates(state, "Enemy")
  );
}

function isHardEndgameDoctrineActive(state: GameState, plan?: EnemyTurnPlan): boolean {
  const phase = plan?.campaignPlan.phase ?? getEnemyStrategicAssessment(state).strategicPhase;
  return (
    usesHardEnemyDoctrine(state) &&
    ownerControlsBothGates(state, "Enemy") &&
    (phase === "BothGatesOwned" || phase === "BaseAssault" || phase === "BaseHold")
  );
}

function isHardCenterSupportDoctrineActive(state: GameState, plan: EnemyTurnPlan): boolean {
  return (
    isHardOpeningDoctrineActive(state) ||
    (
      isHardMidgameDoctrineActive(state, plan) &&
      plan.campaignPlan.phase !== "GateLockoutCombat" &&
      !isActiveEnemyBaseThreat(state, getEnemyBaseThreat(state))
    )
  );
}

function getEnemyCenterSupportStagingCoord(state: GameState, plan: EnemyTurnPlan): UnitInstance["coord"] {
  return isHardOpeningDoctrineActive(state) ? getEnemyOpeningCenterStagingCoord(state) : getEnemyMidgameCenterStagingCoord(state);
}

function getEnemyOpeningCenterStagingCoord(state: GameState): UnitInstance["coord"] {
  const frontRows = getFrontLineRows(state);
  const nmlStart = frontRows.enemyLineRow;
  const nmlCenter = Math.floor((frontRows.enemyLineRow + frontRows.playerLineRow) / 2);
  const dayProgress = Math.max(0, Math.min(1, (state.day - 1) / Math.max(1, HARD_OPENING_GATE_COMMITMENT_LAST_DAY - 1)));
  return getNearestPassableCoord(state, {
    q: state.bases.Enemy.q,
    r: Math.max(nmlStart, Math.min(frontRows.playerLineRow - 1, Math.round(nmlStart + (nmlCenter - nmlStart) * dayProgress)))
  });
}

function getEnemyMidgameCenterStagingCoord(state: GameState): UnitInstance["coord"] {
  const frontRows = getFrontLineRows(state);
  const nmlCenter = Math.floor((frontRows.enemyLineRow + frontRows.playerLineRow) / 2);
  return getNearestPassableCoord(state, {
    q: state.bases.Enemy.q,
    r: Math.max(frontRows.enemyLineRow + 1, Math.min(frontRows.playerLineRow - 1, nmlCenter))
  });
}

function choosePredictedPlayerTargetByDomain(state: GameState, unit: UnitInstance, domain: "Air" | "Ground"): UnitInstance["coord"] | undefined {
  return getPlayerIntelForEnemy(state)
    .filter((intel) => getUnitDefinition(intel.unit.type).domain === domain && canUnitTargetUnit(unit.type, intel.unit.type))
    .sort((first, second) => {
      const firstScore = getUnitInstanceValue(state, first.unit) * first.confidence - hexDistance(unit.coord, first.predictedCoord) * 5;
      const secondScore = getUnitInstanceValue(state, second.unit) * second.confidence - hexDistance(unit.coord, second.predictedCoord) * 5;
      return secondScore - firstScore;
    })[0]?.predictedCoord;
}

function choosePredictedPlayerTypeTarget(state: GameState, unit: UnitInstance, unitTypes: UnitType[]): UnitInstance["coord"] | undefined {
  return getPlayerIntelForEnemy(state)
    .filter((intel) => unitTypes.includes(intel.unit.type) && canUnitTargetUnit(unit.type, intel.unit.type))
    .sort((first, second) => {
      const firstScore = getUnitInstanceValue(state, first.unit) * first.confidence - hexDistance(unit.coord, first.predictedCoord) * 5;
      const secondScore = getUnitInstanceValue(state, second.unit) * second.confidence - hexDistance(unit.coord, second.predictedCoord) * 5;
      return secondScore - firstScore;
    })[0]?.predictedCoord;
}

function chooseEnemyScoutTarget(state: GameState, unit: UnitInstance): UnitInstance["coord"] | undefined {
  const assessment = getEnemyStrategicAssessment(state);
  const visible = getEnemyVisibleHexIds(state);
  const strategicTarget = chooseEnemyStrategicScoutTarget(state, unit);
  if (strategicTarget) {
    return strategicTarget.coord;
  }
  const knownTarget = [...assessment.knownPlayerUnits]
    .sort((first, second) => hexDistance(unit.coord, first.coord) - hexDistance(unit.coord, second.coord))[0];

  if (knownTarget && assessment.scoutNeed < 80) {
    return knownTarget.coord;
  }

  const gateTarget = chooseGateObjective(state, "Enemy", unit.coord);
  const gateDefense = chooseEnemyGateDefenseObjective(state, unit.coord);
  if (gateDefense && assessment.gateUrgency > 65) {
    return gateDefense.coord;
  }

  if (gateTarget && assessment.gateUrgency > 55) {
    return gateTarget.coord;
  }

  return state.map.hexes
    .map((hex) => {
      const newSight = countNewVisibleHexesFrom(state, hex.coord, getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, hex.coord).visibilityRange, visible, unit.owner, unit.type, unit.level);
      const forwardScore = Math.max(0, hex.coord.r - unit.coord.r) * 3;
      const centerPenalty = Math.abs(hex.coord.q - state.bases.Player.q) * 0.4;
      const distancePenalty = hexDistance(unit.coord, hex.coord) * 2;
      return {
        coord: hex.coord,
        score: newSight * 10 + forwardScore - centerPenalty - distancePenalty
      };
    })
    .sort((first, second) => second.score - first.score)[0]?.coord;
}

function chooseEnemyStrategicScoutTarget(
  state: GameState,
  unit: UnitInstance,
  plan?: EnemyTurnPlan
): { coord: UnitInstance["coord"]; score: number; reason: string } | undefined {
  if (!isObjectiveDirectedScoutUnit(unit.type)) {
    return undefined;
  }
  return getEnemyStrategicScoutTargets(state, unit, plan)[0];
}

function getEnemyStrategicScoutTargets(
  state: GameState,
  unit: UnitInstance,
  plan?: EnemyTurnPlan
): Array<{ coord: UnitInstance["coord"]; score: number; reason: string }> {
  const assessment = plan?.strategicSnapshot ?? getEnemyStrategicAssessment(state);
  const targets: Array<{ coord: UnitInstance["coord"]; score: number; reason: string }> = [];
  const add = (coord: UnitInstance["coord"] | undefined, score: number, reason: string): void => {
    if (!coord || !isPassableMapCoord(state, coord)) {
      return;
    }
    targets.push({
      coord: { ...coord },
      score: score + getEnemyScoutTargetVisibilityBonus(state, unit, coord) - hexDistance(unit.coord, coord) * 4,
      reason
    });
  };

  const gatePhase = isEnemyGateContinuityPhase(assessment.strategicPhase);
  if (assessment.strategicPhase === "GateLockoutCombat") {
    const gate = chooseEnemyGateLockoutCounterattackGate(state, plan);
    if (gate) {
      for (const target of getEnemyGateLockoutReconTargets(state, unit, gate, plan)) {
        add(target.coord, target.score, target.reason);
      }
    }
  }

  if (gatePhase) {
    for (const gate of state.gates ?? []) {
      if (gate.owner === "Enemy" && (assessment.predictedGatePressure[gate.id] ?? 0) < 55) {
        continue;
      }
      const laneCoord = chooseEnemyScoutGateLaneCoord(state, gate, unit.coord);
      const pressure = assessment.predictedGatePressure[gate.id] ?? 0;
      const ownershipBonus = gate.owner !== "Enemy" ? 120 : 50;
      add(laneCoord, 240 + ownershipBonus + pressure * 0.7 + getGateSideSightStrategicScore(state, gate), `gate-${gate.id}`);
    }
  }

  for (const threat of getEnemyAntiAirThreatMap(state, plan).threats) {
    const confidenceBonus = threat.confidence * (threat.probable ? 105 : 175);
    add(chooseEnemyScoutStandoffCoord(state, unit, threat.coord), 160 + confidenceBonus, threat.probable ? "probable-anti-air" : "known-anti-air");
  }

  for (const intel of (plan?.playerIntel ?? getEnemyPlannerPlayerIntel(state)).filter((entry) => entry.unit.type === "Artillery")) {
    add(chooseEnemyScoutStandoffCoord(state, unit, intel.predictedCoord), 260 + getUnitInstanceValue(state, intel.unit) * 0.8 * intel.confidence, "artillery");
  }

  if (isEnemyBaseOperationPhase(assessment.strategicPhase) || assessment.strategicPhase === "BothGatesOwned") {
    for (const coord of getEnemyBaseApproachScoutCoords(state)) {
      add(coord, 245 + assessment.baseAttackUrgency * 0.55, "base-approach");
    }
  } else if (assessment.strategicPhase === "BaseDefenseEmergency") {
    add(state.bases.Enemy, 230 + assessment.baseDefenseUrgency * 0.55, "base-defense");
  }

  const byHex = new Map<string, { coord: UnitInstance["coord"]; score: number; reason: string }>();
  for (const target of targets) {
    const key = hexId(target.coord);
    const existing = byHex.get(key);
    if (existing && target.reason === "artillery" && existing.reason !== "artillery") {
      byHex.set(key, { ...existing, reason: "artillery", score: Math.max(existing.score, target.score) });
    } else if (!existing || target.score > existing.score) {
      byHex.set(key, target);
    }
  }
  return [...byHex.values()]
    .filter((target) => target.score > 60)
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))
    .slice(0, 8);
}

function getEnemyGateLockoutReconTargets(
  state: GameState,
  unit: UnitInstance,
  gate: GateState,
  plan?: EnemyTurnPlan
): Array<{ coord: UnitInstance["coord"]; score: number; reason: string }> {
  const targets: Array<{ coord: UnitInstance["coord"]; score: number; reason: string }> = [];
  const visible = getEnemyVisibleHexIds(state);
  const add = (coord: UnitInstance["coord"] | undefined, score: number, reason: string): void => {
    if (!coord || !isPassableMapCoord(state, coord)) {
      return;
    }
    targets.push({ coord: { ...coord }, score, reason });
  };

  for (const intel of (plan?.playerIntel ?? getEnemyPlannerPlayerIntel(state))) {
    const distance = hexDistance(intel.predictedCoord, gate.coord);
    if (distance > ENEMY_GATE_THEATRE_PRIORITY_RADIUS + 2) {
      continue;
    }
    if (intel.unit.type === "Artillery" || intel.unit.type === "Anti-Air") {
      add(
        chooseEnemyScoutStandoffCoord(state, unit, intel.predictedCoord),
        520 + getUnitInstanceValue(state, intel.unit) * 0.7 * intel.confidence + Math.max(0, 9 - distance) * 24,
        intel.unit.type === "Anti-Air" ? "lockout-anti-air" : "lockout-artillery"
      );
      continue;
    }
    if (getUnitDefinition(intel.unit.type).humanBased || intel.unit.type === "Tank" || intel.unit.type === "IFV") {
      add(
        chooseEnemyScoutStandoffCoord(state, unit, intel.predictedCoord),
        340 + getEnemyGateTheatreTargetPriority(state, { ...intel.unit, coord: intel.predictedCoord }, gate) * 0.32,
        "lockout-blocker"
      );
    }
  }

  const sideHexIds = getGateSideHexes(state, gate);
  const hiddenLaneCoords = state.map.hexes
    .filter((hex) => hex.passable && sideHexIds.has(hex.id))
    .filter((hex) => hexDistance(hex.coord, gate.coord) <= ENEMY_GATE_THEATRE_PRIORITY_RADIUS)
    .filter((hex) => !visible.has(hex.id))
    .map((hex) => ({
      coord: hex.coord,
      score:
        380 +
        getEnemyScoutTargetVisibilityBonus(state, unit, hex.coord) * 1.4 +
        (isPlayerGateReinforcementApproach(state, hex.coord, gate) ? 95 : 0) -
        hexDistance(unit.coord, hex.coord) * 5 -
        hexDistance(hex.coord, gate.coord) * 8
    }))
    .sort((first, second) => second.score - first.score || hexId(first.coord).localeCompare(hexId(second.coord)))
    .slice(0, 3);
  for (const lane of hiddenLaneCoords) {
    add(lane.coord, lane.score, "lockout-hidden-blockers");
  }

  const gateStandoff = chooseEnemyScoutGateLaneCoord(state, gate, unit.coord);
  add(gateStandoff, 315 + getGateSideSightStrategicScore(state, gate), "lockout-counterattack-lane");

  return targets;
}

function isObjectiveDirectedScoutUnit(unitType: UnitType): boolean {
  return unitType === "IFV" || unitType === "Ghost" || unitType === "Reaper" || isReconUnit(unitType);
}

function getEnemyScoutTargetVisibilityBonus(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const visible = getEnemyVisibleHexIds(state);
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord);
  return countNewVisibleHexesFrom(state, coord, stats.visibilityRange, visible, unit.owner, unit.type, unit.level) * 7;
}

function chooseEnemyScoutGateLaneCoord(state: GameState, gate: GateState, origin: UnitInstance["coord"]): UnitInstance["coord"] | undefined {
  const sideHexes = getGateSideHexes(state, gate);
  return state.map.hexes
    .filter((hex) => hex.passable && sideHexes.has(hex.id) && hexDistance(hex.coord, gate.coord) <= 4 && !sameHex(hex.coord, gate.coord))
    .sort((first, second) => hexDistance(first.coord, origin) - hexDistance(second.coord, origin) || hexDistance(first.coord, gate.coord) - hexDistance(second.coord, gate.coord) || first.id.localeCompare(second.id))[0]?.coord
    ?? getPassableCoordsNear(state, gate.coord, 2).filter((coord) => !sameHex(coord, gate.coord)).sort((first, second) => hexDistance(first, origin) - hexDistance(second, origin))[0];
}

function chooseEnemyScoutStandoffCoord(state: GameState, unit: UnitInstance, target: UnitInstance["coord"]): UnitInstance["coord"] | undefined {
  return state.map.hexes
    .filter((hex) => {
      if (!hex.passable) {
        return false;
      }
      const visibilityRange = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, hex.coord, target).visibilityRange;
      const distance = hexDistance(hex.coord, target);
      return distance <= visibilityRange && distance >= Math.max(2, Math.floor(visibilityRange * 0.45));
    })
    .sort((first, second) => hexDistance(first.coord, unit.coord) - hexDistance(second.coord, unit.coord) || hexDistance(first.coord, target) - hexDistance(second.coord, target) || first.id.localeCompare(second.id))[0]?.coord;
}

function getEnemyBaseApproachScoutCoords(state: GameState): UnitInstance["coord"][] {
  const coords: UnitInstance["coord"][] = [];
  for (const gate of state.gates ?? []) {
    if (gate.owner === "Enemy") {
      coords.push(
        gate.coord,
        {
          q: Math.round((gate.coord.q * 2 + state.bases.Player.q) / 3),
          r: Math.round((gate.coord.r * 2 + state.bases.Player.r) / 3)
        },
        {
          q: Math.round((gate.coord.q + state.bases.Player.q * 2) / 3),
          r: Math.round((gate.coord.r + state.bases.Player.r * 2) / 3)
        }
      );
    }
  }
  coords.push(
    { q: state.bases.Player.q, r: Math.max(0, state.bases.Player.r - 4) },
    { q: Math.max(0, state.bases.Player.q - 3), r: Math.max(0, state.bases.Player.r - 2) },
    { q: Math.min(state.map.width - 1, state.bases.Player.q + 3), r: Math.max(0, state.bases.Player.r - 2) }
  );
  return uniqueCoords(coords.filter((coord) => isPassableMapCoord(state, coord))).slice(0, 6);
}

function scoreEnemyObjectiveDirectedScoutPosition(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], plan: EnemyTurnPlan): number {
  const mission = plan.rolesByUnitId[unit.id] ?? assignEnemyMission(state, unit);
  if (!isObjectiveDirectedScoutUnit(unit.type) || (mission !== "Scout" && mission !== "PatrolWest" && mission !== "PatrolEast" && unit.type !== "Reaper")) {
    return 0;
  }
  const targets = getEnemyStrategicScoutTargets(state, unit, plan);
  if (!targets.length) {
    return 0;
  }
  return targets.reduce((score, target) => {
    const currentDistance = hexDistance(unit.coord, target.coord);
    const nextDistance = hexDistance(coord, target.coord);
    const progress = Math.max(-2, currentDistance - nextDistance);
    const closeBonus = Math.max(0, 7 - nextDistance) * 18;
    const revealBonus = getEnemyScoutTargetVisibilityBonus(state, unit, coord) * 1.2;
    return score + Math.max(0, target.score) * 0.12 + progress * 48 + closeBonus + revealBonus;
  }, 0);
}

function chooseEnemyGateDefenseObjective(state: GameState, origin: UnitInstance["coord"]): GateState | undefined {
  const assessment = getEnemyStrategicAssessment(state);
  return (state.gates ?? [])
    .filter((gate) => gate.owner === "Enemy")
    .map((gate) => {
      const pressure = assessment.predictedGatePressure[gate.id] ?? 0;
      const knownPressure = getKnownPlayerUnitsForEnemy(state).filter((unit) => hexDistance(unit.coord, gate.coord) <= 7).length * 32;
      const distancePenalty = hexDistance(origin, gate.coord) * 5;
      return {
        gate,
        score: pressure + knownPressure + getGateIncomeBonusForEconomy(state.enemyEconomy) * 12 - distancePenalty
      };
    })
    .filter((entry) => entry.score > 70)
    .sort((first, second) => second.score - first.score)[0]?.gate;
}

function getEnemyReconAnchor(state: GameState): UnitInstance | undefined {
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => isReconUnit(unit.type))
    .sort((first, second) => {
      const firstScore = first.coord.r * 4 + getEffectiveUnitStats(state, first.owner, first.type, first.level, first.coord).visibilityRange + getUnitInstanceValue(state, first) * 0.04;
      const secondScore = second.coord.r * 4 + getEffectiveUnitStats(state, second.owner, second.type, second.level, second.coord).visibilityRange + getUnitInstanceValue(state, second) * 0.04;
      return secondScore - firstScore;
    })[0];
}

function isEnemyBaseCaptureCritical(state: GameState): boolean {
  return state.baseOccupation.Player > 0 || getOwnerUnits(state, "Enemy").some((unit) => getUnitDefinition(unit.type).humanBased && sameHex(unit.coord, state.bases.Player));
}

function getStrategicGatePositionScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const assessment = getEnemyStrategicAssessment(state);
  let score = 0;
  for (const gate of state.gates ?? []) {
    const distance = hexDistance(coord, gate.coord);
    if (distance > (state.difficulty === "Hard" ? 7 : 5)) {
      continue;
    }

    const baseGateScore = scoreGateObjective(state, unit.owner, unit.coord, gate);
    const captureMultiplier = getUnitDefinition(unit.type).humanBased ? (state.difficulty === "Hard" ? 1.28 : 1) : 0.28;
    const proximityScore = Math.max(0, (state.difficulty === "Hard" ? 8 : 6) - distance) * (gate.owner === unit.owner ? 8 : state.difficulty === "Hard" ? 25 : 18);
    const defendScore = gate.owner === unit.owner ? Math.max(0, 5 - distance) * (10 + assessment.gateUrgency * 0.04) : 0;
    score += baseGateScore * captureMultiplier * (distance === 0 ? 1 : 0.18) + proximityScore + defendScore;
  }
  return score;
}

function getBaseCaptureSupportScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  if (!isEnemyBaseCaptureCritical(state)) {
    return 0;
  }

  const distance = hexDistance(coord, state.bases.Player);
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord);
  const definition = getUnitDefinition(unit.type);
  const attackCoverage = distance <= stats.attackRange ? 80 : distance <= stats.attackRange + stats.moveRange ? 34 : 0;
  const bodyguard = Math.max(0, 7 - distance) * (definition.humanBased ? 8 : 14);
  return attackCoverage + bodyguard + state.baseOccupation.Player * 36;
}

function getVisionPositionScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord);
  const visible = getEnemyVisibleHexIds(state);
  const newSight = countNewVisibleHexesFrom(state, coord, stats.visibilityRange, visible, unit.owner, unit.type, unit.level);
  const knownPlayerCoverage = getKnownPlayerUnitsForEnemy(state).filter((playerUnit) => hexDistance(coord, playerUnit.coord) <= getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, playerUnit.coord).visibilityRange).length;

  if (isReconUnit(unit.type)) {
    return newSight * 5 + knownPlayerCoverage * 34;
  }

  if (needsReconSupport(unit.type)) {
    return knownPlayerCoverage * 20 + Math.min(18, newSight * 0.2);
  }

  return knownPlayerCoverage * 10;
}

function countNewVisibleHexesFrom(
  state: GameState,
  coord: UnitInstance["coord"],
  radius: number,
  alreadyVisible: Set<string>,
  owner?: Owner,
  unitType?: UnitType,
  level?: number
): number {
  let count = 0;
  const minQ = Math.max(0, coord.q - radius);
  const maxQ = Math.min(state.map.width - 1, coord.q + radius);
  const minR = Math.max(0, coord.r - radius);
  const maxR = Math.min(state.map.height - 1, coord.r + radius);
  for (let r = minR; r <= maxR; r += 1) {
    for (let q = minQ; q <= maxQ; q += 1) {
      const hex = getHex(state.map, { q, r });
      if (!hex || alreadyVisible.has(hex.id)) {
        continue;
      }

      const effectiveRadius = owner && unitType
        ? getEffectiveUnitStats(state, owner, unitType, level, coord, hex.coord).visibilityRange
        : radius;
      if (hexDistance(coord, hex.coord) <= effectiveRadius) {
        count += 1;
      }
    }
  }
  return count;
}

function scoreEnemyWeightedFogRevealFrom(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const visible = getEnemyVisibleHexIds(state);
  const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord);
  const baseDistance = Math.max(1, hexDistance(state.bases.Enemy, state.bases.Player));
  let score = 0;
  const minQ = Math.max(0, coord.q - stats.visibilityRange);
  const maxQ = Math.min(state.map.width - 1, coord.q + stats.visibilityRange);
  const minR = Math.max(0, coord.r - stats.visibilityRange);
  const maxR = Math.min(state.map.height - 1, coord.r + stats.visibilityRange);

  for (let r = minR; r <= maxR; r += 1) {
    for (let q = minQ; q <= maxQ; q += 1) {
      const hex = getHex(state.map, { q, r });
      if (!hex || visible.has(hex.id)) {
        continue;
      }

      const effectiveRadius = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, hex.coord).visibilityRange;
      if (hexDistance(coord, hex.coord) > effectiveRadius) {
        continue;
      }

      const playerBaseProximity = 1 - Math.min(1, hexDistance(hex.coord, state.bases.Player) / baseDistance);
      score += 0.55 + playerBaseProximity * 1.65;
    }
  }

  return score;
}

function getReconSupportPositionScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const anchor = getEnemyReconAnchor(state);
  if (!anchor || anchor.id === unit.id) {
    return 0;
  }

  const distance = hexDistance(coord, anchor.coord);
  if (needsReconSupport(unit.type)) {
    return Math.max(0, 9 - distance) * 9;
  }

  if (isReconUnit(unit.type)) {
    const supportUnitsNearby = getOwnerUnits(state, "Enemy").filter((ally) => needsReconSupport(ally.type) && hexDistance(coord, ally.coord) <= 8).length;
    return supportUnitsNearby * 12;
  }

  return Math.max(0, 5 - distance) * 3;
}

function getFireSupportPositionScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  if (unit.type !== "Artillery" && unit.type !== "Anti-Air") {
    return 0;
  }

  const firePosition = chooseEnemyFireSupportPosition(state, unit);
  const firePositionDistance = hexDistance(coord, firePosition);
  const centerQ = Math.floor(state.map.width * 0.5);
  const centerR = Math.floor(state.map.height * 0.45);
  const centerDistance = hexDistance(coord, { q: centerQ, r: centerR });
  const coverage = getPlayerIntelForEnemy(state)
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .reduce((score, intel) => {
      const distance = hexDistance(coord, intel.predictedCoord);
      const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, intel.predictedCoord);
      if (distance <= stats.attackRange) {
        return score + getUnitInstanceValue(state, intel.unit) * 0.32 * intel.confidence;
      }
      if (distance <= stats.attackRange + stats.moveRange) {
        return score + getUnitInstanceValue(state, intel.unit) * 0.12 * intel.confidence;
      }
      return score;
    }, 0);

  return Math.max(0, 18 - firePositionDistance) * 12 + Math.max(0, 18 - centerDistance) * 5 + coverage;
}

function getInfluenceCell(state: GameState, coord: UnitInstance["coord"]): InfluenceCell {
  const assessment = getEnemyStrategicAssessment(state);
  return assessment.influence[hexId(coord)] ?? {
    coord,
    threat: 0,
    support: 0,
    vision: 0,
    gate: 0,
    objective: 0,
    repair: 0
  };
}

function getInfluencePositionScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], mission: EnemyMission): number {
  const cell = getInfluenceCell(state, coord);
  const threatWeight = mission === "Repair" ? 2.4 : mission === "Scout" || mission === "PatrolWest" || mission === "PatrolEast" ? 1.1 : mission === "CaptureBase" || mission === "ProtectCapturer" ? 0.7 : mission === "BaseSentry" ? 0.9 : isEnemyGateLockoutClearingMission(mission) ? 1.05 : 1.4;
  const supportWeight = mission === "Scout" || mission === "PatrolWest" || mission === "PatrolEast" ? 0.35 : mission === "Siege" || mission === "Escort" || mission === "ProtectCapturer" || isEnemyGateLockoutCombatMission(mission) ? 1.35 : 0.8;
  const gateWeight = mission === "CaptureGate" || mission === "DefendGate" ? 1.2 : isEnemyGateLockoutCombatMission(mission) ? 1.05 : 0.22;
  const objectiveWeight = mission === "CaptureBase" || mission === "Siege" ? 1.0 : mission === "DefendBase" || mission === "BaseSentry" ? -0.1 : 0.35;
  const visionWeight = mission === "PatrolWest" || mission === "PatrolEast" ? 1.8 : isReconUnit(unit.type) ? 1.4 : needsReconSupport(unit.type) ? 0.45 : 0.2;
  const repairWeight = mission === "Repair" ? 2.2 : 0;
  return (
    cell.support * supportWeight +
    cell.gate * gateWeight +
    cell.objective * objectiveWeight +
    cell.vision * visionWeight +
    cell.repair * repairWeight -
    cell.threat * threatWeight
  );
}

function scoreEnemyPlacementSpacing(state: GameState, unitType: UnitType, coord: UnitInstance["coord"], mission: EnemyMission): number {
  if (isEnemySupplySupportUnit(unitType) || mission === "Repair" || mission === "DefendBase" || mission === "BaseSentry") {
    return 0;
  }

  const unitDomain = getUnitDefinition(unitType).domain;
  return getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    const sameDomain = getUnitDefinition(ally.type).domain === unitDomain;
    const distance = hexDistance(coord, ally.coord);
    if (distance === 0) {
      return score - 58;
    }
    if (distance === 1) {
      return score - 34;
    }
    if (sameDomain && distance === 2) {
      return score - 12;
    }
    if (sameDomain && distance >= 4 && distance <= 6) {
      return score + 10;
    }
    return score;
  }, 0);
}

function getFormationSpreadScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], mission: EnemyMission): number {
  if (state.difficulty !== "Hard" || mission === "DefendBase" || mission === "Repair") {
    return 0;
  }

  const unitDomain = getUnitDefinition(unit.type).domain;
  return getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id || getUnitDefinition(ally.type).domain !== unitDomain) {
      return score;
    }

    const distance = hexDistance(coord, ally.coord);
    if (distance === 0) {
      return score - 48;
    }
    if (distance === 1) {
      return score - 32;
    }
    if (distance === 2) {
      return score - 14;
    }
    if (distance >= 4 && distance <= 7) {
      return score + (mission === "CaptureGate" || mission === "CaptureBase" ? 7 : 4);
    }
    return score;
  }, 0);
}

function getTaskForceCohesionScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], mission: EnemyMission): number {
  const allies = getOwnerUnits(state, "Enemy").filter((ally) => ally.id !== unit.id);
  const recon = allies.filter((ally) => isReconUnit(ally.type)).sort((first, second) => hexDistance(coord, first.coord) - hexDistance(coord, second.coord))[0];
  const capturer = allies
    .filter((ally) => getUnitDefinition(ally.type).humanBased)
    .sort((first, second) => hexDistance(first.coord, state.bases.Player) - hexDistance(second.coord, state.bases.Player))[0];
  const heavy = allies
    .filter((ally) => needsReconSupport(ally.type) || ally.type === "Reaper" || ally.type === "Bomber")
    .sort((first, second) => hexDistance(coord, first.coord) - hexDistance(coord, second.coord))[0];

  let score = 0;
  const cohesionMultiplier = state.difficulty === "Hard" ? 0.62 : 1;
  if ((mission === "Siege" || mission === "Escort" || mission === "ProtectCapturer" || isEnemyGateLockoutClearingMission(mission)) && recon) {
    score += Math.max(0, 9 - hexDistance(coord, recon.coord)) * 10 * cohesionMultiplier;
  }
  if ((mission === "Scout" || mission === "InterceptAir") && heavy) {
    score += Math.max(0, 8 - hexDistance(coord, heavy.coord)) * 5 * cohesionMultiplier;
  }
  if ((mission === "CaptureBase" || mission === "Escort" || mission === "ProtectCapturer" || mission === "ReserveCapturer") && capturer) {
    score += Math.max(0, 7 - hexDistance(coord, capturer.coord)) * 8 * cohesionMultiplier;
  }
  if (isEnemyGateLockoutClearingMission(mission) && capturer) {
    score += Math.max(0, 6 - hexDistance(coord, capturer.coord)) * 7 * cohesionMultiplier;
  }
  if (state.difficulty === "Hard" && mission === "CaptureGate" && capturer) {
    score -= Math.max(0, 4 - hexDistance(coord, capturer.coord)) * 10;
  }
  return score;
}

function scoreTacticalLookahead(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"], mission: EnemyMission): number {
  const hypothetical: UnitInstance = { ...unit, coord };
  const possibleTargets = getPlayerIntelForEnemy(state)
    .filter((intel) => canUnitTargetUnit(unit.type, intel.unit.type))
    .map((intel) => {
      const target: UnitInstance = {
        ...intel.unit,
        coord: { ...intel.predictedCoord }
      };
      const distance = hexDistance(coord, target.coord);
      const stats = getEffectiveUnitStats(state, unit.owner, unit.type, unit.level, coord, target.coord);
      const attackSoon = distance <= stats.attackRange + stats.moveRange;
      const attackInTwoTurns = distance <= stats.attackRange + stats.moveRange * 2;
      const damage = estimateAttackDamage(state, hypothetical, target);
      if (attackSoon) {
        return scoreAttackTarget(state, hypothetical, target, damage) * intel.confidence - distance * 6;
      }
      if (attackInTwoTurns) {
        return scoreAttackTarget(state, hypothetical, target, damage) * intel.confidence * 0.38 - distance * 3;
      }
      return 0;
    });
  const bestFutureAttack = possibleTargets.length ? Math.max(...possibleTargets) : 0;
  const futureDanger = estimatePlayerDangerAt(state, unit, coord);
  const captureLookahead =
    getUnitDefinition(unit.type).humanBased && mission === "CaptureBase"
      ? Math.max(0, 10 - hexDistance(coord, state.bases.Player)) * 18
      : 0;
  const gateLookahead =
    mission === "CaptureGate" || mission === "DefendGate" || isEnemyGateLockoutCombatMission(mission)
      ? (state.gates ?? []).reduce((best, gate) => Math.max(best, Math.max(0, 7 - hexDistance(coord, gate.coord)) * 16), 0)
      : 0;

  return bestFutureAttack * (state.difficulty === "Hard" ? 0.5 : 0.22) + captureLookahead + gateLookahead - futureDanger * 0.45;
}

function getEnemyVanguard(state: GameState, excludedUnitId?: string): UnitInstance | undefined {
  return getOwnerUnits(state, "Enemy")
    .filter((unit) => unit.id !== excludedUnitId && getUnitDefinition(unit.type).humanBased)
    .sort((first, second) => hexDistance(first.coord, state.bases.Player) - hexDistance(second.coord, state.bases.Player))[0];
}

function getEnemyBaseThreat(state: GameState): UnitInstance & { score: number } | undefined {
  const cache = getEnemyEvaluationCache(state);
  if (cache.baseThreatComputed) {
    return cache.baseThreat;
  }

  cache.baseThreat = getPlayerIntelForEnemy(state)
    .map((intel) => ({
      ...intel.unit,
      coord: { ...intel.predictedCoord },
      score:
        scoreThreatToEnemyBase(state, {
          ...intel.unit,
          coord: intel.predictedCoord
        }) *
          intel.confidence +
        (intel.likelyObjective === "EnemyBase" ? 35 * intel.confidence : 0)
    }))
    .filter((unit) => unit.score > 0)
    .sort((first, second) => second.score - first.score)[0];
  cache.baseThreatComputed = true;
  return cache.baseThreat;
}

function isActiveEnemyBaseThreat(state: GameState, threat: (UnitInstance & { score: number }) | undefined): boolean {
  if (!threat) {
    return false;
  }

  if (state.baseOccupation.Enemy > 0 || sameHex(threat.coord, state.bases.Enemy)) {
    return true;
  }

  const distance = hexDistance(threat.coord, state.bases.Enemy);
  const captureThreat = getUnitDefinition(threat.type).humanBased && distance <= 5;
  return threat.score >= 220 || captureThreat;
}

function scoreThreatToEnemyBase(state: GameState, unit: UnitInstance): number {
  const distance = hexDistance(unit.coord, state.bases.Enemy);
  const definition = getUnitDefinition(unit.type);
  const responseRadius = getEnemyBaseResponseRadius(state);
  let score = 0;

  if (definition.humanBased && sameHex(unit.coord, state.bases.Enemy)) {
    score += 300 + state.baseOccupation.Enemy * 90;
  }

  if (distance <= responseRadius) {
    score += Math.max(0, responseRadius + 1 - distance) * (definition.humanBased ? 28 : 10);
    score += getUnitInstanceValue(state, unit) * 0.35;
  }

  return score;
}

function getFriendlySupportScore(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  const multiplier = state.difficulty === "Hard" ? 0.45 : 1;
  return getOwnerUnits(state, "Enemy").reduce((score, ally) => {
    if (ally.id === unit.id) {
      return score;
    }

    const distance = hexDistance(coord, ally.coord);
    if (distance <= 2) {
      return score + 8 * multiplier;
    }
    if (distance <= 5) {
      return score + 3 * multiplier;
    }
    return score;
  }, 0);
}

function estimatePlayerDangerAt(state: GameState, unit: UnitInstance, coord: UnitInstance["coord"]): number {
  return getPlayerIntelForEnemy(state).reduce((danger, intel) => {
    const playerUnit: UnitInstance = {
      ...intel.unit,
      coord: { ...intel.predictedCoord }
    };
    if (!canUnitTargetUnit(playerUnit.type, unit.type)) {
      return danger;
    }

    const distance = hexDistance(coord, playerUnit.coord);
    const stats = getEffectiveUnitStats(state, playerUnit.owner, playerUnit.type, playerUnit.level, playerUnit.coord, coord);
    const damage = estimateAttackDamage(state, playerUnit, unit);
    if (distance <= stats.attackRange) {
      return danger + damage * 1.5 * intel.confidence;
    }

    if (distance <= stats.attackRange + stats.moveRange) {
      return danger + damage * 0.75 * intel.confidence;
    }

    return danger;
  }, 0);
}

export interface AssuranceAiTestResult {
  name: string;
  passed: boolean;
  message?: string;
}

function createAiFixture(day = 10): GameState {
  const state = createInitialState(`ai-test-${day}`);
  state.started = true;
  state.paused = false;
  state.day = day;
  state.difficulty = "Hard";
  state.units = [];
  state.log = [];
  state.enemyEconomy.productionQueue = [];
  state.enemyEconomy.researchQueue = [];
  state.enemyEconomy.moneyPoundsBn = 500;
  invalidateEnemyEvaluationCache();
  return updateFog(state);
}

function addAiFixtureUnit(state: GameState, owner: Owner, type: UnitType, coord: UnitInstance["coord"], health?: number): UnitInstance {
  const level = owner === "Enemy" ? state.enemyEconomy.unitLevels[type] : state.economy.unitLevels[type];
  const maxHealth = getEffectiveUnitHealth(state, owner, type, level);
  const unit: UnitInstance = {
    id: `ai-test-unit-${state.nextId}`,
    owner,
    type,
    level,
    coord: { ...coord },
    health: health ?? maxHealth,
    maxHealth,
    placedDay: Math.max(1, state.day - 1),
    hasMovedThisDay: false,
    movementSpentThisDay: 0,
    hasAttackedThisDay: false
  };
  state.nextId += 1;
  state.units.push(unit);
  return unit;
}

function rememberAiFixtureUnit(state: GameState, unit: UnitInstance, spottedDay = state.day): void {
  state.spottedUnits.Enemy[unit.id] = {
    id: unit.id,
    owner: unit.owner,
    type: unit.type,
    level: unit.level,
    coord: { ...unit.coord },
    health: unit.health,
    maxHealth: unit.maxHealth,
    spottedDay
  };
}

function addKnownAiFixtureUnit(state: GameState, owner: Owner, type: UnitType, coord: UnitInstance["coord"], health?: number): UnitInstance {
  const unit = addAiFixtureUnit(state, owner, type, coord, health);
  rememberAiFixtureUnit(state, unit);
  return unit;
}

function resetAiFixtureEnemyInventory(state: GameState): void {
  state.enemyEconomy.inventoryByLevel ??= Object.fromEntries(UNIT_DEFINITIONS.map((unit) => [unit.type, {}])) as NonNullable<EconomyState["inventoryByLevel"]>;
  for (const unitType of ENEMY_UNIT_TYPES) {
    state.enemyEconomy.inventory[unitType] = 0;
    state.enemyEconomy.inventoryByLevel[unitType] = {};
  }
}

function testAiMediumAndEasyUseScaledHardDoctrine(): void {
  const base = createAiFixture(1);
  const enemyBase = base.bases.Enemy;
  addAiFixtureUnit(base, "Enemy", "Infantry", { q: enemyBase.q - 4, r: enemyBase.r });
  addAiFixtureUnit(base, "Enemy", "Infantry", { q: enemyBase.q - 2, r: enemyBase.r });
  addAiFixtureUnit(base, "Enemy", "Infantry", { q: enemyBase.q + 2, r: enemyBase.r });
  addAiFixtureUnit(base, "Enemy", "Infantry", { q: enemyBase.q + 4, r: enemyBase.r });
  addAiFixtureUnit(base, "Enemy", "Tank", { q: enemyBase.q - 1, r: enemyBase.r + 1 });
  addAiFixtureUnit(base, "Enemy", "IFV", { q: enemyBase.q + 1, r: enemyBase.r + 1 });
  addAiFixtureUnit(base, "Enemy", "Attack Heli", { q: enemyBase.q + 3, r: enemyBase.r + 1 });

  const makePlan = (difficulty: GameState["difficulty"]): EnemyTurnPlan => {
    const state = cloneState(base);
    state.difficulty = difficulty;
    return beginEnemyTurnPlan(updateFog(state));
  };

  const hardPlan = makePlan("Hard");
  const mediumPlan = makePlan("Medium");
  const easyPlan = makePlan("Easy");
  const hardRoleCount = Object.keys(hardPlan.rolesByUnitId).length;
  const mediumRoleCount = Object.keys(mediumPlan.rolesByUnitId).length;
  const easyRoleCount = Object.keys(easyPlan.rolesByUnitId).length;

  assertAiTest(mediumPlan.campaignPlan.phase === hardPlan.campaignPlan.phase, `Medium should use Hard campaign phase shape, got ${mediumPlan.campaignPlan.phase} vs ${hardPlan.campaignPlan.phase}`);
  assertAiTest(easyPlan.campaignPlan.phase === hardPlan.campaignPlan.phase, `Easy should use Hard campaign phase shape, got ${easyPlan.campaignPlan.phase} vs ${hardPlan.campaignPlan.phase}`);
  assertAiTest(mediumRoleCount > 0 && easyRoleCount > 0, `Medium/Easy should retain scaled Hard roles, got medium=${mediumRoleCount} easy=${easyRoleCount}`);
  assertAiTest(hardRoleCount >= mediumRoleCount && mediumRoleCount >= easyRoleCount, `role retention should scale Hard >= Medium >= Easy, got ${hardRoleCount}/${mediumRoleCount}/${easyRoleCount}`);
}

function seedAiFixtureCampaignGateAssignment(state: GameState, unit: UnitInstance, gateId: GateState["id"]): void {
  const assignedGateByUnitId: Record<string, GateState["id"]> = {
    [unit.id]: gateId
  };
  const rolesByUnitId: Record<string, EnemyMission> = {
    [unit.id]: "CaptureGate"
  };
  const playerIntel = getEnemyPlannerPlayerIntel(state);
  const objectiveClock = estimateEnemyObjectiveClocks(state, playerIntel);
  const laneTaskForces: Record<GateState["id"], EnemyLaneTaskForcePlan> = {
    West: createEnemyLaneTaskForcePlan(state, "West", assignedGateByUnitId, rolesByUnitId),
    East: createEnemyLaneTaskForcePlan(state, "East", assignedGateByUnitId, rolesByUnitId)
  };
  (state as GameStateWithEnemyCampaign).enemyCampaignPlan = {
    schemaVersion: 1,
    day: Math.max(1, state.day - 1),
    generatedDay: Math.max(1, state.day - 1),
    invalidationKey: buildEnemyCampaignInvalidationKey(state, rolesByUnitId, "OpeningGateRace", objectiveClock, playerIntel),
    phase: "OpeningGateRace",
    mainEffortGateId: gateId,
    secondaryGateId: gateId === "West" ? "East" : "West",
    assignedCapturerByGateId: getEnemyCampaignLaneField(laneTaskForces, "principalCapturerId"),
    backupCapturerByGateId: getEnemyCampaignLaneField(laneTaskForces, "backupCapturerId"),
    escortGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "escortIds"),
    scoutGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "scoutIds"),
    supportGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "supportIds"),
    baseAssaultPackage: createEmptyEnemyBaseAssaultPackage(),
    assignedGateByUnitId,
    laneTaskForces,
    baseAssaultRoute: [],
    expectedTurnsToCapture: objectiveClock.enemyTurnsToGates,
    objectiveClock
  };
}

function assertAiTest(condition: unknown, message: string): asserts condition {
  if (!condition) {
    throw new Error(message);
  }
}

function getAiTestEffectiveVisionRange(state: GameState, observer: UnitInstance, targetCoord: UnitInstance["coord"]): number {
  return getEffectiveUnitStats(state, observer.owner, observer.type, observer.level, observer.coord, targetCoord).visibilityRange;
}

function canAiTestUnitSeeCoord(state: GameState, observer: UnitInstance, targetCoord: UnitInstance["coord"]): boolean {
  return hexDistance(observer.coord, targetCoord) <= getAiTestEffectiveVisionRange(state, observer, targetCoord);
}

function getAiTestEffectiveAttackRange(state: GameState, attacker: UnitInstance, targetCoord: UnitInstance["coord"]): number {
  return getEffectiveUnitStats(state, attacker.owner, attacker.type, attacker.level, attacker.coord, targetCoord).attackRange;
}

function isAiTestCoordInEffectiveAttackRange(state: GameState, attacker: UnitInstance, targetCoord: UnitInstance["coord"]): boolean {
  return hexDistance(attacker.coord, targetCoord) <= getAiTestEffectiveAttackRange(state, attacker, targetCoord);
}

function testAiFormationSpreadsWhenSafe(): void {
  const state = createAiFixture(12);
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: 14, r: 10 });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: 15, r: 10 });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: 16, r: 11 });
  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(visibleTank), "formation fixture tank must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleTank!.id] = "Escort";

  const bunched = createEnemyCompoundAction(visibleState, visibleTank!, plan, "Move", { moveTo: { q: 16, r: 10 } }, {}, {});
  const spread = createEnemyCompoundAction(visibleState, visibleTank!, plan, "Move", { moveTo: { q: 11, r: 10 } }, {}, {});

  assertAiTest(
    spread.breakdown.formation > bunched.breakdown.formation + 180,
    `safe spread should beat tight clustering in formation score, spread=${spread.breakdown.formation.toFixed(1)} bunched=${bunched.breakdown.formation.toFixed(1)}`
  );
}

function testAiRepairAuraAllowsTightFormation(): void {
  const state = createAiFixture(12);
  const damaged = addAiFixtureUnit(state, "Enemy", "Tank", { q: 12, r: 10 }, 5);
  addAiFixtureUnit(state, "Enemy", "Supply Truck", { q: 13, r: 10 });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: 13, r: 11 });
  const visibleState = updateFog(state);
  const visibleDamaged = visibleState.units.find((unit) => unit.id === damaged.id);
  assertAiTest(Boolean(visibleDamaged), "repair fixture tank must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleDamaged!.id] = "Escort";
  const repairAuraMove = createEnemyCompoundAction(visibleState, visibleDamaged!, plan, "Move", { moveTo: { q: 13, r: 10 } }, {}, {});

  assertAiTest(
    repairAuraMove.breakdown.formation >= 0,
    `repair near Supply Truck should not receive tight-formation penalty, got ${repairAuraMove.breakdown.formation.toFixed(1)}`
  );
}

function testAiNonAttackingMoveRejectsPlayerReplyRange(): void {
  const state = createAiFixture(12);
  const capturer = addAiFixtureUnit(state, "Enemy", "Infantry", { q: 14, r: 8 });
  const player = addKnownAiFixtureUnit(state, "Player", "Infantry", { q: 14, r: 13 });
  const visibleState = updateFog(state);
  const visibleCapturer = visibleState.units.find((unit) => unit.id === capturer.id);
  assertAiTest(Boolean(visibleCapturer), "reply-range fixture capturer must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleCapturer!.id] = "CaptureGate";

  const unsafeMove = { q: 14, r: 11 };
  const action = createEnemyCompoundAction(visibleState, visibleCapturer!, plan, "Move", { moveTo: unsafeMove }, {}, {});
  assertAiTest(canMoveUnitTo(visibleState, visibleCapturer!, unsafeMove), "fixture unsafe move must be legal geometrically");
  assertAiTest(
    estimatePlayerLikelyReplyDamageAtPlanner(visibleState, visibleCapturer!, unsafeMove, plan) > 0,
    `fixture unsafe move should enter ${player.type} reply range`
  );
  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, visibleCapturer!, action, plan), "capture-role move into reply range without attacking must be rejected unless it enters an objective");
}

function testAiOpeningShadowCapturerKeepsPaceToGate(): void {
  const state = createAiFixture(4);
  const gate = state.gates.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "fixture must include west gate");
  const principal = addAiFixtureUnit(state, "Enemy", "Infantry", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 5) });
  const backup = addAiFixtureUnit(state, "Enemy", "Infantry", { q: gate!.coord.q + 1, r: Math.max(0, gate!.coord.r - 5) });
  const visibleState = updateFog(state);
  const visibleGate = visibleState.gates.find((candidate) => candidate.id === gate!.id);
  const visiblePrincipal = visibleState.units.find((unit) => unit.id === principal.id);
  const visibleBackup = visibleState.units.find((unit) => unit.id === backup.id);
  assertAiTest(Boolean(visibleGate && visiblePrincipal && visibleBackup), "shadow capturer fixture units must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visiblePrincipal!.id] = "CaptureGate";
  plan.rolesByUnitId[visibleBackup!.id] = "ShadowCapturer";
  plan.campaignPlan.assignedGateByUnitId[visiblePrincipal!.id] = visibleGate!.id;
  plan.campaignPlan.assignedGateByUnitId[visibleBackup!.id] = visibleGate!.id;
  plan.campaignPlan.laneTaskForces[visibleGate!.id].principalCapturerId = visiblePrincipal!.id;
  plan.campaignPlan.laneTaskForces[visibleGate!.id].backupCapturerId = visibleBackup!.id;

  const move = chooseEnemyPlannerShadowCapturerMove(visibleState, visibleBackup!, plan, visibleGate!);
  assertAiTest(Boolean(move), "shadow capturer should not hold just because it is already trailing the principal while far from the gate");
  assertAiTest(
    hexDistance(move!, visibleGate!.coord) < hexDistance(visibleBackup!.coord, visibleGate!.coord),
    `shadow capturer should keep pace toward gate, got ${hexId(move!)}`
  );
}

function testAiPlacesAllInventoryEveryTurn(): void {
  const state = createAiFixture(7);
  resetAiFixtureEnemyInventory(state);
  const inventoryUnits: UnitType[] = ["Infantry", "Infantry", "Infantry", "Infantry", "Tank", "Tank", "IFV", "IFV", "Artillery", "Anti-Air", "Supply Truck", "Attack Heli"];
  for (const unitType of inventoryUnits) {
    addInventoryUnitAtLevel(state.enemyEconomy, unitType, 1);
  }

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const simulated = planEnemyPlacement(visibleState, plan);
  const remainingInventory = ENEMY_UNIT_TYPES.reduce((total, unitType) => total + (simulated.enemyEconomy.inventory[unitType] ?? 0), 0);

  assertAiTest(plan.placementPlan.length === inventoryUnits.length, `AI should place all inventory, placed ${plan.placementPlan.length}/${inventoryUnits.length}`);
  assertAiTest(remainingInventory === 0, `AI simulated placement should empty inventory, remaining ${remainingInventory}`);
}

function testAiProductionPrefersAffordableTankOverRedundantIfv(): void {
  const state = createAiFixture(6);
  resetAiFixtureEnemyInventory(state);
  state.enemyEconomy.moneyPoundsBn = getProductionCost("Tank") + 4;
  addAiFixtureUnit(state, "Enemy", "IFV", { q: state.bases.Enemy.q - 4, r: state.bases.Enemy.r + 4 });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: state.bases.Enemy.q - 2, r: state.bases.Enemy.r + 4 });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: state.bases.Enemy.q + 2, r: state.bases.Enemy.r + 4 });
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: state.bases.Enemy.q - 5, r: state.bases.Enemy.r + 13 });
  addKnownAiFixtureUnit(state, "Player", "Infantry", { q: state.bases.Enemy.q - 6, r: state.bases.Enemy.r + 12 });

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const candidates = getEnemyPlannerProductionCandidates(visibleState, plan);
  const tank = candidates.find((item) => item.unitType === "Tank");
  const ifv = candidates.find((item) => item.unitType === "IFV");
  const purchase = chooseNextEnemyProductionPlanItem(visibleState, plan, []);

  assertAiTest(Boolean(tank), "affordable Tank should remain a production candidate");
  assertAiTest(Boolean(ifv), "IFV should remain available for comparison");
  assertAiTest(tank!.priority > ifv!.priority, `Tank should outrank redundant IFV, Tank=${tank!.priority.toFixed(1)} IFV=${ifv!.priority.toFixed(1)}`);
  assertAiTest(purchase?.unitType === "Tank", `AI should buy Tank over redundant IFV, got ${purchase?.unitType ?? "none"}`);
}

function testAiProductionHonorsHardUnitCaps(): void {
  const cappedTypes = Object.entries(ENEMY_PRODUCTION_HARD_LIMITS) as Array<[UnitType, number]>;
  for (const [unitType, limit] of cappedTypes) {
    const state = createAiFixture(15);
    resetAiFixtureEnemyInventory(state);
    state.enemyEconomy.moneyPoundsBn = 500;
    for (let index = 0; index < limit - 1; index += 1) {
      addAiFixtureUnit(state, "Enemy", unitType, { q: 2 + (index % 8), r: 2 + Math.floor(index / 8) });
    }

    assertAiTest(!isEnemyProductionHardCapped(state, unitType), `${unitType} should be eligible below hard cap`);
    state.enemyEconomy.inventory[unitType] = 1;
    state.enemyEconomy.inventoryByLevel![unitType][state.enemyEconomy.unitLevels[unitType]] = 1;
    assertAiTest(isEnemyProductionHardCapped(state, unitType), `${unitType} should be capped by fielded plus inventory total`);

    const visibleState = updateFog(state);
    const plan = beginEnemyTurnPlan(visibleState);
    const candidates = getEnemyPlannerProductionCandidates(visibleState, plan);
    assertAiTest(!candidates.some((item) => item.kind === "production" && item.unitType === unitType), `${unitType} production should not be considered at hard cap`);
  }

  const queuedState = createAiFixture(15);
  resetAiFixtureEnemyInventory(queuedState);
  for (let index = 0; index < 4; index += 1) {
    addAiFixtureUnit(queuedState, "Enemy", "Tank", { q: 2 + index, r: 2 });
  }
  queuedState.enemyEconomy.inventory.Tank = 1;
  queuedState.enemyEconomy.inventoryByLevel!.Tank[queuedState.enemyEconomy.unitLevels.Tank] = 1;
  assertAiTest(!isEnemyProductionHardCapped(queuedState, "Tank"), "Tank should remain eligible at five total stock");
  queuedState.enemyEconomy.productionQueue.push({
    id: "ai-test-tank-job",
    owner: "Enemy",
    unitType: "Tank",
    unitLevel: queuedState.enemyEconomy.unitLevels.Tank,
    startedDay: queuedState.day,
    availableDay: queuedState.day + getProductionDays("Tank")
  });
  assertAiTest(isEnemyProductionHardCapped(queuedState, "Tank"), "queued Tank production should count toward the hard cap");

  const specialState = createAiFixture(15);
  resetAiFixtureEnemyInventory(specialState);
  for (let index = 0; index < 8; index += 1) {
    addAiFixtureUnit(specialState, "Enemy", "Operator", { q: 2 + (index % 8), r: 3 + Math.floor(index / 8) });
  }
  specialState.enemyEconomy.inventory.Operator = 3;
  specialState.enemyEconomy.productionQueue.push({
    id: "ai-test-operator-job",
    owner: "Enemy",
    unitType: "Operator",
    unitLevel: specialState.enemyEconomy.unitLevels.Operator,
    startedDay: specialState.day,
    availableDay: specialState.day + getProductionDays("Operator")
  });
  assertAiTest(!isEnemyProductionHardCapped(specialState, "Operator"), "special units should not have hard production caps");
}

function testAiProductionVariableFitScalesWithEconomyAndTime(): void {
  const early = createAiFixture(4);
  resetAiFixtureEnemyInventory(early);
  early.enemyEconomy.incomePoundsBn = 3;
  early.enemyEconomy.efficiencyLevel = 1;

  const late = createAiFixture(30);
  resetAiFixtureEnemyInventory(late);
  late.enemyEconomy.incomePoundsBn = 14;
  late.enemyEconomy.efficiencyLevel = 5;
  late.enemyEconomy.unitLevels.Reaper = 3;
  for (let index = 0; index < 8; index += 1) {
    addAiFixtureUnit(late, "Enemy", "Infantry", { q: 2 + (index % 4), r: 2 + Math.floor(index / 4) });
  }

  const earlyInfantryFit = scoreEnemyProductionVariableFit(early, "Infantry");
  const lateInfantryFit = scoreEnemyProductionVariableFit(late, "Infantry");
  const earlyReaperFit = scoreEnemyProductionVariableFit(early, "Reaper");
  const lateReaperFit = scoreEnemyProductionVariableFit(late, "Reaper");

  assertAiTest(lateInfantryFit < earlyInfantryFit, `late/high-efficiency stock should reduce basic Infantry fit; early=${earlyInfantryFit.toFixed(1)} late=${lateInfantryFit.toFixed(1)}`);
  assertAiTest(lateReaperFit > earlyReaperFit, `late/high-efficiency income should increase Reaper fit; early=${earlyReaperFit.toFixed(1)} late=${lateReaperFit.toFixed(1)}`);
  assertAiTest(lateReaperFit > lateInfantryFit, `late production fit should favor expensive special units; Reaper=${lateReaperFit.toFixed(1)} Infantry=${lateInfantryFit.toFixed(1)}`);
}

function testAiLateGameReaperBiasStartsAtDayFortyFiveAndSaturates(): void {
  const createFixture = (day: number): GameState => {
    const state = createAiFixture(day);
    resetAiFixtureEnemyInventory(state);
    satisfyAiFixtureEfficiencyGate(state);
    addBuilding(state, "Enemy", "Special Services");
    addBuilding(state, "Enemy", "Drone Factory");
    addBuilding(state, "Enemy", "Airfield");
    state.enemyEconomy.moneyPoundsBn = 500;
    state.enemyEconomy.incomePoundsBn = 14;
    state.enemyEconomy.efficiencyLevel = 5;
    state.enemyEconomy.productionCapacityLevel = 3;
    state.enemyEconomy.productionSpeedLevel = 3;
    state.enemyEconomy.unitLevels.Reaper = 3;
    state.enemyEconomy.unitLevels.Tank = 3;
    addAiFixtureUnit(state, "Enemy", "Reaper", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 2 });
    return updateFog(state);
  };

  const before = createFixture(44);
  const after = createFixture(45);
  const beforeBias = getEnemyLateReaperProductionBias(before, "Reaper");
  const afterBias = getEnemyLateReaperProductionBias(after, "Reaper");
  const beforeSpread = scoreEnemyProductionChoice(before, "Reaper") - scoreEnemyProductionChoice(before, "Tank");
  const afterSpread = scoreEnemyProductionChoice(after, "Reaper") - scoreEnemyProductionChoice(after, "Tank");

  assertAiTest(beforeBias === 0, `late Reaper bias should be inactive before day 45, got ${beforeBias.toFixed(1)}`);
  assertAiTest(afterBias >= 200, `late Reaper bias should activate on day 45, got ${afterBias.toFixed(1)}`);
  assertAiTest(
    afterSpread > beforeSpread + 160,
    `day 45 should lift Reaper relative to Tank; before=${beforeSpread.toFixed(1)} after=${afterSpread.toFixed(1)}`
  );

  const saturated = createFixture(45);
  for (let index = 0; index < 5; index += 1) {
    addAiFixtureUnit(saturated, "Enemy", "Reaper", {
      q: Math.max(0, Math.min(saturated.map.width - 1, saturated.bases.Enemy.q + index - 2)),
      r: saturated.bases.Enemy.r + 3
    });
  }
  const saturatedBias = getEnemyLateReaperProductionBias(updateFog(saturated), "Reaper");
  assertAiTest(
    saturatedBias < afterBias * 0.5,
    `late Reaper bias should taper with existing Reapers; lean=${afterBias.toFixed(1)} saturated=${saturatedBias.toFixed(1)}`
  );
  assertAiTest(
    getEnemyLateReaperProductionBias(after, "Tank") === 0,
    "late Reaper bias should not affect non-Reaper production"
  );
}

function testAiProductionRepeatingLastUnitDropsScore(): void {
  const baseline = createAiFixture(14);
  resetAiFixtureEnemyInventory(baseline);
  baseline.enemyEconomy.moneyPoundsBn = 180;
  baseline.enemyEconomy.incomePoundsBn = 9;
  baseline.enemyEconomy.lastProductionUnitType = "IFV";

  const repeated = cloneState(baseline);
  repeated.enemyEconomy.lastProductionUnitType = "Tank";

  const baselineTankFit = scoreEnemyProductionVariableFit(baseline, "Tank");
  const repeatedTankFit = scoreEnemyProductionVariableFit(repeated, "Tank");
  const repetitionPenalty = getEnemyProductionRepetitionPenalty(repeated, "Tank");
  const nonRepeatedPenalty = getEnemyProductionRepetitionPenalty(baseline, "Tank");

  assertAiTest(nonRepeatedPenalty === 0, `non-repeated Tank should have no repetition penalty, got ${nonRepeatedPenalty.toFixed(1)}`);
  assertAiTest(repetitionPenalty >= 280, `repeated Tank should receive a significant repetition penalty, got ${repetitionPenalty.toFixed(1)}`);
  assertAiTest(
    repeatedTankFit < baselineTankFit - 240,
    `last-produced Tank should score much lower; baseline=${baselineTankFit.toFixed(1)} repeated=${repeatedTankFit.toFixed(1)} penalty=${repetitionPenalty.toFixed(1)}`
  );
}

function testAiProductionBasicGroundDevaluesWithDay(): void {
  const early = createAiFixture(6);
  resetAiFixtureEnemyInventory(early);
  early.enemyEconomy.incomePoundsBn = 8;
  early.enemyEconomy.efficiencyLevel = 2;

  const late = cloneState(early);
  late.day = 30;

  const basicGroundUnits: UnitType[] = ["Infantry", "IFV", "Supply Truck", "Artillery", "Anti-Air", "Tank"];
  for (const unitType of basicGroundUnits) {
    const earlyFit = scoreEnemyProductionVariableFit(early, unitType);
    const lateFit = scoreEnemyProductionVariableFit(late, unitType);
    assertAiTest(
      lateFit < earlyFit - 300,
      `${unitType} should be strongly devalued by day 30; early=${earlyFit.toFixed(1)} late=${lateFit.toFixed(1)}`
    );
  }

  const lateArtilleryFit = scoreEnemyProductionVariableFit(late, "Artillery");
  const lateReaperFit = scoreEnemyProductionVariableFit(late, "Reaper");
  assertAiTest(
    lateReaperFit > lateArtilleryFit + 500,
    `late production fit should strongly prefer advanced units over Tank Factory basics; Reaper=${lateReaperFit.toFixed(1)} Artillery=${lateArtilleryFit.toFixed(1)}`
  );
}

function testAiNoProductionCanBeatProductionCandidates(): void {
  const state = createAiFixture(26);
  resetAiFixtureEnemyInventory(state);
  state.enemyEconomy.moneyPoundsBn = getProductionCost("Supply Truck");
  state.enemyEconomy.incomePoundsBn = 0;
  for (let index = 0; index < 6; index += 1) {
    addAiFixtureUnit(state, "Enemy", "Infantry", { q: 2 + (index % 3), r: 2 + Math.floor(index / 3) });
  }
  for (let index = 0; index < 4; index += 1) {
    addAiFixtureUnit(state, "Enemy", "IFV", { q: 8 + index, r: 2 });
  }
  for (let index = 0; index < 5; index += 1) {
    addAiFixtureUnit(state, "Enemy", "Artillery", { q: 3 + index, r: 5 });
    addAiFixtureUnit(state, "Enemy", "Anti-Air", { q: 3 + index, r: 6 });
  }
  for (let index = 0; index < 2; index += 1) {
    addAiFixtureUnit(state, "Enemy", "Supply Truck", { q: 10 + index, r: 5 });
  }

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const candidates = getEnemyPlannerProductionCandidates(visibleState, plan);
  const best = candidates.sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost)[0];
  const noProductionPriority = scoreEnemyNoProductionChoice(visibleState, plan);
  const choice = chooseNextEnemyProductionPlanItem(visibleState, plan, []);

  assertAiTest(Boolean(best), "low-income stock fixture should still have production candidates to compare against");
  assertAiTest(noProductionPriority >= best!.priority, `not producing should outscore best production; none=${noProductionPriority.toFixed(1)} best=${best!.unitType} ${best!.priority.toFixed(1)}`);
  assertAiTest(!choice, `production chooser should allow not producing to win, got ${choice?.unitType ?? "none"}`);
}

