function testAiOpeningArmorPressesTowardGateSupport(): void {
  const state = createAiFixture(5);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  assertAiTest(Boolean(westGate), "fixture must include west gate");
  const edgeTankCoord = getNearestPassableCoord(state, { q: 0, r: Math.max(0, westGate!.coord.r - 8) });
  const edgeTank = addAiFixtureUnit(state, "Enemy", "Tank", edgeTankCoord);
  const rearTankCoord = getNearestPassableCoord(state, { q: Math.max(0, state.bases.Enemy.q - 2), r: Math.max(0, state.bases.Enemy.r + 5) });
  const rearTank = addAiFixtureUnit(state, "Enemy", "Tank", rearTankCoord);
  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const visibleEdgeTank = visibleState.units.find((unit) => unit.id === edgeTank.id);
  const visibleRearTank = visibleState.units.find((unit) => unit.id === rearTank.id);
  assertAiTest(Boolean(visibleEdgeTank && visibleRearTank), "opening armor fixture units must remain visible");

  const edgeTargetGate = chooseEnemyPlannerOpeningGateSupportTarget(visibleState, visibleEdgeTank!, plan);
  const edgeMove = chooseEnemyPlannerEarlyArmorFormationMove(visibleState, visibleEdgeTank!, plan, {});
  assertAiTest(Boolean(edgeTargetGate && edgeMove), "edge Tank should choose a gate-support pressure move");
  assertAiTest(edgeMove!.q >= 2, `edge Tank should leave the extreme map edge, got ${hexId(edgeMove!)}`);
  assertAiTest(
    hexDistance(edgeMove!, edgeTargetGate!.coord) < hexDistance(visibleEdgeTank!.coord, edgeTargetGate!.coord),
    `edge Tank should move closer to its gate theatre, got ${hexId(edgeMove!)}`
  );

  const rearTargetGate = chooseEnemyPlannerOpeningGateSupportTarget(visibleState, visibleRearTank!, plan);
  assertAiTest(Boolean(rearTargetGate), "rear Tank should have an opening support gate target");
  const rearSupportCoord = rearTargetGate ? chooseEnemyPlannerOpeningGateArmorSupportCoord(visibleState, visibleRearTank!, plan, rearTargetGate) : undefined;
  const rearMove = chooseEnemyPlannerEarlyArmorFormationMove(visibleState, visibleRearTank!, plan, {});
  assertAiTest(Boolean(rearSupportCoord && rearMove), "rear Tank should keep pushing toward opening support instead of holding in home area");
  assertAiTest(
    hexDistance(rearMove!, rearSupportCoord!) < hexDistance(visibleRearTank!.coord, rearSupportCoord!),
    `rear Tank should move closer to support position, got ${hexId(rearMove!)}`
  );
}

function testAiIfvMoveAttackRetreatsVisibleInfantry(): void {
  const state = createAiFixture(6);
  const ifv = addAiFixtureUnit(state, "Enemy", "IFV", { q: 24, r: 18 });
  const infantry = addAiFixtureUnit(state, "Player", "Infantry", { q: 23, r: 25 });
  const visibleState = updateFog(state);
  const visibleIfv = visibleState.units.find((unit) => unit.id === ifv.id);
  const visibleInfantry = visibleState.units.find((unit) => unit.id === infantry.id);
  assertAiTest(Boolean(visibleIfv && visibleInfantry), "IFV soft-target fixture units must remain visible");

  const plan = beginEnemyTurnPlan(visibleState);
  const threatMap = getEnemyAntiAirThreatMap(visibleState, plan);
  const tacticalActions = enumerateEnemyImmediateTacticalAttackActions(visibleState, visibleIfv!, plan, {}, {}, threatMap);
  const infantryAction = tacticalActions.find((action) =>
    action.targetId === visibleInfantry!.id &&
    (action.kind === "MoveAttackRetreat" || action.kind === "MoveThenAttack")
  );
  assertAiTest(Boolean(infantryAction), "IFV should generate a move-attack action against visible Infantry in combined move/attack range");

  finalizeEnemyTacticalPlan(visibleState, plan);
  const planned = plan.plannedActions.find((action) => action.unitId === visibleIfv!.id);
  assertAiTest(Boolean(planned), "IFV should receive a tactical action");
  assertAiTest(
    planned?.targetId === visibleInfantry!.id && (planned.kind === "MoveAttackRetreat" || planned.kind === "MoveThenAttack"),
    `IFV should take the safe soft-target shot instead of sitting or only moving, got ${planned?.kind ?? "none"} target ${planned?.targetType ?? "none"}`
  );
}

