function testAiEfficiencyResearchOutranksRoutineUnitUpgrade(): void {
  const state = createAiFixture(14);
  state.enemyEconomy.moneyPoundsBn = 240;
  state.enemyEconomy.efficiencyLevel = 1;
  state.enemyEconomy.productionCapacityLevel = 2;
  state.enemyEconomy.researchCapacityLevel = 2;
  state.enemyEconomy.productionSpeedLevel = 2;
  state.enemyEconomy.researchSpeedLevel = 2;
  state.enemyEconomy.researchQueue = [];
  state.enemyEconomy.productionQueue = [];
  addBuilding(state, "Enemy", "Tank Factory");
  addBuilding(state, "Enemy", "Special Services");
  addBuilding(state, "Enemy", "Drone Factory");
  addAiFixtureUnit(state, "Enemy", "Tank", { q: 12, r: 6 });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: 14, r: 6 });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: 16, r: 6 });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: 18, r: 6 });

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const candidates = getEnemyPlannerResearchCandidates(visibleState, plan);
  const efficiency = candidates.find((item) => item.researchType === "Efficiency");
  const tankUpgrade = candidates.find((item) => item.researchType === "UnitUpgrade" && item.researchUnitType === "Tank");
  const bestUnitUpgrade = candidates
    .filter((item) => item.researchType === "UnitUpgrade")
    .sort((first, second) => second.priority - first.priority)[0];
  const weakestNonUpgrade = candidates
    .filter((item) => item.researchType && item.researchType !== "UnitUpgrade")
    .sort((first, second) => first.priority - second.priority)[0];
  const research = chooseNextEnemyResearchPlanItem(visibleState, plan, []);

  assertAiTest(Boolean(efficiency), "low-efficiency fixture should expose Efficiency research");
  assertAiTest(Boolean(tankUpgrade), "routine Tank fixture should expose Tank upgrade research");
  assertAiTest(Boolean(bestUnitUpgrade && weakestNonUpgrade), "unit-upgrade ordering fixture should expose both upgrade and non-upgrade research");
  assertAiTest(
    bestUnitUpgrade!.priority < weakestNonUpgrade!.priority,
    `Unit upgrades should remain below non-upgrade research, got upgrade=${bestUnitUpgrade!.priority.toFixed(1)} non-upgrade=${weakestNonUpgrade!.priority.toFixed(1)}`
  );
  assertAiTest(
    efficiency!.priority > tankUpgrade!.priority,
    `Efficiency should outrank routine Tank upgrade, got Efficiency=${efficiency!.priority.toFixed(1)} Tank=${tankUpgrade!.priority.toFixed(1)}`
  );
  assertAiTest(
    research?.researchType === "Efficiency",
    `AI should choose Efficiency over routine Tank upgrade, got ${research?.researchType ?? "none"}${research?.researchUnitType ? `:${research.researchUnitType}` : ""}`
  );
}

