function testAiDaySevenEfficiencyGateBlocksProductionUntilStarted(): void {
  const state = createAiFixture(7);
  state.enemyEconomy.moneyPoundsBn = 220;
  state.enemyEconomy.efficiencyLevel = 2;
  state.enemyEconomy.researchQueue = [];
  state.enemyEconomy.productionQueue = [];
  const plan = beginEnemyTurnPlan(updateFog(state));
  const productionBeforeEfficiency = chooseNextEnemyProductionPlanItem(state, plan, []);
  const research = chooseNextEnemyResearchPlanItem(state, plan, []);
  const simulated = planEnemyEconomy(state, plan, { includeFieldUpgrades: false });
  const firstPurchase = plan.economyPlan.purchases[0];

  assertAiTest(!productionBeforeEfficiency, "day seven Efficiency gate should block production before Efficiency L3 research starts");
  assertAiTest(research?.researchType === "Efficiency", `day seven Efficiency gate should force Efficiency research, got ${research?.researchType ?? "none"}`);
  assertAiTest(firstPurchase?.kind === "research" && firstPurchase.researchType === "Efficiency", `day seven economy plan should start with Efficiency, got ${firstPurchase?.kind ?? "none"}`);
  assertAiTest(
    simulated.enemyEconomy.researchQueue.some((job) => job.type === "Efficiency" && (job.targetLevel ?? 0) >= 3),
    "day seven economy plan should put Efficiency L3 into the research queue"
  );
}

