function testAiResearchCapacityRaisesAdvancedResearchValue(): void {
  const lowCapacity = createAiFixture(18);
  const highCapacity = createAiFixture(18);
  for (const state of [lowCapacity, highCapacity]) {
    state.enemyEconomy.moneyPoundsBn = 260;
    state.enemyEconomy.efficiencyLevel = 2;
    state.enemyEconomy.productionCapacityLevel = 2;
    state.enemyEconomy.researchCapacityLevel = 1;
    state.enemyEconomy.productionSpeedLevel = 2;
    state.enemyEconomy.researchSpeedLevel = 2;
    state.enemyEconomy.researchQueue = [];
    addBuilding(state, "Enemy", "Special Services");
  }
  highCapacity.enemyEconomy.researchCapacityLevel = 4;

  const lowPlan = beginEnemyTurnPlan(updateFog(lowCapacity));
  const highPlan = beginEnemyTurnPlan(updateFog(highCapacity));
  const getSpread = (state: GameState, plan: EnemyTurnPlan): number => {
    const candidates = getEnemyPlannerResearchCandidates(state, plan);
    const droneFactory = candidates.find((item) => item.researchType === "UnlockDroneFactory");
    const productionCapacity = candidates.find((item) => item.researchType === "ProductionCapacity");
    assertAiTest(Boolean(droneFactory && productionCapacity), "capacity fixture should expose advanced and basic research candidates");
    return droneFactory!.priority - productionCapacity!.priority;
  };

  const lowSpread = getSpread(lowCapacity, lowPlan);
  const highSpread = getSpread(highCapacity, highPlan);
  assertAiTest(
    highSpread > lowSpread,
    `higher research capacity should improve expensive special research relative to basic research, got low=${lowSpread.toFixed(1)} high=${highSpread.toFixed(1)}`
  );
}

