function testAiResearchCanChooseNotResearchingAfterProgress(): void {
  const state = createAiFixture(24);
  satisfyAiFixtureEfficiencyGate(state);
  state.enemyEconomy.moneyPoundsBn = 260;
  state.enemyEconomy.productionCapacityLevel = 1;
  state.enemyEconomy.researchCapacityLevel = 1;
  state.enemyEconomy.productionSpeedLevel = 1;
  state.enemyEconomy.researchSpeedLevel = 4;
  state.enemyEconomy.researchQueue = [];
  addBuilding(state, "Enemy", "Special Services");
  addBuilding(state, "Enemy", "Drone Factory");
  for (const unitType of ENEMY_UNIT_TYPES) {
    state.enemyEconomy.unitLevels[unitType] = getMaxUnitLevel(unitType);
  }

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const candidates = getEnemyPlannerResearchCandidates(visibleState, plan)
    .map((item) => applyEnemyEconomyResearchLevelSpreadPenalty(visibleState, item))
    .sort((first, second) => second.priority - first.priority || second.score - first.score || first.cost - second.cost);
  const waitPriority = scoreEnemyNoResearchPriority(visibleState, candidates);
  const research = chooseNextEnemyResearchPlanItem(visibleState, plan, []);

  assertAiTest(candidates.length > 0, "heavy-progress fixture should still expose research candidates to compare against waiting");
  assertAiTest(
    waitPriority >= candidates[0].priority,
    `not researching should beat cheap leftover research after heavy progress, got wait=${waitPriority.toFixed(1)} best=${candidates[0].priority.toFixed(1)} ${candidates[0].researchType ?? "none"}`
  );
  assertAiTest(!research, `AI should choose not researching after heavy progress, got ${research?.researchType ?? "none"}`);
}

function testAiAntiAirStepsIntoSightOfAirThreat(): void {
  const state = createAiFixture(8);
  const antiAir = addAiFixtureUnit(state, "Enemy", "Anti-Air", { q: 12, r: 11 });
  const helicopter = addAiFixtureUnit(state, "Player", "Attack Heli", { q: 12, r: 17 });
  rememberAiFixtureUnit(state, helicopter);
  const visibleState = updateFog(state);
  const visibleAntiAir = visibleState.units.find((unit) => unit.id === antiAir.id);
  const visibleHelicopter = visibleState.units.find((unit) => unit.id === helicopter.id);
  assertAiTest(Boolean(visibleAntiAir && visibleHelicopter), "anti-air sight fixture units must remain present");
  const plan = beginEnemyTurnPlan(visibleState);
  const intel = plan.playerIntel.find((entry) => entry.unit.id === helicopter.id);

  assertAiTest(Boolean(intel && intel.age === 0 && !intel.observedCoord), "helicopter should be remembered but not freshly visible at six hexes");
  assertAiTest(!canAiTestUnitSeeCoord(visibleState, visibleAntiAir!, visibleHelicopter!.coord), "fixture anti-air should start one hex outside effective sight");
  assertAiTest(getEnemyPlannerAttackTargets(visibleState, visibleAntiAir!, plan).length === 0, "unseen air target must not be directly attackable");
  const move = chooseEnemyPlannerFireSupportMove(visibleState, visibleAntiAir!, plan);

  assertAiTest(Boolean(move), "anti-air should step toward the remembered air threat");
  assertAiTest(
    hexDistance(move!, visibleHelicopter!.coord) < hexDistance(visibleAntiAir!.coord, visibleHelicopter!.coord),
    `anti-air should close from six hexes toward the helicopter, got ${hexId(move!)}`
  );
  assertAiTest(
    hexDistance(move!, visibleHelicopter!.coord) <= getEffectiveUnitStats(visibleState, visibleAntiAir!.owner, visibleAntiAir!.type, visibleAntiAir!.level, move!, visibleHelicopter!.coord).visibilityRange,
    `anti-air move should regain sight on the helicopter, got ${hexId(move!)}`
  );
}

function testAiArmorKeepsCenterGroundAfterAttack(): void {
  const state = createAiFixture(9);
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: 24, r: 13 });
  const infantry = addAiFixtureUnit(state, "Player", "Infantry", { q: 25, r: 19 });
  rememberAiFixtureUnit(state, infantry);
  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  const visibleInfantry = visibleState.units.find((unit) => unit.id === infantry.id);
  assertAiTest(Boolean(visibleTank && visibleInfantry), "center armor fixture units must remain present");
  const plan = beginEnemyTurnPlan(visibleState);
  const threatMap = getEnemyAntiAirThreatMap(visibleState, plan);
  const actions = enumerateEnemyImmediateTacticalAttackActions(visibleState, visibleTank!, plan, {}, {}, threatMap);
  const center = getEnemyArmorGroundCommitmentObjective(visibleState, visibleTank!, plan);

  assertAiTest(Boolean(center), "center armor fixture should produce a commitment objective");
  assertAiTest(actions.some((action) => action.targetId === visibleInfantry!.id), "center armor should find a tactical attack");
  const best = actions[0];
  const attackCoord = best.kind === "MoveAttackRetreat" && best.moveTo ? best.moveTo : visibleTank!.coord;
  const finalCoord = getEnemyCompoundActionFinalCoord(visibleTank!, best);
  assertAiTest(
    hexDistance(finalCoord, center!) <= hexDistance(attackCoord, center!),
    `center armor should not retreat away from its commitment objective after attacking, got ${best.kind}`
  );
}

function testAiSupplyTruckDoesNotFallbackToBackRowFromForwardFight(): void {
  const state = createAiFixture(9);
  const supply = addAiFixtureUnit(state, "Enemy", "Supply Truck", { q: 12, r: 7 });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: 24, r: 13 });
  addAiFixtureUnit(state, "Enemy", "Artillery", { q: 13, r: 11 });
  addKnownAiFixtureUnit(state, "Player", "Infantry", { q: 25, r: 19 });
  const visibleState = updateFog(state);
  const visibleSupply = visibleState.units.find((unit) => unit.id === supply.id);
  assertAiTest(Boolean(visibleSupply), "supply fallback fixture must retain the Supply Truck");
  const plan = beginEnemyTurnPlan(visibleState);
  const action = chooseEnemyRoutineObjectiveAction(visibleState, visibleSupply!, plan, {}, {});
  const finalCoord = action ? getEnemyCompoundActionFinalCoord(visibleSupply!, action) : visibleSupply!.coord;

  assertAiTest(finalCoord.r >= visibleSupply!.coord.r, `Supply Truck should not fallback toward the home back row, got ${hexId(finalCoord)}`);
}

