function testAiCombatEvaluatorExecutesAttackThenMove(): void {
  const state = createAiFixture(12);
  state.units = [];
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: 14, r: 16 });
  const startCoord = { ...tank.coord };
  const target = addKnownAiFixtureUnit(state, "Player", "Infantry", { q: 15, r: 16 }, 1);
  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(visibleTank), "attack-then-move fixture must retain the Tank");
  const plan = beginEnemyTurnPlan(visibleState);
  const threatMap = getEnemyAntiAirThreatMap(visibleState, plan);
  const immediateActions = enumerateEnemyImmediateTacticalAttackActions(visibleState, visibleTank!, plan, {}, {}, threatMap);
  const attackThenMove = immediateActions.find((action) => action.kind === "AttackThenMove" && action.targetId === target.id);
  assertAiTest(Boolean(attackThenMove), "fixture should generate an attack-then-move candidate");
  const blockedActions = new Set(immediateActions.filter((action) => action.kind !== "AttackThenMove").map((action) => action.id));
  const best = chooseBestEnemyCombatEvaluatorAction(visibleState, plan, {}, {}, blockedActions);

  assertAiTest(best?.unit.id === tank.id, `combat evaluator should select the Tank, got ${best?.unit.type ?? "none"}`);
  assertAiTest(best.action.kind === "AttackThenMove", `combat evaluator should keep attack-then-move candidates, got ${best.action.kind}`);
  assertAiTest(best.action.targetId === target.id, "combat evaluator should target the available Infantry before moving");

  executeEnemyCompoundAction(visibleState, best.action, plan);
  const movedTank = visibleState.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(movedTank), "Tank should survive attack-then-move execution");
  assertAiTest(!visibleState.units.some((unit) => unit.id === target.id), "attack-then-move should execute the attack before moving");
  assertAiTest(!sameHex(movedTank!.coord, startCoord), `Tank should reposition after attacking, got ${hexId(movedTank!.coord)}`);
}

