function testAiBaseHoldDayTwoProtectsCapturer(): void {
  const state = createAiFixture(20);
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
  });
  state.baseOccupation.Player = 2;
  const capturer = addAiFixtureUnit(state, "Enemy", "Ghost", state.bases.Player, 12);
  const backup = addAiFixtureUnit(state, "Enemy", "Infantry", { q: state.bases.Player.q - 4, r: state.bases.Player.r - 1 });
  const escort = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Player.q + 5, r: state.bases.Player.r - 1 });
  const threat = addAiFixtureUnit(state, "Player", "Infantry", { q: state.bases.Player.q + 2, r: state.bases.Player.r + 1 }, 12);
  rememberAiFixtureUnit(state, threat);

  const visibleState = updateFog(state);
  const visibleBackup = visibleState.units.find((unit) => unit.id === backup.id);
  const visibleEscort = visibleState.units.find((unit) => unit.id === escort.id);
  assertAiTest(Boolean(visibleBackup && visibleEscort), "base hold protector fixture units should remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  const backupAction = enumerateEnemyCompoundActions(visibleState, visibleBackup!, plan, {}, {})[0];
  const escortAction = enumerateEnemyCompoundActions(visibleState, visibleEscort!, plan, {}, {})[0];
  assertAiTest(Boolean(backupAction && escortAction), "base hold protectors should have tactical actions");
  const backupFinal = backupAction.moveTo ?? visibleBackup!.coord;
  const escortFinal = escortAction.moveTo ?? visibleEscort!.coord;

  assertAiTest(plan.campaignPlan.phase === "BaseHold", `base occupation should enter BaseHold, got ${plan.campaignPlan.phase}`);
  assertAiTest(plan.campaignPlan.baseAssaultPackage.backupCapturerId === backup.id, "base hold should preserve a backup capturer in the assault package");
  assertAiTest(hexDistance(backupFinal, visibleState.bases.Player) <= getEffectiveUnitStats(visibleState, visibleBackup!.owner, visibleBackup!.type, visibleBackup!.level, backupFinal, visibleState.bases.Player).moveRange, "backup capturer should move within replacement distance");
  assertAiTest(hexDistance(escortFinal, visibleState.bases.Player) < hexDistance(visibleEscort!.coord, visibleState.bases.Player), "escort should move toward the base-hold approach corridor");
  assertAiTest(!sameHex(backupFinal, state.bases.Player) && !sameHex(escortFinal, state.bases.Player), "protectors should not displace the holding capturer");
}

