function testAiGateBackupCapturerValuesReplacementDistance(): void {
  const state = createAiFixture(12);
  const gate = state.gates?.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "fixture must include west gate");
  gate!.occupation.Enemy = 2;
  const principal = addAiFixtureUnit(state, "Enemy", "Infantry", gate!.coord, 10);
  const backup = addAiFixtureUnit(state, "Enemy", "Ghost", { q: gate!.coord.q + 4, r: Math.max(0, gate!.coord.r - 4) }, 10);
  const plan = beginEnemyTurnPlan(updateFog(state));
  plan.rolesByUnitId[principal.id] = "CaptureGate";
  plan.rolesByUnitId[backup.id] = "ShadowCapturer";
  plan.campaignPlan.assignedGateByUnitId[principal.id] = "West";
  plan.campaignPlan.assignedGateByUnitId[backup.id] = "West";
  plan.campaignPlan.laneTaskForces.West.principalCapturerId = principal.id;
  plan.campaignPlan.laneTaskForces.West.backupCapturerId = backup.id;
  const hold = createEnemyCompoundAction(state, backup, plan, "Hold", {}, {}, {});
  const replacementMove = getEnemyLegalMoveCoords(state, backup)
    .filter((coord) => canMoveUnitTo(state, backup, coord))
    .filter((coord) => !sameHex(coord, gate!.coord))
    .filter((coord) => hexDistance(coord, gate!.coord) < hexDistance(backup.coord, gate!.coord))
    .sort((first, second) => hexDistance(first, gate!.coord) - hexDistance(second, gate!.coord) || hexId(first).localeCompare(hexId(second)))[0];
  assertAiTest(Boolean(replacementMove), "fixture must provide a backup progress move");
  const move = createEnemyCompoundAction(state, backup, plan, "Move", { moveTo: replacementMove! }, {}, {});

  assertAiTest(move.breakdown.backupCapturerValue > 0, "Gate backup should receive explicit backupCapturerValue");
  assertAiTest(move.breakdown.replacementDistance > hold.breakdown.replacementDistance, "Gate backup progress should improve replacementDistance score");
  assertAiTest(move.breakdown.total > hold.breakdown.total, "Gate backup should prefer moving into replacement range over holding far away");
}

