function testAiGateLockoutClearJustifiesMediocreTrade(): void {
  const state = createAiFixture(18);
  const westGate = state.gates?.find((candidate) => candidate.id === "West");
  const eastGate = state.gates?.find((candidate) => candidate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  westGate!.owner = "Player";
  westGate!.knownOwner = "Player";
  eastGate!.owner = "Enemy";
  eastGate!.knownOwner = "Enemy";
  const blocker = addAiFixtureUnit(state, "Player", "IFV", westGate!.coord, 20);
  const lines = getFrontLineRows(state);
  const forwardTank = addAiFixtureUnit(state, "Player", "Tank", { q: state.bases.Enemy.q, r: Math.max(0, lines.enemyLineRow - 1) });
  const attacker = addAiFixtureUnit(state, "Enemy", "Tank", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 2) });
  rememberAiFixtureUnit(state, blocker);
  rememberAiFixtureUnit(state, forwardTank);

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const mediocreOutcome: ExpectedAttackOutcome = {
    missProbability: 0.28,
    normalDamageProbability: 0.52,
    normalDamage: 4,
    criticalDamageProbability: 0.2,
    criticalDamage: 8,
    expectedDamage: 3.7,
    killProbability: 0.16
  };
  const hold = createEnemyCompoundAction(visibleState, attacker, plan, "Hold", {}, {}, {});
  const clear = createEnemyCompoundAction(
    visibleState,
    attacker,
    plan,
    "Attack",
    {
      attackAt: blocker.coord,
      targetId: blocker.id,
      targetType: blocker.type,
      expectedOutcome: mediocreOutcome
    },
    {},
    {}
  );

  assertAiTest(clear.breakdown.gateCaptureClock > hold.breakdown.gateCaptureClock + 120, "second-Gate blocker clear should receive explicit lockout clock value");
  assertAiTest(clear.breakdown.total > hold.breakdown.total, "lockout payoff should justify a mediocre local blocker trade");
}

