function testAiClearThenCapture(): void {
  const state = createAiFixture(18);
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
  });
  const blocker = addAiFixtureUnit(state, "Player", "Infantry", state.bases.Player, 1);
  const escort = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Player.q + 1, r: state.bases.Player.r - 4 });
  const clearer = addAiFixtureUnit(state, "Enemy", "Artillery", { q: state.bases.Player.q, r: state.bases.Player.r - 4 });
  const capturer = addAiFixtureUnit(state, "Enemy", "Ghost", { q: state.bases.Player.q, r: state.bases.Player.r - 3 });
  const backup = addAiFixtureUnit(state, "Enemy", "Infantry", { q: state.bases.Player.q - 1, r: state.bases.Player.r - 4 });
  const scout = addAiFixtureUnit(state, "Enemy", "IFV", { q: state.bases.Player.q + 2, r: state.bases.Player.r - 5 });
  state.baseOccupation.Player = 1;
  const plan = beginEnemyTurnPlan(updateFog(state));
  const assaultPackage = plan.campaignPlan.baseAssaultPackage;
  const baseAssaultForce = plan.taskForces.find((force) => force.id === "BaseAssault");
  assertAiTest(assaultPackage.capturerId === capturer.id, "base assault package should choose the Ghost as principal capturer");
  assertAiTest(assaultPackage.backupCapturerId === backup.id, "base assault package should include a backup capturer");
  assertAiTest(assaultPackage.scoutId === scout.id, "base assault package should include a scout");
  assertAiTest(assaultPackage.blockerEscortIds.includes(escort.id), "base assault package should include blocker/escort armor");
  assertAiTest(assaultPackage.damageDealerIds.includes(clearer.id), "base assault package should include a base-tile clearer");
  assertAiTest(assaultPackage.clearBaseTileTargetId === blocker.id, "base assault package should track the base tile blocker");
  assertAiTest(baseAssaultForce?.principalCapturerId === capturer.id && baseAssaultForce.backupCapturerId === backup.id, "base assault task force should expose package capturers");
  assertAiTest(baseAssaultForce?.members.includes(scout.id) && baseAssaultForce.members.includes(clearer.id), "base assault task force should contain scout and clearer");
  assertAiTest(plan.rolesByUnitId[capturer.id] === "CaptureBase" && plan.rolesByUnitId[backup.id] === "CaptureBase", "base assault capturers should receive CaptureBase");
  assertAiTest(plan.rolesByUnitId[scout.id] === "Scout", "base assault scout should keep scout role");
  assertAiTest(plan.rolesByUnitId[clearer.id] === "Siege", "base assault damage dealer should receive clear-base role");
  assertAiTest(plan.objectiveImperatives.some((imperative) => imperative.targetId === blocker.id), "clear-then-capture should include blocker clear");
  assertAiTest(plan.objectiveImperatives.some((imperative) => imperative.dependencies.length > 0), "clear-then-capture should include dependency");
}

