function testAiFireSupportClearsFoggedBaseBlocker(): void {
  const state = createAiFixture(20);
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
  });
  const blocker = addAiFixtureUnit(state, "Player", "Infantry", state.bases.Player, 1);
  const clearer = addAiFixtureUnit(state, "Enemy", "Artillery", { q: state.bases.Player.q, r: state.bases.Player.r - 4 });
  const capturer = addAiFixtureUnit(state, "Enemy", "Ghost", { q: state.bases.Player.q + 8, r: state.bases.Player.r - 8 });
  rememberAiFixtureUnit(state, blocker, state.day - 3);
  state.baseOccupation.Player = 1;

  const visibleState = updateFog(state);
  const visibleClearer = visibleState.units.find((unit) => unit.id === clearer.id);
  const visibleBlocker = visibleState.units.find((unit) => unit.id === blocker.id);
  const visibleCapturer = visibleState.units.find((unit) => unit.id === capturer.id);
  assertAiTest(Boolean(visibleClearer && visibleBlocker), "fixture must retain clearer and blocker");
  assertAiTest(Boolean(visibleCapturer && !canAiTestUnitSeeCoord(visibleState, visibleClearer!, visibleBlocker!.coord) && !canAiTestUnitSeeCoord(visibleState, visibleCapturer!, visibleBlocker!.coord)), "fixture must keep the base blocker outside effective scout visibility");
  const plan = beginEnemyTurnPlan(visibleState);
  assertAiTest(!getEnemyPlannerVisibleTargetIds(plan).has(blocker.id), "base blocker fixture should be unconfirmed by scout visibility");
  assertAiTest(isEnemyFireSupportAttackIntelAuthorized(visibleState, visibleClearer!, visibleBlocker!, plan), "high-payoff base blocker should remain authorized under fog");
  assertAiTest(plan.objectiveImperatives.some((imperative) => imperative.targetId === blocker.id && imperative.unitId === clearer.id), "fogged base blocker should still receive a clear imperative");
}

