function testAiBaseSentryWaitsForRealThreat(): void {
  const opening = createAiFixture(3);
  addAiFixtureUnit(opening, "Enemy", "Tank", { q: opening.bases.Enemy.q, r: opening.bases.Enemy.r + 1 });
  addAiFixtureUnit(opening, "Enemy", "IFV", { q: opening.bases.Enemy.q + 1, r: opening.bases.Enemy.r + 1 });
  const openingPlan = beginEnemyTurnPlan(updateFog(opening));
  assertAiTest(!Object.values(openingPlan.rolesByUnitId).includes("BaseSentry"), "opening should not reserve sentries before a base route exists");

  const blockedRoute = createAiFixture(7);
  const westGate = blockedRoute.gates.find((gate) => gate.id === "West");
  assertAiTest(Boolean(westGate), "fixture must include west gate");
  westGate!.owner = "Player";
  westGate!.knownOwner = "Player";
  addAiFixtureUnit(blockedRoute, "Enemy", "Tank", { q: 23, r: 25 });
  addAiFixtureUnit(blockedRoute, "Enemy", "IFV", { q: blockedRoute.bases.Enemy.q + 1, r: blockedRoute.bases.Enemy.r + 1 });
  const impossibleCapturer = addAiFixtureUnit(blockedRoute, "Player", "Infantry", { q: blockedRoute.bases.Enemy.q, r: blockedRoute.bases.Enemy.r + 4 });
  rememberAiFixtureUnit(blockedRoute, impossibleCapturer);
  const blockedPlan = beginEnemyTurnPlan(updateFog(blockedRoute));
  assertAiTest(!ownerControlsBothGates(blockedRoute, "Player"), "fixture should leave the enemy base route barred");
  assertAiTest(!Object.values(blockedPlan.rolesByUnitId).includes("BaseSentry"), "BaseSentry must not be assigned unless the player controls both Gates");

  const threatened = createAiFixture(14);
  threatened.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
  });
  const tank = addAiFixtureUnit(threatened, "Enemy", "Tank", { q: threatened.bases.Enemy.q, r: threatened.bases.Enemy.r + 1 });
  const ifv = addAiFixtureUnit(threatened, "Enemy", "IFV", { q: threatened.bases.Enemy.q + 1, r: threatened.bases.Enemy.r + 1 });
  const antiAir = addAiFixtureUnit(threatened, "Enemy", "Anti-Air", { q: threatened.bases.Enemy.q - 1, r: threatened.bases.Enemy.r + 1 });
  const threatenedPlan = beginEnemyTurnPlan(updateFog(threatened));
  const sentryIds = [tank, ifv, antiAir].filter((unit) => threatenedPlan.rolesByUnitId[unit.id] === "BaseSentry").map((unit) => unit.id);

  assertAiTest(ownerControlsBothGates(threatened, "Player"), "fixture should give the player both Gates");
  assertAiTest(sentryIds.length === 0, `player owning both Gates without a real route threat should not consume base sentries, got ${sentryIds.length}`);
  assertAiTest(getEnemyDefenseResponderLimit(updateFog(threatened), getEnemyStrategicAssessment(updateFog(threatened))) === 0, "defense responder limit should stay zero without a real base threat");
}

function testAiBaseSentryCountersBaseThreat(): void {
  const state = createAiFixture(18);
  state.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
  });
  const capturer = addAiFixtureUnit(state, "Player", "Infantry", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 4 });
  const airSupport = addAiFixtureUnit(state, "Player", "Bomber", { q: state.bases.Enemy.q + 2, r: state.bases.Enemy.r + 4 });
  rememberAiFixtureUnit(state, capturer);
  rememberAiFixtureUnit(state, airSupport);
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 1 });
  const antiAir = addAiFixtureUnit(state, "Enemy", "Anti-Air", { q: state.bases.Enemy.q - 1, r: state.bases.Enemy.r + 1 });
  const ifv = addAiFixtureUnit(state, "Enemy", "IFV", { q: state.bases.Enemy.q + 1, r: state.bases.Enemy.r + 1 });

  const plan = beginEnemyTurnPlan(updateFog(state));
  const baseDefenseRoles = [tank, antiAir, ifv].filter((unit) => plan.rolesByUnitId[unit.id] === "BaseSentry" || plan.rolesByUnitId[unit.id] === "DefendBase");

  assertAiTest(plan.rolesByUnitId[tank.id] === "DefendBase" || plan.rolesByUnitId[tank.id] === "BaseSentry", `Tank should counter the likely base capturer, got ${plan.rolesByUnitId[tank.id] ?? "none"}`);
  assertAiTest(plan.rolesByUnitId[antiAir.id] === "BaseSentry", `Anti-Air should be kept as sentry against nearby air support, got ${plan.rolesByUnitId[antiAir.id] ?? "none"}`);
  assertAiTest(baseDefenseRoles.length >= 2, `near-base capturer and support should create a BaseSentry/DefendBase group, got ${baseDefenseRoles.length}`);
}

