  assertAiTest(Boolean(westGate && eastGate), "fixture must include gates");
  westGate!.owner = "Player";
  westGate!.knownOwner = "Player";
  eastGate!.occupation.Player = GATE_CAPTURE_DAYS - 1;
  const playerCapturer = addAiFixtureUnit(state, "Player", "Infantry", eastGate!.coord, 10);
  const playerBackup = addAiFixtureUnit(state, "Player", "Operator", { q: westGate!.coord.q, r: westGate!.coord.r + 1 }, 10);
  rememberAiFixtureUnit(state, playerCapturer);
  rememberAiFixtureUnit(state, playerBackup);
  const visibleState = updateFog(state);
  const assessment = getEnemyStrategicAssessment(visibleState);
  const tankScore = scoreEnemyProductionChoice(visibleState, "Tank");
  const artilleryScore = scoreEnemyProductionChoice(visibleState, "Artillery");
  const helicopterScore = scoreEnemyProductionChoice(visibleState, "Attack Heli");

  assertAiTest(assessment.opponentProfile.kind === "GateRusher" || assessment.opponentProfile.gateRush >= 0.62, `fixture should profile GateRusher, got ${assessment.opponentProfile.kind}`);
  assertAiTest(Math.max(tankScore, artilleryScore) > helicopterScore, "GateRusher counter-plan should prefer gate denial/removers over generic Helicopter pressure");
