  const producedTypes = [firstProduction?.unitType, secondProduction?.unitType].filter((unitType): unitType is UnitType => Boolean(unitType));

  assertAiTest(firstPlan.doctrine.strategyPlaybook.plan === "AirSuperiority", `fixture should choose AirSuperiority, got ${firstPlan.doctrine.strategyPlaybook.plan}`);
