function testAiPlaybookReaperTechRushFirstTwoTurns(): void {
  const state = createAiFixture(14);
  satisfyAiFixtureEfficiencyGate(state);
  state.enemyEconomy.moneyPoundsBn = 260;
  addBuilding(state, "Enemy", "Special Services");
  const playerTank = addAiFixtureUnit(state, "Player", "Tank", { q: 14, r: 10 });
  const playerArtillery = addAiFixtureUnit(state, "Player", "Artillery", { q: 16, r: 11 });
  rememberAiFixtureUnit(state, playerTank);
  rememberAiFixtureUnit(state, playerArtillery);
  const gate = state.gates.find((candidate) => candidate.id === "East");
  assertAiTest(Boolean(gate), "fixture must include East Gate");
  gate!.owner = "Enemy";
  gate!.knownOwner = "Enemy";
  gate!.occupation.Player = 1;
  addAiFixtureUnit(state, "Enemy", "Tank", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 4) });

  const firstPlan = planAiAcceptanceTurn(state);
  applyAiAcceptanceEconomyTurn(state, firstPlan);
  const secondPlan = planAiAcceptanceTurn(state);
  const firstResearch = firstPlan.economyPlan.purchases.find((item) => item.kind === "research");
  const producedTypes = [...firstPlan.economyPlan.purchases, ...secondPlan.economyPlan.purchases]
    .filter((item) => item.kind === "production" && item.unitType)
    .map((item) => item.unitType!);

  assertAiTest(firstPlan.doctrine.strategyPlaybook.plan === "ReaperTechRush", `fixture should choose ReaperTechRush, got ${firstPlan.doctrine.strategyPlaybook.plan}`);
  assertStrategyPlaybookIncludes(firstPlan, "UnlockDroneFactory", "ReaperTechRush");
  assertStrategyPlaybookIncludes(firstPlan, "DelayObjectiveClock", "ReaperTechRush");
  assertStrategyPlaybookIncludes(firstPlan, "AvoidNonDelayingSpend", "ReaperTechRush");
  assertAiTest(firstResearch?.researchType === "UnlockDroneFactory", `ReaperTechRush first turn should start Drone Factory, got ${firstResearch?.researchType ?? "none"}`);
  assertAiTest(
    producedTypes.every((unitType) => unitType === "Reaper" || isEnemyReaperTechRushDelayProductionUnit(state, unitType, firstPlan.strategicSnapshot)),
    `ReaperTechRush should avoid non-delaying production before Reaper, got ${producedTypes.join(",") || "none"}`
  );
}

function testAiCombatCounterValueOrder(): void {
  const makeTarget = (type: UnitType): UnitInstance => ({
    id: `ai-test-target-${type}`,
    owner: "Player",
    type,
    level: 1,
    coord: { q: 0, r: 0 },
    health: 1,
    maxHealth: 1,
    placedDay: 1,
    hasMovedThisDay: false,
    movementSpentThisDay: 0,
    hasAttackedThisDay: false
  });
  const assertOrder = (order: UnitType[], target: UnitInstance, label: string): void => {
    for (let index = 0; index < order.length - 1; index += 1) {
      const current = order[index];
      const next = order[index + 1];
      assertAiTest(canUnitTargetUnit(current, target.type), `${current} must be able to target ${label}`);
      assertAiTest(canUnitTargetUnit(next, target.type), `${next} must be able to target ${label}`);
      const currentScore = getCounterPriorityBonus(current, target);
      const nextScore = getCounterPriorityBonus(next, target);
      assertAiTest(currentScore > nextScore, `${label} combat value should rank ${current} above ${next}; got ${currentScore} <= ${nextScore}`);
    }
  };

  assertOrder(ENEMY_GROUND_COMBAT_VALUE_ORDER, makeTarget("Tank"), "ground");
  assertOrder(ENEMY_AIR_COMBAT_VALUE_ORDER, makeTarget("Attack Heli"), "air");
  assertAiTest(canCounterAir("Attack Heli"), "Helicopter should be classified as an air counter");
  assertAiTest(canCounterHighAltitudeAir("Attack Heli"), "Helicopter should be classified as a high-altitude air counter");
}

