function testAiGateLockoutDamagedCombatPowerRepairs(): void {
  const state = createAiFixture(14);
  state.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
    gate.occupation.Player = GATE_CAPTURE_DAYS;
    gate.occupation.Enemy = 0;
  });
  const gate = state.gates.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "fixture must include west gate");
  addKnownAiFixtureUnit(state, "Player", "Infantry", gate!.coord);
  const damagedTank = addAiFixtureUnit(state, "Enemy", "Tank", { q: gate!.coord.q, r: Math.max(1, gate!.coord.r - 2) }, 8);
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 2 });
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: gate!.coord.q, r: gate!.coord.r + 1 });
  addKnownAiFixtureUnit(state, "Player", "Artillery", { q: gate!.coord.q + 1, r: gate!.coord.r + 2 });

  const plan = beginEnemyTurnPlan(updateFog(state));
  const action = enumerateEnemyCompoundActions(state, damagedTank, plan, {}, {})[0];
  const finalCoord = action.moveTo ?? damagedTank.coord;

  assertAiTest(plan.campaignPlan.phase === "GateLockoutCombat", `fixture should enter GateLockoutCombat, got ${plan.campaignPlan.phase}`);
  assertAiTest(shouldEnemyRetreatForRepair(state, damagedTank), "damaged high-value lockout Tank likely to die should repair");
  assertAiTest(plan.rolesByUnitId[damagedTank.id] === "Repair" || plan.rolesByUnitId[damagedTank.id] === "DefendGate", `damaged lockout Tank should receive Repair or immediate gate defense, got ${plan.rolesByUnitId[damagedTank.id] ?? "none"}`);
  assertAiTest(plan.rolesByUnitId[damagedTank.id] === "DefendGate" || finalCoord.r < damagedTank.coord.r, `damaged lockout Tank should retreat toward repair unless committed to gate defense, got ${hexId(finalCoord)}`);

  const killState = createAiFixture(14);
  killState.gates.forEach((candidate) => {
    candidate.owner = "Player";
    candidate.knownOwner = "Player";
    candidate.occupation.Player = GATE_CAPTURE_DAYS;
    candidate.occupation.Enemy = 0;
  });
  const killGate = killState.gates.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(killGate), "immediate-kill fixture must include west gate");
  const killerTank = addAiFixtureUnit(killState, "Enemy", "Tank", { q: killGate!.coord.q, r: Math.max(1, killGate!.coord.r - 2) }, 8);
  addKnownAiFixtureUnit(killState, "Player", "Infantry", killGate!.coord);
  const vulnerableInfantry = addKnownAiFixtureUnit(killState, "Player", "Infantry", { q: killGate!.coord.q, r: killGate!.coord.r + 1 }, 1);
  addKnownAiFixtureUnit(killState, "Player", "Artillery", { q: killGate!.coord.q + 1, r: killGate!.coord.r + 2 });
  const killPlan = beginEnemyTurnPlan(updateFog(killState));
  const killAction = enumerateEnemyCompoundActions(killState, killerTank, killPlan, {}, {})[0];

  assertAiTest(killPlan.campaignPlan.phase === "GateLockoutCombat", `immediate-kill fixture should enter GateLockoutCombat, got ${killPlan.campaignPlan.phase}`);
  assertAiTest(!shouldEnemyRetreatForRepair(killState, killerTank), "damaged lockout Tank with an immediate kill should not repair first");
  assertAiTest(killAction.targetId === vulnerableInfantry.id || killAction.kind !== "Hold", `damaged lockout Tank should take immediate kill or another active lockout action, got ${killAction.targetId ?? "none"}`);
}

