function testAiOpeningPatrolScoutsKeepMovingAfterGateStandoff(): void {
  const state = createAiFixture(5);
  const gate = state.gates?.find((candidate) => candidate.id === "East");
  assertAiTest(Boolean(gate), "fixture must include east gate");
  const standoff = getPassableCoordsNear(state, gate!.coord, 2)
    .filter((coord) => !sameHex(coord, gate!.coord))
    .filter((coord) => coord.r < gate!.coord.r)
    .sort((first, second) => hexDistance(first, gate!.coord) - hexDistance(second, gate!.coord) || hexId(first).localeCompare(hexId(second)))[0];
  assertAiTest(Boolean(standoff), "fixture must find a gate standoff tile");
  const scout = addAiFixtureUnit(state, "Enemy", "IFV", standoff!);
  const visibleState = updateFog(state);
  const visibleScout = visibleState.units.find((unit) => unit.id === scout.id);
  assertAiTest(Boolean(visibleScout), "fixture must retain scout");
  const visibleGate = visibleState.gates.find((candidate) => candidate.id === "East");
  assertAiTest(Boolean(visibleGate), "visible fixture must include east gate");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleScout!.id] = "PatrolEast";

  const forcedAction = chooseEnemyUnifiedForcedMovementAction(visibleState, visibleScout!, plan);
  assertAiTest(forcedAction?.kind !== "Hold", "patrol scout at gate standoff must not receive a forced hold");

  const bestAction = chooseBestEnemyUnifiedEvaluatorAction(visibleState, visibleScout!, plan);
  const finalCoord = bestAction ? getEnemyCompoundActionFinalCoord(visibleScout!, bestAction) : visibleScout!.coord;
  assertAiTest(Boolean(bestAction), "patrol scout at gate standoff should still have an evaluator action");
  assertAiTest(bestAction!.kind !== "Hold", `patrol scout at gate standoff should keep scouting, got ${bestAction!.kind}`);
  assertAiTest(!sameHex(finalCoord, visibleScout!.coord), `patrol scout should move away from stale standoff tile, got ${hexId(finalCoord)}`);
  assertAiTest(!sameHex(finalCoord, visibleGate!.coord), `patrol scout must not move onto the gate tile, got ${hexId(finalCoord)}`);
}

function testAiScoutingIfvsDoNotEnterDefendedGates(): void {
  const state = createAiFixture(8);
  const gate = state.gates?.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "fixture must include west gate");
  gate!.owner = "Player";
  gate!.knownOwner = "Player";

  const scout = addAiFixtureUnit(state, "Enemy", "IFV", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 4) });
  const defender = addAiFixtureUnit(state, "Player", "Infantry", { q: gate!.coord.q + 1, r: gate!.coord.r }, 1);
  rememberAiFixtureUnit(state, defender);

  const visibleState = updateFog(state);
  const visibleScout = visibleState.units.find((unit) => unit.id === scout.id);
  const visibleDefender = visibleState.units.find((unit) => unit.id === defender.id);
  assertAiTest(Boolean(visibleScout && visibleDefender), "defended gate scout fixture must retain both units");
  assertAiTest(canAiTestUnitSeeCoord(visibleState, visibleScout!, gate!.coord), "IFV should already be able to see the gate tile");
  assertAiTest(
    getPassableCoordsNear(visibleState, gate!.coord, 1).some((coord) => !sameHex(coord, gate!.coord) && canAiTestUnitSeeCoord(visibleState, visibleScout!, coord)),
    "IFV should already reveal at least one surrounding gate tile"
  );

  const movedScout: UnitInstance = {
    ...visibleScout!,
    coord: { ...gate!.coord },
    movementSpentThisDay: (visibleScout!.movementSpentThisDay ?? 0) + hexDistance(visibleScout!.coord, gate!.coord)
  };
  const outcome = getExpectedAttackOutcome(visibleState, movedScout, visibleDefender!);
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleScout!.id] = "Scout";
  const scoutGateAttack = createEnemyCompoundAction(
    visibleState,
    visibleScout!,
    plan,
    "MoveThenAttack",
    { moveTo: gate!.coord, attackAt: visibleDefender!.coord, targetId: visibleDefender!.id, targetType: visibleDefender!.type, expectedOutcome: outcome },
    {},
    {}
  );
  assertAiTest(outcome.killProbability >= 0.78, `fixture should provide a high-confidence attack, got ${outcome.killProbability.toFixed(2)}`);
  assertAiTest(canMoveUnitTo(visibleState, visibleScout!, gate!.coord), "fixture should make gate entry movement legal before scout policy");
  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, visibleScout!, scoutGateAttack, plan), "scouting IFV must not enter a gate even for a high-confidence attack");

  const action = enumerateEnemyCompoundActions(visibleState, visibleScout!, plan, {}, {})[0];
  const finalCoord = action.moveTo ?? visibleScout!.coord;
  assertAiTest(!sameHex(finalCoord, gate!.coord), `scouting IFV action must not end on the defended gate, got ${action.kind} to ${hexId(finalCoord)}`);
}

function testAiOpeningIfvsScoutAroundGateAndCenter(): void {
  const state = createAiFixture(6);
  const seededGateId = getEnemySeededOpeningMainEffortGateId(state);
  const gate = state.gates.find((candidate) => candidate.id === seededGateId);
  assertAiTest(Boolean(gate), "fixture must include seeded opening gate");

  const sideOffset = seededGateId === "West" ? -1 : 1;
  const ifvA = addAiFixtureUnit(state, "Enemy", "IFV", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 4) });
  const ifvB = addAiFixtureUnit(state, "Enemy", "IFV", { q: gate!.coord.q + sideOffset, r: Math.max(0, gate!.coord.r - 4) });
  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const visibleIfvs = [ifvA, ifvB]
    .map((unit) => visibleState.units.find((candidate) => candidate.id === unit.id))
    .filter((unit): unit is UnitInstance => Boolean(unit));
  assertAiTest(visibleIfvs.length === 2, "opening IFV fixture should retain both IFVs");

  const visibleGate = visibleState.gates.find((candidate) => candidate.id === seededGateId);
  assertAiTest(Boolean(visibleGate), "visible fixture must include seeded opening gate");
  for (const ifv of visibleIfvs) {
    plan.rolesByUnitId[ifv.id] = "Escort";
    plan.campaignPlan.assignedGateByUnitId[ifv.id] = visibleGate!.id;
  }

  const reservations: Record<string, string> = {};
  const finalCoords: UnitInstance["coord"][] = [];
  for (const ifv of visibleIfvs) {
    const gateMove = createEnemyCompoundAction(visibleState, ifv, plan, "Move", { moveTo: visibleGate!.coord }, reservations, {});
    assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, ifv, gateMove, plan), "opening IFV support must not be allowed to move onto the gate tile");
    const action = enumerateEnemyCompoundActions(visibleState, ifv, plan, reservations, {})[0];
    assertAiTest(Boolean(action), "opening IFV should choose a standoff scouting move");
    const finalCoord = action!.moveTo ?? ifv.coord;
    finalCoords.push(finalCoord);
    reserveEnemyActionDestination(action!, reservations);
    assertAiTest(!sameHex(finalCoord, visibleGate!.coord), `opening IFV should scout around the gate instead of occupying it, got ${hexId(finalCoord)}`);
    assertAiTest(hexDistance(finalCoord, visibleGate!.coord) <= 3, `opening IFV should remain in gate standoff range, got ${hexId(finalCoord)}`);
  }

  const center = getEnemyOpeningCenterStagingCoord(visibleState);
  assertAiTest(
    finalCoords.some((coord) => hexDistance(coord, center) < hexDistance(visibleGate!.coord, center)),
    `at least one opening IFV should scout toward the center, got ${finalCoords.map(hexId).join(", ")}`
  );
}

