function testAiNonCaptureMoveRejectsKillZone(): void {
  const state = createAiFixture(18);
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Enemy.q, r: Math.max(0, state.bases.Enemy.r - 4) });
  const setupState = updateFog(state);
  const setupTank = setupState.units.find((unit) => unit.id === tank.id && unit.owner === "Enemy");
  assertAiTest(Boolean(setupTank), "kill-zone fixture tank must be visible");
  const visible = getVisibleHexIdsForOwner(setupState, "Enemy");
  const unsafeCoord = getLegalMoveCoordsWithVisibility(setupState, setupTank!, visible)
    .filter((coord) => !sameHex(coord, setupTank!.coord))
    .find((coord) =>
      state.map.hexes.filter((hex) => hex.passable && !sameHex(hex.coord, coord) && !sameHex(hex.coord, setupTank!.coord) && hexDistance(hex.coord, coord) <= 2).length >= 3
    );
  assertAiTest(Boolean(unsafeCoord), "kill-zone fixture must find a legal move with nearby threat positions");
  const threatCoords = state.map.hexes
    .filter((hex) => hex.passable && !sameHex(hex.coord, unsafeCoord!) && !sameHex(hex.coord, tank.coord) && hexDistance(hex.coord, unsafeCoord!) <= 2)
    .slice(0, 3)
    .map((hex) => hex.coord);
  threatCoords.forEach((coord) => rememberAiFixtureUnit(state, addAiFixtureUnit(state, "Player", "Artillery", coord)));

  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id && unit.owner === "Enemy");
  assertAiTest(Boolean(visibleTank), "kill-zone fixture tank must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleTank!.id] = "Escort";
  const unsafeAction = createEnemyCompoundAction(visibleState, visibleTank!, plan, "Move", { moveTo: unsafeCoord! }, {}, {});
  const replyDamage = estimatePlayerLikelyReplyDamageAtPlanner(visibleState, visibleTank!, unsafeCoord!, plan);

  assertAiTest(replyDamage >= visibleTank!.health * 0.5, `fixture move should expose the tank to heavy reply damage, got ${replyDamage.toFixed(1)}`);
  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, visibleTank!, unsafeAction, plan), "non-capture move into heavy player reply damage must be rejected");
}

