function testAiGateDenialChainsClearThenOccupy(): void {
  const state = createAiFixture(20);
  const gate = state.gates?.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "fixture must include west gate");
  gate!.owner = "Enemy";
  gate!.knownOwner = "Enemy";
  gate!.occupation.Player = GATE_CAPTURE_DAYS - 1;
  const playerCapturer = addAiFixtureUnit(state, "Player", "Infantry", gate!.coord, 6);
  const clearer = addAiFixtureUnit(state, "Enemy", "Tank", { q: gate!.coord.q + 3, r: gate!.coord.r });
  const occupier = addAiFixtureUnit(state, "Enemy", "Infantry", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 3) });
  rememberAiFixtureUnit(state, playerCapturer);

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const denial = plan.objectiveImperatives.find((imperative) => imperative.id.startsWith(`deny-player-gate-${gate!.id}`));
  const followUp = plan.objectiveImperatives.find((imperative) => imperative.id.startsWith(`capture-after-gate-denial-${gate!.id}`));

  assertAiTest(Boolean(denial && denial.targetId === playerCapturer.id), "Gate denial should target the player capturer");
  assertAiTest(denial!.unitId === clearer.id, `Tank clearer should receive the denial action, got ${denial!.unitId ?? "none"}`);
  assertAiTest(Boolean(followUp), "Gate denial should create a follow-up occupation imperative");
  assertAiTest(followUp!.unitId === occupier.id, `reachable human should be assigned to occupy after denial, got ${followUp!.unitId ?? "none"}`);
  assertAiTest((followUp!.dependencies ?? []).includes(clearer.id), "follow-up Gate occupation should depend on the clearer");
  assertAiTest((plan.activationDependencies[occupier.id] ?? []).includes(clearer.id), "activation order should run the clearer before the occupier");
  assertAiTest(plan.rolesByUnitId[occupier.id] === "CaptureGate", `follow-up occupier should keep CaptureGate role, got ${plan.rolesByUnitId[occupier.id] ?? "none"}`);
}

function testAiDefendGateCoversTheatre(): void {
  const state = createAiFixture(18);
  const gate = state.gates?.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "fixture must include west gate");
  gate!.owner = "Enemy";
  gate!.knownOwner = "Enemy";
  gate!.occupation.Player = 0;
  gate!.occupation.Enemy = GATE_CAPTURE_DAYS;

  const defender = addAiFixtureUnit(state, "Enemy", "Artillery", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 2) });
  const playerArmor = addAiFixtureUnit(state, "Player", "Tank", { q: gate!.coord.q, r: gate!.coord.r + 3 });
  const playerReinforcement = addAiFixtureUnit(state, "Player", "Infantry", { q: gate!.coord.q + 2, r: gate!.coord.r + 2 });
  [playerArmor, playerReinforcement].forEach((unit) => rememberAiFixtureUnit(state, unit));

  const visibleState = updateFog(state);
  const visibleDefender = visibleState.units.find((unit) => unit.id === defender.id);
  const visibleArmor = visibleState.units.find((unit) => unit.id === playerArmor.id);
  assertAiTest(Boolean(visibleDefender && visibleArmor), "defend-gate theatre fixture units must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleDefender!.id] = "DefendGate";
  const visibleGate = visibleState.gates.find((candidate) => candidate.id === gate!.id)!;

  const hold = createEnemyCompoundAction(visibleState, visibleDefender!, plan, "Hold", {}, {}, {});
  const attack = createEnemyCompoundAction(
    visibleState,
    visibleDefender!,
    plan,
    "Attack",
    {
      attackAt: visibleArmor!.coord,
      targetId: visibleArmor!.id,
      targetType: visibleArmor!.type,
      expectedOutcome: getExpectedAttackOutcome(visibleState, visibleDefender!, visibleArmor!)
    },
    {},
    {}
  );
  const moveToGate = createEnemyCompoundAction(visibleState, visibleDefender!, plan, "Move", { moveTo: visibleGate.coord }, {}, {});

  assertAiTest(isEnemyGateTheatreDefenseTarget(visibleState, visibleArmor!, visibleGate, plan), "player armor near the gate should count as a gate-theatre defense target");
  assertAiTest(isEnemyActionAllowedByStrategicStructure(visibleState, visibleDefender!, hold, plan), "DefendGate should allow holding a useful theatre firing position");
  assertAiTest(isEnemyActionAllowedByStrategicStructure(visibleState, visibleDefender!, attack, plan), "DefendGate should allow attacking threats in the wider gate theatre");
  assertAiTest(attack.breakdown.doctrine > moveToGate.breakdown.doctrine, `theatre attack should outscore walking to the gate tile, attack=${attack.breakdown.doctrine.toFixed(1)} move=${moveToGate.breakdown.doctrine.toFixed(1)}`);
  assertAiTest(hold.breakdown.doctrine > moveToGate.breakdown.doctrine, `holding a firing lane should outscore walking to the gate tile, hold=${hold.breakdown.doctrine.toFixed(1)} move=${moveToGate.breakdown.doctrine.toFixed(1)}`);
}

