function testAiHighAltitudeExploitsAbsentAntiAir(): void {
  const state = createAiFixture(6);
  addBuilding(state, "Enemy", "Airfield");
  addBuilding(state, "Enemy", "Drone Factory");
  const westGate = state.gates.find((gate) => gate.id === "West");
  assertAiTest(Boolean(westGate), "fixture must include west gate");
  [
    addAiFixtureUnit(state, "Player", "Tank", { q: westGate!.coord.q, r: westGate!.coord.r + 2 }),
    addAiFixtureUnit(state, "Player", "Artillery", { q: westGate!.coord.q + 2, r: westGate!.coord.r + 1 }),
    addAiFixtureUnit(state, "Player", "IFV", { q: westGate!.coord.q - 2, r: westGate!.coord.r + 1 })
  ].forEach((unit) => rememberAiFixtureUnit(state, unit));

  const visibleState = updateFog(state);
  const assessment = getEnemyStrategicAssessment(visibleState);
  const risk = getEnemyAntiAirProductionRisk(visibleState, assessment);
  const layer = getEnemyHighAltitudeLayerAssessment(visibleState, assessment, risk);
  const bomberAdjustment = getEnemyHighAltitudeLayerProductionAdjustment(visibleState, "Bomber", assessment, layer);
  const reaperAdjustment = getEnemyHighAltitudeLayerProductionAdjustment(visibleState, "Reaper", assessment, layer);

  assertAiTest(!canUnitTargetUnit("Tank", "Bomber"), "ordinary ground units must not target high-altitude Bombers");
  assertAiTest(!canUnitTargetUnit("Operator", "Jet"), "non-Anti-Air ground units must not target high-altitude Jets");
  assertAiTest(canUnitTargetUnit("Anti-Air", "Reaper"), "Anti-Air must be able to target high-altitude Reapers");
  assertAiTest(layer.playerAntiAirThreatCount === 0, "fixture should have no known or probable player Anti-Air threat");
  assertAiTest(bomberAdjustment > 120, `absent Anti-Air should make Bomber exploitation attractive, got ${bomberAdjustment.toFixed(1)}`);
  assertAiTest(reaperAdjustment > 70, `absent Anti-Air should make Reaper exploitation attractive, got ${reaperAdjustment.toFixed(1)}`);
}

