function testAiPlacementCapturerUsesCampaignGateLane(): void {
  const state = createAiFixture(4);
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  westGate!.occupation.Player = 1;
  addAiFixtureUnit(state, "Player", "Infantry", { q: westGate!.coord.q, r: westGate!.coord.r + 1 });
  resetAiFixtureEnemyInventory(state);
  addInventoryUnitAtLevel(state.enemyEconomy, "Infantry", 1);

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const campaignGate = visibleState.gates.find((gate) => gate.id === plan.campaignPlan.mainEffortGateId);
  assertAiTest(Boolean(campaignGate), `campaign should choose a placement main effort, got ${plan.campaignPlan.mainEffortGateId ?? "none"}`);
  planEnemyPlacement(visibleState, plan);
  const placement = plan.placementPlan.find((item) => item.unitType === "Infantry");
  assertAiTest(Boolean(placement), "Infantry inventory should receive a placement plan");

  const campaignLaneDistance = Math.abs(placement!.coord.q - getOpeningGateTopLaneQ(visibleState, campaignGate!));
  const otherGate = campaignGate!.id === "West" ? eastGate! : westGate!;
  const otherLaneDistance = Math.abs(placement!.coord.q - getOpeningGateTopLaneQ(visibleState, otherGate));
  assertAiTest(campaignLaneDistance <= otherLaneDistance, `capture placement should prefer campaign ${campaignGate!.id} lane, got ${hexId(placement!.coord)} campaign=${campaignLaneDistance} other=${otherLaneDistance}`);
}

function testAiPlacementUsesShortestObjectiveRoute(): void {
  const state = createAiFixture(10);
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  westGate!.owner = "Player";
  westGate!.knownOwner = "Player";
  resetAiFixtureEnemyInventory(state);
  addInventoryUnitAtLevel(state.enemyEconomy, "Infantry", 1);

  for (const hex of state.map.hexes) {
    if (hex.coord.r >= 1 && hex.coord.r <= westGate!.coord.r && hex.coord.q >= 8 && hex.coord.q <= 13) {
      hex.passable = false;
    }
  }

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  plan.campaignPlan.phase = "Recovery";
  plan.campaignPlan.mainEffortGateId = "West";
  plan.campaignPlan.secondaryGateId = "East";
  plan.strategicSnapshot.gateUrgency = 420;
  plan.strategicSnapshot.baseAttackUrgency = 60;
  planEnemyPlacement(visibleState, plan);

  const placement = plan.placementPlan.find((item) => item.unitType === "Infantry");
  const laneCoord = { q: getOpeningGateTopLaneQ(visibleState, westGate!), r: visibleState.bases.Enemy.r };
  const placementRoute = placement ? estimateEnemyPlacementObjectiveRoute(visibleState, "Infantry", placement.coord, westGate!.coord) : undefined;
  const laneRoute = estimateEnemyPlacementObjectiveRoute(visibleState, "Infantry", laneCoord, westGate!.coord);

  assertAiTest(Boolean(placement && placementRoute), "Infantry inventory should receive a placement plan");
  assertAiTest(placementRoute!.routeDistance < laneRoute.routeDistance, `placement should choose the shorter objective route, got ${hexId(placement!.coord)} route=${placementRoute!.routeDistance} lane=${laneRoute.routeDistance}`);
}

