function testAiPlacementDefendsCapturedGateWithCaptureUnits(): void {
  const state = createAiFixture(14);
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  westGate!.owner = "Enemy";
  westGate!.knownOwner = "Enemy";
  westGate!.occupation.Enemy = GATE_CAPTURE_DAYS;
  addKnownAiFixtureUnit(state, "Player", "Infantry", { q: westGate!.coord.q, r: westGate!.coord.r + 2 });
  addKnownAiFixtureUnit(state, "Player", "Infantry", { q: westGate!.coord.q + 1, r: westGate!.coord.r + 2 });
  resetAiFixtureEnemyInventory(state);
  for (let count = 0; count < 4; count += 1) {
    addInventoryUnitAtLevel(state.enemyEconomy, "Infantry", 1);
  }

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  plan.campaignPlan.phase = "OneGateOwned";
  plan.campaignPlan.mainEffortGateId = "East";
  plan.campaignPlan.secondaryGateId = "West";
  planEnemyPlacement(visibleState, plan);

  const westLaneQ = getOpeningGateTopLaneQ(visibleState, westGate!);
  const eastLaneQ = getOpeningGateTopLaneQ(visibleState, eastGate!);
  const laneForCoord = (coord: UnitInstance["coord"]): GateState["id"] =>
    Math.abs(coord.q - westLaneQ) <= Math.abs(coord.q - eastLaneQ) ? "West" : "East";
  const capturedGateDefensePlacements = plan.placementPlan.filter((item) => getUnitDefinition(item.unitType).humanBased && laneForCoord(item.coord) === "West");

  assertAiTest(plan.placementPlan.length === 4, `fixture should place all four Infantry, got ${plan.placementPlan.length}`);
  assertAiTest(capturedGateDefensePlacements.length >= 1, "captured Gate should receive at least one capture-unit defender placement");
  assertAiTest(capturedGateDefensePlacements.length <= 3, `captured Gate defense should use at most three capture-unit placements, got ${capturedGateDefensePlacements.length}`);
  assertAiTest(
    plan.placementPlan.slice(0, 3).every((item) => getUnitDefinition(item.unitType).humanBased && laneForCoord(item.coord) === "West"),
    `first three placements should defend captured West Gate, got ${plan.placementPlan.map((item) => `${item.unitType}@${hexId(item.coord)}`).join(",")}`
  );
}

function testAiPlacementFireSupportFollowsBaseAssaultPhase(): void {
  const state = createAiFixture(20);
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
  });
  const blocker = addAiFixtureUnit(state, "Player", "Infantry", state.bases.Player);
  rememberAiFixtureUnit(state, blocker);
  addAiFixtureUnit(state, "Enemy", "Ghost", { q: state.bases.Player.q, r: Math.max(0, state.bases.Player.r - 5) });
  resetAiFixtureEnemyInventory(state);
  addInventoryUnitAtLevel(state.enemyEconomy, "Artillery", 1);

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  assertAiTest(isEnemyBaseOperationPlacementPhase(plan.campaignPlan.phase), `both Gates owned should enter base-operation placement phase, got ${plan.campaignPlan.phase}`);
  planEnemyPlacement(visibleState, plan);
  const placement = plan.placementPlan.find((item) => item.unitType === "Artillery");
  assertAiTest(Boolean(placement), "Artillery inventory should receive a placement plan");

  const bestLegal = getLegalPlacementCoords(visibleState, "Enemy", "Artillery")
    .map((coord) => ({
      coord,
      score: scoreEnemyPlacementCoord(visibleState, "Artillery", coord, plan)
    }))
    .sort((first, second) => second.score - first.score)[0];
  const routeAnchor = plan.campaignPlan.baseAssaultRoute[plan.campaignPlan.baseAssaultRoute.length - 1] ?? state.bases.Player;
  const routeLaneDistance = Math.abs(placement!.coord.q - routeAnchor.q);
  assertAiTest(bestLegal && sameHex(bestLegal.coord, placement!.coord), "planner should use the campaign-aware best Artillery placement");
  assertAiTest(routeLaneDistance <= 3, `base-assault Artillery should bias toward the player-base approach lane, got ${hexId(placement!.coord)} laneDistance=${routeLaneDistance}`);
}

