function testAiAirAntiAirKillExceptionIsStrict(): void {
  const state = createAiFixture(6);
  const helicopter = addAiFixtureUnit(state, "Enemy", "Attack Heli", { q: 14, r: 4 });
  const antiAir = addAiFixtureUnit(state, "Player", "Anti-Air", { q: 14, r: 10 });
  const unsafeCoord = { q: 14, r: 8 };
  const plan = beginEnemyTurnPlan(updateFog(state));
  const lowerConfidenceKill: EnemyAirActionPayoffContext = {
    unitType: helicopter.type,
    targetId: antiAir.id,
    expectedOutcome: {
      missProbability: 0.22,
      normalDamageProbability: 0,
      normalDamage: 0,
      criticalDamageProbability: 0.78,
      criticalDamage: antiAir.health,
      expectedDamage: antiAir.health * 0.78,
      killProbability: 0.78
    }
  };
  const highConfidenceKill: EnemyAirActionPayoffContext = {
    ...lowerConfidenceKill,
    expectedOutcome: {
      ...lowerConfidenceKill.expectedOutcome!,
      missProbability: 0.1,
      criticalDamageProbability: 0.9,
      expectedDamage: antiAir.health,
      killProbability: 0.9
    }
  };
  assertAiTest(!isEnemyAirMoveAllowedByThreatMap(state, helicopter, unsafeCoord, lowerConfidenceKill, plan), "0.78 anti-air kill probability should no longer permit unsafe air movement");
  assertAiTest(isEnemyAirMoveAllowedByThreatMap(state, helicopter, unsafeCoord, highConfidenceKill, plan), "high-confidence anti-air kill should permit the otherwise unsafe air movement");
}

