function testAiFallbackAirMovementRespectsAntiAir(): void {
  const state = createAiFixture(18);
  const antiAir = addAiFixtureUnit(state, "Player", "Anti-Air", { q: state.bases.Player.q, r: state.bases.Player.r - 11 });
  const helicopter = addAiFixtureUnit(state, "Enemy", "Attack Heli", { q: antiAir.coord.q, r: antiAir.coord.r - 8 });
  addAiFixtureUnit(state, "Player", "Infantry", { q: antiAir.coord.q, r: antiAir.coord.r + 2 });
  rememberAiFixtureUnit(state, antiAir);
  const visibleState = updateFog(state);
  const actor = visibleState.units.find((unit) => unit.id === helicopter.id);
  const knownAntiAir = visibleState.units.find((unit) => unit.id === antiAir.id);
  assertAiTest(Boolean(actor && knownAntiAir), "fallback fixture must retain the helicopter and Anti-Air");
  const unsafeFallbackCandidate = getLegalMoveCoordsWithVisibility(visibleState, actor!, getEnemyVisibleHexIds(visibleState))
    .find((coord) => isAiTestCoordInEffectiveAttackRange(visibleState, knownAntiAir!, coord));
  assertAiTest(Boolean(unsafeFallbackCandidate), "fixture must offer an unguarded fallback candidate inside Anti-Air range");

  executeEnemyEmergencyFallbackUnitAction(visibleState, actor!, { enemyMovementTrails: [] });
  const after = visibleState.units.find((unit) => unit.id === helicopter.id);
  assertAiTest(Boolean(after), "fallback air unit must remain alive");
  assertAiTest(!isAiTestCoordInEffectiveAttackRange(visibleState, knownAntiAir!, after!.coord), "fallback air movement must not enter Anti-Air range");
}

