function testAiOpeningInitialDeploymentFollowsDoctrine(): void {
  const state = createAiFixture(1);
  const plan = beginEnemyTurnPlan(updateFog(state));
  planEnemyPlacement(state, plan);
  const west = state.gates.find((gate) => gate.id === "West");
  const east = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(west && east), "fixture must include both gates");
  const seededGateId = getEnemySeededOpeningMainEffortGateId(state);
  const seededGate = seededGateId === "West" ? west! : east!;
  const oppositeGate = seededGateId === "West" ? east! : west!;
  const laneForCoord = (coord: UnitInstance["coord"]): GateState["id"] => {
    return coord.q <= state.bases.Enemy.q ? "West" : "East";
  };
  const count = (unitType: UnitType, gateId: GateState["id"]): number =>
    plan.placementPlan.filter((item) => item.unitType === unitType && laneForCoord(item.coord) === gateId).length;
  const centerSupport = plan.placementPlan.filter((item) => item.unitType === "Artillery" || item.unitType === "Anti-Air" || item.unitType === "Supply Truck");

  assertAiTest(count("Infantry", "West") === 3, `opening should place three Infantry west, got ${count("Infantry", "West")}`);
  assertAiTest(count("Infantry", "East") === 3, `opening should place three Infantry east, got ${count("Infantry", "East")}`);
  assertAiTest(count("Tank", "West") === 1, `opening should place one Tank west, got ${count("Tank", "West")}`);
  assertAiTest(count("Tank", "East") === 1, `opening should place one Tank east, got ${count("Tank", "East")}`);
  assertAiTest(plan.placementPlan.filter((item) => item.unitType === "IFV").every((item) => laneForCoord(item.coord) === seededGateId), "both IFVs should deploy to the seeded side");
  assertAiTest(plan.placementPlan.filter((item) => item.unitType === "Attack Heli").every((item) => laneForCoord(item.coord) === oppositeGate.id), "Helicopter should deploy opposite the seeded IFV side");
  assertAiTest(centerSupport.length === 3, `opening should place Artillery, Anti-Air, and Supply Truck centrally, got ${centerSupport.length}`);
  assertAiTest(
    centerSupport.every((item) => Math.abs(item.coord.q - state.bases.Enemy.q) <= 3),
    `opening fire/support units should deploy around the centre, got ${centerSupport.map((item) => `${item.unitType}@${hexId(item.coord)}`).join(", ")} base=${hexId(state.bases.Enemy)}`
  );
}

function testAiOpeningTankAssignmentsFollowPlacementLanes(): void {
  const state = createAiFixture(1);
  const plan = beginEnemyTurnPlan(updateFog(state));
  planEnemyPlacement(state, plan);
  withEnemyTurnPlan(plan, () => {
    executeEnemyPlacementPlan(state, plan);
    finalizeEnemyTacticalPlan(state, plan);
  });

  const tanks = getOwnerUnits(state, "Enemy").filter((unit) => unit.type === "Tank");
  const westTank = tanks.find((unit) => getOpeningDoctrineUnitSideGateId(state, unit) === "West");
  const eastTank = tanks.find((unit) => getOpeningDoctrineUnitSideGateId(state, unit) === "East");
  assertAiTest(tanks.length === 2, `opening fixture should place two Tanks, got ${tanks.length}`);
  assertAiTest(Boolean(westTank && eastTank), `opening Tanks should occupy both lanes, got ${tanks.map((unit) => hexId(unit.coord)).join(",")}`);
  assertAiTest(plan.campaignPlan.assignedGateByUnitId[westTank!.id] === "West", `west Tank should keep West assignment, got ${plan.campaignPlan.assignedGateByUnitId[westTank!.id] ?? "none"}`);
  assertAiTest(plan.campaignPlan.assignedGateByUnitId[eastTank!.id] === "East", `east Tank should keep East assignment, got ${plan.campaignPlan.assignedGateByUnitId[eastTank!.id] ?? "none"}`);
  assertAiTest(chooseEnemyPlannerOpeningGateSupportTarget(state, westTank!, plan)?.id === "West", "west Tank should support West gate capturers");
  assertAiTest(chooseEnemyPlannerOpeningGateSupportTarget(state, eastTank!, plan)?.id === "East", "east Tank should support East gate capturers");
}

function testAiOpeningScoutsUseSeededSides(): void {
  const state = createAiFixture(2);
  const seededGateId = getEnemySeededOpeningMainEffortGateId(state);
  const oppositeGateId = getOppositeGateId(seededGateId);
  const gate = state.gates.find((candidate) => candidate.id === seededGateId);
  const oppositeGate = state.gates.find((candidate) => candidate.id === oppositeGateId);
  assertAiTest(Boolean(gate && oppositeGate), "fixture must include seeded and opposite gates");
  const ifvA = addAiFixtureUnit(state, "Enemy", "IFV", { q: getOpeningGateTopLaneQ(state, gate!), r: state.bases.Enemy.r + 1 });
  const ifvB = addAiFixtureUnit(state, "Enemy", "IFV", { q: getOpeningGateTopLaneQ(state, gate!) + (seededGateId === "West" ? -1 : 1), r: state.bases.Enemy.r + 1 });
  const helicopter = addAiFixtureUnit(state, "Enemy", "Attack Heli", { q: getOpeningGateTopLaneQ(state, oppositeGate!), r: state.bases.Enemy.r + 1 });
  const plan = beginEnemyTurnPlan(updateFog(state));

  assertAiTest(plan.campaignPlan.assignedGateByUnitId[ifvA.id] === seededGateId, "first IFV should scout the seeded side");
  assertAiTest(plan.campaignPlan.assignedGateByUnitId[ifvB.id] === seededGateId, "second IFV should scout the seeded side");
  assertAiTest(plan.campaignPlan.assignedGateByUnitId[helicopter.id] === oppositeGateId, "Helicopter should scout the opposite side");
  assertAiTest(plan.rolesByUnitId[helicopter.id] === (oppositeGateId === "West" ? "PatrolWest" : "PatrolEast"), `Helicopter should receive opposite patrol mission, got ${plan.rolesByUnitId[helicopter.id] ?? "none"}`);
}

function testAiOpeningCenterSupportPushesNoMansLand(): void {
  const state = createAiFixture(2);
  const artillery = addAiFixtureUnit(state, "Enemy", "Artillery", { q: state.bases.Enemy.q - 1, r: state.bases.Enemy.r + 1 });
  const antiAir = addAiFixtureUnit(state, "Enemy", "Anti-Air", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 1 });
  const supply = addAiFixtureUnit(state, "Enemy", "Supply Truck", { q: state.bases.Enemy.q + 1, r: state.bases.Enemy.r + 1 });
  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const movedArtillery = visibleState.units.find((unit) => unit.id === artillery.id)!;
  const movedAntiAir = visibleState.units.find((unit) => unit.id === antiAir.id)!;
  const movedSupply = visibleState.units.find((unit) => unit.id === supply.id)!;
  const artilleryMove = chooseEnemyPlannerFireSupportMove(visibleState, movedArtillery, plan);
  const antiAirMove = chooseEnemyPlannerFireSupportMove(visibleState, movedAntiAir, plan);
  const supplyMove = chooseEnemyPlannerSupplyTruckSupportMove(visibleState, movedSupply, plan);

  assertAiTest(Boolean(artilleryMove && artilleryMove.r > movedArtillery.coord.r), `Artillery should push toward centre No Man's Land, got ${artilleryMove ? hexId(artilleryMove) : "none"}`);
  assertAiTest(Boolean(antiAirMove && antiAirMove.r > movedAntiAir.coord.r), `Anti-Air should push toward centre No Man's Land, got ${antiAirMove ? hexId(antiAirMove) : "none"}`);
  assertAiTest(Boolean(supplyMove && supplyMove.r > movedSupply.coord.r), `Supply Truck should push toward centre No Man's Land, got ${supplyMove ? hexId(supplyMove) : "none"}`);
}

function testAiOpeningFireSupportDoesNotDriftBackrow(): void {
  const state = createAiFixture(5);
  state.units = [];
  const antiAir = addAiFixtureUnit(state, "Enemy", "Anti-Air", { q: 11, r: 30 });
  const artillery = addAiFixtureUnit(state, "Enemy", "Artillery", { q: 17, r: 35 });
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: 9, r: 28 });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: 10, r: 30 });
  addKnownAiFixtureUnit(state, "Player", "IFV", { q: 10, r: 18 });
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: 18, r: 18 });
  addKnownAiFixtureUnit(state, "Player", "Attack Heli", { q: 19, r: 19 });

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const center = getEnemyOpeningCenterStagingCoord(visibleState);
  const supportUnits = [antiAir, artillery]
    .map((unit) => visibleState.units.find((candidate) => candidate.id === unit.id))
    .filter((unit): unit is UnitInstance => Boolean(unit));
  assertAiTest(supportUnits.length === 2, "fixture should retain Anti-Air and Artillery support units");

  for (const unit of supportUnits) {
    const action = enumerateEnemyCompoundActions(visibleState, unit, plan, {}, {})[0];
    const finalCoord = action ? getEnemyCompoundActionFinalCoord(unit, action) : unit.coord;
    assertAiTest(action?.kind !== "Hold", `${unit.type} should not hold in the back area while center support is needed`);
    assertAiTest(finalCoord.r < unit.coord.r, `${unit.type} should move out of the backrow, got ${hexId(unit.coord)} -> ${hexId(finalCoord)}`);
    assertAiTest(
      hexDistance(finalCoord, center) < hexDistance(unit.coord, center),
      `${unit.type} should close on center support staging, got ${hexId(unit.coord)} -> ${hexId(finalCoord)} center=${hexId(center)}`
    );
  }
}

