function testAiOpeningInfantryAllCommitToGates(): void {
  const state = createAiFixture(2);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  const eastGate = state.gates?.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  const infantry = [
    addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 8) }),
    addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q + 1, r: Math.max(0, westGate!.coord.r - 8) }),
    addAiFixtureUnit(state, "Enemy", "Infantry", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 8) }),
    addAiFixtureUnit(state, "Enemy", "Infantry", { q: eastGate!.coord.q - 1, r: Math.max(0, eastGate!.coord.r - 8) })
  ];
  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const visibleInfantry = infantry
    .map((unit) => visibleState.units.find((candidate) => candidate.id === unit.id))
    .filter((unit): unit is UnitInstance => Boolean(unit));
  const principalCapturers = visibleInfantry.filter((unit) => plan.rolesByUnitId[unit.id] === "CaptureGate");
  assertAiTest(principalCapturers.length <= 2, `opening should keep no more than one principal infantry per gate, got ${principalCapturers.length}`);
  for (const unit of visibleInfantry) {
    const target = chooseEnemyPlannerGateTargetForUnit(visibleState, unit, plan) ?? chooseGateObjective(visibleState, "Enemy", unit.coord);
    const role = plan.rolesByUnitId[unit.id];
    assertAiTest(role === "CaptureGate" || role === "ShadowCapturer" || role === "EscortCapture", `opening infantry ${unit.id} should be assigned to a capture lane role, got ${role ?? "none"}`);
    assertAiTest(Boolean(target), "opening infantry should have a gate target");
    const action = enumerateEnemyCompoundActions(visibleState, unit, plan, {}, {})[0];
    assertAiTest(Boolean(action), `opening infantry ${unit.id} should have a tactical action`);
    const finalCoord = action.moveTo ?? unit.coord;
    if (role === "CaptureGate") {
      assertAiTest(action.kind !== "Hold", `principal infantry ${unit.id} should not hold before reaching a gate`);
      assertAiTest(hexDistance(finalCoord, target!.coord) < hexDistance(unit.coord, target!.coord), `principal infantry ${unit.id} should move closer to its gate`);
      continue;
    }

    const principalId = plan.campaignPlan.laneTaskForces[target!.id].principalCapturerId;
    const principal = principalId ? state.units.find((candidate) => candidate.id === principalId) : undefined;
    if (principal && action.kind === "Hold") {
      const trailDistance = hexDistance(unit.coord, principal.coord);
      assertAiTest(trailDistance >= 1 && trailDistance <= 3, `shadow infantry ${unit.id} may only hold while trailing its principal, distance ${trailDistance}`);
    } else {
      assertAiTest(action.kind !== "Hold", `shadow infantry ${unit.id} should move when not already trailing its principal`);
    }
  }
}

