function testAiOpeningLaneTaskForcesPersist(): void {
  const state = createAiFixture(4);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  const eastGate = state.gates?.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  const westPrincipal = addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 7) });
  const westSupport = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 1 });
  const eastPrincipal = addAiFixtureUnit(state, "Enemy", "Infantry", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 7) });
  const assignedGateByUnitId: Record<string, GateState["id"]> = {
    [westPrincipal.id]: "West",
    [westSupport.id]: "West",
    [eastPrincipal.id]: "East"
  };
  const rolesByUnitId: Record<string, EnemyMission> = {
    [westPrincipal.id]: "CaptureGate",
    [westSupport.id]: "Escort",
    [eastPrincipal.id]: "CaptureGate"
  };
  const playerIntel = getEnemyPlannerPlayerIntel(state);
  const objectiveClock = estimateEnemyObjectiveClocks(state, playerIntel);
  const laneTaskForces: Record<GateState["id"], EnemyLaneTaskForcePlan> = {
    West: createEnemyLaneTaskForcePlan(state, "West", assignedGateByUnitId, rolesByUnitId),
    East: createEnemyLaneTaskForcePlan(state, "East", assignedGateByUnitId, rolesByUnitId)
  };
  (state as GameStateWithEnemyCampaign).enemyCampaignPlan = {
    schemaVersion: 1,
    day: state.day - 1,
    generatedDay: state.day - 1,
    invalidationKey: buildEnemyCampaignInvalidationKey(state, rolesByUnitId, "OpeningGateRace", objectiveClock, playerIntel),
    phase: "OpeningGateRace",
    mainEffortGateId: "West",
    secondaryGateId: "East",
    assignedCapturerByGateId: getEnemyCampaignLaneField(laneTaskForces, "principalCapturerId"),
    backupCapturerByGateId: getEnemyCampaignLaneField(laneTaskForces, "backupCapturerId"),
    escortGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "escortIds"),
    scoutGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "scoutIds"),
    supportGroupByGateId: getEnemyCampaignLaneGroup(laneTaskForces, "supportIds"),
    baseAssaultPackage: createEmptyEnemyBaseAssaultPackage(),
    assignedGateByUnitId,
    laneTaskForces,
    baseAssaultRoute: [],
    expectedTurnsToCapture: objectiveClock.enemyTurnsToGates,
    objectiveClock
  };

  const plan = beginEnemyTurnPlan(updateFog(state));
  const westLane = plan.campaignPlan.laneTaskForces.West;

  assertAiTest(plan.campaignPlan.assignedGateByUnitId[westSupport.id] === "West", "opening Tank support should keep its assigned lane across turns");
  assertAiTest(westLane.principalCapturerId === westPrincipal.id, "west lane should keep its previous principal capturer");
  assertAiTest(westLane.supportIds.includes(westSupport.id), "west lane should keep its previous Tank support member");
}

function testAiCampaignPlanPersistsUntilInvalidated(): void {
  const state = createAiFixture(4);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  const eastGate = state.gates?.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  const westInfantry = addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 7) });
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 7) });
  const westTank = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 1 });

  const visibleState = updateFog(state);
  const firstPlan = beginEnemyTurnPlan(visibleState);
  const firstGeneratedDay = firstPlan.campaignPlan.generatedDay;
  const firstKey = firstPlan.campaignPlan.invalidationKey;
  const westLane = firstPlan.campaignPlan.laneTaskForces.West;
  const tankGateId = firstPlan.campaignPlan.assignedGateByUnitId[westTank.id];
  assertAiTest(firstPlan.campaignPlan.assignedCapturerByGateId.West === westLane.principalCapturerId, "campaign plan should expose assigned capturer by gate");
  assertAiTest(Boolean(tankGateId && (firstPlan.campaignPlan.supportGroupByGateId[tankGateId] ?? []).includes(westTank.id)), "campaign plan should expose support group by gate");
  persistEnemyCampaignPlan(visibleState, firstPlan);

  visibleState.day += 1;
  const secondPlan = beginEnemyTurnPlan(updateFog(visibleState));

  assertAiTest(secondPlan.campaignPlan.generatedDay === firstGeneratedDay, "unchanged campaign plan should keep its original generated day");
  assertAiTest(secondPlan.campaignPlan.day === visibleState.day, "reused campaign plan should refresh its current day");
  assertAiTest(secondPlan.campaignPlan.invalidationKey === firstKey, "unchanged campaign plan should keep the same invalidation key");
  assertAiTest(secondPlan.campaignPlan.assignedGateByUnitId[westInfantry.id] === firstPlan.campaignPlan.assignedGateByUnitId[westInfantry.id], "reused campaign plan should preserve capturer assignment");
  assertAiTest(secondPlan.campaignPlan.expectedTurnsToCapture.West !== undefined, "reused campaign plan should refresh expected gate clocks");
}

function testAiCampaignPlanInvalidatesOnGateChange(): void {
  const state = createAiFixture(4);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  const eastGate = state.gates?.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 7) });
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 7) });

  const firstPlan = beginEnemyTurnPlan(updateFog(state));
  const firstKey = firstPlan.campaignPlan.invalidationKey;

  state.day += 1;
  westGate!.owner = "Enemy";
  westGate!.knownOwner = "Enemy";
  westGate!.occupation.Enemy = GATE_CAPTURE_DAYS;
  const secondPlan = beginEnemyTurnPlan(updateFog(state));

  assertAiTest(secondPlan.campaignPlan.generatedDay === state.day, "gate state change should regenerate the campaign plan");
  assertAiTest(secondPlan.campaignPlan.invalidationKey !== firstKey, "gate state change should change the campaign invalidation key");
  assertAiTest(secondPlan.campaignPlan.assignedGateByUnitId !== firstPlan.campaignPlan.assignedGateByUnitId, "invalidated campaign plan should rebuild assignment storage");
}

function testAiMidgameMainEffortGetsBestPackage(): void {
  const state = createAiFixture(12);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  const eastGate = state.gates?.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  westGate!.occupation.Enemy = 1;
  const bestCapturer = addAiFixtureUnit(state, "Enemy", "Ghost", { q: westGate!.coord.q + 1, r: Math.max(0, westGate!.coord.r - 4) });
  const spareCapturer = addAiFixtureUnit(state, "Enemy", "Infantry", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 4) });
  const escort = addAiFixtureUnit(state, "Enemy", "Tank", { q: westGate!.coord.q - 1, r: Math.max(0, westGate!.coord.r - 4) });
  const scout = addAiFixtureUnit(state, "Enemy", "Jet", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 5) });

  const plan = beginEnemyTurnPlan(updateFog(state));
  const mainGateId = plan.campaignPlan.mainEffortGateId;
  assertAiTest(mainGateId === "West", `active midgame gate clock should become main effort, got ${mainGateId ?? "none"}`);
  const mainLane = plan.campaignPlan.laneTaskForces[mainGateId];
  const secondaryLane = plan.campaignPlan.laneTaskForces[plan.campaignPlan.secondaryGateId ?? "East"];

  assertAiTest(mainLane.principalCapturerId === bestCapturer.id, "main effort should receive the best capturer");
  assertAiTest(mainLane.supportIds.includes(escort.id), "main effort should receive Tank/IFV escort support");
  assertAiTest(mainLane.scoutIds.includes(scout.id), "main effort should receive the scout");
  assertAiTest(plan.campaignPlan.assignedGateByUnitId[spareCapturer.id] === "West", "without enough support, spare capturer should reinforce the main effort");
  assertAiTest(!secondaryLane.principalCapturerId, "secondary effort should not receive a principal capturer without enough units for dual pressure");
}

function testAiMidgamePressuresBothGatesWithEnoughUnits(): void {
  const state = createAiFixture(12);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  const eastGate = state.gates?.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  westGate!.occupation.Enemy = 1;
  const westCapturer = addAiFixtureUnit(state, "Enemy", "Ghost", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 4) });
  const eastCapturer = addAiFixtureUnit(state, "Enemy", "Operator", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 4) });
  const westEscort = addAiFixtureUnit(state, "Enemy", "Tank", { q: westGate!.coord.q - 1, r: Math.max(0, westGate!.coord.r - 4) });
  const eastEscort = addAiFixtureUnit(state, "Enemy", "IFV", { q: eastGate!.coord.q + 1, r: Math.max(0, eastGate!.coord.r - 4) });
  const westScout = addAiFixtureUnit(state, "Enemy", "Jet", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 5) });
  const eastScout = addAiFixtureUnit(state, "Enemy", "Attack Heli", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 5) });

  const plan = beginEnemyTurnPlan(updateFog(state));
  assertAiTest(plan.campaignPlan.mainEffortGateId === "West", `west active clock should be main effort, got ${plan.campaignPlan.mainEffortGateId ?? "none"}`);
  assertAiTest(plan.campaignPlan.secondaryGateId === "East", `east should be secondary effort, got ${plan.campaignPlan.secondaryGateId ?? "none"}`);
  const westLane = plan.campaignPlan.laneTaskForces.West;
  const eastLane = plan.campaignPlan.laneTaskForces.East;

  assertAiTest(westLane.principalCapturerId === westCapturer.id, "dual pressure should keep best capturer on main effort");
  assertAiTest(eastLane.principalCapturerId === eastCapturer.id, "dual pressure should assign a principal capturer to secondary effort");
  assertAiTest(westLane.supportIds.includes(westEscort.id), "main effort should keep armor support");
  assertAiTest(eastLane.supportIds.includes(eastEscort.id), "secondary effort should receive armor support when dual pressure is viable");
  assertAiTest(westLane.scoutIds.includes(westScout.id), "main effort should receive a scout");
  assertAiTest(eastLane.scoutIds.includes(eastScout.id), "secondary effort should receive a scout when dual pressure is viable");
}

