function testAiCommittedInfantryAdvanceThroughHelicopterPressure(): void {
  const state = createAiFixture(4);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  assertAiTest(Boolean(westGate), "fixture must include west gate");
  const principal = addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 6) });
  const backup = addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q + 1, r: Math.max(0, westGate!.coord.r - 6) });
  const escort = addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q - 1, r: Math.max(0, westGate!.coord.r - 6) });
  seedAiFixtureCampaignGateAssignment(state, principal, "West");
  let visibleState = updateFog(state);
  let plan = beginEnemyTurnPlan(visibleState);
  for (const [unit, role] of [[principal, "CaptureGate"], [backup, "ShadowCapturer"], [escort, "EscortCapture"]] as [UnitInstance, EnemyMission][]) {
    plan.rolesByUnitId[unit.id] = role;
    plan.campaignPlan.assignedGateByUnitId[unit.id] = "West";
  }
  const visiblePrincipal = visibleState.units.find((unit) => unit.id === principal.id);
  assertAiTest(Boolean(visiblePrincipal), "helicopter-pressure fixture must retain principal infantry");
  const exposedProgress = chooseHardOpeningCaptureGateProgressMove(visibleState, visiblePrincipal!, plan);
  assertAiTest(Boolean(exposedProgress), "fixture must provide a gate progress move before helicopter pressure");

  const helicopter = addAiFixtureUnit(state, "Player", "Attack Heli", { q: exposedProgress!.q, r: Math.min(state.map.height - 1, exposedProgress!.r + 2) });
  rememberAiFixtureUnit(state, helicopter);
  visibleState = updateFog(state);
  plan = beginEnemyTurnPlan(visibleState);
  for (const [unit, role] of [[principal, "CaptureGate"], [backup, "ShadowCapturer"], [escort, "EscortCapture"]] as [UnitInstance, EnemyMission][]) {
    plan.rolesByUnitId[unit.id] = role;
    plan.campaignPlan.assignedGateByUnitId[unit.id] = "West";
  }

  const pressuredPrincipal = visibleState.units.find((unit) => unit.id === principal.id);
  assertAiTest(Boolean(pressuredPrincipal), "helicopter-pressure fixture must retain pressured principal infantry");
  const replyDamage = estimatePlayerLikelyReplyDamageAtPlanner(visibleState, pressuredPrincipal!, exposedProgress!, plan);
  const exposedAction = createEnemyCompoundAction(visibleState, pressuredPrincipal!, plan, "Move", { moveTo: exposedProgress! }, {}, {});
  const action = enumerateEnemyCompoundActions(visibleState, pressuredPrincipal!, plan, {}, {})[0];
  const finalCoord = action.moveTo ?? pressuredPrincipal!.coord;

  assertAiTest(replyDamage > 0 && replyDamage < pressuredPrincipal!.health, `fixture progress move should enter non-lethal Helicopter reply pressure, got ${replyDamage.toFixed(1)}`);
  assertAiTest(isCommittedObjectiveCaptureAdvanceExposureJustified(visibleState, pressuredPrincipal!, exposedProgress!, plan, replyDamage), "three committed infantry should justify non-lethal gate-advance exposure");
  assertAiTest(isEnemyCompoundActionPlausiblyLegal(visibleState, pressuredPrincipal!, exposedAction, plan), "committed gate infantry progress should not be rejected solely for Helicopter reply pressure");
  assertAiTest(action.kind !== "Hold", `committed gate infantry should keep advancing under Helicopter pressure, got ${action.kind}`);
  assertAiTest(hexDistance(finalCoord, westGate!.coord) < hexDistance(pressuredPrincipal!.coord, westGate!.coord), `committed gate infantry should move closer to the gate, got ${hexId(finalCoord)}`);
}

