function testAiOpeningTankSupportsGateCapture(): void {
  const state = createAiFixture(2);
  const westGate = state.gates?.find((gate) => gate.id === "West");
  const eastGate = state.gates?.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 8) });
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 8) });
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 1 });
  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(visibleTank), "opening tank fixture should remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  const target = chooseEnemyPlannerOpeningGateSupportTarget(visibleState, visibleTank!, plan);
  assertAiTest(plan.rolesByUnitId[tank.id] === "Escort", `opening tank should escort gate capturers, got ${plan.rolesByUnitId[tank.id] ?? "none"}`);
  assertAiTest(Boolean(target), "opening tank should have a gate support target");
  const supportCoord = chooseEnemyPlannerOpeningGateArmorSupportCoord(visibleState, visibleTank!, plan, target!);
  assertAiTest(Boolean(supportCoord), "opening tank should choose a concrete support hex");
  assertAiTest(hexDistance(supportCoord!, target!.coord) >= 1 && hexDistance(supportCoord!, target!.coord) <= 3, "opening tank support hex should be 1-3 hexes from the gate");
  assertAiTest(!sameHex(supportCoord!, target!.coord), "opening tank support hex should not be the capture tile");
  assertAiTest(canEnemyGateSupportPositionTargetGate(visibleState, visibleTank!, supportCoord!, target!), "opening tank support hex should be able to target the supported Gate tile");
  const action = enumerateEnemyCompoundActions(visibleState, visibleTank!, plan, {}, {})[0];
  assertAiTest(Boolean(action), "opening tank should have a tactical action");
  const finalCoord = action.moveTo ?? visibleTank!.coord;
  assertAiTest(action.kind !== "Hold", "opening tank should not hold at the base during the gate race");
  assertAiTest(!sameHex(finalCoord, target!.coord), "opening tank should support near the gate without occupying the capture tile");
  assertAiTest(hexDistance(finalCoord, supportCoord!) < hexDistance(visibleTank!.coord, supportCoord!), "opening tank should move toward its support hex");
  assertAiTest(hexDistance(finalCoord, target!.coord) < hexDistance(visibleTank!.coord, target!.coord), "opening tank should move closer to its supported gate");
}

