function testAiBaseAssaultCombatRejectsRearwardDrift(): void {
  const state = createAiFixture(22);
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
    gate.occupation.Enemy = GATE_CAPTURE_DAYS;
  });
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Player.q, r: 2 });
  addAiFixtureUnit(state, "Enemy", "Ghost", { q: state.bases.Player.q - 1, r: 4 });
  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(visibleTank), "rearward-drift fixture must retain Tank");
  const plan = beginEnemyTurnPlan(visibleState);
  const rearwardMove = { q: visibleTank!.coord.q, r: Math.max(0, visibleTank!.coord.r - 2) };
  const forwardMove = { q: visibleTank!.coord.q, r: visibleTank!.coord.r + 2 };
  const rearwardAction = createEnemyCompoundAction(visibleState, visibleTank!, plan, "Move", { moveTo: rearwardMove }, {}, {});
  const directState = cloneState(visibleState);
  const directTank = directState.units.find((unit) => unit.id === tank.id)!;
  const directPlan = beginEnemyTurnPlan(directState);
  directPlan.rolesByUnitId[directTank.id] = "Siege";

  assertAiTest(plan.rolesByUnitId[tank.id] === "Siege", `rearward-drift Tank should receive Siege, got ${plan.rolesByUnitId[tank.id] ?? "none"}`);
  assertAiTest(displayHexId(visibleState.map, rearwardMove).endsWith(",39"), `fixture rearward move should reproduce the logged back-row retreat, got ${displayHexId(visibleState.map, rearwardMove)}`);
  assertAiTest(canMoveUnitTo(visibleState, visibleTank!, rearwardMove), `fixture rearward move must be legal movement, got ${displayHexId(visibleState.map, rearwardMove)}`);
  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, visibleTank!, rearwardAction, plan), "base-assault Siege must reject rearward drift toward its own back line");
  assertAiTest(!executeEnemyCompoundActionDirect(directState, directTank, rearwardAction, directPlan), "live executor must reject base-assault drift to display row 39");
  assertAiTest(isEnemyCompoundActionPlausiblyLegal(visibleState, visibleTank!, createEnemyCompoundAction(visibleState, visibleTank!, plan, "Move", { moveTo: forwardMove }, {}, {}), plan), "base-assault Siege should allow forward pressure toward the player base");
}

function testAiBaseAssaultCombatRejectsNonProgressShuffle(): void {
  const state = createAiFixture(24);
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
    gate.occupation.Enemy = GATE_CAPTURE_DAYS;
  });
  const entryRow = getPlayerBaseAssaultAreaMinRow(state);
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: Math.max(0, state.bases.Player.q - 8), r: entryRow - 3 });
  addAiFixtureUnit(state, "Enemy", "Ghost", { q: state.bases.Player.q, r: entryRow - 4 });
  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(visibleTank), "nonprogress-shuffle fixture must retain Tank");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleTank!.id] = "Siege";
  const currentDistance = hexDistance(visibleTank!.coord, visibleState.bases.Player);
  const shuffle = getEnemyLegalMoveCoords(visibleState, visibleTank!)
    .filter((coord) => canMoveUnitTo(visibleState, visibleTank!, coord))
    .filter((coord) => coord.r > visibleTank!.coord.r)
    .filter((coord) => hexDistance(coord, visibleState.bases.Player) >= currentDistance)
    .sort((first, second) => hexDistance(second, visibleState.bases.Player) - hexDistance(first, visibleState.bases.Player) || hexId(first).localeCompare(hexId(second)))[0];
  assertAiTest(Boolean(shuffle), "fixture must provide a forward-row shuffle that does not close on the player base");
  const action = createEnemyCompoundAction(visibleState, visibleTank!, plan, "Move", { moveTo: shuffle! }, {}, {});

  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, visibleTank!, action, plan), `base-assault Siege must reject nonprogress shuffles, got ${displayHexId(visibleState.map, shuffle!)}`);
}

