function testAiBaseAssaultFirePositionsSpreadCoverage(): void {
  const state = createAiFixture(24);
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
    gate.occupation.Enemy = GATE_CAPTURE_DAYS;
  });
  const entryRow = getPlayerBaseAssaultAreaMinRow(state);
  const units = [
    addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Player.q - 1, r: entryRow - 5 }),
    addAiFixtureUnit(state, "Enemy", "IFV", { q: state.bases.Player.q, r: entryRow - 5 }),
    addAiFixtureUnit(state, "Enemy", "Artillery", { q: state.bases.Player.q + 1, r: entryRow - 5 })
  ];
  addAiFixtureUnit(state, "Enemy", "Ghost", { q: state.bases.Player.q - 2, r: entryRow - 4 });
  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const targets = units.map((unit) => {
    const visible = visibleState.units.find((candidate) => candidate.id === unit.id);
    assertAiTest(Boolean(visible), `${unit.type} fire-position fixture must retain unit`);
    const target = chooseEnemyBaseAssaultPenetrationTarget(visibleState, visible!, plan);
    assertAiTest(Boolean(target), `${unit.type} should choose a base fire position`);
    assertAiTest(scoreEnemyBaseAssaultFireCoverage(visibleState, visible!, target!, plan) >= 520, `${unit.type} fire position should cover the player base/backline, got ${hexId(target!)}`);
    return target!;
  });
  const uniqueQs = new Set(targets.map((coord) => coord.q));

  assertAiTest(uniqueQs.size >= 2, `base-assault fire positions should spread across firing lanes, got ${targets.map(hexId).join(", ")}`);
}

