  assertAiTest(emergencyAssessment.initiativePressure < recoveryAssessment.initiativePressure, `base emergency should clamp initiative pressure below recovery pressure ${recoveryAssessment.initiativePressure.toFixed(1)}, got ${emergencyAssessment.initiativePressure.toFixed(1)}`);
  assertAiTest(emergencyAssessment.initiativeReasons.includes("base-emergency-clamp"), "initiative reasons should include base emergency clamp");
