function testAiRecoveryGateScoreDiscountsPlayerTheatrePower(): void {
  const quiet = createAiFixture(14);
  quiet.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
    gate.occupation.Player = GATE_CAPTURE_DAYS;
    gate.occupation.Enemy = 0;
  });
  const quietGate = quiet.gates.find((gate) => gate.id === "West");
  assertAiTest(Boolean(quietGate), "fixture must include west gate");
  clearEnemyEvaluationCache();
  const quietAssessment = getEnemyStrategicAssessment(quiet);
  const quietScore = scoreEnemyGateCaptureObjective(quiet, quiet.bases.Enemy, quietGate!);

  const pressured = createAiFixture(14);
  pressured.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
    gate.occupation.Player = GATE_CAPTURE_DAYS;
    gate.occupation.Enemy = 0;
  });
  const pressuredGate = pressured.gates.find((gate) => gate.id === "West");
  assertAiTest(Boolean(pressuredGate), "fixture must include pressured west gate");
  const blocker = addAiFixtureUnit(pressured, "Player", "Infantry", { q: pressuredGate!.coord.q, r: pressuredGate!.coord.r + 1 });
  rememberAiFixtureUnit(pressured, blocker);
  clearEnemyEvaluationCache();
  const pressuredAssessment = getEnemyStrategicAssessment(pressured);
  const theatre = estimateGateTheatrePressure(pressured, pressuredGate!);
  const pressuredScore = scoreEnemyGateCaptureObjective(pressured, pressured.bases.Enemy, pressuredGate!);

  assertAiTest(quietAssessment.strategicPhase === "Recovery", `quiet fixture should be Recovery, got ${quietAssessment.strategicPhase}`);
  assertAiTest(pressuredAssessment.strategicPhase === "Recovery", `pressured fixture should remain Recovery, got ${pressuredAssessment.strategicPhase}`);
  assertAiTest(theatre.player.combat > theatre.enemy.combat, "fixture should have player-favored gate theatre power");
  assertAiTest(pressuredScore < quietScore - 70, `player-favored theatre should discount Recovery gate score, quiet=${quietScore.toFixed(1)} pressured=${pressuredScore.toFixed(1)}`);
}

function testAiGateLockoutCombatPrecedesRecovery(): void {
  const state = createAiFixture(14);
  state.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
    gate.occupation.Player = GATE_CAPTURE_DAYS;
    gate.occupation.Enemy = 0;
  });
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 2 });
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: state.bases.Enemy.q + 1, r: state.bases.Enemy.r + 2 });
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: westGate!.coord.q, r: westGate!.coord.r + 1 });
  addKnownAiFixtureUnit(state, "Player", "Artillery", { q: eastGate!.coord.q, r: eastGate!.coord.r + 2 });
  addKnownAiFixtureUnit(state, "Player", "Infantry", westGate!.coord);

  const plan = beginEnemyTurnPlan(state);
  const recoveryWeights = getEnemyStrategicPhaseWeights("Recovery");
  const lockoutWeights = getEnemyStrategicPhaseWeights("GateLockoutCombat");

  assertAiTest(plan.strategicSnapshot.strategicPhase === "GateLockoutCombat", `player gate lockout with forward force should transition to GateLockoutCombat, got ${plan.strategicSnapshot.strategicPhase}`);
  assertAiTest(plan.campaignPlan.phase === "GateLockoutCombat", `campaign phase should follow strategic snapshot, got ${plan.campaignPlan.phase}`);
  assertAiTest(lockoutWeights.combat > recoveryWeights.combat && lockoutWeights.defense > recoveryWeights.defense, "lockout combat should raise combat and defense weights above recovery");
  assertAiTest(lockoutWeights.gate < recoveryWeights.gate, "lockout combat should lower raw gate-capture weight below recovery");
  assertAiTest(plan.rolesByUnitId[tank.id] !== "CaptureGate", `combat tank should not become raw gate capturer, got ${plan.rolesByUnitId[tank.id] ?? "none"}`);
}

function testAiGateLockoutExitsWhenCounterattackReady(): void {
  const state = createAiFixture(16);
  state.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
    gate.occupation.Player = GATE_CAPTURE_DAYS;
    gate.occupation.Enemy = 0;
  });
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");

  const capturer = addAiFixtureUnit(state, "Enemy", "Operator", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 5) });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: westGate!.coord.q - 1, r: Math.max(0, westGate!.coord.r - 2) });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: westGate!.coord.q + 1, r: Math.max(0, westGate!.coord.r - 2) });
  addAiFixtureUnit(state, "Enemy", "Artillery", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 4) });
  addKnownAiFixtureUnit(state, "Player", "Infantry", westGate!.coord);
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: westGate!.coord.q + 2, r: westGate!.coord.r + 2 });
  addKnownAiFixtureUnit(state, "Player", "Artillery", { q: eastGate!.coord.q, r: eastGate!.coord.r + 2 });

  const visibleState = updateFog(state);
  const playerIntel = getEnemyPlannerPlayerIntel(visibleState);
  const targetGate = chooseEnemyGateLockoutSuccessGate(visibleState, playerIntel);
  const theatre = targetGate ? estimateGateTheatrePressure(visibleState, targetGate, 9, playerIntel) : undefined;
  const phase = getEnemyStrategicAssessment(visibleState).strategicPhase;
  const plan = beginEnemyTurnPlan(visibleState);

  assertAiTest(scoreEnemyGateLockoutCombatPressure(visibleState, playerIntel) >= ENEMY_GATE_LOCKOUT_COMBAT_PRESSURE_THRESHOLD, "fixture should still have lockout combat pressure");
  assertAiTest(Boolean(targetGate && theatre), "fixture should choose a lockout success gate");
  assertAiTest(theatre!.enemy.total >= theatre!.player.total * 0.98 || theatre!.enemy.combat >= theatre!.player.combat * 1.02, "fixture should have enemy theatre parity near the chosen gate");
  assertAiTest(hasEnemyGateLockoutCounterattackSucceeded(visibleState, playerIntel), "counterattack readiness should satisfy the lockout success condition");
  assertAiTest(canEnemyHealthyHumanReachOrSafelyApproachGate(visibleState, visibleState.units.find((unit) => unit.id === capturer.id)!, targetGate!, theatre!, playerIntel), "healthy human should be able to safely approach the chosen gate");
  assertAiTest(phase === "Recovery", `counterattack-ready lockout should exit to Recovery, got ${phase}`);
  assertAiTest(plan.campaignPlan.phase === "Recovery", `campaign plan should follow Recovery after lockout success, got ${plan.campaignPlan.phase}`);
}

function testAiGateLockoutAssignsClearingRolesBeforeCapture(): void {
  const state = createAiFixture(14);
  state.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
    gate.occupation.Player = GATE_CAPTURE_DAYS;
    gate.occupation.Enemy = 0;
  });
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");

  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 5) });
  const ifv = addAiFixtureUnit(state, "Enemy", "IFV", { q: eastGate!.coord.q + 1, r: Math.max(0, eastGate!.coord.r - 5) });
  const artillery = addAiFixtureUnit(state, "Enemy", "Artillery", { q: eastGate!.coord.q - 1, r: Math.max(0, eastGate!.coord.r - 6) });
  const antiAir = addAiFixtureUnit(state, "Enemy", "Anti-Air", { q: eastGate!.coord.q + 2, r: Math.max(0, eastGate!.coord.r - 6) });
  const infantry = addAiFixtureUnit(state, "Enemy", "Infantry", { q: eastGate!.coord.q, r: Math.max(0, eastGate!.coord.r - 7) });
  addKnownAiFixtureUnit(state, "Player", "Infantry", eastGate!.coord);
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: eastGate!.coord.q + 1, r: eastGate!.coord.r + 1 });
  addKnownAiFixtureUnit(state, "Player", "Artillery", { q: westGate!.coord.q, r: westGate!.coord.r + 1 });

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const tankRole = plan.rolesByUnitId[tank.id];
  const ifvRole = plan.rolesByUnitId[ifv.id];

  assertAiTest(plan.strategicSnapshot.strategicPhase === "GateLockoutCombat", `fixture should enter GateLockoutCombat, got ${plan.strategicSnapshot.strategicPhase}`);
  assertAiTest(tankRole === "ClearGateApproach" || tankRole === "CoverCounterattack" || tankRole === "DefendGate", `tank should clear, cover, or defend the gate approach, got ${tankRole ?? "none"}`);
  assertAiTest(ifvRole === "ClearGateApproach" || ifvRole === "CoverCounterattack" || ifvRole === "DefendGate" || ifvRole === "BaseSentry", `IFV should clear, cover, defend, or guard against base pressure, got ${ifvRole ?? "none"}`);
  assertAiTest(plan.rolesByUnitId[artillery.id] === "SuppressGateZone", `artillery should suppress the gate zone, got ${plan.rolesByUnitId[artillery.id] ?? "none"}`);
  assertAiTest(plan.rolesByUnitId[antiAir.id] === "CoverCounterattack" || plan.rolesByUnitId[antiAir.id] === "BaseSentry", `anti-air should cover the counterattack or guard against base pressure, got ${plan.rolesByUnitId[antiAir.id] ?? "none"}`);
  assertAiTest(plan.rolesByUnitId[infantry.id] === "ReserveCapturer", `infantry should wait as reserve capturer, got ${plan.rolesByUnitId[infantry.id] ?? "none"}`);
  assertAiTest(![tank, ifv, artillery, antiAir].some((unit) => plan.rolesByUnitId[unit.id] === "CaptureGate"), "combat units should not be assigned raw CaptureGate roles during lockout combat");
}

function testAiGateLockoutEconomyForcesCombatProduction(): void {
  const state = createAiFixture(14);
  satisfyAiFixtureEfficiencyGate(state);
  addBuilding(state, "Enemy", "Special Services");
  addBuilding(state, "Enemy", "Drone Factory");
  state.enemyEconomy.moneyPoundsBn = 95;
  state.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
    gate.occupation.Player = GATE_CAPTURE_DAYS;
    gate.occupation.Enemy = 0;
  });
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  addKnownAiFixtureUnit(state, "Player", "Infantry", westGate!.coord);
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 2 });
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: westGate!.coord.q, r: westGate!.coord.r + 1 });
  addKnownAiFixtureUnit(state, "Player", "Artillery", { q: eastGate!.coord.q, r: eastGate!.coord.r + 2 });

  const plan = beginEnemyTurnPlan(updateFog(state));
  planEnemyEconomy(state, plan);
  const firstPurchase = plan.economyPlan.purchases[0];

  assertAiTest(plan.campaignPlan.phase === "GateLockoutCombat", `fixture should enter GateLockoutCombat, got ${plan.campaignPlan.phase}`);
  assertAiTest(plan.economyPlan.reservedFunds <= 12, `lockout economy should lower reserves, got ${plan.economyPlan.reservedFunds}`);
  assertAiTest(
    Boolean(firstPurchase?.kind === "production" && firstPurchase.unitType && isEnemyGateLockoutDirectCombatProductionUnit(firstPurchase.unitType)),
    `GateLockoutCombat should force affordable direct combat production first, got ${firstPurchase?.kind ?? "none"} ${firstPurchase?.unitType ?? ""}`
  );
  assertAiTest(
    !firstPurchase || firstPurchase.kind !== "research" || !firstPurchase.researchType || !isEconomyOrThroughputResearch(firstPurchase.researchType),
    `GateLockoutCombat should suppress economy/throughput research first purchase, got ${firstPurchase?.researchType ?? "none"}`
  );
  assertAiTest(
    plan.economyPlan.purchases.every((item) => item.kind !== "research"),
    "GateLockoutCombat should not choose research while direct combat production is affordable"
  );
}

