function testAiGateLockoutScoutsBeforeCounterattack(): void {
  const state = createAiFixture(16);
  state.gates.forEach((gate) => {
    gate.owner = "Player";
    gate.knownOwner = "Player";
    gate.occupation.Player = GATE_CAPTURE_DAYS;
    gate.occupation.Enemy = 0;
  });
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");

  const scout = addAiFixtureUnit(state, "Enemy", "Attack Heli", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 5) });
  const bomber = addAiFixtureUnit(state, "Enemy", "Bomber", { q: westGate!.coord.q + 1, r: Math.max(0, westGate!.coord.r - 6) });
  const capturer = addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q - 1, r: Math.max(0, westGate!.coord.r - 5) });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: westGate!.coord.q + 2, r: Math.max(0, westGate!.coord.r - 4) });
  const artillery = addKnownAiFixtureUnit(state, "Player", "Artillery", { q: westGate!.coord.q, r: westGate!.coord.r + 2 });
  const antiAir = addKnownAiFixtureUnit(state, "Player", "Anti-Air", { q: westGate!.coord.q + 2, r: westGate!.coord.r + 2 });
  addKnownAiFixtureUnit(state, "Player", "Infantry", westGate!.coord);
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: eastGate!.coord.q, r: eastGate!.coord.r + 2 });
  [artillery, antiAir].forEach((unit) => rememberAiFixtureUnit(state, unit));

  const visibleState = updateFog(state);
  const visibleScout = visibleState.units.find((unit) => unit.id === scout.id);
  assertAiTest(Boolean(visibleScout), "lockout scout fixture must retain scout unit");
  const plan = beginEnemyTurnPlan(visibleState);
  const targetGate = chooseEnemyGateLockoutCounterattackGate(visibleState, plan);
  const scoutTarget = chooseEnemyStrategicScoutTarget(visibleState, visibleScout!, plan);

  assertAiTest(plan.campaignPlan.phase === "GateLockoutCombat", `fixture should enter GateLockoutCombat, got ${plan.campaignPlan.phase}`);
  assertAiTest(targetGate?.id === westGate!.id, `fixture should counterattack the west gate, got ${targetGate?.id ?? "none"}`);
  assertAiTest(plan.rolesByUnitId[scout.id] === "Scout" || plan.rolesByUnitId[scout.id] === "Escort", `GateLockoutCombat should assign a recon unit to Scout or Escort, got ${plan.rolesByUnitId[scout.id] ?? "none"}`);
  assertAiTest(
    scoutTarget?.reason.startsWith("lockout-"),
    `lockout scout should target counterattack reveal work, got ${scoutTarget?.reason ?? "none"}`
  );
  assertAiTest(plan.rolesByUnitId[scout.id] === "Escort" || (plan.activationDependencies[bomber.id] ?? []).includes(scout.id), "lockout aircraft should wait for counterattack scout reveal unless scout is assigned as escort");
  assertAiTest(plan.rolesByUnitId[scout.id] === "Escort" || (plan.activationDependencies[capturer.id] ?? []).includes(scout.id), "lockout reserve capturer should wait for counterattack scout reveal unless scout is assigned as escort");
}

