function testAiInfantryCommitsToPressuredGate(): void {
  const state = createAiFixture(14);
  const gate = state.gates?.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "fixture must include west gate");
  gate!.owner = "Player";
  gate!.occupation.Player = 1;
  const infantry = addAiFixtureUnit(state, "Enemy", "Infantry", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 8) });
  const backup = addAiFixtureUnit(state, "Enemy", "Infantry", { q: gate!.coord.q + 2, r: Math.max(0, gate!.coord.r - 7) });
  addAiFixtureUnit(state, "Player", "Infantry", { q: gate!.coord.q, r: gate!.coord.r + 1 });
  addAiFixtureUnit(state, "Player", "Tank", { q: gate!.coord.q + 1, r: gate!.coord.r + 2 });
  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const principal = [infantry, backup]
    .map((unit) => visibleState.units.find((candidate) => candidate.id === unit.id))
    .find((unit): unit is UnitInstance => Boolean(unit && plan.rolesByUnitId[unit.id] === "CaptureGate"));
  assertAiTest(Boolean(principal), `pressured gate should assign a principal infantry capturer, got ${plan.rolesByUnitId[infantry.id] ?? "none"} and ${plan.rolesByUnitId[backup.id] ?? "none"}`);
  const action = enumerateEnemyCompoundActions(visibleState, principal!, plan, {}, {})[0];
  const finalCoord = action.moveTo ?? principal!.coord;
  assertAiTest(action.kind !== "Hold", "pressured gate infantry should not linger on hold");
  assertAiTest(hexDistance(finalCoord, gate!.coord) < hexDistance(principal!.coord, gate!.coord), "pressured gate infantry should move closer to the gate");
}

function testAiReservationAndOverkill(): void {
  const state = createAiFixture(14);
  const first = addAiFixtureUnit(state, "Enemy", "Tank", { q: 12, r: 28 });
  const second = addAiFixtureUnit(state, "Enemy", "Tank", { q: 16, r: 28 });
  const target = addAiFixtureUnit(state, "Player", "Operator", { q: 14, r: 30 }, 1);
  const other = addAiFixtureUnit(state, "Player", "Infantry", { q: 16, r: 30 }, 8);
  const visibleState = updateFog(state);
  const visibleFirst = visibleState.units.find((unit) => unit.id === first.id);
  const visibleSecond = visibleState.units.find((unit) => unit.id === second.id);
  const visibleTarget = visibleState.units.find((unit) => unit.id === target.id);
  assertAiTest(Boolean(visibleFirst && visibleSecond && visibleTarget), "reservation fixture units must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  const reserved: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }> = {};
  const action = createEnemyCompoundAction(visibleState, visibleFirst!, plan, "Attack", {
    attackAt: visibleTarget!.coord,
    targetId: visibleTarget!.id,
    targetType: visibleTarget!.type,
    expectedOutcome: getExpectedAttackOutcome(visibleState, visibleFirst!, visibleTarget!)
  }, {}, reserved);
  reserveEnemyActionExpectedDamage(action, reserved);
  const secondAction = enumerateEnemyCompoundActions(visibleState, visibleSecond!, plan, {}, reserved)[0];
  assertAiTest(Boolean(secondAction), "reserved overkill fixture should provide a second action");
  assertAiTest(secondAction.targetId !== target.id || secondAction.targetId === other.id, "overkill reservation should prefer another target when lethal damage is reserved");
}

function testExpectedOutcome(expectedDamage: number, killProbability: number): ExpectedAttackOutcome {
  return {
    missProbability: 0,
    normalDamageProbability: 1,
    normalDamage: expectedDamage,
    criticalDamageProbability: 0,
    criticalDamage: expectedDamage,
    expectedDamage,
    killProbability
  };
}

function testAiUsefulDamageBoundsOverkillScoring(): void {
  const state = createAiFixture(16);
  const attacker = addAiFixtureUnit(state, "Enemy", "Tank", { q: 14, r: 24 });
  const nearDead = addAiFixtureUnit(state, "Player", "Operator", { q: 14, r: 25 }, 1);
  const healthy = addAiFixtureUnit(state, "Player", "Tank", { q: 15, r: 25 }, 24);
  const visibleState = updateFog(state);
  const visibleAttacker = visibleState.units.find((unit) => unit.id === attacker.id);
  const visibleNearDead = visibleState.units.find((unit) => unit.id === nearDead.id);
  const visibleHealthy = visibleState.units.find((unit) => unit.id === healthy.id);
  assertAiTest(Boolean(visibleAttacker && visibleNearDead && visibleHealthy), "useful-damage fixture units must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  const overkill = createEnemyCompoundAction(visibleState, visibleAttacker!, plan, "Attack", {
    attackAt: visibleNearDead!.coord,
    targetId: visibleNearDead!.id,
    targetType: visibleNearDead!.type,
    expectedOutcome: testExpectedOutcome(24, 0.42)
  }, {}, {});
  const usefulHit = createEnemyCompoundAction(visibleState, visibleAttacker!, plan, "Attack", {
    attackAt: visibleHealthy!.coord,
    targetId: visibleHealthy!.id,
    targetType: visibleHealthy!.type,
    expectedOutcome: testExpectedOutcome(10, 0.05)
  }, {}, {});

  assertAiTest(overkill.breakdown.expectedDamage < usefulHit.breakdown.expectedDamage, `overkill damage should be bounded, got overkill=${overkill.breakdown.expectedDamage.toFixed(1)} useful=${usefulHit.breakdown.expectedDamage.toFixed(1)}`);
}

