function testAiMaterialLeadAllowsCombatAdvanceIntoReplyPressure(): void {
  const state = createAiFixture(18);
  state.units = [];
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: 14, r: 20 });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: 12, r: 20 });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: 16, r: 20 });
  addAiFixtureUnit(state, "Enemy", "Artillery", { q: 13, r: 19 });
  addKnownAiFixtureUnit(state, "Player", "Infantry", { q: 14, r: 24 });
  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(visibleTank), "combat-advance fixture must retain the Tank");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleTank!.id] = "Escort";

  const candidate = getEnemyLegalMoveCoords(visibleState, visibleTank!)
    .filter((coord) => canMoveUnitTo(visibleState, visibleTank!, coord))
    .filter((coord) => !sameHex(coord, visibleTank!.coord))
    .map((coord) => ({
      coord,
      replyDamage: estimatePlayerLikelyReplyDamageAtPlanner(visibleState, visibleTank!, coord, plan)
    }))
    .filter((entry) => entry.replyDamage > 0)
    .filter((entry) => !isEnemyPlannerOneShotExposed(visibleState, visibleTank!, entry.coord, plan))
    .sort((first, second) => first.replyDamage - second.replyDamage || hexId(first.coord).localeCompare(hexId(second.coord)))[0];

  assertAiTest(Boolean(candidate), "fixture should expose a non-lethal reply-pressure advance");
  assertAiTest(getEnemyKnownMaterialAdvantageRatio(plan) >= 1.18, "fixture should put the enemy materially ahead");
  const action = createEnemyCompoundAction(visibleState, visibleTank!, plan, "Move", { moveTo: candidate!.coord }, {}, {});
  assertAiTest(
    isEnemyCompoundActionPlausiblyLegal(visibleState, visibleTank!, action, plan),
    `material-leading combat Tank should be allowed to advance into bounded reply damage ${candidate!.replyDamage.toFixed(1)}`
  );
}

function testAiInitiativeAdvancesGatePacketOnNeutralBoard(): void {
  const state = createAiFixture(6);
  state.units = [];
  const gate = state.gates.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "neutral packet fixture must include West Gate");
  gate!.owner = null;
  gate!.knownOwner = null;
  const capturer = addAiFixtureUnit(state, "Enemy", "Infantry", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 6) });
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: gate!.coord.q - 1, r: Math.max(0, gate!.coord.r - 7) });
  const ifv = addAiFixtureUnit(state, "Enemy", "IFV", { q: gate!.coord.q + 1, r: Math.max(0, gate!.coord.r - 7) });
  addKnownAiFixtureUnit(state, "Player", "Infantry", { q: gate!.coord.q + 3, r: gate!.coord.r + 8 });
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: gate!.coord.q - 3, r: gate!.coord.r + 8 });

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const visibleUnits = [capturer, tank, ifv]
    .map((unit) => visibleState.units.find((candidate) => candidate.id === unit.id))
    .filter((unit): unit is UnitInstance => Boolean(unit));
  const advancing = visibleUnits.filter((unit) => {
    const action = enumerateEnemyCompoundActions(visibleState, unit, plan, {}, {})[0];
    if (!action || action.kind === "Hold") {
      return false;
    }
    const finalCoord = getEnemyCompoundActionFinalCoord(unit, action);
    return hexDistance(finalCoord, gate!.coord) < hexDistance(unit.coord, gate!.coord);
  });

  assertAiTest(plan.strategicSnapshot.initiativePressure > 0, `neutral packet fixture should create initiative pressure, got ${plan.strategicSnapshot.initiativePressure.toFixed(1)}`);
  assertAiTest(advancing.length >= 2, `at least two packet units should advance toward the neutral gate, got ${advancing.length}`);
  assertAiTest(advancing.length < visibleUnits.length || advancing.length >= 2, "packet fixture should make active moves rather than all Hold/standoff");
}

function testAiEqualMaterialAllowsBoundedArmorTempoRisk(): void {
  const state = createAiFixture(18);
  state.units = [];
  const gate = state.gates.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "bounded armor risk fixture must include West Gate");
  for (const candidate of state.gates) {
    candidate.owner = "Player";
    candidate.knownOwner = "Player";
  }
  gate!.occupation.Player = 1;
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 6) });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: gate!.coord.q + 1, r: Math.max(0, gate!.coord.r - 5) });
  addKnownAiFixtureUnit(state, "Player", "IFV", { q: gate!.coord.q, r: gate!.coord.r + 4 });
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: gate!.coord.q + 3, r: gate!.coord.r + 4 });

  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(visibleTank), "bounded armor risk fixture must retain the Tank");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleTank!.id] = "Escort";
  const currentAttack = estimateEnemyBestPotentialAttackValue(visibleState, visibleTank!, plan, visibleTank!.coord);
  const candidate = getEnemyLegalMoveCoords(visibleState, visibleTank!)
    .filter((coord) => canMoveUnitTo(visibleState, visibleTank!, coord))
    .filter((coord) => !sameHex(coord, visibleTank!.coord))
    .map((coord) => {
      const action = createEnemyCompoundAction(visibleState, visibleTank!, plan, "Move", { moveTo: coord }, {}, {});
      const replyDamage = estimatePlayerLikelyReplyDamageAtPlanner(visibleState, visibleTank!, coord, plan, action);
      return {
        coord,
        action,
        replyDamage,
        replyRatio: replyDamage / Math.max(1, visibleTank!.health),
        objectiveProgress: hexDistance(visibleTank!.coord, gate!.coord) - hexDistance(coord, gate!.coord),
        attackGain: estimateEnemyBestPotentialAttackValue(visibleState, visibleTank!, plan, coord) - currentAttack
      };
    })
    .filter((entry) => entry.replyRatio >= 0.25 && entry.replyRatio <= 0.5)
    .filter((entry) => entry.objectiveProgress > 0 || entry.attackGain > 0)
    .sort((first, second) => second.objectiveProgress - first.objectiveProgress || second.attackGain - first.attackGain || first.replyDamage - second.replyDamage)[0];
  const chosen = enumerateEnemyCompoundActions(visibleState, visibleTank!, plan, {}, {})[0];
  const chosenFinal = chosen ? getEnemyCompoundActionFinalCoord(visibleTank!, chosen) : visibleTank!.coord;

  assertAiTest(plan.strategicSnapshot.initiativePressure >= 85, `fixture should create high initiative pressure, got ${plan.strategicSnapshot.initiativePressure.toFixed(1)}`);
  assertAiTest(Boolean(candidate), "fixture should expose a bounded 25-50% reply-risk armor advance");
  assertAiTest(isEnemyCompoundActionPlausiblyLegal(visibleState, visibleTank!, candidate!.action, plan), `bounded armor tempo advance should be legal, reply=${candidate!.replyDamage.toFixed(1)}`);
  assertAiTest(
    chosen && chosen.kind !== "Hold" && hexDistance(chosenFinal, gate!.coord) <= hexDistance(visibleTank!.coord, gate!.coord),
    `chosen armor action should be allowed to stage/advance under initiative, got ${chosen?.kind ?? "none"} to ${hexId(chosenFinal)}`
  );
}

function testAiNoOverDefenseWithoutImmediateBaseThreat(): void {
  const state = createAiFixture(18);
  state.units = [];
  const gate = state.gates.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "over-defense fixture must include West Gate");
  gate!.owner = "Player";
  gate!.knownOwner = "Player";
  gate!.occupation.Player = 1;
  addAiFixtureUnit(state, "Enemy", "Infantry", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 6) });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: gate!.coord.q - 1, r: Math.max(0, gate!.coord.r - 5) });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: gate!.coord.q + 1, r: Math.max(0, gate!.coord.r - 5) });
  addAiFixtureUnit(state, "Enemy", "Artillery", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 7) });
  addKnownAiFixtureUnit(state, "Player", "Tank", { q: gate!.coord.q, r: gate!.coord.r + 3 });
  addKnownAiFixtureUnit(state, "Player", "Artillery", { q: gate!.coord.q + 2, r: gate!.coord.r + 4 });

  const visibleState = updateFog(state);
  const plan = beginEnemyTurnPlan(visibleState);
  const defensiveRoles = Object.values(plan.rolesByUnitId).filter((role) => role === "BaseSentry" || role === "DefendBase").length;
  const offensiveRoles = Object.values(plan.rolesByUnitId).filter((role) =>
    role === "CaptureGate" ||
    role === "EscortCapture" ||
    role === "ShadowCapturer" ||
    role === "Escort" ||
    role === "Siege" ||
    role === "Scout" ||
    isEnemyGateLockoutCombatMission(role)
  ).length;
  const immediateBaseThreat = getEnemyBaseThreat(visibleState);

  assertAiTest(!isActiveEnemyBaseThreat(visibleState, immediateBaseThreat), "fixture should have pressure without an immediate base threat");
  assertAiTest(defensiveRoles <= 1, `without an immediate base threat, at most one unit should be defensive, got ${defensiveRoles}`);
  assertAiTest(offensiveRoles >= 2, `spare combat units should keep offensive/gate/escort roles, got ${offensiveRoles}`);
}

