function testAiSupportUnitsStageBehindCombatOnly(): void {
  const state = createAiFixture(18);
  state.units = [];
  const gate = state.gates.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "support staging fixture must include West Gate");
  gate!.owner = "Player";
  gate!.knownOwner = "Player";
  gate!.occupation.Player = 1;
  const artillery = addAiFixtureUnit(state, "Enemy", "Artillery", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 6) });
  const unsupportedArtillery = addAiFixtureUnit(state, "Enemy", "Artillery", { q: gate!.coord.q + 6, r: Math.max(0, gate!.coord.r - 6) });
  addAiFixtureUnit(state, "Enemy", "Tank", { q: gate!.coord.q, r: Math.max(0, gate!.coord.r - 3) });
  const playerTank = addKnownAiFixtureUnit(state, "Player", "Tank", { q: gate!.coord.q, r: gate!.coord.r });
  addKnownAiFixtureUnit(state, "Player", "IFV", { q: gate!.coord.q + 1, r: gate!.coord.r });

  const visibleState = updateFog(state);
  const visibleArtillery = visibleState.units.find((unit) => unit.id === artillery.id);
  const visibleUnsupportedArtillery = visibleState.units.find((unit) => unit.id === unsupportedArtillery.id);
  const visibleTarget = visibleState.units.find((unit) => unit.id === playerTank.id);
  assertAiTest(Boolean(visibleArtillery && visibleUnsupportedArtillery && visibleTarget), "support staging fixture must retain Artillery units and target");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleArtillery!.id] = "Siege";
  plan.rolesByUnitId[visibleUnsupportedArtillery!.id] = "Siege";
  const compoundMoveThenAttack = createEnemyCompoundAction(visibleState, visibleArtillery!, plan, "MoveThenAttack", {
    moveTo: { q: visibleArtillery!.coord.q, r: visibleArtillery!.coord.r + 1 },
    attackAt: visibleTarget!.coord,
    targetId: visibleTarget!.id,
    targetType: visibleTarget!.type,
    expectedOutcome: getExpectedAttackOutcome(visibleState, visibleArtillery!, visibleTarget!)
  }, {}, {});
  const compoundAttackThenMove = createEnemyCompoundAction(visibleState, visibleArtillery!, plan, "AttackThenMove", {
    moveTo: { q: visibleArtillery!.coord.q, r: visibleArtillery!.coord.r + 1 },
    attackAt: visibleTarget!.coord,
    targetId: visibleTarget!.id,
    targetType: visibleTarget!.type,
    expectedOutcome: getExpectedAttackOutcome(visibleState, visibleArtillery!, visibleTarget!)
  }, {}, {});
  const coveredMoves = getEnemyPlannerCandidateMoveCoords(visibleState, visibleArtillery!, plan, {});
  const supportedMove = coveredMoves.find((coord) => scoreEnemyAggressiveStageCoveredSupport(visibleState, visibleArtillery!, coord) > 0);
  const unsupported = getEnemyLegalMoveCoords(visibleState, visibleUnsupportedArtillery!)
    .filter((coord) => canMoveUnitTo(visibleState, visibleUnsupportedArtillery!, coord))
    .filter((coord) => !sameHex(coord, visibleUnsupportedArtillery!.coord))
    .map((coord) => {
      const action = createEnemyCompoundAction(visibleState, visibleUnsupportedArtillery!, plan, "Move", { moveTo: coord }, {}, {});
      return {
        coord,
        action,
        replyDamage: estimatePlayerLikelyReplyDamageAtPlanner(visibleState, visibleUnsupportedArtillery!, coord, plan, action),
        cover: scoreEnemyAggressiveStageCoveredSupport(visibleState, visibleUnsupportedArtillery!, coord)
      };
    })
    .filter((entry) => entry.replyDamage > 0 && entry.cover <= 0)
    .sort((first, second) => second.replyDamage - first.replyDamage || hexId(first.coord).localeCompare(hexId(second.coord)))[0];

  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, visibleArtillery!, compoundMoveThenAttack, plan), "Artillery MoveThenAttack must remain planner-illegal");
  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, visibleArtillery!, compoundAttackThenMove, plan), "Artillery AttackThenMove must remain planner-illegal");
  assertAiTest(Boolean(supportedMove), "covered Artillery should consider ordinary Move staging behind combat");
  assertAiTest(Boolean(unsupported), "fixture should expose unsupported dangerous Artillery staging");
  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(visibleState, visibleUnsupportedArtillery!, unsupported!.action, plan), `unsupported dangerous support staging should be rejected, reply=${unsupported!.replyDamage.toFixed(1)}`);
}

function testAiTempoRiskContestsPlayerGateUnderLocalSupport(): void {
  const state = createAiFixture(18);
  state.units = [];
  const westGate = state.gates?.find((gate) => gate.id === "West");
  const eastGate = state.gates?.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  for (const gate of [westGate!, eastGate!]) {
    gate.owner = "Player";
    gate.knownOwner = "Player";
  }
  westGate!.occupation.Player = 1;

  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: westGate!.coord.q, r: westGate!.coord.r - 6 });
  addAiFixtureUnit(state, "Enemy", "IFV", { q: westGate!.coord.q + 1, r: westGate!.coord.r - 5 });
  addAiFixtureUnit(state, "Enemy", "Artillery", { q: westGate!.coord.q + 2, r: westGate!.coord.r - 6 });
  addKnownAiFixtureUnit(state, "Player", "IFV", { q: westGate!.coord.q, r: westGate!.coord.r + 4 });

  const visibleState = updateFog(state);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  const visibleGate = visibleState.gates.find((gate) => gate.id === "West");
  assertAiTest(Boolean(visibleTank && visibleGate), "tempo-risk fixture must retain the Tank and West Gate");
  const plan = beginEnemyTurnPlan(visibleState);
  plan.rolesByUnitId[visibleTank!.id] = "Escort";

  const actions = enumerateEnemyCompoundActions(visibleState, visibleTank!, plan, {}, {});
  const action = actions[0];
  const finalCoord = action ? getEnemyCompoundActionFinalCoord(visibleTank!, action) : visibleTank!.coord;
  const replyDamage = action ? estimatePlayerLikelyReplyDamageAtPlanner(visibleState, visibleTank!, finalCoord, plan, action) : 0;
  const replyRatio = replyDamage / Math.max(1, visibleTank!.health);

  assertAiTest(Boolean(action), "tempo-risk fixture should produce an action");
  assertAiTest(hexDistance(finalCoord, visibleGate!.coord) < hexDistance(visibleTank!.coord, visibleGate!.coord), `healthy combat unit should move toward the contested gate, got ${action.kind} to ${hexId(finalCoord)}`);
  assertAiTest(replyRatio >= 0.25 && replyRatio <= 0.5, `fixture should require bounded 25-50% reply risk, got ${(replyRatio * 100).toFixed(1)}%`);
  assertAiTest(action.breakdown.tempoRisk > 0, `bounded-risk tempo move should score explicit tempoRisk, got ${action.breakdown.tempoRisk.toFixed(1)}`);
  assertAiTest(getEnemyRiskBudgetDiscount(visibleState, visibleTank!, action, finalCoord, plan) === 0.58, "bounded-risk tempo move should discount duplicate danger scoring");
}

