function testAiReservationFocusFiresPriorityTarget(): void {
  const state = createAiFixture(16);
  const gate = state.gates.find((candidate) => candidate.id === "West");
  assertAiTest(Boolean(gate), "fixture must include west gate");
  gate!.owner = "Player";
  gate!.knownOwner = "Player";
  gate!.occupation.Player = GATE_CAPTURE_DAYS;
  gate!.occupation.Enemy = 0;
  const first = addAiFixtureUnit(state, "Enemy", "Artillery", { q: gate!.coord.q - 2, r: gate!.coord.r - 3 });
  const second = addAiFixtureUnit(state, "Enemy", "Artillery", { q: gate!.coord.q + 2, r: gate!.coord.r - 3 });
  const tank = addAiFixtureUnit(state, "Player", "Tank", gate!.coord, 30);
  const infantry = addAiFixtureUnit(state, "Player", "Infantry", { q: gate!.coord.q + 1, r: gate!.coord.r }, 12);
  const visibleState = updateFog(state);
  const visibleFirst = visibleState.units.find((unit) => unit.id === first.id);
  const visibleSecond = visibleState.units.find((unit) => unit.id === second.id);
  const visibleTank = visibleState.units.find((unit) => unit.id === tank.id);
  const visibleInfantry = visibleState.units.find((unit) => unit.id === infantry.id);
  assertAiTest(Boolean(visibleFirst && visibleSecond && visibleTank && visibleInfantry), "focus-fire fixture units must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  const reserved: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }> = {};
  const firstAction = createEnemyCompoundAction(visibleState, visibleFirst!, plan, "Attack", {
    attackAt: visibleTank!.coord,
    targetId: visibleTank!.id,
    targetType: visibleTank!.type,
    expectedOutcome: getExpectedAttackOutcome(visibleState, visibleFirst!, visibleTank!)
  }, {}, reserved);
  reserveEnemyActionExpectedDamage(firstAction, reserved);
  assertAiTest(!isEnemyReservedDamageLikelyClearingTarget(visibleTank!, reserved[visibleTank!.id]), "first reservation should leave the gate tank needing follow-up");

  const secondAction = enumerateEnemyCompoundActions(visibleState, visibleSecond!, plan, {}, reserved)[0];
  assertAiTest(
    secondAction?.targetId === visibleTank!.id,
    `second attacker should focus-fire the reserved gate-control Tank, got ${secondAction?.targetId === visibleInfantry!.id ? "Infantry" : secondAction?.targetId ?? "none"}`
  );
}

function testAiReservationCompletesObjectiveBlocker(): void {
  const state = createAiFixture(18);
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
    gate.occupation.Enemy = GATE_CAPTURE_DAYS;
  });
  const blocker = addAiFixtureUnit(state, "Player", "Tank", state.bases.Player, 14);
  const unrelated = addAiFixtureUnit(state, "Player", "Operator", { q: state.bases.Player.q + 2, r: state.bases.Player.r - 1 }, 1);
  const first = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Player.q - 1, r: state.bases.Player.r - 3 });
  const second = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Player.q + 1, r: state.bases.Player.r - 3 });
  addAiFixtureUnit(state, "Enemy", "Ghost", { q: state.bases.Player.q, r: state.bases.Player.r - 2 });
  const visibleState = updateFog(state);
  const visibleBlocker = visibleState.units.find((unit) => unit.id === blocker.id);
  const visibleUnrelated = visibleState.units.find((unit) => unit.id === unrelated.id);
  const visibleFirst = visibleState.units.find((unit) => unit.id === first.id && unit.owner === "Enemy");
  const visibleSecond = visibleState.units.find((unit) => unit.id === second.id && unit.owner === "Enemy");
  assertAiTest(Boolean(visibleBlocker && visibleUnrelated && visibleFirst && visibleSecond), "fixture units must remain visible");
  const plan = beginEnemyTurnPlan(visibleState);
  const reserved: Record<string, { expectedDamage: number; killProbability: number; unitIds: string[] }> = {};
  const firstAction = createEnemyCompoundAction(visibleState, visibleFirst!, plan, "Attack", {
    attackAt: visibleBlocker!.coord,
    targetId: visibleBlocker!.id,
    targetType: visibleBlocker!.type,
    expectedOutcome: getExpectedAttackOutcome(visibleState, visibleFirst!, visibleBlocker!)
  }, {}, reserved);
  reserveEnemyActionExpectedDamage(firstAction, reserved);

  assertAiTest(isEnemyObjectiveBlockerTarget(visibleState, visibleBlocker!, plan), "base occupant should be recognised as an objective blocker");
  assertAiTest(!isEnemyReservedDamageLikelyClearingTarget(visibleBlocker!, reserved[visibleBlocker!.id]), "first reservation should not already clear the blocker");
  const secondActions = enumerateEnemyCompoundActions(visibleState, visibleSecond!, plan, {}, reserved);
  const secondAction = secondActions[0];

  assertAiTest(secondAction?.targetId === visibleBlocker!.id, `second clearer should keep damage on base blocker before unrelated target, got ${secondAction?.targetId ?? "none"}`);
}

