function testAiLocalFallbackPreservesCaptureGate(): void {
  const state = createAiFixture(10);
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  westGate!.owner = null;
  westGate!.knownOwner = null;
  eastGate!.owner = "Player";
  eastGate!.knownOwner = "Player";
  const capturer = addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 4) });
  addAiFixtureUnit(state, "Player", "Infantry", { q: eastGate!.coord.q, r: eastGate!.coord.r + 1 });
  const plan = beginEnemyTurnPlan(updateFog(state));
  plan.rolesByUnitId[capturer.id] = "CaptureGate";
  plan.campaignPlan.assignedGateByUnitId[capturer.id] = "West";
  const beforeDistance = hexDistance(capturer.coord, westGate!.coord);
  const invalid = createEnemyCompoundAction(state, capturer, plan, "Move", { moveTo: { q: 0, r: 0 } }, {}, {});

  assertAiTest(!executeEnemyCompoundAction(state, invalid, plan), "invalid CaptureGate planned move should fail direct execution");
  executeEnemyLocalFallback(state, capturer.id, plan, { enemyMovementTrails: [] });
  const after = state.units.find((unit) => unit.id === capturer.id);

  assertAiTest(Boolean(after), "fallback capturer should survive");
  assertAiTest(hexDistance(after!.coord, westGate!.coord) < beforeDistance, `fallback should progress toward assigned West Gate, distance ${beforeDistance} -> ${hexDistance(after!.coord, westGate!.coord)}`);
  assertAiTest(hexDistance(after!.coord, westGate!.coord) < hexDistance(after!.coord, eastGate!.coord), "fallback should preserve the assigned Gate instead of drifting to another objective");
}

