function testAiStructuralFilterRejectsAntiAirDrift(): void {
  const state = updateFog(createAiFixture(18));
  const helicopter = addAiFixtureUnit(state, "Enemy", "Attack Heli", { q: 14, r: 4 });
  const antiAir = addAiFixtureUnit(state, "Player", "Anti-Air", { q: 14, r: 9 });
  rememberAiFixtureUnit(state, antiAir);
  const plan = beginEnemyTurnPlan(updateFog(state));
  const unsafeMove = { q: 14, r: 6 };
  const unsafeAction = createEnemyCompoundAction(state, helicopter, plan, "Move", { moveTo: unsafeMove }, {}, {});

  assertAiTest(isAiTestCoordInEffectiveAttackRange(state, antiAir, unsafeMove), "fixture unsafe move must enter Anti-Air range");
  assertAiTest(!isEnemyCompoundActionPlausiblyLegal(state, helicopter, unsafeAction, plan), "Anti-Air-covered air drift must be rejected before scoring");
}

function testAiLiveRevalidationPreservesCaptureRole(): void {
  const state = updateFog(createAiFixture(10));
  const westGate = state.gates.find((gate) => gate.id === "West");
  const eastGate = state.gates.find((gate) => gate.id === "East");
  assertAiTest(Boolean(westGate && eastGate), "fixture must include both gates");
  westGate!.owner = null;
  westGate!.knownOwner = null;
  eastGate!.owner = "Player";
  eastGate!.knownOwner = "Player";
  const capturer = addAiFixtureUnit(state, "Enemy", "Infantry", { q: westGate!.coord.q, r: Math.max(0, westGate!.coord.r - 4) });
  const plan = beginEnemyTurnPlan(updateFog(state));
  plan.rolesByUnitId[capturer.id] = "CaptureGate";
  plan.campaignPlan.assignedGateByUnitId[capturer.id] = "West";
  const beforeDistance = hexDistance(capturer.coord, westGate!.coord);
  const driftMove = getEnemyLegalMoveCoords(state, capturer)
    .filter((coord) => canMoveUnitTo(state, capturer, coord))
    .filter((coord) => hexDistance(coord, westGate!.coord) >= beforeDistance)
    .sort((first, second) => hexDistance(second, westGate!.coord) - hexDistance(first, westGate!.coord) || hexId(first).localeCompare(hexId(second)))[0];
  assertAiTest(Boolean(driftMove), "fixture must provide a legal role-wrong drift move");
  plan.plannedActions = [createEnemyCompoundAction(state, capturer, plan, "Move", { moveTo: driftMove }, {}, {})];

  executeEnemyTacticalPlan(state, plan, { enemyMovementTrails: [] });
  const after = state.units.find((unit) => unit.id === capturer.id);

  assertAiTest(Boolean(after), "live revalidation fallback capturer should survive");
  assertAiTest(!sameHex(after!.coord, driftMove), "live revalidation should reject a legal move that drifts away from assigned capture role");
  assertAiTest(hexDistance(after!.coord, westGate!.coord) < beforeDistance, `live revalidation fallback should preserve Gate tempo, distance ${beforeDistance} -> ${hexDistance(after!.coord, westGate!.coord)}`);
}

function testAiLiveRevalidationFallsBackFromAntiAir(): void {
  const state = updateFog(createAiFixture(18));
  const helicopter = addAiFixtureUnit(state, "Enemy", "Attack Heli", { q: 14, r: 4 });
  const plan = beginEnemyTurnPlan(updateFog(state));
  const unsafeCoord = { q: 14, r: 6 };
  plan.plannedActions = [createEnemyCompoundAction(state, helicopter, plan, "Move", { moveTo: unsafeCoord }, {}, {})];
  const antiAir = addAiFixtureUnit(state, "Player", "Anti-Air", { q: 14, r: 9 });
  rememberAiFixtureUnit(state, antiAir);
  invalidateEnemyEvaluationCache();

  assertAiTest(isAiTestCoordInEffectiveAttackRange(state, antiAir, unsafeCoord), "fixture unsafe move must enter newly known Anti-Air range");
  executeEnemyTacticalPlan(state, plan, { enemyMovementTrails: [] });
  const after = state.units.find((unit) => unit.id === helicopter.id);

  assertAiTest(Boolean(after), "live revalidation air fallback should preserve the air unit");
  assertAiTest(!sameHex(after!.coord, unsafeCoord), "live revalidation should reject a planned move into newly known Anti-Air coverage");
  assertAiTest(!isAiTestCoordInEffectiveAttackRange(state, antiAir, after!.coord), `live revalidation fallback should end outside Anti-Air range, got ${hexId(after!.coord)}`);
}

function testAiActiveCacheInvalidation(): void {
  const state = updateFog(createAiFixture(5));
  const plan = beginEnemyTurnPlan(state);
  const before = getEnemyStrategicAssessment(state).player.totalCount;
  withEnemyTurnPlan(plan, () => {
    const player = addAiFixtureUnit(state, "Player", "Tank", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 4 });
    rememberAiFixtureUnit(state, player);
    invalidateEnemyEvaluationCache();
    const after = getEnemyStrategicAssessment(state).player.totalCount;
    assertAiTest(after > before, "active turn invalidation must clear stale strategic assessment");
  });
}

function testAiActiveCacheInvalidatesVisibilityAfterMove(): void {
  const state = updateFog(createAiFixture(18));
  state.gates.forEach((gate) => {
    gate.owner = "Enemy";
    gate.knownOwner = "Enemy";
    gate.occupation.Enemy = GATE_CAPTURE_DAYS;
  });
  const entryRow = getPlayerBaseAssaultAreaMinRow(state);
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Player.q, r: entryRow - 9 });
  const revealCoord = { q: state.bases.Player.q, r: entryRow };
  const plan = beginEnemyTurnPlan(updateFog(state));

  withEnemyTurnPlan(plan, () => {
    const before = getEnemyVisibleHexIds(state);
    assertAiTest(!before.has(hexId(revealCoord)), "fixture reveal coord should start outside cached enemy sight");
    tank.coord = { q: state.bases.Player.q, r: entryRow - 5 };
    synchronizeEnemyFogInPlace(state);
    invalidateEnemyEvaluationCache();
    const after = getEnemyVisibleHexIds(state);
    assertAiTest(after.has(hexId(revealCoord)), "active turn invalidation must refresh enemy sight after movement");
  });
}

function testAiEmergencyFallbackTurn(): void {
  const state = updateFog(createAiFixture(5));
  const tank = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 2 });
  addAiFixtureUnit(state, "Player", "Infantry", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 8 });
  const before = { ...tank.coord };
  runEnemyEmergencyFallbackTurn(state, { enemyMovementTrails: [] });
  const after = state.units.find((unit) => unit.id === tank.id);
  assertAiTest(Boolean(after), "fallback actor must remain alive");
  assertAiTest(!sameHex(before, after!.coord) || after!.hasAttackedThisDay, "emergency fallback must move or attack an available enemy unit");
}

function testAiEmergencyFallbackDeniesBaseLoss(): void {
  const state = createAiFixture(18);
  resetAiFixtureEnemyInventory(state);
  state.baseOccupation.Enemy = BASE_CAPTURE_DAYS - 1;
  const defender = addAiFixtureUnit(state, "Enemy", "Tank", { q: state.bases.Enemy.q, r: state.bases.Enemy.r + 2 });
  const capturer = addAiFixtureUnit(state, "Player", "Infantry", state.bases.Enemy);
  const decoy = addAiFixtureUnit(state, "Player", "Tank", { q: state.bases.Enemy.q + 1, r: state.bases.Enemy.r + 2 });
  const beforeCapturerHealth = capturer.health;
  const beforeDecoyHealth = decoy.health;

  const visibleState = updateFog(state);
  runEnemyEmergencyFallbackTurn(visibleState, { enemyMovementTrails: [] });

  const afterDefender = visibleState.units.find((unit) => unit.id === defender.id);
  const afterCapturer = visibleState.units.find((unit) => unit.id === capturer.id);
  const afterDecoy = visibleState.units.find((unit) => unit.id === decoy.id);
  assertAiTest(afterDefender?.hasAttackedThisDay, "emergency fallback should spend the defender attack on base-loss denial");
  assertAiTest(!afterCapturer || afterCapturer.health < beforeCapturerHealth, "emergency fallback should damage or remove the base capturer");
  assertAiTest(!afterDecoy || afterDecoy.health === beforeDecoyHealth, "base-loss denial should outrank a generic material attack");
}

