function testAiSmokePerformance(): void {
  for (let index = 0; index < 3; index += 1) {
    const state = createAiFixture(8 + index);
    addAiFixtureUnit(state, "Enemy", "Tank", { q: 13 + index, r: 2 + index });
    addAiFixtureUnit(state, "Enemy", "IFV", { q: 15, r: 2 + index });
    addAiFixtureUnit(state, "Player", "Infantry", { q: 14, r: 12 + index });
    const plan = beginEnemyTurnPlan(updateFog(state));
    finalizeEnemyTacticalPlan(cloneState(state), plan);
    assertAiTest(plan.searchStats.nodes <= ENEMY_PLANNER_NODE_CAP, "search node cap must be respected");
  }
}

function installAssuranceAiBrowserHooks(): void {
  if (typeof window === "undefined") {
    return;
  }
  const target = window as Window & {
    __assuranceAiTests?: { run: () => AssuranceAiTestResult[] };
    __assuranceAiDebug?: {
      inspectProfile: () => EnemyPlayerStyleProfile;
      resetProfile: () => EnemyPlayerStyleProfile;
      constants: Record<string, number | boolean>;
    };
  };
  target.__assuranceAiTests = {
    run: runAssuranceAiTests
  };
  target.__assuranceAiDebug = {
    inspectProfile: loadEnemyHistoricalPlayerProfile,
    resetProfile: resetEnemyHistoricalPlayerProfile,
    constants: {
      ENEMY_PLANNER_BEAM_WIDTH,
      ENEMY_PLANNER_ACTION_CAP,
      ENEMY_PLANNER_NODE_CAP,
      ENEMY_PLANNER_RELEVANT_UNIT_CAP,
      ENEMY_ARMY_SPEND_DOWN_SCORE_THRESHOLD
    }
  };
  try {
    if (new URLSearchParams(window.location.search).get(ENEMY_PLANNER_TEST_PARAM) === "1") {
      queueMicrotask(() => runAssuranceAiTests());
    }
  } catch {
    // Test auto-run is optional and should never affect ordinary play.
  }
}

installAssuranceAiBrowserHooks();
